def protocolo_duracao(seq):
    """Duração total (s) de uma sequência, já contando as repetições."""
    if not seq:
        return 0.0
    uma = sum(float(f.get("dur", 0) or 0) for f in seq.get("fases", []))
    return uma * max(1, int(seq.get("repeticoes", 1) or 1))


def protocolo_expandir(seq):
    """Desdobra a sequência em fases absolutas: [(t_inicio, t_fim, rótulo, tipo)].

    É o que o executor percorre em tempo real e o que a linha do tempo desenha.
    Quando há mais de uma repetição, o rótulo ganha sufixo "#n" para que os
    marcadores gravados sejam distinguíveis na hora de analisar.
    """
    fases = seq.get("fases", []) if seq else []
    reps = max(1, int((seq or {}).get("repeticoes", 1) or 1))
    fora, t = [], 0.0
    for r in range(reps):
        for f in fases:
            d = float(f.get("dur", 0) or 0)
            if d <= 0:
                continue
            rot = f.get("label", "fase")
            if reps > 1:
                rot = f"{rot} #{r + 1}"
            fora.append((t, t + d, rot, f.get("tipo", "livre")))
            t += d
    return fora


def rotulo_fase_tela(rot):
    """Rótulo de fase como aparece na tela, no idioma ativo.

    O marcador gravado continua com o rótulo em português ("Contração máxima
    #2"); só a exibição passa por tr(). O sufixo " #n" da repetição fica de
    fora da chave, senão cada repetição precisaria de uma tradução própria.
    Rótulo criado pelo usuário não está no dicionário e volta como está.
    """
    base, sep, n = str(rot).rpartition(" #")
    if sep and n.isdigit():
        return "%s #%s" % (tr(base), n)
    return tr(str(rot))


def _fmt_dur(seg):
    """Duração legível: 45 s vira '45 s'; 125 s vira '2 min 05 s'."""
    seg = max(0.0, float(seg))
    if seg < 60:
        return f"{seg:g} s"
    m, s = divmod(int(round(seg)), 60)
    return f"{m} min {s:02d} s" if s else f"{m} min"


def _safe_filename(nome):
    """Transforma um nome livre em algo gravável no Windows."""
    limpo = re.sub(r'[<>:"/\\|?*]', "-", str(nome)).strip(" .")
    return limpo[:120] or "protocolo"


