# Mantida para compatibilidade com codigo legado (recriada apos cada troca de tema)
STYLESHEET = build_stylesheet(COLORS)


def escreve_csv_planilha(caminho, cabecalho, linhas):
    """Grava uma TABELA DE RELATÓRIO no formato que a planilha do usuário abre.

    O `data.csv` da sessão continua no padrão internacional (vírgula separando
    campos, ponto decimal) porque é o registro científico, lido por pandas,
    MNE e MATLAB — mexer nele quebraria script de terceiro.

    Já os relatórios são feitos para abrir no Excel/Calc, e aí o padrão
    internacional atrapalha: no Excel em português, alemão, francês ou
    espanhol o separador de lista é ";" e o decimal é ",". Abrindo o arquivo
    antigo, "0.004" virava texto — ou, pior, era lido como 4 (ponto
    interpretado como separador de milhar).

    Escreve com BOM (o Excel precisa dele para reconhecer UTF-8) e converte o
    ponto decimal só quando a máquina usa vírgula.
    """
    import csv as _csv
    import locale as _locale
    try:
        virgula = _locale.localeconv().get("decimal_point", ".") == ","
    except Exception:
        virgula = False
    sep = ";" if virgula else ","

    def _num(v):
        """Números viram texto no decimal da máquina; o resto passa direto."""
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return v
        t = f"{v:.6g}"
        return t.replace(".", ",") if virgula else t

    with open(caminho, "w", newline="", encoding="utf-8-sig") as f:
        w = _csv.writer(f, delimiter=sep)
        if cabecalho:
            w.writerow(list(cabecalho))
        for linha in linhas:
            w.writerow([_num(v) for v in linha])
    return caminho


def _apply_theme_colors(theme_name):
    """Atualiza COLORS (in-place) para o tema escolhido. Retorna o dict."""
    palette = THEMES.get(theme_name, THEMES["Lime (verde-limao)"])
    # mutacao in-place para que referencias existentes acompanhem
    for k, v in palette.items():
        COLORS[k] = v
    # Fallback: temas antigos sem table_bg/table_alt — derivam de surface/surface_alt
    if "table_bg"  not in palette: COLORS["table_bg"]  = palette.get("surface", "#1a1a1a")
    if "table_alt" not in palette: COLORS["table_alt"] = palette.get("surface_alt", "#252525")
    # As cores dos TRAÇOS acompanham o tema. A paleta original era neon, feita
    # para fundo preto: no tema claro (hoje o padrão) alguns canais ficavam com
    # contraste perto de 1,2:1 e sumiam do gráfico.
    aplicar_paleta_canais(COLORS.get("surface", "#ffffff"))
    return COLORS


# ============================================================
# FilterChain — notch + bandpass por canal (com num canais variável)
# ============================================================
class FilterChain:
    # Esquemas de re-referenciação suportados
    """Cadeia de processamento amostra a amostra: re-referenciação, notch e passa-
    faixa aplicados aos canais em tempo real.

    A janela principal cria uma instância única (self.filters) com
    MAX_CHANNELS, consumida em _on_sample a cada amostra que chega da serial. É
    stateful — guarda o estado zi de cada filtro por canal — então trocar de
    sessão sem reset_state() arrasta o transiente da anterior. As constantes
    REREF_* no topo são os únicos modos que set_reref aceita.
    """
    REREF_NONE       = "none"        # Sem re-referenciação
    REREF_CAR        = "car"         # Common Average Reference (média de todos os canais)
    REREF_MASTOID    = "mastoid"     # Média de canais de referência (M1+M2)/2
    REREF_LAPLACIAN  = "laplacian"   # Surface Laplacian (canal - média vizinhos)
    REREF_BIPOLAR    = "bipolar"     # Pares bipolares (ch i+1 - ch i)
    REREF_REST       = "rest"        # Aproximação REST (subtrai média de canais distantes)

    def __init__(self, sample_rate=SAMPLE_RATE, num_channels=MAX_CHANNELS):
        """Cria a cadeia com tudo desligado (sem notch, sem passa-faixa, sem re-
        referenciação) e já monta os coeficientes chamando rebuild().

        num_channels dimensiona as matrizes de estado zi e é passado como
        MAX_CHANNELS mesmo quando bem menos canais estão ativos, para não
        precisar realocar quando o usuário muda a expansão.
        """
        self.sample_rate = sample_rate
        self.num_channels = num_channels
        self.notch_enabled    = False
        self.notch_freq       = 60.0
        self.bandpass_enabled = False
        self.bp_low           = 1.0
        self.bp_high          = 50.0
        # ---- Re-referenciação ----
        self.reref_mode = self.REREF_NONE
        # Canais de referência (índices) para esquemas que precisam (Mastoid)
        self.reref_channels = []
        # Tipo de sinal por canal ("EEG"/"EMG"/"ECG"/"EoG"/"off"). Sem esta lista a
        # média comum somava TODOS os canais: em montagem multimodal o QRS do canal
        # de ECG voltava para cada canal de EEG com ganho -1/N (medido: -0,25 com 4
        # canais, -0,065 com 16), ou seja ~100 uV de artefato sobre um alfa de 10 uV.
        self.channel_signal_types = None   # None = trata tudo como EEG (chamada legada)
        # Vizinhos por canal (para Laplacian) — pré-computado em set_reref_mode
        self._laplacian_neighbors = None
        self._sos_notch = None
        self._zi_notch  = None
        self._sos_bp    = None
        self._zi_bp     = None
        self.rebuild()

    def set_reref(self, mode, ref_channels=None, signal_types=None):
        """Configura modo de re-referenciação. ref_channels: índices 0-based.

        signal_types: lista paralela aos canais. Passe-a sempre que a montagem for
        multimodal — é ela que impede a média comum de somar ECG/EMG/EoG no EEG.
        """
        if mode in (self.REREF_NONE, self.REREF_CAR, self.REREF_MASTOID,
                    self.REREF_LAPLACIAN, self.REREF_BIPOLAR, self.REREF_REST):
            self.reref_mode = mode
        if ref_channels is not None:
            self.reref_channels = list(ref_channels)
        if signal_types is not None:
            self.channel_signal_types = list(signal_types)
        # Pre-compute neighbors for Laplacian (uses ELECTRODE_POSITIONS distances)
        if self.reref_mode == self.REREF_LAPLACIAN:
            self._compute_laplacian_neighbors()

    def _compute_laplacian_neighbors(self):
        """Para cada canal, identifica os 3-4 vizinhos mais próximos via posição 10-20."""
        try:
            positions = [(p[1], p[2]) for p in ELECTRODE_POSITIONS]
        except Exception:
            self._laplacian_neighbors = None; return
        n = min(self.num_channels, len(positions))
        neighbors = []
        for i in range(n):
            d = []
            for j in range(n):
                if j == i: continue
                dist = ((positions[i][0] - positions[j][0])**2 +
                        (positions[i][1] - positions[j][1])**2) ** 0.5
                d.append((dist, j))
            d.sort()
            # Pega 4 vizinhos mais próximos (Laplaciano local)
            neighbors.append([j for _, j in d[:4]])
        self._laplacian_neighbors = neighbors

    def _car_channels(self, n):
        """Índices elegíveis a entrar/receber a referência comum: só os marcados
        como EEG. Sem lista de tipos (chamada legada) devolve todos. Se a marcação
        zerar os EEG também devolve todos: média de conjunto vazio viraria NaN e
        apagaria a sessão inteira em silêncio.
        """
        types = self.channel_signal_types
        if not types:
            return list(range(n))
        eeg = [c for c in range(min(n, len(types))) if types[c] == "EEG"]
        return eeg if eeg else list(range(n))

    def apply_reref(self, sample):
        """Aplica re-referenciação a um vetor de amostras (in-place safe)."""
        n = len(sample)
        if n < 2 or self.reref_mode == self.REREF_NONE:
            return sample
        out = sample.copy()
        car = self._car_channels(n)
        car_set = set(car)          # set: o teste de pertinencia roda por amostra
        if self.reref_mode == self.REREF_CAR:
            # Média só entre EEG e subtraída só do EEG. Antes ECG/EMG entravam na
            # média (injetando o QRS em todo canal) e ainda levavam a subtração —
            # o que não faz sentido: canal de ECG é bipolar, não tem ref. comum.
            ref = float(np.mean(out[car]))
            out[car] -= ref
        elif self.reref_mode == self.REREF_MASTOID:
            chans = [c for c in self.reref_channels if 0 <= c < n]
            if chans:
                ref = float(np.mean(out[chans]))
                out[car] -= ref
        elif self.reref_mode == self.REREF_LAPLACIAN and self._laplacian_neighbors:
            tmp = out.copy()
            for i in range(min(n, len(self._laplacian_neighbors))):
                if i not in car_set: continue
                # vizinho tem de ser EEG: a vizinhança vem de ELECTRODE_POSITIONS,
                # que dá uma posição 10-20 a QUALQUER índice de canal — em montagem
                # multimodal isso elegia o canal de ECG/EMG como "vizinho próximo".
                nb = [j for j in self._laplacian_neighbors[i] if j < n and j in car_set]
                if nb:
                    out[i] = tmp[i] - float(np.mean(tmp[nb]))
        elif self.reref_mode == self.REREF_BIPOLAR:
            # ch i' = ch i - ch i+1 (último mantido)
            tmp = out.copy()
            for i in range(n - 1):
                out[i] = tmp[i] - tmp[i + 1]
        elif self.reref_mode == self.REREF_REST:
            # Aproximação simplificada: subtrai média dos canais marcados como
            # 'distantes' (= todos exceto os 4 vizinhos)
            if self._laplacian_neighbors:
                tmp = out.copy()
                for i in range(min(n, len(self._laplacian_neighbors))):
                    if i not in car_set: continue
                    # 'far' restrito a EEG: a média dos canais distantes incluía o
                    # ECG e vazava QRS exatamente como a CAR, só que canal a canal.
                    far = [j for j in car
                           if j != i and j not in self._laplacian_neighbors[i]]
                    if far:
                        out[i] = tmp[i] - float(np.mean(tmp[far]))
            else:
                ref = float(np.mean(out[car]))
                out[car] -= ref
        return out

    def rebuild(self):
        """Recalcula os coeficientes SOS e o estado inicial dos filtros; é chamada
        sempre que o usuário mexe nos controles de notch ou passa-faixa.

        Configuração inválida (frequência acima de Nyquist, ou bp_low >=
        bp_high) simplesmente desliga aquele filtro em vez de gerar erro. Notch
        é iirnotch com Q=30 convertido para SOS; o passa-faixa é Butterworth de
        4ª ordem. Efeito colateral importante: o estado zi de todos os canais é
        recriado do zero, ou seja, mexer no filtro durante uma gravação
        introduz um transiente.
        """
        nyq = self.sample_rate / 2.0
        if self.notch_enabled and 0 < self.notch_freq < nyq:
            b, a = scipy_signal.iirnotch(self.notch_freq / nyq, Q=30.0)
            self._sos_notch = scipy_signal.tf2sos(b, a)
            zi = scipy_signal.sosfilt_zi(self._sos_notch)
            # zi com os canais COMO EIXO — (n_secoes, n_canais, 2) — para
            # filtrar todos os canais numa chamada so' de sosfilt. Ver
            # apply_sample: mesmo resultado bit a bit, 8x mais rapido.
            self._zi_notch = np.repeat(zi[:, None, :], self.num_channels,
                                       axis=1).copy()
        else:
            self._sos_notch = self._zi_notch = None
        if self.bandpass_enabled and 0 < self.bp_low < self.bp_high < nyq:
            self._sos_bp = scipy_signal.butter(
                4, [self.bp_low / nyq, self.bp_high / nyq],
                btype="bandpass", output="sos",
            )
            zi = scipy_signal.sosfilt_zi(self._sos_bp)
            self._zi_bp = np.repeat(zi[:, None, :], self.num_channels,
                                    axis=1).copy()
        else:
            self._sos_bp = self._zi_bp = None

    def set_sample_rate(self, sample_rate):
        """Troca a taxa de amostragem da cadeia e refaz coeficientes e estado.

        Faltava esta porta de entrada: a taxa só era fixada no construtor, e a
        janela criava a cadeia uma única vez com 250 Hz. Em Cyton+Daisy chegam
        16 canais a 125 Hz (dois pacotes de 8 formam uma amostra), mas nyq
        continuava 125 em vez de 62,5 e todo pedido de frequência valia o dobro:
        o notch de 60 Hz rejeitava 30 Hz (ganho medido 0,0000) e deixava a rede
        de 60 Hz passar com ganho 1,0000; o passa-faixa 1-50 virava 0,5-25 Hz.
        Devolve True só quando a taxa mudou, para o chamador poder registrar.
        """
        sr = float(sample_rate)
        if sr <= 0 or abs(sr - self.sample_rate) < 1e-9:
            return False
        self.sample_rate = sr
        self.rebuild()       # nyq, SOS e zi recalculados já na taxa nova
        self.reset_state()   # zi antigo pertence à taxa antiga: viraria transiente
        return True

    def reset_state(self):
        """Zera a memória dos filtros em todos os canais; chamada ao (re)conectar,
        para o sinal novo não herdar o transiente da sessão anterior."""
        if self._zi_notch is not None:
            self._zi_notch *= 0
        if self._zi_bp is not None:
            self._zi_bp *= 0

    def apply_sample(self, sample):
        """Aplica re-ref + notch + bandpass aos canais ativos.

        Ordem: re-referenciação → notch → bandpass (padrão da literatura).
        """
        # 1) Re-referenciação (CAR / Laplacian / Mastoid / Bipolar / REST)
        if self.reref_mode != self.REREF_NONE:
            out = self.apply_reref(sample)
        else:
            out = sample.copy()
        # Uma chamada de sosfilt por canal e por filtro (16 chamadas com 8
        # canais) custava 82% do tempo de _on_sample — 1,352 ms por amostra na
        # aba Tempo Real, o que fazia o marcapasso disparar em rajada e o
        # cabecalho acusar "perda" que nao existia. Com os canais como eixo
        # (axis=-1) sao 2 chamadas: 0,210 -> 0,026 ms, resultado identico.
        n = len(out)
        m = min(n, self.num_channels)
        if m > 0 and self._sos_notch is not None:
            y, self._zi_notch[:, :m, :] = scipy_signal.sosfilt(
                self._sos_notch, out[:m].reshape(m, 1),
                zi=self._zi_notch[:, :m, :], axis=-1)
            out[:m] = y[:, 0]
        if m > 0 and self._sos_bp is not None:
            y, self._zi_bp[:, :m, :] = scipy_signal.sosfilt(
                self._sos_bp, out[:m].reshape(m, 1),
                zi=self._zi_bp[:, :m, :], axis=-1)
            out[:m] = y[:, 0]
        return out


# ============================================================
# UDPSender
# ============================================================
class UDPSender:
    """Espelha amostras e marcadores como datagramas JSON para um destino UDP,
    permitindo integrar o app com software externo (jogos, Unity, scripts de
    análise).

    A janela principal mantém uma instância única (self.udp), ligada e
    desligada pelo botão de streaming da aba de integração. É fire-and-forget:
    sem handshake, sem ACK, sem reenvio — pacote perdido é perdido, e ninguém
    percebe.
    """
    def __init__(self):
        """Cria o sender desabilitado, apontando para 127.0.0.1:12345."""
        self.host = "127.0.0.1"
        self.port = 12345
        self.enabled = False
        self._sock = None

    def start(self):
        """Abre o socket UDP e habilita o envio, devolvendo False se a criação do
        socket falhar.

        Não válida host nem porta: UDP não estabelece conexão, então um destino
        errado só se manifesta como pacotes que somem silenciosamente.
        """
        try:
            self._sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            self.enabled = True
            return True
        except Exception:
            self._sock = None; self.enabled = False; return False

    def stop(self):
        """Fecha o socket e desabilita o envio."""
        if self._sock:
            try: self._sock.close()
            except Exception: pass
        self._sock = None; self.enabled = False

    def send_sample(self, t, sample):
        """Empacota uma amostra (tempo de sessão, número de canais e valores) em
        JSON e dispara para o destino UDP configurado.

        É chamada uma vez por amostra dentro de _on_sample, ou seja, a
        serialização JSON acontece na taxa de aquisição. Valores vão
        arredondados em 3 casas e o tempo em 4. Qualquer exceção de envio é
        engolida sem log, então falha de rede não aparece na interface.
        """
        if not self.enabled or self._sock is None: return
        try:
            payload = json.dumps({
                "t": round(t, 4),
                "n": len(sample),
                "v": [round(float(x), 3) for x in sample],
            }).encode("utf-8")
            self._sock.sendto(payload, (self.host, self.port))
        except Exception: pass

    def send_marker(self, t, label):
        """Envia um marcador rotulado pelo mesmo socket das amostras, para o
        receptor externo sincronizar eventos com o sinal.

        O datagrama tem as chaves "t" e "marker", enquanto as amostras usam
        "t"/"n"/"v" — quem recebe precisa distinguir os dois formatos no mesmo
        fluxo. Exceções de envio são engolidas.
        """
        if not self.enabled or self._sock is None: return
        try:
            payload = json.dumps({"t": round(t, 4), "marker": str(label)}).encode("utf-8")
            self._sock.sendto(payload, (self.host, self.port))
        except Exception: pass


# ============================================================
# LSLSender — Lab Streaming Layer (padrão de neurociência)
# ============================================================
class LSLSender:
    """Stream EEG via LSL (Lab Streaming Layer) — sub-ms sync com
    PsychoPy, OpenViBE, Unity, Matlab e centenas de outros softwares."""

    def __init__(self):
        """Cria o emissor LSL desligado, sem outlets, com o nome de stream e o
        source_id padrão."""
        self.enabled  = False
        self.outlet   = None
        self.marker_outlet = None
        self.stream_name   = "EEG_Data_Collector"
        self.source_id     = "eeg_collector_lime"

    @staticmethod
    def available():
        """Informa se o pylsl está disponível, para a interface habilitar ou não a
        opção de streaming LSL."""
        return HAS_LSL

    def start(self, num_channels=8, sample_rate=SAMPLE_RATE, ch_labels=None):
        """Abre os outlets LSL para que PsychoPy, OpenViBE, Unity e afins
        enxerguem o stream de EEG desta coleta.

        Cria DOIS outlets: um de dados (float32, srate nominal) e outro de
        markers (string, srate 0), como manda o padrão LSL. O import de pylsl é
        adiado para dentro da função, então a dependência só pesa quando o
        usuário liga o LSL. Os metadados declaram unidade "microvolts" por
        canal. Em qualquer falha, imprime no console, zera os outlets e devolve
        False — quem chama precisa checar o retorno.
        """
        if not HAS_LSL:
            return False
        try:
            import pylsl  # lazy: só carrega quando o usuário usa LSL
            info = pylsl.StreamInfo(
                name=self.stream_name,
                type="EEG",
                channel_count=num_channels,
                nominal_srate=sample_rate,
                channel_format=pylsl.cf_float32,
                source_id=self.source_id,
            )
            # Channel labels (eletrodos do mapeamento)
            chans = info.desc().append_child("channels")
            for i in range(num_channels):
                ch = chans.append_child("channel")
                lbl = (ch_labels[i] if ch_labels and i < len(ch_labels)
                       else f"CH{i+1}")
                ch.append_child_value("label", lbl)
                ch.append_child_value("unit", "microvolts")
                ch.append_child_value("type", "EEG")
            self.outlet = pylsl.StreamOutlet(info)

            # Outlet de markers separado (padrao LSL)
            mk_info = pylsl.StreamInfo(
                name=f"{self.stream_name}_markers", type="Markers",
                channel_count=1, nominal_srate=0,
                channel_format=pylsl.cf_string,
                source_id=f"{self.source_id}_markers",
            )
            self.marker_outlet = pylsl.StreamOutlet(mk_info)
            self.enabled = True
            return True
        except Exception as exc:
            print(f"[LSL] falha iniciando outlet: {exc}")
            self.outlet = self.marker_outlet = None
            self.enabled = False
            return False

    def stop(self):
        """Desliga o envio LSL soltando as referências aos dois outlets."""
        self.outlet = None
        self.marker_outlet = None
        self.enabled = False

    def send_sample(self, sample):
        """Empurra uma amostra multicanal para o outlet de dados do LSL.

        Silencioso por projeto: sai sem erro se o LSL estiver desligado e
        engole exceções, porque é chamado uma vez por amostra (250 Hz) e não
        pode derrubar a aquisição.
        """
        if not self.enabled or self.outlet is None: return
        try:
            self.outlet.push_sample([float(x) for x in sample])
        except Exception: pass

    def send_marker(self, label):
        """Publica um marcador de evento no outlet de markers, separado do de
        dados."""
        if not self.enabled or self.marker_outlet is None: return
        try:
            self.marker_outlet.push_sample([str(label)])
        except Exception: pass


# ============================================================
# AutoStats — FACILITADOR estatístico: escolhe o teste sozinho
# ============================================================
# Objetivo: o usuário (clínico/estudante) NÃO precisa saber qual teste usar.
# O fluxo padrão da literatura é automatizado: descritivas -> normalidade
# (Shapiro) -> paramétrico/não-paramétrico -> tamanho de efeito -> correção de
# múltiplas comparações (Holm) -> conclusão em linguagem simples.
def _stat_descr(vals):
    """Resume um vetor de valores em n, média, DP, mediana e IQR para as tabelas
    do facilitador estatístico.

    Descarta None e não-finitos antes de calcular. Com n=1 o DP sai 0.0 (não
    NaN), porque ddof=1 não se aplica nesse caso.
    """
    a = np.asarray([v for v in vals if v is not None and np.isfinite(v)], float)
    if a.size == 0:
        return {"n": 0, "mean": float("nan"), "sd": float("nan"),
                "median": float("nan"), "iqr": float("nan")}
    return {"n": int(a.size), "mean": float(np.mean(a)),
            "sd": float(np.std(a, ddof=1)) if a.size > 1 else 0.0,
            "median": float(np.median(a)),
            "iqr": float(np.subtract(*np.percentile(a, [75, 25])))}


def _cohen_d(a, b):
    """Calcula o d de Cohen entre dois grupos independentes, usado como tamanho de
    efeito nos relatórios.

    Usa o DP agrupado (pooled) com ddof=1. Devolve NaN se algum grupo tiver n<2
    ou se o DP agrupado der zero.
    """
    a = np.asarray(a, float); b = np.asarray(b, float)
    na, nb = len(a), len(b)
    if na < 2 or nb < 2:
        return float("nan")
    sp = np.sqrt(((na - 1) * np.var(a, ddof=1) + (nb - 1) * np.var(b, ddof=1))
                 / (na + nb - 2))
    return float((np.mean(a) - np.mean(b)) / sp) if sp > 0 else float("nan")


def _effect_mag(d):
    """Traduz o tamanho de efeito num rótulo verbal
    (desprezível/pequeno/médio/grande) exibido na conclusão em pt-BR.

    Cortes convencionais de Cohen — 0,2 / 0,5 / 0,8 — aplicados sobre o valor
    ABSOLUTO. Valores não-finitos viram "—".
    """
    d = abs(d)
    if not np.isfinite(d):
        return "—"
    if d < 0.2: return tr("desprezível")
    if d < 0.5: return tr("pequeno")
    if d < 0.8: return tr("médio")
    return tr("grande")


def auto_compare(groups, names=None, paired=False, alpha=0.05):
    """Escolhe e roda o teste estatístico adequado automaticamente.
    `groups`: lista de sequências numéricas (2 ou mais grupos)."""
    import scipy.stats as st
    arrs = [np.asarray([v for v in g if v is not None and np.isfinite(v)], float)
            for g in groups]
    names = names or [tr("Grupo {0}").format(i + 1) for i in range(len(arrs))]
    res = {"names": names, "descr": [_stat_descr(g) for g in arrs], "alpha": alpha,
           "test": "—", "stat": float("nan"), "p": float("nan"),
           "effect_name": "—", "effect": float("nan"),
           "normal": None, "ok": False, "note": ""}
    if any(a.size < 2 for a in arrs):
        res["note"] = tr("amostra insuficiente (n<2 em algum grupo)")
        return res

    def _is_normal(a):
        """Decide se um grupo passa como normal, o que define a escolha entre
        teste paramétrico e não-paramétrico.

        Shapiro-Wilk com alfa fixo em 0,05. Atenção: com n<3, ou se o scipy
        levantar exceção, assume normal — ou seja, o caminho de dúvida empurra
        para o teste paramétrico.
        """
        if a.size < 3:
            return True
        try:
            return float(st.shapiro(a).pvalue) > 0.05
        except Exception:
            return True
    all_normal = all(_is_normal(a) for a in arrs)
    res["normal"] = bool(all_normal)
    try:
        if len(arrs) == 2:
            a, b = arrs
            if paired:
                n = min(len(a), len(b)); a, b = a[:n], b[:n]
                # No teste pareado o pressuposto e a normalidade das DIFERENCAS
                # d = a - b, nao de cada grupo isolado.
                diff = a - b
                paired_normal = _is_normal(diff)
                res["normal"] = bool(paired_normal)
                if paired_normal:
                    s, p = st.ttest_rel(a, b); res["test"] = tr("t de Student (pareado)")
                    sd = np.std(diff, ddof=1)
                    res["effect"] = float(np.mean(diff) / sd) if sd > 0 else float("nan")
                    res["effect_name"] = "Cohen dz"
                else:
                    s, p = st.wilcoxon(a, b); res["test"] = tr("Wilcoxon (pareado)")
                    res["effect_name"] = "r"
            else:
                if all_normal:
                    s, p = st.ttest_ind(a, b, equal_var=False)
                    res["test"] = tr("t de Welch (independente)")
                    res["effect"] = _cohen_d(a, b); res["effect_name"] = "Cohen d"
                else:
                    s, p = st.mannwhitneyu(a, b, alternative="two-sided")
                    res["test"] = "Mann-Whitney U"; res["effect_name"] = "r"
            res["stat"] = float(s); res["p"] = float(p)
        else:
            if all_normal:
                s, p = st.f_oneway(*arrs); res["test"] = tr("ANOVA (1 fator)")
            else:
                s, p = st.kruskal(*arrs); res["test"] = "Kruskal-Wallis"
            res["stat"] = float(s); res["p"] = float(p)
        res["ok"] = True
    except Exception as exc:
        res["note"] = tr("falha no teste: {0}").format(exc)
    return res


def holm_correction(pvals):
    """Holm-Bonferroni: p-valores ajustados (mantém a ordem de entrada)."""
    p = np.asarray(pvals, float)
    order = np.argsort(np.where(np.isfinite(p), p, np.inf))
    m = int(np.sum(np.isfinite(p)))
    adj = np.full_like(p, np.nan)
    running, rank = 0.0, 0
    for idx in order:
        if not np.isfinite(p[idx]):
            continue
        rank += 1
        running = max(running, (m - rank + 1) * float(p[idx]))
        adj[idx] = min(running, 1.0)
    return adj.tolist()


def interpret_result(res):
    """Conclusão em linguagem simples (pt-BR) a partir de auto_compare()."""
    if not res.get("ok"):
        return tr("Não foi possível concluir: {0}.").format(res.get('note') or tr('dados insuficientes'))
    p = res["p"]; nm = res["names"]; sig = p < res["alpha"]
    eff, en = res.get("effect"), res.get("effect_name")
    txt = (f"{res['test']}: " +
           (tr("DIFERENÇA significativa") if sig else tr("sem diferença significativa")) +
           f" (p = {p:.4f}).")
    if len(nm) == 2 and sig:
        d = res["descr"]
        maior = nm[0] if d[0]["mean"] >= d[1]["mean"] else nm[1]
        txt += tr(" Em média, {0} é maior.").format(maior)
    if en not in ("—", None) and eff is not None and np.isfinite(eff):
        txt += tr(" Efeito ({0}) = {1:.2f} ({2}).").format(en, eff, _effect_mag(eff))
    if any(d["n"] < 5 for d in res["descr"]):
        txt += tr(" ATENÇÃO: amostra pequena (n<5) — interprete com cautela.")
    return txt


# ============================================================
# GuidedStatsDialog — UI do facilitador estatístico
# ============================================================
class EvolutionDialog(QtWidgets.QDialog):
    """Evolução do paciente ao longo das sessões — o "antes e depois" em curva.

    Responde à pergunta clínica: "entre a primeira coleta e a de hoje, a métrica
    subiu ou desceu?". Para cada sessão do voluntário escolhido calcula UMA
    métrica (potência de banda EEG, RMS ou frequência mediana de EMG, taxa de
    picos de EoG), plota a curva por data, ajusta a tendência por mínimos
    quadrados e mostra a variação percentual entre a primeira e a última.

    Deliberadamente NÃO emite juízo de "melhora/piora": a direção boa depende
    da métrica e do quadro (mais mu em repouso pode ser bom; mais RMS num
    músculo espástico pode ser ruim). O software mostra o número; a leitura é
    do profissional. Para comparar grupos com teste estatístico, o caminho
    continua sendo a Estatística guiada.
    """

    METRICAS = [
        ("Potência de banda EEG (µV²)", "banda"),
        ("RMS do sinal (µV) — EMG/atividade", "rms"),
        ("Frequência mediana (Hz) — fadiga EMG", "mdf"),
        ("Frequência cardíaca (bpm) — ECG", "fc"),
        ("Picos/min (limiar 80 µV) — piscadas EoG*", "picos"),
    ]
    # Cada métrica pertence a um tipo de exame: a curva misturava EEG, EMG,
    # ECG e EOG do mesmo paciente e dava "+59%" sem sentido (G21)
    METRICA_MODALIDADE = {"banda": "EEG", "rms": "EMG", "mdf": "EMG",
                          "fc": "ECG", "picos": "EoG"}
    # Rótulos do Simples, em palavras comuns (tr no ponto de exibição)
    METRICAS_LEIGO = {"banda": "Ondas do cérebro (força do ritmo escolhido)",
                      "rms": "Força do músculo",
                      "mdf": "Cansaço do músculo (frequência mediana)",
                      "fc": "Batimentos do coração por minuto",
                      "picos": "Piscadas por minuto"}

    def __init__(self, parent, sessoes):
        """Recebe a lista de sessões já varrida por _list_all_sessions."""
        super().__init__(parent)
        self._simples = bool(getattr(parent, "_nivel_simples", lambda: False)())
        self.setWindowTitle(
            tr("Evolução do paciente — gravações ao longo do tempo") if self._simples
            else tr("Evolução do paciente — sessões ao longo do tempo"))
        self.resize(980, 680)
        self._sessoes = sessoes
        self._resultado = []          # [(rotulo, data, valor)]
        self._ignoradas = 0           # gravações de outro tipo de exame

        lay = QtWidgets.QVBoxLayout(self)

        # ---- filtros ----
        topo = QtWidgets.QGridLayout()
        topo.addWidget(QtWidgets.QLabel(
            tr("Paciente:") if self._simples else tr("Voluntário:")), 0, 0)
        self.cb_vol = QtWidgets.QComboBox()
        vols = sorted({s.get("volunteer", "") for s in sessoes
                       if s.get("volunteer")})
        self.cb_vol.addItem(tr("(todos os pacientes)") if self._simples
                            else tr("(todas as sessões)"), "")
        for v in vols:
            self.cb_vol.addItem(v, v)
        # o paciente em uso já vem escolhido
        try:
            cur = parent.volunteers.current() or {}
            i = self.cb_vol.findData(f"{cur.get('vid', '')} {cur.get('nome', '')}".strip())
            if i > 0:
                self.cb_vol.setCurrentIndex(i)
        except Exception:
            pass
        topo.addWidget(self.cb_vol, 0, 1)

        topo.addWidget(QtWidgets.QLabel(tr("Métrica:")), 0, 2)
        self.cb_met = QtWidgets.QComboBox()
        for rot, chave in self.METRICAS:
            self.cb_met.addItem(
                tr(self.METRICAS_LEIGO[chave]) if self._simples else tr(rot), chave)
        # a métrica do exame em uso já vem escolhida (Multimodal fica no EEG)
        modo = getattr(getattr(parent, "config", None), "acquisition_mode", "EEG")
        for i, (_r, chave) in enumerate(self.METRICAS):
            if self.METRICA_MODALIDADE.get(chave) == modo:
                self.cb_met.setCurrentIndex(i)
                break
        self.cb_met.currentIndexChanged.connect(self._metrica_mudou)
        topo.addWidget(self.cb_met, 0, 3)

        topo.addWidget(QtWidgets.QLabel(
            tr("Ritmo:") if self._simples else tr("Banda:")), 1, 0)
        self.cb_banda = QtWidgets.QComboBox()
        self.cb_banda.addItems(list(EEG_BANDS.keys()))
        self.cb_banda.setCurrentText("Alpha")
        topo.addWidget(self.cb_banda, 1, 1)

        canais_lbl = QtWidgets.QLabel(tr("Canais (ex.: C3,C4 ou vazio=todos):"))
        topo.addWidget(canais_lbl, 1, 2)
        self.ed_canais = QtWidgets.QLineEdit("")
        self.ed_canais.setPlaceholderText(tr("todos"))
        topo.addWidget(self.ed_canais, 1, 3)
        # no Simples os canais são escolhidos pelo tipo do exame
        canais_lbl.setVisible(not self._simples)
        self.ed_canais.setVisible(not self._simples)

        self.bt_rodar = QtWidgets.QPushButton(tr("Calcular evolução"))
        self.bt_rodar.setMinimumHeight(30)
        self.bt_rodar.clicked.connect(self._rodar)
        topo.addWidget(self.bt_rodar, 0, 4, 2, 1)
        lay.addLayout(topo)

        # ---- gráfico ----
        self.plot = pg.PlotWidget(enableMenu=False)
        self.plot.showGrid(x=True, y=True, alpha=0.2)
        self.plot.setLabel("bottom", tr("Gravação (da mais antiga à mais recente)")
                           if self._simples else tr("Sessão (ordem cronológica)"))
        self.curva = self.plot.plot(pen=pg.mkPen(COLORS["accent"], width=2),
                                    symbol="o", symbolSize=8,
                                    symbolBrush=COLORS["accent"])
        self.tendencia = self.plot.plot(pen=pg.mkPen(
            COLORS["warning"], width=1.6, style=QtCore.Qt.PenStyle.DashLine))
        lay.addWidget(self.plot, stretch=2)

        # ---- resumo + tabela ----
        self.lb_resumo = QtWidgets.QLabel("—")
        self.lb_resumo.setWordWrap(True)
        self.lb_resumo.setStyleSheet(
            f"color: {COLORS['text']}; background: {COLORS['surface_alt']}; "
            f"border: 1px solid {COLORS['border']}; border-radius: 4px; "
            f"padding: 8px;")
        lay.addWidget(self.lb_resumo)

        self.tabela = QtWidgets.QTableWidget(0, 3)
        self.tabela.setHorizontalHeaderLabels(
            [tr("Gravação") if self._simples else tr("Sessão"), tr("Data"), tr("Valor")])
        self.tabela.horizontalHeader().setSectionResizeMode(
            0, QtWidgets.QHeaderView.ResizeMode.Stretch)
        # A coluna Data nascia com 100 px e o carimbo completo mede ~152:
        # data e hora saiam com reticencias.
        self.tabela.horizontalHeader().setSectionResizeMode(
            1, QtWidgets.QHeaderView.ResizeMode.ResizeToContents)
        self.tabela.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        lay.addWidget(self.tabela, stretch=1)

        rodape = QtWidgets.QHBoxLayout()
        self.lb_nota = QtWidgets.QLabel(
            tr("Piscadas por minuto é uma estimativa; confira no traçado.")
            if self._simples else
            tr("*Picos/min é uma estimativa por limiar; confirme no traçado."))
        self.lb_nota.setStyleSheet(f"color: {COLORS['text_dim']}; font-style: italic;")
        rodape.addWidget(self.lb_nota)
        rodape.addStretch()
        bt_csv = QtWidgets.QPushButton(tr("Exportar CSV…"))
        bt_csv.clicked.connect(self._exportar_csv)
        rodape.addWidget(bt_csv)
        bt_png = QtWidgets.QPushButton(tr("Exportar imagem…"))
        bt_png.clicked.connect(self._exportar_png)
        rodape.addWidget(bt_png)
        lay.addLayout(rodape)
        self._metrica_mudou()

    def _metrica_mudou(self):
        """A escolha de banda só faz sentido para a métrica de potência EEG."""
        eh_banda = self.cb_met.currentData() == "banda"
        self.cb_banda.setEnabled(eh_banda)

    # ---- cálculo ----
    def _canais_escolhidos(self, ch_names, n_ch):
        """Converte o texto \"C3,C4\" em índices; vazio = todos os canais."""
        txt = self.ed_canais.text().strip()
        if not txt:
            return list(range(n_ch))
        alvo = {t.strip().upper() for t in txt.replace(";", ",").split(",")
                if t.strip()}
        idx = []
        for i, nome in enumerate(ch_names[:n_ch]):
            base = str(nome).upper().replace("_UV", "").strip()
            if base in alvo or f"CH{i+1}" in alvo:
                idx.append(i)
        return idx or list(range(n_ch))

    def _metrica_da_sessao(self, csv_path, tipos=None):
        """Calcula a métrica escolhida para UMA sessão; None se ilegível.

        `tipos` (channel_types do summary.json): sem canais digitados, ficam
        só os canais do tipo da métrica — no Multimodal a banda EEG saía da
        média com os canais de músculo e coração (G21)."""
        try:
            d = self.parent()._load_session_csv(csv_path)
            X = np.asarray(d.get("eeg"), float)
            if X.size == 0:
                return None
            sr = float(d.get("sr") or SAMPLE_RATE)
            nomes = d.get("ch_names") or [f"CH{i+1}" for i in range(X.shape[0])]
            met = self.cb_met.currentData()
            idx = self._canais_escolhidos(nomes, X.shape[0])
            if not self.ed_canais.text().strip() and tipos:
                alvo = self.METRICA_MODALIDADE.get(met)
                do_tipo = [i for i in range(X.shape[0])
                           if i < len(tipos) and tipos[i] == alvo]
                if do_tipo:
                    idx = do_tipo
            X = X[idx]
            X = X - np.median(X, axis=1, keepdims=True)
            if met == "fc":
                return self._frequencia_cardiaca(X, sr)
            if met == "banda":
                lo, hi = EEG_BANDS_CATALOGO[self.cb_banda.currentText()]
                vals = [SignalProcessor.compute_band_power(c, lo, hi, sr)
                        for c in X]
                return float(np.mean(vals))
            if met == "rms":
                return float(np.sqrt(np.mean(X ** 2)))
            if met == "mdf":
                vals = []
                for c in X:
                    nper = min(1024, len(c))
                    if nper < 64:
                        continue
                    f, p = scipy_signal.welch(c, fs=sr, nperseg=nper)
                    # ISEK/SENIAM: MDF de fadiga só vale de 20 Hz para cima.
                    # Integrando a PSD inteira (0 Hz -> Nyquist), um artefato de
                    # movimento/cabo de 2 Hz domina a potência e derruba o MDF de
                    # ~65 Hz para ~2 Hz. Como este diálogo NÃO pré-filtra o sinal
                    # (só subtrai a mediana, que não toca em 2 Hz), a curva de
                    # evolução acusava "queda de 97%" entre sessões — leitura de
                    # fadiga severa — quando o único fato novo era um eletrodo
                    # balançando. Mesma banda que o painel de fadiga ao vivo e o
                    # run_recipe já usam, para os três números não se contradizerem.
                    b = (f >= 20.0) & (f <= min(500.0, f[-1]))
                    f, p = f[b], p[b]
                    if f.size < 2:
                        continue
                    acum = np.cumsum(p)
                    if acum[-1] <= 0:
                        continue
                    vals.append(float(f[min(int(np.searchsorted(acum,
                                                        acum[-1] / 2.0)), f.size - 1)]))
                return float(np.mean(vals)) if vals else None
            if met == "picos":
                # estimativa: deflexões acima de 80 µV com refratário de 300 ms
                melhor = X[np.argmax(np.max(np.abs(X), axis=1))]
                lim = 80.0
                acima = np.abs(melhor) > lim
                bordas = np.flatnonzero(np.diff(acima.astype(int)) == 1)
                if bordas.size == 0:
                    return 0.0
                refr = int(0.3 * sr)
                picos, ultimo = 0, -refr
                for b in bordas:
                    if b - ultimo >= refr:
                        picos += 1
                        ultimo = b
                minutos = melhor.size / sr / 60.0
                return picos / minutos if minutos > 0 else None
        except Exception:
            return None
        return None

    @staticmethod
    def _frequencia_cardiaca(X, sr):
        """Batimentos por minuto pelo canal de ritmo mais regular (Pan-Tompkins
        + intervalos RR); None com menos de 3 batimentos."""
        melhor = None
        for c in X:
            rr = ecg_rr(ecg_pan_tompkins(c, sr), sr)
            if rr.size < 3 or np.mean(rr) <= 0:
                continue
            cv = float(np.std(rr) / np.mean(rr))
            if melhor is None or cv < melhor[0]:
                melhor = (cv, 60000.0 / float(np.mean(rr)))
        return None if melhor is None else melhor[1]

    def _rodar(self):
        """Calcula a métrica escolhida em cada sessão do voluntário filtrado,
        traça curva + tendência linear e preenche a tabela; exige >= 2 sessões
        legíveis e resume a variação primeira→última em % com aviso clínico.

        Só entram as gravações do tipo de exame da métrica (o Multimodal
        entra quando tem canais desse tipo); as outras são contadas e a tela
        diz quantas ficaram de fora (G21)."""
        vol = self.cb_vol.currentData()
        do_vol = [s for s in self._sessoes
                  if not vol or s.get("volunteer", "") == vol]
        alvo = self.METRICA_MODALIDADE.get(self.cb_met.currentData())
        sess, self._ignoradas = [], 0
        for s in do_vol:
            modo = s.get("modality")
            if (modo is None or modo == alvo
                    or (modo == "Hibrido" and alvo in (s.get("ch_types") or []))):
                sess.append(s)
            else:
                self._ignoradas += 1
        # ordena pelo que houver de data; sem data vai para o fim, por nome
        sess.sort(key=lambda s: (s.get("date") or "9999", s.get("name", "")))
        if len(sess) < 2:
            txt = (tr("São necessárias pelo menos 2 gravações do mesmo paciente "
                      "para traçar evolução.") if self._simples else
                   tr("São necessárias pelo menos 2 sessões do mesmo voluntário "
                      "para traçar evolução."))
            if self._ignoradas:
                txt += " " + self._frase_ignoradas()
            QtWidgets.QMessageBox.information(self, tr("Evolução"), txt)
            return
        QtWidgets.QApplication.setOverrideCursor(
            QtCore.Qt.CursorShape.WaitCursor)
        try:
            self._resultado = []
            for s in sess:
                v = self._metrica_da_sessao(s.get("csv"), s.get("ch_types"))
                if v is not None and np.isfinite(v):
                    self._resultado.append(
                        (s.get("name", "?"), s.get("date", ""), float(v)))
        finally:
            QtWidgets.QApplication.restoreOverrideCursor()
        if len(self._resultado) < 2:
            QtWidgets.QMessageBox.information(
                self, tr("Evolução"),
                tr("Menos de 2 sessões legíveis para essa métrica."))
            return

        y = np.array([r[2] for r in self._resultado])
        x = np.arange(len(y), dtype=float)
        self.curva.setData(x, y)
        a, b = np.polyfit(x, y, 1)
        self.tendencia.setData(x, a * x + b)
        eixo = self.plot.getAxis("bottom")
        # A data ISO tem 19 caracteres; cortar em 10 jogava a hora fora e
        # tres sessoes do mesmo dia viravam tres rotulos identicos.
        dias = set(r[1][:10] for r in self._resultado if r[1])
        mesmo_dia = len(dias) <= 1
        rotulos = []
        for i, r in enumerate(self._resultado):
            iso = r[1] or ""
            if len(iso) >= 10:
                txt = iso[8:10] + "/" + iso[5:7]
                if mesmo_dia and len(iso) >= 16:
                    txt += " " + iso[11:16]
            else:
                txt = (r[0] or "")[:10]    # sessao sem summary.json: o nome
            rotulos.append((i, txt))
        eixo.setTicks([rotulos])
        self.plot.setLabel("left", self.cb_met.currentText().split("(")[0].strip())

        delta = ((y[-1] - y[0]) / abs(y[0]) * 100.0) if y[0] else float("nan")
        seta = "↑" if y[-1] > y[0] else ("↓" if y[-1] < y[0] else "→")
        # no Simples não há Estatística guiada para apontar (G21)
        aviso = (tr("A direção desejável depende do que está sendo tratado: "
                    "interprete com o profissional. Este resumo não é laudo "
                    "nem diagnóstico.") if self._simples else
                 tr("A direção desejável depende da métrica e do quadro "
                    "clínico — interprete com o profissional. Para teste "
                    "estatístico Antes × Depois, use a Estatística guiada."))
        if self._ignoradas:
            aviso = self._frase_ignoradas() + " " + aviso
        # números no idioma da tela: "3.739" com ponto parecia três mil (G27)
        self.lb_resumo.setText(
            f"<b>{len(y)} "
            f"{tr('gravações analisadas') if self._simples else tr('sessões analisadas')}"
            f"</b> · {tr('primeira')}: {num_loc(y[0], 3, 'g')} · "
            f"{tr('última')}: {num_loc(y[-1], 3, 'g')} · "
            f"<b>{tr('variação')}: {seta} {num_loc(delta, 1, sinal=True)}%</b> · "
            f"{tr('tendência')}: {num_loc(a, 3, 'g', sinal=True)}/"
            f"{tr('gravação') if self._simples else tr('sessão')}<br>"
            f"<span style='color:{COLORS['text_dim']}'>{aviso}</span>")

        self.tabela.setRowCount(len(self._resultado))
        for i, (nome, data, valor) in enumerate(self._resultado):
            self.tabela.setItem(i, 0, QtWidgets.QTableWidgetItem(nome))
            self.tabela.setItem(i, 1, QtWidgets.QTableWidgetItem(data))
            it = QtWidgets.QTableWidgetItem(num_loc(valor, 4, "g"))
            it.setTextAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            self.tabela.setItem(i, 2, it)

    def _frase_ignoradas(self):
        """"2 gravação(ões) de outro tipo de exame foram ignoradas." (G21)."""
        return (tr("{0} gravação(ões) de outro tipo de exame foram ignoradas.")
                if self._simples else
                tr("{0} sessão(ões) de outra modalidade foram ignoradas.")
                ).format(self._ignoradas)

    # ---- exportação ----
    def _exportar_csv(self):
        """Salva a evolução calculada (sessão, data, valor) em CSV com BOM
        UTF-8 para abrir certo no Excel; silencioso se nada foi calculado."""
        if not self._resultado:
            return
        p, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Exportar evolução"), "evolucao.csv", "CSV (*.csv)")
        if not p:
            return
        with io.open(p, "w", encoding="utf-8-sig", newline="") as f:
            wcsv = csv.writer(f)
            wcsv.writerow(["sessao", "data",
                           self.cb_met.currentText()])
            wcsv.writerows(self._resultado)

    def _exportar_png(self):
        """Salva um PNG do gráfico de evolução via grab() do widget (captura
        o que está na tela, incluindo tendência e eixos rotulados)."""
        if not self._resultado:
            return
        p, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Exportar imagem"), "evolucao.png", "PNG (*.png)")
        if not p:
            return
        self.plot.grab().save(p)


class GuidedStatsDialog(QtWidgets.QDialog):
    """Compara grupos de sessões (ex.: Antes × Depois) por banda de potência,
    escolhe o teste sozinho, monta a tabela e explica — sem exigir conhecimento
    estatístico do usuário."""

    COLS = ["banda", "A", "B", "teste", "p", "p_holm", "efeito", "signif"]

    def __init__(self, main):
        """Monta a janela de comparação entre dois grupos de sessões: nomes dos
        grupos, seleção de arquivos, tabela por banda e área de conclusão.

        Os widgets de cada grupo são criados em laço e guardados via setattr
        com os nomes name_A, cnt_A, name_B e cnt_B — é por esses nomes que o
        resto da classe os acessa, então eles não aparecem em atribuições
        explícitas.
        """
        super().__init__(main)
        self.main = main
        self._files = {"A": [], "B": []}
        self._rows = []
        self.setWindowTitle(tr("Estatística guiada — comparar grupos"))
        self.resize(860, 580)
        v = QtWidgets.QVBoxLayout(self)
        intro = QtWidgets.QLabel(
            tr("Selecione as sessões de cada grupo (ex.: <b>Antes</b> × <b>Depois</b>). "
            "Você pode juntar sessões de <b>vários pacientes</b> no mesmo grupo — "
            "ex.: o \"antes\" de todos num grupo e o \"depois\" de todos no outro. "
            "<b>Com ≥ 2 sessões em cada grupo:</b> cada sessão conta como "
            "1 amostra (<b>≥ 5</b> para um resultado confiável).<br>"
            "<b>Com 1 arquivo só em algum grupo:</b> o programa passa a fatiar "
            "as gravações em <b>janelas de até 10 s</b> — cada janela vira uma "
            "amostra. O fatiamento vale para <b>os dois grupos</b> (mesmo o que "
            "tiver vários arquivos), para a unidade de amostra ser a mesma dos "
            "dois lados; a duração real da janela é informada no resultado. "
            "Assim dá para comparar 1 arquivo × 1 arquivo, mas o valor de p "
            "fica otimista — use como exploratório.<br>"
            "O programa escolhe o teste, monta a tabela por banda (δ θ α β γ) e "
            "explica em linguagem simples. Aceita <b>.csv</b> e também "
            "<b>.edf/.bdf</b> (converte na hora)."))
        intro.setWordWrap(True); intro.setTextFormat(QtCore.Qt.TextFormat.RichText)
        v.addWidget(intro)
        for key, default in (("A", tr("Antes")), ("B", tr("Depois"))):
            row = QtWidgets.QHBoxLayout()
            row.addWidget(QtWidgets.QLabel(tr("Grupo {0}:").format(key)))
            name = QtWidgets.QLineEdit(default); setattr(self, f"name_{key}", name)
            row.addWidget(name)
            cnt = QtWidgets.QLabel(tr("0 sessões")); setattr(self, f"cnt_{key}", cnt)
            row.addWidget(cnt, 1)
            btn = QtWidgets.QPushButton(tr("Selecionar sessões…"))
            btn.clicked.connect(lambda _, k=key: self._pick(k))
            row.addWidget(btn)
            v.addLayout(row)
        self.paired_chk = QtWidgets.QCheckBox(
            tr("Amostras pareadas (os mesmos sujeitos nos dois grupos)"))
        v.addWidget(self.paired_chk)
        run = QtWidgets.QPushButton(tr("Comparar"))
        run.clicked.connect(self._compute)
        v.addWidget(run)
        self.table = QtWidgets.QTableWidget(0, len(self.COLS))
        self.table.setHorizontalHeaderLabels([tr("Banda"), tr("Grupo A"), tr("Grupo B"), tr("Teste"), tr("p"), tr("p (Holm)"),
             tr("Efeito"), tr("Signif.?")])
        self.table.horizontalHeader().setStretchLastSection(True)
        v.addWidget(self.table, 1)
        self.summary = QtWidgets.QTextEdit(); self.summary.setReadOnly(True)
        self.summary.setMaximumHeight(140)
        v.addWidget(self.summary)
        save = QtWidgets.QPushButton(tr("Salvar relatório (HTML + CSV)…"))
        save.clicked.connect(self._save)
        v.addWidget(save)

    def _pick(self, key):
        """Abre o seletor de arquivos de um grupo e atualiza o contador colorido
        de sessões.

        Arquivos .edf/.bdf escolhidos aqui são convertidos na hora para CSV
        nativo num arquivo temporário (edf_to_native_csv), e a lista passa a
        guardar o caminho do temporário, não o original. A cor do rótulo
        codifica a regra de amostra: verde para n>=5, âmbar para n>=2 e
        vermelho abaixo disso.
        """
        start = getattr(self.main.config, "save_directory", "")
        files, _ = QtWidgets.QFileDialog.getOpenFileNames(
            self, tr("Sessões do Grupo {0}").format(key), start,
            tr("Sessões (*.csv *.edf *.bdf *.EDF *.BDF);;CSV (*.csv);;Todos (*)"))
        if not files:
            return
        # Converte EDF/BDF -> CSV nativo (temporário) automaticamente.
        resolved = []
        for f in files:
            if os.path.splitext(f)[1].lower() in (".edf", ".bdf"):
                try:
                    import tempfile
                    tmp = os.path.join(
                        tempfile.gettempdir(),
                        f"edfimp_{os.path.splitext(os.path.basename(f))[0][:30]}.csv")
                    edf_to_native_csv(f, tmp)
                    resolved.append(tmp)
                except Exception as exc:
                    QtWidgets.QMessageBox.warning(
                        self, "EDF", tr("Não consegui ler {0}:\n{1}").format(os.path.basename(f), exc))
            else:
                resolved.append(f)
        if not resolved:
            # Nenhum arquivo sobreviveu (ex.: único .edf escolhido está
            # corrompido). Antes isto APAGAVA a seleção anterior do grupo e
            # ainda mostrava "0 sessão ✓" — mantemos o que já havia.
            QtWidgets.QMessageBox.warning(
                self, tr("Nada a adicionar"),
                tr("Nenhum dos arquivos escolhidos pôde ser lido.\n"
                   "A seleção anterior deste grupo foi mantida."))
            return
        self._files[key] = resolved
        lbl = getattr(self, f"cnt_{key}")
        n = len(resolved)
        if n >= 5:
            lbl.setText(tr("{0} sessões ✓ (bom)").format(n)); lbl.setStyleSheet("color:#1E7E34;")
        elif n >= 2:
            lbl.setText(tr("{0} sessões ✓ (mínimo; ≥5 é melhor)").format(n))
            lbl.setStyleSheet("color:#B8860B;")
        else:
            lbl.setText(tr("{0} sessão ✓ (liga o modo janelas)").format(n))
            lbl.setStyleSheet("color:#B8860B;")
        # Um grupo com 1 arquivo joga OS DOIS no modo janelas — o outro rótulo
        # precisa dizer isso, senão diz "5 sessões" e a tabela mostra 150 n.
        self._sync_rotulos_grupos()

    def _sync_rotulos_grupos(self):
        """Faz os dois contadores concordarem sobre o modo em vigor.

        Quando qualquer grupo fica com 1 arquivo, a comparação inteira passa a
        ser por janelas; sem este aviso o outro grupo continuaria anunciando
        "5 sessões" enquanto a tabela reporta n=150 janelas.
        """
        modo_janelas = any(len(self._files[k]) == 1 for k in ("A", "B"))
        for k in ("A", "B"):
            lbl = getattr(self, f"cnt_{k}", None)
            n = len(self._files[k])
            if lbl is None or n < 2:
                continue
            if modo_janelas:
                lbl.setText(tr("{0} sessões — serão fatiadas em janelas").format(n))
                lbl.setStyleSheet("color:#B8860B;")
            elif n >= 5:
                lbl.setText(tr("{0} sessões ✓ (bom)").format(n))
                lbl.setStyleSheet("color:#1E7E34;")
            else:
                lbl.setText(tr("{0} sessões ✓ (mínimo; ≥5 é melhor)").format(n))
                lbl.setStyleSheet("color:#B8860B;")

    def _band_powers(self, csv_path):
        """Reduz uma sessão inteira a um valor de potência por banda — é esse
        número que vira UMA amostra no teste estatístico.

        Welch com nperseg limitado a 256 amostras, integrando a PSD dentro de
        cada faixa de EEG_BANDS e tirando a média entre TODOS os canais (não dá
        para escolher canal nesta tela). Devolve None quando o CSV não carrega,
        e o chamador simplesmente ignora a sessão.
        """
        d = self.main._load_session_csv(csv_path)
        if not d:
            return None
        eeg, sr = d["eeg"], d["sr"]
        out = {}
        for band, (lo, hi) in EEG_BANDS.items():
            vals = []
            for i in range(eeg.shape[0]):
                f, psd = scipy_signal.welch(eeg[i], fs=sr,
                                            nperseg=min(256, eeg.shape[1]))
                m = (f >= lo) & (f < hi)
                vals.append(float(_TRAPEZOID(psd[m], f[m])) if np.any(m) else 0.0)
            out[band] = float(np.mean(vals)) if vals else 0.0
        return out

    def _band_powers_windows(self, csv_path, win_s=10.0):
        """Divide UMA sessão em janelas de tempo e devolve uma lista de dicts
        de potência por banda — cada janela vira uma amostra do teste.

        É o que permite comparar 1 arquivo × 1 arquivo. Janelas sem overlap e
        de duração FIXA: quem escolhe win_s é o chamador (_janela_comum), para
        os dois grupos usarem exatamente a mesma unidade amostral. Devolve
        lista vazia quando o CSV não carrega ou não cabe nem uma janela.
        """
        d = self.main._load_session_csv(csv_path)
        if not d:
            return []
        eeg, sr = d["eeg"], d["sr"]
        n = int(win_s * sr)
        if n < 1 or eeg.shape[1] < n:
            return []
        out = []
        for k in range(eeg.shape[1] // n):
            seg = eeg[:, k * n:(k + 1) * n]
            p = {}
            for band, (lo, hi) in EEG_BANDS.items():
                vals = []
                for i in range(seg.shape[0]):
                    f, psd = scipy_signal.welch(seg[i], fs=sr,
                                                nperseg=min(256, seg.shape[1]))
                    m = (f >= lo) & (f < hi)
                    vals.append(float(_TRAPEZOID(psd[m], f[m]))
                                if np.any(m) else 0.0)
                p[band] = float(np.mean(vals)) if vals else 0.0
            out.append(p)
        return out

    def _janela_comum(self, arquivos, alvo_s=10.0, piso_s=2.0):
        """Escolhe UMA duração de janela que sirva aos dois grupos.

        Sem isso, um grupo poderia acabar com janelas de 10 s e o outro com
        janelas de 3 s: as amostras deixam de ser comparáveis (médias de Welch
        sobre trechos de tamanhos diferentes têm variâncias diferentes), que é
        exatamente o que o modo janelas existe para evitar.

        Usa a MENOR gravação do conjunto e pede que ela renda pelo menos 2
        janelas. Devolve None quando nem a janela mínima cabe duas vezes.
        """
        menor = None
        for c in arquivos:
            d = self.main._load_session_csv(c)
            if not d or d["eeg"].size == 0:
                continue
            dur = d["eeg"].shape[1] / float(d["sr"] or 1)
            menor = dur if menor is None else min(menor, dur)
        if menor is None:
            return None
        win = min(alvo_s, menor / 2.0)
        return win if win >= piso_s else None

    def _compute(self):
        """Roda a comparação banda a banda, preenche a tabela e escreve a
        conclusão em linguagem simples.

        A correção de Holm é aplicada sobre o conjunto das bandas e a coluna
        "Signif.?" usa o p CORRIGIDO, não o p bruto. Bloqueia a execução com um
        aviso explicativo quando algum grupo tem menos de 2 sessões — esse
        texto existe porque um beta tester travava aqui sem entender o motivo.
        Guarda as células em self._rows, que é o que o relatório escreve.
        """
        A, B = self._files["A"], self._files["B"]
        if not A or not B:
            QtWidgets.QMessageBox.warning(
                self, tr("Grupos"), tr("Selecione sessões nos dois grupos."))
            return None
        nameA = self.name_A.text().strip() or "A"
        nameB = self.name_B.text().strip() or "B"
        # MODO JANELAS: se algum grupo tem 1 arquivo só, os DOIS grupos são
        # fatiados em janelas de MESMA duração (cada janela = 1 amostra), para
        # as unidades amostrais dos dois lados serem comparáveis. Vale para o
        # grupo com 1 arquivo E para o com vários — senão estaríamos comparando
        # "média de sessão" contra "média de janela".
        modo_janelas = (len(A) == 1 or len(B) == 1)
        win_s = None
        if modo_janelas:
            win_s = self._janela_comum(list(A) + list(B))
            if win_s is None:
                QtWidgets.QMessageBox.warning(
                    self, tr("Gravação curta demais"),
                    tr("Para comparar com 1 arquivo por grupo eu divido as "
                    "gravações em janelas de tempo, e cada janela vira uma "
                    "amostra.\n\nA gravação mais curta que você escolheu não "
                    "rende nem duas janelas de 2 s (precisa de ~4 s de sinal).\n\n"
                    "Saída: use sessões mais longas, ou selecione 2 ou mais "
                    "arquivos em cada grupo."))
                return None
            powA = [p for c in A for p in self._band_powers_windows(c, win_s)]
            powB = [p for c in B for p in self._band_powers_windows(c, win_s)]
        else:
            powA = [p for p in (self._band_powers(c) for c in A) if p]
            powB = [p for p in (self._band_powers(c) for c in B) if p]
        if not powA or not powB:
            QtWidgets.QMessageBox.critical(
                self, tr("Dados"), tr("Não consegui ler potências de banda das sessões."))
            return None
        # Checagem de amostra ACIONÁVEL (o beta tester travava aqui sem entender).
        if len(powA) < 2 or len(powB) < 2:
            QtWidgets.QMessageBox.warning(
                self, tr("Amostra insuficiente"),
                tr("Para comparar, cada grupo precisa de pelo menos 2 amostras.\n\nVocê tem "
                   "agora:   {0} = {1}   |   {2} = {3}\n\n").format(nameA, len(powA), nameB, len(powB))
                + (tr("Neste modo cada amostra é uma janela de {0:.0f} s da gravação — se "
                      "apareceu este aviso, a gravação é curta demais.\n").format(win_s) if modo_janelas else
                   tr("Cada sessão conta como 1 amostra.\n"))
                + tr("Dica: você pode juntar sessões de VÁRIOS pacientes no mesmo grupo (o \"antes\" de todos num grupo, o \"depois\" de todos no outro).\nRecomendado: 5 ou mais sessões por grupo para um resultado confiável."))
            return None
        # Parear janela-a-janela não faz sentido (não são os mesmos sujeitos).
        pareado = self.paired_chk.isChecked() and not modo_janelas
        if pareado and len(powA) != len(powB):
            # auto_compare truncaria no menor silenciosamente, formando pares
            # por POSIÇÃO na lista — com tamanhos diferentes isso quase certo
            # emparelha sujeitos errados. Melhor perguntar do que inventar.
            resp = QtWidgets.QMessageBox.question(
                self, tr("Grupos de tamanhos diferentes"),
                # campos formatados DEPOIS do tr(): com f-string a chave saía
                # já com os números e nunca existia no dicionário
                tr("Você marcou \"amostras pareadas\", mas os grupos têm "
                   "quantidades diferentes de sessões legíveis "
                   "({0} × {1}).\n\n"
                   "No pareado cada sessão do grupo A é comparada com a da "
                   "MESMA POSIÇÃO no grupo B, e o excedente seria descartado "
                   "— o que costuma emparelhar voluntários errados.\n\n"
                   "Quer que eu rode como NÃO pareado (recomendado)?").format(
                       len(powA), len(powB)),
                QtWidgets.QMessageBox.StandardButton.Yes
                | QtWidgets.QMessageBox.StandardButton.Cancel)
            if resp != QtWidgets.QMessageBox.StandardButton.Yes:
                return None
            pareado = False
        bands = list(EEG_BANDS.keys())
        results, pvals = [], []
        for band in bands:
            ga = [p[band] for p in powA]; gb = [p[band] for p in powB]
            r = auto_compare([ga, gb], [nameA, nameB], paired=pareado)
            results.append((band, r)); pvals.append(r["p"])
        adj = holm_correction(pvals)
        self._rows = []
        self.table.setRowCount(len(results))
        for i, (band, r) in enumerate(results):
            da, db = r["descr"]
            eff = r.get("effect")
            eff_txt = (f"{r['effect_name']}={eff:.2f}"
                       if (eff is not None and np.isfinite(eff)
                           and r["effect_name"] not in ("—", None)) else "—")
            cells = {
                "banda": band,
                "A": f"{da['mean']:.3g}±{da['sd']:.2g} (n={da['n']})",
                "B": f"{db['mean']:.3g}±{db['sd']:.2g} (n={db['n']})",
                "teste": r["test"],
                "p": f"{r['p']:.4f}" if np.isfinite(r["p"]) else "—",
                "p_holm": f"{adj[i]:.4f}" if np.isfinite(adj[i]) else "—",
                "efeito": eff_txt,
                "signif": tr("SIM") if (np.isfinite(adj[i]) and adj[i] < 0.05) else tr("não"),
            }
            for j, key in enumerate(self.COLS):
                self.table.setItem(i, j, QtWidgets.QTableWidgetItem(str(cells[key])))
            self._rows.append(cells)
        self.table.setHorizontalHeaderLabels([tr("Banda"), nameA, nameB, tr("Teste"), tr("p"), tr("p (Holm)"), tr("Efeito"), tr("Signif.?")])
        self.table.resizeColumnsToContents()
        sig = [band for (band, _r), a in zip(results, adj)
               if np.isfinite(a) and a < 0.05]
        if modo_janelas:
            jan = f"{win_s:.0f} s" if win_s >= 1 else f"{win_s:.1f} s"
            lines = [tr("Comparação: {0} ({1} janelas de {2}, de {3} arquivo(s)) × "
                        "{4} ({5} janelas de {2}, de {6} arquivo(s)), por banda de "
                        "potência média.").format(nameA, len(powA), jan, len(A),
                                                  nameB, len(powB), len(B)),
                     tr("Como um dos grupos tem 1 arquivo só, os DOIS grupos foram fatiados em "
                        "janelas de {0} — inclusive o grupo com vários arquivos — para que a "
                        "unidade de amostra seja a mesma dos dois lados.").format(jan)]
            if len(A) == 1 and len(B) == 1:
                lines.append(tr("ATENÇÃO: as janelas vêm de uma ÚNICA gravação "
                             "por grupo, então o resultado diz se ESTAS duas "
                             "gravações diferem entre si; não generaliza para "
                             "o paciente nem para um grupo de pacientes. Para "
                             "conclusão clínica, use 2 ou mais sessões por grupo."))
            else:
                lines.append(tr("ATENÇÃO: janelas da mesma gravação não são "
                             "observações independentes, então o valor de p "
                             "é otimista (tende a dar significativo com "
                             "facilidade). Trate como exploratório."))
            if self.paired_chk.isChecked():
                lines.append(tr("(A opção \"pareadas\" foi ignorada: janelas de "
                             "gravações diferentes não são pares.)"))
        else:
            lines = [tr("Comparação: {0} ({1} sessões) × {2} ({3} sessões), por banda de potência "
                        "média.").format(nameA, len(powA), nameB, len(powB))]
        if sig:
            lines.append(tr("Bandas com diferença significativa (após correção de "
                         "múltiplas comparações, Holm): ") + ", ".join(sig) + ".")
        else:
            lines.append(tr("Nenhuma banda apresentou diferença significativa após a "
                         "correção de múltiplas comparações."))
        for band, r in results:
            lines.append(f"• {band}: {interpret_result(r)}")
        self.summary.setPlainText("\n".join(lines))
        return self._rows

    def _save(self):
        """Pergunta onde salvar e dispara a escrita do relatório da comparação."""
        if not self._rows:
            QtWidgets.QMessageBox.information(
                self, tr("Nada a salvar"), tr("Rode a comparação primeiro."))
            return
        start = getattr(self.main.config, "save_directory", "")
        path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Salvar relatório"),
            os.path.join(start, "estatistica_guiada.html"), "HTML (*.html)")
        if not path:
            return
        self._write_report(path)
        QtWidgets.QMessageBox.information(self, tr("Salvo"), tr("Relatório salvo:\n{0}").format(path))

    def _write_report(self, path):
        """Gera o relatório final em HTML e um CSV irmão com a mesma tabela.

        O CSV é escrito no mesmo caminho com a extensão trocada, sem perguntar
        nada ao usuário. O escape do resumo trata apenas & e <, então conteúdo
        com aspas ou > entra cru no HTML.
        """
        csv_path = os.path.splitext(path)[0] + ".csv"
        # relatório = feito para abrir na planilha, então segue o decimal da
        # máquina (ver escreve_csv_planilha)
        escreve_csv_planilha(csv_path, self.COLS,
                             [[r[k] for k in self.COLS] for r in self._rows])
        nameA = self.name_A.text().strip() or "A"
        nameB = self.name_B.text().strip() or "B"
        rows_html = "".join(
            "<tr>" + "".join(f"<td>{r[k]}</td>" for k in self.COLS) + "</tr>"
            for r in self._rows)
        summ = self.summary.toPlainText().replace("&", "&amp;").replace(
            "<", "&lt;").replace("\n", "<br>")
        html = (
            "<!doctype html><html><head><meta charset='utf-8'>"
            f"<title>Estatística guiada — {APP_NAME}</title><style>"
            "body{font-family:Arial,sans-serif;margin:24px;color:#1a2230}"
            "table{border-collapse:collapse;width:100%;font-size:14px}"
            "th,td{border:1px solid #dbe1ea;padding:6px 10px;text-align:left}"
            "th{background:#eef4f1;color:#0c7f5f}h1{color:#0f9d75;font-size:20px}"
            "</style></head><body><h1>Relatório de Estatística Guiada</h1>"
            f"<p>{APP_NAME} v{APP_VERSION} — {APP_AUTHORS}</p>"
            "<table><thead><tr>"
            f"<th>Banda</th><th>{nameA}</th><th>{nameB}</th><th>Teste</th>"
            "<th>p</th><th>p (Holm)</th><th>Efeito</th><th>Signif.?</th>"
            f"</tr></thead><tbody>{rows_html}</tbody></table>"
            f"<h3>Conclusão</h3><p>{summ}</p>"
            f"<p style='color:#5b6473;font-size:12px'>Gerado por {APP_NAME} "
            f"v{APP_VERSION} — {CODE_URL}</p></body></html>")
        with open(path, "w", encoding="utf-8") as f:
            f.write(html)
        return csv_path


# ============================================================
# IntraSessionStatsDialog — comparar CONDIÇÕES dentro de uma sessão (genérico)
# ============================================================
class IntraSessionStatsDialog(QtWidgets.QDialog):
    """Facilitador GENÉRICO e MULTIMODAL: compara as condições/classes presentes
    em UMA sessão — sejam quais forem (dorsi/plantar, mãos, ou o que o usuário
    marcar) — por uma métrica que o próprio usuário escolhe (potência de banda
    para EEG, RMS para EMG/ECG, ou ERD% vs repouso). Não assume nenhum movimento."""

    METRICS = [("band", "Potência de banda (EEG)"),
               ("rms", "RMS / amplitude (qualquer sinal)"),
               ("erd", "ERD% vs repouso (EEG)")]

    def __init__(self, main, session=None):
        """Monta a janela que compara as condições marcadas dentro de UMA sessão,
        com seletores de métrica, banda e canal.

        Aceita uma sessão já carregada pelo chamador no parâmetro session; se
        ela não vier, a janela abre vazia esperando o botão "Carregar sessão…".
        """
        super().__init__(main)
        self.main = main
        self.d = None
        self._last = None
        self.setWindowTitle(tr("Comparar condições da sessão (genérico/multimodal)"))
        self.resize(840, 580)
        v = QtWidgets.QVBoxLayout(self)
        intro = QtWidgets.QLabel(
            tr("Compara as <b>condições/classes marcadas nesta sessão</b> — sejam "
            "quais forem — pela métrica que você escolher. Genérico e multimodal: "
            "ajuste métrica/banda/canais ao seu caso (EEG, EMG, ECG, EoG). O teste "
            "estatístico é escolhido automaticamente."))
        intro.setWordWrap(True); intro.setTextFormat(QtCore.Qt.TextFormat.RichText)
        v.addWidget(intro)
        row0 = QtWidgets.QHBoxLayout()
        self.sess_lbl = QtWidgets.QLabel(tr("(nenhuma sessão carregada)"))
        load_btn = QtWidgets.QPushButton(tr("Carregar sessão…"))
        load_btn.clicked.connect(self._load)
        row0.addWidget(self.sess_lbl, 1); row0.addWidget(load_btn)
        v.addLayout(row0)
        rowm = QtWidgets.QHBoxLayout()
        rowm.addWidget(QtWidgets.QLabel(tr("Métrica:")))
        self.metric_combo = QtWidgets.QComboBox()
        for key, lbl in self.METRICS:
            self.metric_combo.addItem(tr(lbl), key)
        rowm.addWidget(self.metric_combo)
        rowm.addWidget(QtWidgets.QLabel(tr("Banda:")))
        self.band_combo = QtWidgets.QComboBox()
        for b in EEG_BANDS:
            self.band_combo.addItem(b)
        rowm.addWidget(self.band_combo)
        rowm.addWidget(QtWidgets.QLabel(tr("Canais:")))
        self.chan_combo = QtWidgets.QComboBox()
        self.chan_combo.addItem(tr("Todos (média)"))
        rowm.addWidget(self.chan_combo, 1)
        v.addLayout(rowm)
        run = QtWidgets.QPushButton(tr("Comparar"))
        run.clicked.connect(self._compute)
        v.addWidget(run)
        self.table = QtWidgets.QTableWidget(0, 4)
        self.table.setHorizontalHeaderLabels([tr("Condição"), tr("n"), tr("Média ± DP"), tr("Mediana")])
        self.table.horizontalHeader().setStretchLastSection(True)
        v.addWidget(self.table, 1)
        self.summary = QtWidgets.QTextEdit(); self.summary.setReadOnly(True)
        self.summary.setMaximumHeight(150)
        v.addWidget(self.summary)
        save = QtWidgets.QPushButton(tr("Salvar relatório (HTML + CSV)…"))
        save.clicked.connect(self._save)
        v.addWidget(save)
        if session:
            self.set_session(session)

    def set_session(self, d):
        """Adota um dicionário de sessão já carregado, repovoando o seletor de
        canais e o rótulo de resumo.

        O item de índice 0 do combo é sempre "Todos (média)"; os canais reais
        começam em 1, e _chan_idx depende dessa convenção.
        """
        self.d = d
        self.chan_combo.clear(); self.chan_combo.addItem(tr("Todos (média)"))
        for nm in d.get("ch_names", []):
            self.chan_combo.addItem(nm)
        dur = d["eeg"].shape[1] / d["sr"] if d.get("sr") else 0
        self.sess_lbl.setText(
            tr("{0} canais · {1:.0f}s · {2} eventos · {3} marcadores").format(d['eeg'].shape[0], dur, len(d.get('trials', [])), len(d.get('markers', []))))

    def _load(self):
        """Abre o diálogo de arquivo e carrega um data.csv como sessão corrente da
        janela."""
        start = getattr(self.main.config, "save_directory", "")
        path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Abrir sessão (data.csv)"), start, "CSV (*.csv)")
        if not path:
            return
        d = self.main._load_session_csv(path)
        if d:
            self.set_session(d)

    def _chan_idx(self):
        """Traduz a escolha do combo de canais na lista de índices de linha do
        array de EEG.

        O índice 0 ("Todos (média)") devolve todos os canais; os demais são
        deslocados de 1 e saturados no último canal existente, para não
        estourar quando o combo ficar dessincronizado da sessão.
        """
        i = self.chan_combo.currentIndex()
        n = self.d["eeg"].shape[0]
        if i <= 0:
            return list(range(n))
        return [min(i - 1, n - 1)]

    def _bandpower(self, seg, sr, lo, hi):
        """Calcula a potência de um segmento numa faixa de frequência, base das
        métricas "band" e "erd".

        Integra a PSD de Welch (nperseg limitado a 256) e devolve a média entre
        os canais do segmento recebido.
        """
        vals = []
        for i in range(seg.shape[0]):
            f, psd = scipy_signal.welch(seg[i], fs=sr, nperseg=min(256, seg.shape[1]))
            m = (f >= lo) & (f < hi)
            vals.append(float(_TRAPEZOID(psd[m], f[m])) if np.any(m) else 0.0)
        return float(np.mean(vals)) if vals else 0.0

    def _conditions(self):
        """Genérico: {rótulo: [valor por trial/segmento]} + fonte. Usa trials
        (Event Id/Class Id) se houver; senão segmenta por marcadores."""
        d = self.d; eeg = d["eeg"]; sr = d["sr"]; N = eeg.shape[1]
        chans = self._chan_idx()
        metric = self.metric_combo.currentData()
        band = self.band_combo.currentText()
        lo, hi = EEG_BANDS_CATALOGO.get(band, EEG_BANDS_CATALOGO['Alpha'])
        base_phases = getattr(self.main, "BASELINE_PHASES",
                              ("baseline", "pre_rest", "inter_baseline"))

        def seg_of(s0, s1):
            """Recorta o trecho de EEG dos canais selecionados entre duas
            amostras.

            Devolve None para trechos com menos de 16 amostras — curtos demais
            para a PSD —, e o chamador apenas pula esses trials em silêncio.
            """
            s0 = max(0, int(s0)); s1 = min(N, int(s1))
            return eeg[np.ix_(chans, range(s0, s1))] if s1 - s0 >= 16 else None

        def value(seg, base_seg=None):
            """Converte um segmento no número que representa aquela condição,
            conforme a métrica escolhida no combo.

            Em "rms" a banda selecionada é ignorada. Em "erd" o retorno é
            percentual relativo à baseline ((bp-base)/base*100) e vira NaN se
            não houver segmento de baseline ou se a potência da baseline for
            zero.
            """
            if metric == "rms":
                return float(np.mean([np.sqrt(np.mean(seg[i] ** 2))
                                      for i in range(seg.shape[0])]))
            bp = self._bandpower(seg, sr, lo, hi)
            if metric == "erd":
                if base_seg is None:
                    return float("nan")
                bb = self._bandpower(base_seg, sr, lo, hi)
                return (bp - bb) / bb * 100.0 if bb > 0 else float("nan")
            return bp

        out = {}
        trials = [t for t in d.get("trials", []) if t.get("phase") == "mi"]
        if trials:
            base_trials = [t for t in d.get("trials", [])
                           if t.get("phase") in base_phases]
            for t in trials:
                seg = seg_of(t.get("start_line", 1) - 2, t.get("end_line", 1) - 1)
                if seg is None:
                    continue
                bseg = None
                if metric == "erd" and base_trials:
                    prev = [b for b in base_trials
                            if b.get("start_line", 0) <= t.get("start_line", 0)]
                    bt = prev[-1] if prev else base_trials[0]
                    bseg = seg_of(bt.get("start_line", 1) - 2,
                                  bt.get("end_line", 1) - 1)
                val = value(seg, bseg)
                if val is not None and np.isfinite(val):
                    cid = t.get("class_id", -1)
                    label = (t.get("class_name")
                             or (f"classe {cid}" if cid >= 0 else "MI"))
                    out.setdefault(str(label), []).append(val)
            # Adiciona REPOUSO como condição (permite comparar mesmo com 1 só
            # classe: "houve efeito vs repouso?"). ERD já é relativo à baseline,
            # então não entra como grupo.
            if metric != "erd":
                for b in base_trials:
                    seg = seg_of(b.get("start_line", 1) - 2, b.get("end_line", 1) - 1)
                    if seg is None:
                        continue
                    val = value(seg, None)
                    if val is not None and np.isfinite(val):
                        out.setdefault(tr("Repouso"), []).append(val)
            return out, "classes + repouso (Event Id)"
        # Fallback genérico: condições por marcadores (formato nativo)
        markers = d.get("markers", [])
        if markers:
            for i, (ts, lab) in enumerate(markers):
                t_next = markers[i + 1][0] if i + 1 < len(markers) else ts + 5.0
                seg = seg_of(ts * sr, min(t_next, ts + 5.0) * sr)
                if seg is None:
                    continue
                val = value(seg, seg if metric == "erd" else None)
                if val is not None and np.isfinite(val):
                    out.setdefault(str(lab), []).append(val)
            return out, "marcadores"
        return {}, "—"

    def _compute(self):
        """Extrai as condições da sessão, roda o teste automático entre elas e
        preenche a tabela e a conclusão.

        Exige pelo menos 2 condições distintas, senão avisa e desiste. O
        resultado fica em self._last, que é exatamente o que _save escreve no
        relatório.
        """
        if not self.d:
            QtWidgets.QMessageBox.warning(self, tr("Sessão"),
                                         tr("Carregue uma sessão primeiro."))
            return None
        groups, source = self._conditions()
        groups = {k: vv for k, vv in groups.items() if len(vv) >= 1}
        if len(groups) < 2:
            QtWidgets.QMessageBox.information(
                self, tr("Condições insuficientes"),
                tr("Não encontrei pelo menos 2 condições/classes nesta sessão. Use "
                "uma sessão com eventos/marcadores (ou compare grupos de sessões "
                "em 'Estatística guiada')."))
            return None
        names = list(groups.keys()); vals = [groups[k] for k in names]
        r = auto_compare(vals, names)
        self.table.setRowCount(len(names))
        rows = []
        for i, nm in enumerate(names):
            dsc = r["descr"][i]
            cells = [nm, str(dsc["n"]),
                     f"{dsc['mean']:.3g} ± {dsc['sd']:.2g}",
                     f"{dsc['median']:.3g}"]
            for j, c in enumerate(cells):
                self.table.setItem(i, j, QtWidgets.QTableWidgetItem(c))
            rows.append(cells)
        self.table.resizeColumnsToContents()
        metric_lbl = tr(dict(self.METRICS)[self.metric_combo.currentData()])
        band_txt = (f" ({self.band_combo.currentText()})"
                    if self.metric_combo.currentData() != "rms" else "")
        head = (tr("Métrica: {0}{1}  |  Canais: {2}  |  Condições de: {3}").format(metric_lbl, band_txt, self.chan_combo.currentText(), source))
        concl = interpret_result(r)
        self.summary.setPlainText(head + "\n\n" + concl)
        self._last = {"rows": rows, "head": head, "concl": concl}
        return self._last

    def _save(self):
        """Salva a comparação de condições como HTML mais um CSV com as
        descritivas por condição.

        O CSV vai para o mesmo caminho com a extensão trocada. Só funciona
        depois de _compute, pois lê self._last.
        """
        if not self._last:
            QtWidgets.QMessageBox.information(self, tr("Nada a salvar"),
                                             tr("Rode a comparação primeiro."))
            return
        start = getattr(self.main.config, "save_directory", "")
        path, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Salvar relatório"),
            os.path.join(start, "comparacao_condicoes.html"), "HTML (*.html)")
        if not path:
            return
        import csv as _csv
        csv_path = os.path.splitext(path)[0] + ".csv"
        with open(csv_path, "w", newline="", encoding="utf-8") as f:
            w = _csv.writer(f); w.writerow(["condicao", "n", "media_dp", "mediana"])
            for r in self._last["rows"]:
                w.writerow(r)
        rows_html = "".join(
            "<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>"
            for r in self._last["rows"])
        summ = (self._last["head"] + "\n\n" + self._last["concl"]).replace(
            "&", "&amp;").replace("<", "&lt;").replace("\n", "<br>")
        html = (
            "<!doctype html><html><head><meta charset='utf-8'>"
            f"<title>Comparação de condições — {APP_NAME}</title><style>"
            "body{font-family:Arial,sans-serif;margin:24px;color:#1a2230}"
            "table{border-collapse:collapse;width:100%;font-size:14px}"
            "th,td{border:1px solid #dbe1ea;padding:6px 10px;text-align:left}"
            "th{background:#eef4f1;color:#0c7f5f}h1{color:#0f9d75;font-size:20px}"
            "</style></head><body><h1>Comparação de condições da sessão</h1>"
            f"<p>{APP_NAME} v{APP_VERSION} — {APP_AUTHORS}</p>"
            "<table><thead><tr><th>Condição</th><th>n</th><th>Média ± DP</th>"
            f"<th>Mediana</th></tr></thead><tbody>{rows_html}</tbody></table>"
            f"<h3>Conclusão</h3><p>{summ}</p>"
            f"<p style='color:#5b6473;font-size:12px'>Gerado por {APP_NAME} "
            f"v{APP_VERSION} — {CODE_URL}</p></body></html>")
        with open(path, "w", encoding="utf-8") as f:
            f.write(html)
        QtWidgets.QMessageBox.information(self, tr("Salvo"), tr("Relatório salvo:\n{0}").format(path))


# ============================================================
# SerialReaderThread — Hardware/Simulação/Playback com suporte a expansão 16ch
# ============================================================
class _Marcapasso:
    """Mantém uma cadência fixa (ex.: 250 Hz) apesar do sono impreciso do SO.

    `time.sleep(dt)` NUNCA acorda antes do prazo e quase sempre acorda depois.
    Dormindo dt a cada volta, o atraso ACUMULA: medido nesta máquina, um laço
    pedindo 3,80 ms rodava a 4,12 ms — 243 Hz em vez de 250, sem consumidor
    nenhum. Era esse o "buraco" que aparecia como perda de amostras no Modo
    Simulação.

    A correção é contar por PRAZO ABSOLUTO: cada volta mira `inicio + n·dt`,
    então um atraso pontual é absorvido na volta seguinte em vez de somar. O
    último trecho é esperado sem dormir, porque abaixo de ~1 ms o sono do
    Windows não tem resolução — é pouco tempo de CPU e é o que garante a
    cadência.
    """

    # abaixo disto o sono do SO não ajuda; esperamos acordados
    LIMIAR_GIRO = 0.0012          # s

    def __init__(self, periodo_s, limite_atraso_s=0.25):
        """Arma a cadência com o período pedido (ex.: 1/250 para 250 Hz)."""
        self.dt = float(periodo_s)
        self.prox = time.perf_counter() + self.dt
        self.atrasos = 0          # voltas em que já estávamos atrasados
        # atraso que ainda se recupera em sequência; acima dele, reancora
        self.limite = float(limite_atraso_s)
        # prazos que a reancoragem pulou (na simulação: amostras que nunca
        # chegam a existir, e portanto perda de verdade)
        self.puladas = 0

    def espera(self):
        """Segura a execução até o próximo prazo. Devolve o instante alvo."""
        alvo = self.prox
        resto = alvo - time.perf_counter()
        if resto > self.LIMIAR_GIRO:
            time.sleep(resto - self.LIMIAR_GIRO)
        while time.perf_counter() < alvo:
            pass
        self.prox = alvo + self.dt
        # Se ficamos MUITO para trás (pausa do SO, swap, janela arrastada), não
        # tenta recuperar disparando uma rajada: reancora no presente. Perder a
        # cadência por um instante é melhor que despejar 200 amostras de uma vez
        # com carimbos de tempo amontoados.
        agora = time.perf_counter()
        if self.prox < agora - self.limite:
            self.puladas += int((agora - self.prox) / self.dt) + 1
            self.prox = agora + self.dt
            self.atrasos += 1
        return alvo



class GeradorSimulado:
    """Sinal sintetico POR TIPO DE CANAL, uma amostra por chamada.

    Antes todo canal recebia as mesmas tres senoides (10, 20 e 6 Hz) com uma
    fase diferente. Media: a topografia usava 4% da escala de cor, a aba
    Musculos nao via contracao nenhuma (0% das amostras acima do limiar), a aba
    Coracao lia as cristas das senoides como picos R e anunciava 196 bpm com
    HRV de aparencia clinica, a aba Olhos nao via piscada e a conectividade
    dava 0,69 em TODOS os pares.

    Tudo o que e' caro (QRS, piscada, sacada) sai de tabela pre-calculada; o
    resto e' vetorizado sobre os canais. Semente fixa: repetivel.
    """

    SEMENTE = 20260920

    def __init__(self, n, tipos, mapa, fs, t0=0.0):
        self.n = int(n)
        self.fs = float(fs)
        self.dt = 1.0 / self.fs
        self.t = float(t0)
        self.rng = np.random.default_rng(self.SEMENTE)
        tipos = list(tipos or ["EEG"] * self.n)[: self.n]
        tipos += ["EEG"] * (self.n - len(tipos))
        mapa = list(mapa or [])
        idx = lambda alvo: np.array(
            [i for i, x in enumerate(tipos) if x == alvo], dtype=int)
        self.i_eeg, self.i_emg = idx("EEG"), idx("EMG")
        self.i_ecg, self.i_eog = idx("ECG"), idx("EoG")
        self.i_off = idx("off")
        self.amostra = np.zeros(self.n)

        # ---- EEG: ganho por POSICAO do eletrodo (e' isso que da topografia) --
        k = len(self.i_eeg)
        xy = np.array([ALL_ELECTRODES.get(mapa[i] if i < len(mapa) else "",
                                          (0.0, 0.0)) for i in self.i_eeg],
                      dtype=float).reshape(-1, 2)
        x, y = (xy[:, 0], xy[:, 1]) if k else (np.zeros(0), np.zeros(0))
        self.g_alfa = 12.0 + 26.0 * (0.5 - y / 2.0)     # alfa forte occipital
        self.g_teta = 6.0 + 14.0 * (0.5 + y / 2.0)      # teta forte frontal
        self.g_beta = 4.0 + 6.0 * (1.0 - np.abs(y))     # beta central
        self.lado = np.sign(x)                          # -1 esq, +1 dir
        self.ph = (self.i_eeg * 0.7) if k else np.zeros(0)
        self.ruido_eeg = np.zeros(k)

        # ---- EMG: surtos de contracao e queda de MDF com a fadiga ----
        m = len(self.i_emg)
        self.emg_amp = (120.0 + 60.0 * ((self.i_emg % 4) / 3.0)) if m else np.zeros(0)
        # o ATRASO por canal e' o que da contraste a co-contracao e ao joystick
        self.emg_atraso = ((self.i_emg % 4) * 0.30) if m else np.zeros(0)
        self.emg_lp = np.zeros(m)
        self.emg_k = 0.6
        self._prox_k = self.t

        # ---- ECG: tabela PQRST (soma de 5 gaussianas), 1024 pontos ----
        self.ecg_tab = self._tabela_ecg(1024)
        self.ecg_fase = 0.0
        self.ecg_rr = 0.85
        # derivacoes pares e impares com ganho oposto: nao saem identicas
        self.ecg_gan = (np.where((self.i_ecg % 2) == 0, 600.0, -340.0)
                        if len(self.i_ecg) else np.zeros(0))

        # ---- EoG: tabelas de piscada e de sacada ----
        self.eog_pisc = self._tabela_piscada(max(2, int(0.30 * self.fs)))
        self.eog_ramp = self._tabela_sacada(max(2, int(0.06 * self.fs)))
        self.eog_i_pisc = -1
        self.eog_prox_pisc = self.t + 2.0
        self.eog_i_sac = -1
        self.eog_prox_sac = self.t + 1.5
        self.eog_alvo = 0.0
        self.eog_de = 0.0
        self.eog_pos = 0.0
        self.eog_deriva = 0.0
        # canal EoG de indice par = horizontal, impar = vertical
        self.eog_h = np.array([j for j in range(len(self.i_eog)) if j % 2 == 0],
                              dtype=int)
        self.eog_v = np.array([j for j in range(len(self.i_eog)) if j % 2 == 1],
                              dtype=int)

        self.accel = np.zeros(3)

    # ------------------------------------------------------------- tabelas
    @staticmethod
    def _tabela_ecg(n):
        """Complexo PQRST normalizado (pico R = 1,0) em n pontos."""
        f = np.linspace(0.0, 1.0, n, endpoint=False)
        def g(c, a, w):
            return a * np.exp(-0.5 * ((f - c) / w) ** 2)
        return (g(0.16, 0.12, 0.022) + g(0.26, -0.09, 0.006)
                + g(0.29, 1.00, 0.007) + g(0.32, -0.22, 0.008)
                + g(0.50, 0.28, 0.035))

    @staticmethod
    def _tabela_piscada(n):
        return np.sin(np.pi * np.linspace(0.0, 1.0, n)) ** 2

    @staticmethod
    def _tabela_sacada(n):
        return 0.5 - 0.5 * np.cos(np.pi * np.linspace(0.0, 1.0, n))

    # ------------------------------------------------------------- amostra
    def proxima(self):
        """Devolve (amostra de n canais, acelerometro de 3 eixos)."""
        t = self.t
        s = self.amostra
        rng = self.rng

        if len(self.i_eeg):
            env = 0.55 + 0.45 * np.sin(2 * np.pi * 0.1 * t)   # ciclo de 10 s
            erd = 0.5 * np.sin(2 * np.pi * t / 16.0)          # ERD/ERS de 16 s
            lat = 1.0 - 0.6 * erd * self.lado                 # alterna o lado
            self.ruido_eeg *= 0.92
            self.ruido_eeg += rng.normal(0.0, 3.0, len(self.i_eeg))
            s[self.i_eeg] = (
                self.g_alfa * env * lat * np.sin(2 * np.pi * 10.0 * t + self.ph)
                + self.g_teta * np.sin(2 * np.pi * 6.0 * t + 0.4 * self.ph)
                + self.g_beta * np.sin(2 * np.pi * 20.0 * t + 0.9 * self.ph)
                + self.ruido_eeg * 2.2)

        if len(self.i_emg):
            # ciclo de 4 s: 2 s de contracao com rampa de 200 ms
            fase = (t - self.emg_atraso) % 4.0
            ativ = np.clip(np.minimum(fase, 2.0 - fase) / 0.2, 0.0, 1.0)
            ativ = np.where(fase < 2.0, ativ, 0.0)
            if t >= self._prox_k:
                # o corte do portador cai de 110 para 55 Hz em 120 s: e' essa a
                # queda de MDF que a aba Fadiga mede (custa um exp a cada 0,5 s)
                self._prox_k = t + 0.5
                fcorte = 110.0 - 55.0 * (0.5 - 0.5 * np.cos(2 * np.pi * t / 120.0))
                self.emg_k = 1.0 - np.exp(-2 * np.pi * fcorte / self.fs)
            self.emg_lp += self.emg_k * (rng.normal(0.0, 1.0, len(self.i_emg))
                                         - self.emg_lp)
            s[self.i_emg] = (8.0 + self.emg_amp * ativ) * self.emg_lp

        if len(self.i_ecg):
            self.ecg_fase += self.dt / self.ecg_rr
            if self.ecg_fase >= 1.0:
                self.ecg_fase -= 1.0
                # 70 bpm com arritmia sinusal respiratoria discreta
                self.ecg_rr = 60.0 / (70.0 + 2.5 * np.sin(2 * np.pi * 0.25 * t))
            v = self.ecg_tab[min(1023, int(self.ecg_fase * 1024))]
            s[self.i_ecg] = self.ecg_gan * v + rng.normal(0.0, 6.0, len(self.i_ecg))

        if len(self.i_eog):
            if self.eog_i_pisc >= 0:
                p = self.eog_pisc[self.eog_i_pisc]
                self.eog_i_pisc += 1
                if self.eog_i_pisc >= len(self.eog_pisc):
                    self.eog_i_pisc = -1
            else:
                p = 0.0
                if t >= self.eog_prox_pisc:
                    self.eog_i_pisc = 0
                    self.eog_prox_pisc = t + 2.5 + 2.0 * rng.random()
            if self.eog_i_sac >= 0:
                self.eog_pos = (self.eog_de + (self.eog_alvo - self.eog_de)
                                * self.eog_ramp[self.eog_i_sac])
                self.eog_i_sac += 1
                if self.eog_i_sac >= len(self.eog_ramp):
                    self.eog_i_sac = -1
                    self.eog_pos = self.eog_alvo
            elif t >= self.eog_prox_sac:
                self.eog_de = self.eog_pos
                self.eog_alvo = float(rng.choice((-260.0, -120.0, 0.0,
                                                  120.0, 260.0)))
                self.eog_i_sac = 0
                self.eog_prox_sac = t + 1.2 + 1.6 * rng.random()
            self.eog_deriva = 0.995 * self.eog_deriva + rng.normal(0.0, 0.6)
            s[self.i_eog] = self.eog_deriva + rng.normal(0.0, 4.0, len(self.i_eog))
            if len(self.eog_h):
                s[self.i_eog[self.eog_h]] += self.eog_pos
            if len(self.eog_v):
                s[self.i_eog[self.eog_v]] += 240.0 * p + 0.25 * self.eog_pos

        if len(self.i_off):
            # canal desligado nao pode sair com 27 uV de EEG
            s[self.i_off] = rng.normal(0.0, 1.5, len(self.i_off))

        # acelerometro: 5 s parado, 3 s de movimento a ~1,8 Hz — sem isso a aba
        # Acel via so' um circulinho de 0,1 g e nao separava repouso de movimento
        mov = 1.0 if (t % 8.0) >= 5.0 else 0.0
        self.accel[0] = (0.02 * np.sin(2 * np.pi * 0.3 * t)
                         + mov * 0.35 * np.sin(2 * np.pi * 1.8 * t))
        self.accel[1] = (0.02 * np.cos(2 * np.pi * 0.3 * t)
                         + mov * 0.22 * np.sin(2 * np.pi * 1.8 * t + 1.0))
        self.accel[2] = (1.00 + 0.01 * np.sin(2 * np.pi * 2 * t)
                         + mov * 0.18 * np.sin(2 * np.pi * 3.6 * t))
        self.t = t + self.dt
        return s, self.accel


class SerialReaderThread(QThread):
    """QThread que alimenta o aplicativo com amostras, vindas da placa pela
    serial, do simulador interno ou do playback de um CSV gravado.

    Tudo roda fora do thread da GUI: a única comunicação com a interface são os
    Signals (data_received, error, connection_state, progress,
    expansion_detected) — não toque em widgets aqui dentro. SCALE_UV converte a
    contagem de 24 bits do ADS1299 (referência 4,5 V, ganho 24) em microvolts,
    e SCALE_ACCEL converte o acelerômetro em g.
    """
    # 3o argumento = instante da amostra em RELOGIO MONOTONICO
    # (time.perf_counter), carimbado NA ORIGEM. Antes o tempo era lido no
    # thread da GUI, com time.time(): amostras que chegavam em rajada
    # compartilhavam a mesma leitura (66% dos intervalos davam ZERO, o que
    # cegava a medicao de taxa) e um ajuste de relogio no meio da coleta
    # reescrevia o eixo do tempo do experimento.
    data_received    = Signal(np.ndarray, np.ndarray, float)
    # varias amostras de uma vez (k x n, k x 3, k carimbos): a simulacao
    # atrasada entrega assim o que venceu, com uma troca de GIL so'
    bloco_recebido   = Signal(np.ndarray, np.ndarray, np.ndarray)
    error            = Signal(str)
    connection_state = Signal(bool)
    progress         = Signal(float)
    expansion_detected = Signal(int)  # emite num de canais detectados (8 ou 16)

    SCALE_UV    = 4.5 / 24.0 / (2 ** 23 - 1) * 1_000_000.0
    SCALE_ACCEL = 0.002

    def __init__(self, port=None, baud_rate=115200, mode="hardware",
                 playback_path=None, daisy=False, num_channels=None, parent=None,
                 signal_types=None, channel_mapping=None):
        """Guarda o modo de operação e resolve quantos canais a thread vai
        produzir.

        Um num_channels explícito é limitado ao intervalo [BASE_CHANNELS,
        MAX_CHANNELS], para suportar as placas customizadas de 24 a 64 canais.
        Sem ele, cai no comportamento antigo de 8 ou 16 canais conforme o flag
        daisy, mantido por compatibilidade com chamadas legadas.
        """
        super().__init__(parent)
        self.port = port
        self.baud_rate = baud_rate
        self.mode = mode
        self.playback_path = playback_path
        self.daisy = bool(daisy)
        # Aceita override explícito de num_channels (para suportar 24/32/40/48/56/64
        # vindos da placa customizada). Se ausente, cai no comportamento legacy
        # 8 ou 16 baseado no flag `daisy` (compat com chamadas antigas).
        if num_channels is None:
            self.num_channels = CYTON_MAX_CHANNELS if self.daisy else BASE_CHANNELS
        else:
            self.num_channels = max(BASE_CHANNELS, min(MAX_CHANNELS, int(num_channels)))
        self._serial = None
        self._running = False
        self._daisy_upper = None   # buffer da metade "superior" (8ch) entre pacotes Cyton
        # Perda REAL, contada na fonte: _read_packet pelo numero de amostra e,
        # na simulacao, os prazos que o marcapasso pulou ao reancorar.
        self.perdidas = 0
        self._perd_pacotes = 0     # pacotes que faltaram (Daisy: 2 por amostra)
        self._ult_num = None       # ultimo numero de amostra visto (8 bits)
        # ressincronizacao: bytes devolvidos a' fila, estado e candidato a'
        # realinhamento (so' conta perda depois de 2 pacotes validos seguidos)
        self._buf = bytearray()
        self._ressinc = False
        self._cand = None
        # COPIA dos tipos e do mapeamento: a thread nunca pode ler self.config,
        # que a GUI altera a qualquer momento. None = tudo EEG (chamada legada).
        if signal_types:
            tipos = list(signal_types)[: self.num_channels]
            tipos += ["EEG"] * (self.num_channels - len(tipos))
            self.signal_types = tipos
        else:
            self.signal_types = None
        self.channel_mapping = list(channel_mapping) if channel_mapping else None
        self._tipos_novos = None   # a GUI deposita aqui uma troca de tipo

    def run(self):
        """Ponto de entrada do QThread: despacha para simulação, playback ou
        serial conforme o modo configurado.

        Qualquer modo diferente de "simulation" e "playback" cai no caminho
        serial.
        """
        if self.mode == "simulation":
            self._run_simulation()
        elif self.mode == "playback":
            self._run_playback()
        else:
            self._run_serial()

    def _run_simulation(self):
        """Gera sinal sintético POR TIPO DE CANAL (EEG, EMG, ECG, EoG, off)
        para exercitar o aplicativo sem placa conectada.

        Quem faz o sinal é GeradorSimulado; aqui só entra a cadência do
        _Marcapasso. As amplitudes já saem em microvolts. Trocar o tipo de um
        canal na aba Filtros e Canais vale na hora: a GUI deposita a lista nova
        em _tipos_novos e o gerador é refeito na volta seguinte, continuando do
        mesmo instante.
        """
        self.connection_state.emit(True)
        self._running = True
        dt = 1.0 / SAMPLE_RATE
        n = self.num_channels
        gerador = GeradorSimulado(n, self.signal_types, self.channel_mapping,
                                  SAMPLE_RATE)
        # Recupera ate 5 s de atraso gerando em sequencia, com o carimbo do
        # PRAZO de cada amostra. Reancorando a 250 ms, uma tela pesada (EMG
        # grande na escala de 100 uV) tomava o GIL e a gravacao saia a 51 Hz
        # sem nenhuma perda registrada.
        marcapasso = _Marcapasso(dt, limite_atraso_s=5.0)
        t_amostra = marcapasso.prox - dt
        lote = []
        while self._running:
            novos = self._tipos_novos
            if novos is not None:
                self._tipos_novos = None
                gerador = GeradorSimulado(n, novos, self.channel_mapping,
                                          SAMPLE_RATE, t0=gerador.t)
            sample, accel = gerador.proxima()
            # COPIA obrigatoria: o sinal Qt e' enfileirado entre threads e
            # guarda a referencia — o gerador reusa o mesmo vetor.
            lote.append((sample.copy(), accel.copy(), t_amostra))
            # Atrasado (o prazo seguinte ja venceu): junta no mesmo bloco.
            # Cada emit devolve o GIL para a tela; uma a uma, a tela pesada
            # deixava o gerador para tras de novo a cada amostra.
            if len(lote) < 64 and time.perf_counter() >= marcapasso.prox:
                t_amostra = marcapasso.espera()
                self.perdidas = marcapasso.puladas
                continue
            if len(lote) == 1:
                self.data_received.emit(*lote[0])
            else:
                self.bloco_recebido.emit(
                    np.array([x[0] for x in lote]),
                    np.array([x[1] for x in lote]),
                    np.array([x[2] for x in lote], dtype=float))
            lote = []
            t_amostra = marcapasso.espera()
            # o que a reancoragem pulou nunca foi gerado: e' perda de verdade
            self.perdidas = marcapasso.puladas
        self.connection_state.emit(False)

    def _run_playback(self):
        """Reproduz um CSV já gravado como se fosse aquisição ao vivo, emitindo
        amostra a amostra no mesmo ritmo do hardware.

        Lê o cabeçalho antes para carregar só as colunas numéricas: o data.csv
        nativo termina na coluna textual 'marker', que quebraria np.loadtxt
        mesmo vazia. O número de canais é inferido das colunas (timestamp + N +
        3 de acelerômetro, com e sem marker) e encaixado nos passos válidos de
        EXPANSION_STEPS; se diferir do configurado, emite expansion_detected e
        reconfigura a si mesmo. O progresso só é emitido a cada 64 amostras (i
        & 0x3F).
        """
        if not self.playback_path or not os.path.exists(self.playback_path):
            self.error.emit(tr("CSV de playback não encontrado: {0}").format(self.playback_path))
            return
        try:
            # Le o cabecalho para NAO tentar converter a coluna textual 'marker'
            # (data.csv nativo sempre termina em 'marker' -> np.loadtxt falharia
            #  ate quando os marcadores estao vazios). Espelha _load_native_session_csv.
            usecols = None
            try:
                with open(self.playback_path, "r", encoding="utf-8", errors="ignore") as _f:
                    header = next(csv.reader(_f))
                num_cols = [i for i, h in enumerate(header)
                            if h.strip().endswith("_uV")
                            or h.strip() in ("timestamp_s", "ax_g", "ay_g", "az_g")]
                if num_cols:
                    usecols = num_cols
            except Exception:
                usecols = None
            data = np.loadtxt(self.playback_path, delimiter=",", skiprows=1,
                              usecols=usecols, encoding="utf-8")
        except Exception as exc:
            self.error.emit(tr("Falha lendo CSV: {0}").format(exc))
            return
        if data.ndim == 1:
            data = data.reshape(1, -1)
        n_rows, n_cols = data.shape

        # Auto-detecção multi-step do número de canais a partir das colunas do CSV
        # Formato esperado: timestamp + N canais + ax + ay + az [+ marker]
        # Tenta encaixar nos passos válidos: 8, 16, 24, 32, 40, 48, 56, 64
        inferred = n_cols - 1 - 3  # remove timestamp + 3 accel; sem assumir marker
        detected = None
        for cand in (inferred, inferred - 1):  # tenta com e sem marker
            if cand in EXPANSION_STEPS:
                detected = cand; break
        if detected is None:
            # Snap ao passo mais próximo dentro do range válido
            if BASE_CHANNELS <= inferred <= MAX_CHANNELS:
                detected = min(EXPANSION_STEPS, key=lambda s: abs(s - inferred))
            else:
                detected = max(1, n_cols - 1)
        if detected != self.num_channels:
            self.num_channels = detected
            self.expansion_detected.emit(detected)

        self.connection_state.emit(True)
        self._running = True
        dt = 1.0 / SAMPLE_RATE
        marcapasso = _Marcapasso(dt)
        for i in range(n_rows):
            if not self._running: break
            row = data[i]
            if row.shape[0] >= 1 + detected:
                sample = row[1 : 1 + detected]
            else:
                sample = np.zeros(detected)
            if row.shape[0] >= 1 + detected + 3:
                accel = row[1 + detected : 1 + detected + 3]
            else:
                accel = np.zeros(3)
            self.data_received.emit(sample, accel, time.perf_counter())
            if (i & 0x3F) == 0:
                self.progress.emit((i + 1) / n_rows)
            marcapasso.espera()
        self.progress.emit(1.0)
        self._running = False
        self.connection_state.emit(False)

    def _run_serial(self):
        """Abre a porta serial, manda a placa começar a transmitir e fica lendo
        pacotes até stop().

        Espera 2 s depois de abrir a porta, tempo do reset do microcontrolador;
        se a expansão daisy estiver ligada envia "C" antes, e então "b" para
        iniciar o streaming. Erros durante a leitura viram o sinal error e
        encerram o laço; o finally sempre fecha a porta e avisa a GUI que caiu
        a conexão.
        """
        try:
            self._serial = serial.Serial(self.port, self.baud_rate, timeout=1.0)
            time.sleep(2.0)
            try:
                self._serial.reset_input_buffer()
                # Se expansão solicitada, manda o comando C antes de iniciar streaming
                if self.daisy:
                    self._serial.write(b"C")
                    time.sleep(0.4)
                    # A resposta de texto da placa ("...$$$") chegava depois
                    # do reset e entrava no fluxo como perda: espera por ela
                    # e descarta antes de iniciar.
                    fim = time.perf_counter() + 1.5
                    resp = b""
                    while time.perf_counter() < fim and b"$$$" not in resp:
                        pedaco = self._serial.read(max(1, int(self._serial.in_waiting or 0)))
                        if not pedaco:
                            break
                        resp += pedaco
                    self._serial.reset_input_buffer()
                self._serial.write(b"b")
            except Exception: pass
        except (serial.SerialException, OSError) as exc:
            self.error.emit(tr("Falha ao abrir {0}: {1}").format(self.port, exc))
            return
        self.connection_state.emit(True)
        self._running = True
        try:
            while self._running:
                packet = self._read_packet()
                if packet is not None:
                    sample, accel = packet
                    self.data_received.emit(sample, accel, time.perf_counter())
        except Exception as exc:
            self.error.emit(tr("Erro durante leitura: {0}").format(exc))
        finally:
            self._close_serial()
            self.connection_state.emit(False)

    def _le(self, n):
        # bytes devolvidos a' fila na ressincronizacao saem primeiro
        if self._buf:
            out = bytes(self._buf[:n])
            del self._buf[:n]
            if len(out) < n:
                out += self._serial.read(n - len(out))
            return out
        return self._serial.read(n)

    def _read_packet(self):
        """Le um pacote do protocolo. Em modo expansão, intercala dois pacotes para
        formar um sample de 16 canais."""
        head = self._le(1)
        if not head:
            return None
        if head[0] != 0xA0:
            # Fora de sincronia. NAO conta byte a byte: 20 bytes de texto da
            # placa viravam 20 "perdas" e um pacote truncado virava 17. A
            # perda sai do salto do numero de amostra depois de realinhar.
            self._ressinc = True
            return None
        payload = self._le(32)
        if len(payload) < 32 or not (0xC0 <= payload[31] <= 0xC6):
            # sem o byte de parada o 0xA0 era dado: devolve os bytes a' fila e
            # segue procurando logo depois dele
            self._buf[0:0] = payload
            self._ressinc = True
            return None
        num = payload[0]
        if self._ressinc:
            cand = self._cand
            if cand is None or num != (cand[0] + 1) % 256:
                # 1o pacote valido depois da perda: so' candidato. Um 0xA0 no
                # meio do payload com um 0xC0 32 bytes adiante dava um salto
                # de numero de ate' 255.
                self._cand = (num, payload)
                return None
            # dois validos seguidos: realinhado. O atual volta a' fila e sai o
            # candidato — nenhum dos dois se perde.
            self._buf[0:0] = b"\xA0" + payload
            num, payload = cand
            self._cand = None
            self._ressinc = False
        # O numero de amostra da placa e' de 8 bits e da a volta a cada 256:
        # aritmetica modular, senao a primeira volta viraria "perda de 255".
        if self._ult_num is not None:
            faltam = (num - self._ult_num - 1) % 256
            if faltam:
                self._perd_pacotes += faltam
                # na Daisy cada amostra de 16 canais sao 2 pacotes
                self.perdidas = ((self._perd_pacotes + 1) // 2 if self.daisy
                                 else self._perd_pacotes)
        self._ult_num = num
        # Decodifica 8 canais EEG
        eight = np.empty(BASE_CHANNELS)
        for ch in range(BASE_CHANNELS):
            base = 1 + ch * 3
            raw = (payload[base] << 16) | (payload[base + 1] << 8) | payload[base + 2]
            if raw & 0x800000:
                raw -= 1 << 24
            eight[ch] = raw * self.SCALE_UV
        # Acelerômetro
        accel = np.zeros(3)
        try:
            if payload[31] == 0xC0:
                for k in range(3):
                    raw = int.from_bytes(payload[25 + k*2 : 27 + k*2], "big", signed=True)
                    accel[k] = raw * self.SCALE_ACCEL
        except Exception: pass

        if not self.daisy:
            return eight, accel

        # Em modo expansão, intercala pacotes. Sample number byte = payload[0]
        # Convenção do protocolo: bit alto indica board "upper" vs "lower"
        sample_num = payload[0]
        is_upper = (sample_num & 0x01) == 0  # heurica: par = upper, impar = lower
        if is_upper:
            self._daisy_upper = eight
            return None  # ainda não temos o par
        else:
            if self._daisy_upper is None:
                return None
            sixteen = np.concatenate([self._daisy_upper, eight])
            self._daisy_upper = None
            return sixteen, accel

    def send_command(self, cmd):
        """Envia um caractere de comando para o firmware da placa pela serial já
        aberta.

        Devolve False se a porta estiver fechada ou se a escrita falhar — o
        erro não é propagado nem sinalizado.
        """
        if self._serial and self._serial.is_open:
            try:
                self._serial.write(cmd.encode("ascii"))
                return True
            except Exception:
                return False
        return False

    def _close_serial(self):
        """Encerra a sessão com a placa mandando o comando de parada e fechando a
        porta.

        Envia "s" antes de fechar para interromper o streaming. As exceções são
        engolidas de propósito, porque isto roda no finally do laço de leitura
        e não pode mascarar o erro original.
        """
        if self._serial and self._serial.is_open:
            try: self._serial.write(b"s")
            except: pass
            try: self._serial.close()
            except: pass
        self._serial = None

    def stop(self):
        """Sinaliza o fim do laço de aquisição e espera a thread terminar.

        Bloqueia quem chama por até 2500 ms no wait(); como é acionado pela
        GUI, esse é o teto de congelamento da interface ao parar a coleta.
        """
        self._running = False
        self.wait(2500)


# ============================================================
# Leitor EDF/BDF TOLERANTE (numpy puro) — lê exames clínicos mesmo com
# cabeçalho quebrado (ex.: iCelera com acento no nome do paciente, que faz
# EDFbrowser/pyedflib recusarem o arquivo inteiro). Só lê os campos NUMÉRICOS
# do header; ignora textos não-ASCII. Não depende de pyedflib (funciona no .exe).
# Especificação EDF: https://www.edfplus.info/specs/edf.html
# ============================================================
def _parse_edf_tals(block):
    """Parseia TALs (anotações EDF+) de um bloco de bytes de um registro.
    Retorna [(onset_s, duration_s, texto)]. Ignora o TAL de cronometragem."""
    out = []
    for tal in bytes(block).split(b"\x00"):
        if b"\x14" not in tal:
            continue
        head, _sep, rest = tal.partition(b"\x14")
        on_b, _s2, dur_b = head.partition(b"\x15")
        on_s = on_b.decode("ascii", "ignore").strip()
        if not on_s or on_s[0] not in "+-":
            continue
        try:
            onset = float(on_s)
        except ValueError:
            continue
        try:
            dur = float(dur_b.decode("ascii", "ignore").strip()) if dur_b else 0.0
        except ValueError:
            dur = 0.0
        for t in rest.split(b"\x14"):
            txt = t.decode("utf-8", "replace").strip()
            if txt:
                out.append((onset, dur, txt))
    return out


def _detect_trigger_events(sig, fs, label, min_gap_s=0.05):
    """Detecta bordas de SUBIDA num canal de gatilho (ex.: 'Foto estimulo' do
    iCelera). Retorna [(onset_s, label)]."""
    sig = np.asarray(sig, dtype=float)
    sig = sig[np.isfinite(sig)]
    if sig.size < 2 or fs <= 0:
        return []
    # min/max (não percentil): o gatilho costuma ser esparso (<5% das amostras),
    # então percentil 5/95 colapsaria. Só roda em canais já rotulados como gatilho.
    lo, hi = float(np.min(sig)), float(np.max(sig))
    if hi - lo < 1e-9:                          # canal plano (sem estímulo)
        return []
    thr = lo + 0.5 * (hi - lo)
    above = sig > thr
    rising = np.where((~above[:-1]) & (above[1:]))[0] + 1
    out, last = [], -1e9
    lbl = str(label).strip() or "trigger"
    for idx in rising:
        t = idx / float(fs)
        if t - last >= min_gap_s:
            out.append((t, lbl))
            last = t
    return out


def read_edf(path):
    """Lê um EDF/BDF de forma tolerante. Retorna dict com labels, signals
    (µV físicos), fs por canal, etc. Ignora o campo de texto do paciente."""
    with open(path, "rb") as f:
        raw = f.read()
    if len(raw) < 256:
        raise ValueError("Arquivo muito curto para ser EDF/BDF.")
    H = raw[:256]

    def _num(b, default="0"):
        """Extrai um campo numérico ASCII do cabeçalho EDF descartando bytes que
        não sejam ASCII.

        É esse descarte que permite abrir exames recusados por EDFbrowser e
        pyedflib, como os do iCelera com acento no nome do paciente. Devolve
        string (o default quando o campo está vazio), então quem chama ainda
        precisa converter para int ou float.
        """
        s = b.decode("ascii", "ignore").strip()
        return s or default

    try:
        ns = int(_num(H[252:256]))
    except ValueError:
        raise ValueError("Cabeçalho EDF inválido (nº de sinais).")
    if ns <= 0 or ns > 2048:
        raise ValueError(f"Nº de sinais fora do esperado: {ns}")
    n_records = int(_num(H[236:244], "-1"))
    rec_dur = float(_num(H[244:252], "1")) or 1.0
    reserved = H[192:236].decode("ascii", "replace").upper()
    is_bdf = (raw[:1] == b"\xff") or ("BDF" in reserved) or path.lower().endswith(".bdf")
    # data/hora de início (para sincronizar com marcadores por relógio)
    start_epoch = None
    try:
        sd = H[168:176].decode("ascii", "ignore").strip()   # dd.mm.yy
        stt = H[176:184].decode("ascii", "ignore").strip()  # hh.mm.ss
        dd, mo, yy = (int(x) for x in re.split(r"[.:]", sd)[:3])
        hh, mi, ss = (int(x) for x in re.split(r"[.:]", stt)[:3])
        yy = 2000 + yy if yy < 85 else 1900 + yy
        start_epoch = datetime(yy, mo, dd, hh, mi, ss).timestamp()
    except Exception:
        start_epoch = None

    p = [256]
    def field(size):
        """Fatia o próximo campo por sinal do cabeçalho EDF e avança o cursor de
        leitura.

        O cursor mora em p[0] — uma lista de um elemento só para a closure
        poder alterá-lo. A ordem das chamadas tem que espelhar exatamente o
        layout do EDF: pular um campo desalinha todos os seguintes, e é por
        isso que existem chamadas field(80) e field(32) cujo retorno é
        descartado.
        """
        chunk = raw[p[0]:p[0] + size * ns]; p[0] += size * ns
        return [chunk[i * size:(i + 1) * size] for i in range(ns)]

    labels   = [x.decode("ascii", "replace").strip() for x in field(16)]
    field(80)                                       # transducer
    phys_dim = [x.decode("ascii", "replace").strip() for x in field(8)]
    phys_min = [float(_num(x)) for x in field(8)]
    phys_max = [float(_num(x)) for x in field(8)]
    dig_min  = [float(_num(x)) for x in field(8)]
    dig_max  = [float(_num(x)) for x in field(8)]
    field(80)                                       # prefiltering
    nsamp    = [int(_num(x)) for x in field(8)]     # amostras por registro
    field(32)                                       # reserved por sinal

    bps = 3 if is_bdf else 2
    data_start = 256 + ns * 256
    rec_size = int(np.sum(nsamp)) * bps
    if n_records < 0 and rec_size:
        n_records = max(0, (len(raw) - data_start) // rec_size)
    sig_off = (np.concatenate([[0], np.cumsum(nsamp)]) * bps).astype(np.int64)
    sigs = [np.empty(nsamp[s] * n_records, dtype=np.float64) for s in range(ns)]
    for r in range(n_records):
        base = data_start + r * rec_size
        for s in range(ns):
            cnt = nsamp[s]
            if cnt == 0:
                continue
            st = base + int(sig_off[s])
            b = raw[st:st + cnt * bps]
            if len(b) < cnt * bps:
                cnt = len(b) // bps
                b = b[:cnt * bps]
            if is_bdf:
                a = np.frombuffer(b, np.uint8).reshape(-1, 3).astype(np.int32)
                v = a[:, 0] | (a[:, 1] << 8) | (a[:, 2] << 16)
                v = np.where(v >= (1 << 23), v - (1 << 24), v).astype(np.float64)
            else:
                v = np.frombuffer(b, "<i2").astype(np.float64)
            sigs[s][r * nsamp[s]: r * nsamp[s] + cnt] = v
    for s in range(ns):
        dmn, dmx, pmn, pmx = dig_min[s], dig_max[s], phys_min[s], phys_max[s]
        if dmx != dmn:
            sigs[s] = pmn + (sigs[s] - dmn) * (pmx - pmn) / (dmx - dmn)
    fs = [nsamp[s] / rec_dur if rec_dur else 0.0 for s in range(ns)]
    # anotações EDF+ (TALs do canal "EDF Annotations"), se houver
    annotations = []
    for s in range(ns):
        if "annotation" in labels[s].lower() and nsamp[s] > 0:
            for rr in range(n_records):
                st = data_start + rr * rec_size + int(sig_off[s])
                block = raw[st: st + nsamp[s] * bps]
                annotations.extend(_parse_edf_tals(block))
    annotations.sort(key=lambda x: x[0])
    return {"labels": labels, "signals": sigs, "fs": fs, "phys_dim": phys_dim,
            "n_records": n_records, "rec_dur": rec_dur, "is_bdf": is_bdf,
            "annotations": annotations, "start_epoch": start_epoch}


def _load_nano_markers(path):
    """Lê o *_markers.csv do Protocolo (iCelera Nano): fases/classes +
    onset_epoch_ms. Retorna lista de dicts."""
    out = []
    try:
        with open(path, encoding="utf-8") as f:
            for row in csv.DictReader(f):
                try:
                    out.append({
                        "phase": (row.get("phase") or "").strip(),
                        "class_name": (row.get("class_name") or "").strip(),
                        "class_id": int(row.get("class_id", -1) or -1),
                        "onset_ms": float(row.get("onset_epoch_ms", 0) or 0),
                        "offset_ms": float(row.get("offset_epoch_ms", 0) or 0),
                    })
                except Exception:
                    pass
    except Exception:
        pass
    return out


def _nano_protocol_events(markers, annotations, start_epoch, sync="auto"):
    """Mapeia os marcadores do protocolo (onset_epoch_ms) para o tempo do EDF.
    'clock' = relógio de início do EDF; 'markers' = 2 anotações do EDF ancoram
    sync_start/sync_end (corrige offset e deriva). Retorna [(onset_s, label)]."""
    if not markers:
        return []
    onsets = [m["onset_ms"] for m in markers if m["onset_ms"] > 0]
    if not onsets:
        return []
    ann_on = [a[0] for a in (annotations or [])]
    ss = next((m for m in markers if m["phase"] == "sync_start"), None)
    se = next((m for m in markers if m["phase"] == "sync_end"), None)
    a0_app = ss["onset_ms"] if ss else min(onsets)
    a1_app = se["onset_ms"] if se else max((m["offset_ms"] or m["onset_ms"])
                                           for m in markers)
    method = sync
    if method == "auto":
        method = "markers" if len(ann_on) >= 2 else "clock"
    if method == "markers" and len(ann_on) >= 2:
        a0e, a1e = float(min(ann_on)), float(max(ann_on))
        scale = (a1e - a0e) / max(1e-6, (a1_app - a0_app) / 1000.0)
        conv = lambda ms: a0e + (ms - a0_app) / 1000.0 * scale
    elif start_epoch is not None:
        conv = lambda ms: ms / 1000.0 - start_epoch
    else:
        base = min(onsets)
        conv = lambda ms: (ms - base) / 1000.0
    out = []
    for m in markers:
        if m["phase"] in ("sync_start", "sync_end"):
            continue
        out.append((conv(m["onset_ms"]),
                    m["class_name"] or m["phase"] or "evt"))
    return out


def edf_to_native_csv(edf_path, out_csv, max_seconds=None, markers_csv=None,
                      sync="auto"):
    """Converte um EDF/BDF para o CSV NATIVO do ROA (time_s,<ch>_uV,...)
    para abrir direto no modo Offline. Mapeia canais pelo NOME (multi-placa),
    descarta não-EEG e extrai eventos (anotações EDF+ / gatilho). Se markers_csv
    (iCelera Nano) for dado, sincroniza e adiciona os eventos do protocolo.
    Retorna (out_csv, labels, fs, n)."""
    r = read_edf(edf_path)
    types = [classify_channel(l) for l in r["labels"]]
    def _valid(i):
        """Descarta canais do EDF sem taxa de amostragem ou sem nenhuma amostra."""
        return r["fs"][i] > 0 and len(r["signals"][i])
    # prioriza os canais EEG reconhecidos pelo NOME do eletrodo (multi-placa:
    # iCelera, etc.); se nenhum for reconhecido, cai p/ qualquer canal não-anotação
    # (placas com rótulos genéricos CH1..CHn).
    eeg_idx = [i for i in range(len(r["labels"])) if types[i] == "eeg" and _valid(i)]
    if eeg_idx:
        idxs = eeg_idx
    else:
        idxs = [i for i, l in enumerate(r["labels"])
                if "annotation" not in l.lower() and _valid(i)]
    if not idxs:
        raise ValueError("Nenhum canal de sinal válido encontrado no EDF.")
    # taxa de amostragem dominante (moda dos fs arredondados)
    fs_round = [int(round(r["fs"][i])) for i in idxs]
    fs = max(set(fs_round), key=fs_round.count)
    keep = [i for i in idxs if int(round(r["fs"][i])) == fs]
    # nome CANÔNICO do eletrodo (Fp1, T7…) quando reconhecido; senão o rótulo cru.
    # Assim a montagem/topografia mapeiam certo, independentemente da placa.
    labels = [canonical_electrode(r["labels"][i]) or (r["labels"][i] or f"CH{k+1}")
              for k, i in enumerate(keep)]
    n = min(len(r["signals"][i]) for i in keep)
    if max_seconds:
        n = min(n, int(max_seconds * fs))
    t = np.arange(n) / float(fs)
    mat = np.column_stack([r["signals"][i][:n] for i in keep])
    # --- eventos: anotações EDF+ + bordas de canais de gatilho -> coluna 'marker'
    ev = [(on, txt) for (on, _d, txt) in r.get("annotations", [])]
    for i in range(len(r["labels"])):
        if types[i] == "trigger" and _valid(i):
            ev += _detect_trigger_events(r["signals"][i], r["fs"][i], r["labels"][i])
    if markers_csv:                             # iCelera Nano: eventos do protocolo
        ev += _nano_protocol_events(_load_nano_markers(markers_csv),
                                    r.get("annotations", []),
                                    r.get("start_epoch"), sync)
    marker = [""] * n
    n_ev = 0
    for on, txt in ev:
        si = int(round(float(on) * fs))
        if 0 <= si < n and not marker[si]:
            marker[si] = str(txt).replace(",", ";").replace("\n", " ").strip()[:40]
            n_ev += 1
    header = "time_s," + ",".join(f"{l}_uV" for l in labels)
    # tempo com precisão fixa (senão a SR medida sai errada em exames longos);
    # sinais em 6 algarismos significativos (mais que suficiente p/ µV).
    fmt = ["%.6f"] + ["%.6g"] * len(labels)
    if n_ev:                                    # há eventos -> escreve coluna marker
        buf = io.StringIO()
        np.savetxt(buf, np.column_stack([t, mat]), delimiter=",", fmt=fmt)
        num_lines = buf.getvalue().split("\n")
        with open(out_csv, "w", encoding="utf-8", newline="") as f:
            f.write(header + ",marker\n")
            for k in range(n):
                f.write(num_lines[k] + "," + marker[k] + "\n")
    else:
        np.savetxt(out_csv, np.column_stack([t, mat]), delimiter=",",
                   header=header, comments="", fmt=fmt)
    return out_csv, labels, fs, n


# ============================================================
# ICA (FastICA) em numpy PURO — remove artefato ocular (piscada) sem depender
# do MNE nem de pip install. Funciona no .exe. Algoritmo FastICA simétrico
# (Hyvärinen 1999) com não-linearidade tanh.
# ============================================================
def _fast_ica_W(Xw, n_components, max_iter=250, tol=1e-5, seed=42):
    """FastICA simétrico sobre dados JÁ branqueados Xw (n_comp x n)."""
    n = Xw.shape[1]
    rng = np.random.RandomState(seed)
    def _sym(W):
        """Ortogonaliza a matriz de separação a cada iteração — a descorrelação
        simétrica que dá nome ao FastICA simétrico.

        Usa SVD (u @ vt) em vez da raiz quadrada inversa de W @ W.T, que é
        numericamente mais frágil. Também é usada para ortogonalizar o chute
        inicial aleatório.
        """
        u, _s, vt = np.linalg.svd(W, full_matrices=False)
        return u @ vt
    W = _sym(rng.randn(n_components, n_components))
    for _ in range(max_iter):
        WX = W @ Xw
        g = np.tanh(WX)
        gp = (1.0 - g * g).mean(axis=1)
        Wn = _sym((g @ Xw.T) / n - gp[:, None] * W)
        lim = np.max(np.abs(np.abs(np.sum(Wn * W, axis=1)) - 1.0))
        W = Wn
        if lim < tol:
            break
    return W


# ============================================================
# Importador de arquivos: detecção de formato + perfil editável
# ============================================================
# Por que existe: até aqui o app só abria três formatos conhecidos. Um CSV
# com separador ';', decimal com vírgula, ou metadados no topo resultava em
# ZERO canais reconhecidos — e a análise quebrava sem explicar nada. Agora o
# programa PALPITA o formato, mostra as primeiras linhas e deixa o usuário
# corrigir cada item antes de importar.

CSV_PROFILE_DEFAULT = {
    "sep": ",",            # separador de coluna
    "decimal": ".",        # separador decimal
    "encoding": "utf-8",
    "skip": 0,             # linhas a pular ANTES do cabeçalho
    "header_row": True,    # a 1ª linha após 'skip' é cabeçalho?
    "comment": "#",        # prefixo de linha comentada ("" = nenhum)
    "ch_cols": [],         # índices das colunas de sinal
    "time_col": None,      # coluna de tempo (opcional)
    "event_col": None,     # coluna de evento/fase (opcional)
    "sr": 0.0,             # 0 => deduzir da coluna de tempo
    "unit_scale": 1.0,     # multiplicador para µV (1e3 se o arquivo é mV)
    "signal_type": "EEG",
    "time_unit": "auto",   # s / ms / us / idx / auto
}


def csv_sniff_profile(path, max_linhas=80):
    """Analisa o início do arquivo e PALPITA um perfil de leitura.

    Devolve (perfil, linhas_cruas). Nada é decidido em definitivo: o palpite
    vai para a tela para o usuário conferir e corrigir.
    """
    perfil = dict(CSV_PROFILE_DEFAULT)
    brutas = []
    # encoding: tenta utf-8 (com BOM) e cai para latin-1, que nunca falha
    for enc in ("utf-8-sig", "utf-8", "latin-1"):
        try:
            with open(path, "r", encoding=enc, errors="strict") as f:
                brutas = [f.readline().rstrip("\n\r") for _ in range(max_linhas)]
            perfil["encoding"] = enc
            break
        except (UnicodeDecodeError, LookupError):
            continue
    if not brutas:
        with open(path, "r", encoding="latin-1", errors="ignore") as f:
            brutas = [f.readline().rstrip("\n\r") for _ in range(max_linhas)]
        perfil["encoding"] = "latin-1"
    brutas = [l for l in brutas if l != ""] or [""]

    # 1) quantas linhas comentadas/metadados no topo. Além do '#' padrão,
    # reconhece '%' (OpenBCI GUI) e '//' — o prefixo detectado fica no perfil
    # para o carregador pular as mesmas linhas.
    pref = perfil["comment"]
    if brutas and not brutas[0].lstrip().startswith(pref or "#"):
        for cand in ("%", "//"):
            if brutas[0].lstrip().startswith(cand):
                pref = cand
                perfil["comment"] = cand
                break
    skip = 0
    while skip < len(brutas) and pref and brutas[skip].lstrip().startswith(pref):
        skip += 1
    perfil["skip"] = skip
    corpo = brutas[skip:] or brutas

    # 2) separador: o candidato que gera mais colunas de forma CONSISTENTE
    melhor, melhor_n = ",", 0
    for cand in (",", ";", "\t", "|"):
        contagens = [l.count(cand) for l in corpo[:12] if l.strip()]
        if not contagens:
            continue
        n = min(contagens)
        if n > melhor_n and len(set(contagens)) <= 3:
            melhor, melhor_n = cand, n
    perfil["sep"] = melhor
    if melhor_n == 0:
        return perfil, brutas          # arquivo de 1 coluna ou ilegível

    campos = [l.split(melhor) for l in corpo if l.strip()]
    if not campos:
        return perfil, brutas

    def _num(tok, dec):
        """Testa se um token do CSV é numérico, respeitando o separador decimal
        que o sniffer palpitou.

        Com decimal vírgula, remove os pontos antes de converter, tratando-os
        como separador de milhar: "1.234" nesse modo vira 1234, não 1,234.
        Aspas simples e duplas em volta do campo são removidas.
        """
        t = tok.strip().strip('"').strip("'")
        if dec == ",":
            t = t.replace(".", "").replace(",", ".")
        try:
            float(t); return True
        except ValueError:
            return False

    # 3) decimal: vírgula só se ela aparecer DENTRO dos campos
    dec = ","
    amostra = campos[1] if len(campos) > 1 else campos[0]
    if melhor != "," and sum(1 for c in amostra if "," in c) >= max(1, len(amostra)//3):
        perfil["decimal"] = ","
    else:
        perfil["decimal"] = "."
    dec = perfil["decimal"]

    # 4) cabeçalho: a 1ª linha é texto e a 2ª é numérica?
    l0 = campos[0]
    l1 = campos[1] if len(campos) > 1 else campos[0]
    num0 = sum(1 for c in l0 if _num(c, dec))
    num1 = sum(1 for c in l1 if _num(c, dec))
    perfil["header_row"] = (num0 < max(1, len(l0) // 2)) and (num1 > len(l1) // 2)
    nomes = [c.strip().strip('"') for c in l0] if perfil["header_row"] else \
            [f"Col{i+1}" for i in range(len(l0))]
    dados = campos[1:] if perfil["header_row"] else campos

    # 5) colunas numéricas = candidatas a canal
    n_col = len(nomes)
    numericas = []
    for j in range(n_col):
        vals = [r[j] for r in dados[:20] if j < len(r)]
        if vals and sum(1 for v in vals if _num(v, dec)) >= max(1, int(0.8 * len(vals))):
            numericas.append(j)

    # 6) papéis especiais pelo NOME da coluna
    def _acha(chaves):
        """Acha a primeira coluna cujo nome contenha alguma palavra-chave, usada
        para adivinhar quem é tempo e quem é evento.

        A comparação é por substring em maiúsculas e a busca de tempo roda
        primeiro, incluindo a chave "INDEX" — logo um cabeçalho como
        "EVENT_INDEX" é capturado como coluna de tempo antes de ser testado
        como evento.
        """
        for j, nm in enumerate(nomes):
            u = nm.strip().upper()
            if any(k in u for k in chaves):
                return j
        return None
    t_col = _acha(("TIME", "TEMPO", "TIMESTAMP", "SAMPLE_INDEX", "INDEX"))
    e_col = _acha(("EVENT", "MARKER", "MARCADOR", "STATE", "PHASE", "FASE",
                   "TRIGGER", "CLASS"))
    if e_col is not None and e_col in numericas and len(numericas) > 1:
        pass                                   # evento numérico também vale
    perfil["time_col"] = t_col
    perfil["event_col"] = e_col
    perfil["ch_cols"] = [j for j in numericas if j not in (t_col, e_col)]

    # 7) taxa de amostragem: do nome ("Time:512Hz"), do preâmbulo, ou do tempo
    import re as _re
    for l in brutas[:skip] + [" ".join(nomes)]:
        m = _re.search(r"(?:sampling_frequency_hz|sample[_ ]?rate|Time)\D{0,4}"
                       r"(\d+(?:\.\d+)?)", l, _re.I)
        if m:
            try:
                perfil["sr"] = float(m.group(1)); break
            except ValueError:
                pass
    if not perfil["sr"] and t_col is not None and len(dados) > 3:
        try:
            ts = []
            for r in dados[:200]:
                if t_col < len(r) and _num(r[t_col], dec):
                    v = r[t_col].strip().replace(".", "").replace(",", ".") \
                        if dec == "," else r[t_col].strip()
                    ts.append(float(v))
            if len(ts) > 3:
                dt = float(np.median(np.diff(ts)))
                if dt > 0:
                    # coluna de tempo em segundos -> 1/dt ; se for índice, dt=1
                    perfil["sr"] = round(1.0 / dt, 3) if dt < 1 else 0.0
        except Exception:
            pass
    return perfil, brutas


def csv_load_with_profile(path, perfil):
    """Lê o arquivo aplicando o perfil. Devolve o mesmo dicionário de sessão
    dos outros loaders (sr, eeg, ch_names, markers, trials, format)."""
    p = dict(CSV_PROFILE_DEFAULT); p.update(perfil or {})
    sep, dec, pref = p["sep"], p["decimal"], p.get("comment") or ""
    n_skip = int(p.get("skip") or 0)
    linhas = []
    with open(path, "r", encoding=p.get("encoding", "utf-8"),
              errors="ignore") as f:
        for i, raw in enumerate(f):
            # 'skip' é contado sobre as linhas FÍSICAS do arquivo: é o que
            # permite ler um arquivo cujo preâmbulo NÃO começa com '#'
            # (ex.: exportações de Excel com 6 linhas de metadados).
            if i < n_skip:
                continue
            s = raw.rstrip("\n\r")
            if not s.strip():
                continue
            if pref and s.lstrip().startswith(pref):
                continue
            linhas.append(s)
    if not linhas:
        raise ValueError("Arquivo sem linhas de dados após pular o cabeçalho.")

    # csv.reader respeita campos entre aspas que contenham o separador
    # (ex.: "Paciente, João";1,23) — split() cru quebrava nesses casos.
    def _campos(s):
        """Quebra uma linha do CSV em campos respeitando aspas, em vez de usar
        split() cru.

        Usa o separador do perfil (sep) e não tenta detecta-lo; se o csv.reader
        levantar exceção, cai no split(sep) simples. Existe porque campos
        citados que contenham o separador (ex.: "Paciente, Joao";1,23)
        quebravam o parser antigo.
        """
        try:
            return next(csv.reader([s], delimiter=sep, skipinitialspace=True))
        except Exception:
            return s.split(sep)

    if p.get("header_row"):
        nomes_raw = [c.strip().strip('"') for c in _campos(linhas[0])]
        corpo = linhas[1:]
    else:
        nomes_raw = [f"Col{i+1}" for i in range(len(_campos(linhas[0])))]
        corpo = linhas

    ch_cols = list(p.get("ch_cols") or [])
    if not ch_cols:
        raise ValueError("Nenhuma coluna de sinal selecionada.")
    e_col, t_col = p.get("event_col"), p.get("time_col")
    esc = float(p.get("unit_scale") or 1.0)

    dados, eventos, tempos = [], [], []
    for s in corpo:
        r = _campos(s)
        try:
            v = []
            for j in ch_cols:
                tok = r[j].strip().strip('"')
                if dec == ",":
                    tok = tok.replace(".", "").replace(",", ".")
                v.append(float(tok) * esc)
            dados.append(v)
        except (ValueError, IndexError):
            continue                      # linha ruim: ignora em vez de quebrar
        if e_col is not None and e_col < len(r):
            eventos.append(r[e_col].strip().strip('"'))
        if t_col is not None and t_col < len(r):
            tok = r[t_col].strip()
            if dec == ",":
                tok = tok.replace(".", "").replace(",", ".")
            try: tempos.append(float(tok))
            except ValueError: pass
    if not dados:
        raise ValueError("Nenhuma linha numérica pôde ser lida com este perfil.")

    eeg = np.asarray(dados, dtype=float).T
    sr = float(p.get("sr") or 0.0)
    sr_origem = "declarada"
    if sr <= 0 and len(tempos) > 3:
        dt = float(np.median(np.diff(tempos)))
        # A coluna de tempo pode estar em s, ms, µs ou ser um ÍNDICE de amostra.
        # Antes, qualquer dt >= 1 (ms, µs ou índice) virava sr=0 e o programa
        # caía calado no padrão de 250 Hz — a escala de TODA a análise saía
        # errada sem nenhum aviso.
        un = (p.get("time_unit") or "auto").lower()
        if dt > 0:
            if un == "s" or (un == "auto" and dt < 0.1):
                sr, sr_origem = 1.0 / dt, "deduzida do tempo (s)"
            elif un == "ms" or (un == "auto" and 0.1 <= dt < 100):
                sr, sr_origem = 1000.0 / dt, "deduzida do tempo (ms)"
            elif un == "us":
                sr, sr_origem = 1e6 / dt, "deduzida do tempo (µs)"
            # 'índice de amostra' (dt≈1) não informa a taxa: fica para o usuário
    if sr <= 0:
        sr, sr_origem = float(SAMPLE_RATE), "PADRÃO (não foi possível deduzir)"

    nomes = [nomes_raw[j] if j < len(nomes_raw) else f"CH{j+1}" for j in ch_cols]

    # eventos -> marcadores/trials nas TRANSIÇÕES
    markers, trials = [], []
    if eventos:
        atual, ini = eventos[0], 0
        markers.append((0.0, atual))
        for i, e in enumerate(eventos[1:], start=1):
            if e != atual:
                trials.append({"phase": str(atual).lower(), "class_id": -1,
                               "class_name": atual, "start_line": ini + 1,
                               "end_line": i, "duration": (i - ini) / sr})
                markers.append((i / sr, e)); atual, ini = e, i
        trials.append({"phase": str(atual).lower(), "class_id": -1,
                       "class_name": atual, "start_line": ini + 1,
                       "end_line": len(eventos),
                       "duration": (len(eventos) - ini) / sr})
    return {"sr": sr, "eeg": eeg, "ch_names": nomes, "markers": markers,
            "format": "perfil", "trials": trials, "events_csv_path": None,
            "signal_type": p.get("signal_type", "EEG"), "perfil": p,
            # metadados que o painel Offline exibe (antes saía "SR não disponível")
            "csv_path": path, "sr_origem": sr_origem,
            "sr_declared": float(p.get("sr") or 0.0) or None,
            "n_samples": int(eeg.shape[1]),
            "duration_s": round(eeg.shape[1] / sr, 2) if sr else None}


def avaliar_qualidade_sinal(eeg, ch_names, tipo="EEG"):
    """Controle de qualidade ao importar: diz, por canal, se o sinal é
    plausível. Existe porque um EDF com os 20 canais SATURADOS passou batido
    e a análise seguiu como se fosse EEG válido.

    Retorna (veredito_global, lista_por_canal, resumo_texto).
    """
    lim = {"EEG": (0.5, 150.0, 500.0), "EMG": (1.0, 2000.0, 5000.0),
           "ECG": (5.0, 5000.0, 10000.0), "EoG": (1.0, 1000.0, 3000.0)}
    lo_ok, hi_ok, hi_sat = lim.get(tipo, lim["EEG"])
    por_canal, n_sat, n_flat, n_ok = [], 0, 0, 0
    X = np.asarray(eeg, float)
    if X.ndim != 2 or X.size == 0:
        return "vazio", [], tr("Nenhum canal para avaliar.")
    for i in range(X.shape[0]):
        x = X[i]
        rms = float(np.sqrt(np.mean(x * x)))
        pk = float(np.max(np.abs(x))) if x.size else 0.0
        frac_alta = float(np.mean(np.abs(x) > hi_sat)) if x.size else 0.0
        if rms < lo_ok or np.allclose(x, x[0] if x.size else 0):
            st = "sem sinal"; n_flat += 1
        elif rms > hi_ok * 10 or frac_alta > 0.20:
            st = "saturado"; n_sat += 1
        elif rms > hi_ok:
            st = "amplitude alta"
        else:
            st = "ok"; n_ok += 1
        por_canal.append({"canal": ch_names[i] if i < len(ch_names) else f"CH{i+1}",
                          "rms": round(rms, 1), "pico": round(pk, 1),
                          "status": st})
    n = X.shape[0]
    if n_sat >= max(1, n // 2):
        ver = "reprovado"
        txt = (tr("{0} de {1} canais SATURADOS (amplitude muito acima do esperado para "
                  "{2}). Os resultados não serão confiáveis — verifique referência, ganho e "
                  "aterramento antes de analisar.").format(n_sat, n, tipo))
    elif n_flat >= max(1, n // 2):
        ver = "reprovado"
        txt = tr("{0} de {1} canais sem sinal (linha reta ou amplitude nula).").format(n_flat, n)
    elif n_sat or n_flat:
        ver = "atencao"
        txt = (tr("{0} de {1} canais ok; {2} saturado(s), {3} sem sinal. Confira os canais "
                  "marcados antes de analisar.").format(n_ok, n, n_sat, n_flat))
    else:
        ver = "ok"
        txt = tr("Todos os {0} canais com amplitude plausível para {1}.").format(n, tipo)
    return ver, por_canal, txt


def ica_clean_eog(eeg_uV, sr, ch_names, n_components=None):
    """Remove piscadas por ICA (numpy puro). Filtra 1-40 Hz (estabiliza a ICA),
    detecta o componente ocular (correlação com canais frontais ou curtose) e
    reconstrói. Retorna (eeg_limpo_uV, indices_excluidos, info)."""
    X = np.asarray(eeg_uV, dtype=float)
    n_ch, n = X.shape
    if n_ch < 2 or n < 32:
        return X, [], {"backend": "numpy", "note": tr("sinal curto demais")}
    try:
        hi = min(40.0, sr / 2.0 * 0.98)
        sos = scipy_signal.butter(4, [1.0, hi], btype="band", fs=sr, output="sos")
        Xf = scipy_signal.sosfiltfilt(sos, X, axis=1)
    except Exception:
        Xf = X - X.mean(axis=1, keepdims=True)
    mean = Xf.mean(axis=1, keepdims=True)
    Xc = Xf - mean
    cov = np.cov(Xc)
    dvals, E = np.linalg.eigh(cov)
    order = np.argsort(dvals)[::-1]
    k = min(n_components or 15, n_ch)
    sel = order[:k]
    dsel = np.maximum(dvals[sel], 1e-12)
    K = (E[:, sel] / np.sqrt(dsel)).T          # branqueamento  k x n_ch
    Xw = K @ Xc
    W = _fast_ica_W(Xw, k)
    S = W @ Xw                                  # fontes  k x n
    frontal = [i for i, nm in enumerate(ch_names)
               if nm.upper().replace("EEG", "").replace("-", "").strip()
               in ("FP1", "FP2", "FPZ", "AF7", "AF8", "FP1F", "FP2F")]
    excluded = []
    if frontal:
        fsig = Xc[frontal].mean(axis=0)
        cors = np.array([abs(np.corrcoef(S[c], fsig)[0, 1]) for c in range(k)])
        cmax = int(np.nanargmax(cors))
        if np.isfinite(cors[cmax]) and cors[cmax] > 0.5:
            excluded = [cmax]
    if not excluded:                            # fallback: fonte mais impulsiva
        kurt = np.array([float(((S[c] - S[c].mean()) ** 4).mean()
                               / (S[c].var() ** 2 + 1e-12) - 3.0) for c in range(k)])
        cmax = int(np.argmax(kurt))
        if kurt[cmax] > 10:
            excluded = [cmax]
    S2 = S.copy()
    for c in excluded:
        S2[c] = 0.0
    clean = (np.linalg.pinv(K) @ (np.linalg.pinv(W) @ S2)) + mean
    return clean, excluded, {"backend": "numpy", "n_components": k}


# ============================================================
# DSP AVANÇADO (numpy/scipy puro) — algoritmos do roteiro de revisão que
# faltavam: reamostragem anti-aliasing (DSP-04), notch de harmônicos + auto
# 50/60 (DSP-03), multitaper (EEG-04), aperiódico 1/f FOOOF-lite (EEG-05),
# TKEO/onset EMG (EMG-03), correção de ectópicos (ECG-02), Lomb-Scargle
# (ECG-03), regressão EOG Gratton-Coles (EOG-03), LTTB (VIZ-02).
# ============================================================
def resample_with_antialias(sig, fs_in, fs_out):
    """Reamostra COM anti-aliasing (DSP-04). Downsample inteiro usa decimate
    (low-pass embutido); caso geral usa resample_poly. Nunca subsampling simples.
    Retorna (sinal, fs_out)."""
    sig = np.asarray(sig, dtype=float)
    fi, fo = int(round(fs_in)), int(round(fs_out))
    if fo == fi or sig.size < 4 or fo <= 0:
        return sig, float(fs_in)
    g = math.gcd(fi, fo)
    up, down = fo // g, fi // g
    if up == 1 and down > 1:
        try:
            return scipy_signal.decimate(sig, down, ftype="iir",
                                         zero_phase=True), float(fs_out)
        except Exception:
            pass
    try:
        return scipy_signal.resample_poly(sig, up, down), float(fs_out)
    except Exception:
        return sig, float(fs_in)


def detect_line_freq(sig, fs):
    """Detecta a rede (50 vs 60 Hz) pelo maior pico na PSD (DSP-03)."""
    sig = np.asarray(sig, float); sig = sig[np.isfinite(sig)]
    if sig.size < int(fs) or fs < 130:
        return 60.0
    f, p = scipy_signal.welch(sig, fs=fs, nperseg=min(len(sig), int(fs * 2)))

    def _band(fc):
        """Devolve o maior pico da PSD na vizinhanca de uma frequência candidata
        da rede.

        A faixa e fc +/- 1,5 Hz; se nenhum bin de Welch cair nela, devolve 0.0,
        o que faz detect_line_freq escolher 60 Hz por empate.
        """
        m = (f >= fc - 1.5) & (f <= fc + 1.5)
        return float(p[m].max()) if m.any() else 0.0
    return 50.0 if _band(50.0) > _band(60.0) else 60.0


def notch_harmonics(sig, fs, base=60.0, n_harmonics=3, Q=30.0):
    """Notch na fundamental + harmônicos (DSP-03), fase-zero (offline)."""
    sig = np.asarray(sig, float)
    ny = fs / 2.0
    out = sig
    for k in range(1, int(n_harmonics) + 1):
        f0 = base * k
        if 0 < f0 < ny * 0.98:
            try:
                b, a = scipy_signal.iirnotch(f0 / ny, Q)
                out = scipy_signal.filtfilt(b, a, out)
            except Exception:
                pass
    return out


def psd_multitaper(sig, fs, NW=3.0, n_tapers=None):
    """PSD por multitaper (DPSS/Slepian) — menor variância que Welch (EEG-04).
    Retorna (freqs, psd em unidade^2/Hz)."""
    sig = np.asarray(sig, float); sig = sig[np.isfinite(sig)]
    n = sig.size
    if n < 16:
        return np.array([]), np.array([])
    K = int(n_tapers) if n_tapers else max(1, int(2 * NW) - 1)
    sig = sig - sig.mean()
    tapers = scipy_signal.windows.dpss(n, NW, K)
    psds = [np.abs(np.fft.rfft(w * sig)) ** 2 / fs for w in np.atleast_2d(tapers)]
    return np.fft.rfftfreq(n, 1.0 / fs), np.mean(psds, axis=0)


def aperiodic_fit(freqs, psd, fmin=1.0, fmax=45.0):
    """Ajuste aperiódico 1/f em log-log (FOOOF-lite, EEG-05): offset, expoente e
    a PSD 'achatada' (razão pico/aperiódico) que realça oscilações reais."""
    freqs = np.asarray(freqs, float); psd = np.asarray(psd, float)
    m = (freqs >= fmin) & (freqs <= fmax) & (freqs > 0) & (psd > 0)
    flat = psd.copy()
    if m.sum() < 5:
        return dict(offset=None, exponent=None, flat=flat)
    lf, lp = np.log10(freqs[m]), np.log10(psd[m])
    A = np.vstack([np.ones_like(lf), -lf]).T
    (offset, exponent), *_ = np.linalg.lstsq(A, lp, rcond=None)
    model = 10 ** (offset - exponent * lf)
    flat[m] = psd[m] / np.maximum(model, 1e-30)
    return dict(offset=float(offset), exponent=float(exponent), flat=flat)


def tkeo(sig):
    """Operador de energia Teager-Kaiser: psi[n]=x[n]^2 - x[n-1]*x[n+1] (EMG-03)."""
    sig = np.asarray(sig, float)
    y = np.zeros_like(sig)
    if sig.size >= 3:
        y[1:-1] = sig[1:-1] ** 2 - sig[:-2] * sig[2:]
    return y


def regrade_para_taxa_nominal(eeg, ts, sr_nominal, max_vao=5):
    """Recoloca cada amostra no indice que o carimbo de tempo dela manda.

    Justapor as amostras sobreviventes encolhe o eixo do tempo: numa perda
    concentrada num trecho so, toda frequencia lida depois sai deslocada na
    mesma proporcao. Aqui cada amostra volta para a grade nominal; vao curto
    (ate `max_vao` amostras) e tapado por interpolacao e vao longo vira
    lacuna declarada, para o MNE poder recusar o trecho.

    Devolve (eeg_novo, idx, lacunas); idx[i] e o indice novo da linha i (-1
    se ela foi descartada) e lacunas e [(inicio_s, duracao_s)]. Devolve
    (eeg, None, []) quando nao da para reconstruir.
    """
    eeg = np.asarray(eeg, float)
    ts = np.asarray(ts, float)
    if eeg.ndim != 2 or ts.ndim != 1 or ts.size != eeg.shape[1]:
        return eeg, None, []
    n_ch, n_samp = eeg.shape
    bons = np.isfinite(ts)
    if n_samp < 2 or not np.any(bons):
        return eeg, None, []
    t0 = float(ts[bons][0])
    idx = np.rint((ts - t0) * float(sr_nominal)).astype(np.int64)
    idx[~bons] = -1
    # Carimbo repetido ou que anda para tras desalinha tudo o que vem depois:
    # so entra na grade o que for estritamente crescente.
    corrida = np.maximum.accumulate(idx)
    ok = (idx == corrida) & (idx >= 0)
    ok[1:] &= np.diff(corrida) > 0
    idx_ok = idx[ok]
    if idx_ok.size < 2:
        return eeg, None, []
    total = int(idx_ok[-1]) + 1
    novo = np.full((n_ch, total), np.nan)
    novo[:, idx_ok] = eeg[:, ok]
    lacunas = []
    for a, b in zip(idx_ok[:-1], idx_ok[1:]):
        vao = int(b) - int(a) - 1
        if vao <= 0:
            continue
        if vao <= max_vao:
            for c in range(n_ch):
                novo[c, int(a) + 1:int(b)] = np.linspace(
                    novo[c, int(a)], novo[c, int(b)], vao + 2)[1:-1]
        else:
            lacunas.append(((int(a) + 1) / float(sr_nominal),
                            vao / float(sr_nominal)))
    idx[~ok] = -1
    return np.nan_to_num(novo, nan=0.0), idx, lacunas


def emg_onset_tkeo(sig, fs, k=3.0, min_dur_s=0.05, baseline_s=0.5, info=None):
    """Onset/offset de ativação EMG via TKEO + duplo limiar (EMG-03).
    Retorna [(onset_s, offset_s)]. Com `info` (dict), conta de onde saiu a
    linha de base: info["base_ini_s"] e info["base_realocada"]."""
    e = np.abs(tkeo(np.asarray(sig, float)))
    win = max(1, int(0.02 * fs))
    if win > 1:
        e = np.convolve(e, np.ones(win) / win, mode="same")
    nb = max(win, int(baseline_s * fs))
    base = e[:nb]
    ini = 0
    # Gravacao que ja comeca contraindo: o limiar calibrado ali fica no nivel
    # da contracao e o detector devolvia ZERO ativacoes num arquivo cheio
    # delas. Quando o comeco esta acima da mediana do registro, a linha de
    # base passa para o trecho mais quieto do arquivo inteiro.
    if e.size > 2 * nb and float(base.mean()) > float(np.median(e)):
        movel = np.convolve(e, np.ones(nb) / nb, mode="valid")
        ini = int(np.argmin(movel))
        base = e[ini:ini + nb]
    if info is not None:
        info["base_ini_s"] = ini / float(fs)
        info["base_realocada"] = ini > 0
    thr = base.mean() + k * (base.std() or 1e-9)
    active = e > thr
    min_n = max(1, int(min_dur_s * fs))
    out, i, N = [], 0, len(active)
    while i < N:
        if active[i]:
            j = i
            while j < N and active[j]:
                j += 1
            if j - i >= min_n:
                out.append((i / fs, j / fs))
            i = j
        else:
            i += 1
    return out


def emg_fundir_ativacoes(ativ, gap_s=0.25, min_dur_s=0.10):
    """Junta ativações separadas por menos de `gap_s` e descarta as mais
    curtas que `min_dur_s`. O TKEO liga e desliga várias vezes dentro de UMA
    contração (o envelope oscila em volta do limiar) e o relatório contava 12
    contrações onde a figura mostrava 6 faixas (validação com leigos).
    Devolve [(onset_s, offset_s)], como emg_onset_tkeo."""
    out = []
    for t0, t1 in sorted((float(a), float(b)) for a, b in (ativ or [])):
        if out and t0 - out[-1][1] < gap_s:
            out[-1] = (out[-1][0], max(out[-1][1], t1))
        else:
            out.append((t0, t1))
    return [(a, b) for a, b in out if (b - a) >= min_dur_s]


def hrv_pendente(n, chave):
    """Texto de pendência de uma métrica de HRV, ou None se já dá para calcular.

    Existe para o painel poder mostrar "—" e quanto ainda falta em vez de
    imprimir um número calculado sobre uma janela onde o índice não está
    definido — o que era pior que não mostrar nada, porque parecia uma medida.
    """
    falta = ECG_RR_MIN.get(chave, 0) - int(n)
    return tr("— (faltam {} RR)").format(falta) if falta > 0 else None


def correct_ectopic_rr(rr_ms, threshold=0.3):
    """Correção de ectópicos na série RR (à la Lipponen-Tarvainen, ECG-02):
    marca RR que desviam > threshold da mediana móvel e interpola. Retorna
    (rr_corrigido, indices_corrigidos)."""
    rr = np.asarray(rr_ms, float)
    if rr.size < 3:
        return rr, []
    kern = min(5, rr.size if rr.size % 2 else rr.size - 1)
    med = scipy_signal.medfilt(rr, kernel_size=max(3, kern))
    dev = np.abs(rr - med) / np.maximum(med, 1e-6)
    bad = np.where(dev > threshold)[0]
    corr = rr.copy()
    good = np.setdiff1d(np.arange(rr.size), bad)
    if good.size >= 2 and bad.size:
        corr[bad] = np.interp(bad, good, rr[good])
    return corr, bad.tolist()


def hrv_lomb_scargle(rr_times_s, rr_ms):
    """LF/HF por Lomb-Scargle (RR irregular, SEM interpolar, ECG-03)."""
    t = np.asarray(rr_times_s, float)
    y = np.asarray(rr_ms, float)
    if t.size < 8 or np.std(y) < 1e-9:          # série curta ou constante
        return dict(lf=None, hf=None, lf_hf=None, method="lomb-scargle")
    y = y - y.mean()
    f = np.linspace(0.0033, 0.4, 400)
    try:
        pg = scipy_signal.lombscargle(t, y, 2 * np.pi * f, normalize=True)
    except Exception:
        return dict(lf=None, hf=None, lf_hf=None, method="lomb-scargle")
    lfm = (f >= 0.04) & (f < 0.15)
    hfm = (f >= 0.15) & (f < 0.4)
    lf = float(np.trapz(pg[lfm], f[lfm])); hf = float(np.trapz(pg[hfm], f[hfm]))
    return dict(lf=lf, hf=hf, lf_hf=(lf / hf if hf > 0 else None),
                method="lomb-scargle")


def eog_regression(eeg, eog):
    """Remove artefato ocular por regressão (Gratton-Coles, EOG-03):
    eeg_corr = eeg - b*eog, b = cov(eeg,eog)/var(eog). eeg pode ser (n,) ou
    (n_ch, n); eog é (n,). Retorna eeg corrigido."""
    eeg = np.asarray(eeg, float); eog = np.asarray(eog, float)
    single = eeg.ndim == 1
    E = eeg[None, :] if single else eeg
    ref = eog - eog.mean()
    v = float(np.dot(ref, ref))
    if v <= 0:
        return eeg
    out = np.empty_like(E)
    for c in range(E.shape[0]):
        b = float(np.dot(E[c] - E[c].mean(), ref)) / v
        out[c] = E[c] - b * eog
    return out[0] if single else out


def lttb(x, y, n_out):
    """Largest-Triangle-Three-Buckets: decimação PRESERVADORA DE PICO para
    display (VIZ-02) — nunca esconde spikes como '1 a cada N'."""
    x = np.asarray(x, float); y = np.asarray(y, float)
    n = len(x)
    if n_out >= n or n_out < 3 or n < 3:
        return x, y
    ox = np.empty(n_out); oy = np.empty(n_out)
    ox[0], oy[0] = x[0], y[0]
    every = (n - 2) / (n_out - 2)
    a = 0
    for i in range(n_out - 2):
        s = int(np.floor((i + 1) * every)) + 1
        e = min(int(np.floor((i + 2) * every)) + 1, n)
        avx = x[s:e].mean() if e > s else x[min(s, n - 1)]
        avy = y[s:e].mean() if e > s else y[min(s, n - 1)]
        r0 = int(np.floor(i * every)) + 1
        r1 = int(np.floor((i + 1) * every)) + 1
        rx, ry = x[r0:r1], y[r0:r1]
        if len(rx) == 0:
            ox[i + 1], oy[i + 1] = x[r0 - 1], y[r0 - 1]; a = r0 - 1; continue
        area = np.abs((x[a] - avx) * (ry - y[a]) - (x[a] - rx) * (avy - y[a]))
        j = int(np.argmax(area))
        ox[i + 1], oy[i + 1] = rx[j], ry[j]
        a = r0 + j
    ox[-1], oy[-1] = x[-1], y[-1]
    return ox, oy


# ============================================================
# SignalProcessor
# ============================================================
class SignalProcessor:
    """Reune as rotinas de análise espectral e estatística usadas pelas abas de
    tempo real e offline (FFT, potência de banda, PSD, ERD/ERS, envelope de
    EMG).

    Não guarda estado: e so um namespace de @staticmethod que recebem o array
    de amostras. Varias rotinas devolvem zeros quando o trecho tem menos de 1 s
    (len(data) < sample_rate), então chamadas com janelas curtas falham em
    silêncio.
    """
    @staticmethod
    def compute_fft(data, sample_rate=SAMPLE_RATE):
        """Calcula o espectro de amplitude de um trecho, alimentando os gráficos
        de FFT ao vivo, a análise offline e os relatórios.

        A normalizacao 2/sum(janela) compensa o ganho coerente da Hanning
        (~0,5); a versão antiga usava 2/n e subestimava a amplitude em cerca de
        2x. Com menos de 2 amostras devolve dois arrays vazios.
        """
        n = len(data)
        if n < 2:
            return np.array([]), np.array([])
        window = np.hanning(n)
        # 2/sum(window) compensa o ganho coerente da janela (Hanning ~0.5);
        # com janela retangular sum=n, generaliza. Antes usava 2/n -> ~2x baixo.
        wsum = float(np.sum(window)) or float(n)
        spectrum = np.abs(rfft(data * window)) * 2.0 / wsum
        freqs = rfftfreq(n, 1.0 / sample_rate)
        return freqs, spectrum

    @staticmethod
    def compute_band_powers(data, sample_rate=SAMPLE_RATE):
        """Integra a PSD de Welch dentro de cada faixa de EEG_BANDS (Delta a
        Gamma) e devolve o dicionário de potências por banda.

        Com menos de 1 s de dados devolve todas as bandas em 0.0. nperseg e
        limitado a 256 amostras, o que fixa a resolução espectral em torno de 1
        Hz a 250 Hz.
        """
        if len(data) < sample_rate:
            return {b: 0.0 for b in EEG_BANDS}
        nperseg = min(256, len(data))
        freqs, psd = scipy_signal.welch(data, fs=sample_rate, nperseg=nperseg)
        powers = {}
        df = float(freqs[1] - freqs[0]) if len(freqs) > 1 else 0.0
        for band, (low, high) in EEG_BANDS.items():
            # Mesma regra do retângulo de compute_band_power: o trapézio perdia
            # meio Δf em cada borda da faixa e deixava Delta (3,5 Hz de largura,
            # 4 bins) ~16% abaixo do real, quebrando a soma de Parseval.
            mask = (freqs >= low) & (freqs < high)
            powers[band] = float(np.sum(psd[mask]) * df) if np.any(mask) else 0.0
        return powers

    @staticmethod
    def compute_statistics(data):
        """Calcula media, desvio-padrão e RMS de um canal para os painéis
        numericos e para o relatório."""
        if len(data) == 0:
            return {"mean": 0.0, "std": 0.0, "rms": 0.0}
        return {
            "mean": float(np.mean(data)),
            "std":  float(np.std(data)),
            "rms":  float(np.sqrt(np.mean(np.square(data)))),
        }

    @staticmethod
    def compute_psd_column(data, sample_rate=SAMPLE_RATE, fmax=SPEC_FMAX, n_bins=SPEC_FMAX):
        """Produz uma coluna do espectrograma: PSD em dB reamostrada numa grade
        fixa de 0 a fmax.

        Com menos de 1 s de dados devolve a coluna inteira em -80 dB, o piso da
        escala, para não abrir buraco no espectrograma. O default n_bins =
        SPEC_FMAX da 1 bin por Hz.
        """
        if len(data) < sample_rate:
            return np.full(n_bins, -80.0)
        nperseg = min(256, len(data))
        freqs, psd = scipy_signal.welch(data, fs=sample_rate, nperseg=nperseg)
        psd_db = 10.0 * np.log10(np.maximum(psd, 1e-12))
        grid = np.linspace(0.0, fmax, n_bins, endpoint=False)
        return np.interp(grid, freqs, psd_db)

    @staticmethod
    def compute_band_power(data, low, high, sample_rate=SAMPLE_RATE):
        """Integra a PSD de Welch numa faixa arbitraria de Hz; e a base do ERD/ERS
        e do índice de foco.

        A guarda olha o nperseg efetivo, e nao 1 s fixo, e o "sem dados" devolve
        NaN (indefinido) em vez de 0.0.
        """
        n = len(data)
        # A guarda antiga era `len(data) < sample_rate` e devolvia 0.0: toda
        # janela menor que 1 s virava "potência zero" em silêncio. E o curso
        # temporal de ERD desliza janelas de 0,5 s — como 0,5·sr < sr SEMPRE, a
        # potência dava 0 em 100% das chamadas e o ERD% travava em
        # (0 − base)/base·100 = −100% para todo canal e todo instante: as curvas
        # de C3/C4/Cz eram três retas horizontais.
        # O que o Welch de fato exige é UM segmento; 8 amostras é o piso.
        if n < 8:
            return float("nan")
        nperseg = min(256, n)
        # nfft fixo em 256: com janela curta (0,5 s = 125 amostras) o Δf virava
        # 2 Hz e a máscara 8–13 Hz cobria 6,0 Hz contra 4,9 Hz da janela longa;
        # a mesma faixa media +25% em ruído branco só por ser mais curta.
        freqs, psd = scipy_signal.welch(data, fs=sample_rate, nperseg=nperseg,
                                        nfft=max(256, nperseg))
        mask = (freqs >= low) & (freqs < high)
        # Faixa mais estreita que a resolução (sample_rate/nperseg): nenhum bin
        # cai dentro. Isso é medida INDEFINIDA, não potência nula — devolver 0.0
        # aqui contaminava razões de ERD e potência relativa com zeros falsos.
        if not np.any(mask): return float("nan")
        # Regra do retângulo (Σ psd·Δf) para QUALQUER número de bins — a mesma
        # de compute_band_powers e do heatmap do PDF, que já divergiam desta.
        # O trapézio integrava de freqs[mask][0] a freqs[mask][-1], ou seja
        # sobre (nbins−1)·Δf em vez de nbins·Δf: perdia meio bin em cada borda
        # e enxergava só os bins internos. A 250 Hz/nperseg 256 (Δf≈0,977 Hz)
        # uma faixa de 2 Hz tem 2 bins e saía −50,0% EXATOS; Delta/Theta (4
        # bins) −25%, Alfa (5 bins) −20%. Pior: um pico colado na borda da
        # faixa entrava pela metade — senoide de 8,4 Hz medida em 8–13 Hz saía
        # 47% abaixo do valor certo, enquanto a mesma senoide a 10,5 Hz (miolo)
        # saía correta. O caso de 1 bin já era exceção aqui; agora é a regra
        # geral, e o valor volta a fechar com Parseval (Σ bandas ≈ variância).
        df = float(freqs[1] - freqs[0]) if freqs.size > 1 else 1.0
        return float(np.sum(psd[mask]) * df)

    @staticmethod
    def compute_band_density(data, low, high, sample_rate=SAMPLE_RATE):
        """Densidade espectral MEDIA na faixa (µV²/Hz) — irmã de
        compute_band_power, usada só onde as janelas comparadas têm durações
        diferentes.

        O ERD compara janelas de 0,5 s contra um repouso de 3 s. A potência
        SOMADA depende de quantos bins caem na faixa, e esse número muda com o
        nperseg de cada lado: o mesmo arquivo lido com a taxa nominal ou com a
        taxa medida pelo leitor mudava o ERD% em 43 pontos percentuais, e ruído
        estacionário sem tarefa nenhuma marcava de −18% a +26%. A razão entre
        densidades é imune ao número de bins.
        """
        n = len(data)
        if n < 8:
            return float("nan")
        nperseg = min(256, n)
        # nfft fixo: a média por bin só é comparável se a máscara pegar os
        # MESMOS bins dos dois lados. Sem isso a janela de 0,5 s cobria 6,000 Hz
        # e o repouso 4,883 Hz, e o ERD%(t) tinha −18,6% fixo sem evento algum.
        freqs, psd = scipy_signal.welch(data, fs=sample_rate, nperseg=nperseg,
                                        nfft=max(256, nperseg))
        mask = (freqs >= low) & (freqs < high)
        if not np.any(mask):
            return float("nan")
        return float(np.mean(psd[mask]))

    @staticmethod
    def compute_focus_index(data, sample_rate=SAMPLE_RATE):
        """Calcula o índice de foco beta/(alfa+beta) exibido no FocusMeterWidget
        da aba de análise.

        Resultado em 0..1; quando a soma alfa+beta e desprezivel devolve 0,5
        (neutro) em vez de dividir por zero.
        """
        alpha = SignalProcessor.compute_band_power(data, 8.0, 13.0, sample_rate)
        beta  = SignalProcessor.compute_band_power(data, 13.0, 30.0, sample_rate)
        s = alpha + beta
        # compute_band_power agora pode devolver NaN (trecho curto demais ou
        # faixa sem bin); NaN < 1e-9 e False, entao sem este teste o medidor de
        # foco exibiria NaN em vez do neutro 0,5.
        if not np.isfinite(s) or s < 1e-9: return 0.5
        return float(beta / s)

    @staticmethod
    def compute_emg_envelope(data, sample_rate=SAMPLE_RATE, window_s=0.10):
        """Extrai o envelope de EMG por media móvel do valor absoluto, usado pelo
        EMGEnvelopeWidget.

        Janela default de 0,10 s convertida em amostras pela taxa; se a janela
        for maior que o trecho, devolve um valor constante igual a media. A
        convolucao usa mode='same', então as bordas ficam atenuadas.
        """
        if len(data) < 2:
            return np.zeros_like(data)
        w = max(1, int(sample_rate * window_s))
        absdata = np.abs(data)
        if w >= len(absdata):
            return np.full_like(absdata, np.mean(absdata))
        kernel = np.ones(w) / w
        return np.convolve(absdata, kernel, mode="same")

    # ====================================================================
    # ERS/ERD — Event-Related (De)Synchronization
    # Método de Pfurtscheller & Lopes da Silva (1999).
    # Para cada trial: P_event = potência banda durante a fase MI.
    #                  P_baseline = potência banda durante a fase baseline.
    # ERD%(canal) = ((P_event - P_baseline) / P_baseline) × 100
    # Negativo = dessincronização (típico em motor imagery sobre córtex motor
    # contralateral). Positivo = sincronização ("beta rebound" pós-movimento).
    # ====================================================================
    @staticmethod
    def compute_ersd_per_channel(eeg, sr, trials_mi, trials_baseline_ref,
                                  band_low, band_high):
        """Para cada canal, calcula ERD/ERS médio entre trials.
        Args:
          eeg: array (n_ch, n_samp), em µV
          sr:  sample rate
          trials_mi: lista de (start_line, end_line) das janelas MI (1-indexed
                     conforme o events.csv do BCI system)
          trials_baseline_ref: lista de (start_line, end_line) das janelas
                     de referência (baseline ou pre_rest) para cada trial
          band_low, band_high: faixa em Hz
        Retorna: np.array (n_ch,) com ERD% (negativo = dessinc.)
        """
        n_ch = eeg.shape[0]
        out = np.zeros(n_ch)
        if not trials_mi or not trials_baseline_ref: return out
        for ch in range(n_ch):
            pot_mi, pot_bl = [], []
            for (mi_s, mi_e), (bl_s, bl_e) in zip(trials_mi,
                                                    trials_baseline_ref):
                # csv_start_line/csv_end_line são 1-indexed nas linhas DE DADOS
                # (ou seja, sample_index = line - 1 se o header já foi subtraído).
                # Nas saídas dos dois sistemas, linha 1 = primeira amostra; o
                # header é parte separada. Vamos clamp e usar como sample idx.
                a = max(0, mi_s - 1); b = min(eeg.shape[1], mi_e)
                c = max(0, bl_s - 1); d = min(eeg.shape[1], bl_e)
                if b - a < int(sr * 0.5) or d - c < int(sr * 0.5):
                    continue   # menos de 0.5s, ignora
                p_mi = SignalProcessor.compute_band_power(
                    eeg[ch, a:b], band_low, band_high, sr)
                p_bl = SignalProcessor.compute_band_power(
                    eeg[ch, c:d], band_low, band_high, sr)
                if not (np.isfinite(p_mi) and np.isfinite(p_bl)): continue
                if p_bl < 1e-12: continue
                pot_mi.append(p_mi); pot_bl.append(p_bl)
            # RAZAO DAS MEDIAS (Pfurtscheller & Lopes da Silva, 1999), nao
            # media das razoes. Com pre_rest de 3 s o Welch encaixa um unico
            # segmento (2 graus de liberdade) e o 1/P_baixo dos trials com
            # baseline fraca dominava a media por desigualdade de Jensen:
            # ruido estacionario SEM efeito de tarefa saía +25,2%, e um ERD
            # real de -50% de potencia era lido como -38,5%.
            if pot_bl:
                m_bl = float(np.mean(pot_bl))
                if m_bl > 1e-12:
                    out[ch] = (float(np.mean(pot_mi)) - m_bl) / m_bl * 100.0
        return out

    @staticmethod
    def compute_ersd_baseline_density(eeg, sr, bl_ranges, band_low, band_high,
                                      window_s=0.5):
        """Densidade de referência por canal para o ERD%(t).

        O repouso é fatiado em janelas do MESMO comprimento das de análise
        (window_s, passo de metade), como no mosaico ERSP: mesma resolução e
        mesmo vazamento espectral dos dois lados da razão. Um Welch único do
        repouso inteiro espalhava o pico de mu de outro jeito e deixava o
        curso temporal com ERD de −7% a −19% sem evento algum.
        """
        n_chs = eeg.shape[0]
        base = np.full(n_chs, 1e-9)
        jan = int(round(window_s * sr)); passo = max(1, jan // 2)
        if jan < 8:
            return base
        for ch in range(n_chs):
            vals = []
            for (bl_s, bl_e) in bl_ranges:
                a = max(0, bl_s - 1); b = min(eeg.shape[1], bl_e)
                if b - a < jan:
                    continue
                for a2 in range(a, b - jan + 1, passo):
                    vals.append(SignalProcessor.compute_band_density(
                        eeg[ch, a2:a2 + jan], band_low, band_high, sr))
            vals = [v for v in vals if np.isfinite(v)]
            if vals:
                base[ch] = float(np.mean(vals))
        return base

    @staticmethod
    def compute_ersd_timecourse(eeg, sr, trials_mi, baseline_pwr_per_ch,
                                  band_low, band_high, window_s=0.5,
                                  step_s=0.1, lock_before_s=1.0,
                                  duration_s=4.0):
        """Curso temporal ERD%(t) médio entre trials, com janela deslizante.
        Para cada trial, computa banda em janelas (window_s, step_s) cobrindo
        [-lock_before_s, +duration_s] em torno do início do MI. Normaliza
        cada trial pela potência baseline daquele canal.
        Retorna (t_axis (T,), ersd (n_ch, T))
        """
        n_ch = eeg.shape[0]
        win_n  = int(round(window_s * sr))
        step_n = int(round(step_s * sr))
        if win_n < 4 or step_n < 1:
            return np.array([]), np.zeros((n_ch, 0))
        before_n = int(round(lock_before_s * sr))
        after_n  = int(round(duration_s * sr))
        # gera centros (em samples) relativos ao início do MI
        centers = np.arange(-before_n + win_n // 2,
                             after_n - win_n // 2 + 1, step_n)
        if centers.size == 0:
            return np.array([]), np.zeros((n_ch, 0))
        t_axis = centers / sr
        T = len(centers)
        accum = np.zeros((n_ch, T)); cnt = np.zeros((n_ch, T))
        for ti, (mi_s, _mi_e) in enumerate(trials_mi):
            mi_start = mi_s - 1  # 1-indexed → 0-indexed
            for k, c in enumerate(centers):
                a = mi_start + c - win_n // 2
                b = a + win_n
                if a < 0 or b > eeg.shape[1]: continue
                for ch in range(n_ch):
                    # DENSIDADE, nao potencia somada: a janela de 0,5 s tem 2 a
                    # 3 bins e o repouso tem 10, e a razao entre potencias
                    # somadas carregava esse desencontro inteiro.
                    p = SignalProcessor.compute_band_density(
                        eeg[ch, a:b], band_low, band_high, sr)
                    p_base = baseline_pwr_per_ch[ch] if ch < len(baseline_pwr_per_ch) else 1e-9
                    # Janela sem estimativa válida (NaN) não entra na média:
                    # tratada como 0, ela arrastava o ERD% para −100%.
                    if not np.isfinite(p) or not np.isfinite(p_base): continue
                    if p_base < 1e-12: continue
                    accum[ch, k] += (p - p_base) / p_base * 100.0
                    cnt[ch, k]   += 1
        # Instantes sem nenhum trial válido ficam NaN, não 0.0. Com zeros, o
        # gráfico desenhava uma linha em "ERD% = 0" exatamente onde NÃO houve
        # medida — indistinguível de uma ausência real de dessincronização.
        # Isso acontece sempre nas bordas do eixo (−1 s a +4 s), onde o trial
        # não cabe inteiro dentro do sinal.
        ersd = np.full((n_ch, T), np.nan)
        mask = cnt > 0
        ersd[mask] = accum[mask] / cnt[mask]
        return t_axis, ersd


# ============================================================
# Topografia — peças comuns às três vistas (2D, domo e tomografia)
# ============================================================
# Fração do raio da cabeça em que o eletrodo é desenhado. O campo usa a
# mesma escala: antes o disco ficava a 0,92 R e o pico do campo a 1,00 R, e a
# cor do disco não batia com o mapa logo embaixo dele.
_TOPO_ESCALA_EL = 0.92
# Grade do campo interpolado. As três vistas leem o MESMO campo (mesma
# spline, mesma grade): o domo e a tomografia só o reamostram.
_TOPO_GRADE = 160
# Campos já calculados, com limite: sem despejo, uma sessão longa ou um
# arrasto do domo encheriam a memória.
_TOPO_CAMPOS = {}
_TOPO_CAMPOS_MAX = 6
_TOPO_POS_CACHE = {}
_TOPO_TEXTO_CACHE = {}
# Lugar dos nomes dos eletrodos por (fonte, raio, posições, nomes): o dado
# novo não muda a posição dos discos, só a cor (ver _topo_nomes).
_TOPO_NOMES_CACHE = {}
_TOPO_LUTS = {}
# Escala DIVERGENTE do ERD%: azul = dessincronização (ERD, negativo), quase
# branco = zero, vermelho = sincronização (ERS). Azul para ERD é a convenção
# do próprio ROA no mapa ERSP. Com |ERD%| o ERS e o ERD de mesmo tamanho
# saíam com a mesma cor.
_TOPO_DIVERGENTE = ((33, 102, 172), (103, 169, 207), (247, 247, 247),
                    (239, 138, 98), (178, 24, 43))
# Spline esférica (Perrin et al., 1989; a do EEGLAB e do MNE), m = 4. A IDW
# 1/d² dava a CADA eletrodo um platô de derivada nula: eletrodo isolado virava
# alvo de anéis e um foco só aparecia como dois. A matriz grade x eletrodos só
# depende das posições e fica em cache; por quadro sobra um produto
# matriz-vetor. Sem regularização: a spline passa EXATAMENTE pelo valor de
# cada eletrodo (com lambda 1e-5 o erro chegava a 7% da escala com 16 canais
# e o disco não batia com o mapa embaixo dele). 20 termos: com 10, o sistema
# de 64 canais ficava mal condicionado.
_TOPO_SPLINE = {}
_TOPO_SPLINE_MAX = 4
_TOPO_SPLINE_TERMOS = 20
_TOPO_G_TABELA = None


def _topo_lut(ancoras=None):
    """Tabela 256 x 3 (uint8) interpolada nas âncoras (viridis por padrão, as
    mesmas de HeadPlotWidget._color_for_power).

    Nasce no primeiro uso, não no main(): o Offline, o ERS/ERD e os testes
    criam o widget sem passar por ele.
    """
    anc_t = tuple(ancoras or HeadPlotWidget._VIRIDIS)
    lut = _TOPO_LUTS.get(anc_t)
    if lut is None:
        anc = np.array(anc_t, dtype=np.float64)
        x = np.linspace(0.0, len(anc) - 1.0, 256)
        i = np.clip(x.astype(np.int32), 0, len(anc) - 2)
        fr = (x - i)[:, None]
        lut = np.clip(anc[i] * (1.0 - fr) + anc[i + 1] * fr,
                      0, 255).astype(np.uint8)
        _TOPO_LUTS[anc_t] = lut
    return lut


def _topo_indice_cor(t):
    """Campo 0..1 -> índice da tabela viridis (NaN vai para o fundo)."""
    t = np.nan_to_num(np.asarray(t, dtype=np.float32), nan=0.0,
                      posinf=1.0, neginf=0.0)
    return np.clip(t * 255.0 + 0.5, 0, 255).astype(np.int32)


def _topo_pos(nome):
    """Posição 10-20 de um rótulo de canal, ou None.

    Aceita FP1, T3 e 'EEG C3-A1' pelo mesmo canonical_electrode do resto do
    programa: esses canais sumiam do mapa sem aviso.
    """
    if not nome:
        return None
    pos = ALL_ELECTRODES.get(nome)
    if pos is not None:
        return pos
    if nome not in _TOPO_POS_CACHE:
        if len(_TOPO_POS_CACHE) > 512:      # rótulos livres: não cresce sem fim
            _TOPO_POS_CACHE.clear()
        try:
            _TOPO_POS_CACHE[nome] = ALL_ELECTRODES.get(canonical_electrode(nome))
        except Exception:
            _TOPO_POS_CACHE[nome] = None
    return _TOPO_POS_CACHE[nome]


def _topo_vetor(valores, n):
    """Os n primeiros valores como float; o que faltar ou não for número vira
    NaN (e fica fora do mapa, em vez de derrubar o desenho)."""
    out = np.full(max(0, int(n)), np.nan)
    for i, v in enumerate(list(valores or [])[:out.size]):
        try:
            out[i] = float(v)
        except (TypeError, ValueError):
            pass
    return out


def _topo_floats(valores):
    """Lista de float para raw_values; entrada inválida vira NaN e a lista é
    completada até MAX_CHANNELS (lista curta dava IndexError no desenho)."""
    out = []
    for v in list(valores or []):
        try:
            out.append(float(v))
        except (TypeError, ValueError):
            out.append(float("nan"))
    return out + [float("nan")] * (MAX_CHANNELS - len(out))


def _topo_esfera(x, y):
    """Ponto do desenho (projeção azimutal equidistante; o eletrodo da borda,
    a 90 graus do vértice, fica em _TOPO_ESCALA_EL) -> ponto na esfera."""
    x = np.asarray(x, dtype=np.float64)
    y = np.asarray(y, dtype=np.float64)
    th = np.hypot(x, y) / _TOPO_ESCALA_EL * (np.pi / 2.0)
    fi = np.arctan2(y, x)
    s = np.sin(th)
    return np.stack([s * np.cos(fi), s * np.sin(fi), np.cos(th)], axis=-1)


def _topo_g_spline(cosg):
    """g(cos γ) da spline esférica com m = 4 (recorrência de Legendre)."""
    cosg = np.clip(cosg, -1.0, 1.0)
    p_ant = np.ones_like(cosg)
    p = cosg.copy()
    g = np.zeros_like(cosg)
    for n in range(1, _TOPO_SPLINE_TERMOS + 1):
        g += ((2.0 * n + 1.0) / float((n * (n + 1)) ** 4)) * p
        p_ant, p = p, ((2.0 * n + 1.0) * cosg * p - n * p_ant) / (n + 1.0)
    return g / (4.0 * np.pi)


def _topo_g_tabelado(cosg):
    """g(cos γ) por interpolação numa tabela de 20 001 pontos: para a grade
    (25 600 pixels x eletrodos) a recorrência custava ~0,5 s com 64 canais.
    Erro dentro da cabeça abaixo de 1/255 da escala."""
    global _TOPO_G_TABELA
    if _TOPO_G_TABELA is None:
        xs = np.linspace(-1.0, 1.0, 20001)
        _TOPO_G_TABELA = (xs, _topo_g_spline(xs))
    xs, gs = _TOPO_G_TABELA
    return np.interp(np.ravel(cosg), xs, gs).reshape(np.shape(cosg))


def _topo_spline_base(pts, n):
    """(inversa do sistema da spline, matriz grade x eletrodos), em cache
    pelas posições: o dado muda a cada quadro, a montagem quase nunca."""
    chave = (n, pts)
    base = _TOPO_SPLINE.pop(chave, None)
    if base is None:
        e = _topo_esfera([q[0] for q in pts], [q[1] for q in pts])
        E = len(pts)
        A = np.zeros((E + 1, E + 1))
        A[:E, :E] = _topo_g_spline(e @ e.T)
        A[:E, E] = 1.0
        A[E, :E] = 1.0
        try:
            A_inv = np.linalg.inv(A)
            if not np.all(np.isfinite(A_inv)):
                raise np.linalg.LinAlgError
        except np.linalg.LinAlgError:
            # dois canais na mesma posição: mínimos quadrados (média deles)
            A_inv = np.linalg.pinv(A)
        g = np.linspace(-1.0, 1.0, n)
        gx, gy = np.meshgrid(g, -g)          # linha 0 = frente (y = +1)
        # Fora do eletrodo mais externo o pixel repete o valor da spline no
        # raio desse eletrodo, na mesma direção (extensão radial): lá não há
        # medida, e a spline livre inventava um anel no máximo da escala.
        rho_el = max(0.3, max(math.hypot(q[0], q[1]) for q in pts))
        rho = np.hypot(gx, gy)
        fator = np.minimum(1.0, rho_el / np.maximum(rho, 1e-9))
        gx, gy = gx * fator, gy * fator
        grade = _topo_esfera(gx.ravel(), gy.ravel()).astype(np.float32)
        Gx = _topo_g_tabelado(grade @ e.T.astype(np.float32)).astype(np.float32)
        base = (A_inv, Gx)
        while len(_TOPO_SPLINE) >= _TOPO_SPLINE_MAX:
            _TOPO_SPLINE.pop(next(iter(_TOPO_SPLINE)))
    _TOPO_SPLINE[chave] = base
    return base


def _topo_campo(pts, vals, n=None):
    """Campo interpolado por spline esférica numa grade n x n que cobre o
    quadrado [-1, 1]²; linha 0 = frente (y = +1), coluna 0 = esquerda.

    pts já na escala do desenho (_TOPO_ESCALA_EL) e vals em 0..1, como
    tuplas. O campo é cortado na faixa MEDIDA (menor e maior eletrodo): a
    spline pode passar do máximo entre eletrodos, e a cor não pode mostrar
    um valor que nenhum eletrodo mediu.
    """
    n = int(n or _TOPO_GRADE)
    chave = (n, tuple(pts), tuple(vals))
    campo = _TOPO_CAMPOS.pop(chave, None)
    if campo is None:
        if not len(vals):
            campo = np.zeros((n, n), np.float32)
        elif max(vals) == min(vals):
            # Valores iguais: a interpolação devolveria o mesmo número com
            # ruído de arredondamento, que a tomografia desenharia como
            # contorno falso.
            campo = np.full((n, n), float(vals[0]), dtype=np.float32)
        else:
            A_inv, Gx = _topo_spline_base(tuple(pts), n)
            E = len(vals)
            coef = A_inv @ np.append(np.asarray(vals, dtype=np.float64), 0.0)
            campo = (Gx @ coef[:E].astype(np.float32)
                     + np.float32(coef[E])).reshape(n, n)
            campo = np.clip(campo, min(vals), max(vals)).astype(np.float32)
        campo.setflags(write=False)
        while len(_TOPO_CAMPOS) >= _TOPO_CAMPOS_MAX:
            _TOPO_CAMPOS.pop(next(iter(_TOPO_CAMPOS)))
    _TOPO_CAMPOS[chave] = campo
    return campo


# Véu sobre o mapa longe de qualquer eletrodo. A spline é lisa mas não sabe
# onde há medida: com 8 canais e foco occipital o platô do máximo caía a 0,36
# do eletrodo mais próximo, e com foco em C3 surgia um máximo local de 10% da
# escala em T7, sem eletrodo. A cor esmaece em direção ao fundo da cabeça onde
# a COBERTURA dos eletrodos é baixa: soma de gaussianas de desvio 0,45 x o
# espaçamento da montagem (mediana da distância de cada eletrodo ao vizinho).
# Pela distância ao eletrodo mais próximo o véu desenhava as fronteiras entre
# eletrodos como riscos claros; com a soma, entre dois vizinhos a cobertura
# se soma e não há véu. A cor nunca some (o véu para em 60%). No tema
# escuro o fundo fica perto da ponta baixa da escala e o véu usa um cinza
# (_topo_cor_veu).
_TOPO_VEU_MAX = 0.60
_TOPO_VEU_SIGMA = 0.45    # desvio da gaussiana, em espaçamentos da montagem
_TOPO_VEU_INI = 0.05      # véu começa com cobertura abaixo de 0,95
_TOPO_VEU_FIM = 0.80      # e chega ao máximo com cobertura abaixo de 0,2
_TOPO_VEUS = {}


def _topo_veu(pts, n=None):
    """Opacidade do véu (0 a _TOPO_VEU_MAX) numa grade n x n igual à do campo
    (linha 0 = frente, coluna 0 = esquerda); pts na escala do desenho."""
    n = int(n or _TOPO_GRADE)
    chave = (n, tuple(pts))
    veu = _TOPO_VEUS.get(chave)
    if veu is None:
        P = np.asarray(pts, dtype=np.float64).reshape(-1, 2)
        if len(P) == 0:
            veu = np.zeros((n, n), np.float32)
        else:
            if len(P) > 1:
                D = np.hypot(P[:, None, 0] - P[None, :, 0],
                             P[:, None, 1] - P[None, :, 1])
                np.fill_diagonal(D, np.inf)
                esp = float(np.median(D.min(axis=1)))
            else:
                esp = 0.5
            sig = _TOPO_VEU_SIGMA * max(esp, 0.05)
            g = np.linspace(-1.0, 1.0, n)
            gx, gy = np.meshgrid(g, -g)
            cob = np.zeros(gx.shape)
            for px, py in P:
                cob += np.exp(-((gx - px) ** 2 + (gy - py) ** 2) / (2.0 * sig * sig))
            u = np.clip((1.0 - cob - _TOPO_VEU_INI)
                        / (_TOPO_VEU_FIM - _TOPO_VEU_INI), 0.0, 1.0)
            u = u * u * (3.0 - 2.0 * u)      # sem degrau na borda do véu
            veu = (u * _TOPO_VEU_MAX).astype(np.float32)
        veu.setflags(write=False)
        if len(_TOPO_VEUS) >= 8:
            _TOPO_VEUS.clear()
        _TOPO_VEUS[chave] = veu
    return veu


def _topo_cor_fundo():
    """Cor do fundo da cabeça (a mesma do contorno preenchido), em RGB."""
    c = QtGui.QColor(COLORS["surface_alt"])
    return np.array([c.red(), c.green(), c.blue()], dtype=np.float32)


# Distância RGB mínima entre a cor do véu e QUALQUER cor da escala. No tema
# escuro o fundo da cabeça (28,36,56) fica a 58 da ponta baixa da viridis
# (68,1,84): a área sem eletrodo saía roxo-escura, lida como potência baixa.
# Com o fundo perto da escala, o véu vai para um cinza neutro fora dela.
_TOPO_VEU_DIST_MIN = 100.0
_TOPO_CORES_VEU = {}


def _topo_cor_veu():
    """Cor para a qual o véu esmaece o mapa, em RGB: o fundo da cabeça se ele
    está longe da escala (temas claros); senão o cinza mais escuro, a partir
    do médio, que fica a _TOPO_VEU_DIST_MIN de toda a viridis."""
    chave = COLORS["surface_alt"]
    cor = _TOPO_CORES_VEU.get(chave)
    if cor is None:
        lut = _topo_lut().astype(np.float32)

        def dmin(c):
            return float(np.sqrt(((lut - c) ** 2).sum(axis=1)).min())
        cor = _topo_cor_fundo()
        if dmin(cor) < _TOPO_VEU_DIST_MIN:
            for g in range(128, 256, 4):
                cinza = np.full(3, float(g), np.float32)
                if dmin(cinza) >= _TOPO_VEU_DIST_MIN:
                    cor = cinza
                    break
        _TOPO_CORES_VEU[chave] = cor
    return cor


def _topo_aplica_veu(rgb, veu):
    """Mistura a cor do mapa com a cor do véu (_topo_cor_veu) na opacidade
    do véu."""
    v = np.asarray(veu, dtype=np.float32)[..., None]
    return np.clip(np.asarray(rgb, dtype=np.float32) * (1.0 - v)
                   + _topo_cor_veu() * v + 0.5, 0, 255).astype(np.uint8)


def _topo_amplia(campo, m):
    """Interpolação bilinear de um campo n x n para m x m (só numpy)."""
    n = campo.shape[0]
    pos = np.linspace(0.0, n - 1.0, int(m), dtype=np.float32)
    i0 = np.clip(pos.astype(np.int32), 0, n - 2)
    f = pos - i0.astype(np.float32)
    g = np.float32(1.0) - f
    lin = campo[i0, :] * g[:, None] + campo[i0 + 1, :] * f[:, None]
    return lin[:, i0] * g[None, :] + lin[:, i0 + 1] * f[None, :]


def _topo_qimage_rgba(buf):
    """QImage (ARGB32 premultiplicada, com cópia própria) de um array H x W x 4
    RGBA. A conversão copia os pixels: o buffer numpy pode ser liberado."""
    buf = np.ascontiguousarray(buf, dtype=np.uint8)
    h, w = buf.shape[:2]
    img = QtGui.QImage(buf.data, w, h, 4 * w, QtGui.QImage.Format.Format_RGBA8888)
    return img.convertToFormat(QtGui.QImage.Format.Format_ARGB32_Premultiplied)


def _topo_qimage_indice(idx, tabela):
    """QImage indexada (8 bits) de um array H x W de índices, com a tabela de
    cores 0xAARRGGBB e cópia própria. Poucas cores (as camadas): o Qt pinta
    direto da tabela, sem o numpy montar 4 bytes por pixel."""
    idx = np.ascontiguousarray(idx, dtype=np.uint8)
    h, w = idx.shape
    img = QtGui.QImage(idx.data, w, h, w, QtGui.QImage.Format.Format_Indexed8)
    img.setColorTable([int(c) for c in tabela])
    return img.copy()


def _topo_rect_amostras(x, y, lado, n):
    """Retângulo onde desenhar uma imagem de n pixels cujo centro do pixel k
    é a amostra k de linspace(-1, 1, n): sobra meio pixel de cada lado.
    Sem isso o mapa ficava até meio pixel da grade fora do lugar."""
    e = lado / (2.0 * max(1, n - 1))
    return QtCore.QRectF(x - e, y - e, lado + 2 * e, lado + 2 * e)


def _topo_recorta(imagem, caminho):
    """Apaga, com antialiasing, tudo o que fica fora de `caminho`.

    setClipPath recorta por pixel inteiro (daí a borda serrilhada). Aqui se
    apaga o COMPLEMENTO em DestinationOut: a cobertura parcial da borda vira
    alfa e o contorno sai liso. Desenhar o próprio caminho em DestinationIn
    não serve: o modo só age nos pixels que o pincel toca.
    """
    fora = QtGui.QPainterPath()
    fora.addRect(QtCore.QRectF(-2.0, -2.0, imagem.width() + 4.0,
                               imagem.height() + 4.0))
    fora.addPath(caminho)
    fora.setFillRule(QtCore.Qt.FillRule.OddEvenFill)
    q = QtGui.QPainter(imagem)
    q.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
    q.setCompositionMode(QtGui.QPainter.CompositionMode.CompositionMode_DestinationOut)
    q.setPen(QtCore.Qt.PenStyle.NoPen)
    q.setBrush(QtGui.QBrush(QtGui.QColor(0, 0, 0, 255)))
    q.drawPath(fora)
    q.end()
    return imagem


def _topo_texto(p, cx, cy, texto, fonte, fundo, largura=2.6):
    """Texto centrado em (cx, cy) com contorno de contraste, sem tarja.

    A cor sai da luminância WCAG de `fundo` (_text_on) e o contorno é a cor
    oposta: legível em qualquer ponto da viridis sem cobrir o mapa, como a
    cápsula branca cobria.
    """
    if not texto:
        return
    # O contorno dos glifos é guardado centrado na origem e só transladado:
    # refazer addText de 64 nomes a cada quadro custava ~4 ms.
    chave = (texto, fonte.key())
    base = _TOPO_TEXTO_CACHE.get(chave)
    if base is None:
        if len(_TOPO_TEXTO_CACHE) > 512:
            _TOPO_TEXTO_CACHE.clear()
        fm = QtGui.QFontMetricsF(fonte)
        base = QtGui.QPainterPath()
        base.addText(QtCore.QPointF(-fm.horizontalAdvance(texto) / 2.0,
                                    (fm.ascent() - fm.descent()) / 2.0), fonte, texto)
        _TOPO_TEXTO_CACHE[chave] = base
    cam = base.translated(cx, cy)
    cor = HeadPlotWidget._text_on(fundo)
    halo = (QtGui.QColor(0, 0, 0, 205) if cor.lightness() > 127
            else QtGui.QColor(255, 255, 255, 205))
    caneta = QtGui.QPen(halo, largura)
    caneta.setJoinStyle(QtCore.Qt.PenJoinStyle.RoundJoin)
    p.setPen(caneta)
    p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
    p.drawPath(cam)
    p.setPen(QtCore.Qt.PenStyle.NoPen)
    p.setBrush(QtGui.QBrush(cor))
    p.drawPath(cam)


def _topo_fmt(v):
    """Número curto para o disco e a escala: três algarismos e nada de
    notação científica na faixa usual de potência."""
    try:
        v = float(v)
    except (TypeError, ValueError):
        return "—"
    if not math.isfinite(v):
        return "—"
    a = abs(v)
    if a >= 100:
        return f"{v:.0f}"
    if a >= 10:
        return f"{v:.1f}"
    if a >= 0.01 or a == 0:
        return f"{v:.2f}"
    return f"{v:.2g}"


def _topo_faixa_barra(w, cx, r):
    """Extremos x da barra de escala: da largura da cabeça (com piso para
    caberem os números e o aviso), nunca além das margens do widget."""
    meia = max(1.25 * r, 170.0)
    return max(40.0, cx - meia), min(w - 40.0, cx + meia)


# Largura da coluna da barra em pé (barra + números com unidade + aviso).
_TOPO_COLUNA_BARRA = 170.0


def _topo_textos_barra(vmin, vmax, plano, unidade="", divergente=False):
    """(texto da ponta baixa, da ponta alta, aviso ou None), com a unidade.

    Quadro 'plano' só diz "sem variação" quando os eletrodos são iguais de
    fato; abaixo de 1% da escala ele diz "variação < 1%" e as pontas mostram
    o menor e o maior valor de verdade (antes mostravam a média nas duas e os
    discos, números diferentes)."""
    u = (" " + unidade) if unidade else ""
    if divergente:
        a = max(abs(float(vmin)), abs(float(vmax)))
        esq = tr("ERD · {0}").format(_topo_fmt(-a) + u)
        dir_ = tr("ERS · {0}").format("+" + _topo_fmt(a) + u)
    else:
        esq = tr("baixo · {0}").format(_topo_fmt(vmin) + u)
        dir_ = tr("alto · {0}").format(_topo_fmt(vmax) + u)
    aviso = None
    if plano:
        ref = max(1.0, abs(float(vmin)), abs(float(vmax)))
        aviso = (tr("sem variação entre eletrodos")
                 if abs(float(vmax) - float(vmin)) <= 1e-9 * ref
                 else tr("variação < 1% entre eletrodos"))
    return esq, dir_, aviso


def _topo_gradiente(grad, degraus, cor):
    """Paradas do gradiente: contínuo ou em faixas duras (camadas)."""
    if degraus:
        for k in range(degraus):
            c = cor((k + 0.5) / degraus)
            grad.setColorAt(k / float(degraus), c)
            grad.setColorAt(max(k / float(degraus), (k + 1) / float(degraus) - 1e-4), c)
    else:
        for k in range(17):
            grad.setColorAt(k / 16.0, cor(k / 16.0))


def _topo_barra(p, x0, x1, y, vmin, vmax, plano, degraus=None, unidade="",
                divergente=False, nota=None, cor=None):
    """Barra de cor com os NÚMEROS das pontas (e a unidade), igual nas três
    vistas.

    O domo e a tomografia não tinham escala nenhuma. Sem variação entre
    eletrodos uma marca aponta o meio da escala (a cor do mapa) e o aviso
    aparece no centro. `nota` troca os números por um texto: a fatia funda
    da tomografia não está na escala do escalpo. `cor` é a função t -> QColor
    da escala (viridis, ou a divergente do ERD%).
    """
    if x1 - x0 < 40:
        return
    cor = cor or HeadPlotWidget._color_for_power
    alt = 10.0
    grad = QtGui.QLinearGradient(x0, 0.0, x1, 0.0)
    _topo_gradiente(grad, degraus, cor)
    ret = QtCore.QRectF(x0, y, x1 - x0, alt)
    p.setPen(QtCore.Qt.PenStyle.NoPen)
    p.setBrush(QtGui.QBrush(grad))
    p.drawRoundedRect(ret, 3, 3)
    p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
    p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1))
    p.drawRoundedRect(ret, 3, 3)
    xm = (x0 + x1) / 2.0
    if nota:
        p.setFont(QtGui.QFont(FONT_UI, 8))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
        fm = QtGui.QFontMetricsF(p.font())
        p.drawText(QtCore.QRectF(x0, y + alt + 2, x1 - x0, 15),
                   QtCore.Qt.AlignmentFlag.AlignCenter,
                   fm.elidedText(nota, QtCore.Qt.TextElideMode.ElideRight, x1 - x0))
        return
    esq, dir_, aviso = _topo_textos_barra(vmin, vmax, plano, unidade, divergente)
    if plano or divergente:
        # marca no meio: a cor do quadro plano, ou o zero da escala divergente
        marca = QtGui.QPen(QtGui.QColor(COLORS["text"]), 2.2 if plano else 1.4)
        marca.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
        p.setPen(marca)
        p.drawLine(QtCore.QPointF(xm, y - 3), QtCore.QPointF(xm, y + alt + 3))
    p.setFont(QtGui.QFont(FONT_DATA, 8))
    p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
    fm = QtGui.QFontMetricsF(p.font())
    larg_ponta = max(fm.horizontalAdvance(esq), fm.horizontalAdvance(dir_))
    p.drawText(QtCore.QRectF(x0, y + alt + 2, larg_ponta + 4, 15),
               QtCore.Qt.AlignmentFlag.AlignLeft, esq)
    p.drawText(QtCore.QRectF(x1 - larg_ponta - 4, y + alt + 2, larg_ponta + 4, 15),
               QtCore.Qt.AlignmentFlag.AlignRight, dir_)
    if aviso:
        f_aviso = QtGui.QFont(FONT_UI, 8, QtGui.QFont.Weight.Bold)
        p.setFont(f_aviso)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["warning"])))
        fm_a = QtGui.QFontMetricsF(f_aviso)
        livre = (x1 - x0) - 2 * (larg_ponta + 10)
        if fm_a.horizontalAdvance(aviso) <= livre:
            p.drawText(QtCore.QRectF(x0, y + alt + 2, x1 - x0, 15),
                       QtCore.Qt.AlignmentFlag.AlignCenter, aviso)
        else:
            # não cabe entre os números: logo acima da barra, na largura toda
            p.drawText(QtCore.QRectF(x0, y - 16, x1 - x0, 14),
                       QtCore.Qt.AlignmentFlag.AlignCenter,
                       fm_a.elidedText(aviso, QtCore.Qt.TextElideMode.ElideRight, x1 - x0))
    elif divergente:
        p.drawText(QtCore.QRectF(xm - 20, y + alt + 2, 40, 15),
                   QtCore.Qt.AlignmentFlag.AlignCenter, "0")


def _topo_barra_v(p, x, y0, y1, larg, vmin, vmax, plano, degraus=None,
                  unidade="", divergente=False, nota=None, cor=None):
    """Barra EM PÉ à direita da cabeça, para quadro baixo e largo (1366x768,
    Offline, ERS/ERD): a cabeça fica com a altura inteira e os números da
    escala continuam à vista, sem rolar. Ponta alta em cima."""
    if y1 - y0 < 40 or larg < 40:
        return
    cor = cor or HeadPlotWidget._color_for_power
    lb = 10.0
    grad = QtGui.QLinearGradient(0.0, y1, 0.0, y0)
    _topo_gradiente(grad, degraus, cor)
    ret = QtCore.QRectF(x, y0, lb, y1 - y0)
    p.setPen(QtCore.Qt.PenStyle.NoPen)
    p.setBrush(QtGui.QBrush(grad))
    p.drawRoundedRect(ret, 3, 3)
    p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
    p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1))
    p.drawRoundedRect(ret, 3, 3)
    ym = (y0 + y1) / 2.0
    ao_lado = QtCore.QRectF(x + lb + 6, ym - 8, larg - lb - 6, 16)
    if nota:
        p.setFont(QtGui.QFont(FONT_UI, 8))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
        p.drawText(QtCore.QRectF(x + lb + 6, y0, larg - lb - 6, y1 - y0),
                   int(QtCore.Qt.AlignmentFlag.AlignVCenter
                       | QtCore.Qt.AlignmentFlag.AlignLeft)
                   | int(QtCore.Qt.TextFlag.TextWordWrap), nota)
        return
    esq, dir_, aviso = _topo_textos_barra(vmin, vmax, plano, unidade, divergente)
    if plano or divergente:
        marca = QtGui.QPen(QtGui.QColor(COLORS["text"]), 2.2 if plano else 1.4)
        marca.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
        p.setPen(marca)
        p.drawLine(QtCore.QPointF(x - 3, ym), QtCore.QPointF(x + lb + 3, ym))
    p.setFont(QtGui.QFont(FONT_DATA, 8))
    p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
    fm = QtGui.QFontMetricsF(p.font())
    p.drawText(QtCore.QRectF(x - 2, y0 - 17, larg + 2, 15),
               QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignBottom,
               fm.elidedText(dir_, QtCore.Qt.TextElideMode.ElideRight, larg + 2))
    p.drawText(QtCore.QRectF(x - 2, y1 + 2, larg + 2, 15),
               QtCore.Qt.AlignmentFlag.AlignLeft | QtCore.Qt.AlignmentFlag.AlignTop,
               fm.elidedText(esq, QtCore.Qt.TextElideMode.ElideRight, larg + 2))
    if aviso:
        f_aviso = QtGui.QFont(FONT_UI, 8, QtGui.QFont.Weight.Bold)
        p.setFont(f_aviso)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["warning"])))
        p.drawText(ao_lado, QtCore.Qt.AlignmentFlag.AlignLeft
                   | QtCore.Qt.AlignmentFlag.AlignVCenter,
                   QtGui.QFontMetricsF(f_aviso).elidedText(
                       aviso, QtCore.Qt.TextElideMode.ElideRight, ao_lado.width()))
    elif divergente:
        p.drawText(ao_lado, QtCore.Qt.AlignmentFlag.AlignLeft
                   | QtCore.Qt.AlignmentFlag.AlignVCenter, "0")


def _topo_nomes(p, itens, rr, fonte, largura=2.4):
    """Nomes dos eletrodos sem cobrir disco nem outro nome.

    itens = [(x, y, nome, cor_do_disco, opacidade)], discos de raio rr.
    Tenta acima, abaixo, à direita e à esquerda do disco; se nenhum lugar
    estiver livre, o nome não é desenhado (é melhor faltar que tapar o vizinho).
    """
    # A busca de lugar só depende de posição, nome, raio e fonte: guardada,
    # o quadro de dado novo só redesenha (64 canais: ~10 ms a menos no domo).
    chave = (fonte.key(), round(float(rr), 3),
             tuple((round(float(x), 3), round(float(y), 3), nome)
                   for x, y, nome, _c, _o in itens))
    lugares = _TOPO_NOMES_CACHE.get(chave)
    if lugares is None:
        lugares = _topo_nomes_lugares(itens, rr, fonte)
        if len(_TOPO_NOMES_CACHE) > 64:      # arrasto do domo: cada ângulo é um
            _TOPO_NOMES_CACHE.clear()        # jogo de posições; não acumula
        _TOPO_NOMES_CACHE[chave] = lugares
    for k, tx, ty in lugares:
        _x, _y, nome, cor, opac = itens[k]
        p.setOpacity(opac)
        _topo_texto(p, tx, ty, nome, fonte, cor, largura=largura)
    p.setOpacity(1.0)


def _topo_nomes_lugares(itens, rr, fonte):
    """Onde cada nome cabe: [(k, x, y)] dos itens que ganharam lugar."""
    fm = QtGui.QFontMetricsF(fonte)
    alt = fm.ascent() - fm.descent()
    r_obst = rr + 1.5
    centros = [(x, y) for x, y, _n, _c, _o in itens]
    postos = []
    lugares = []
    for k, (x, y, nome, cor, opac) in enumerate(itens):
        if not nome:
            continue
        lw = fm.horizontalAdvance(nome) + 3.0
        folga = rr + 3.0
        for tx, ty in ((x, y - folga - alt / 2.0), (x, y + folga + alt / 2.0),
                       (x + rr + 3.0 + lw / 2.0, y), (x - rr - 3.0 - lw / 2.0, y)):
            ret = QtCore.QRectF(tx - lw / 2.0, ty - alt / 2.0 - 2.0, lw, alt + 4.0)
            if any(o.intersects(ret) for o in postos):
                continue
            livre = True
            for kk, (dx, dy) in enumerate(centros):
                if kk == k:
                    continue
                qx = min(max(dx, ret.left()), ret.right())
                qy = min(max(dy, ret.top()), ret.bottom())
                if (qx - dx) ** 2 + (qy - dy) ** 2 < r_obst * r_obst:
                    livre = False
                    break
            if livre:
                postos.append(ret)
                lugares.append((k, tx, ty))
                break
    return lugares


def _topo_caminho_cabeca(cx, cy, r, orelha=1.07, nariz=1.10):
    """Contorno da cabeça, nariz e orelhas num caminho só (arcos e curvas).

    Eram três figuras soltas e a emenda do nariz e das orelhas com o círculo
    aparecia como degrau.
    """
    def pt(g, e=1.0):
        a = math.radians(g)
        return QtCore.QPointF(cx + math.cos(a) * r * e, cy - math.sin(a) * r * e)

    ret = QtCore.QRectF(cx - r, cy - r, 2 * r, 2 * r)
    c = QtGui.QPainterPath()
    c.moveTo(pt(84))
    c.quadTo(pt(88, 1.0 + (nariz - 1.0) * 0.55), pt(90, nariz))
    c.quadTo(pt(92, 1.0 + (nariz - 1.0) * 0.55), pt(96))
    c.arcTo(ret, 96, 76)
    c.cubicTo(pt(174, orelha + 0.03), pt(186, orelha + 0.03), pt(188))
    c.arcTo(ret, 188, 164)
    c.cubicTo(pt(354, orelha + 0.03), pt(6, orelha + 0.03), pt(8))
    c.arcTo(ret, 8, 76)
    c.closeSubpath()
    return c


# Casos do marching squares: arestas 0 = topo, 1 = direita, 2 = base,
# 3 = esquerda; bits a, b, c, d = cantos sup-esq, sup-dir, inf-dir, inf-esq.
_TOPO_MS_CASOS = {
    1: ((3, 0),), 2: ((0, 1),), 3: ((3, 1),), 4: ((1, 2),),
    5: ((3, 0), (1, 2)), 6: ((0, 2),), 7: ((2, 3),), 8: ((2, 3),),
    9: ((0, 2),), 10: ((0, 1), (2, 3)), 11: ((1, 2),), 12: ((1, 3),),
    13: ((0, 1),), 14: ((3, 0),),
}


def _topo_isolinhas(V, nivel):
    """Isolinha `nivel` do campo V como polilinhas CONTÍNUAS.

    Marching squares só nas células que o nível atravessa; os segmentos são
    encadeados pela aresta que compartilham. Em segmentos soltos cada pedaço
    recebia antialiasing sozinho e a linha saía granulada nas juntas.
    Devolve uma lista de listas de (coluna, linha) fracionárias.
    """
    n_lin, n_col = V.shape
    acima = V > nivel
    code = (acima[:-1, :-1].astype(np.uint8)
            | (acima[:-1, 1:].astype(np.uint8) << 1)
            | (acima[1:, 1:].astype(np.uint8) << 2)
            | (acima[1:, :-1].astype(np.uint8) << 3))
    ls, cs = np.nonzero((code != 0) & (code != 15))
    if ls.size == 0:
        return []
    cod = code[ls, cs]
    va = V[ls, cs].astype(np.float64)
    vb = V[ls, cs + 1].astype(np.float64)
    vc = V[ls + 1, cs + 1].astype(np.float64)
    vd = V[ls + 1, cs].astype(np.float64)

    def fr(p0, p1):
        den = p1 - p0
        den = np.where(np.abs(den) < 1e-12, 1e-12, den)
        return np.clip((nivel - p0) / den, 0.0, 1.0)

    lf = ls.astype(np.float64)
    cf = cs.astype(np.float64)
    off = n_lin * n_col
    # id único por aresta da grade: a mesma aresta vista pelas duas células
    # vizinhas tem o mesmo id e o mesmo ponto (interpolado dos mesmos cantos)
    ex = (cf + fr(va, vb), cf + 1.0, cf + fr(vd, vc), cf)
    ey = (lf, lf + fr(vb, vc), lf + 1.0, lf + fr(va, vd))
    eid = (ls * n_col + cs, off + ls * n_col + cs + 1,
           (ls + 1) * n_col + cs, off + ls * n_col + cs)
    ponto = {}
    segs = []
    for caso, pares in _TOPO_MS_CASOS.items():
        m = cod == caso
        if not m.any():
            continue
        for a, b in pares:
            ia = eid[a][m].tolist()
            ib = eid[b][m].tolist()
            ponto.update(zip(ia, zip(ex[a][m].tolist(), ey[a][m].tolist())))
            ponto.update(zip(ib, zip(ex[b][m].tolist(), ey[b][m].tolist())))
            segs.extend(zip(ia, ib))
    viz = {}
    for k, (a, b) in enumerate(segs):
        viz.setdefault(a, []).append(k)
        viz.setdefault(b, []).append(k)
    usado = [False] * len(segs)
    linhas = []
    for k0 in range(len(segs)):
        if usado[k0]:
            continue
        usado[k0] = True
        cadeia = list(segs[k0])
        for _lado in (0, 1):
            ponta = cadeia[-1]
            while True:
                prox = None
                for k in viz.get(ponta, ()):
                    if not usado[k]:
                        prox = k
                        break
                if prox is None:
                    break
                usado[prox] = True
                a, b = segs[prox]
                ponta = b if a == ponta else a
                cadeia.append(ponta)
            cadeia.reverse()
        linhas.append([ponto[e] for e in cadeia])
    return linhas


def _topo_argb(cor):
    """QColor -> inteiro 0xAARRGGBB opaco (pixel de QImage ARGB32)."""
    return (0xFF000000 | (cor.red() << 16) | (cor.green() << 8) | cor.blue())


def _topo_logar_falha(widget):
    """Um quadro ruim não pode derrubar a aba nem encher o log a cada 0,5 s:
    registra a primeira falha de cada widget e segue."""
    if not getattr(widget, "_falha_logada", False):
        widget._falha_logada = True
        logging.getLogger("eeg").exception("topografia: falha ao desenhar %s",
                                           type(widget).__name__)


# ============================================================
# HeadPlotWidget — suporta 8 ou 16 eletrodos
# ============================================================
class HeadPlotWidget(QtWidgets.QWidget):
    """Head plot com 3 modos visuais:
       1) Eletrodos coloridos por potência (dots)
       2) Mapa de calor INTERPOLADO (spline esférica) sobre o couro cabeludo
       3) Ambos sobrepostos (default)
    O mapeamento CH -> nome de eletrodo eh dinâmico (do AppConfig)."""

    HEATMAP_GRID = _TOPO_GRADE  # resolucao do campo interpolado (NxN)
    # Potência de banda = integral da PSD (µV²/Hz x Hz). A barra não tinha
    # unidade; quem usa outra grandeza troca na instância (ERD%: "%").
    unidade = "µV²"

    def __init__(self, parent=None):
        """Monta o head plot 2D com 8 canais, mapeamento 10-20 default e as duas
        camadas visuais (mapa de calor e eletrodos) ligadas.

        raw_values guarda o valor original escrito dentro de cada eletrodo e
        powers guarda a versão normalizada 0..1 usada nas cores; são listas de
        MAX_CHANNELS posições, independentes de num_channels.
        """
        super().__init__(parent)
        self.powers = [0.0] * MAX_CHANNELS
        self.raw_values = [0.0] * MAX_CHANNELS
        self.num_channels = BASE_CHANNELS
        self.band_name = "Alpha"
        self.show_heatmap = True
        self.show_dots = True
        self.map_mode = "interp"   # "interp" (potencial) | "csd" (Laplaciano)
        self.expected_channels = set()   # índices a DESTACAR (ex.: área esperada da MI)
        # Cores por min-max do quadro. O head plot de ERD% desliga isto
        # (autoscale_min = False), porque lá o zero tem significado próprio.
        self.autoscale_min = True
        self._disp_range = (0.0, 0.0)    # (menor, maior) valor bruto do quadro
        self._plano = False              # quadro sem variação entre eletrodos
        self._validos = []               # canal tem valor e posição no 10-20
        self._campo_chave = ((), ())     # (pontos, valores) do campo
        self._img_cache = None           # (chave, imagem recortada)
        # Canais a partir de BASE_CHANNELS vêm do módulo de expansão. Antes
        # isso era um anel verde, que sumia sobre o disco verde-azulado e não
        # tinha legenda; agora vai na dica de ferramenta do eletrodo. No
        # ERS/ERD (canais de um arquivo) fica desligado.
        self.mostra_borda_expansao = True
        # "relativa" (min-max do quadro) ou "divergente" (ERD%: zero no meio,
        # sinal preservado; a cor e o número mostram ERD e ERS diferentes).
        self.escala = "relativa"
        self.rotulo_modo = None          # título no lugar de POTÊNCIA (ex.: "ERD%")
        self._mostra = np.zeros(0)       # número escrito em cada disco (= a cor)
        self._alvos = []                 # (x, y, raio, canal) p/ a dica do eletrodo
        # Mapeamento default; sera atualizado por set_mapping()
        self.mapping = list(DEFAULT_MAPPING)
        # 260x240 é o piso em que o desenho ainda cabe (r = min(w,h)/2 - 56).
        # Com 420x420 de mínimo o widget estourava o painel do Layout Custom:
        # 155 px ficavam fora, sumindo O1/O2 e a barra de legenda inteira.
        self.setMinimumSize(260, 240)
        self.setToolTip(tr("Cores relativas a este quadro. A ponta escura é o "
                           "menor valor medido e a ponta clara, o maior."))
        self.setStyleSheet(f"background-color: {COLORS['surface']};")
        self._recompute_display()

    def set_num_channels(self, n):
        """Ajusta quantos eletrodos são desenhados, renormaliza e repinta.

        A escala é refeita já aqui: com o número novo de canais o menor e o
        maior valor do quadro podem mudar.
        """
        self.num_channels = max(0, min(int(n), MAX_CHANNELS))
        self._recompute_display()
        self.update()

    def set_mapping(self, mapping):
        """Define qual eletrodo (do 10-20) cada canal CHn ocupa."""
        if isinstance(mapping, (list, tuple)) and len(mapping) == MAX_CHANNELS:
            self.mapping = list(mapping)
            self._recompute_display()
            self.update()

    def set_show_heatmap(self, on):
        """Liga ou desliga a camada de mapa de calor interpolado."""
        self.show_heatmap = bool(on); self.update()

    def set_show_dots(self, on):
        """Liga ou desliga o desenho dos eletrodos sobre o mapa."""
        self.show_dots = bool(on); self.update()

    def set_powers(self, values, band_name="Alpha"):
        """Recebe a potência por canal da banda selecionada e atualiza o head
        plot.

        Guarda os valores brutos (escritos dentro de cada eletrodo) e chama
        _recompute_display, que estica a escala entre o menor e o maior valor
        do próprio quadro — as cores são relativas, não absolutas, e as pontas
        da legenda mostram os dois números. O mapa em si só é calculado ao
        pintar: numa aba oculta, set_powers custa quase nada.
        """
        self.raw_values = _topo_floats(values)
        self.band_name = band_name
        self._recompute_display()
        self.update()

    def set_expected_channels(self, ch_indices):
        """Marca (com anel de destaque) os canais/eletrodos ESPERADOS — ex.: a
        área sensoriomotora contralateral de uma classe de imaginação motora."""
        self.expected_channels = set(int(i) for i in (ch_indices or [])
                                     if 0 <= int(i) < MAX_CHANNELS)
        self.update()

    def set_map_mode(self, mode):
        """Modo do mapa: 'interp' (potencial de escalpo, IDW) ou 'csd'
        (Laplaciano de superfície — realça fontes locais, reduz condução de
        volume [McFarland 1997; Nunez & Srinivasan 2006])."""
        self.map_mode = "csd" if str(mode).lower().startswith("csd") else "interp"
        self._recompute_display()
        self.update()

    def _nome(self, i):
        """Rótulo do canal i no mapeamento atual."""
        return self.mapping[i] if i < len(self.mapping) else f"CH{i+1}"

    def _recompute_display(self):
        """Recalcula os valores 0..1 exibidos, conforme o modo (interp/CSD) e
        a escala (relativa/divergente).

        Só entram na escala os canais com valor finito e posição no 10-20:
        um canal sem posição com o maior valor deixava o mapa inteiro escuro.
        Guarda em _mostra o número que vai no disco: no CSD é o próprio |CSD|
        (antes o disco mostrava a potência bruta pintada na cor do |CSD|).
        """
        n = max(0, min(int(self.num_channels), MAX_CHANNELS))
        raw = _topo_vetor(self.raw_values, n)
        pos = [_topo_pos(self._nome(i)) for i in range(n)]
        ok = [i for i in range(n) if pos[i] is not None and np.isfinite(raw[i])]
        if self.escala == "divergente":
            vals = raw[ok]
            a = float(np.max(np.abs(vals))) if len(ok) else 0.0
            if a > 0:
                t = np.clip(0.5 + 0.5 * vals / a, 0.0, 1.0)
            else:
                t = np.full(vals.shape, 0.5)
            vmin, vmax, plano = -a, a, a <= 0
        else:
            if self.map_mode == "csd" and len(ok) >= 4:
                xy = np.array([pos[i] for i in ok], dtype=float)
                rv = raw[ok]
                k = min(4, len(ok) - 1)
                csd = rv.copy()
                for j in range(len(ok)):
                    d2 = np.sum((xy - xy[j]) ** 2, axis=1); d2[j] = np.inf
                    nn = np.argsort(d2)[:k]
                    csd[j] = rv[j] - float(np.mean(rv[nn]))
                vals = np.abs(csd)                       # magnitude da fonte local
            else:
                vals = np.clip(raw[ok], 0.0, None)
            t, vmin, vmax, plano = HeadPlotWidget._escala(vals, self.autoscale_min)
        disp = np.zeros(n)
        disp[ok] = t
        mostra = np.full(n, np.nan)
        mostra[ok] = vals
        self._mostra = mostra
        self._disp_range = (vmin, vmax)
        self._plano = bool(plano)
        validos = [False] * n
        for i in ok:
            validos[i] = True
        self._validos = validos
        S = _TOPO_ESCALA_EL
        self._campo_chave = (
            tuple((round(pos[i][0] * S, 6), round(pos[i][1] * S, 6)) for i in ok),
            tuple(round(float(x), 9) for x in t))
        self.powers = [float(x) for x in disp] + [0.0] * (MAX_CHANNELS - n)

    def _texto_valor(self, i):
        """Texto do valor escrito dentro do disco do eletrodo i: o mesmo número
        que dá a cor (potência, |CSD| ou ERD% com sinal)."""
        if i < len(self._validos) and self._validos[i] and i < len(self._mostra):
            v = self._mostra[i]
            txt = _topo_fmt(v)
            if self.escala == "divergente" and np.isfinite(v) and v > 0:
                txt = "+" + txt
            return txt
        return "—"

    def _ancoras(self):
        """Âncoras da escala de cor deste widget."""
        return _TOPO_DIVERGENTE if self.escala == "divergente" else self._VIRIDIS

    def _cor(self, t):
        """Cor do valor normalizado t na escala deste widget."""
        return HeadPlotWidget._cor_ancoras(t, self._ancoras())

    def event(self, ev):
        """Dica de ferramenta por eletrodo: nome, valor com unidade e, no
        Tempo Real, se o canal é do módulo de expansão. Com muitos canais o
        valor não cabe no disco e só aparece aqui."""
        if ev.type() == QtCore.QEvent.Type.ToolTip:
            try:
                txt = self._dica_eletrodo(ev.pos())
            except Exception:
                txt = None
            if txt:
                QtWidgets.QToolTip.showText(ev.globalPos(), txt, self)
                return True
        return super().event(ev)

    def _dica_eletrodo(self, pos):
        """Texto da dica do eletrodo sob `pos` (ou None fora dos discos)."""
        melhor = None
        for ex, ey, raio, i in self._alvos:
            d2 = (pos.x() - ex) ** 2 + (pos.y() - ey) ** 2
            if d2 <= (raio + 3) ** 2 and (melhor is None or d2 < melhor[0]):
                melhor = (d2, i)
        if melhor is None:
            return None
        i = melhor[1]
        linha = "%s: %s" % (self._nome(i), self._texto_valor(i))
        if self.unidade and self._texto_valor(i) != "—":
            linha += " " + self.unidade
        if self.mostra_borda_expansao and i >= BASE_CHANNELS:
            linha += "\n" + tr("módulo de expansão")
        return linha

    # ----- mapa de calor (spline esférica) --------------------------
    def _compute_heatmap_image(self, r_px=None):
        """Campo interpolado como QImage NxN (fora do disco, transparente)."""
        pts, vals = self._campo_chave
        campo = _topo_campo(pts, vals)
        n = campo.shape[0]
        buf = np.zeros((n, n, 4), np.uint8)
        buf[..., :3] = _topo_lut()[_topo_indice_cor(campo)]
        u = np.linspace(-1.0, 1.0, n)
        buf[..., 3] = np.where((u[None, :] ** 2 + u[:, None] ** 2) <= 1.0, 236, 0)
        return _topo_qimage_rgba(buf)

    def _imagem_mapa(self, lado):
        """Mapa colorido em `lado` px, com a borda do disco antialiasada.

        Três trocas em relação ao desenho antigo: o laço de setPixelColor
        (9 216 chamadas por quadro) virou indexação na tabela de cor; o disco
        sai por máscara vetorial, não por setClipPath; e a imagem só é refeita
        quando o dado, a escala ou o tamanho mudam.
        """
        chave = (self._campo_chave, lado, self.escala, COLORS["surface_alt"])
        if self._img_cache is not None and self._img_cache[0] == chave:
            return self._img_cache[1]
        pts, vals = self._campo_chave
        campo = _topo_campo(pts, vals)
        n = campo.shape[0]
        buf = np.empty((n, n, 4), np.uint8)
        # véu longe dos eletrodos: lá o valor é só interpolado (_topo_veu).
        # Quadro plano fica sem véu: sem variação não há valor a atribuir, e
        # o véu desenharia "ilhas" em volta dos eletrodos num mapa uniforme.
        rgb = _topo_lut(self._ancoras())[_topo_indice_cor(campo)]
        buf[..., :3] = rgb if self._plano else _topo_aplica_veu(rgb, _topo_veu(pts, n))
        # Opaco: com alfa 236 o fundo clareava o mapa e o mesmo valor saía com
        # uma cor no 2D e outra no domo e na tomografia (e na barra).
        buf[..., 3] = 255
        pequena = _topo_qimage_rgba(buf)
        grande = QtGui.QImage(lado, lado, QtGui.QImage.Format.Format_ARGB32_Premultiplied)
        grande.fill(0)
        q = QtGui.QPainter(grande)
        q.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        q.drawImage(_topo_rect_amostras(0.0, 0.0, float(lado), n), pequena)
        q.end()
        disco = QtGui.QPainterPath()
        disco.addEllipse(QtCore.QRectF(0.5, 0.5, lado - 1.0, lado - 1.0))
        _topo_recorta(grande, disco)
        self._img_cache = (chave, grande)
        return grande

    def paintEvent(self, ev):
        """Desenha o head plot 2D inteiro: mapa de calor, contorno da cabeça com
        nariz e orelhas, eletrodos com valor dentro e nome ao lado, e a barra
        de escala com números e unidade.

        Eletrodos em expected_channels ganham um anel extra; o módulo de
        expansão aparece na dica de ferramenta de cada eletrodo.
        """
        p = QtGui.QPainter(self)
        try:
            self._pinta(p)
        except Exception:
            _topo_logar_falha(self)
        finally:
            p.end()

    def _disposicao(self, w, h):
        """(cx, cy, r, vertical): em quadro baixo e largo a barra vai para a
        direita da cabeça e a cabeça ganha a altura toda. A 1366x768 e no
        Offline a barra com os números só aparecia rolando."""
        r_h = max(20.0, min(w, h) / 2.0 - 56)
        col = _TOPO_COLUNA_BARRA
        r_v = max(20.0, min((h - 34.0) / 2.1, (w - col - 24.0) / 2.2))
        if r_v > 1.25 * r_h:
            cy = 26.0 + max(0.0, (h - 34.0 - 2.1 * r_v) / 2.0) + 1.1 * r_v
            return (w - col) / 2.0, cy, r_v, True
        if h > w + 80:
            # alto e estreito: cabeça encostada no título (nariz incluso)
            return w / 2.0, 30.0 + 1.12 * r_h, r_h, False
        return w / 2.0, h / 2.0 + 6, r_h, False

    def _pinta(self, p):
        """Corpo do paintEvent (separado para o paintEvent nunca vazar exceção)."""
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.TextAntialiasing, True)
        w, h = self.width(), self.height()
        cx, cy, r, vertical = self._disposicao(w, h)
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        n = max(0, min(int(self.num_channels), MAX_CHANNELS))
        tem_dado = any(self._validos[:n])

        cabeca = _topo_caminho_cabeca(cx, cy, r)
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
        p.drawPath(cabeca)
        # ----- Mapa de calor interpolado (atras dos eletrodos) -----
        if self.show_heatmap and tem_dado:
            dpr = float(p.device().devicePixelRatioF() or 1.0)
            lado = int(min(1600, max(32, round(2 * r * dpr))))
            p.drawImage(QtCore.QRectF(cx - r, cy - r, 2 * r, 2 * r),
                        self._imagem_mapa(lado))
        # Contorno: traço escuro por fora e claro por dentro. Um traço só
        # some numa das pontas da viridis (roxo quase preto ou amarelo).
        p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
        p.setPen(QtGui.QPen(QtGui.QColor(12, 16, 22, 170), 3.6))
        p.drawPath(_topo_caminho_cabeca(cx, cy, r + 1.4))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"]), 2.0))
        p.drawPath(cabeca)

        # Titulo (interface — Inter)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["accent"])))
        title_font = QtGui.QFont(FONT_UI, 11, QtGui.QFont.Weight.Bold)
        p.setFont(title_font)
        if self.rotulo_modo is not None:
            mode_txt = self.rotulo_modo
        else:
            mode_txt = tr("CSD/LAPLACIANO") if self.map_mode == "csd" else tr("POTÊNCIA")
        p.drawText(QtCore.QRectF(0, 4, w, 18), QtCore.Qt.AlignmentFlag.AlignCenter,
                   f"{mode_txt} · {self.band_name.upper()}  ({self.num_channels}ch)")

        # ----- Eletrodos (dots) -----
        self._alvos = []
        if self.show_dots:
            self._pinta_eletrodos(p, cx, cy, r, n)

        # ----- Escala com os números -----
        if tem_dado:
            vmin, vmax = self._disp_range
            div = self.escala == "divergente"
            if vertical:
                col = _TOPO_COLUNA_BARRA
                xb = min(cx + 1.07 * r + 26.0, w - col + 20.0)
                _topo_barra_v(p, xb, cy - 0.72 * r, cy + 0.72 * r, w - xb - 8.0,
                              vmin, vmax, self._plano, unidade=self.unidade,
                              divergente=div, cor=self._cor)
            else:
                x0, x1 = _topo_faixa_barra(w, cx, r)
                # barra logo abaixo da cabeça (no quadro alto, não no rodapé)
                yb = min(h - 34.0, cy + r + 22.0)
                _topo_barra(p, x0, x1, yb, vmin, vmax, self._plano,
                            unidade=self.unidade, divergente=div, cor=self._cor)

    def _pinta_eletrodos(self, p, cx, cy, r, n):
        """Disco colorido com o VALOR dentro e o nome fora do disco.

        Três regras para nada ficar por cima de nada: o disco nunca passa de
        42% da distância ao vizinho mais próximo (com 64 canais eles se
        tocavam); o valor só entra se couber na CORDA do disco à altura do
        texto, num corpo único para o quadro inteiro (senão fica só na dica
        de ferramenta); e o nome vai acima, abaixo, à direita ou à esquerda,
        onde a caixa dele não cruzar outro disco nem outro nome. Se nada
        couber, o nome também fica só na dica (antes ele era escrito por cima
        do valor do disco da fileira de cima)."""
        S = _TOPO_ESCALA_EL
        itens = []
        for i in range(n):
            q = _topo_pos(self._nome(i))
            if q is not None:
                itens.append((i, cx + q[0] * r * S, cy - q[1] * r * S))
        if not itens:
            return
        nvis = len(itens)
        raio = 20.0 if nvis <= 8 else 18.0 if nvis <= 16 else 15.0 if nvis <= 32 else 12.0
        raio = min(raio, max(6.0, r * 0.10))
        if nvis >= 2:
            xy = np.array([(a[1], a[2]) for a in itens], dtype=float)
            d = np.sqrt(((xy[:, None, :] - xy[None, :, :]) ** 2).sum(axis=2))
            np.fill_diagonal(d, np.inf)
            raio = max(4.0, min(raio, 0.42 * float(d.min())))
        f_nome = QtGui.QFont(FONT_UI, 9 if nvis <= 8 else 8 if nvis <= 32 else 7,
                             QtGui.QFont.Weight.Bold)
        fm_nome = QtGui.QFontMetricsF(f_nome)
        # Valor: um corpo só para o quadro (antes 8/7/6 pt misturados), o
        # maior em que o PIOR texto caiba na corda do disco (caneta de 2 px e
        # 1 px de folga), medida à altura das maiúsculas.
        f_val = None
        if nvis <= 32 and raio >= 11:
            textos = [self._texto_valor(i) for i, _x, _y in itens]
            ri = raio - 2.0
            for pt in (8, 7, 6):
                f = QtGui.QFont(FONT_DATA, pt)
                fm = QtGui.QFontMetricsF(f)
                meia = (fm.capHeight() + 2.0) / 2.0
                if meia >= ri:
                    continue
                corda = 2.0 * math.sqrt(ri * ri - meia * meia) - 2.0
                if all(fm.horizontalAdvance(t) <= corda for t in textos):
                    f_val = f
                    break
        cores = {}
        for i, ex, ey in itens:
            valido = i < len(self._validos) and self._validos[i]
            color = (self._cor(self.powers[i]) if valido
                     else QtGui.QColor(COLORS["surface_alt"]))
            cores[i] = color
            cor_texto = HeadPlotWidget._text_on(color)
            # Anel de DESTAQUE nos eletrodos esperados (ex.: área da MI)
            if i in self.expected_channels:
                p.setBrush(QtGui.QBrush(QtCore.Qt.BrushStyle.NoBrush))
                caneta_anel = QtGui.QPen(QtGui.QColor(COLORS["accent"]), 2)
                caneta_anel.setStyle(QtCore.Qt.PenStyle.DashLine)
                p.setPen(caneta_anel)
                p.drawEllipse(QtCore.QPointF(ex, ey), raio + 4, raio + 4)
            p.setBrush(QtGui.QBrush(color))
            p.setPen(QtGui.QPen(cor_texto, 2))
            p.drawEllipse(QtCore.QPointF(ex, ey), raio, raio)
            self._alvos.append((ex, ey, raio, i))
            # Valor DENTRO do disco: o próprio disco é o fundo, sem tarja
            if f_val is not None:
                p.setFont(f_val)
                p.setPen(QtGui.QPen(cor_texto))
                p.drawText(QtCore.QRectF(ex - raio, ey - raio, 2 * raio, 2 * raio),
                           QtCore.Qt.AlignmentFlag.AlignCenter, self._texto_valor(i))
        # Nomes numa segunda passada, cada um onde não cobre disco nem nome.
        alt_txt = fm_nome.ascent() - fm_nome.descent()
        folga = raio + 5.0            # livre do anel tracejado (raio + 4)
        r_obst = raio + 1.5
        centros = [(ex, ey) for _i, ex, ey in itens]
        postos = []
        for k, (i, ex, ey) in enumerate(itens):
            nome = self._nome(i)
            if not nome:
                continue
            lw = fm_nome.horizontalAdvance(nome) + 3.0
            candidatos = ((ex, ey - folga - alt_txt / 2.0),
                          (ex, ey + folga + alt_txt / 2.0),
                          (ex + raio + 4.0 + lw / 2.0, ey),
                          (ex - raio - 4.0 - lw / 2.0, ey))
            for tx, ty in candidatos:
                ret = QtCore.QRectF(tx - lw / 2.0, ty - alt_txt / 2.0 - 2.0,
                                    lw, alt_txt + 4.0)
                livre = not any(o.intersects(ret) for o in postos)
                if livre:
                    for kk, (dx, dy) in enumerate(centros):
                        if kk == k:
                            continue
                        qx = min(max(dx, ret.left()), ret.right())
                        qy = min(max(dy, ret.top()), ret.bottom())
                        if (qx - dx) ** 2 + (qy - dy) ** 2 < r_obst * r_obst:
                            livre = False
                            break
                if livre:
                    postos.append(ret)
                    _topo_texto(p, tx, ty, nome, f_nome, cores[i])
                    break

    # Colormap perceptualmente uniforme (viridis) — seguro p/ daltonismo
    # (VIZ-09: nunca 'jet'/HSV, que distorce a leitura de magnitude).
    _VIRIDIS = ((68, 1, 84), (59, 82, 139), (33, 145, 140),
                (94, 201, 98), (253, 231, 37))

    @staticmethod
    def _escala(vals, com_minimo=True):
        """Escala 0..1 do quadro: devolve (array, menor, maior, plano).

        Sem variação (todos iguais, ou faixa abaixo de 1% do valor) o quadro
        é 'plano': tudo vai para o MEIO da escala. Antes caía na divisão pelo
        máximo e a cabeça inteira saía amarela, como se toda ela estivesse no
        pico. As pontas guardam o menor e o maior valor de verdade (a barra
        diz "variação < 1%"). Com com_minimo=False (zero como âncora) a escala
        vai de 0 ao maior valor, e um quadro todo zero fica na ponta baixa,
        que é o que o zero significa nessa escala.
        """
        arr = np.asarray(vals, dtype=float)
        if arr.size == 0:
            return arr, 0.0, 0.0, False
        vmin = float(np.min(arr)); vmax = float(np.max(arr))
        ref = max(abs(vmin), abs(vmax))
        if (vmax - vmin) <= 1e-12 or (vmax - vmin) < 0.01 * ref:
            if not com_minimo and ref <= 1e-12:
                return np.zeros(arr.shape), 0.0, 0.0, True
            return np.full(arr.shape, 0.5), vmin, vmax, True
        if com_minimo:
            return np.clip((arr - vmin) / (vmax - vmin), 0.0, 1.0), vmin, vmax, False
        base = vmax if vmax > 0 else 1.0
        return np.clip(arr / base, 0.0, 1.0), 0.0, vmax, False

    @staticmethod
    def _normaliza_minmax(vals, com_minimo=True):
        """Escala 0..1 entre o menor e o maior valor; devolve (array, menor, maior).

        Mesma regra de _escala (quadro plano vai ao meio da escala); fica por
        compatibilidade com quem só quer os três valores.
        """
        arr, vmin, vmax, _plano = HeadPlotWidget._escala(vals, com_minimo)
        return arr, vmin, vmax

    @staticmethod
    def _text_on(color):
        """Preto ou branco, conforme a luminância WCAG da cor de fundo.

        O nome do eletrodo era preto fixo: na faixa escura da viridis o
        contraste caía a 1,38:1, muito abaixo do mínimo de 4,5:1.
        """
        def _lin(c):
            c = c / 255.0
            return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
        lum = (0.2126 * _lin(color.red()) + 0.7152 * _lin(color.green())
               + 0.0722 * _lin(color.blue()))
        return QtGui.QColor("#000000") if lum > 0.18 else QtGui.QColor("#ffffff")

    @staticmethod
    def _cor_ancoras(t, lut):
        """Valor normalizado 0..1 -> cor, interpolando linearmente entre as
        âncoras `lut`. NaN vira o fundo da escala (antes caía no topo)."""
        t = float(t)
        if t != t:
            t = 0.0
        t = max(0.0, min(1.0, t))
        x = t * (len(lut) - 1)
        i = int(x)
        if i >= len(lut) - 1:
            r, g, b = lut[-1]
        else:
            a, c, fr = lut[i], lut[i + 1], x - i
            r = a[0] + (c[0] - a[0]) * fr
            g = a[1] + (c[1] - a[1]) * fr
            b = a[2] + (c[2] - a[2]) * fr
        return QtGui.QColor(int(r), int(g), int(b))

    @staticmethod
    def _color_for_power(t):
        """Converte um valor normalizado 0..1 na cor viridis correspondente,
        servindo as três vistas de topografia.

        Interpolacao linear entre 5 ancoras da viridis, escolhida por ser
        perceptualmente uniforme e segura para daltonismo (VIZ-09 proibe
        'jet'/HSV). HeadPlotWidget3D e HeadPlotWidgetCT chamam este método
        direto na classe HeadPlotWidget.
        """
        return HeadPlotWidget._cor_ancoras(t, HeadPlotWidget._VIRIDIS)


class _TopoPontos:
    """Normalização comum ao domo e à tomografia: mesma escala e mesmo campo
    do 2D no modo interpolado (as três vistas leem o mesmo campo)."""

    unidade = "µV²"       # potência de banda, como no 2D

    def _prepara_pontos(self):
        """Refaz escala, pontos e chave do campo a partir de raw_values."""
        n = max(0, min(int(self.num_channels), MAX_CHANNELS))
        raw = _topo_vetor(self.raw_values, n)
        nomes = [self.mapping[i] if i < len(self.mapping) else None for i in range(n)]
        pos = [_topo_pos(nm) for nm in nomes]
        idx = [i for i in range(n) if pos[i] is not None and np.isfinite(raw[i])]
        t, vmin, vmax, plano = HeadPlotWidget._escala(np.clip(raw[idx], 0.0, None))
        self._disp_range = (vmin, vmax)
        self._plano = bool(plano)
        self._idx = idx
        self._pos = {i: pos[i] for i in idx}
        self._norm = {i: float(t[k]) for k, i in enumerate(idx)}
        S = _TOPO_ESCALA_EL
        self._campo_chave = (
            tuple((round(pos[i][0] * S, 6), round(pos[i][1] * S, 6)) for i in idx),
            tuple(round(float(x), 9) for x in t))
        self._V = None               # o campo sai do cache ao pintar

    def _campo_atual(self):
        """O campo IDW do quadro (o mesmo array do 2D, vindo do cache)."""
        self._V = _topo_campo(*self._campo_chave)
        return self._V


# ============================================================
# HeadPlotWidget3D — topografia EEG pseudo-3D (domo rotacionável)
# ============================================================
class HeadPlotWidget3D(_TopoPontos, QtWidgets.QWidget):
    """Topografia EEG pseudo-3D: domo do escalpo (hemisfério) com a potência
    do MESMO campo do 2D + sombra só na borda + rotação por mouse.
    Traçado por pixel em numpy sobre a projeção esférica — sem PyOpenGL;
    roda no .exe."""

    GRID = _TOPO_GRADE     # o domo lê o campo do 2D nesta grade
    LADO_IMG = 380         # teto da resolução interna do domo (px)
    LADO_ARRASTO = 220     # durante o arrasto, mais leve; cheia ao soltar
    GEO_MAX = 3            # ângulos guardados no cache de geometria

    def __init__(self, parent=None):
        """Prepara o domo pseudo-3D: valores zerados e angulos iniciais de camera.

        pitch nasce em 0,42 rad (~24 graus): com 0,60 o occipital, onde mora
        o alfa de repouso, ficava atrás da borda do domo. O cursor de mão
        aberta sinaliza que o widget e arrastavel.
        """
        super().__init__(parent)
        self.raw_values = [0.0] * MAX_CHANNELS
        self.num_channels = BASE_CHANNELS
        self.mapping = list(DEFAULT_MAPPING)
        self.band_name = "Alpha"
        self.expected_channels = set()
        self.yaw = 0.0
        self.pitch = 0.42            # tilt inicial — vê o domo em 3D
        self._drag = None
        self._V = None               # campo do quadro (o mesmo do 2D)
        self._disp_range = (0.0, 0.0)
        self._plano = False
        self._geo = {}               # geometria por (lado, yaw, pitch), com limite
        self._img_cache = None
        self.setMinimumSize(420, 420)
        self.setToolTip(tr("Arraste na horizontal para girar a cabeça e na "
                           "vertical para inclinar."))
        self.setCursor(QtCore.Qt.CursorShape.OpenHandCursor)
        self._recompute()

    # ---- API (compatível com HeadPlotWidget) ----
    def set_num_channels(self, n):
        """Ajusta o número de eletrodos, renormaliza e repinta."""
        self.num_channels = max(0, min(int(n), MAX_CHANNELS))
        self._recompute(); self.update()

    def set_mapping(self, mapping):
        """Troca o mapeamento CH -> eletrodo 10-20 e renormaliza.

        Ignora a lista em silêncio se ela não tiver exatamente MAX_CHANNELS
        entradas.
        """
        if isinstance(mapping, (list, tuple)) and len(mapping) == MAX_CHANNELS:
            self.mapping = list(mapping); self._recompute(); self.update()

    def set_expected_channels(self, idx):
        """Marca com anel de destaque os canais esperados, por exemplo a area
        sensoriomotora da classe de imaginação motora."""
        self.expected_channels = set(int(i) for i in (idx or [])
                                     if 0 <= int(i) < MAX_CHANNELS)
        self.update()

    def set_powers(self, values, band_name="Alpha"):
        """Recebe a potência por canal da banda e repinta. O campo e a imagem
        do domo só são feitos ao pintar (aba oculta não paga nada)."""
        self.raw_values = _topo_floats(values)
        self.band_name = band_name
        self._recompute(); self.update()

    def set_map_mode(self, mode):
        """Existe so por compatibilidade de API com HeadPlotWidget: o domo sempre
        usa potencial interpolado e ignora o modo pedido."""
        pass   # o domo usa sempre potencial interpolado

    def _active_points(self):
        """Posições 2D (10-20, sem escala) e potências normalizadas dos canais
        com valor e posição, na ordem dos canais."""
        if not self._idx:
            return np.array([]), np.array([])
        return (np.array([self._pos[i] for i in self._idx], dtype=float),
                np.array([self._norm[i] for i in self._idx], dtype=float))

    def _recompute(self):
        """Refaz a escala do quadro (mesma regra do 2D, inclusive o caso plano)
        e a chave do campo; o campo em si vem do cache comum ao pintar."""
        self._prepara_pontos()

    def _rot(self, X, Y, Z):
        # yaw sobre o eixo Z (giro da cabeça) e SO DEPOIS pitch sobre X (tilt)
        """Aplica a rotação da camera aos pontos do domo antes da projeção.

        A ordem importa: depois do pitch, Z ja e o eixo de visao, entao aplicar
        o yaw por ultimo deixava a profundidade intacta e o conjunto de
        eletrodos escondidos nunca mudava. Funciona com arrays numpy e com
        escalares; _geometria usa a transposta desta mesma rotação.
        """
        cb, sb = math.cos(self.yaw), math.sin(self.yaw)
        X1 = X * cb - Y * sb; Y1 = X * sb + Y * cb; Z1 = Z
        ca, sa = math.cos(self.pitch), math.sin(self.pitch)
        Y2 = Y1 * ca - Z1 * sa; Z2 = Y1 * sa + Z1 * ca; X2 = X1
        return X2, Y2, Z2

    def _geometria(self, M):
        """Para cada pixel da imagem M x M: onde ler o campo, o alfa da
        silhueta e o sombreamento. Depende só do ângulo, não do dado: com o
        sinal chegando, o quadro custa a consulta de tabela e a cor.

        O pixel (u, v) vê o ponto da esfera (u, v, w); desfaz-se a rotação e
        pega-se o ponto do escalpo. Só entra a face de FORA do hemisfério
        (z >= 0): a face interna do lado oposto não é desenhada.
        """
        chave = (M, round(self.yaw, 4), round(self.pitch, 4))
        geo = self._geo.pop(chave, None)
        if geo is None:
            u = np.linspace(-1.0, 1.0, M, dtype=np.float32)[None, :]
            v = np.linspace(1.0, -1.0, M, dtype=np.float32)[:, None]
            r2 = u * u + v * v
            ww = np.sqrt(np.clip(1.0 - r2, 0.0, None))
            cb, sb = math.cos(self.yaw), math.sin(self.yaw)
            ca, sa = math.cos(self.pitch), math.sin(self.pitch)
            x = cb * u + ca * sb * v + sa * sb * ww
            y = -sb * u + ca * cb * v + sa * cb * ww
            z = -sa * v + ca * ww
            passo = 2.0 / (M - 1.0)
            rad = np.sqrt(r2)
            # alfa suave na borda da esfera E no aro (z = 0): borda lisa sem clip
            alfa = np.minimum(np.clip((1.0 - rad) / (1.3 * passo), 0.0, 1.0),
                              np.clip(z / (1.3 * passo), 0.0, 1.0))
            N = self.GRID
            S = _TOPO_ESCALA_EL
            fc = np.clip((x * S + 1.0) * 0.5 * (N - 1), 0.0, N - 1.001)
            fl = np.clip((1.0 - y * S) * 0.5 * (N - 1), 0.0, N - 1.001)
            col = fc.astype(np.int32); lin = fl.astype(np.int32)
            tx = (fc - col).astype(np.float32); ty = (fl - lin).astype(np.float32)
            # Sombra só perto da silhueta (escurecimento de borda), para dar
            # volume. O Lambert antigo (0,55 + 0,45·λ) escurecia até 45% da
            # cor no occipital e na esquerda: a cor lida na barra ficava até
            # meia escala abaixo do dado. Aqui o miolo sai com a cor exata e
            # só a faixa da borda escurece (no máximo 15%).
            sombra = (1.0 - 0.15 * (1.0 - ww) ** 3).astype(np.float32)
            geo = (lin, col, tx, ty, (alfa * 255.0 + 0.5).astype(np.uint8), sombra)
            while len(self._geo) >= self.GEO_MAX:
                self._geo.pop(next(iter(self._geo)))
        self._geo[chave] = geo
        return geo

    def _imagem_domo(self, M):
        """Imagem do domo (M x M) para o dado e o ângulo atuais, em cache."""
        chave = (self._campo_chave, M, round(self.yaw, 4), round(self.pitch, 4),
                 COLORS["surface_alt"])
        if self._img_cache is not None and self._img_cache[0] == chave:
            return self._img_cache[1]
        lin, col, tx, ty, alfa, sombra = self._geometria(M)
        F2 = self._campo_atual()
        n2 = F2.shape[1]
        # Interpolação só nos pixels que aparecem (alfa > 0), com índice e
        # pesos guardados por ângulo, em float32: com o sinal chegando era o
        # maior custo do quadro (domo de 64 canais a 30 de 35 ms).
        ch_g = (M, round(self.yaw, 4), round(self.pitch, 4), F2.shape)
        ic = getattr(self, "_interp_domo", None)
        if ic is None or ic[0] != ch_g:
            vis = np.flatnonzero(alfa.ravel() > 0)
            x_, y_ = tx.ravel()[vis], ty.ravel()[vis]
            i00 = (lin.ravel()[vis].astype(np.intp) * n2
                   + col.ravel()[vis].astype(np.intp))
            pesos = tuple(np.asarray(q, np.float32) for q in (
                (1 - x_) * (1 - y_), x_ * (1 - y_), (1 - x_) * y_, x_ * y_))
            ic = (ch_g, vis, i00, pesos)
            self._interp_domo = ic
        _cg, vis, i00, (w00, w01, w10, w11) = ic
        Ff = np.asarray(F2, np.float32).ravel()
        F = (Ff[i00] * w00 + Ff[i00 + 1] * w01
             + Ff[i00 + n2] * w10 + Ff[i00 + n2 + 1] * w11)
        rgb = _topo_lut()[_topo_indice_cor(F)]
        buf = np.zeros((M * M, 4), np.uint8)
        if self._plano:
            # quadro plano: sem sombra (a borda pareceria ter menos potência)
            # e sem véu (ver _imagem_mapa do 2D)
            buf[vis, :3] = rgb
        else:
            # O mesmo véu do 2D, reamostrado como o campo, junto com a sombra:
            # cor = (rgb·(1-v) + fundo·v)·sombra = rgb·A + B. A e B só
            # dependem das posições e do ângulo e ficam em cache; refazer o
            # véu a cada dado novo passava dos 35 ms por quadro com 64 canais.
            ch_v = (self._campo_chave[0], M, round(self.yaw, 4),
                    round(self.pitch, 4), COLORS["surface_alt"])
            vc = getattr(self, "_veu_domo", None)
            if vc is None or vc[0] != ch_v:
                V2 = _topo_veu(self._campo_chave[0], F2.shape[0])
                Vd = ((V2[lin, col] * (1 - tx) + V2[lin, col + 1] * tx) * (1 - ty)
                      + (V2[lin + 1, col] * (1 - tx) + V2[lin + 1, col + 1] * tx) * ty)
                A = ((1.0 - Vd) * sombra).astype(np.float32)[..., None]
                B = ((Vd * sombra)[..., None]
                     * _topo_cor_veu()[None, None, :]).astype(np.float32)
                # só os pixels que aparecem, na ordem de `vis` (mesmo ângulo)
                vc = (ch_v, A.reshape(-1, 1)[vis], B.reshape(-1, 3)[vis])
                self._veu_domo = vc
            buf[vis, :3] = np.minimum(rgb * vc[1] + vc[2], 255.0).astype(np.uint8)
        buf[:, 3] = alfa.ravel()
        img = _topo_qimage_rgba(buf.reshape(M, M, 4))
        self._img_cache = (chave, img)
        return img

    def _silhueta(self, cx, cy, R):
        """Contorno exato do hemisfério projetado: metade de baixo do círculo
        unida à metade de cima da elipse do aro, de semi-eixos (R, R·cos pitch)."""
        ca = max(1e-3, math.cos(self.pitch))
        cam = QtGui.QPainterPath()
        cam.moveTo(cx - R, cy)
        cam.arcTo(QtCore.QRectF(cx - R, cy - R, 2 * R, 2 * R), 180, 180)
        cam.arcTo(QtCore.QRectF(cx - R, cy - ca * R, 2 * R, 2 * ca * R), 0, 180)
        cam.closeSubpath()
        return cam

    def paintEvent(self, ev):
        """Renderiza o domo (imagem traçada por pixel), o contorno, o nariz,
        os eletrodos, o título, a escala numérica e a dica de arrasto."""
        p = QtGui.QPainter(self)
        try:
            self._pinta(p)
        except Exception:
            _topo_logar_falha(self)
        finally:
            p.end()

    def _pinta(self, p):
        """Corpo do paintEvent (separado para o paintEvent nunca vazar exceção)."""
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.TextAntialiasing, True)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        # A silhueta não é um círculo: vai de cy - cos(pitch)·R até cy + R.
        # O raio sai dessa altura real, entre o título e a escala, e a caixa
        # da silhueta é centrada (senão o domo invadia a legenda). Em quadro
        # baixo e largo a barra vai em pé, à direita do domo.
        ca = max(1e-3, math.cos(self.pitch))
        topo = 52.0
        col = _TOPO_COLUNA_BARRA
        R_h = max(20.0, min((w - 56.0) / 2.0, (h - 64.0 - topo) / (1.0 + ca)))
        R_v = max(20.0, min((w - col - 56.0) / 2.0, (h - 26.0 - topo) / (1.0 + ca)))
        vertical = R_v > 1.25 * R_h
        if vertical:
            R, base, cx = R_v, h - 26.0, (w - col) / 2.0
        else:
            R, base, cx = R_h, h - 64.0, w / 2.0
        cy = topo + (base - topo - R * (1.0 + ca)) / 2.0 + ca * R
        tem_dado = bool(self._idx)

        self._pinta_nariz(p, cx, cy, R)
        if tem_dado:
            dpr = float(p.device().devicePixelRatioF() or 1.0)
            teto = self.LADO_ARRASTO if self._drag is not None else self.LADO_IMG
            M = int(max(48, min(teto, round(2 * R * dpr))))
            p.drawImage(_topo_rect_amostras(cx - R, cy - R, 2 * R, M),
                        self._imagem_domo(M))
        else:
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
            p.drawPath(self._silhueta(cx, cy, R))
        # contorno da silhueta: anel escuro por fora, claro por dentro
        p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
        p.setPen(QtGui.QPen(QtGui.QColor(10, 14, 20, 170), 3.4))
        p.drawPath(self._silhueta(cx, cy, R + 1.0))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"]), 1.6))
        p.drawPath(self._silhueta(cx, cy, R))

        self._draw_overlays(p, cx, cy, R)
        # título + escala + dica. O título diz POTÊNCIA: o combo "Mapa" em
        # CSD só vale para o 2D, e o domo continuava sem dizer o que mostra.
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["accent"])))
        p.setFont(QtGui.QFont(FONT_UI, 11, QtGui.QFont.Weight.Bold))
        p.drawText(QtCore.QRectF(0, 4, w, 18), QtCore.Qt.AlignmentFlag.AlignCenter,
                   f"3D · {tr('POTÊNCIA')} · {self.band_name.upper()}  ({self.num_channels}ch)")
        if tem_dado:
            vmin, vmax = self._disp_range
            if vertical:
                xb = min(cx + R + 26.0, w - col + 20.0)
                _topo_barra_v(p, xb, cy - ca * R + 6.0, cy + R - 6.0, w - xb - 8.0,
                              vmin, vmax, self._plano, unidade=self.unidade)
            else:
                x0, x1 = _topo_faixa_barra(w, cx, R)
                _topo_barra(p, x0, x1, h - 48.0, vmin, vmax, self._plano,
                            unidade=self.unidade)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
        p.setFont(QtGui.QFont(FONT_UI, 8))
        # "sombreado = relevo de potência" era falso: a sombra nunca dependeu
        # do dado. Agora ela é só de borda e o rodapé diz isso.
        rodape = tr("Arraste na horizontal para girar a cabeça e na vertical "
                    "para inclinar · cor = dado; a sombra da borda só dá volume")
        p.drawText(QtCore.QRectF(4, h - 18, w - 8, 14),
                   QtCore.Qt.AlignmentFlag.AlignCenter,
                   QtGui.QFontMetricsF(p.font()).elidedText(
                       rodape, QtCore.Qt.TextElideMode.ElideRight, w - 8))

    def _project_pt(self, x, y, z, cx, cy, R):
        """Projeta um ponto da esfera unitaria em coordenadas de tela, devolvendo
        também a profundidade rotacionada (z > 0 = voltado ao observador)."""
        Xr, Yr, Zr = self._rot(x, y, z)
        return cx + float(Xr) * R, cy - float(Yr) * R, float(Zr)

    def _rim_polygon(self, cx, cy, R):
        """Aro do escalpo (z=0) projetado."""
        th = np.linspace(0, 2 * np.pi, 72)
        Xr, Yr, Zr = self._rot(np.cos(th), np.sin(th), np.zeros_like(th))
        return QtGui.QPolygonF([QtCore.QPointF(cx + float(x) * R, cy - float(y) * R)
                                for x, y in zip(Xr, Yr)])

    def _pinta_nariz(self, p, cx, cy, R):
        """Nariz projetado no plano do aro, desenhado antes do domo (a base
        fica escondida sob a borda) e só quando está voltado ao observador."""
        tip = self._project_pt(0.0, 1.11, 0.0, cx, cy, R)
        if tip[2] < -0.05:
            return
        b1 = self._project_pt(-0.10, 0.99, 0.0, cx, cy, R)
        b2 = self._project_pt(0.10, 0.99, 0.0, cx, cy, R)
        nariz = QtGui.QPainterPath()
        nariz.moveTo(b1[0], b1[1])
        nariz.quadTo((b1[0] + tip[0]) / 2.0, (b1[1] + tip[1]) / 2.0, tip[0], tip[1])
        nariz.quadTo((b2[0] + tip[0]) / 2.0, (b2[1] + tip[1]) / 2.0, b2[0], b2[1])
        nariz.closeSubpath()
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"]), 1.6))
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
        p.drawPath(nariz)

    def _draw_overlays(self, p, cx, cy, R):
        """Eletrodos projetados sobre o domo: disco na cor do valor e o nome
        acima, fora do disco, com contorno de contraste.

        Some quem está atrás do domo (profundidade < -0,15); perto da borda o
        eletrodo esmaece em vez de sumir de repente — o occipital costuma ser
        justamente o de borda.
        """
        nvis = len(self._idx)
        rr = 7.0 if nvis <= 16 else 6.0 if nvis <= 32 else 4.5
        fonte = QtGui.QFont(FONT_UI, 8 if nvis <= 16 else 7, QtGui.QFont.Weight.Bold)
        nomes = []
        for i in self._idx:
            ex, ey = self._pos[i]
            ez = math.sqrt(max(0.0, 1.0 - ex * ex - ey * ey))
            px, py, pz = self._project_pt(ex, ey, ez, cx, cy, R)
            if pz < -0.15:          # atrás do domo — oculta
                continue
            p.setOpacity(max(0.35, min(1.0, (pz + 0.15) / 0.3)))
            cor = HeadPlotWidget._color_for_power(self._norm.get(i, 0.0))
            if i in self.expected_channels:
                p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
                p.setPen(QtGui.QPen(QtGui.QColor(COLORS["accent"]), 2.5))
                p.drawEllipse(QtCore.QPointF(px, py), rr + 4, rr + 4)
            p.setBrush(QtGui.QBrush(cor))
            # borda preta fixa sumia no roxo; segue o contraste do disco
            p.setPen(QtGui.QPen(HeadPlotWidget._text_on(cor), 1.4))
            p.drawEllipse(QtCore.QPointF(px, py), rr, rr)
            nome = self.mapping[i] if i < len(self.mapping) else ""
            nomes.append((px, py, nome, cor, p.opacity()))
        p.setOpacity(1.0)
        # nomes por cima de todos os discos, sem tapar disco nem outro nome
        _topo_nomes(p, nomes, rr, fonte)

    # ---- interação ----
    def mousePressEvent(self, ev):
        """Comeca o arrasto de rotação guardando a posição do clique e os angulos
        de partida."""
        self._drag = (ev.position().x(), ev.position().y(), self.yaw, self.pitch)
        self.setCursor(QtCore.Qt.CursorShape.ClosedHandCursor)

    def mouseMoveEvent(self, ev):
        """Atualiza yaw e pitch conforme o arrasto do mouse e repinta o domo
        (em resolução reduzida enquanto arrasta).

        Sensibilidade de 0,012 rad por pixel; o pitch e limitado a 0,05..1,55
        rad para o domo não chegar a vista de topo nem virar completamente de
        perfil.
        """
        if self._drag is None:
            return
        x0, y0, yaw0, pitch0 = self._drag
        # % 2*pi só por higiene: o yaw crescia indefinidamente com o arrasto.
        self.yaw = (yaw0 + (ev.position().x() - x0) * 0.012) % (2 * math.pi)
        self.pitch = max(0.05, min(1.55, pitch0 + (ev.position().y() - y0) * 0.012))
        self.update()

    def mouseReleaseEvent(self, ev):
        """Encerra o arrasto, devolve o cursor de mão aberta e repinta em
        resolução cheia."""
        self._drag = None
        self.setCursor(QtCore.Qt.CursorShape.OpenHandCursor)
        self.update()


# ============================================================
# HeadPlotWidgetCT — topografia estilo "tomografia computadorizada"
# ============================================================
class HeadPlotWidgetCT(_TopoPontos, QtWidgets.QWidget):
    """Topografia EEG estilo tomografia: o campo do 2D POSTERIZADO em camadas
    isopotenciais, com decaimento em profundidade (condução de volume) e
    isolinhas vetoriais. QImage/numpy puro — sem MNE/scipy pesado."""

    GRID = _TOPO_GRADE
    # 11 camadas (ímpar): o meio da escala (0,5) cai no MEIO de uma camada e o
    # quadro plano sai na mesma cor do 2D. Com 12 ele caía na fronteira entre
    # duas camadas, e a cor e a marca da barra não batiam com o 2D.
    LEVELS = 11
    SUPER = 1.25     # campo ampliado a 1,25x o disco na tela antes de posterizar
    TETO = 900       # teto do lado ampliado (custo por quadro)
    GRADE_ISO = 96   # grade das isolinhas (ver _imagem_ct)

    def __init__(self, parent=None):
        """Inicializa a vista de tomografia com valores zerados e fatia na
        superfície do escalpo.

        depth vai de 0 (escalpo) a 1 (camada profunda) e e alimentado pelo
        slider 0..100 da aba via set_slice_depth.
        """
        super().__init__(parent)
        self.raw_values = [0.0] * MAX_CHANNELS
        self.num_channels = BASE_CHANNELS
        self.mapping = list(DEFAULT_MAPPING)
        self.band_name = "Alpha"
        self.expected_channels = set()
        self.depth = 0.0             # 0 = escalpo · 1 = camada profunda
        self._V = None
        self._disp_range = (0.0, 0.0)
        self._disp_norm = {}         # canal -> valor 0..1 (p/ desenhar o eletrodo)
        self._plano = False
        self._img_cache = None
        # Rodapé "Profundidade da camada". A aba Topografia o desliga: lá o
        # rótulo do controle deslizante já mostra a mesma coisa.
        self.mostra_rodape = True
        self.setMinimumSize(420, 420)
        self.setToolTip(tr("Tomografia isopotencial. Use o controle de profundidade "
                        "para 'fatiar' camadas internas (modelo de condução de volume)."))
        self._recompute()

    # ---- API compatível ----
    def set_num_channels(self, n):
        """Ajusta o número de eletrodos, renormaliza e repinta."""
        self.num_channels = max(0, min(int(n), MAX_CHANNELS))
        self._recompute(); self.update()

    def set_mapping(self, mapping):
        """Troca o mapeamento CH -> eletrodo e renormaliza.

        Ignora listas cujo tamanho não seja exatamente MAX_CHANNELS.
        """
        if isinstance(mapping, (list, tuple)) and len(mapping) == MAX_CHANNELS:
            self.mapping = list(mapping); self._recompute(); self.update()

    def set_expected_channels(self, idx):
        """Marca os canais a destacar na vista de tomografia."""
        self.expected_channels = set(int(i) for i in (idx or [])
                                     if 0 <= int(i) < MAX_CHANNELS)
        self.update()

    def set_powers(self, values, band_name="Alpha"):
        """Entrada principal do widget: guarda a potência por canal e o nome da
        banda e refaz a escala; o campo e as camadas saem ao pintar.

        A escala é min-max do quadro (a mesma do 2D): o mapa é sempre relativo
        e a barra mostra os dois números.
        """
        self.raw_values = _topo_floats(values)
        self.band_name = band_name
        self._recompute(); self.update()

    def set_map_mode(self, mode):
        """No-op mantido só para o widget aceitar a mesma API do HeadPlotWidget.

        Permite trocar um widget pelo outro sem o chamador testar o tipo; aqui
        não existe modo de mapa, então a chamada é ignorada.
        """
        pass

    def set_slice_depth(self, d):
        """d em 0..100 (slider) -> profundidade 0..1."""
        self.depth = max(0.0, min(1.0, float(d) / 100.0))
        self.update()

    def _recompute(self):
        """Refaz a escala (mesma regra do 2D, inclusive o caso plano) e a chave
        do campo compartilhado."""
        self._prepara_pontos()
        self._disp_norm = dict(self._norm)

    def _imagem_ct(self, lado):
        """Fatia posterizada em LEVELS camadas, com isolinhas e recorte liso.

        O campo é AMPLIADO (bilinear) para 1,25x o disco na tela ANTES de
        posterizar: posterizar a grade grossa e esticar depois é o que dava a
        escada. As isolinhas são polilinhas vetoriais por cima das fronteiras.
        A profundidade age como sempre: atenua exp(-1,6·d) e encolhe o raio
        visível para 1 - 0,9·d.
        """
        d = self.depth
        chave = (self._campo_chave, lado, round(d, 4), COLORS["surface_alt"])
        if self._img_cache is not None and self._img_cache[0] == chave:
            return self._img_cache[1]
        L = self.LEVELS
        aten = math.exp(-1.6 * d)
        lim = max(0.06, 1.0 - 0.9 * d)
        cores = [_topo_argb(HeadPlotWidget._color_for_power((k + 0.5) / L))
                 for k in range(L)]
        campo = self._campo_atual()
        linhas = []
        if self._plano:
            # campo constante: uma camada só, no meio da escala (atenuada)
            nivel = max(0, min(L - 1, int(0.5 * aten * L + 1e-9)))
            m = 8
            pequena = _topo_qimage_indice(np.full((m, m), nivel, np.uint8), cores)
        else:
            Veff = np.clip(campo * np.float32(aten), 0.0, 1.0)
            m = int(min(self.TETO, max(64, round(lado * self.SUPER))))
            m -= m % 4               # linha da QImage indexada alinhada em 32 bits
            nivel = (_topo_amplia(Veff, m) * np.float32(L)).astype(np.uint8)
            np.minimum(nivel, L - 1, out=nivel)
            pequena = _topo_qimage_indice(nivel, cores)
            # Isolinhas numa grade de 96 (reamostrada do mesmo campo, com as
            # pontas): o encadeamento em Python era metade do custo do
            # quadro com 8 e 16 canais. O campo da spline é liso e a linha
            # fica a menos de 1 px da fronteira das camadas.
            Viso = _topo_amplia(Veff, self.GRADE_ISO)
            for k in range(1, L):
                for ln in _topo_isolinhas(Viso, k / float(L)):
                    linhas.append((k, ln))
        grande = QtGui.QImage(lado, lado, QtGui.QImage.Format.Format_ARGB32_Premultiplied)
        grande.fill(0)
        q = QtGui.QPainter(grande)
        q.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        q.drawImage(_topo_rect_amostras(0.0, 0.0, float(lado), m), pequena)
        if linhas:
            q.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
            esc = lado / float(self.GRADE_ISO - 1)
            larg = max(1.0, lado / 560.0)
            canetas = {}
            for k, ln in linhas:
                caneta = canetas.get(k)
                if caneta is None:
                    # cor de contraste da camada de cima, meio transparente
                    cor = HeadPlotWidget._text_on(
                        HeadPlotWidget._color_for_power((k + 0.5) / L))
                    cor.setAlpha(150)
                    caneta = QtGui.QPen(cor, larg)
                    caneta.setJoinStyle(QtCore.Qt.PenJoinStyle.RoundJoin)
                    caneta.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
                    canetas[k] = caneta
                q.setPen(caneta)
                q.drawPolyline(QtGui.QPolygonF([QtCore.QPointF(c * esc, l_ * esc)
                                                for c, l_ in ln]))
        # Véu por cima das camadas e das isolinhas, como no 2D e no domo:
        # longe de eletrodo a camada é só interpolação.
        veu = _topo_veu(self._campo_chave[0], self.GRID)
        if not self._plano and float(np.max(veu)) > 0.0:
            fundo = _topo_cor_veu().astype(np.uint8)
            vb = np.empty(veu.shape + (4,), np.uint8)
            vb[..., :3] = fundo
            vb[..., 3] = np.clip(veu * 255.0 + 0.5, 0, 255).astype(np.uint8)
            q.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
            q.drawImage(_topo_rect_amostras(0.0, 0.0, float(lado), veu.shape[0]),
                        _topo_qimage_rgba(vb))
        q.end()
        disco = QtGui.QPainterPath()
        disco.addEllipse(QtCore.QPointF(lado / 2.0, lado / 2.0),
                         lado / 2.0 * lim - 0.6, lado / 2.0 * lim - 0.6)
        _topo_recorta(grande, disco)
        self._img_cache = (chave, grande)
        return grande

    def paintEvent(self, ev):
        """Desenha a cabeça (contorno com nariz e orelhas), a fatia posterizada,
        o limite da fatia, os eletrodos que caem dentro dela, título, escala
        em camadas com números e o rótulo de profundidade."""
        p = QtGui.QPainter(self)
        try:
            self._pinta(p)
        except Exception:
            _topo_logar_falha(self)
        finally:
            p.end()

    def _pinta(self, p):
        """Corpo do paintEvent (separado para o paintEvent nunca vazar exceção)."""
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.SmoothPixmapTransform, True)
        p.setRenderHint(QtGui.QPainter.RenderHint.TextAntialiasing, True)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        # Em quadro baixo e largo a barra vai em pé à direita (ver o 2D).
        col = _TOPO_COLUNA_BARRA
        R_h = max(20.0, min(w, h) / 2.0 - 62)
        rodape = 24.0 if self.mostra_rodape else 6.0
        R_v = max(20.0, min((h - 26.0 - rodape) / 2.2, (w - col - 24.0) / 2.2))
        vertical = R_v > 1.25 * R_h
        if vertical:
            R = R_v
            cx = (w - col) / 2.0
            cy = 26.0 + max(0.0, (h - 26.0 - rodape - 2.2 * R) / 2.0) + 1.1 * R
        else:
            R = R_h
            cx, cy = w / 2.0, h / 2.0 + 2
        tem_dado = bool(self._idx)
        lim = max(0.06, 1.0 - 0.9 * self.depth)
        aten = math.exp(-1.6 * self.depth)

        cabeca = _topo_caminho_cabeca(cx, cy, R)
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
        p.drawPath(cabeca)
        if tem_dado:
            dpr = float(p.device().devicePixelRatioF() or 1.0)
            lado = int(min(1600, max(32, round(2 * R * dpr))))
            p.drawImage(QtCore.QRectF(cx - R, cy - R, 2 * R, 2 * R),
                        self._imagem_ct(lado))
        p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
        p.setPen(QtGui.QPen(QtGui.QColor(12, 16, 22, 170), 3.6))
        p.drawPath(_topo_caminho_cabeca(cx, cy, R + 1.4))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"]), 2.0))
        p.drawPath(cabeca)
        if lim < 0.999:
            # limite da fatia: traço fino e contínuo (os anéis pontilhados
            # por cima do mapa atrapalhavam a leitura das camadas)
            cor_lim = QtGui.QColor(COLORS["text_dim"]); cor_lim.setAlpha(170)
            p.setPen(QtGui.QPen(cor_lim, 1.3))
            p.drawEllipse(QtCore.QPointF(cx, cy), R * lim, R * lim)

        # Eletrodos da fatia. Quem cai fora do raio visível é omitido, senão o
        # desenho mentiria sobre a anatomia ao mover o controle de profundidade.
        S = _TOPO_ESCALA_EL
        L = self.LEVELS
        nvis = len(self._idx)
        rr = 6.0 if nvis <= 16 else 5.0 if nvis <= 32 else 4.0
        fonte_el = QtGui.QFont(FONT_UI, 8 if nvis <= 16 else 7, QtGui.QFont.Weight.Bold)
        nomes = []
        for i in self._idx:
            ex, ey = self._pos[i]
            if math.hypot(ex, ey) * S > lim + 1e-9:
                continue
            band = max(0, min(L - 1, int(self._norm.get(i, 0.0) * aten * L + 1e-9)))
            cor_el = HeadPlotWidget._color_for_power((band + 0.5) / L)
            px_e = cx + ex * R * S
            py_e = cy - ey * R * S
            if i in self.expected_channels:
                p.setPen(QtGui.QPen(QtGui.QColor(COLORS["accent"]), 2))
                p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
                p.drawEllipse(QtCore.QPointF(px_e, py_e), rr + 4, rr + 4)
            p.setBrush(QtGui.QBrush(cor_el))
            p.setPen(QtGui.QPen(HeadPlotWidget._text_on(cor_el), 1.4))
            p.drawEllipse(QtCore.QPointF(px_e, py_e), rr, rr)
            nome = self.mapping[i] if i < len(self.mapping) else ""
            nomes.append((px_e, py_e, nome, cor_el, 1.0))
        _topo_nomes(p, nomes, rr, fonte_el)

        # título + escala em camadas + rótulo de profundidade
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["accent"])))
        p.setFont(QtGui.QFont(FONT_UI, 11, QtGui.QFont.Weight.Bold))
        p.drawText(QtCore.QRectF(0, 4, w, 18), QtCore.Qt.AlignmentFlag.AlignCenter,
                   f"{tr('Tomografia').upper()} · {tr('POTÊNCIA')} · {self.band_name.upper()}  ({self.num_channels}ch)")
        if tem_dado:
            vmin, vmax = self._disp_range
            # Abaixo do escalpo as camadas são o campo x e^(-1,6·d): nenhuma
            # cor chega à ponta alta, e os números do escalpo na barra fariam
            # quem lê a cor subestimar o valor medido. Na fatia funda a barra
            # fica sem números e diz o fator do modelo.
            nota = None
            if self.depth > 0.004:
                nota = tr("modelo ilustrativo: cores do escalpo × {0}").format(
                    "%.2f" % aten)
            if vertical:
                xb = min(cx + 1.07 * R + 26.0, w - col + 20.0)
                _topo_barra_v(p, xb, cy - 0.72 * R, cy + 0.72 * R, w - xb - 8.0,
                              vmin, vmax, self._plano, degraus=L,
                              unidade=self.unidade, nota=nota)
            else:
                x0, x1 = _topo_faixa_barra(w, cx, R)
                _topo_barra(p, x0, x1, h - 48.0, vmin, vmax, self._plano,
                            degraus=L, unidade=self.unidade, nota=nota)
        if self.mostra_rodape:
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
            p.setFont(QtGui.QFont(FONT_UI, 8))
            p.drawText(QtCore.QRectF(0, h - 18, w, 14),
                       QtCore.Qt.AlignmentFlag.AlignCenter,
                       tr("Profundidade da camada: {0:.0f}%  ·  {1} isopotenciais").format(self.depth * 100, self.LEVELS))


# ============================================================
# FocusMeterWidget
# ============================================================
class FocusMeterWidget(QtWidgets.QWidget):
    """Painel de índice de foco beta/(alfa+beta) com número grande, barra, rótulo
    de estado e histórico em gráfico.

    Só exibe: o índice é calculado fora e entregue por update_value.
    """
    def __init__(self, parent=None):
        """Monta o layout do painel (título, valor, barra de 0-100, rótulo de
        estado e gráfico) e cria o histórico.

        O histórico é um deque de 120 pontos pré-preenchido com 0.5, então a
        curva já nasce cheia na linha média em vez de crescer da esquerda.
        """
        super().__init__(parent)
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        title = QtWidgets.QLabel(tr("Índice de Foco — β / (α + β)"))
        title.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold; font-size: 11pt;")
        layout.addWidget(title)
        self.value_label = QtWidgets.QLabel("--")
        self.value_label.setStyleSheet(f"color: {COLORS['accent']}; font-size: 32pt; font-weight: bold;")
        self.value_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(self.value_label)
        self.bar = QtWidgets.QProgressBar(); self.bar.setRange(0, 100)
        self.bar.setTextVisible(False); self.bar.setMaximumHeight(20)
        layout.addWidget(self.bar)
        self.state_label = QtWidgets.QLabel(tr("aguardando..."))
        self.state_label.setStyleSheet(f"color: {COLORS['text_dim']};")
        self.state_label.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        layout.addWidget(self.state_label)
        self.plot = pg.PlotWidget(enableMenu=False)
        self.plot.showGrid(x=True, y=True, alpha=0.15)
        self.plot.setYRange(0, 1); self.plot.setLabel("left", tr("Foco"))
        self.plot.setMenuEnabled(False); self.plot.setMouseEnabled(x=False, y=False)
        self.curve = self.plot.plot(pen=pg.mkPen(COLORS["accent"], width=2))
        layout.addWidget(self.plot, stretch=1)
        self.history = deque([0.5] * 120, maxlen=120)

    def update_value(self, focus):
        """Recebe um novo índice de foco e atualiza número, barra, curva do
        histórico e a classificação textual do estado.

        Espera focus já normalizado em 0..1. Os limiares são fixos: abaixo de
        0.40 marca RELAXADO/DISTRAIDO, acima de 0.60 marca FOCADO, entre eles
        NEUTRO.
        """
        self.history.append(focus)
        self.curve.setData(np.arange(len(self.history)), np.array(self.history))
        pct = int(focus * 100)
        self.value_label.setText(f"{focus:.2f}")
        self.bar.setValue(pct)
        if focus < 0.40:
            self.state_label.setText(tr("RELAXADO / DISTRAIDO"))
            self.state_label.setStyleSheet(f"color: {COLORS['warning']};")
        elif focus > 0.60:
            self.state_label.setText(tr("FOCADO"))
            self.state_label.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold;")
        else:
            self.state_label.setText(tr("NEUTRO"))
            self.state_label.setStyleSheet(f"color: {COLORS['text_dim']};")


# ============================================================
# EMGEnvelopeWidget
# ============================================================
class EMGEnvelopeWidget(QtWidgets.QWidget):
    """Painel que mostra o EMG retificado de um canal junto com sua envoltória RMS
    suavizada.

    O combo de canal só registra a escolha do operador — nada aqui o conecta a
    nada; quem lê o índice e chama update_signal é código externo.
    """
    def __init__(self, parent=None):
        """Monta o título, a linha do seletor de canal e o gráfico com as duas
        curvas (sinal retificado em cinza, envoltória em destaque).

        O combo é populado com todos os MAX_CHANNELS de uma vez; é
        set_num_channels que depois desabilita os que não existem na montagem
        atual.
        """
        super().__init__(parent)
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        title = QtWidgets.QLabel(tr("Envoltoria EMG (RMS suavizado)"))
        title.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold; font-size: 11pt;")
        layout.addWidget(title)
        ch_row = QtWidgets.QHBoxLayout()
        ch_row.addWidget(QtWidgets.QLabel(tr("Canal:")))
        self.channel_combo = QtWidgets.QComboBox()
        for i in range(MAX_CHANNELS):
            self.channel_combo.addItem(f"CH{i+1}")
        ch_row.addWidget(self.channel_combo); ch_row.addStretch()
        layout.addLayout(ch_row)
        self.plot = pg.PlotWidget(enableMenu=False)
        self.plot.showGrid(x=True, y=True, alpha=0.15)
        self.plot.setLabel("left", tr("|sinal| (µV)"))
        self.plot.setLabel("bottom", tr("Tempo"), units="s")
        self.plot.setMenuEnabled(False)
        self.curve_raw = self.plot.plot(pen=pg.mkPen(COLORS["text_dim"], width=1))
        self.curve_env = self.plot.plot(pen=pg.mkPen(COLORS["accent"], width=2))
        layout.addWidget(self.plot, stretch=1)

    def set_num_channels(self, n):
        # Habilita/desabilita itens 9-16
        """Desabilita no combo os canais acima da quantidade em uso, sem removê-
        los da lista.

        Precisa alcançar os itens via model().item(i) porque o QComboBox não
        expõe habilitar item diretamente. Se o canal selecionado ficar fora da
        faixa, a seleção volta para o primeiro.
        """
        for i in range(MAX_CHANNELS):
            item = self.channel_combo.model().item(i)
            if item is not None:
                item.setEnabled(i < n)
        if self.channel_combo.currentIndex() >= n:
            self.channel_combo.setCurrentIndex(0)

    def update_signal(self, data, sample_rate=SAMPLE_RATE):
        """Redesenha as duas curvas a partir de um bloco de sinal e da envoltória
        calculada por SignalProcessor.

        Blocos com menos de 10 amostras são ignorados sem aviso. A curva de
        fundo é |sinal| (retificado), não o sinal bruto — valores negativos
        nunca aparecem.
        """
        if len(data) < 10:
            return
        t = np.arange(len(data)) / sample_rate
        env = SignalProcessor.compute_emg_envelope(data, sample_rate)
        self.curve_raw.setData(t, np.abs(data))
        self.curve_env.setData(t, env)


# ============================================================
# _EogGazeWidget — visualização de direção do olhar (EoG)
# ============================================================
class _EogGazeWidget(QtWidgets.QWidget):
    """Diagrama XY mostrando posição do olho em tempo real.

    Recebe coordenadas normalizadas em [-1, +1]. A origem (0,0) é o centro.
    +x = direita, +y = cima. Linhas-guia desenhadas a cada 0.5 unidade.
    """
    def __init__(self, parent=None):
        """Inicia o olhar no centro e o rastro vazio."""
        super().__init__(parent)
        self._gx = 0.0
        self._gy = 0.0
        self._trail = []  # últimas N posições para "rastro"
        self.setMinimumSize(180, 180)

    def set_gaze(self, gx, gy):
        """Atualiza a posição do olhar, empurra o ponto no rastro e repinta.

        O limite é RADIAL (raio <= 1), não um quadrado: o fundo é um disco e
        dois limites independentes deixavam o olhar diagonal 41% fora do
        círculo. Encurtar pelo raio preserva a direção, que é o que se lê. O
        rastro guarda no máximo 30 posições, descartando as mais antigas.
        """
        gx = float(gx); gy = float(gy)
        raio = math.hypot(gx, gy)
        if raio > 1.0:
            gx /= raio; gy /= raio
        self._gx = gx
        self._gy = gy
        self._trail.append((self._gx, self._gy))
        if len(self._trail) > 30:
            self._trail.pop(0)
        self.update()

    def paintEvent(self, event):
        """Desenha o alvo circular com grade, o rastro esmaecido e o ponto atual
        do olhar, mais as marcas de direção.

        O y é invertido na conversão para pixels (em Qt o y cresce para baixo),
        então +y do gaze aparece na parte de cima. Os indicadores de direção
        usam caracteres do bloco Geometric Shapes de propósito, para não
        depender de fonte de emoji.
        """
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        w = self.width(); h = self.height()
        size = min(w, h)
        # Centro
        cx = w / 2; cy = h / 2
        r = size / 2 - 6
        # Fundo circular
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1))
        p.drawEllipse(QtCore.QPointF(cx, cy), r, r)
        # Grade
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1,
                            QtCore.Qt.PenStyle.DashLine))
        p.drawLine(QtCore.QPointF(cx - r, cy), QtCore.QPointF(cx + r, cy))
        p.drawLine(QtCore.QPointF(cx, cy - r), QtCore.QPointF(cx, cy + r))
        for f in (0.33, 0.66):
            p.drawEllipse(QtCore.QPointF(cx, cy), r * f, r * f)
        # Rastro (alpha proporcional à idade)
        n = len(self._trail)
        for i, (gx, gy) in enumerate(self._trail):
            alpha = int(40 + 180 * i / max(1, n - 1))
            color = QtGui.QColor(SIGNAL_TYPE_COLORS["EoG"])
            color.setAlpha(alpha)
            p.setBrush(QtGui.QBrush(color))
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            px = cx + gx * r; py = cy - gy * r  # y invertido (Qt y+ é para baixo)
            p.drawEllipse(QtCore.QPointF(px, py), 3, 3)
        # Dot atual
        p.setBrush(QtGui.QBrush(QtGui.QColor(SIGNAL_TYPE_COLORS["EoG"])))
        p.setPen(QtGui.QPen(QtGui.QColor("#ffffff"), 1.5))
        px = cx + self._gx * r; py = cy - self._gy * r
        p.drawEllipse(QtCore.QPointF(px, py), 7, 7)
        # Labels direcionais (triângulos Geometric Shapes — não-emoji)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
        p.setFont(QtGui.QFont(FONT_UI, 9, QtGui.QFont.Weight.Bold))
        p.drawText(int(cx - 5), int(cy - r + 12), "▲")  # ▲
        p.drawText(int(cx - 5), int(cy + r - 2),  "▼")  # ▼
        p.drawText(int(cx + r - 14), int(cy + 5), "▶")  # ▶
        p.drawText(int(cx - r + 4),  int(cy + 5), "◀")  # ◀


# ============================================================
# LINHA DO TEMPO DO PROTOCOLO
# ============================================================
class ProtocolTimelineWidget(QtWidgets.QWidget):
    """Desenha a sequência de fases como uma faixa horizontal colorida.

    Serve para dois papéis:
      * no editor, é a PRÉVIA — o operador vê imediatamente o que montou, sem
        precisar somar durações de cabeça;
      * durante a coleta, ganha um cursor que anda, mostrando em que ponto do
        protocolo o participante está.

    QPainter puro de propósito: precisa funcionar dentro do .exe sem depender
    de nenhuma biblioteca de plotagem.
    """

    def __init__(self, parent=None):
        """Fixa a altura mínima da faixa e inicia sem blocos e sem cursor."""
        super().__init__(parent)
        self.setMinimumHeight(64)
        self.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                           QtWidgets.QSizePolicy.Policy.Fixed)
        self._blocos = []      # [(t0, t1, rótulo, tipo)]
        self._total = 0.0
        self._cursor = None    # segundos decorridos, ou None fora da execução

    def set_sequence(self, seq):
        """Recebe a sequência crua do editor e a expande em blocos com tempos
        absolutos, que é o formato que o paintEvent desenha.

        protocolo_expandir resolve as repetições; a duração total sai do fim do
        último bloco, e é ela que faz a faixa ocupar sempre a largura inteira.
        """
        self._blocos = protocolo_expandir(seq)
        self._total = self._blocos[-1][1] if self._blocos else 0.0
        self.update()

    def set_cursor(self, t):
        """Posiciona o marcador de execução no instante indicado, em segundos.

        Passar None apaga o cursor — é assim que a faixa volta ao modo prévia
        quando não há coleta rodando.
        """
        self._cursor = t
        self.update()

    def paintEvent(self, _ev):
        """Desenha os blocos coloridos por tipo de fase, a régua de tempo por
        baixo e o cursor de execução.

        Blocos com menos de 34 px de largura ficam sem rótulo (e mesmo os que
        cabem são elididos), porque texto amassado atrapalha mais do que
        informa. Tipo de fase não encontrado em PROTOCOL_PHASE_TYPES cai na cor
        de "livre". Com sequência vazia, desenha uma mensagem no lugar da
        faixa.
        """
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        if self._total <= 0:
            p.setPen(QtGui.QColor(COLORS["text_dim"]))
            p.drawText(QtCore.QRect(0, 0, w, h),
                       QtCore.Qt.AlignmentFlag.AlignCenter,
                       tr("Sequência vazia — acrescente fases abaixo."))
            return

        marg, barra_h = 8, 30
        larg = max(1, w - 2 * marg)
        topo = 10

        for t0, t1, rot, tipo in self._blocos:
            x0 = marg + larg * (t0 / self._total)
            x1 = marg + larg * (t1 / self._total)
            cor = QtGui.QColor(PROTOCOL_PHASE_TYPES.get(
                tipo, PROTOCOL_PHASE_TYPES["livre"])[1])
            r = QtCore.QRectF(x0, topo, max(1.0, x1 - x0), barra_h)
            p.fillRect(r, cor)
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["surface"]), 1))
            p.drawRect(r)
            # o rótulo só entra se couber — senão polui mais do que informa
            f = p.font(); f.setPointSizeF(7.5); p.setFont(f)
            if r.width() > 34:
                p.setPen(QtGui.QColor("#FFFFFF"))
                p.drawText(r, QtCore.Qt.AlignmentFlag.AlignCenter,
                           _elide_txt(p, rotulo_fase_tela(rot), r.width() - 6))

        # régua de tempo por baixo
        p.setPen(QtGui.QColor(COLORS["text_dim"]))
        f = p.font(); f.setPointSizeF(7.5); p.setFont(f)
        passo = _passo_regua(self._total)
        t = 0.0
        while t <= self._total + 1e-6:
            x = marg + larg * (t / self._total)
            p.drawLine(int(x), topo + barra_h, int(x), topo + barra_h + 4)
            p.drawText(QtCore.QRectF(x - 22, topo + barra_h + 4, 44, 14),
                       QtCore.Qt.AlignmentFlag.AlignCenter, f"{t:g}s")
            t += passo

        # cursor de execução
        if self._cursor is not None and 0 <= self._cursor <= self._total:
            x = marg + larg * (self._cursor / self._total)
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["warning"]), 2))
            p.drawLine(int(x), topo - 6, int(x), topo + barra_h + 2)
            p.setBrush(QtGui.QColor(COLORS["warning"]))
            p.drawEllipse(QtCore.QPointF(x, topo - 6), 3.5, 3.5)


def _elide_txt(painter, texto, largura):
    """Corta o texto com reticências para caber em `largura` pixels."""
    fm = painter.fontMetrics()
    return fm.elidedText(texto, QtCore.Qt.TextElideMode.ElideRight,
                         int(max(8, largura)))


def _passo_regua(total):
    """Escolhe um passo 'redondo' para a régua, com ~6 a 12 marcas."""
    for passo in (1, 2, 5, 10, 15, 30, 60, 120, 300, 600):
        if total / passo <= 12:
            return passo
    return max(1.0, round(total / 10.0))


# ============================================================
# Widgets ANATÔMICOS (representações visuais intuitivas por modalidade):
# HeartWidget (ECG), EyeWidget (EOG), MuscleBodyWidget (EMG).
# ============================================================
class HeartWidget(QtWidgets.QWidget):
    """Coração estilizado que PULSA a cada batimento detectado (pico R) e mostra
    o BPM — representação anatômica intuitiva do ECG (fica vermelho em arritmia)."""

    def __init__(self, parent=None):
        """Prepara o estado de pulso/BPM/alerta e liga o timer de 33 ms que anima
        o decaimento da batida.

        33 ms dá cerca de 30 quadros por segundo; o timer roda o tempo todo,
        mas só repinta quando há pulso ativo.
        """
        super().__init__(parent)
        self.setMinimumSize(150, 165)
        self._pulse = 0.0
        self._bpm = 0.0
        self._alert = False
        self._timer = QtCore.QTimer(self)
        self._timer.timeout.connect(self._decay)
        self._timer.start(33)

    def beat(self, bpm=None):
        """Dispara a animação de uma batida (pulso vai a 1.0) e, se vier o valor,
        atualiza o BPM mostrado."""
        self._pulse = 1.0
        if bpm is not None:
            self._bpm = float(bpm)
        self.update()

    def set_bpm(self, bpm):
        """Troca só o número de BPM exibido, sem animar batida."""
        self._bpm = float(bpm or 0.0); self.update()

    def set_alert(self, on):
        """Liga ou desliga o estado de alerta, que repinta o coração com a cor de
        erro."""
        self._alert = bool(on); self.update()

    def _decay(self):
        """Faz o pulso decair a cada tique do timer, produzindo o esmaecimento da
        batida.

        Cai 0,07 por quadro a 33 ms, então uma batida leva por volta de meio
        segundo para sumir.
        """
        if self._pulse > 0.0:
            self._pulse = max(0.0, self._pulse - 0.07); self.update()

    def _heart_path(self, cx, cy, s):
        """Constrói o contorno do coração a partir da curva cardióide clássica.

        Amostra a curva de 4 em 4 graus (91 pontos); `s` é o fator de escala
        que o paintEvent modula com o pulso para inflar a figura.
        """
        path = QtGui.QPainterPath()
        for i in range(0, 361, 4):
            t = math.radians(i)
            x = 16 * math.sin(t) ** 3
            y = (13 * math.cos(t) - 5 * math.cos(2 * t)
                 - 2 * math.cos(3 * t) - math.cos(4 * t))
            px, py = cx + x * s, cy - y * s
            path.moveTo(px, py) if i == 0 else path.lineTo(px, py)
        path.closeSubpath()
        return path

    def paintEvent(self, ev):
        """Desenha o coração preenchido com halo em volta e o BPM escrito no
        centro.

        Tamanho, espessura do halo e opacidade crescem com self._pulse (até
        cerca de +14% de escala). Enquanto o BPM for zero mostra "--".
        """
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        cx, cy = w / 2.0, h / 2.0 + 4
        s = min(w, h) * 0.028 * (1.0 + 0.14 * self._pulse)
        path = self._heart_path(cx, cy, s)
        col = QtGui.QColor(COLORS["error"] if self._alert
                           else SIGNAL_TYPE_COLORS.get("ECG", "#e0554e"))
        glow = QtGui.QColor(col); glow.setAlpha(int(50 + 130 * self._pulse))
        p.setPen(QtGui.QPen(glow, 5 + 9 * self._pulse))
        p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
        p.drawPath(path)
        fill = QtGui.QColor(col); fill.setAlpha(int(190 + 60 * self._pulse))
        p.setBrush(QtGui.QBrush(fill))
        p.setPen(QtGui.QPen(col.darker(130), 2))
        p.drawPath(path)
        p.setPen(QtGui.QPen(QtGui.QColor("#ffffff")))
        p.setFont(QtGui.QFont(FONT_UI, 15, QtGui.QFont.Weight.Bold))
        p.drawText(QtCore.QRectF(0, cy - 15, w, 24),
                   QtCore.Qt.AlignmentFlag.AlignCenter,
                   f"{self._bpm:.0f}" if self._bpm else "--")
        p.setFont(QtGui.QFont(FONT_UI, 8))
        p.drawText(QtCore.QRectF(0, cy + 7, w, 14),
                   QtCore.Qt.AlignmentFlag.AlignCenter, "bpm")


class EyeWidget(QtWidgets.QWidget):
    """Olho estilizado que PISCA quando uma piscada é detectada e cuja pupila
    acompanha o olhar (gaze) — representação intuitiva do EOG."""

    def __init__(self, parent=None):
        """Inicia o olho aberto e olhando ao centro e liga o timer de 33 ms que
        reabre a pálpebra."""
        super().__init__(parent)
        self.setMinimumSize(190, 120)
        self._blink = 0.0        # 0=aberto, 1=fechado
        self._gx = 0.0; self._gy = 0.0
        self._timer = QtCore.QTimer(self)
        self._timer.timeout.connect(self._decay)
        self._timer.start(33)

    def blink(self):
        """Fecha a pálpebra de uma vez; quem a reabre gradualmente é o _decay do
        timer."""
        self._blink = 1.0; self.update()

    def set_gaze(self, gx, gy):
        """Move a íris e a pupila conforme a direção do olhar.

        Clampa em [-1, +1]; no desenho o deslocamento ainda é limitado a 75% do
        espaço livre, de modo que a íris nunca encosta na borda da esclera.
        """
        self._gx = max(-1.0, min(1.0, float(gx)))
        self._gy = max(-1.0, min(1.0, float(gy)))
        self.update()

    def _decay(self):
        """Reabre a pálpebra aos poucos a cada tique do timer.

        Cai 0,16 por quadro a 33 ms, o que dá uma piscada de aproximadamente
        0,2 s.
        """
        if self._blink > 0.0:
            self._blink = max(0.0, self._blink - 0.16); self.update()

    def paintEvent(self, ev):
        """Desenha esclera, íris, pupila e brilho, e por cima a pálpebra descendo
        na proporção do blink.

        A íris é pintada com clip na forma da esclera para não vazar. A
        pálpebra é um retângulo pintado com a cor de fundo do widget: só parece
        uma pálpebra sobre superfície lisa.
        """
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        cx, cy = w / 2.0, h / 2.0
        ew = min(w * 0.42, 130.0); eh = min(h * 0.40, 62.0)
        eye = QtGui.QPainterPath(); eye.addEllipse(QtCore.QPointF(cx, cy), ew, eh)
        # esclera
        p.setBrush(QtGui.QBrush(QtGui.QColor("#fbfbfb")))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"]), 2))
        p.drawPath(eye)
        # íris + pupila (movem com o olhar, presas dentro da esclera)
        ir = eh * 0.72
        px = cx + self._gx * (ew - ir) * 0.75
        py = cy - self._gy * (eh - ir) * 0.75
        p.setClipPath(eye)
        p.setBrush(QtGui.QBrush(QtGui.QColor(SIGNAL_TYPE_COLORS.get("EoG", "#3a7bd5"))))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"]), 1))
        p.drawEllipse(QtCore.QPointF(px, py), ir, ir)
        p.setBrush(QtGui.QBrush(QtGui.QColor("#0c0c0c")))
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        p.drawEllipse(QtCore.QPointF(px, py), ir * 0.45, ir * 0.45)
        # brilho
        p.setBrush(QtGui.QBrush(QtGui.QColor("#ffffff")))
        p.drawEllipse(QtCore.QPointF(px - ir * 0.3, py - ir * 0.3), ir * 0.12, ir * 0.12)
        # pálpebra: desce de cima conforme o blink
        if self._blink > 0.01:
            lid_h = 2.0 * eh * self._blink
            p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface"])))
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.drawRect(QtCore.QRectF(cx - ew, cy - eh, 2 * ew, lid_h))
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"]), 2))
            yln = cy - eh + lid_h
            p.drawLine(QtCore.QPointF(cx - ew, yln), QtCore.QPointF(cx + ew, yln))
        p.setClipping(False)
        p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"]), 2))
        p.drawPath(eye)


class MuscleBodyWidget(QtWidgets.QWidget):
    """Silhueta do corpo com os músculos mapeados coloridos por ativação (%MVC)
    — o 'mapa topográfico' do EMG. Cada canal vira um ponto na região do músculo."""

    # posições normalizadas (x,y em 0..1) por REGIÃO anatômica (vista frontal)
    REGION_POS = {
        "Ombro":     [(0.32, 0.22), (0.68, 0.22)],
        "Braço":     [(0.26, 0.34), (0.74, 0.34)],
        "Antebraço": [(0.20, 0.47), (0.80, 0.47)],
        "Peito":     [(0.41, 0.27), (0.59, 0.27)],
        "Abdômen":   [(0.50, 0.42)],
        "Costas":    [(0.50, 0.33)],
        "Glúteo":    [(0.50, 0.55)],
        "Coxa":      [(0.41, 0.66), (0.59, 0.66)],
        "Perna":     [(0.41, 0.83), (0.59, 0.83)],
        "Pescoço":   [(0.50, 0.15)],
    }

    def __init__(self, parent=None):
        """Fixa o tamanho mínimo da silhueta e começa sem nenhum músculo ativado."""
        super().__init__(parent)
        self.setMinimumSize(220, 360)
        self._muscles = []   # [(label, region, pct 0..100)]

    def set_activations(self, items):
        """items: lista de (label, region, pct)."""
        self._muscles = list(items or [])
        self.update()

    def _body_path(self, w, h):
        """Monta a silhueta do corpo como uma elipse (cabeça) mais retângulos
        arredondados de tronco, braços e pernas.

        Todas as medidas são frações de w e h, então a figura acompanha o
        redimensionamento. O mesmo path também serve de região de recorte para
        o mapa de calor no paintEvent.
        """
        path = QtGui.QPainterPath()
        cx = w * 0.5
        path.addEllipse(QtCore.QPointF(cx, h * 0.10), w * 0.09, h * 0.06)  # cabeça
        # tronco + membros como um contorno simples
        path.addRoundedRect(QtCore.QRectF(w*0.36, h*0.18, w*0.28, h*0.40),
                            w*0.06, w*0.06)                                # tronco
        path.addRoundedRect(QtCore.QRectF(w*0.18, h*0.20, w*0.10, h*0.30),
                            w*0.04, w*0.04)                                # braço E
        path.addRoundedRect(QtCore.QRectF(w*0.72, h*0.20, w*0.10, h*0.30),
                            w*0.04, w*0.04)                                # braço D
        path.addRoundedRect(QtCore.QRectF(w*0.38, h*0.56, w*0.11, h*0.38),
                            w*0.05, w*0.05)                                # perna E
        path.addRoundedRect(QtCore.QRectF(w*0.51, h*0.56, w*0.11, h*0.38),
                            w*0.05, w*0.05)                                # perna D
        return path

    def paintEvent(self, ev):
        """Desenha a silhueta, os borrões de calor por %MVC nas regiões mapeadas e
        as setas com o rótulo nome + percentual.

        Quando mais de um canal cai na mesma região, os pontos alternam entre
        os slots de REGION_POS; região desconhecida vai parar no centro do
        abdômen. A cor vem de HeadPlotWidget._color_for_power, a mesma escala
        usada no mapa de EEG. As caixas de rótulo são presas dentro da largura
        do widget para não serem cortadas na borda. Sem músculos mapeados, só
        aparece o corpo e uma instrução.
        """
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        body = self._body_path(w, h)
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1))
        p.drawPath(body)
        if not self._muscles:
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
            p.setFont(QtGui.QFont(FONT_UI, 9))
            p.drawText(self.rect(), QtCore.Qt.AlignmentFlag.AlignBottom
                       | QtCore.Qt.AlignmentFlag.AlignHCenter,
                       tr("Mapeie músculos por canal para ver a ativação"))
            return
        # posições (uma por canal; regioes repetidas usam slots alternados)
        used, pts = {}, []
        for label, region, pct in self._muscles:
            slots = self.REGION_POS.get(region, [(0.50, 0.42)])
            k = used.get(region, 0); used[region] = k + 1
            nx, ny = slots[k % len(slots)]
            pts.append((str(label), nx * w, ny * h,
                        max(0.0, min(100.0, float(pct)))))
        # 1) MAPA DE CALOR: glows radiais (cor por %MVC) recortados na silhueta
        p.save(); p.setClipPath(body)
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        glow_r = min(w, h) * 0.17
        for _lbl, ex, ey, pct in pts:
            t = pct / 100.0
            c = HeadPlotWidget._color_for_power(t)
            grad = QtGui.QRadialGradient(ex, ey, glow_r)
            c0 = QtGui.QColor(c); c0.setAlpha(int(50 + 170 * t))
            c1 = QtGui.QColor(c); c1.setAlpha(0)
            grad.setColorAt(0.0, c0); grad.setColorAt(1.0, c1)
            p.setBrush(QtGui.QBrush(grad))
            p.drawEllipse(QtCore.QPointF(ex, ey), glow_r, glow_r)
        p.restore()
        # 2) SETAS direcionadas ao ponto + rótulo (nome + %) do lado externo
        p.setFont(QtGui.QFont(FONT_UI, 8, QtGui.QFont.Weight.Bold))
        fm = p.fontMetrics()
        for lbl, ex, ey, pct in pts:
            side = -1 if ex < w * 0.5 else 1
            lx = ex + side * (w * 0.16); ly = ey
            col = HeadPlotWidget._color_for_power(pct / 100.0)
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"]), 1.6))
            p.drawLine(QtCore.QPointF(lx, ly), QtCore.QPointF(ex, ey))
            ang = math.atan2(ey - ly, ex - lx); ah = 9.0
            tri = QtGui.QPolygonF([
                QtCore.QPointF(ex, ey),
                QtCore.QPointF(ex + ah * math.cos(ang + 2.62),
                               ey + ah * math.sin(ang + 2.62)),
                QtCore.QPointF(ex + ah * math.cos(ang - 2.62),
                               ey + ah * math.sin(ang - 2.62))])
            p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["text"])))
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.drawPolygon(tri)
            txt = f"{lbl[:14]}  {pct:.0f}%"
            tw = fm.horizontalAdvance(txt) + 12
            bx = lx if side > 0 else lx - tw
            bx = max(2.0, min(bx, w - tw - 2.0))   # nunca corta na borda
            p.setBrush(QtGui.QBrush(col))
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1))
            p.drawRoundedRect(QtCore.QRectF(bx, ly - 9, tw, 18), 4, 4)
            p.setPen(QtGui.QPen(QtGui.QColor("#000000")))
            p.drawText(QtCore.QRectF(bx, ly - 9, tw, 18),
                       QtCore.Qt.AlignmentFlag.AlignCenter, txt)


# ============================================================
# Mapa de co-contração agonista/antagonista
# ------------------------------------------------------------
# Método de Fonseca et al., "sEMG-Driven Robotic Prosthesis and Analysis of
# Muscle Activation in Transfemoral Amputees and Able-Bodied Individuals",
# IEEE/EMBS NER 2025, que por sua vez adapta o controlador volitivo de [12].
#
# A ideia: com um par agonista/antagonista (ex.: reto femoral = extensão,
# bíceps femoral = flexão do joelho), a RAZÃO entre as duas ativações diz a
# INTENÇÃO de movimento, independentemente da intensidade. Calibra-se pedindo
# ao voluntário que faça cada movimento; a nuvem de cada movimento vira uma
# reta pela origem (m_f e m_e). A bissetriz angular entre elas (m0) separa o
# espaço em "quer flexionar" e "quer estender".
# ============================================================
def cocontracao_reta(ativ_ext, ativ_flex):
    """Inclinação da reta pela ORIGEM que melhor descreve uma nuvem.

    Devolve m = média ponderada de flex/ext, no sentido de mínimos quadrados
    SEM intercepto (y = m·x): m = Σ(x·y)/Σ(x²). A reta é forçada pela origem
    porque "sem ativação nenhuma" tem de significar "sem intenção" — um
    intercepto livre daria intenção com músculo relaxado.

    Devolve None se não houver dado suficiente ou se o eixo x for todo zero.
    """
    x = np.asarray(ativ_ext, dtype=float).ravel()
    y = np.asarray(ativ_flex, dtype=float).ravel()
    if x.size < 2 or x.size != y.size:
        return None
    ok = np.isfinite(x) & np.isfinite(y)
    x, y = x[ok], y[ok]
    if x.size < 2:
        return None
    den = float(np.sum(x * x))
    if den <= 1e-12:
        return None
    return float(np.sum(x * y) / den)


def cocontracao_fronteira(m_flex, m_ext):
    """Reta que separa flexão de extensão: a BISSETRIZ ANGULAR das duas.

    m0 = tan( (atan(m_f) + atan(m_e)) / 2 ), como na eq. do artigo. Usa-se o
    ângulo, e não a média das inclinações, porque inclinação não é linear:
    a média aritmética de 0,1 e 10 daria 5,05, que visualmente não fica no
    meio das duas retas — já a bissetriz angular fica.
    """
    if m_flex is None or m_ext is None:
        return None
    if not (np.isfinite(m_flex) and np.isfinite(m_ext)):
        return None
    return float(math.tan((math.atan(m_flex) + math.atan(m_ext)) / 2.0))


def cocontracao_saida(m, m_flex, m_ext, m0, w_max=1.0):
    """Comando volitivo W a partir da razão m = u_flex / u_ext.

    Eq. (1) do artigo:
        W = w_max · (m − m0)/(m_f − m0)   se m >  m0   (região de flexão)
        W = w_max · (m − m0)/(m0 − m_e)   se m ≤ m0   (região de extensão)

    Em m = m0 a saída é 0 (nenhuma intenção); satura em ±w_max quando m chega
    à reta do movimento puro. O sinal indica o sentido: positivo para flexão,
    negativo para extensão. Devolve None quando o mapa não está calibrado.
    """
    if None in (m, m_flex, m_ext, m0):
        return None
    try:
        if m > m0:
            den = m_flex - m0
            if abs(den) < 1e-9:
                return None
            w = w_max * (m - m0) / den
        else:
            den = m0 - m_ext
            if abs(den) < 1e-9:
                return None
            w = w_max * (m - m0) / den
        if not np.isfinite(w):
            return None
        return float(max(-w_max, min(w_max, w)))
    except Exception:
        return None


def cocontracao_razao(u_flex, u_ext, piso=1e-3):
    """Razão m = u_flex / u_ext, protegida contra extensão ~zero.

    Sem o piso, um instante com o extensor relaxado mandaria m para o infinito
    e o ponto sairia do gráfico. O piso equivale a dizer "abaixo disto não dá
    para afirmar a intenção".
    """
    try:
        ue = max(float(u_ext), piso)
        return float(u_flex) / ue
    except Exception:
        return None


class CoContractionMapDialog(QtWidgets.QDialog):
    """Mapa de co-contração agonista/antagonista (método NER 2025).

    Fluxo de uso: escolher o canal de FLEXÃO e o de EXTENSÃO, gravar alguns
    segundos fazendo cada movimento (é a calibração), e o programa ajusta a
    reta de cada nuvem, traça a fronteira entre elas e passa a mostrar, ao
    vivo, de que lado da fronteira está a intenção do voluntário.

    As ativações são normalizadas por %MVC quando o canal tem MVC calibrada;
    sem isso ficam em µV, e aí só a RAZÃO entre os dois canais tem sentido —
    a razão é justamente o que o método usa.
    """

    def __init__(self, main):
        """Monta a janela do mapa: seleção do par de canais, gráfico das duas
        nuvens com as retas ajustadas, botões de calibração e a leitura
        numérica (mf, me, m0, m, W)."""
        super().__init__(main)
        self.main = main
        self.setWindowTitle(tr("Mapa de co-contração — intenção de movimento"))
        self.resize(940, 620)
        self._flex = []          # [(u_ext, u_flex)] coletados na flexão
        self._ext = []           # idem, na extensão
        self._coletando = None   # None | "flex" | "ext"
        self._mf = self._me = self._m0 = None

        v = QtWidgets.QVBoxLayout(self)
        intro = QtWidgets.QLabel(tr(
            "Mede a <b>intenção de movimento</b> a partir de um par de músculos "
            "antagonistas. Grave alguns segundos de cada movimento (calibração): "
            "cada nuvem vira uma reta, e a <b>bissetriz entre elas separa flexão "
            "de extensão</b>. Depois, o ponto ao vivo mostra de que lado está a "
            "intenção e com que intensidade.<br>"
            "<i>Método: Fonseca et al., IEEE/EMBS NER 2025 — controlador volitivo "
            "de prótese de joelho.</i>"))
        intro.setWordWrap(True)
        intro.setTextFormat(QtCore.Qt.TextFormat.RichText)
        v.addWidget(intro)

        # ---- seleção de canais ----
        sel = QtWidgets.QHBoxLayout()
        sel.addWidget(QtWidgets.QLabel(tr("Canal de FLEXÃO:")))
        self.cb_flex = QtWidgets.QComboBox()
        sel.addWidget(self.cb_flex)
        sel.addSpacing(14)
        sel.addWidget(QtWidgets.QLabel(tr("Canal de EXTENSÃO:")))
        self.cb_ext = QtWidgets.QComboBox()
        sel.addWidget(self.cb_ext)
        sel.addStretch(1)
        v.addLayout(sel)
        self._popular_canais()

        # ---- gráfico ----
        self.plot = pg.PlotWidget()
        self.plot.setBackground(COLORS["surface"])
        self.plot.showGrid(x=True, y=True, alpha=0.25)
        self.plot.setLabel("bottom", tr("Ativação EMG (extensão)"))
        self.plot.setLabel("left", tr("Ativação EMG (flexão)"))
        self.plot.addLegend(offset=(-10, 10))
        self.sc_flex = pg.ScatterPlotItem(size=5, pen=None,
                                          brush=pg.mkBrush(212, 54, 79, 150),
                                          name=tr("dados de flexão"))
        self.sc_ext = pg.ScatterPlotItem(size=5, pen=None,
                                         brush=pg.mkBrush(37, 99, 201, 150),
                                         name=tr("dados de extensão"))
        self.plot.addItem(self.sc_flex); self.plot.addItem(self.sc_ext)
        self.ln_mf = self.plot.plot([], [], pen=pg.mkPen("#d4364f", width=2),
                                    name="m_f")
        self.ln_me = self.plot.plot([], [], pen=pg.mkPen("#2563c9", width=2),
                                    name="m_e")
        self.ln_m0 = self.plot.plot(
            [], [], pen=pg.mkPen("#1a7f5a", width=2,
                                 style=QtCore.Qt.PenStyle.DashLine), name="m₀")
        self.ln_m = self.plot.plot([], [], pen=pg.mkPen("#00bcd4", width=2),
                                   name=tr("m (ao vivo)"))
        self.pt_m = pg.ScatterPlotItem(size=13, pen=pg.mkPen("#006e7a", width=2),
                                       brush=pg.mkBrush("#00bcd4"))
        self.plot.addItem(self.pt_m)
        v.addWidget(self.plot, 1)

        # ---- botões de calibração ----
        bt = QtWidgets.QHBoxLayout()
        self.btn_flex = QtWidgets.QPushButton(tr("● Gravar FLEXÃO"))
        self.btn_flex.setToolTip(tr(
            "Enquanto estiver pressionado o botão, peça o movimento de flexão. "
            "Clique de novo para parar."))
        self.btn_flex.setCheckable(True)
        self.btn_flex.clicked.connect(lambda: self._alternar("flex"))
        bt.addWidget(self.btn_flex)
        self.btn_ext = QtWidgets.QPushButton(tr("● Gravar EXTENSÃO"))
        self.btn_ext.setCheckable(True)
        self.btn_ext.clicked.connect(lambda: self._alternar("ext"))
        bt.addWidget(self.btn_ext)
        b_lim = QtWidgets.QPushButton(tr("Limpar calibração"))
        b_lim.clicked.connect(self._limpar)
        bt.addWidget(b_lim)
        bt.addStretch(1)
        b_load = QtWidgets.QPushButton(tr("Calibrar de uma sessão…"))
        b_load.setToolTip(tr(
            "Usa uma sessão já gravada, separando os movimentos pelos "
            "marcadores de fase, em vez de calibrar ao vivo."))
        b_load.clicked.connect(self._de_sessao)
        bt.addWidget(b_load)
        b_save = QtWidgets.QPushButton(tr("Salvar mapa (.json)…"))
        b_save.clicked.connect(self._salvar)
        bt.addWidget(b_save)
        v.addLayout(bt)

        # ---- leitura numérica ----
        self.lbl = QtWidgets.QLabel()
        self.lbl.setTextFormat(QtCore.Qt.TextFormat.RichText)
        self.lbl.setWordWrap(True)
        v.addWidget(self.lbl)
        self._atualizar_leitura(None, None)

        main._cocontr_dialog = self

    # ------------------------------------------------------------------
    def _popular_canais(self):
        """Lista os canais marcados como EMG, com o músculo quando definido."""
        for cb in (self.cb_flex, self.cb_ext):
            cb.clear()
        tipos = getattr(self.main.config, "channel_signal_types", [])
        musc = getattr(self.main.config, "emg_channel_muscle", [])
        achou = 0
        for ch in range(MAX_CHANNELS):
            if ch < len(tipos) and tipos[ch] != "EMG":
                continue
            if ch >= self.main.num_channels:
                continue
            nome = musc[ch] if ch < len(musc) and musc[ch] != "(não definido)" else ""
            rot = f"CH{ch + 1}" + (f" — {nome}" if nome else "")
            self.cb_flex.addItem(rot, ch)
            self.cb_ext.addItem(rot, ch)
            achou += 1
        if achou >= 2:
            self.cb_ext.setCurrentIndex(1)

    def _norm(self, ch, valor):
        """Converte µV para %MVC quando o canal tem MVC calibrada."""
        mvc = getattr(self.main.config, "emg_channel_mvc_uV", [])
        if ch < len(mvc):
            try:
                m = float(mvc[ch])
                if m > 1e-6:
                    return 100.0 * float(valor) / m
            except (TypeError, ValueError):
                pass
        return float(valor)

    def alimentar(self, env_por_canal):
        """Recebe o envelope ao vivo do EMG e atualiza coleta e ponto atual."""
        if not env_por_canal:
            return
        chf = self.cb_flex.currentData()
        che = self.cb_ext.currentData()
        if chf is None or che is None or chf == che:
            return
        if chf not in env_por_canal or che not in env_por_canal:
            return
        uf = self._norm(chf, env_por_canal[chf])
        ue = self._norm(che, env_por_canal[che])
        if self._coletando == "flex":
            self._flex.append((ue, uf))
            self._recalcular()
        elif self._coletando == "ext":
            self._ext.append((ue, uf))
            self._recalcular()
        self._marcar_ponto(ue, uf)

    def _alternar(self, qual):
        """Liga/desliga a coleta de um dos movimentos (só um por vez)."""
        botao = self.btn_flex if qual == "flex" else self.btn_ext
        outro = self.btn_ext if qual == "flex" else self.btn_flex
        outro.setChecked(False)
        self._coletando = qual if botao.isChecked() else None
        if self._coletando:
            (self._flex if qual == "flex" else self._ext).clear()

    def _limpar(self):
        """Descarta a calibração e volta o mapa ao estado inicial."""
        self._flex.clear(); self._ext.clear()
        self._mf = self._me = self._m0 = None
        self.btn_flex.setChecked(False); self.btn_ext.setChecked(False)
        self._coletando = None
        self._recalcular()

    def _recalcular(self):
        """Reajusta as retas e redesenha tudo."""
        if self._flex:
            xs, ys = zip(*self._flex)
            self.sc_flex.setData(xs, ys)
            self._mf = cocontracao_reta(xs, ys)
        else:
            self.sc_flex.setData([], []); self._mf = None
        if self._ext:
            xs, ys = zip(*self._ext)
            self.sc_ext.setData(xs, ys)
            self._me = cocontracao_reta(xs, ys)
        else:
            self.sc_ext.setData([], []); self._me = None
        self._m0 = cocontracao_fronteira(self._mf, self._me)
        # extensão do eixo x para desenhar as retas
        todos = [p[0] for p in self._flex] + [p[0] for p in self._ext]
        xmax = max(todos) * 1.15 if todos else 1.0
        for reta, item in ((self._mf, self.ln_mf), (self._me, self.ln_me),
                           (self._m0, self.ln_m0)):
            if reta is None:
                item.setData([], [])
            else:
                item.setData([0, xmax], [0, reta * xmax])

    def _marcar_ponto(self, ue, uf):
        """Desenha o ponto de intenção atual e atualiza os números."""
        self.pt_m.setData([ue], [uf])
        m = cocontracao_razao(uf, ue)
        if m is not None:
            xmax = max(ue * 1.4, 1e-6)
            self.ln_m.setData([0, xmax], [0, m * xmax])
        W = cocontracao_saida(m, self._mf, self._me, self._m0)
        # Índice clássico de co-contração (Falconer & Winter): quanto os DOIS
        # músculos estão ativos ao mesmo tempo. É outra pergunta que a do W —
        # W diz de que LADO da fronteira está a intenção; este diz se o par
        # está enrijecendo a articulação. Com m₀ ≠ 1 (o caso normal), ativações
        # iguais caem de um dos lados, e só este índice denuncia a rigidez.
        soma = uf + ue
        cc = (2.0 * min(uf, ue) / soma * 100.0) if soma > 1e-9 else 0.0
        self._atualizar_leitura(m, W, cc, max(uf, ue))

    def _atualizar_leitura(self, m, W, cc=None, pico=None):
        """Escreve mf/me/m0/m/W em texto, com a interpretação em palavras."""
        def f(x):
            """Formata número para leitura, com travessão quando não há valor."""
            return "—" if x is None or not np.isfinite(x) else f"{x:.3f}"
        if W is None:
            veredito = tr("(calibre os dois movimentos para ler a intenção)")
        elif abs(W) < 0.10:
            veredito = tr("em cima da fronteira — sem intenção definida")
        elif W > 0:
            veredito = tr("intenção de FLEXÃO") + f" — {abs(W) * 100:.0f}%"
        else:
            veredito = tr("intenção de EXTENSÃO") + f" — {abs(W) * 100:.0f}%"
        extra = ""
        if cc is not None and pico is not None and pico > 1e-6:
            rotulo = (tr("co-contração alta (articulação enrijecida)")
                      if cc >= 60 else tr("co-contração"))
            extra = f" &nbsp;·&nbsp; {rotulo}: {cc:.0f}%"
        self.lbl.setText(
            f"<b>m<sub>f</sub></b> = {f(self._mf)} &nbsp;&nbsp; "
            f"<b>m<sub>e</sub></b> = {f(self._me)} &nbsp;&nbsp; "
            f"<b>m<sub>0</sub></b> = {f(self._m0)} &nbsp;&nbsp;|&nbsp;&nbsp; "
            f"<b>m</b> = {f(m)} &nbsp;&nbsp; <b>W</b> = {f(W)}<br>"
            f"<span style='color:{COLORS['text_dim']}'>{veredito}{extra} "
            f"&nbsp;·&nbsp; {len(self._flex)} " + tr("amostras de flexão")
            + f", {len(self._ext)} " + tr("amostras de extensão") + "</span>")

    def _de_sessao(self):
        """Calibra a partir de uma sessão gravada, separando pelos marcadores.

        Procura no marker/evento as palavras de flexão e extensão; o que não
        casar com nenhuma das duas é ignorado. Serve para reaproveitar coletas
        antigas sem repetir o protocolo com o voluntário.
        """
        inicio = getattr(self.main.config, "save_directory", "")
        caminho, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Sessão para calibrar o mapa"), inicio, "CSV (*.csv)")
        if not caminho:
            return
        d = self.main._load_session_csv(caminho)
        if not d:
            QtWidgets.QMessageBox.warning(self, tr("Sessão"),
                                          tr("Não consegui ler essa sessão."))
            return
        chf = self.cb_flex.currentData(); che = self.cb_ext.currentData()
        eeg = d["eeg"]
        if chf is None or che is None or max(chf, che) >= eeg.shape[0]:
            QtWidgets.QMessageBox.warning(
                self, tr("Canais"),
                tr("A sessão não tem os canais escolhidos."))
            return
        sr = d["sr"]
        # Mesmo metodo e mesma janela do ao vivo: "rms" minusculo caia no ramo
        # |x|+LP e a nuvem calibrada nascia ~20% abaixo da escala do ponto vivo.
        met = getattr(self.main.config, "emg_envelope_method", "RMS")
        jan = float(getattr(self.main.config, "emg_envelope_window_ms", 100))
        env_f = self.main._compute_emg_envelope(eeg[chf], sr, met, jan)
        env_e = self.main._compute_emg_envelope(eeg[che], sr, met, jan)
        marks = d.get("markers") or []
        PAL_FLEX = ("flex", "flexao", "flexão", "flexion")
        PAL_EXT = ("ext", "extensao", "extensão", "extension")
        self._flex.clear(); self._ext.clear()
        usados = 0
        for mk in marks:
            try:
                rot = str(mk.get("label", "")).lower()
                i0 = int(mk.get("sample", 0))
                i1 = min(i0 + int(2 * sr), len(env_f), len(env_e))
            except Exception:
                continue
            if i1 - i0 < 10:
                continue
            alvo = (self._flex if any(p in rot for p in PAL_FLEX)
                    else self._ext if any(p in rot for p in PAL_EXT) else None)
            if alvo is None:
                continue
            for i in range(i0, i1, max(1, int(sr // 20))):
                alvo.append((self._norm(che, env_e[i]), self._norm(chf, env_f[i])))
            usados += 1
        if not usados:
            QtWidgets.QMessageBox.information(
                self, tr("Sem marcadores de movimento"),
                tr("Essa sessão não tem marcadores com 'flexão' ou 'extensão' "
                   "no nome, então não dá para separar os dois movimentos.\n\n"
                   "Use a calibração ao vivo, ou grave a sessão com o protocolo "
                   "de fases nomeando os movimentos."))
            return
        self._recalcular()

    def _salvar(self):
        """Grava o mapa em .json — é o que alimenta um controlador de prótese."""
        if self._m0 is None:
            QtWidgets.QMessageBox.information(
                self, tr("Mapa incompleto"),
                tr("Calibre os dois movimentos antes de salvar."))
            return
        inicio = getattr(self.main.config, "save_directory", "")
        caminho, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Salvar mapa de co-contração"),
            os.path.join(inicio, "mapa_cocontracao.json"), "JSON (*.json)")
        if not caminho:
            return
        chf = self.cb_flex.currentData(); che = self.cb_ext.currentData()
        musc = getattr(self.main.config, "emg_channel_muscle", [])
        dados = {
            "metodo": ("mapa de co-contracao agonista/antagonista; "
                       "Fonseca et al., IEEE/EMBS NER 2025"),
            "gerado_por": f"{APP_NAME} v{APP_VERSION}",
            "canal_flexao": chf, "canal_extensao": che,
            "musculo_flexao": (musc[chf] if chf is not None and chf < len(musc) else ""),
            "musculo_extensao": (musc[che] if che is not None and che < len(musc) else ""),
            "m_flexao": self._mf, "m_extensao": self._me, "m_fronteira": self._m0,
            "n_amostras_flexao": len(self._flex),
            "n_amostras_extensao": len(self._ext),
            "unidade": "%MVC quando calibrado, senao uV",
        }
        try:
            with open(caminho, "w", encoding="utf-8") as f:
                json.dump(dados, f, ensure_ascii=False, indent=2)
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self, tr("Salvar"), str(exc))
            return
        QtWidgets.QMessageBox.information(
            self, tr("Salvo"), f"{tr('Mapa salvo em')}:\n{caminho}")

    def closeEvent(self, ev):
        """Solta a referência na janela principal para o EMG parar de alimentar."""
        if getattr(self.main, "_cocontr_dialog", None) is self:
            self.main._cocontr_dialog = None
        super().closeEvent(ev)


# ============================================================
# MuscleAtlasWidget — atlas muscular INTERATIVO (posicionar eletrodos)
# ============================================================
class MuscleAtlasWidget(QtWidgets.QWidget):
    """Atlas muscular interativo — vistas FRONTAL e POSTERIOR.

    Recursos:
      • silhueta anatômica com os principais grupos (braço, perna, pescoço,
        rosto, peito, costas, glúteo, panturrilha, ...);
      • mapa de calor (%MVC) por músculo mapeado a um canal;
      • posicionamento CLICÁVEL de eletrodos numerados (1, 2, 3, ...),
        renomeáveis, arrastáveis, com anel de QUALIDADE/acurácia do contato;
      • exportação da imagem final em alta resolução.
    QPainter puro — sem dependência de 'pip install'; roda no .exe.
    """

    sigElectrodesChanged = QtCore.Signal()
    sigElectrodeSelected = QtCore.Signal(int)   # id do eletrodo (ou -1)
    sigZoomChanged = QtCore.Signal(float)      # fator de zoom atual

    HANDLE_R = 12.0    # raio base do marcador de eletrodo (px)

    def __init__(self, parent=None):
        """Prepara o estado do atlas: vista frontal, lista de eletrodos, mapas de
        ativação e de dados ao vivo, seleção e margens reservadas.

        Mouse tracking e ClickFocus são ligados porque o widget trata arraste
        do eletrodo e a tecla Delete. _pad_top/_pad_bot reservam 24 e 42 px no
        topo e no rodapé para que o corpo não invada título nem legenda.
        """
        super().__init__(parent)
        self.setMinimumSize(300, 470)
        self.setMouseTracking(True)
        self.setFocusPolicy(QtCore.Qt.FocusPolicy.ClickFocus)
        self._view = "front"
        self._electrodes = []     # [{id,name,x,y,view,channel,muscle}]
        self._muscle_act = {}     # muscle_name -> pct (0..100)
        self._live = {}           # canal(0-based) -> (pct, quality 0..100)
        self._sel = -1            # id do eletrodo selecionado
        self._place_mode = False
        self._dragging = False
        self._show_labels = True
        self._pad_top = 24        # faixa reservada p/ título (px)
        self._pad_bot = 42        # faixa reservada p/ legenda/contagem (px)
        self._zoom = 1.0          # 1.0 = corpo inteiro
        self._foco_n = (0.5, 0.5) # ponto que fica parado ao ampliar
        self._pan_ini = None      # arraste com o botao direito
        self.setToolTip(
            tr("Clique em 'Adicionar eletrodo' e clique no corpo para posicionar.\n"
            "ARRASTE o eletrodo sobre o corpo: o mapa de calor acompanha e mostra\n"
            "a intensidade da área muscular medida ali (quanto mais forte a\n"
            "contração, maior e mais quente a mancha). O músculo é reconhecido\n"
            "automaticamente pela posição.\n"
            "Duplo-clique renomeia · Delete remove o selecionado."))

    # ---------------- API pública ----------------
    def set_view(self, view):
        """Alterna o atlas entre a vista frontal e a posterior.

        Qualquer valor diferente de "back" é tratado como "front".
        """
        self._view = "back" if view == "back" else "front"
        self.update()

    def get_view(self):
        """Devolve a vista em exibição, "front" ou "back"."""
        return self._view

    def set_show_labels(self, on):
        """Liga ou desliga a exibição dos rótulos dos eletrodos."""
        self._show_labels = bool(on); self.update()

    def set_place_mode(self, on):
        """Arma o modo de posicionamento, em que o próximo clique no corpo cria um
        eletrodo em vez de selecionar.

        Também troca o cursor para cruz. Não desliga sozinho após o clique:
        quem ativou precisa chamar set_place_mode(False).
        """
        self._place_mode = bool(on)
        self.setCursor(QtCore.Qt.CursorShape.CrossCursor if on
                       else QtCore.Qt.CursorShape.ArrowCursor)

    def set_muscle_activations(self, d):
        """Atualiza o dicionário músculo -> %MVC que alimenta o mapa de calor e
        redesenha o atlas.

        Valores em porcentagem (0..100). Serve de fallback: um eletrodo só usa
        esse valor quando não tem canal ligado com leitura ao vivo.
        """
        self._muscle_act = dict(d or {}); self.update()

    def set_live_channel_data(self, d):
        """Recebe as leituras ao vivo por canal que definem a intensidade do calor
        e o anel de qualidade dos eletrodos.

        Formato: canal 0-based -> (pct de MVC, qualidade 0..100). Canal ausente
        no dicionário faz o eletrodo cair no valor do músculo.
        """
        self._live = dict(d or {}); self.update()

    def set_electrodes(self, items):
        """Repõe a lista de eletrodos a partir de dados salvos (sessão/JSON),
        normalizando os campos de cada item.

        Entradas malformadas são descartadas em silêncio pelo try/except. Não
        emite sigElectrodesChanged nem mexe na seleção atual.
        """
        self._electrodes = []
        for e in (items or []):
            try:
                self._electrodes.append({
                    "id":      int(e.get("id", self._next_id())),
                    "name":    str(e.get("name", "")),
                    "x":       float(e.get("x", 0.5)),
                    "y":       float(e.get("y", 0.5)),
                    "view":    "back" if e.get("view") == "back" else "front",
                    "channel": int(e.get("channel", -1)),
                    "muscle":  str(e.get("muscle", "")),
                })
            except Exception:
                continue
        self.update()

    def get_electrodes(self):
        """Devolve cópias dos eletrodos para serialização ou para preencher
        tabelas da interface."""
        return [dict(e) for e in self._electrodes]

    def selected_id(self):
        """Id do eletrodo selecionado, ou -1 quando não há seleção."""
        return self._sel

    def select(self, eid):
        """Seleciona um eletrodo por id a partir de fora do widget (lista lateral,
        por exemplo) e emite sigElectrodeSelected."""
        self._sel = int(eid); self.update()
        self.sigElectrodeSelected.emit(self._sel)

    def _next_id(self):
        """Gera o número do próximo eletrodo a partir do maior id existente.

        Como usa o máximo, apagar o último eletrodo faz o próximo reaproveitar
        o mesmo número.
        """
        return max((e["id"] for e in self._electrodes), default=0) + 1

    def _nearest_muscle(self, nx, ny, view, max_d=0.14):
        """Músculo sob a posição (nx, ny), em coordenadas normalizadas.

        O corpo é BILATERAL mas o mapa ATLAS_MUSCLE_XY guarda cada músculo uma
        única vez (num dos lados). Sem espelhar, arrastar o eletrodo para o
        braço/perna do outro lado não reconhecia nada e o mapa de calor ficava
        sem intensidade. Aqui testamos a posição e o seu espelho em torno da
        linha média (x = 0.5) — o nome do músculo é o mesmo dos dois lados.
        """
        best, bd = "", 1e9
        nx_esp = 1.0 - nx          # espelho em torno da linha média
        for m, (v, mx, my) in ATLAS_MUSCLE_XY.items():
            if v != view:
                continue
            d = min((mx - nx) ** 2 + (my - ny) ** 2,
                    (mx - nx_esp) ** 2 + (my - ny) ** 2)
            if d < bd:
                bd, best = d, m
        return best if bd <= max_d ** 2 else ""

    def muscle_side(self, nx):
        """Lado do corpo pela posição horizontal (vista frontal: o lado direito
        do voluntário aparece à ESQUERDA de quem olha)."""
        if abs(nx - 0.5) < 0.06:
            return ""                      # linha média (tronco/centro)
        if self._view == "front":
            return "D" if nx < 0.5 else "E"
        return "E" if nx < 0.5 else "D"

    def add_electrode(self, nx, ny, view=None, name=None, channel=-1, muscle=""):
        """Cria um eletrodo na posição normalizada indicada, já reconhecendo pelo
        local o músculo medido.

        x e y são presos em 0.02..0.98 para o marcador não sair da área
        desenhada. O nome padrão é E<id> e o novo eletrodo já sai selecionado;
        emite os dois sinais.
        """
        eid = self._next_id()
        view = view or self._view
        snap_m = muscle or self._nearest_muscle(nx, ny, view)
        e = {"id": eid, "name": name or f"E{eid}",
             "x": float(max(0.02, min(0.98, nx))),
             "y": float(max(0.02, min(0.98, ny))),
             "view": view, "channel": int(channel), "muscle": snap_m}
        self._electrodes.append(e)
        self._sel = eid
        self.update()
        self.sigElectrodesChanged.emit()
        self.sigElectrodeSelected.emit(eid)
        return e

    def remove_selected(self):
        """Remove o eletrodo selecionado (tecla Delete ou botão da barra) e zera a
        seleção."""
        if self._sel < 0:
            return
        self._electrodes = [e for e in self._electrodes if e["id"] != self._sel]
        self._sel = -1
        self.update()
        self.sigElectrodesChanged.emit()
        self.sigElectrodeSelected.emit(-1)

    def clear_all(self):
        """Esvazia o mapa de eletrodos inteiro e limpa a seleção.

        Apaga também os eletrodos da vista que não está aparecendo; a
        confirmação com o usuário, se houver, é responsabilidade de quem chama.
        """
        self._electrodes = []; self._sel = -1
        self.update(); self.sigElectrodesChanged.emit()
        self.sigElectrodeSelected.emit(-1)

    def _find(self, eid):
        """Busca linear do eletrodo pelo id, devolvendo None quando não existe."""
        for e in self._electrodes:
            if e["id"] == eid:
                return e
        return None

    def rename(self, eid, new_name):
        """Aplica o nome novo vindo do duplo-clique ou do painel lateral e
        redesenha.

        O nome é truncado em 24 caracteres para o rótulo desenhado ao lado do
        marcador não estourar.
        """
        e = self._find(eid)
        if e:
            e["name"] = str(new_name)[:24]
            self.update(); self.sigElectrodesChanged.emit()

    def set_channel(self, eid, ch, muscle=None):
        """Vincula o eletrodo a um canal de aquisição, o que faz o marcador passar
        a exibir %MVC e qualidade ao vivo.

        O músculo só é sobrescrito quando o argumento muscle não é None; passar
        string vazia apaga o músculo reconhecido.
        """
        e = self._find(eid)
        if e:
            e["channel"] = int(ch)
            if muscle is not None:
                e["muscle"] = str(muscle)
            self.update(); self.sigElectrodesChanged.emit()

    # ---------------- mapeamento de coordenadas (mantém paint↔mouse alinhados) ----------------
    def _by(self, fy, h):
        """Fração anatômica (0..1) -> pixel Y dentro da faixa do corpo."""
        return self._pad_top + fy * max(1.0, (h - self._pad_top - self._pad_bot))

    def _fy(self, py, h):
        """Converte pixel Y de volta para a fração anatômica 0..1, inverso de _by
        usado no tratamento do mouse.

        Tem de acompanhar _by: se _pad_top/_pad_bot mudarem só de um lado,
        clique e desenho saem de registro.
        """
        span = max(1.0, h - self._pad_top - self._pad_bot)
        return (py - self._pad_top) / span

    # ---------------- geometria ----------------
    def _silhouette(self, w, h):
        """Contorno humanoide simétrico (serve p/ frontal e posterior)."""
        p = QtGui.QPainterPath()
        cx = w * 0.5
        Y = lambda f: self._by(f, h)      # noqa: E731
        # altura efetiva do corpo (p/ raios verticais escalarem com a faixa)
        bh = max(1.0, h - self._pad_top - self._pad_bot)
        p.addEllipse(QtCore.QPointF(cx, Y(0.075)), w * 0.072, bh * 0.058)   # cabeça
        p.addRect(QtCore.QRectF(cx - w * 0.035, Y(0.115),
                                w * 0.07, bh * 0.05))                       # pescoço
        torso = QtGui.QPolygonF([
            QtCore.QPointF(cx - w * 0.175, Y(0.19)),
            QtCore.QPointF(cx + w * 0.175, Y(0.19)),
            QtCore.QPointF(cx + w * 0.135, Y(0.35)),
            QtCore.QPointF(cx + w * 0.155, Y(0.485)),
            QtCore.QPointF(cx - w * 0.155, Y(0.485)),
            QtCore.QPointF(cx - w * 0.135, Y(0.35)),
        ])
        tp = QtGui.QPainterPath(); tp.addPolygon(torso); p.addPath(tp)
        p.addEllipse(QtCore.QPointF(cx - w * 0.175, Y(0.205)), w * 0.055, bh * 0.045)
        p.addEllipse(QtCore.QPointF(cx + w * 0.175, Y(0.205)), w * 0.055, bh * 0.045)
        for s in (-1, 1):
            p.addRoundedRect(QtCore.QRectF(cx + s * w * 0.26 - w * 0.05, Y(0.205),
                                           w * 0.10, bh * 0.175), w * 0.03, w * 0.03)  # braço
            p.addRoundedRect(QtCore.QRectF(cx + s * w * 0.335 - w * 0.043, Y(0.365),
                                           w * 0.086, bh * 0.155), w * 0.03, w * 0.03)  # antebraço
            p.addEllipse(QtCore.QPointF(cx + s * w * 0.355, Y(0.535)), w * 0.036, bh * 0.028)  # mão
            p.addRoundedRect(QtCore.QRectF(cx + s * w * 0.075 - w * 0.062, Y(0.475),
                                           w * 0.124, bh * 0.225), w * 0.045, w * 0.045)  # coxa
            p.addRoundedRect(QtCore.QRectF(cx + s * w * 0.075 - w * 0.052, Y(0.685),
                                           w * 0.104, bh * 0.205), w * 0.038, w * 0.038)  # panturrilha
            p.addEllipse(QtCore.QPointF(cx + s * w * 0.075, Y(0.905)), w * 0.052, bh * 0.03)  # pé
        return p

    def _hit(self, px, py, w, h):
        """Retorna id do eletrodo (vista atual) sob o ponto, ou -1."""
        r2 = (self.HANDLE_R + 4) ** 2
        best, bd = -1, r2
        for e in self._electrodes:
            if e["view"] != self._view:
                continue
            d = (e["x"] * w - px) ** 2 + (self._by(e["y"], h) - py) ** 2
            if d <= bd:
                bd, best = d, e["id"]
        return best

    @staticmethod
    def _quality_color(q):
        """Escolhe a cor do anel de contato de acordo com a qualidade medida do
        eletrodo.

        Faixas: >=75 verde, >=50 amarelo, >=30 laranja, abaixo disso vermelho.
        Qualidade None (canal sem leitura) devolve o cinza de texto apagado.
        """
        if q is None:
            return QtGui.QColor(COLORS.get("text_dim", "#8a8a8a"))
        if q >= 75:
            return QtGui.QColor(COLORS.get("success", "#2ea043"))
        if q >= 50:
            return QtGui.QColor(COLORS.get("warning", "#d29922"))
        if q >= 30:
            return QtGui.QColor("#e07b30")
        return QtGui.QColor(COLORS.get("error", "#e05050"))

    # ---------------- render ----------------
    # ---------------- zoom e deslocamento ----------------
    # O corpo inteiro num painel pequeno deixa antebraço/mão do tamanho de
    # poucos pixels, e posicionar eletrodo ali vira sorte. O zoom é aplicado
    # como TRANSFORMAÇÃO do QPainter, e o mouse passa pela transformação
    # INVERSA — assim toda a geometria existente continua valendo, sem
    # reescrever silhueta, músculos e eletrodos.
    ZOOM_MIN, ZOOM_MAX = 1.0, 8.0

    # (rótulo, zoom, foco x, foco y) — o foco é a fração do widget que fica
    # parada na tela ao ampliar.
    # Rótulos em português DE PROPÓSITO: isto é atributo de classe e um tr()
    # aqui seria resolvido uma única vez, no import, congelando a lista no
    # idioma inicial. Quem monta o seletor chama tr() na hora e guarda esta
    # string como dado — é ela que zoom_regiao() compara.
    REGIOES = (
        ("Corpo inteiro", 1.0, 0.50, 0.50),
        ("Cabeça e pescoço", 3.4, 0.50, 0.09),
        ("Ombro e braço", 2.6, 0.30, 0.28),
        ("Antebraço e mão", 3.6, 0.22, 0.42),
        ("Tronco", 2.0, 0.50, 0.32),
        ("Quadril e coxa", 2.4, 0.50, 0.60),
        ("Perna e pé", 2.8, 0.50, 0.84),
    )

    def _transf(self, w, h):
        """(deslocamento x, deslocamento y, zoom) da vista atual."""
        z = float(getattr(self, "_zoom", 1.0))
        fx = float(getattr(self, "_foco_n", (0.5, 0.5))[0]) * w
        fy = float(getattr(self, "_foco_n", (0.5, 0.5))[1]) * h
        return fx * (1.0 - z), fy * (1.0 - z), z

    def _pos_logica(self, ev):
        """Posição do mouse DESFEITO o zoom — é o que a geometria entende."""
        w, h = self.width(), self.height()
        ox, oy, z = self._transf(w, h)
        return ((ev.position().x() - ox) / z, (ev.position().y() - oy) / z)

    def set_zoom(self, z, foco_n=None):
        """Ajusta o zoom (e opcionalmente o ponto focal, em fração 0..1)."""
        self._zoom = max(self.ZOOM_MIN, min(self.ZOOM_MAX, float(z)))
        if foco_n is not None:
            self._foco_n = (min(1.0, max(0.0, float(foco_n[0]))),
                            min(1.0, max(0.0, float(foco_n[1]))))
        if abs(self._zoom - 1.0) < 1e-6:
            self._foco_n = (0.5, 0.5)      # sem zoom, sempre centrado
        self.update()
        self.sigZoomChanged.emit(self._zoom)

    def zoom_regiao(self, nome):
        """Aplica um dos enquadramentos prontos (antebraço, coxa, ...)."""
        for rot, z, fx, fy in self.REGIOES:
            if rot == nome:
                self.set_zoom(z, (fx, fy))
                return True
        return False

    def wheelEvent(self, ev):
        """Roda do mouse amplia/reduz ANCORADO NO CURSOR.

        Ancorar no cursor é o que faz o zoom parecer natural: o ponto sob o
        mouse não escapa enquanto se aproxima do músculo.
        """
        d = ev.angleDelta().y()
        if not d:
            return
        w, h = self.width(), self.height()
        antes = self._zoom
        novo = antes * (1.15 if d > 0 else 1 / 1.15)
        novo = max(self.ZOOM_MIN, min(self.ZOOM_MAX, novo))
        if abs(novo - antes) < 1e-9:
            ev.accept(); return
        if novo <= 1.0 + 1e-9:
            self.set_zoom(1.0)
        else:
            # Mantém sob o cursor o mesmo ponto lógico de antes. Isolando o
            # foco de   tela = lógico·z + foco·(1 − z):
            #     foco = (tela − z·lógico) / (1 − z)
            # ATENÇÃO ao denominador: ao AMPLIAR, (1 − z) é NEGATIVO. Um
            # max(1e-9, 1−z) aqui destruía o sinal e a âncora ia parar longe —
            # o ponto sob o cursor fugia a cada giro da roda.
            den = 1.0 - novo
            if abs(den) < 1e-9:
                ev.accept(); return
            lx, ly = self._pos_logica(ev)
            px, py = ev.position().x(), ev.position().y()
            fx = (px - novo * lx) / den / max(1.0, w)
            fy = (py - novo * ly) / den / max(1.0, h)
            self.set_zoom(novo, (fx, fy))
        ev.accept()

    def paintEvent(self, ev):
        """Ponto de entrada do Qt para redesenhar o atlas na tela.

        NÃO aplica mais o zoom ao painter inteiro. Fazia isso antes, e com
        isso o zoom ampliava também o texto: no enquadramento do antebraço
        (3,6x) o rótulo de um eletrodo ficava três vezes mais largo que a
        caixa, atravessava a figura e saía cortado na borda. Quem escala é só
        a geometria do corpo; marcador, número e rótulo têm tamanho de tela.
        """
        p = QtGui.QPainter(self)
        self._paint(p, self.width(), self.height())

    def render_highres(self, scale=2.0, title=""):
        """Gera um QPixmap ampliado do atlas para exportar a imagem do
        posicionamento dos eletrodos.

        Reaproveita _paint com p.scale(), então o layout exportado é o da
        janela no momento: redimensionar o widget muda a imagem. O título extra
        só aparece nessa rota.
        """
        w, h = self.width(), self.height()
        pm = QtGui.QPixmap(max(1, int(w * scale)), max(1, int(h * scale)))
        pm.fill(QtGui.QColor(COLORS["surface"]))
        p = QtGui.QPainter(pm)
        p.scale(scale, scale)
        self._paint(p, w, h, export_title=title)
        p.end()
        return pm

    def _paint(self, p, w, h, export_title=None):
        """Desenha o atlas completo: cabeçalho da vista, silhueta, rótulos de
        grupo, mapa de calor, eletrodos e legenda de qualidade.

        Compartilhado por paintEvent e render_highres, por isso w/h chegam por
        parâmetro e não se deve usar self.width() aqui. O calor é recortado
        pela silhueta (setClipPath) e cada eletrodo pinta a mancha na posição
        em que foi colado, não na posição anatômica do músculo.
        """
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        p.fillRect(0, 0, w, h, QtGui.QColor(COLORS["surface"]))
        body = self._silhouette(w, h)
        # O zoom vale para o DESENHO DO CORPO, não para o texto. `_tela`
        # converte uma coordenada do corpo para o pixel onde ela aparece, e é
        # com ela que os rótulos e os marcadores se posicionam mantendo o
        # tamanho de leitura.
        _ox, _oy, _z = self._transf(w, h)
        self._z_atual = _z

        def _tela(lx, ly):
            """Coordenada do corpo -> pixel na tela, já com o zoom aplicado."""
            return (_ox + lx * _z, _oy + ly * _z)

        def _sob_zoom():
            """Contexto do painter com a transformação do zoom aplicada."""
            p.save()
            if abs(_z - 1.0) > 1e-6:
                p.translate(_ox, _oy)
                p.scale(_z, _z)

        # O cabeçalho é desenhado no FIM, junto com a legenda: com zoom, a
        # silhueta ampliada passa por cima do topo do widget e comia as
        # primeiras letras de "Vista Frontal (anterior)".

        # silhueta (sob o zoom)
        _sob_zoom()
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1.4))
        p.drawPath(body)
        # linha de simetria / coluna (dá a sensação de frontal vs posterior)
        cx = w * 0.5
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1,
                            QtCore.Qt.PenStyle.DashLine if self._view == "front"
                            else QtCore.Qt.PenStyle.SolidLine))
        p.drawLine(QtCore.QPointF(cx, self._by(0.17, h)),
                   QtCore.QPointF(cx, self._by(0.48, h)))
        p.restore()

        # rótulos de grupo (guia suave) — acompanham a anatomia, mas em
        # tamanho de tela: ampliados pelo zoom eles cobriam o corpo inteiro.
        if self._show_labels:
            p.setFont(QtGui.QFont(FONT_UI, 7))
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
            for name_pt, gx, gy in ATLAS_GROUP_LABELS.get(self._view, []):
                sx, sy = _tela(gx * w, self._by(gy, h))
                if not (-40 <= sx <= w + 40 and 0 <= sy <= h):
                    continue
                p.drawText(QtCore.QRectF(sx - 40, sy - 7, 80, 14),
                           QtCore.Qt.AlignmentFlag.AlignCenter, tr(name_pt))

        # 1) HEATMAP DE INTENSIDADE — o calor SEGUE O ELETRODO.
        #
        # Antes a mancha era desenhada na posição anatômica fixa do músculo
        # (ATLAS_MUSCLE_XY), então arrastar o eletrodo não mudava nada. Agora
        # cada eletrodo pinta a área que ELE está medindo, na posição em que
        # foi colado, e o RAIO cresce com a ativação: quanto mais forte a
        # contração, maior a área destacada. É o mapa de calor da região
        # muscular efetivamente trabalhada.
        # O calor pertence ao corpo: escala junto com ele.
        _sob_zoom()
        p.setClipPath(body)
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        base_r = min(w, h) * 0.10

        def _glow(cx, cy, t, raio):
            """Pinta uma mancha radial de calor num ponto, com cor e opacidade
            proporcionais à intensidade.

            Fecha sobre o QPainter p de _paint. t vai de 0 a 1; o alfa do
            centro varia de 45 a 230 e o raio é passado por quem chama (cresce
            com a ativação).
            """
            c = HeadPlotWidget._color_for_power(t)
            grad = QtGui.QRadialGradient(cx, cy, raio)
            c0 = QtGui.QColor(c); c0.setAlpha(int(45 + 185 * t))
            cm = QtGui.QColor(c); cm.setAlpha(int(20 + 90 * t))
            c1 = QtGui.QColor(c); c1.setAlpha(0)
            grad.setColorAt(0.0, c0); grad.setColorAt(0.55, cm)
            grad.setColorAt(1.0, c1)
            p.setBrush(QtGui.QBrush(grad))
            p.drawEllipse(QtCore.QPointF(cx, cy), raio, raio)

        cobertos = set()
        for e in self._electrodes:
            if e.get("view") != self._view:
                continue
            # intensidade: %MVC ao vivo do canal ligado; se não houver canal,
            # cai para a ativação do músculo sob o eletrodo
            pct, ch = None, e.get("channel")
            if ch is not None and ch >= 0 and ch in self._live:
                pct = self._live[ch][0]
            if pct is None and e.get("muscle"):
                pct = self._muscle_act.get(e["muscle"])
            if pct is None:
                continue
            t = max(0.0, min(1.0, float(pct) / 100.0))
            # a área cresce ~75%..160% do raio base conforme a intensidade
            _glow(e["x"] * w, self._by(e["y"], h), t, base_r * (0.75 + 0.85 * t))
            if e.get("muscle"):
                cobertos.add(e["muscle"])

        # Músculos com ativação mas SEM eletrodo colado continuam sendo
        # mostrados na sua posição anatômica (não se perde informação).
        for m, (v, mx, my) in ATLAS_MUSCLE_XY.items():
            if v != self._view or m in cobertos:
                continue
            pct = self._muscle_act.get(m)
            if pct is None:
                continue
            t = max(0.0, min(1.0, float(pct) / 100.0))
            _glow(mx * w, self._by(my, h), t, base_r * (0.75 + 0.85 * t))
        p.restore()

        # 2) ELETRODOS — em coordenada de tela, com tamanho constante
        self._paint_electrodes(p, w, h, _tela)

        # 3) cabeçalho, legendas e contagem — por cima de tudo
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"])))
        p.setFont(QtGui.QFont(FONT_UI, 10, QtGui.QFont.Weight.Bold))
        head = (tr("Vista Frontal (anterior)") if self._view == "front"
                else tr("Vista Posterior"))
        fundo = QtGui.QColor(COLORS["surface"])
        fundo.setAlpha(215)
        # Na exportacao a faixa cresce: o subtitulo ficava metade fora do fundo
        # opaco, desenhado por cima do corpo.
        p.fillRect(QtCore.QRectF(0, 0, w, 36 if export_title else 21), fundo)
        p.drawText(QtCore.QRectF(0, 2, w, 18),
                   QtCore.Qt.AlignmentFlag.AlignHCenter, head)
        if export_title:
            p.setFont(QtGui.QFont(FONT_UI, 8))
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
            p.drawText(QtCore.QRectF(0, 20, w, 14),
                       QtCore.Qt.AlignmentFlag.AlignHCenter, export_title[:60])
        p.fillRect(QtCore.QRectF(0, h - 38, w, 38), fundo)
        p.setFont(QtGui.QFont(FONT_UI, 8))
        n_here = sum(1 for e in self._electrodes if e["view"] == self._view)
        n_all = len(self._electrodes)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
        p.drawText(QtCore.QRectF(6, h - 34, w - 12, 14),
                   QtCore.Qt.AlignmentFlag.AlignLeft,
                   tr("Eletrodos nesta vista: {}   ·   total: {}").format(
                       n_here, n_all))
        # legenda de qualidade (barra)
        lx0 = 6
        p.setFont(QtGui.QFont(FONT_UI, 7))
        p.drawText(QtCore.QRectF(lx0, h - 18, 54, 14),
                   QtCore.Qt.AlignmentFlag.AlignLeft, tr("Qualidade:"))
        # Um valor por FAIXA de _quality_color (<30, 30-49, 50-74, >=75): com
        # 55 e 65 as caixas de "média" e "boa" saiam da mesma cor e o laranja
        # do contato ruim nunca aparecia na legenda.
        seg = [(tr("baixa"), self._quality_color(20)),
               (tr("média"), self._quality_color(40)),
               (tr("boa"), self._quality_color(60)),
               (tr("ótima"), self._quality_color(85))]
        sx = lx0 + 54
        for lbl, col in seg:
            p.setBrush(QtGui.QBrush(col)); p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.drawRect(QtCore.QRectF(sx, h - 16, 11, 9))
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
            p.drawText(int(sx + 13), int(h - 8), lbl)
            sx += 13 + p.fontMetrics().horizontalAdvance(lbl) + 8

    def _paint_electrodes(self, p, w, h, para_tela=None):
        """Desenha os marcadores da vista atual: halo de seleção, anel de
        qualidade, disco colorido, número e rótulo lateral.

        O anel fica pontilhado e fino quando o canal não tem leitura ao vivo. A
        cor do disco vem de CHANNEL_COLORS pelo índice do canal, com o accent
        como reserva. O rótulo troca de lado na metade direita do widget e é
        preso dentro dos limites.
        """
        fm_num = QtGui.QFontMetrics(QtGui.QFont(FONT_DATA, 9, QtGui.QFont.Weight.Bold))
        lbl_font = QtGui.QFont(FONT_UI, 7, QtGui.QFont.Weight.Bold)
        fm = QtGui.QFontMetrics(lbl_font)
        R = self.HANDLE_R
        # Retângulos de rótulo já ocupados: dois eletrodos próximos escreviam
        # um por cima do outro. Aparecia pouco sem zoom e ficava ilegível com
        # zoom, porque a distância entre os marcadores cresce mas a caixa de
        # texto continua do mesmo tamanho.
        ocupados = []
        for e in self._electrodes:
            if e["view"] != self._view:
                continue
            ex, ey = e["x"] * w, self._by(e["y"], h)
            if para_tela is not None:
                ex, ey = para_tela(ex, ey)
            # Fora do quadro não se desenha. Com zoom numa região, um eletrodo
            # de outra parte do corpo caía fora da área visível e mesmo assim
            # tinha o rótulo empurrado para a borda — dava a impressão de que
            # havia um eletrodo ali, e ainda cortava o texto.
            if not (-R <= ex <= w + R and -R <= ey <= h + R):
                continue
            # Leitura defensiva: um KeyError aqui não vira erro visível, vira
            # widget que para de se desenhar — o pior tipo de falha, porque
            # some sem dizer por quê. O carregador de montagem já preenche o
            # campo; isto cobre qualquer outro caminho que crie o eletrodo.
            ch = e.get("channel", -1)
            pct, qual = None, None
            if ch is not None and ch >= 0 and ch in self._live:
                pct, qual = self._live[ch]
            base = QtGui.QColor(CHANNEL_COLORS[ch]) if (0 <= (ch or -1) < len(CHANNEL_COLORS)) \
                else QtGui.QColor(COLORS["accent"])
            # halo de seleção
            if e["id"] == self._sel:
                p.setBrush(QtGui.QBrush(QtGui.QColor(255, 255, 255, 60)))
                p.setPen(QtCore.Qt.PenStyle.NoPen)
                p.drawEllipse(QtCore.QPointF(ex, ey), R + 7, R + 7)
            # anel de qualidade
            qcol = self._quality_color(qual)
            p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
            p.setPen(QtGui.QPen(qcol, 3.2 if qual is not None else 1.6,
                                QtCore.Qt.PenStyle.SolidLine if qual is not None
                                else QtCore.Qt.PenStyle.DotLine))
            p.drawEllipse(QtCore.QPointF(ex, ey), R + 2.2, R + 2.2)
            # corpo do marcador
            p.setBrush(QtGui.QBrush(base))
            p.setPen(QtGui.QPen(QtGui.QColor(COLORS["surface"]), 1.5))
            p.drawEllipse(QtCore.QPointF(ex, ey), R, R)
            # número
            p.setPen(QtGui.QPen(QtGui.QColor("#ffffff")))
            p.setFont(QtGui.QFont(FONT_DATA, 9, QtGui.QFont.Weight.Bold))
            num = str(e["id"])
            p.drawText(QtCore.QRectF(ex - R, ey - R, 2 * R, 2 * R),
                       QtCore.Qt.AlignmentFlag.AlignCenter, num)
            # rótulo lateral (nome + músculo/lado + %MVC + Q)
            if self._show_labels:
                parts = [e["name"]]
                # músculo reconhecido pela posição + lado do corpo (E/D): o
                # operador precisa saber se está no bíceps direito ou esquerdo
                mus = e.get("muscle") or ""
                if mus:
                    lado = self.muscle_side(e.get("x", 0.5))
                    parts.append(f"{mus}{(' ' + lado) if lado else ''}")
                if pct is not None:
                    parts.append(f"{pct:.0f}%MVC")
                if qual is not None:
                    parts.append(f"Q{qual:.0f}")
                txt = "  ".join(parts)
                side = -1 if ex > w * 0.5 else 1
                tw = fm.horizontalAdvance(txt) + 10
                lx = ex + side * (R + 6)
                bx = lx if side > 0 else lx - tw
                bx = max(2.0, min(bx, w - tw - 2.0))
                by = max(2.0, min(ey - 8, h - 18))
                # Desvia de rótulo já escrito, descendo de linha em linha. Se
                # não couber em lugar nenhum, desiste da caixa em vez de
                # empilhar texto ilegível.
                alvo = QtCore.QRectF(bx, by, tw, 15)
                for _ in range(6):
                    if not any(alvo.intersects(o) for o in ocupados):
                        break
                    by += 17.0
                    if by > h - 18:
                        by = max(2.0, min(ey - 8, h - 18)) - 17.0
                    alvo = QtCore.QRectF(bx, by, tw, 15)
                else:
                    continue
                ocupados.append(alvo)
                p.setFont(lbl_font)
                p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
                p.setPen(QtGui.QPen(qcol, 1.2))
                p.drawRoundedRect(QtCore.QRectF(bx, by, tw, 15), 3, 3)
                p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"])))
                p.drawText(QtCore.QRectF(bx, by, tw, 15),
                           QtCore.Qt.AlignmentFlag.AlignCenter, txt)

    # ---------------- interação ----------------
    def mousePressEvent(self, ev):
        """Trata o clique: em modo de posicionamento cria um eletrodo ali, senão
        seleciona o que está sob o cursor e inicia o arraste.

        Converte o pixel para coordenada normalizada com _fy; o eixo x usa px/w
        direto porque não há padding horizontal.
        """
        w, h = self.width(), self.height()
        px, py = self._pos_logica(ev)
        if ev.button() == QtCore.Qt.MouseButton.RightButton and self._zoom > 1.0:
            self._pan_ini = (ev.position().x(), ev.position().y(),
                             self._foco_n[0], self._foco_n[1])
            return
        if self._place_mode:
            self.add_electrode(px / w, self._fy(py, h))
            return
        eid = self._hit(px, py, w, h)
        self._sel = eid
        self._dragging = eid >= 0
        self.sigElectrodeSelected.emit(eid)
        self.update()

    def mouseMoveEvent(self, ev):
        """Arrasta o eletrodo selecionado e reavalia, a cada movimento, qual
        músculo está sob ele.

        x é limitado a 0.02..0.98 mas y aceita 0..1. sigElectrodesChanged é
        emitido durante o arraste sempre que o músculo reconhecido muda, não
        apenas ao soltar.
        """
        # Arraste com o botão DIREITO desloca a vista ampliada (o equivalente a
        # empurrar o papel debaixo da lupa).
        if self._pan_ini is not None:
            x0, y0, fx0, fy0 = self._pan_ini
            w0, h0 = max(1, self.width()), max(1, self.height())
            z = max(1e-6, self._zoom - 1.0)
            self.set_zoom(self._zoom,
                          (fx0 + (ev.position().x() - x0) / (w0 * z),
                           fy0 + (ev.position().y() - y0) / (h0 * z)))
            return
        if not self._dragging or self._sel < 0:
            return
        w, h = self.width(), self.height()
        e = self._find(self._sel)
        if e is None:
            return
        lx, ly = self._pos_logica(ev)
        e["x"] = max(0.02, min(0.98, lx / w))
        e["y"] = max(0.0, min(1.0, self._fy(ly, h)))
        # O músculo acompanha o arraste: ao levar o eletrodo do bíceps para o
        # tríceps, a leitura passa a ser do tríceps na hora. Antes o rótulo
        # ficava congelado no primeiro músculo e o mapa mentia sobre a região.
        novo = self._nearest_muscle(e["x"], e["y"], e["view"])
        if novo and novo != e.get("muscle"):
            e["muscle"] = novo
            self.sigElectrodesChanged.emit()
        self.update()

    def mouseReleaseEvent(self, ev):
        """Encerra o arraste, confirma o músculo da posição final e avisa a
        interface que o mapa mudou."""
        self._pan_ini = None
        if self._dragging:
            self._dragging = False
            # confirma o músculo da posição final
            e = self._find(self._sel)
            if e is not None:
                m = self._nearest_muscle(e["x"], e["y"], e["view"])
                if m:
                    e["muscle"] = m
            self.sigElectrodesChanged.emit()

    def mouseDoubleClickEvent(self, ev):
        """Duplo-clique sobre um marcador abre o diálogo de renomear o eletrodo."""
        w, h = self.width(), self.height()
        eid = self._hit(*self._pos_logica(ev), w, h)
        if eid < 0:
            return
        e = self._find(eid)
        new, ok = pede_texto(
            self, tr("Renomear eletrodo"), tr("Nome do eletrodo:"),
            QtWidgets.QLineEdit.EchoMode.Normal, e["name"])
        if ok and new.strip():
            self.rename(eid, new.strip())

    def keyPressEvent(self, ev):
        """Delete e Backspace apagam o eletrodo selecionado; as demais teclas
        seguem para o comportamento padrão.

        Só chega aqui com o widget em foco, e a política é ClickFocus: é
        preciso clicar no atlas antes.
        """
        if ev.key() in (QtCore.Qt.Key.Key_Delete, QtCore.Qt.Key.Key_Backspace):
            self.remove_selected()
        else:
            super().keyPressEvent(ev)


# ============================================================
# _VirtualJoystickWidget — visualização do EMG Joystick
# ============================================================
class _VirtualJoystickWidget(QtWidgets.QWidget):
    """Widget que desenha um joystick virtual.

    Estado: x, y em [-1, +1]. Áreas N/S/L/O destacadas quando ativadas.
    """
    def __init__(self, parent=None):
        """Inicializa os eixos zerados, a zona morta padrão e o tamanho mínimo do
        painel."""
        super().__init__(parent)
        self._x = 0.0; self._y = 0.0
        self._dead_zone = 0.15
        self.setMinimumSize(220, 220)

    def set_axes(self, x, y, dead_zone=0.15):
        """Recebe a posição do joystick calculada a partir do EMG e redesenha o
        painel.

        x e y são presos em -1..+1; dead_zone é fração do raio e serve apenas
        para desenhar o círculo de referência.
        """
        self._x = max(-1.0, min(1.0, float(x)))
        self._y = max(-1.0, min(1.0, float(y)))
        self._dead_zone = dead_zone
        self.update()

    def paintEvent(self, event):
        """Desenha o joystick: quadrado de fundo, cruz central, círculo da zona
        morta, setas N/S/L/O acesas e o cursor com as coordenadas numéricas.

        As setas acendem no limiar fixo de 0.3, independente da dead_zone
        mostrada. O eixo Y é invertido na tela (py = cy - y*r) para que valores
        positivos apontem para cima.
        """
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        w = self.width(); h = self.height()
        size = min(w, h)
        cx = w / 2; cy = h / 2
        r = size / 2 - 8
        # Quadrante de fundo
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface_alt"])))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1.5))
        p.drawRect(QtCore.QRectF(cx - r, cy - r, 2 * r, 2 * r))
        # Cruz central
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["border"]), 1,
                            QtCore.Qt.PenStyle.DashLine))
        p.drawLine(QtCore.QPointF(cx - r, cy), QtCore.QPointF(cx + r, cy))
        p.drawLine(QtCore.QPointF(cx, cy - r), QtCore.QPointF(cx, cy + r))
        # Dead zone (círculo)
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["background"])))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"]), 1,
                            QtCore.Qt.PenStyle.DotLine))
        dz_r = r * self._dead_zone
        p.drawEllipse(QtCore.QPointF(cx, cy), dz_r, dz_r)
        # Direções (N/S/L/O) — destacadas se ativas
        # Triângulos Geometric Shapes (sem emoji)
        active_color = QtGui.QColor(SIGNAL_TYPE_COLORS["EMG"])
        inactive_color = QtGui.QColor(COLORS["text_dim"])
        p.setFont(QtGui.QFont(FONT_UI, 12, QtGui.QFont.Weight.Bold))
        # Up (y>0.3)
        c = active_color if self._y > 0.3 else inactive_color
        p.setPen(QtGui.QPen(c))
        p.drawText(int(cx - 6), int(cy - r + 18), "▲")
        # Down
        c = active_color if self._y < -0.3 else inactive_color
        p.setPen(QtGui.QPen(c))
        p.drawText(int(cx - 6), int(cy + r - 4), "▼")
        # Right
        c = active_color if self._x > 0.3 else inactive_color
        p.setPen(QtGui.QPen(c))
        p.drawText(int(cx + r - 16), int(cy + 6), "▶")
        # Left
        c = active_color if self._x < -0.3 else inactive_color
        p.setPen(QtGui.QPen(c))
        p.drawText(int(cx - r + 4), int(cy + 6), "◀")
        # Cursor (posição atual)
        p.setBrush(QtGui.QBrush(QtGui.QColor(SIGNAL_TYPE_COLORS["EMG"])))
        p.setPen(QtGui.QPen(QtGui.QColor("#ffffff"), 1.5))
        px = cx + self._x * r; py = cy - self._y * r
        p.drawEllipse(QtCore.QPointF(px, py), 10, 10)
        # Coordenadas (canto)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text"])))
        p.setFont(QtGui.QFont(FONT_DATA, 9))
        p.drawText(8, h - 6, f"X={self._x:+.2f}  Y={self._y:+.2f}")


# ============================================================
# _CommandPalette — busca global tipo VS Code (Ctrl+Shift+P)
# ============================================================
# Lista comandos + abas + voluntários + sessões. Usuário digita,
# filtro fuzzy, Enter executa.
class _CommandPalette(QtWidgets.QDialog):
    """Diálogo flutuante de busca global de comandos.

    Comandos são uma lista de dicts:
        {"label": "Abrir Conexão", "category": "Aba", "action": callable}
    """
    def __init__(self, commands, parent=None):
        """Monta a paleta: campo de busca, lista de resultados e os atalhos Esc,
        setas e Enter.

        A aparência é definida por stylesheet inline no próprio construtor. A
        lista já nasce preenchida porque _refilter('') é chamado antes de dar
        foco ao campo.
        """
        super().__init__(parent)
        self.setWindowTitle(tr("Pesquisar"))
        self.setWindowFlags(QtCore.Qt.WindowType.Dialog |
                             QtCore.Qt.WindowType.FramelessWindowHint)
        self.setMinimumSize(540, 420)
        self.setStyleSheet(
            f"QDialog {{ background: {COLORS.get('surface', '#222')}; "
            f"border: 2px solid {COLORS.get('accent', '#a6e22e')}; "
            f"border-radius: 6px; }} "
            f"QLineEdit {{ background: {COLORS.get('surface_alt', '#333')}; "
            f"color: {COLORS.get('text', '#fff')}; border: 1px solid "
            f"{COLORS.get('border', '#555')}; padding: 8px; font-size: 13pt; }} "
            f"QListWidget {{ background: {COLORS.get('surface', '#222')}; "
            f"color: {COLORS.get('text', '#fff')}; border: none; "
            f"font-size: 11pt; }} "
            f"QListWidget::item {{ padding: 6px 8px; "
            f"border-bottom: 1px solid {COLORS.get('border', '#444')}; }} "
            f"QListWidget::item:selected {{ "
            f"background: {COLORS.get('accent', '#a6e22e')}; "
            f"color: {COLORS.get('background', '#000')}; }}"
        )
        self._commands = list(commands)
        layout = QtWidgets.QVBoxLayout(self)
        layout.setContentsMargins(8, 8, 8, 8); layout.setSpacing(6)
        self.search_edit = QtWidgets.QLineEdit()
        self.search_edit.setPlaceholderText(tr("Pesquisar abas, voluntários, sessões, comandos..."))
        self.search_edit.textChanged.connect(self._refilter)
        layout.addWidget(self.search_edit)
        self.list_widget = QtWidgets.QListWidget()
        self.list_widget.itemActivated.connect(self._execute_item)
        self.list_widget.itemDoubleClicked.connect(self._execute_item)
        layout.addWidget(self.list_widget, stretch=1)
        # Atalhos de navegação
        QtGui.QShortcut(QtGui.QKeySequence("Esc"), self, activated=self.reject)
        QtGui.QShortcut(QtGui.QKeySequence("Down"), self,
                         activated=lambda: self._move_selection(+1))
        QtGui.QShortcut(QtGui.QKeySequence("Up"), self,
                         activated=lambda: self._move_selection(-1))
        QtGui.QShortcut(QtGui.QKeySequence("Return"), self,
                         activated=self._execute_current)
        self._refilter("")
        self.search_edit.setFocus()

    def _refilter(self, text):
        """Refaz a lista a cada tecla digitada, mantendo só os comandos cujo
        rótulo e categoria contêm todos os termos.

        É um AND de substrings por token, não busca fuzzy. Cada item guarda o
        dict do comando em UserRole e a primeira linha fica selecionada.
        """
        text = text.lower().strip()
        self.list_widget.clear()
        for cmd in self._commands:
            label = cmd.get("label", "")
            category = cmd.get("category", "")
            haystack = f"{label} {category} {tr(category)}".lower()
            if text and not all(tok in haystack for tok in text.split()):
                continue
            it = QtWidgets.QListWidgetItem(f"[{tr(category)}]  {label}")
            it.setData(QtCore.Qt.ItemDataRole.UserRole, cmd)
            self.list_widget.addItem(it)
        if self.list_widget.count():
            self.list_widget.setCurrentRow(0)

    def _move_selection(self, delta):
        """Move a seleção com as setas, dando a volta ao chegar nas pontas da
        lista."""
        cur = self.list_widget.currentRow()
        new = (cur + delta) % max(1, self.list_widget.count())
        self.list_widget.setCurrentRow(new)

    def _execute_current(self):
        """Executa o item destacado, acionado pelo atalho Enter."""
        it = self.list_widget.currentItem()
        if it: self._execute_item(it)

    def _execute_item(self, item):
        """Chama a ação associada ao comando escolhido e fecha a paleta.

        Exceções da ação são engolidas e só aparecem impressas no stdout; o
        diálogo é aceito mesmo quando a ação falha.
        """
        cmd = item.data(QtCore.Qt.ItemDataRole.UserRole)
        if cmd and callable(cmd.get("action")):
            try: cmd["action"]()
            except Exception as exc: print(f"[Palette] erro: {exc}")
        self.accept()


# ============================================================
# _SimulationOverlay — watermark diagonal "DADOS NÃO REAIS"
# ============================================================
# Quando o modo de aquisição é "Simulação" ou "Playback", este overlay é
# mostrado por cima do conteúdo central com uma marca d'água diagonal
# semi-transparente para evitar que demos sejam confundidos com sessões
# clínicas reais.
class _SimulationOverlay(QtWidgets.QWidget):
    """Marca d'água diagonal que cobre a área central quando a aquisição é
    simulação ou playback, evitando confundir demonstração com sessão real.

    Criada pela janela principal como filha do QTabWidget e mantida escondida
    por padrão; o redimensionamento vem de fora, por um eventFilter que replica
    o tamanho das abas.
    """
    def __init__(self, parent=None):
        """Configura os atributos de transparência do overlay e o texto/cor padrão
        da marca d'água.

        WA_TransparentForMouseEvents é o que permite continuar clicando nos
        gráficos por baixo.
        """
        super().__init__(parent)
        # Não captura mouse — passa cliques para os widgets abaixo
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        # Fundo transparente
        self.setAttribute(QtCore.Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self._text = tr("SIMULAÇÃO - DADOS NÃO REAIS")
        self._color = QtGui.QColor(255, 100, 100, 35)  # vermelho semi-transparente

    def set_text(self, text):
        """Troca o texto da marca d'água e força o redesenho."""
        self._text = text
        self.update()

    def set_color(self, color):
        """Troca a cor e o alfa da marca d'água e força o redesenho."""
        self._color = color
        self.update()

    def paintEvent(self, event):
        """Desenha a marca d'água diagonal repetida por cima do conteúdo enquanto
        o app está em Simulação ou Playback.

        O padrão é propositalmente esparso: rotação de -30° e passos de th*6 na
        vertical e tw+220 na horizontal, com alpha baixo vindo de set_color (35
        no padrão), para não competir visualmente com o traçado do sinal. A
        fonte é fixa (Inter 24 pt negrito); em máquinas sem essa fonte o Qt
        substitui e o espaçamento calculado por QFontMetrics muda junto.
        """
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing)
        p.setRenderHint(QtGui.QPainter.RenderHint.TextAntialiasing)
        w = self.width(); h = self.height()
        # Texto repetido em diagonal — padrão discreto (espaçado) para não
        # competir com o sinal. Cor/alpha vêm de set_color (alpha baixo).
        font = QtGui.QFont("Inter", 24, QtGui.QFont.Weight.Bold)
        p.setFont(font)
        p.setPen(QtGui.QPen(self._color))
        # Rotaciona -30° e desenha algumas vezes, bem espaçado
        p.translate(w / 2, h / 2)
        p.rotate(-30)
        fm = QtGui.QFontMetrics(font)
        tw = fm.horizontalAdvance(self._text)
        th = fm.height()
        # Tile o texto num padrão esparso (menos repetições)
        for y in range(-int(h*1.5), int(h*1.5), th * 6):
            for x in range(-int(w*1.5), int(w*1.5), tw + 220):
                p.drawText(x, y, self._text)


# ============================================================
# BluetoothScanThread — varredura BLE async em thread separada
# ============================================================
# Usa bleak (BLE) se disponível. Faz scan de 8s e emite a lista de
# devices encontrados via Qt signal. Não bloqueia a UI principal.
#
# Em Windows, bleak usa as APIs nativas WinRT (sem precisar de drivers extras).
# Para dispositivos BT clássicos (HC-05, módulos seriais), o usuário deve
# parear pelo Windows e a porta COM virtual aparecerá no combo de portas.
# ============================================================
try:
    import bleak as _bleak_module
    HAS_BLEAK = True
except Exception:
    HAS_BLEAK = False


class _BluetoothScanThread(QtCore.QThread):
    """Thread que executa scan BLE async (8 s) e emite devices ao concluir.

    Sinais:
        scan_progress(int seconds_elapsed)
        scan_done(list of dicts {name, address, rssi, type})
        scan_failed(str error_message)
    """
    scan_progress = QtCore.Signal(int)
    scan_done = QtCore.Signal(list)
    scan_failed = QtCore.Signal(str)

    def __init__(self, duration_s=8.0, parent=None):
        """Guarda a duração desejada do scan BLE antes de a thread começar."""
        super().__init__(parent)
        self._duration = duration_s

    def run(self):
        """Corpo da thread: roda a varredura BLE fora do thread da UI e devolve o
        resultado por sinal (scan_done ou scan_failed).

        Cria um event loop asyncio dedicado a esta thread (new_event_loop +
        set_event_loop) porque a thread secundária não herda o loop do
        processo. Sem a lib bleak, emite scan_failed com a instrução de pip e
        retorna. Roda fora do thread da GUI: comunique-se só pelos sinais, não
        mexa em widgets aqui.
        """
        if not HAS_BLEAK:
            self.scan_failed.emit(
                tr("Biblioteca 'bleak' não instalada. "
                "Instale com: pip install bleak")
            )
            return
        import asyncio
        try:
            from bleak import BleakScanner
        except Exception as exc:
            self.scan_failed.emit(tr("Erro ao importar bleak: {0}").format(exc))
            return

        async def _do_scan():
            """Corrotina que faz a descoberta em si e normaliza cada dispositivo
            achado no dict {name, address, rssi, type}.

            Os dois ramos chamam BleakScanner.discover; só muda o formato
            esperado do retorno (dict addr -> (dev, adv) com return_adv=True no
            bleak >= 0.20 versus lista de BLEDevice nas versões antigas). Como
            o ramo de fallback também depende de discover, a checagem hasattr
            não protege contra a ausência do método. Só enxerga BLE: módulos
            Bluetooth clássicos (HC-05 e afins) não aparecem aqui, chegam como
            porta COM virtual.
            """
            devices = []
            try:
                # discover() retorna dict[address, (BLEDevice, AdvertisementData)]
                # em bleak >= 0.20. Para versões antigas, usa scanner manual.
                if hasattr(BleakScanner, "discover"):
                    found = await BleakScanner.discover(
                        timeout=self._duration, return_adv=True)
                    for addr, (dev, adv) in found.items():
                        devices.append({
                            "name":    dev.name or tr("(sem nome)"),
                            "address": dev.address,
                            "rssi":    getattr(adv, "rssi", None),
                            "type":    "BLE",
                        })
                else:
                    found = await BleakScanner.discover(timeout=self._duration)
                    for d in found:
                        devices.append({
                            "name":    d.name or tr("(sem nome)"),
                            "address": d.address,
                            "rssi":    getattr(d, "rssi", None),
                            "type":    "BLE",
                        })
            except Exception as exc:
                raise exc
            return devices

        try:
            # Cria event loop dedicado para esta thread
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            devices = loop.run_until_complete(_do_scan())
            loop.close()
            self.scan_done.emit(devices)
        except Exception as exc:
            self.scan_failed.emit(tr("Falha no scan BLE: {0}").format(exc))


# ============================================================
# LauncherScreen — Tela de boas-vindas / dashboard inicial
# ============================================================
# Aparece ANTES da janela principal e direciona o fluxo de trabalho do
# usuário. Reduz sobrecarga cognitiva: em vez de cair direto em 4 grupos
# × 5+ sub-abas, o usuário escolhe a intenção (Nova Coleta / Analisar /
# BCI / Simulação) + configura hardware básico antes do app abrir.
#
# Retorna um dict de "choice" com:
#   {"mode": "live"|"offline"|"bci"|"sim",
#    "port": "COM3" or None,
#    "expansion_16ch": bool,
#    "acquisition_type": "EEG"|"EMG"|"ECG"|"Hibrido",
#    "volunteer_dir": str or None}
# ============================================================
class _GlifoFluxo(QtWidgets.QWidget):
    """Ícone DESENHADO do card de fluxo de trabalho.

    Antes cada card usava um caractere do bloco Geometric Shapes (▶ ■ ◆ ◯).
    Eles seguiam o tema, mas não diziam nada: um quadrado não sugere "analisar
    dados". Aqui cada glifo mostra o que o fluxo faz — um traçado de biossinal
    com ponto de gravação, um espectro em barras, uma cabeça emitindo ondas, e
    uma senoide sintética dentro de moldura tracejada.

    Desenhado com QPainter (sem arquivo externo, sem emoji), então acompanha a
    cor do tema e fica nítido em qualquer DPI.
    """

    def __init__(self, tipo, cor, parent=None):
        """Cria o glifo do tipo pedido ("live"/"offline"/"bci"/"sim") na cor
        de destaque do card."""
        super().__init__(parent)
        self._tipo = tipo
        self._cor = QtGui.QColor(cor)
        self.setMinimumHeight(52)
        self.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                           QtWidgets.QSizePolicy.Policy.Fixed)

    def set_cor(self, cor):
        """Troca a cor do glifo (usado quando o tema muda)."""
        self._cor = QtGui.QColor(cor)
        self.update()

    def paintEvent(self, _ev):
        """Desenha o glifo centrado, escalado pela altura disponível."""
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        lado = min(self.width(), self.height())
        if lado < 8:
            return
        # trabalha num quadrado 0..100 centrado, para a matemática ficar legível
        p.translate((self.width() - lado) / 2.0, (self.height() - lado) / 2.0)
        p.scale(lado / 100.0, lado / 100.0)
        cor = self._cor
        caneta = QtGui.QPen(cor, 7.0)
        caneta.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
        caneta.setJoinStyle(QtCore.Qt.PenJoinStyle.RoundJoin)

        if self._tipo == "live":
            # traçado de biossinal + ponto de gravação
            p.setPen(caneta)
            cam = QtGui.QPainterPath()
            cam.moveTo(10, 55)
            for x, y in ((26, 55), (33, 30), (42, 76), (51, 44), (58, 62),
                         (66, 55), (90, 55)):
                cam.lineTo(x, y)
            p.drawPath(cam)
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.setBrush(cor)
            p.drawEllipse(QtCore.QPointF(50, 88), 9, 9)

        elif self._tipo == "offline":
            # espectro em barras sobre uma linha de base
            p.setPen(QtCore.Qt.PenStyle.NoPen)
            p.setBrush(cor)
            for i, alt in enumerate((26, 46, 70, 38, 56, 22)):
                x = 12 + i * 13.5
                p.drawRoundedRect(QtCore.QRectF(x, 80 - alt, 9.5, alt), 3, 3)
            eixo = QtGui.QPen(cor, 5.0)
            eixo.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
            p.setPen(eixo)
            p.drawLine(QtCore.QPointF(10, 84), QtCore.QPointF(90, 84))

        elif self._tipo == "bci":
            # cabeça de perfil + ondas saindo dela
            p.setPen(caneta)
            p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
            p.drawEllipse(QtCore.QPointF(40, 50), 25, 27)
            p.drawLine(QtCore.QPointF(40, 23), QtCore.QPointF(40, 30))
            for i, r in enumerate((13, 22, 31)):
                arco = QtGui.QPen(cor, 5.5 - i * 0.7)
                arco.setCapStyle(QtCore.Qt.PenCapStyle.RoundCap)
                p.setPen(arco)
                cx = QtCore.QRectF(70 - r, 50 - r, 2 * r, 2 * r)
                p.drawArc(cx, -55 * 16, 110 * 16)

        else:  # "sim" — senoide sintética dentro de moldura tracejada
            trac = QtGui.QPen(cor, 4.0, QtCore.Qt.PenStyle.DashLine)
            trac.setDashPattern([4, 4])
            p.setPen(trac)
            p.setBrush(QtCore.Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(QtCore.QRectF(10, 20, 80, 60), 8, 8)
            p.setPen(caneta)
            cam = QtGui.QPainterPath()
            cam.moveTo(20, 50)
            for i in range(1, 61):
                x = 20 + i
                cam.lineTo(x, 50 - 20 * math.sin(i / 60.0 * 2 * math.pi * 1.5))
            p.drawPath(cam)
        p.end()


class _WorkflowCard(QtWidgets.QFrame):
    """Card grande clicável para a tela inicial.

    Recebe as cores via parâmetro (tema). Hover é controlado por property
    [hover="true"] aplicada via QSS no nível do diálogo.
    """
    clicked = QtCore.Signal()

    def __init__(self, title, subtitle, icon_text, accent_color,
                 text_color="#1a1a1a", dim_color="#666666", parent=None):
        """Monta o card clicável de fluxo de trabalho com ícone, título e
        subtítulo nas cores recebidas do tema.

        O mínimo de 188x168 px foi escolhido para que dois cards caibam lado a
        lado no painel central mesmo na janela mínima de 1200 px; a partir daí
        eles crescem por size policy. As cores de texto/ícone são aplicadas por
        stylesheet inline em cada QLabel; só o fundo e a borda vêm do QSS do
        diálogo, via objectName workflowCard.
        """
        super().__init__(parent)
        self.setObjectName("workflowCard")
        self.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        # Largura mínima enxuta para que 2 cards caibam no painel central mesmo
        # na janela mínima (1200px); crescem via size policy Expanding.
        self.setMinimumSize(188, 168)
        self.setProperty("hover", False)

        v = QtWidgets.QVBoxLayout(self)
        v.setContentsMargins(18, 16, 18, 16)
        v.setSpacing(8)
        # Os espaçadores nas pontas mantêm ícone+título+subtítulo como um BLOCO
        # centrado. Sem eles o Qt reparte a sobra entre os widgets e o subtítulo
        # desgruda do título, indo parar no rodapé do card.
        v.addStretch(1)
        # Ícone DESENHADO, que mostra o que o fluxo faz (ver _GlifoFluxo).
        # icon_text virou a CHAVE do glifo ("live"/"offline"/"bci"/"sim").
        self.icon_lbl = _GlifoFluxo(icon_text, accent_color)
        self.icon_lbl.setObjectName("cardIcon")
        self.icon_lbl.setMinimumHeight(64)
        v.addWidget(self.icon_lbl)
        # Título
        self.title_lbl = QtWidgets.QLabel(title)
        self.title_lbl.setObjectName("cardTitle")
        self.title_lbl.setStyleSheet(
            f"color: {text_color}; font-size: 13pt; font-weight: bold; "
            f"background: transparent;")
        self.title_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        v.addWidget(self.title_lbl)
        # Subtítulo
        self.sub_lbl = QtWidgets.QLabel(subtitle)
        self.sub_lbl.setObjectName("cardSubtitle")
        self.sub_lbl.setStyleSheet(
            f"color: {dim_color}; font-size: 9pt; background: transparent;")
        self.sub_lbl.setWordWrap(True)
        self.sub_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        v.addWidget(self.sub_lbl)
        v.addStretch(1)

        self._accent = accent_color

    def mousePressEvent(self, ev):
        """Emite o sinal clicked quando o card recebe o botão esquerdo do mouse."""
        if ev.button() == QtCore.Qt.MouseButton.LeftButton:
            self.clicked.emit()
        super().mousePressEvent(ev)

    def enterEvent(self, ev):
        """Liga o estado de hover do card ao passar o mouse.

        O par unpolish/polish é obrigatório: o QSS do diálogo seleciona por
        QFrame#workflowCard[hover="true"] e o Qt só reavalia a regra se o
        estilo for repolido depois de mudar a property.
        """
        self.setProperty("hover", True)
        self.style().unpolish(self); self.style().polish(self)
        super().enterEvent(ev)

    def leaveEvent(self, ev):
        """Desliga o estado de hover do card quando o mouse sai."""
        self.setProperty("hover", False)
        self.style().unpolish(self); self.style().polish(self)
        super().leaveEvent(ev)


class LauncherScreen(QtWidgets.QDialog):
    """Tela inicial. Bloqueia até o usuário fazer uma escolha (ou sair).

    Uso:
        launcher = LauncherScreen(config, volunteers_mgr)
        if launcher.exec() == QtWidgets.QDialog.DialogCode.Accepted:
            choice = launcher.get_choice()
            # ...

    Cores: segue o tema global (COLORS dict) — não tem paleta fixa.
    """

    # Sinal opcional para integrações externas
    launch_requested = QtCore.Signal(dict)

    # Código de retorno do exec() quando o operador pede a tela completa no
    # rodapé da tela simples; o main() reabre o launcher em vez de sair.
    TROCAR_PARA_COMPLETO = 2

    @staticmethod
    def _shift_color(hex_color, delta):
        """Clareia/escurece uma cor hex. delta + clareia, - escurece. [-100..+100]."""
        try:
            c = QtGui.QColor(hex_color)
            h, s, v, a = c.getHsv()
            v = max(0, min(255, v + delta))
            c.setHsv(h, s, v, a)
            return c.name()
        except Exception:
            return hex_color

    @staticmethod
    def _shrink_combo(combo, min_chars=8):
        """Evita que itens de texto longo (porta COM, nome de voluntário)
        forcem a largura do painel lateral — o que espremia o painel central
        e cortava os cards. O combo passa a dimensionar pelo mínimo de
        caracteres e a encolher/elidir; o popup mantém a largura dos itens."""
        try:
            combo.setSizeAdjustPolicy(
                QtWidgets.QComboBox.SizeAdjustPolicy
                .AdjustToMinimumContentsLengthWithIcon)
            combo.setMinimumContentsLength(min_chars)
            combo.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                                QtWidgets.QSizePolicy.Policy.Fixed)
            combo.setMinimumWidth(0)
        except Exception:
            pass

    def _theme(self):
        """Atalho para a paleta do tema atual + cores derivadas."""
        return {
            "bg":         COLORS.get("background",  "#1e1e1e"),
            "panel":      COLORS.get("surface",     "#2d2d2d"),
            "panel_alt":  COLORS.get("surface_alt", "#363636"),
            "border":     COLORS.get("border",      "#404040"),
            "text":       COLORS.get("text",        "#ffffff"),
            "text_dim":   COLORS.get("text_dim",    "#aaaaaa"),
            "accent":     COLORS.get("accent",      "#a6e22e"),
            "accent_dim": COLORS.get("accent_dim",  "#7eb820"),
            "danger":     COLORS.get("error",       "#ee5566"),
            "warning":    COLORS.get("warning",     "#eebb33"),
            # Cores derivadas
            "hover":      self._shift_color(COLORS.get("surface_alt", "#363636"), +10),
            "card_bg":    COLORS.get("surface_alt", "#363636"),
        }

    def __init__(self, config=None, volunteers_mgr=None, parent=None):
        """Prepara o diálogo do launcher: guarda config e gerenciador de
        voluntários, aplica o QSS do tema, monta os três painéis e preenche as
        listas.

        O mínimo de 1200x680 é premissa do layout — abaixo disso a proporção
        3:6:3 com painéis laterais limitados a 340 px deixa de garantir espaço
        para os cards. self.choice fica None até o usuário clicar em algum card
        ou abrir uma sessão; quem chama deve checar isso além do código de
        retorno do exec().
        """
        # o launcher pode ser aberto sem o main() (testes, quem embute o ROA)
        _resolve_fontes()
        super().__init__(parent)
        self.config = config
        self.volunteers = volunteers_mgr
        self.choice = None   # dict preenchido ao clicar em um card
        self._open_settings_request = False  # se o usuário clicou no engrenagem
        # Nível lido uma vez: a tela não é reconstruída in-place (o QSS e os
        # painéis são montados aqui); trocar de nível reabre o launcher.
        self._simples = (getattr(config, "ui_level", "simples") == "simples")
        # Escolhas do diálogo "Trocar" da tela simples (None = usar o salvo).
        # O número de canais vem do config: a escolha da vez anterior valia
        # só até fechar o programa (validação com leigos, G02).
        self._acq_escolhido = None
        self._nch_escolhido = None
        lc = getattr(config, "launcher_channels", None)
        if isinstance(lc, int) and lc in EXPANSION_STEPS and lc != BASE_CHANNELS:
            self._nch_escolhido = lc

        # "Launcher" é inglês de informática; a tela é o Início (K6/G31)
        self.setWindowTitle(tr("{0} — Início").format(APP_NAME))
        if self._simples:
            self.setMinimumSize(760, 540)
            self.resize(760, 540)
        else:
            self.setMinimumSize(1200, 680)
            self.resize(1280, 720)
        # Ícone (se existir) — o roa.ico da marca nova tem prioridade; o
        # cérebro antigo fica de fallback p/ instalações sem o arquivo novo.
        ico_path = _resolve_asset(
            "roa.ico",
            _resolve_asset("app_brain.ico",
                           os.path.join(SCRIPT_DIR, "app_brain.ico")))
        if os.path.exists(ico_path):
            self.setWindowIcon(QtGui.QIcon(ico_path))

        # A tela simples soma o seu acabamento à folha do launcher
        self.setStyleSheet(_escala_fontes_qss(self._build_stylesheet() + (
            self._qss_simples_launcher() if self._simples else "")))
        if self._simples:
            self._build_ui_simples()
        else:
            self._build_ui()
        self._populate_data()

    # ----- Choice API -----
    def get_choice(self):
        """Retorna o dict de escolha (preenchido quando o usuário clica em um card)."""
        return self.choice

    def settings_requested(self):
        """True se o usuário pediu para abrir as Configurações ao invés de um modo."""
        return self._open_settings_request

    # ----- UI -----
    def _build_ui(self):
        """Monta o esqueleto do launcher: corpo com os três painéis lado a lado
        mais o rodapé.

        Os stretches 3:6:3 dão o dobro de espaço ao painel central; é o que
        impede o título e os cards de serem cortados quando os laterais
        crescem.
        """
        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0); root.setSpacing(0)

        # ----- Body: 3 painéis lado a lado -----
        body = QtWidgets.QWidget()
        body.setObjectName("body")
        body_layout = QtWidgets.QHBoxLayout(body)
        body_layout.setContentsMargins(16, 16, 16, 8); body_layout.setSpacing(12)
        # Proporção 3:6:3 — painel central recebe mais espaço para evitar
        # cortar o título "O que você deseja fazer hoje?"
        body_layout.addWidget(self._build_left_panel(),  stretch=3)
        body_layout.addWidget(self._build_center_panel(), stretch=6)
        body_layout.addWidget(self._build_right_panel(), stretch=3)
        root.addWidget(body, stretch=1)

        # ----- Footer -----
        root.addWidget(self._build_footer())

    # ----- Tela simples (coluna única) -----
    def _build_ui_simples(self):
        """Tela inicial do modo simples, em coluna única: exame em uso,
        paciente, duas tarefas e o treino em simulação.

        Porta, Pré-Flight, sessões recentes e os cartões de pesquisa não são
        criados aqui; continuam na tela completa, a um clique no rodapé.
        """
        th = self._theme()
        d = self._dens_tela
        root = QtWidgets.QVBoxLayout(self)
        root.setContentsMargins(0, 0, 0, 0); root.setSpacing(0)
        body = QtWidgets.QWidget()
        body.setObjectName("body")
        v = QtWidgets.QVBoxLayout(body)
        v.setContentsMargins(d(56, 32), d(28, 16), d(56, 32), d(16, 10))
        v.setSpacing(d(20, 12))

        # ---- Logo + exame em uso ----
        topo = QtWidgets.QHBoxLayout(); topo.setSpacing(8)
        topo.addWidget(self._logo_simples())
        topo.addStretch(1)
        # Rótulo + valor em degraus diferentes; cores na folha (_qss_simples_launcher)
        ex_lbl = QtWidgets.QLabel(tr("Exame:"))
        ex_lbl.setObjectName("rotuloExame")
        topo.addWidget(ex_lbl)
        self.exame_lbl = QtWidgets.QLabel("")
        self.exame_lbl.setObjectName("valorExame")
        topo.addWidget(self.exame_lbl)
        self.trocar_btn = QtWidgets.QPushButton(tr("Trocar"))
        self.trocar_btn.setObjectName("smallBtn")
        self.trocar_btn.setMinimumHeight(d(38, 32))
        self.trocar_btn.clicked.connect(self._dialogo_trocar_exame)
        topo.addWidget(self.trocar_btn)
        v.addLayout(topo)
        self._atualiza_rotulo_exame()

        # ---- Paciente ----
        pac = QtWidgets.QHBoxLayout(); pac.setSpacing(8)
        pac_lbl = QtWidgets.QLabel(tr("Paciente:"))
        pac_lbl.setObjectName("rotuloPaciente")
        pac.addWidget(pac_lbl)
        self.volunteer_combo = QtWidgets.QComboBox()
        self.volunteer_combo.setObjectName("volunteerCombo")
        self._shrink_combo(self.volunteer_combo, min_chars=24)
        self.volunteer_combo.setMinimumHeight(d(46, 38))
        pac.addWidget(self.volunteer_combo, stretch=1)
        # "(último usado)" ao lado do paciente que veio do config; some quando
        # a pessoa troca a escolha
        self.ultimo_lbl = QtWidgets.QLabel(tr("(último usado)"))
        self.ultimo_lbl.setObjectName("rotuloUltimo")
        self.ultimo_lbl.setStyleSheet("color: %s; font-size: %dpt;"
                                      % (self._theme()["text_dim"], _pt(10)))
        self.ultimo_lbl.setVisible(False)
        pac.addWidget(self.ultimo_lbl)
        self.volunteer_combo.currentIndexChanged.connect(
            lambda _i: self._marca_ultimo_usado(False))
        self.new_volunteer_btn = QtWidgets.QPushButton(tr("+ Novo"))
        self.new_volunteer_btn.setObjectName("smallBtn")
        self.new_volunteer_btn.setMinimumHeight(d(46, 38))
        self.new_volunteer_btn.clicked.connect(self._on_new_volunteer_clicked)
        pac.addWidget(self.new_volunteer_btn)
        v.addLayout(pac)

        # ---- As duas tarefas ----
        cards = QtWidgets.QHBoxLayout(); cards.setSpacing(d(24, 16))
        self._cards = {}
        # Cartões com teto de altura: esticados até o rodapé diluíam a escolha
        alto_card = _dens(340, 300)
        # "exame", não "sessão": glossário do Simples (validação com leigos)
        for mode, t, s in (
            ("live", tr("Novo exame"),
             tr("Conectar o aparelho, ver o sinal e gravar")),
            ("offline", tr("Abrir uma gravação"),
             tr("Ver de novo, gerar relatório ou salvar figura")),
        ):
            card = _WorkflowCard(t, s, mode, th["accent"],
                                  text_color=th["text"],
                                  dim_color=th["text_dim"])
            card.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                               QtWidgets.QSizePolicy.Policy.Expanding)
            card.setMaximumHeight(alto_card)
            card.setMinimumHeight(min(alto_card, d(260, 200)))
            cl = card.layout()
            cl.setContentsMargins(d(28, 20), d(24, 16), d(28, 20), d(24, 16))
            cl.setSpacing(d(12, 8))
            card.icon_lbl.setMinimumHeight(d(92, 64))
            card.title_lbl.setStyleSheet(
                f"color: {paleta_simples()['texto']}; font-size: {d(16, 14)}pt; "
                f"font-weight: bold; background: transparent;")
            card.sub_lbl.setStyleSheet(
                f"color: {paleta_simples()['texto2']}; font-size: 11pt; "
                f"background: transparent;")
            # "Nova sessão" é a tarefa do dia: borda do acento (ver a folha)
            card.setProperty("principal", mode == "live")
            card.clicked.connect(lambda m=mode: self._on_card_clicked(m))
            cards.addWidget(card, stretch=1)
            self._cards[mode] = card
        # O bloco cartões + treino sobe para o terço de cima do vão
        v.addStretch(1)
        v.addLayout(cards)

        # ---- Treino sem aparelho (discreto, fora dos cartões) ----
        sim_row = QtWidgets.QHBoxLayout()
        sim_row.addStretch(1)
        # "simulação" é palavra do Completo; no Simples é treino
        self.sim_btn = QtWidgets.QPushButton(tr("Treino (sem aparelho)"))
        self.sim_btn.setObjectName("ghostBtn")
        self.sim_btn.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
        self.sim_btn.clicked.connect(
            lambda _=False: self._on_card_clicked("sim"))
        self.sim_btn.setMinimumHeight(d(40, 34))
        sim_row.addWidget(self.sim_btn)
        sim_row.addStretch(1)
        v.addLayout(sim_row)
        v.addStretch(2)
        root.addWidget(body, stretch=1)

        # ---- Rodapé: porta para a tela completa + Sair ----
        foot = QtWidgets.QFrame()
        foot.setObjectName("footer")
        h = QtWidgets.QHBoxLayout(foot)
        h.setContentsMargins(d(56, 32), d(10, 8), d(56, 32), d(14, 10))
        h.setSpacing(8)
        # mesmo nome do menu Ajuda e do seletor Exibição (G29/G30)
        self.modo_completo_btn = QtWidgets.QPushButton(
            tr("Mudar para Completo (pesquisa)"))
        self.modo_completo_btn.setMinimumHeight(d(38, 32))
        self.modo_completo_btn.setObjectName("ghostBtn")
        self.modo_completo_btn.clicked.connect(self._on_modo_completo)
        h.addWidget(self.modo_completo_btn)
        h.addStretch()
        info_lbl = QtWidgets.QLabel(f"© {APP_YEAR} {APP_AUTHORS}")
        info_lbl.setStyleSheet(
            f"color: {th['text_dim']}; font-size: 9pt; background: transparent;")
        h.addWidget(info_lbl)
        h.addStretch()
        self.exit_btn = QtWidgets.QPushButton(tr("Sair"))
        self.exit_btn.setObjectName("dangerBtn")
        self.exit_btn.setMinimumHeight(d(38, 32))
        self.exit_btn.clicked.connect(self.reject)
        h.addWidget(self.exit_btn)
        root.addWidget(foot)

    @staticmethod
    def _dens_tela(alto, baixo):
        """A tela simples abre em 760x540 em qualquer monitor: usa sempre os
        números compactos (com os da tela alta o treino cobria os cartões)."""
        return baixo

    def _qss_simples_launcher(self):
        """Acabamento da tela simples, somado à folha do launcher: cartões com
        borda, "Nova sessão" em destaque e os botões secundários em contorno
        neutro legível ("Sair" deixa de ser vermelho: sair não é problema)."""
        _decide_ui_simples()
        P = paleta_simples()
        d = self._dens_tela
        return f"""
        QFrame#workflowCard {{ background-color: {P['sup']};
            border: 1px solid {P['borda']}; border-radius: 14px; }}
        QFrame#workflowCard[principal="true"] {{
            border: 2px solid {P['acento']}; }}
        QFrame#workflowCard[hover="true"] {{ background-color: {P['tinta']};
            border: 2px solid {P['acento']}; }}
        QLabel#rotuloExame {{ color: {P['texto2']}; font-size: 11pt; }}
        QLabel#valorExame {{ color: {P['texto']}; font-size: {d(14, 12)}pt;
            font-weight: bold; }}
        QLabel#rotuloPaciente {{ color: {P['texto']}; font-size: 11pt;
            font-weight: 600; }}
        QComboBox {{ border: 1px solid {P['borda']}; border-radius: 8px;
            padding: {d(8, 6)}px {d(12, 10)}px; font-size: 11pt; }}
        QPushButton#smallBtn, QPushButton#ghostBtn, QPushButton#dangerBtn {{
            background-color: {P['sup']}; color: {P['texto']};
            border: 1px solid {P['borda']}; border-radius: 8px;
            padding: {d(9, 7)}px {d(16, 12)}px; font-size: 10pt;
            font-weight: 600; }}
        QPushButton#smallBtn:hover, QPushButton#ghostBtn:hover,
        QPushButton#dangerBtn:hover {{ color: {P['acento_txt']};
            border: 1px solid {P['acento']}; background-color: {P['tinta']}; }}
        """

    def _logo_simples(self):
        """Logo da tela simples (menor que a do painel esquerdo); cai no nome
        do programa se o PNG faltar."""
        th = self._theme()
        lbl = QtWidgets.QLabel()
        lbl.setStyleSheet("background: transparent;")
        brand_png = _resolve_asset("roa_logo.png", "")
        pix = QtGui.QPixmap(brand_png) if brand_png else QtGui.QPixmap()
        if not pix.isNull():
            dpr = self.devicePixelRatioF() if hasattr(
                self, "devicePixelRatioF") else 1.0
            pix = pix.scaledToWidth(
                int(150 * dpr),
                QtCore.Qt.TransformationMode.SmoothTransformation)
            pix.setDevicePixelRatio(dpr)
            if _tema_escuro():
                pix = _pixmap_tingido(pix, th["accent"])
            lbl.setPixmap(pix)
        else:
            lbl.setText(APP_NAME)
            lbl.setStyleSheet(
                f"color: {th['accent']}; font-size: 24pt; font-weight: bold; "
                f"background: transparent;")
        return lbl

    def _tipos_de_exame(self):
        """Os 5 tipos de exame (chave, rótulo, dica), na ordem da tela. Fonte
        única dos radios do Pré-Flight e do diálogo "Trocar". No Simples a
        dica diz o que o exame mede, em palavras comuns; a dica com filtro e
        notch é do Completo (validação com leigos, G34)."""
        if getattr(self, "_simples", False):
            return (
                ("EEG", tr("EEG · Cérebro"),
                 tr("Sinal do cérebro, pelos eletrodos na cabeça.")),
                ("EMG", tr("EMG · Músculos"),
                 tr("Sinal dos músculos, pelos eletrodos na pele sobre o músculo.")),
                ("ECG", tr("ECG · Coração"),
                 tr("Sinal do coração, pelos eletrodos no peito ou nos pulsos.")),
                ("EoG", tr("EOG · Olhos"),
                 tr("Piscadas e movimento do olhar, pelos eletrodos perto dos olhos.")),
                ("Hibrido", tr("Multimodal (combinar sinais)"),
                 tr("Mais de um tipo de sinal na mesma gravação: os canais são "
                    "divididos entre cérebro, músculos, coração e olhos.")),
            )
        return (
            ("EEG", tr("EEG · Cérebro"),
             tr("Todos os canais marcados como EEG. Filtro 0.5-70 Hz + notch.")),
            ("EMG", tr("EMG · Músculos"),
             tr("Todos os canais marcados como EMG. Filtro 20-Nyquist + notch.")),
            ("ECG", tr("ECG · Coração"),
             tr("Todos os canais marcados como ECG. Filtro 0.5-100 Hz + notch.")),
            ("EoG", tr("EOG · Olhos"),
             tr("Todos os canais marcados como EoG. Filtro 0.1-30 Hz + notch.")),
            ("Hibrido", tr("Multimodal (combinar sinais)"),
             tr("Mistura: 1-8 EEG / 9-12 EMG / 13-14 ECG / 15-16 EoG.")),
        )

    def _preenche_combo_canais(self, combo):
        """Itens 8..64 do seletor de canais (userData = número inteiro). No
        Simples só o número: "placa base" e "+1 módulo" são do Completo (G34)."""
        simples = getattr(self, "_simples", False)
        for n in EXPANSION_STEPS:
            if simples:
                combo.addItem(tr("{0} canais").format(n), n)
            elif n == BASE_CHANNELS:
                combo.addItem(tr("8 canais (placa base)"), n)
            else:
                mods = (n - BASE_CHANNELS) // BASE_CHANNELS
                combo.addItem(
                    f"{n} " + tr("canais") + f"  (+{mods} " +
                    (tr("módulo") if mods == 1 else tr("módulos")) + ")", n)

    def _exame_atual(self):
        """Tipo de exame em vigor na tela simples: o escolhido em "Trocar" ou,
        sem escolha, o modo salvo na config."""
        acq = self._acq_escolhido or getattr(
            self.config, "acquisition_mode", "EEG")
        validos = [k for k, _l, _t in self._tipos_de_exame()]
        return acq if acq in validos else "EEG"

    def _atualiza_rotulo_exame(self):
        """Reescreve o rótulo ao lado de "Exame:" com a modalidade em vigor."""
        if not hasattr(self, "exame_lbl"):
            return
        atual = self._exame_atual()
        rotulo = next((l for k, l, _t in self._tipos_de_exame() if k == atual),
                      atual)
        n_ch = self._nch_escolhido or BASE_CHANNELS
        # A contagem só aparece quando foge da placa base (Daisy/expansão)
        if n_ch != BASE_CHANNELS:
            rotulo = rotulo + " · " + tr("{0} canais").format(n_ch)
        self.exame_lbl.setText(rotulo)

    def _dialogo_trocar_exame(self):
        """Diálogo pequeno da tela simples: tipo de exame + número de canais.

        O número de canais fica aqui porque a Daisy não é detectada em
        hardware; sem o combo o operador ficaria preso em 8.
        """
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(tr("Tipo de exame e número de canais"))
        v = QtWidgets.QVBoxLayout(dlg)
        v.setContentsMargins(18, 16, 18, 14); v.setSpacing(6)
        atual = self._exame_atual()
        radios = {}
        for key, label, tip in self._tipos_de_exame():
            rb = QtWidgets.QRadioButton(label)
            rb.setObjectName("acqRadio")
            rb.setToolTip(tip)
            rb.setChecked(key == atual)
            v.addWidget(rb)
            radios[key] = rb
        ch_row = QtWidgets.QHBoxLayout(); ch_row.setSpacing(6)
        ch_row.addWidget(QtWidgets.QLabel(tr("Número de canais:")))
        combo = QtWidgets.QComboBox()
        # largura pelo conteúdo: "8 canais" saía "8 canai" (validação com leigos)
        combo.setSizeAdjustPolicy(QtWidgets.QComboBox.SizeAdjustPolicy.AdjustToContents)
        combo.setMinimumContentsLength(12)
        self._preenche_combo_canais(combo)
        idx = combo.findData(self._nch_escolhido or BASE_CHANNELS)
        combo.setCurrentIndex(max(0, idx))
        ch_row.addWidget(combo, stretch=1)
        # Multimodal precisa de mais de um tipo de canal: marcado com 8 canais
        # virava um EEG comum sem aviso (validação com leigos, G11). Sobe para
        # 16 sozinho e diz como os canais ficam divididos; com 8 também há
        # divisão (layout_multimodal).
        nota = QtWidgets.QLabel("")
        nota.setWordWrap(True)
        nota.setVisible(False)
        nota.setStyleSheet("color: %s; font-size: %dpt;"
                           % (self._theme()["text_dim"], _pt(10)))
        rb_multi = radios.get("Hibrido")

        def _nota_multimodal(*_a):
            multi = rb_multi is not None and rb_multi.isChecked()
            nota.setVisible(multi)
            if multi:
                n = combo.currentData()
                n = n if isinstance(n, int) else BASE_CHANNELS
                nota.setText(tr("Multimodal com {0} canais: {1}. Para mudar, "
                                "escolha outro número de canais abaixo.")
                             .format(n, descreve_layout_multimodal(n)))
            # o diálogo já tinha o tamanho de antes da nota: cresce com ela
            dlg.adjustSize()

        def _ao_marcar_multimodal(on):
            n = combo.currentData()
            if on and (n if isinstance(n, int) else BASE_CHANNELS) < 16:
                i16 = combo.findData(16)
                if i16 >= 0:
                    combo.setCurrentIndex(i16)
            _nota_multimodal()

        if rb_multi is not None:
            rb_multi.toggled.connect(_ao_marcar_multimodal)
        combo.currentIndexChanged.connect(_nota_multimodal)
        _nota_multimodal()
        v.addSpacing(8)
        v.addWidget(nota)
        v.addLayout(ch_row)
        # o que é "canal" para quem nunca viu o aparelho
        canal_lbl = QtWidgets.QLabel(tr("Canal = cada eletrodo (uma linha de sinal na "
                                        "tela). 8 canais é o padrão do aparelho."))
        canal_lbl.setWordWrap(True)
        canal_lbl.setStyleSheet("color: %s; font-size: %dpt;"
                                % (self._theme()["text_dim"], _pt(10)))
        v.addWidget(canal_lbl)
        bb = QtWidgets.QDialogButtonBox(
            QtWidgets.QDialogButtonBox.StandardButton.Ok |
            QtWidgets.QDialogButtonBox.StandardButton.Cancel)
        bb.button(QtWidgets.QDialogButtonBox.StandardButton.Ok).setText(tr("OK"))
        bb.button(QtWidgets.QDialogButtonBox.StandardButton.Cancel).setText(
            tr("Cancelar"))
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        v.addSpacing(8)
        v.addWidget(bb)
        # Referências para o teste offscreen mexer no diálogo aberto
        self._dlg_exame_radios = radios
        self._dlg_exame_combo = combo
        self._dlg_exame_nota = nota
        aceito = dlg.exec() == QtWidgets.QDialog.DialogCode.Accepted
        # não segura widgets de um diálogo já fechado
        self._dlg_exame_radios = self._dlg_exame_combo = None
        self._dlg_exame_nota = None
        if not aceito:
            return
        self._acq_escolhido = next(
            (k for k, rb in radios.items() if rb.isChecked()), atual)
        val = combo.currentData()
        self._nch_escolhido = val if isinstance(val, int) else BASE_CHANNELS
        print(f"[Launcher] Exame trocado: acq={self._acq_escolhido!r}, "
              f"ch={self._nch_escolhido}")
        # Fica salvo na hora: antes só o botão "Completo" gravava, e quem
        # trocava o exame e clicava Sair reabria em EEG (G02).
        try:
            if self.config is not None:
                self.config.acquisition_mode = self._acq_escolhido
                self.config.launcher_channels = self._nch_escolhido
                self.config.save()
        except Exception as exc:
            print(f"[Launcher] erro salvando o exame escolhido: {exc}")
        self._atualiza_rotulo_exame()

    def _listar_portas(self):
        """Relê as portas seriais do pyserial; sem pyserial devolve lista
        vazia (mesma tolerância de _refresh_ports)."""
        try:
            import serial.tools.list_ports as _lp
            return list(_lp.comports())
        except Exception:
            return []

    def _porta_automatica(self):
        """Resolve a porta do aparelho sem mostrar combo ao leigo.

        Devolve (porta, modo): 1 porta -> usa; 2+ -> pergunta qual; 0 ->
        oferece tentar de novo ou treinar em simulação. (None, None) quando o
        operador desiste.
        """
        while True:
            ports = self._listar_portas()
            if len(ports) == 1:
                return ports[0].device, "live"
            if len(ports) >= 2:
                return self._dialogo_qual_porta(ports)
            box = self._caixa_sem_aparelho()
            box.exec()
            clicado = box.clickedButton()
            if clicado == box._b_de_novo:
                continue
            if clicado == box._b_sim:
                return None, "sim"
            return None, None

    def _caixa_sem_aparelho(self):
        """Caixa "Nenhum aparelho encontrado" em palavras comuns, com o que
        fazer passo a passo; "Tentar de novo" é o único botão cheio, os outros
        são de contorno e Cancelar é a recusa (X e Esc). Antes eram três
        botões azuis iguais e "placa"/"dongle" (validação com leigos, G33)."""
        box = QtWidgets.QMessageBox(self)
        box.setIcon(QtWidgets.QMessageBox.Icon.Warning)
        box.setWindowTitle(tr("Novo exame"))
        box.setText(tr("Nenhum aparelho encontrado."))
        box.setInformativeText(tr(
            "O que fazer:\n"
            "1. Ligue o aparelho e veja se a luz dele acende.\n"
            "2. Encaixe o cabo USB (ou o receptor sem fio) no computador.\n"
            "3. Espere uns 5 segundos e clique em Tentar de novo.\n\n"
            "Sem o aparelho, você pode praticar com um sinal de exemplo "
            "(Treino)."))
        box._b_de_novo = box.addButton(
            tr("Tentar de novo"), QtWidgets.QMessageBox.ButtonRole.AcceptRole)
        box._b_sim = box.addButton(
            tr("Treino (sem aparelho)"), QtWidgets.QMessageBox.ButtonRole.ActionRole)
        # Sem um botão de recusa o X da caixa fica morto
        box._b_cancel = box.addButton(
            tr("Cancelar"), QtWidgets.QMessageBox.ButtonRole.RejectRole)
        # "ghostBtn" é o contorno da folha da tela inicial (a caixa herda);
        # o botão já foi polido pelo addButton, então o nome novo só vale
        # depois de repolir
        for b in (box._b_sim, box._b_cancel):
            b.setObjectName("ghostBtn")
            b.style().unpolish(b)
            b.style().polish(b)
        box.setDefaultButton(box._b_de_novo)
        box.setEscapeButton(box._b_cancel)
        return box

    def _dialogo_qual_porta(self, ports):
        """Com 2+ portas, pergunta qual é o aparelho já sugerindo o adaptador
        USB-serial (FTDI do dongle, CP210x, CH340); porta Bluetooth virtual
        abre mas fica muda."""
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(tr("Qual porta é o aparelho?"))
        dlg.setMinimumWidth(460)
        v = QtWidgets.QVBoxLayout(dlg)
        v.setContentsMargins(18, 16, 18, 14); v.setSpacing(8)
        v.addWidget(QtWidgets.QLabel(tr("Qual porta é o aparelho?")))
        lista = QtWidgets.QListWidget()
        sugerida = -1
        for i, p in enumerate(ports):
            desc = str(getattr(p, "description", "") or "")
            it = QtWidgets.QListWidgetItem(f"{p.device} — {desc}")
            it.setData(QtCore.Qt.ItemDataRole.UserRole, p.device)
            lista.addItem(it)
            if sugerida < 0 and any(
                    m in desc.upper()
                    for m in ("FTDI", "USB SERIAL", "CP210", "CH340")):
                sugerida = i
        lista.setCurrentRow(max(0, sugerida))
        lista.itemDoubleClicked.connect(lambda _it: dlg.accept())
        v.addWidget(lista, stretch=1)
        bb = QtWidgets.QDialogButtonBox(
            QtWidgets.QDialogButtonBox.StandardButton.Ok |
            QtWidgets.QDialogButtonBox.StandardButton.Cancel)
        bb.button(QtWidgets.QDialogButtonBox.StandardButton.Ok).setText(tr("OK"))
        bb.button(QtWidgets.QDialogButtonBox.StandardButton.Cancel).setText(
            tr("Cancelar"))
        bb.accepted.connect(dlg.accept)
        bb.rejected.connect(dlg.reject)
        v.addWidget(bb)
        self._dlg_porta_lista = lista
        aceito = dlg.exec() == QtWidgets.QDialog.DialogCode.Accepted
        self._dlg_porta_lista = None   # não segura widget de diálogo fechado
        if not aceito:
            return None, None
        it = lista.currentItem()
        if it is None:
            return None, None
        return it.data(QtCore.Qt.ItemDataRole.UserRole), "live"

    def _on_modo_completo(self):
        """Rodapé da tela simples: grava o nível avançado e fecha com o código
        próprio; o main() reabre o launcher de 3 painéis."""
        print("[Launcher] Botão clicado: Modo completo (pesquisa)")
        try:
            if self.config is not None:
                self.config.ui_level = "avancado"
                # O exame trocado aqui vale também na tela completa
                if self._acq_escolhido:
                    self.config.acquisition_mode = self._acq_escolhido
                self.config.save()
        except Exception as exc:
            print(f"[Launcher] erro salvando nível avançado: {exc}")
        self.done(self.TROCAR_PARA_COMPLETO)

    # ----- Painel esquerdo -----
    def _build_left_panel(self):
        """Constrói o painel esquerdo, que reúne a identidade do app, o voluntário
        ativo e as sessões recentes.

        A largura é travada em 340 px para não roubar espaço do painel central.
        O duplo clique na lista de recentes é o atalho que abre a sessão direto
        em modo offline.
        """
        th = self._theme()
        panel = QtWidgets.QFrame()
        panel.setObjectName("sidePanel")
        # Largura limitada: impede que os painéis laterais "comam" o painel
        # central (o que cortava os cards de Analisar Dados / Modo Simulação).
        panel.setMaximumWidth(340)
        v = QtWidgets.QVBoxLayout(panel)
        v.setContentsMargins(16, 16, 16, 16); v.setSpacing(10)

        # Logo no topo
        logo_box = QtWidgets.QFrame()
        logo_box.setObjectName("logoBox")
        lb = QtWidgets.QVBoxLayout(logo_box)
        lb.setContentsMargins(12, 12, 12, 12)
        lb.setSpacing(4)
        # Marca: a LOGO de verdade. Só cai no texto se o PNG faltar (instalação
        # incompleta ou hot-update que trouxe só o .py).
        brand_png = _resolve_asset("roa_logo.png", "")
        brand_lbl = QtWidgets.QLabel()
        brand_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        brand_lbl.setStyleSheet("background: transparent;")
        pix = QtGui.QPixmap(brand_png) if brand_png else QtGui.QPixmap()
        if not pix.isNull():
            # devicePixelRatio mantém a logo nítida em tela HiDPI
            dpr = self.devicePixelRatioF() if hasattr(
                self, "devicePixelRatioF") else 1.0
            alvo = int(232 * dpr)
            pix = pix.scaledToWidth(
                alvo, QtCore.Qt.TransformationMode.SmoothTransformation)
            pix.setDevicePixelRatio(dpr)
            if _tema_escuro():
                pix = _pixmap_tingido(pix, th["accent"])
            brand_lbl.setPixmap(pix)
            lb.addWidget(brand_lbl)
        else:
            brand_lbl.setText(APP_NAME)
            brand_lbl.setStyleSheet(
                f"color: {th['accent']}; font-size: 30pt; font-weight: bold; "
                f"background: transparent;")
            lb.addWidget(brand_lbl)
            sub = QtWidgets.QLabel(APP_FULLNAME)
            sub.setStyleSheet(
                f"color: {th['accent']}; font-size: 9pt; background: transparent;")
            sub.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            lb.addWidget(sub)
        sub_lbl = QtWidgets.QLabel(f"{tr(APP_EDITION)} · v{APP_VERSION}")
        sub_lbl.setStyleSheet(
            f"color: {th['text_dim']}; font-size: 9pt; background: transparent;")
        sub_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        lb.addWidget(sub_lbl)
        v.addWidget(logo_box)

        # ---- Voluntário ativo ----
        v.addWidget(self._section_label(tr("Voluntário Ativo")))
        vol_row = QtWidgets.QHBoxLayout()
        vol_row.setSpacing(6)
        self.volunteer_combo = QtWidgets.QComboBox()
        self.volunteer_combo.setObjectName("volunteerCombo")
        self._shrink_combo(self.volunteer_combo)
        vol_row.addWidget(self.volunteer_combo, stretch=1)
        self.new_volunteer_btn = QtWidgets.QPushButton(tr("+ Novo"))
        self.new_volunteer_btn.setObjectName("smallBtn")
        self.new_volunteer_btn.setMaximumWidth(90)
        self.new_volunteer_btn.clicked.connect(self._on_new_volunteer_clicked)
        vol_row.addWidget(self.new_volunteer_btn)
        v.addLayout(vol_row)

        # ---- Sessões recentes ----
        v.addWidget(self._section_label(tr("Sessões Recentes")))
        self.recent_list = QtWidgets.QListWidget()
        self.recent_list.setObjectName("recentList")
        self.recent_list.itemDoubleClicked.connect(self._on_recent_session_open)
        v.addWidget(self.recent_list, stretch=1)
        # Botão para abrir CSV manualmente
        open_csv_btn = QtWidgets.QPushButton(tr("Abrir CSV manualmente..."))
        open_csv_btn.setObjectName("ghostBtn")
        open_csv_btn.clicked.connect(self._on_open_csv_manual)
        v.addWidget(open_csv_btn)

        return panel

    # ----- Painel central -----
    def _build_center_panel(self):
        """Constrói o painel central com o grid 2x2 dos quatro fluxos de trabalho
        (live, offline, bci, sim).

        Cada card é conectado com lambda m=mode para fixar o modo no momento da
        criação (sem isso todos capturariam a última iteração). Os cards ficam
        guardados em self._cards indexados pelo modo. Os ícones são caracteres
        Unicode do bloco Geometric Shapes, não emojis, para seguir a cor do
        tema.
        """
        th = self._theme()
        panel = QtWidgets.QFrame()
        panel.setObjectName("centerPanel")
        v = QtWidgets.QVBoxLayout(panel)
        # Margens reduzidas + sem stretches estranhos para não comprimir os cards
        v.setContentsMargins(20, 24, 20, 20); v.setSpacing(10)

        # Título grande — auto-shrink se a janela for menor que o ideal.
        # Diminuímos a fonte e usamos word-wrap para evitar corte.
        title = QtWidgets.QLabel(tr("O que você deseja fazer hoje?"))
        title.setObjectName("centerTitle")
        title.setStyleSheet(
            f"color: {th['text']}; font-size: 18pt; font-weight: bold; "
            f"background: transparent; letter-spacing: 0.5px; padding: 0;")
        title.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        title.setWordWrap(True)
        v.addWidget(title)

        subtitle = QtWidgets.QLabel(tr("Escolha um fluxo de trabalho para começar"))
        subtitle.setStyleSheet(
            f"color: {th['text_dim']}; font-size: 11pt; "
            f"background: transparent; padding-bottom: 6px;")
        subtitle.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        subtitle.setWordWrap(True)
        v.addWidget(subtitle)

        # Grid 2x2 de cards. Cada card EXPANDE para preencher sua coluna e o
        # bloco é limitado em largura + centralizado por espaçadores laterais —
        # assim os cards NUNCA estouram o painel central (o que cortava o
        # subtítulo de "Analisar Dados" e "Modo Simulação" na coluna direita).
        cards_wrapper = QtWidgets.QWidget()
        cards = QtWidgets.QGridLayout(cards_wrapper)
        cards.setHorizontalSpacing(16); cards.setVerticalSpacing(16)
        cards.setContentsMargins(0, 0, 0, 0)

        # Os 4 fluxos. (mode, título, subtítulo, ícone-texto, cor de destaque)
        # Ícones: caracteres tipográficos Unicode (Geometric Shapes block) —
        # SEM emojis. Renderizados como texto puro pelo Qt.
        # A 4ª coluna é a CHAVE do glifo desenhado, não mais um caractere solto:
        # traçado com ponto de gravação, espectro em barras, cabeça emitindo
        # ondas e senoide sintética em moldura tracejada.
        flows = [
            ("live",    tr("Nova Coleta"),
             tr("Conectar ao hardware e gravar uma sessão em tempo real"),
             "live", th["accent"]),
            ("offline", tr("Analisar Dados"),
             tr("Abrir um CSV e explorar análises offline (FFT, ERP, ERS/ERD)"),
             "offline", th["accent"]),
            ("bci",     tr("Aplicações BCI"),
             tr("Biofeedback interativo: Focus, EMG Joystick, SSVEP"),
             "bci", th["warning"]),
            ("sim",     tr("Modo Simulação"),
             tr("Gerar dados sintéticos para testar a interface sem hardware"),
             "sim", th["text_dim"]),
        ]
        self._cards = {}
        for i, (mode, t, s, ic, col) in enumerate(flows):
            r, c = i // 2, i % 2
            card = _WorkflowCard(t, s, ic, col,
                                  text_color=th["text"],
                                  dim_color=th["text_dim"])
            card.setSizePolicy(QtWidgets.QSizePolicy.Policy.Expanding,
                               QtWidgets.QSizePolicy.Policy.Expanding)
            card.clicked.connect(lambda m=mode: self._on_card_clicked(m))
            cards.addWidget(card, r, c)
            self._cards[mode] = card
        # Faz as 2 colunas e linhas terem o mesmo stretch (cards iguais)
        cards.setColumnStretch(0, 1); cards.setColumnStretch(1, 1)
        cards.setRowStretch(0, 1); cards.setRowStretch(1, 1)
        # O bloco preenche a largura do painel central. Como os painéis
        # laterais têm largura máxima limitada, o central sempre recebe espaço
        # suficiente para os 2 cards lado a lado, sem corte — em qualquer
        # tamanho de janela (>= 1200 px). Os cards crescem juntos (Expanding).
        v.addWidget(cards_wrapper, stretch=1)

        return panel

    # ----- Painel direito -----
    def _build_right_panel(self):
        """Constrói o painel direito de Pré-Flight Check: porta serial, número de
        canais e tipo de aquisição.

        O combo de canais percorre EXPANSION_STEPS e guarda o número inteiro de
        canais como userData; ele substituiu o antigo checkbox binário de 16
        canais, mas o dict de escolha ainda exporta expansion_16ch por
        compatibilidade. Nada é aplicado aqui: os valores só são lidos quando o
        usuário clica em um card. No fim, liga os sinais dos combos e radios ao
        _refresh_summary.
        """
        th = self._theme()
        panel = QtWidgets.QFrame()
        panel.setObjectName("sidePanel")
        panel.setMaximumWidth(340)  # idem painel esquerdo (não espremer o centro)
        v = QtWidgets.QVBoxLayout(panel)
        v.setContentsMargins(16, 16, 16, 16); v.setSpacing(10)

        v.addWidget(self._section_label(tr("Pré-Flight Check")))
        hint = QtWidgets.QLabel(tr(
            "Configure o hardware antes de iniciar a coleta. "
            "Estes parâmetros são aplicados ao iniciar."))
        hint.setStyleSheet(
            f"color: {th['text_dim']}; font-size: 9pt; background: transparent;")
        hint.setWordWrap(True)
        v.addWidget(hint)

        # ---- Bloco: Hardware ----
        hw_box = QtWidgets.QFrame()
        hw_box.setObjectName("subPanel")
        hl = QtWidgets.QVBoxLayout(hw_box)
        hl.setContentsMargins(12, 10, 12, 12); hl.setSpacing(8)
        hl.addWidget(self._sub_label(tr("Configuração de Hardware")))
        # Porta COM
        port_row = QtWidgets.QHBoxLayout(); port_row.setSpacing(6)
        port_row.addWidget(QtWidgets.QLabel(tr("Porta:")))
        self.launcher_port_combo = QtWidgets.QComboBox()
        # Não deixar o texto longo da porta (ex.: "COM11 — Serial Padrão por
        # link Bluetooth") forçar a largura do painel: o combo encolhe e elide,
        # abrindo espaço para o painel central (evita corte dos cards).
        self._shrink_combo(self.launcher_port_combo)
        port_row.addWidget(self.launcher_port_combo, stretch=1)
        self.refresh_ports_btn = QtWidgets.QPushButton(tr("Atualizar"))
        self.refresh_ports_btn.setObjectName("smallBtn")
        self.refresh_ports_btn.setMaximumWidth(90)
        self.refresh_ports_btn.setToolTip(tr("Atualizar lista de portas COM"))
        self.refresh_ports_btn.clicked.connect(self._refresh_ports)
        port_row.addWidget(self.refresh_ports_btn)
        hl.addLayout(port_row)
        # Seletor de número de canais (8 -> 64, em passos de 8). Substitui o
        # antigo checkbox binário "16 canais": agora o usuário escolhe a
        # quantidade exata ANTES de entrar no programa.
        ch_row = QtWidgets.QHBoxLayout(); ch_row.setSpacing(6)
        ch_row.addWidget(QtWidgets.QLabel(tr("Número de canais:")))
        self.expansion_combo = QtWidgets.QComboBox()
        self.expansion_combo.setToolTip(tr(
            "Placa base = 8 canais. Cada módulo de expansão adiciona +8 "
            "(até 64). Aplicado ao entrar no programa."))
        self._preenche_combo_canais(self.expansion_combo)
        self.expansion_combo.setCurrentIndex(0)  # default: 8
        self._shrink_combo(self.expansion_combo)
        ch_row.addWidget(self.expansion_combo, stretch=1)
        hl.addLayout(ch_row)
        v.addWidget(hw_box)

        # ---- Bloco: Tipo de Aquisição ----
        type_box = QtWidgets.QFrame()
        type_box.setObjectName("subPanel")
        tl = QtWidgets.QVBoxLayout(type_box)
        tl.setContentsMargins(12, 10, 12, 12); tl.setSpacing(6)
        tl.addWidget(self._sub_label(tr("Tipo de Aquisição")))
        self.acquisition_group = QtWidgets.QButtonGroup(self)
        self.acquisition_group.setExclusive(True)
        self._acq_radios = {}
        for key, label, tip in self._tipos_de_exame():
            rb = QtWidgets.QRadioButton(label)
            rb.setObjectName("acqRadio")
            rb.setToolTip(tip)
            tl.addWidget(rb)
            self.acquisition_group.addButton(rb)
            self._acq_radios[key] = rb
        # Restaura o modo salvo (antes forçava EEG e quem gravava EMG tinha de
        # remarcar a cada abertura); EEG só quando a config traz lixo.
        self._acq_radios.get(
            getattr(self.config, "acquisition_mode", "EEG"),
            self._acq_radios["EEG"]).setChecked(True)
        v.addWidget(type_box)

        # Espaço
        v.addStretch()

        # ---- Status atual (resumo) ----
        self.summary_lbl = QtWidgets.QLabel("")
        self.summary_lbl.setObjectName("summaryLabel")
        self.summary_lbl.setWordWrap(True)
        self.summary_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        v.addWidget(self.summary_lbl)
        self._refresh_summary()
        # Re-renderiza summary ao mudar opções
        self.launcher_port_combo.currentIndexChanged.connect(self._refresh_summary)
        self.expansion_combo.currentIndexChanged.connect(self._refresh_summary)
        for rb in self._acq_radios.values():
            rb.toggled.connect(self._refresh_summary)

        return panel

    def _selected_channels(self):
        """Número de canais escolhido no Pré-Flight (8..64)."""
        if hasattr(self, "expansion_combo"):
            val = self.expansion_combo.currentData()
            if isinstance(val, int):
                return val
        return BASE_CHANNELS

    # ----- Rodapé -----
    def _build_footer(self):
        """Monta o rodapé com o atalho para Configurações, o crédito e o botão
        Sair.

        Sair chama reject() direto, sem confirmação: o código que abre o
        launcher precisa tratar o retorno Rejected como desistência de iniciar
        o app.
        """
        th = self._theme()
        foot = QtWidgets.QFrame()
        foot.setObjectName("footer")
        h = QtWidgets.QHBoxLayout(foot)
        h.setContentsMargins(16, 8, 16, 12); h.setSpacing(8)

        self.settings_btn = QtWidgets.QPushButton(tr("Configurações"))
        self.settings_btn.setObjectName("ghostBtn")
        self.settings_btn.setToolTip(tr("Abrir o aplicativo direto na aba Configurações"))
        self.settings_btn.clicked.connect(self._on_settings_clicked)
        h.addWidget(self.settings_btn)

        h.addStretch()

        info_lbl = QtWidgets.QLabel(f"© {APP_YEAR} {APP_AUTHORS}")
        info_lbl.setStyleSheet(
            f"color: {th['text_dim']}; font-size: 9pt; background: transparent;")
        h.addWidget(info_lbl)

        h.addStretch()

        self.exit_btn = QtWidgets.QPushButton(tr("Sair"))
        self.exit_btn.setObjectName("dangerBtn")
        self.exit_btn.clicked.connect(self.reject)
        h.addWidget(self.exit_btn)

        return foot

    # ----- Helpers de UI -----
    def _section_label(self, text):
        """Fabrica os rótulos de cabeçalho de seção dos painéis laterais.

        Aplica .upper() no texto recebido, então já vem depois do tr() e não
        preserva a caixa original.
        """
        th = self._theme()
        lbl = QtWidgets.QLabel(text.upper())
        lbl.setObjectName("sectionLabel")
        lbl.setStyleSheet(
            f"color: {th['accent']}; font-size: 10pt; font-weight: bold; "
            f"background: transparent; letter-spacing: 1.5px; padding-top: 4px;")
        return lbl

    def _sub_label(self, text):
        """Fabrica os rótulos em negrito usados como título dos sub-painéis do
        Pré-Flight."""
        th = self._theme()
        lbl = QtWidgets.QLabel(text)
        lbl.setStyleSheet(
            f"color: {th['text']}; font-size: 10pt; font-weight: bold; "
            f"background: transparent;")
        return lbl

    # ----- Populadores -----
    def _populate_data(self):
        """Dispara os três preenchimentos dinâmicos do launcher (voluntários,
        sessões recentes e portas) ao final da construção."""
        self._populate_volunteers()
        self._populate_recent_sessions()
        self._refresh_ports()

    def _populate_volunteers(self):
        """Preenche o combo de voluntários a partir do gerenciador de perfis.

        O userData de cada item é o campo _dirname do perfil (nome da pasta),
        que é exatamente o que sai em choice["volunteer_dir"]. Falha ao listar
        só imprime no console e deixa o combo apenas com a opção vazia.
        """
        self.volunteer_combo.clear()
        self.volunteer_combo.addItem(tr("(nenhum — selecione ou cadastre)"), None)
        if self.volunteers is None:
            return
        try:
            vols = self.volunteers.list_volunteers()
        except Exception as exc:
            print(f"[Launcher] erro listando voluntários: {exc}")
            return
        for prof in vols:
            vid = prof.get("vid", "?")
            nome = prof.get("nome", "")
            if nome and getattr(self, "_simples", False):
                # "V01 — Maria" não dizia o que é o V01; no Simples o nome vem
                # primeiro e o código é explicado (G27)
                label = tr("{0} (código {1})").format(nome, vid)
            else:
                label = f"{vid} — {nome}" if nome else vid
            self.volunteer_combo.addItem(label, prof.get("_dirname"))
        # Reaberta pelo "⌂ Início" com um paciente em uso, a tela dizia
        # "(nenhum)" enquanto a janela seguia gravando para ele: o combo
        # nasce no paciente em uso (o registro é o mesmo da janela)
        try:
            cur = self.volunteers.current()
        except Exception:
            cur = None
        if cur and cur.get("_dirname"):
            i = self.volunteer_combo.findData(cur.get("_dirname"))
            if i >= 0:
                self.volunteer_combo.setCurrentIndex(i)
            return
        # programa recém-aberto: o último paciente usado, se a ficha existir
        # (validação com leigos: o exame era lembrado, o paciente não)
        ult = getattr(self.config, "last_volunteer_dir", "") if self.config is not None else ""
        i = self.volunteer_combo.findData(ult) if ult else -1
        if i >= 0:
            self.volunteer_combo.setCurrentIndex(i)
            self._marca_ultimo_usado(True)

    def _marca_ultimo_usado(self, mostrar):
        """Mostra/esconde o "(último usado)" ao lado do combo de pacientes."""
        lbl = getattr(self, "ultimo_lbl", None)
        if lbl is not None:
            lbl.setVisible(bool(mostrar))
            self.volunteer_combo.setToolTip(
                tr("Último paciente usado, já escolhido. Troque se o exame for "
                   "de outra pessoa.") if mostrar else "")

    def _populate_recent_sessions(self):
        """Varre o diretório de sessões procurando data.csv e lista as 30
        gravações mais recentes.

        Procura em dois lugares: subpastas soltas de save_directory e
        volunteers/<VID_Nome>/<sessão>/. Ordena por mtime decrescente. O
        caminho completo do CSV fica no UserRole do item, que é o que
        _on_recent_session_open consome; os itens de placeholder não têm esse
        dado. A varredura é síncrona no thread da UI — em diretórios de rede
        grandes ela trava a abertura do launcher.
        """
        if not hasattr(self, "recent_list"):
            return   # tela simples não tem a lista de recentes
        self.recent_list.clear()
        if self.config is None:
            return
        base = getattr(self.config, "save_directory", None)
        if not base or not os.path.isdir(base):
            self.recent_list.addItem(tr("(diretório de sessões vazio)"))
            return
        # Coleta CSVs em subpastas (até 50)
        found = []
        try:
            # 1) Sessões soltas
            for entry in os.listdir(base):
                full = os.path.join(base, entry)
                if os.path.isdir(full):
                    csv = os.path.join(full, "data.csv")
                    if os.path.isfile(csv):
                        found.append((os.path.getmtime(csv), entry, csv))
            # 2) Sessões dentro de volunteers/<VID_Name>/
            vol_root = os.path.join(base, "volunteers")
            if os.path.isdir(vol_root):
                for vol_dir in os.listdir(vol_root):
                    full_v = os.path.join(vol_root, vol_dir)
                    if os.path.isdir(full_v):
                        for sess in os.listdir(full_v):
                            full_s = os.path.join(full_v, sess)
                            csv = os.path.join(full_s, "data.csv")
                            if os.path.isfile(csv):
                                found.append((os.path.getmtime(csv),
                                              f"{vol_dir} / {sess}", csv))
        except Exception as exc:
            print(f"[Launcher] erro listando sessões: {exc}")
        # Ordena por mtime desc e mostra até 30
        found.sort(reverse=True)
        if not found:
            it = QtWidgets.QListWidgetItem(tr("(nenhuma sessão gravada ainda)"))
            try:
                it.setForeground(QtGui.QColor(self._theme()["text_dim"]))
            except Exception:
                pass
            it.setFlags(QtCore.Qt.ItemFlag.ItemIsEnabled)
            self.recent_list.addItem(it)
            return
        for mtime, name, full_csv in found[:30]:
            import datetime as _dt
            ts = _dt.datetime.fromtimestamp(mtime).strftime("%d/%m %H:%M")
            label = f"  {name}\n  └─ {ts}"
            it = QtWidgets.QListWidgetItem(label)
            it.setData(QtCore.Qt.ItemDataRole.UserRole, full_csv)
            self.recent_list.addItem(it)

    def _refresh_ports(self):
        """Recarrega o combo de portas seriais a partir do pyserial.

        O userData é só o device (ex.: COM3), enquanto o texto exibido
        concatena a descrição. A tentativa de restaurar a seleção usa findText
        do texto anterior completo, então basta a descrição da porta mudar
        entre duas atualizações para a seleção se perder. Ausência do pyserial
        é engolida e cai no item "(nenhuma porta detectada)".
        """
        if not hasattr(self, "launcher_port_combo"):
            return   # tela simples resolve a porta em _porta_automatica
        cur_text = self.launcher_port_combo.currentText() if hasattr(self, "launcher_port_combo") else ""
        self.launcher_port_combo.clear()
        try:
            import serial.tools.list_ports as _lp
            ports = list(_lp.comports())
        except Exception:
            ports = []
        if not ports:
            self.launcher_port_combo.addItem(tr("(nenhuma porta detectada)"), None)
        else:
            for p in ports:
                self.launcher_port_combo.addItem(
                    f"{p.device} — {p.description}", p.device)
        # Tenta restaurar seleção
        idx = self.launcher_port_combo.findText(cur_text)
        if idx >= 0:
            self.launcher_port_combo.setCurrentIndex(idx)

    def _refresh_summary(self):
        # Resumo bonito no canto direito inferior
        """Reescreve a linha de resumo do Pré-Flight com porta, número de canais e
        modo escolhidos.

        É o slot ligado aos sinais dos combos e dos radios, então roda a cada
        mudança de opção. O texto é rich text (HTML) dentro do QLabel e o
        stylesheet do rótulo é reaplicado a cada chamada.
        """
        if not hasattr(self, "summary_lbl"):
            return
        th = self._theme()
        port = self.launcher_port_combo.currentData() if hasattr(self, "launcher_port_combo") else None
        ch = tr("{0} canais").format(self._selected_channels())
        acq = next((k for k, rb in self._acq_radios.items() if rb.isChecked()), "EEG")
        text = (f"<b>{tr('Setup pronto:')}</b><br>"
                f"{tr('Porta:')} <span style='color:{th['accent']}'>{port or '—'}</span> · "
                f"<span style='color:{th['accent']}'>{ch}</span> · "
                f"{tr('Modo:')} <span style='color:{th['accent']}'>{acq}</span>")
        self.summary_lbl.setText(text)
        self.summary_lbl.setStyleSheet(
            f"color: {th['text_dim']}; font-size: 9pt; "
            f"background: {th['panel_alt']}; "
            f"border: 1px solid {th['border']}; "
            f"border-radius: 4px; padding: 8px;")

    # ----- Event handlers -----
    def _on_card_clicked(self, mode):
        """Usuário escolheu um fluxo — fecha o dialog com a escolha."""
        if getattr(self, "_simples", False):
            # Tela simples: exame e canais vêm de "Trocar" (ou do salvo) e a
            # porta é resolvida aqui, antes de a janela abrir.
            port = None
            acq = self._exame_atual()
            n_ch = self._nch_escolhido or BASE_CHANNELS
            if mode == "live":
                port, mode = self._porta_automatica()
                if mode is None:
                    return   # desistiu; continua na tela inicial
        else:
            port = self.launcher_port_combo.currentData() if hasattr(self, "launcher_port_combo") else None
            acq  = next((k for k, rb in self._acq_radios.items() if rb.isChecked()), "EEG")
            n_ch = self._selected_channels()
        vol_dir = self.volunteer_combo.currentData() if hasattr(self, "volunteer_combo") else None
        self.choice = {
            "mode": mode,
            "port": port,
            "num_channels": n_ch,
            "expansion_16ch": (n_ch > BASE_CHANNELS),
            "acquisition_type": acq,
            "volunteer_dir": vol_dir,
            # a pessoa VIU o combo: "(nenhum)" aqui é uma escolha, e a
            # janela solta o paciente em uso (os outros caminhos, sem combo,
            # mandam None sem essa marca e não mexem no paciente)
            "volunteer_escolhido": hasattr(self, "volunteer_combo"),
            "selected_csv": None,
        }
        # Sem backend complexo — apenas imprime para confirmar
        print(f"[Launcher] Card clicado: mode={mode!r}, port={port!r}, "
              f"ch={n_ch}, "
              f"acq={acq!r}, vol_dir={vol_dir!r}")
        self.launch_requested.emit(self.choice)
        self.accept()

    def _on_new_volunteer_clicked(self):
        """Cadastra um paciente só pelo nome (VID automático) e já o deixa
        selecionado no combo. O resto da ficha se completa na aba Voluntários.

        Sem gerenciador de voluntários (falha ao criar o registro temporário
        no main) cai no aviso antigo, que manda cadastrar dentro do programa.
        """
        print("[Launcher] Botão clicado: + Novo (voluntário)")
        if self.volunteers is None:
            QtWidgets.QMessageBox.information(
                self, tr("Cadastrar voluntário"),
                tr("O cadastro completo será aberto após você iniciar um fluxo.\n"
                "Você pode cadastrar na aba <b>Voluntários</b> dentro do aplicativo."))
            return
        # Título e campo com a mesma palavra: "voluntário" no título e
        # "paciente" no campo pareciam dois cadastros (K3/G27)
        titulo = (tr("Cadastrar novo paciente") if self._simples
                  else tr("Cadastrar novo voluntário"))
        nome, ok = pede_texto(
            self, titulo,
            tr("Nome do paciente:") if self._simples else tr("Nome do voluntário:"))
        nome = (nome or "").strip()
        if not ok or not nome:
            return
        try:
            # create_volunteer só recusa pasta repetida (VID + nome); como o
            # VID aqui é sempre novo, o nome repetido precisa ser barrado antes
            if any((p.get("nome") or "").strip().casefold() == nome.casefold()
                   for p in self.volunteers.list_volunteers()):
                raise ValueError(nome)
            prof = self.volunteers.create_volunteer(
                {"vid": self.volunteers.next_vid(), "nome": nome})
        except ValueError:
            QtWidgets.QMessageBox.warning(
                self, titulo,
                tr("Já existe um paciente com esse nome. Escolha-o na lista "
                   "ou use outro nome."))
            return
        except Exception as exc:
            # disco cheio / pasta sem permissão: mostra o motivo do sistema
            QtWidgets.QMessageBox.warning(self, titulo, str(exc))
            return
        print(f"[Launcher] Paciente cadastrado: {prof.get('_dirname')!r}")
        self._populate_volunteers()
        idx = self.volunteer_combo.findData(prof.get("_dirname"))
        if idx >= 0:
            self.volunteer_combo.setCurrentIndex(idx)

    def _on_recent_session_open(self, item):
        """Duplo clique numa sessão recente encerra o launcher em modo offline já
        apontando para o CSV escolhido.

        Ignora o que estiver selecionado nos outros controles: acquisition_type
        sai do modo salvo na config (gravação de EMG reabre em EMG) e
        volunteer_dir em None; só o número de canais é aproveitado.
        """
        csv_path = item.data(QtCore.Qt.ItemDataRole.UserRole)
        if not csv_path: return
        print(f"[Launcher] Sessão recente: {csv_path}")
        n_ch = self._selected_channels()
        self.choice = {
            "mode": "offline",
            "port": None,
            "num_channels": n_ch,
            "expansion_16ch": (n_ch > BASE_CHANNELS),
            "acquisition_type": getattr(self.config, "acquisition_mode", "EEG"),
            "volunteer_dir": None,
            "selected_csv": csv_path,
        }
        self.launch_requested.emit(self.choice)
        self.accept()

    def _on_open_csv_manual(self):
        """Abre um seletor de arquivo para escolher um CSV qualquer e encerra o
        launcher em modo offline com ele.

        Mesma simplificação do caminho de sessões recentes: acquisition_type
        do modo salvo na config e volunteer_dir None. O diálogo começa em
        config.save_directory, caindo na home do usuário se a config não
        existir.
        """
        path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Abrir CSV de sessão"),
            getattr(self.config, "save_directory", os.path.expanduser("~")),
            tr("CSV (*.csv);;Todos (*)"))
        if not path: return
        print(f"[Launcher] CSV manual: {path}")
        n_ch = self._selected_channels()
        self.choice = {
            "mode": "offline",
            "port": None,
            "num_channels": n_ch,
            "expansion_16ch": (n_ch > BASE_CHANNELS),
            "acquisition_type": getattr(self.config, "acquisition_mode", "EEG"),
            "volunteer_dir": None,
            "selected_csv": path,
        }
        self.launch_requested.emit(self.choice)
        self.accept()

    def _on_settings_clicked(self):
        """Encerra o launcher pedindo que o app abra direto na aba de
        Configurações.

        Marca _open_settings_request e emite um choice com mode="settings",
        valor que não é nenhum dos quatro fluxos dos cards — quem consome o
        dict precisa tratar esse caso explicitamente.
        """
        print("[Launcher] Botão clicado: Configurações")
        self._open_settings_request = True
        n_ch = self._selected_channels()
        self.choice = {
            "mode": "settings",
            "port": None,
            "num_channels": n_ch,
            "expansion_16ch": (n_ch > BASE_CHANNELS),
            "acquisition_type": getattr(self.config, "acquisition_mode", "EEG"),
            "volunteer_dir": None,
            "selected_csv": None,
        }
        self.launch_requested.emit(self.choice)
        self.accept()

