    def _ersd_load_csv(self):
        """Abre um CSV do Data acquisition system, confere que é do formato BCI e
        habilita as análises compatíveis com o conteúdo dele.

        Recusa arquivos sem as colunas Event Id/Class Id e arquivos sem nenhuma
        fase extraível. Cada botão tem seu pré-requisito: classificadores
        exigem 2 ou mais classes, lateralidade exige as classes 0 e 1 (mãos) e
        a validação focal exige pelo menos 10 fases pre_rest. Sem o _events.csv
        companheiro os trials são reconstruídos da coluna Event Id, o que só
        gera um aviso no log.
        """
        path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Abrir CSV do Data acquisition system"),
            self.config.save_directory, tr("CSV (*.csv);;Todos (*)"))
        if not path:
            return
        d = self._load_session_csv(path)
        if not d:
            return
        if d.get("format") != "bci_protocol":
            QtWidgets.QMessageBox.warning(self, tr("Formato"),
                tr("Este CSV não parece ser do Data acquisition system "
                "(faltam colunas 'Event Id' / 'Class Id'). "
                "Para análise ERD genérica, use a aba Offline."))
            return
        trials = d.get("trials") or []
        if not trials:
            QtWidgets.QMessageBox.warning(self, tr("Sem trials detectados"),
                tr("CSV BCI carregado, mas não foi possível extrair fases nem "
                "do *_events.csv companheiro nem da coluna 'Event Id' (toda "
                "zerada). Sem fases não há como calcular ERD."))
            return
        # Aviso (não bloqueia) se não tem events.csv: trials reconstruídos
        if not d.get("events_csv_path"):
            self._log("Aviso: sem _events.csv companheiro — trials "
                      "reconstruídos a partir da coluna 'Event Id'.")
        self._ersd_data = d
        # Sumário
        n_mi = sum(1 for t in trials if t.get("phase") == "mi")
        n_base = sum(1 for t in trials if t.get("phase") in self.BASELINE_PHASES)
        classes_present = sorted({t.get("class_id") for t in trials
                                   if t.get("phase") == "mi" and t.get("class_id", -1) >= 0})
        cls_str = ", ".join(self.BCI_CLASS_NAMES.get(c, "?") for c in classes_present)
        n_ch = d["eeg"].shape[0]; sr = d["sr"]
        sr_info = self._format_sr_check(d)
        self.ersd_status.setTextFormat(QtCore.Qt.TextFormat.RichText)
        self.ersd_status.setText(
            tr("✓ <b>{0}</b> · {1} canais · {2} trials MI · {3} baselines · classes: "
               "{4}<br>").format(os.path.basename(path), n_ch, n_mi, n_base, cls_str)
            + sr_info
        )
        self.ersd_compute_btn.setEnabled(True)
        if hasattr(self, "ersd_pico_btn"):
            # A detecção do pico individual só faz sentido com montagem que
            # tenha canal sensório-motor: é lá que o mu é medido.
            centrais = self._ersd_canais_centrais()
            self.ersd_pico_btn.setEnabled(bool(centrais))
            if not centrais:
                self.ersd_mu_lbl.setText(tr(
                    "Esta montagem não tem C3/Cz/C4. Sem canal sensório-motor "
                    "não há como procurar o mu nem distingui-lo do alfa "
                    "posterior."))
            else:
                self.ersd_mu_lbl.setText("")
        if hasattr(self, "ersd_classify_btn"):
            self.ersd_classify_btn.setEnabled(len(classes_present) >= 2)
        if hasattr(self, "ersd_ersp_btn"):
            self.ersd_ersp_btn.setEnabled(n_mi > 0)
        if hasattr(self, "ersd_lat_btn"):
            # lateralidade só faz sentido p/ mãos (classes 0 e 1)
            self.ersd_lat_btn.setEnabled(0 in classes_present and 1 in classes_present)
        if hasattr(self, "ersd_valid_btn"):
            # validação exige repouso PRÉ-tentativa (pre_rest) casado com a MI
            n_pre = sum(1 for t in trials if t.get("phase") == "pre_rest")
            self.ersd_valid_btn.setEnabled(n_mi > 0 and n_pre >= 10)

    # Área sensoriomotora ESPERADA por classe de imaginação motora
    # (córtex CONTRALATERAL para as mãos; região central/medial para os pés).
    ERSD_EXPECTED = {
        0: ["C4"],                 # LEFT_HAND  -> hemisfério direito (contralateral)
        1: ["C3"],                 # RIGHT_HAND -> hemisfério esquerdo (contralateral)
        2: ["Cz", "FCz", "CPz"],   # DORSI (pé) -> área do pé (medial/central)
        3: ["Cz", "FCz", "CPz"],   # PLANTAR (pé) -> idem
    }

    def _ersd_expected_indices(self, cls):
        """Índices (na montagem do head plot BCI) dos eletrodos esperados p/ a classe."""
        names = self.ERSD_EXPECTED.get(cls, [])
        return [i for i, n in enumerate(self.BCI_EEG_CHANNELS) if n in names]

    def _ersd_on_class_changed(self):
        """Destaca a área esperada quando o usuário troca a classe (sem recomputar)."""
        if hasattr(self, "ersd_head"):
            self.ersd_head.set_expected_channels(
                self._ersd_expected_indices(self.ersd_class_combo.currentData()))

    def _ersd_banda_mudou(self, texto):
        """Espelha nos campos de Hz a banda escolhida no seletor."""
        faixa = self.ERSD_BANDS.get(texto)
        if not faixa:
            return                       # "Personalizada": os campos mandam
        for sp, v in ((self.ersd_lo_spin, faixa[0]),
                      (self.ersd_hi_spin, faixa[1])):
            sp.blockSignals(True)
            sp.setValue(v)
            sp.blockSignals(False)

    def _ersd_faixa_editada(self, _v=None):
        """Editar os Hz na mão passa o seletor para 'Personalizada'.

        Sem isso o rótulo continuaria dizendo "Mu (8-13 Hz)" enquanto a conta
        usaria outra faixa — o pior tipo de discordância, porque some no
        relatório.
        """
        lo, hi = self.ersd_lo_spin.value(), self.ersd_hi_spin.value()
        for nome, (a, b) in self.ERSD_BANDS.items():
            if abs(a - lo) < 0.05 and abs(b - hi) < 0.05:
                if self.ersd_band_combo.currentText() != nome:
                    self.ersd_band_combo.blockSignals(True)
                    self.ersd_band_combo.setCurrentText(nome)
                    self.ersd_band_combo.blockSignals(False)
                return
        self.ersd_band_combo.blockSignals(True)
        self.ersd_band_combo.setCurrentText(tr("Personalizada"))
        self.ersd_band_combo.blockSignals(False)

    def _ersd_faixa_atual(self):
        """Faixa em Hz que vale agora, sempre lida dos campos numéricos."""
        lo = float(self.ersd_lo_spin.value())
        hi = float(self.ersd_hi_spin.value())
        if hi <= lo:
            hi = lo + 0.5
        return lo, hi

    def _ersd_canais_centrais(self):
        """Índices dos canais sensório-motores da montagem carregada."""
        d = self._ersd_data or {}
        return indices_por_regiao(d.get("ch_names") or [], MU_CANAIS_CENTRAIS)

    def _ersd_detectar_mu(self):
        """Centra a faixa no pico de mu DESTA pessoa, medido no repouso.

        Usa as fases de baseline como janela de busca: é no repouso que o mu
        está presente e forte. Sem baseline marcada, cai para o registro
        inteiro e diz isso.
        """
        d = self._ersd_data
        if not d:
            return
        eeg, sr, nomes = d["eeg"], d["sr"], d["ch_names"]
        canais = self._ersd_canais_centrais()
        if not canais:
            self.ersd_mu_lbl.setText(tr(
                "Não há canal sensório-motor (C3/Cz/C4) nesta montagem — o "
                "pico do mu não pode ser procurado onde ele não é medido."))
            return
        trechos = [(t["start_line"], t["end_line"])
                   for t in (d.get("trials") or [])
                   if t.get("phase") in self.BASELINE_PHASES]
        pico, lo, hi, ok = mu_pico_individual(eeg, sr, canais, trechos=trechos)
        onde = (tr("no repouso") if trechos else tr("no registro inteiro"))
        if not ok:
            self.ersd_mu_lbl.setText(tr(
                "Não achei um pico de mu destacado {} nos canais "
                "sensório-motores. A faixa continua como estava — melhor isso "
                "que centrar a análise num pico que não existe.").format(onde))
            return
        self.ersd_lo_spin.setValue(lo)
        self.ersd_hi_spin.setValue(hi)
        # O pico é da PESSOA: guardar na configuração faz a banda "Mu" das
        # tabelas e dos gráficos usar a mesma faixa que o ERS/ERD acabou de
        # medir, em vez de duas faixas diferentes com o mesmo nome.
        try:
            self.config.mu_band = [float(lo), float(hi)]
            self.config.save()
            aplicar_bandas(self.config)
        except Exception as exc:
            logging.getLogger("eeg").warning("faixa de mu não persistida: %s", exc)
        self.ersd_mu_lbl.setText(tr(
            "Pico individual de mu em <b>{:.1f} Hz</b> ({}, {} canais). Faixa "
            "ajustada para <b>{:.1f}–{:.1f} Hz</b> — e é esta a faixa que a "
            "banda <b>Mu</b> passa a usar nas tabelas.").format(
                pico, onde, len(canais), lo, hi))

    def _ersd_compute(self):
        """Calcula o ERD% por canal para a classe e a banda escolhidas e atualiza
        barras, topografia e curso temporal C3/Cz/C4.

        Cada trial MI é pareado com a fase de baseline que termina mais perto
        ANTES dele; se não houver nenhuma anterior, usa a primeira da lista. A
        topografia recebe |ERD%| porque o head plot só aceita valores não-
        negativos — o sinal se perde no mapa e só sobrevive nas barras (verde =
        ERS positivo, vermelho = ERD).
        """
        if not self._ersd_data:
            return
        d = self._ersd_data
        eeg, sr, names = d["eeg"], d["sr"], d["ch_names"]
        trials = d.get("trials") or []
        cls = self.ersd_class_combo.currentData()
        band_name = self.ersd_band_combo.currentText()
        bl_pref = self.ersd_baseline_combo.currentData()
        # A faixa vem dos CAMPOS, não do nome do preset: é ela que a pessoa
        # ajusta e é ela que o "Detectar mu individual" escreve.
        low, high = self._ersd_faixa_atual()
        # Laplaciano ANTES de qualquer potência: ele muda o sinal, não a conta.
        if getattr(self, "ersd_lap_chk", None) and self.ersd_lap_chk.isChecked():
            eeg = laplaciano_local(eeg, names, MU_CANAIS_CENTRAIS)

        # Filtra MI trials
        mi_trials = [t for t in trials if t.get("phase") == "mi"
                     and (cls < 0 or t.get("class_id") == cls)]
        if not mi_trials:
            QtWidgets.QMessageBox.warning(self, "ERS/ERD",
                tr("Nenhum trial MI dessa classe no events.csv."))
            return

        # Para cada MI trial, encontra a baseline mais próxima ANTES dele
        if bl_pref == "auto":
            bl_phases = self.BASELINE_PHASES
        else:
            bl_phases = (bl_pref,)
        bl_trials = [t for t in trials if t.get("phase") in bl_phases]

        # Para cada MI trial, pega a fase de baseline imediatamente anterior
        # (com end_line < start_line do MI). Se não houver, usa o trial baseline
        # mais próximo (anterior).
        mi_ranges, bl_ranges = [], []
        for mi in mi_trials:
            mi_s, mi_e = mi["start_line"], mi["end_line"]
            best = None
            best_gap = float("inf")
            for b in bl_trials:
                if b["end_line"] <= mi_s:
                    gap = mi_s - b["end_line"]
                    if gap < best_gap:
                        best_gap = gap; best = b
            if best is None and bl_trials:
                best = bl_trials[0]
            if best is None:
                continue
            mi_ranges.append((mi_s, mi_e))
            bl_ranges.append((best["start_line"], best["end_line"]))

        if not mi_ranges:
            QtWidgets.QMessageBox.warning(self, "ERS/ERD",
                tr("Sem pares MI+baseline emparelháveis."))
            return

        # ERD por canal (média entre trials)
        ersd = SignalProcessor.compute_ersd_per_channel(
            eeg, sr, mi_ranges, bl_ranges, low, high)
        n_ch = len(ersd)

        # Atualiza barras
        self.ersd_bars.setOpts(
            x=list(range(n_ch)), height=ersd.tolist(),
            brushes=[pg.mkBrush("#22dd33" if v > 0 else COLORS["error"])
                     for v in ersd])
        self.ersd_bar_plot.getAxis("bottom").setTicks(
            [list(enumerate(names))])

        # Atualiza head plot com o ERD% assinado (escala divergente: o zero
        # fica no meio e o disco mostra o mesmo número da barra ao lado).
        try:
            padded = np.zeros(MAX_CHANNELS)
            padded[:n_ch] = ersd[:MAX_CHANNELS]
            # Os nomes do ARQUIVO, como no gráfico de barras: _topo_pos acha a
            # posição de FP1/T3/T4 pelo canonical_electrode, e o mapa deixa de
            # dizer T7/T8 enquanto as barras dizem T3/T4.
            bci_map = list(names)[:MAX_CHANNELS]
            bci_map = bci_map + [""] * (MAX_CHANNELS - len(bci_map))
            self.ersd_head.set_mapping(bci_map)
            self.ersd_head.set_num_channels(min(n_ch, MAX_CHANNELS))
            self.ersd_head.set_powers(padded.tolist(),
                                       band_name=band_name.split()[0])
            # Destaca a área sensoriomotora ESPERADA da classe selecionada
            self.ersd_head.set_expected_channels(
                self._ersd_expected_indices(self.ersd_class_combo.currentData()))
        except Exception: pass

        # Curso temporal C3/C4/Cz (índices nesses canais)
        # Calcula potência baseline média por canal para normalização
        base_pwr = SignalProcessor.compute_ersd_baseline_density(
            eeg, sr, bl_ranges, low, high)
        t_axis, ersd_t = SignalProcessor.compute_ersd_timecourse(
            eeg, sr, mi_ranges, base_pwr, low, high)
        # Plota C3, C4, Cz se presentes
        def _ch_idx(label):
            """Acha a posição de um eletrodo pelo nome na montagem carregada,
            devolvendo -1 quando ele não existe."""
            try: return names.index(label)
            except ValueError: return -1
        i_c3 = _ch_idx("C3"); i_c4 = _ch_idx("C4"); i_cz = _ch_idx("Cz")
        if i_c3 >= 0 and t_axis.size:
            self.ersd_c3_curve.setData(t_axis, ersd_t[i_c3])
        else:
            self.ersd_c3_curve.setData([], [])
        if i_c4 >= 0 and t_axis.size:
            self.ersd_c4_curve.setData(t_axis, ersd_t[i_c4])
        else:
            self.ersd_c4_curve.setData([], [])
        if i_cz >= 0 and t_axis.size:
            self.ersd_cz_curve.setData(t_axis, ersd_t[i_cz])
        else:
            self.ersd_cz_curve.setData([], [])

        # Sumário
        cls_name = (self.BCI_CLASS_NAMES.get(cls, tr("Todas")) if cls >= 0 else tr("Todas"))
        most_neg = int(np.argmin(ersd[:n_ch]))
        self.ersd_info_label.setText(
            tr("N trials: {0} | Classe: {1} | Banda: {2} ({3:.1f}–{4:.1f} Hz)  | Maior "
               "ERD: {5} ({6:+.1f}%) | Mediana: {7:+.1f}%").format(len(mi_ranges), cls_name, band_name, low, high, names[most_neg], ersd[most_neg], float(np.median(ersd[:n_ch])))
        )
        # É MU MESMO? Esta é a parte que frequência nenhuma responde. Um ERD
        # forte em 8–13 Hz pode ser alfa occipital vazando — sobretudo se o
        # voluntário fechou os olhos durante a tarefa. Quem separa é a
        # topografia da REAÇÃO: mu cai mais em C3/Cz/C4 que em O1/O2/P3/P4.
        if getattr(self, "ersd_mu_lbl", None) is not None:
            vere, c_med, p_med, texto = mu_ou_alfa_posterior(ersd[:n_ch], names)
            cor = {"mu": COLORS.get("accent", "#1a23e0"),
                   "alfa posterior": COLORS.get("error", "#c0392b"),
                   "misto": COLORS.get("warning", "#e0a030")}.get(
                       vere, COLORS.get("text_dim", "#777"))
            if vere == "indeterminado":
                self.ersd_mu_lbl.setText(
                    f"<span style='color:{cor}'>{_html_escape(texto)}</span>")
            else:
                self.ersd_mu_lbl.setText(
                    f"<b style='color:{cor}'>{tr('Origem do ERD')}: "
                    f"{_html_escape(vere)}</b> — {_html_escape(texto)}  ·  "
                    + tr("central {:+.1f}% · posterior {:+.1f}%").format(
                        c_med, p_med)
                    + ("  ·  " + tr("Laplaciano ligado")
                       if self.ersd_lap_chk.isChecked() else ""))
        self._audit_event("ersd_compute",
                          n_trials=len(mi_ranges), classe=cls_name,
                          band=band_name)

    def _ersd_run_classical(self):
        """Demonstração: roda os classificadores CLÁSSICOS de MI (linha de base
        de pesquisa) sobre os trials carregados, com validação cruzada, nível de
        acaso e teste de permutação. É a referência a superar com machine learning."""
        if not self._ersd_data:
            return
        d = self._ersd_data
        eeg, sr, trials = d["eeg"], d["sr"], d.get("trials") or []
        mode = self.ersd_clf_mode.currentData() if hasattr(self, "ersd_clf_mode") else "cxc"
        try:
            if mode == "rxm":
                ep, y, top = mi_extract_rest_mi_epochs(eeg, sr, trials, tmin=0.5)
            else:
                ep, y, top = mi_extract_epochs(eeg, sr, trials, tmin=0.5)
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self, tr("Classificação"), tr("Falha ao extrair épocas: {0}").format(exc))
            return
        if len(ep) < 10 or len(np.unique(y)) != 2:
            QtWidgets.QMessageBox.information(
                self, tr("Classificação clássica"),
                tr("São necessárias 2 classes com trials suficientes (≥5 por classe). "
                "Para 'Repouso × MI', o arquivo precisa ter fases pre_rest."))
            return
        if mode == "rxm":
            cls_names = [tr("Repouso"), tr("Imaginação Motora")]
        else:
            cls_names = [self.BCI_CLASS_NAMES.get(c, str(c)) for c in top]
        n = len(y)
        self.ersd_classify_btn.setEnabled(False)
        self.ersd_classify_btn.setText(tr("Calculando (validação cruzada + permutação)…"))
        QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.CursorShape.WaitCursor)
        QtWidgets.QApplication.processEvents()
        try:
            rows = []
            for key, label in [("bandpower", "Band-power + LDA"),
                               ("csp", "CSP + LDA"),
                               ("riemann", "Riemanniano (tangente) + LDA")]:
                r = mi_cv_accuracy(ep, y, sr, method=key)
                rows.append((label, r))
            # permutação só p/ o CSP (o mais representativo) — 100 permutações
            perm = mi_permutation_p(ep, y, sr, method="csp", n_perm=100)
            ceil95 = mi_chance_ceiling(n)
        finally:
            QtWidgets.QApplication.restoreOverrideCursor()
            self.ersd_classify_btn.setEnabled(True)
            self.ersd_classify_btn.setText(tr("Classificadores clássicos (validação cruzada)…"))

        best = max((r[1][0] for r in rows if r[1]), default=0.0)
        html = [tr("<b>Classificação clássica de Imaginação Motora</b> — {0} × {1}<br><span "
                   "style='color:{2}'>n = {3} trials · validação cruzada estratificada "
                   "5-fold · sinal 8–30 Hz + CAR</span><table cellpadding=5 "
                   "style='margin-top:6px'><tr><th align=left>Modelo "
                   "clássico</th><th>Acurácia (CV)</th></tr>").format(cls_names[0], cls_names[1], COLORS['text_dim'], n)]
        for label, r in rows:
            if r is None:
                html.append(f"<tr><td>{label}</td><td align=center>n/a</td></tr>")
            else:
                acc, sd = r
                # Verde só acima do teto de acaso para ESTE n (68,4% com 20
                # trials, 76% com 10): o 65 fixo pintava de verde uma acurácia
                # que a linha de baixo declarava compatível com o acaso.
                col = (COLORS.get('success', '#2e9e50') if acc >= max(65.0, ceil95) else
                       COLORS.get('warning', '#d9a520') if acc >= ceil95
                       else COLORS.get('error', '#d1495b'))
                html.append(f"<tr><td>{label}</td>"
                            f"<td align=center><b style='color:{col}'>{acc:.1f}% ± {sd:.1f}</b></td></tr>")
        html.append("</table><br>")
        html.append(tr("Nível de <b>acaso</b>: 50% (teto 95% ≈ {0:.1f}% para n={1}).<br>").format(ceil95, n))
        html.append(tr("As cores comparam cada acurácia com esse teto; o teste "
                       "de permutação abaixo vale só para o CSP.<br>"))
        if perm and not np.isnan(perm[1]):
            sig = tr("significativo") if perm[1] < 0.05 else tr("NÃO significativo")
            html.append(tr("<b>Teste de permutação</b> (CSP, 100 perm.): acurácia nula média "
                           "{0:.1f}% · <b>p = {1:.3f}</b> ({2}).<br>").format(perm[2], perm[1], sig))
        html.append(tr("<br><span style='color:{0}'>Esta é a linha de base clássica de BCI. Um "
                       "modelo de <b>machine learning</b> (FBCSP, Riemanniano+MDM, deep) deve "
                       "<b>igualar ou superar</b> estes valores. Validação cruzada evita a "
                       "superestimação da acurácia de treino.</span>").format(COLORS['text_dim']))

        dlg = QtWidgets.QMessageBox(self)
        dlg.setWindowTitle(tr("Classificadores clássicos — validação cruzada"))
        dlg.setTextFormat(QtCore.Qt.TextFormat.RichText)
        dlg.setText("".join(html))
        dlg.setIcon(QtWidgets.QMessageBox.Icon.Information)
        dlg.exec()
        self._log(f"Classificação clássica: melhor CV = {best:.1f}% "
                  f"({cls_names[0]}×{cls_names[1]}, n={n})")
        self._audit_event("ersd_classical_cv", n_trials=n,
                          classes=cls_names, best_acc=round(best, 1),
                          perm_p=(round(perm[1], 4) if perm else None))

    # ---- ERS/ERD: Mapa Tempo×Frequência (ERSP) ----
    def _ersd_baseline_ranges(self, trials):
        """TODOS os trechos de repouso do arquivo (baseline, pre_rest,
        inter_baseline): o mosaico ERSP promedia as janelas de todos."""
        return [(t["start_line"], t["end_line"]) for t in trials
                if t.get("phase") in self.BASELINE_PHASES
                and t["end_line"] > t["start_line"]]

    def _ersd_baseline_range(self, trials):
        """Maior fase de baseline disponível (preferência: 'baseline' de 60 s)."""
        best = None
        for t in trials:
            if t.get("phase") in self.BASELINE_PHASES:
                span = t["end_line"] - t["start_line"]
                if best is None or span > (best["end_line"] - best["start_line"]):
                    best = t
        return (best["start_line"], best["end_line"]) if best else None

    def _ersd_show_ersp(self):
        """Desenha o mosaico tempo×frequência (ERSP em dB contra o repouso) dos
        canais C3/Cz/C4 por classe de imaginação motora.

        Linhas são classes e colunas são canais. Com duas classes acrescenta
        uma terceira linha com a diferença entre elas, em escala ±3 dB (as
        linhas por classe usam ±6 dB). Se nenhuma classe estiver selecionada,
        escolhe as duas mais frequentes no arquivo. O cálculo pode demorar, daí
        o cursor de espera.
        """
        if not self._ersd_data:
            return
        d = self._ersd_data
        eeg, sr, names = d["eeg"], d["sr"], d["ch_names"]
        trials = d.get("trials") or []
        from collections import Counter
        cls = self.ersd_class_combo.currentData()
        base = self._ersd_baseline_ranges(trials) or None
        chans = [c for c in ("C3", "Cz", "C4") if c in names]
        if base is None:
            QtWidgets.QMessageBox.information(
                self, "ERSP", tr("Preciso de uma baseline (repouso) no arquivo.")); return
        if not chans:
            QtWidgets.QMessageBox.information(
                self, "ERSP", tr("Canais C3/Cz/C4 não encontrados na montagem.")); return
        # short label por class_id
        _short = {0: tr("mão E"), 1: tr("mão D"), 2: tr("pé dorsi"), 3: tr("pé plantar")}
        # Linhas a mostrar: 1 classe selecionada, ou as 2 classes + diferença
        mis = [t for t in trials if t.get("phase") == "mi" and t.get("class_id", -1) >= 0]
        if cls >= 0:
            rows_cls = [cls]
        else:
            rows_cls = [c for c, _ in Counter(t["class_id"] for t in mis).most_common(2)]
        if not rows_cls:
            QtWidgets.QMessageBox.information(self, "ERSP", tr("Sem trials MI no arquivo.")); return

        QtWidgets.QApplication.setOverrideCursor(QtCore.Qt.CursorShape.WaitCursor)
        try:
            # ERSP por classe: {class_id: {ch: (FG,tvec,ersp)}}
            per_cls, n_by = {}, {}
            n_base = None
            for c in rows_cls:
                rng = [(t["start_line"], t["end_line"]) for t in mis if t.get("class_id") == c]
                n_by[c] = len(rng)
                per_cls[c] = {}
                for ch in chans:
                    inf_b = {}
                    r = mi_ersp_channel(eeg, sr, rng, base, names.index(ch),
                                        info=inf_b)
                    n_base = inf_b.get("n_base", n_base)
                    if r is not None:
                        per_cls[c][ch] = r
        finally:
            QtWidgets.QApplication.restoreOverrideCursor()
        if not any(per_cls.values()):
            QtWidgets.QMessageBox.information(self, "ERSP", tr("Não foi possível calcular o ERSP.")); return

        cmap = pg.ColorMap([0.0, 0.5, 1.0],
                           [(33, 102, 172), (247, 247, 247), (178, 24, 43)])
        lut = cmap.getLookupTable(0.0, 1.0, 256)
        glw = self.ersd_ersp_glw
        glw.clear()

        def _draw(row, ch_i, ch, FG, tvec, mat, levels, title):
            """Desenha um painel do mosaico ERSP (uma classe em um canal) como
            imagem colorida com a marca do início da MI.

            O setRect converte os índices da matriz para os eixos reais — tempo
            em segundos no x, frequência em Hz no y.
            """
            p = glw.addPlot(row=row, col=ch_i, title=title)
            p.setMouseEnabled(False, False)
            try: p.hideButtons()
            except Exception: pass
            img = pg.ImageItem(); img.setImage(mat, levels=levels)
            img.setLookupTable(lut)
            img.setRect(QtCore.QRectF(float(tvec[0]), float(FG[0]),
                                      float(tvec[-1] - tvec[0]), float(FG[-1] - FG[0])))
            p.addItem(img)
            p.addItem(pg.InfiniteLine(pos=0.0, angle=90,
                      pen=pg.mkPen("#111", style=QtCore.Qt.PenStyle.DashLine)))
            p.setYRange(FG[0], FG[-1]); p.setXRange(tvec[0], tvec[-1])

        rows_cls_all = list(rows_cls) + (["diff"] if len(rows_cls) == 2 else [])
        for ri, c in enumerate(rows_cls_all):
            for ch_i, ch in enumerate(chans):
                if c == "diff":
                    a = per_cls[rows_cls[0]].get(ch); b = per_cls[rows_cls[1]].get(ch)
                    if not a or not b:
                        continue
                    FG, tvec, ea = a; _, _, eb = b
                    _draw(ri, ch_i, ch, FG, tvec, ea - eb, (-3, 3),
                          f"Δ {_short.get(rows_cls[0],'A')}−{_short.get(rows_cls[1],'B')} · {ch}")
                else:
                    if ch not in per_cls[c]:
                        continue
                    FG, tvec, ersp = per_cls[c][ch]
                    _draw(ri, ch_i, ch, FG, tvec, ersp, (-6, 6),
                          f"{_short.get(c, self.BCI_CLASS_NAMES.get(c,'?'))} · {ch}")

        if len(rows_cls) == 2:
            info = (tr("ERSP por classe (dB vs repouso) · {0} ({1}) × {2} ({3}) · última linha = "
                       "<b>diferença</b> (±3 dB): <b style='color:#2b7bba'>azul</b> = 1ª classe "
                       "dessincroniza mais.").format(_short.get(rows_cls[0],'A'), n_by[rows_cls[0]], _short.get(rows_cls[1],'B'), n_by[rows_cls[1]]))
            self.ersd_ersp_glw.setMinimumHeight(560)
        else:
            info = (tr("ERSP (dB vs repouso) · {0} ({1} trials) · <b style='color:#2b7bba'>azul "
                       "= dessincronização (imaginou)</b>").format(_short.get(rows_cls[0], 'classe'), n_by.get(rows_cls[0],0)))
            self.ersd_ersp_glw.setMinimumHeight(240)
        # Poucas janelas de repouso: o ruído da própria referência aparece
        # como faixas horizontais — avisar antes que sejam lidas como efeito.
        if n_base is not None and n_base < 40:
            info += "<br>" + tr(
                "<b style='color:{0}'>Referência curta:</b> só {1} janelas de "
                "repouso de 0,5 s. Faixas horizontais de alguns dB podem ser "
                "ruído da própria referência, não efeito da tarefa.").format(
                    COLORS["warning"], n_base)
        self.ersd_ersp_info.setText(info)
        self._audit_event("ersd_ersp", classes=rows_cls, channels=chans)

    def _ersd_show_lateralization(self):
        """Mostra num diálogo o índice de lateralidade C3/C4 das duas classes de
        mão, com veredito sobre o padrão contralateral.

        Limiares do veredito: acima de 8% é padrão contralateral clássico,
        entre 2% e 8% é lateralização fraca, abaixo disso não há lateralização
        clara. Exige baseline no arquivo mais as classes 0 (mão esquerda) e 1
        (mão direita).
        """
        if not self._ersd_data:
            return
        d = self._ersd_data
        eeg, sr, names = d["eeg"], d["sr"], d["ch_names"]
        trials = d.get("trials") or []
        if "C3" not in names or "C4" not in names:
            QtWidgets.QMessageBox.information(
                self, tr("Lateralidade"), tr("Canais C3/C4 não encontrados.")); return
        base = self._ersd_baseline_range(trials)
        rl = [(t["start_line"], t["end_line"]) for t in trials
              if t.get("phase") == "mi" and t.get("class_id") == 0]   # LEFT_HAND
        rr = [(t["start_line"], t["end_line"]) for t in trials
              if t.get("phase") == "mi" and t.get("class_id") == 1]   # RIGHT_HAND
        if base is None or not rl or not rr:
            QtWidgets.QMessageBox.information(
                self, tr("Lateralidade"), tr("Preciso de baseline + classes mão E (0) e mão D (1).")); return
        res = mi_lateralization(eeg, sr, rl, rr, base, names.index("C3"), names.index("C4"))
        if res is None:
            QtWidgets.QMessageBox.information(self, tr("Lateralidade"), tr("Não foi possível calcular.")); return
        lat = res["lat"]
        if lat > 8:
            verdict = (tr("<b style='color:#2e9e50'>padrão contralateral CLÁSSICO</b> "
                       "(lateralização típica de MI de mãos)"))
        elif lat > 2:
            verdict = tr("<b style='color:#d9a520'>lateralização fraca</b>")
        else:
            verdict = (tr("<b style='color:#c0392b'>SEM lateralização clara</b> "
                       "(engajamento bilateral — o discriminante entre classes é espacial)"))
        html = (
            tr("<b>Índice de lateralidade C3/C4 (banda mu, MI de mãos)</b><br><table "
               "cellpadding=5 style='margin-top:6px'><tr><th></th><th>C3 (hemisf. "
               "E)</th><th>C4 (hemisf. D)</th></tr><tr><td><b>Mão DIREITA</b></td><td "
               "align=center>{0:+.0f}%</td><td "
               "align=center>{1:+.0f}%</td></tr><tr><td><b>Mão ESQUERDA</b></td><td "
               "align=center>{2:+.0f}%</td><td "
               "align=center>{3:+.0f}%</td></tr></table><br><b>Índice de lateralidade = "
               "{4:+.1f}%</b> &nbsp;→&nbsp; {5}.<br><span style='color:{6}'>Positivo = a "
               "mão D dessincroniza mais o C3 (contralateral) e a mão E, o C4. Perto de "
               "zero = engajamento bilateral.</span>").format(res['c3_right'], res['c4_right'], res['c3_left'], res['c4_left'], lat, verdict, COLORS['text_dim']))
        dlg = QtWidgets.QMessageBox(self)
        dlg.setWindowTitle(tr("Índice de lateralidade C3/C4"))
        dlg.setTextFormat(QtCore.Qt.TextFormat.RichText)
        dlg.setText(html); dlg.setIcon(QtWidgets.QMessageBox.Icon.Information)
        dlg.exec()
        self._audit_event("ersd_lateralization", lat=round(lat, 1))

    def _ersd_validate_erd(self):
        """Válida se o ERD é FOCAL (sensório-motor) ou GLOBAL (atenção/estado).

        Existe porque é fácil produzir um 'mapa de ativação' que na verdade é
        diferença de estado: basta usar um baseline distante. Aqui a referência
        é o repouso imediatamente ANTES de cada tentativa e o efeito motor é
        contrastado contra eletrodos de controle."""
        if not self._ersd_data:
            return
        d = self._ersd_data
        trials = d.get("trials") or []
        self.ersd_valid_btn.setEnabled(False)
        self.ersd_valid_btn.setText(tr("Validando (referência pré-tentativa + permutação)…"))
        QtWidgets.QApplication.processEvents()
        try:
            res = mi_validate_focal_erd(d["eeg"], d["sr"], d["ch_names"], trials)
        except Exception as exc:
            res = {"erro": f"{type(exc).__name__}: {exc}"}
        finally:
            self.ersd_valid_btn.setEnabled(True)
            self.ersd_valid_btn.setText(
                tr("⚑ Validar ERD: é focal (motor) ou global (atenção)?…"))
        if res.get("erro"):
            QtWidgets.QMessageBox.information(self, tr("Validar ERD"), res["erro"]); return

        lo, hi = res["banda"]
        if not res["tem_pico"]:
            cor, tit = "#c0392b", tr("SEM ritmo mu resolvível")
        elif res["focal"]:
            cor, tit = "#2e9e50", tr("ERD FOCAL (sensório-motor)")
        else:
            cor, tit = "#d9a520", tr("ERD GLOBAL (não focal)")

        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(tr("Validação do ERD — focal ou global?"))
        dlg.resize(900, 560)
        v = QtWidgets.QVBoxLayout(dlg)
        head = QtWidgets.QLabel(
            tr("<b style='color:{0}; font-size:13pt'>{1}</b><br><span "
               "style='color:{2}'>Pico de mu do sujeito: <b>{3:.1f} Hz</b> (banda "
               "{4:.0f}–{5:.0f} Hz) · {6} tentativas após rejeição de artefato</span>").format(cor, tit, COLORS['text_dim'], res['pico_mu'], lo, hi, res['n_trials']))
        head.setTextFormat(QtCore.Qt.TextFormat.RichText); head.setWordWrap(True)
        v.addWidget(head)

        pw = pg.PlotWidget()
        pw.showGrid(x=True, y=True, alpha=0.2)
        pw.setLabel("left", tr("potência de mu em relação à janela pré-aviso"),
                    units="dB")
        pw.setLabel("bottom", tr("tempo relativo ao início do aviso (s)"))
        pw.addLegend(offset=(10, 10)); pw.setMenuEnabled(False)
        TW = res["TW"]
        cols = ["#d1495b", "#2e9e50", "#2b7bba"]
        for nm, c in zip(res["motor_names"], cols):
            if nm in res["tc"]:
                pw.plot(TW, res["tc"][nm], pen=pg.mkPen(c, width=2), name=nm)
        ctl = [res["tc"][nm] for nm in res["ctrl_names"] if nm in res["tc"]]
        if ctl:
            pw.plot(TW, np.nanmedian(np.array(ctl, float), axis=0),
                    pen=pg.mkPen("#888", width=2, style=QtCore.Qt.PenStyle.DashLine),
                    name=tr("controle (frontal/temporal)"))
        pw.addItem(pg.InfiniteLine(pos=0, angle=90,
                                   pen=pg.mkPen("#444", style=QtCore.Qt.PenStyle.DashLine)))
        pw.addItem(pg.InfiniteLine(pos=0, angle=0, pen=pg.mkPen("#444")))
        v.addWidget(pw, 1)

        p_txt = "n/d" if not np.isfinite(res["p"]) else f"{res['p']:.4f}"
        txt = QtWidgets.QLabel(
            tr("<table cellpadding=4><tr><th>eletrodos "
               "motores</th><th>controle</th><th>contraste</th><th>p "
               "(permutação)</th></tr><tr><td align=center>{0:+.2f} dB</td><td "
               "align=center>{1:+.2f} dB</td><td align=center><b>{2:+.2f} dB</b></td><td "
               "align=center>{3}</td></tr></table><p style='color:{4}'>{5}</p><p "
               "style='color:{4}'><b>Como ler:</b> se a curva cinza (controle) acompanha "
               "as coloridas (motoras), a queda NÃO é do córtex motor — é global. Um ERD "
               "de tarefa real deve CAIR após o aviso e ser MAIS forte em C3/Cz/C4 que "
               "nos eletrodos de controle.</p>").format(res['motor'], res['ctrl'], res['contraste'], p_txt, COLORS['text_dim'], res['veredito']))
        txt.setTextFormat(QtCore.Qt.TextFormat.RichText); txt.setWordWrap(True)
        v.addWidget(txt)
        bb = QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.StandardButton.Close)
        traduz_botao_fechar(bb)
        bb.rejected.connect(dlg.reject); bb.accepted.connect(dlg.accept)
        v.addWidget(bb)
        try: dlg.setStyleSheet(build_stylesheet(COLORS))
        except Exception: pass
        dlg.exec()
        self._audit_event("ersd_validate_erd", focal=bool(res["focal"]),
                          contraste=round(res["contraste"], 3),
                          p=None if not np.isfinite(res["p"]) else round(res["p"], 4),
                          pico_mu=round(res["pico_mu"], 1), tem_pico=bool(res["tem_pico"]))

    # ---- Tab: Conexão ----
    def _ajustar_grid_conexao(self):
        """No Simples as linhas Baud/Modo/Playback do grid ficam ocultas; sem
        isto a altura mínima de 34 px de cada uma vira um vão em branco."""
        grid = getattr(self, "_conn_grid", None)
        if grid is None:
            return
        simples = self._nivel_simples()
        h = 0 if simples else 34
        for r in (1, 2, 3):
            grid.setRowMinimumHeight(r, h)
        # Simples: a coluna do campo estica e "Atualizar" fica no tamanho
        # natural (ocupava um terço da largura). Avançado: como a 1.8.4.
        for col, est in enumerate((0, 1, 0) if simples else (0, 0, 0)):
            grid.setColumnStretch(col, est)
        # e a sobra de altura fica numa linha vazia no fim, não entre a porta
        # e o diretório (vão de ~300 px)
        if simples or grid.rowCount() > 5:     # no Avançado nunca criada
            grid.setRowStretch(5, 1 if simples else 0)
        b = getattr(self, "refresh_btn", None)
        if b is not None:
            pol = QtWidgets.QSizePolicy.Policy
            b.setSizePolicy(pol.Maximum if simples else pol.Minimum, pol.Fixed)
            self._papel_botao(b, "secundaria" if simples else None)

    def _build_connection_tab(self):
        # Helper local: label com altura minima garantida (evita corte vertical
        # quando a tela e pequena e o QGridLayout tenta espremer demais).
        """Monta a aba de Conexão: porta/baud/modo, arquivo de playback, scan
        Bluetooth, expansão de canais, botões conectar/gravar/demo e o log da
        sessão.

        Devolve uma QScrollArea e não o widget de conteúdo — sem ela os grupos
        ficavam cortados verticalmente em telas baixas. O self.expansion_toggle
        é um QCheckBox oculto mantido só para não quebrar handlers antigos que
        esperavam um booleano onde hoje há um combo de 8 a 64 canais.
        """
        def _h_label(text, role="form"):
            """Cria os rótulos do formulário de conexão com altura mínima, para o
            QGridLayout não os espremer até cortar o texto."""
            lbl = QtWidgets.QLabel(text)
            lbl.setMinimumHeight(28)
            if role == "form":
                lbl.setStyleSheet(f"color: {COLORS['text']}; font-weight: bold;")
            return lbl

        # Widget interno (conteudo real) + QScrollArea externa, para que a aba
        # nunca tenha widgets "comidos" verticalmente em telas pequenas.
        inner = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(inner)
        layout.setContentsMargins(20, 20, 20, 20); layout.setSpacing(15)

        conn_group = QtWidgets.QGroupBox(tr("Parâmetros de Conexão"))
        grid = QtWidgets.QGridLayout(conn_group)
        grid.setContentsMargins(12, 14, 12, 12)
        grid.setVerticalSpacing(12); grid.setHorizontalSpacing(15)
        # Forca altura minima das linhas — corrige bug "labels cortados"
        # observado em telas baixas (QGridLayout sem hint de altura espreme).
        for r in range(5):
            grid.setRowMinimumHeight(r, 34)
        self._conn_grid = grid   # _ajustar_grid_conexao zera as linhas ocultas

        # o texto muda com o nível: "Aparelho (porta USB):" no Simples (G35)
        self._conn_port_lbl = _h_label(tr("Porta COM:"))
        grid.addWidget(self._conn_port_lbl, 0, 0)
        self.port_combo = QtWidgets.QComboBox()
        self.port_combo.setMinimumWidth(280); self.port_combo.setMinimumHeight(30)
        grid.addWidget(self.port_combo, 0, 1)
        self.refresh_btn = QtWidgets.QPushButton(tr("Atualizar"))
        self.refresh_btn.setMinimumHeight(30)
        self.refresh_btn.clicked.connect(self._refresh_ports)
        grid.addWidget(self.refresh_btn, 0, 2)

        baud_lbl = _h_label("Baud Rate:")
        grid.addWidget(baud_lbl, 1, 0)
        self.baud_combo = QtWidgets.QComboBox()
        self.baud_combo.setMinimumHeight(30)
        self.baud_combo.addItems(["9600","19200","38400","57600","115200","230400","460800","921600"])
        self.baud_combo.setCurrentText("115200"); self.baud_combo.setEditable(True)
        grid.addWidget(self.baud_combo, 1, 1)

        modo_lbl = _h_label("Modo:")
        grid.addWidget(modo_lbl, 2, 0)
        self.mode_combo = QtWidgets.QComboBox()
        self.mode_combo.setMinimumHeight(30)
        self.mode_combo.addItems([
            tr("Hardware (porta COM real)"),
            tr("Simulação (sinal sintético)"),
            tr("Playback (replay de CSV)"),
        ])
        self.mode_combo.currentIndexChanged.connect(self._on_mode_changed)
        grid.addWidget(self.mode_combo, 2, 1)

        pb_lbl = _h_label(tr("Arquivo de playback:"))
        grid.addWidget(pb_lbl, 3, 0)
        pb_row = QtWidgets.QHBoxLayout(); pb_row.setSpacing(6)
        self.playback_path_edit = QtWidgets.QLineEdit()
        self.playback_path_edit.setMinimumHeight(30)
        self.playback_path_edit.setPlaceholderText(tr("(selecione um CSV gravado anteriormente)"))
        self.playback_path_edit.setEnabled(False)
        pb_row.addWidget(self.playback_path_edit, stretch=1)
        self.playback_browse_btn = QtWidgets.QPushButton(tr("Procurar..."))
        self.playback_browse_btn.setMinimumHeight(30)
        self.playback_browse_btn.setEnabled(False)
        self.playback_browse_btn.clicked.connect(self._select_playback_file)
        pb_row.addWidget(self.playback_browse_btn)
        pb_widget = QtWidgets.QWidget(); pb_widget.setLayout(pb_row)
        grid.addWidget(pb_widget, 3, 1, 1, 2)
        # Simples: só Porta COM + Atualizar e o diretório de sessões
        self._register_advanced("ui", baud_lbl, self.baud_combo, modo_lbl,
                                self.mode_combo, pb_lbl, pb_widget)

        self._conn_dir_lbl = _h_label(tr("Diretório de sessões:"))
        grid.addWidget(self._conn_dir_lbl, 4, 0)
        self.conn_save_dir_label = QtWidgets.QLabel(self.config.save_directory)
        self.conn_save_dir_label.setMinimumHeight(28)
        self.conn_save_dir_label.setStyleSheet(
            f"color: {COLORS['text_dim']}; font-style: italic;")
        self.conn_save_dir_label.setWordWrap(True)
        grid.addWidget(self.conn_save_dir_label, 4, 1, 1, 2)
        layout.addWidget(conn_group)

        # ============================================================
        # Grupo BLUETOOTH — scan e listagem de dispositivos BLE
        # ============================================================
        bt_group = QtWidgets.QGroupBox(tr("Bluetooth (BLE) — Dispositivos Pareáveis"))
        bt_layout = QtWidgets.QVBoxLayout(bt_group)
        bt_layout.setContentsMargins(10, 12, 10, 10); bt_layout.setSpacing(8)

        bt_info = QtWidgets.QLabel(
            tr("Dispositivos Bluetooth Low Energy ao redor. "
            "Para placas com perfil <b>Serial Port</b> (HC-05, Cyton-BT, etc.), "
            "primeiro pareie no Windows (Configurações → Bluetooth) — uma porta "
            "COM virtual será criada e aparecerá na lista de portas acima. "
            "Para dispositivos BLE puros (Ganglion, etc.), use o scan abaixo.")
        )
        bt_info.setTextFormat(QtCore.Qt.TextFormat.RichText)
        bt_info.setStyleSheet(f"color: {COLORS['text_dim']};")
        bt_info.setWordWrap(True)
        bt_info.setMinimumHeight(70)
        bt_layout.addWidget(bt_info)

        bt_row = QtWidgets.QHBoxLayout(); bt_row.setSpacing(8)
        self.bt_scan_btn = QtWidgets.QPushButton(tr("Procurar dispositivos (8 s)"))
        self.bt_scan_btn.setMinimumHeight(32)
        self.bt_scan_btn.clicked.connect(self._bt_scan_start)
        bt_row.addWidget(self.bt_scan_btn)
        self.bt_status_lbl = QtWidgets.QLabel(tr("Pronto."))
        self.bt_status_lbl.setMinimumHeight(28)
        self.bt_status_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        bt_row.addWidget(self.bt_status_lbl, stretch=1)
        self.bt_pair_help_btn = QtWidgets.QPushButton(tr("Como parear no Windows"))
        self.bt_pair_help_btn.setMinimumHeight(32)
        self.bt_pair_help_btn.clicked.connect(self._bt_show_pair_help)
        bt_row.addWidget(self.bt_pair_help_btn)
        bt_layout.addLayout(bt_row)

        self.bt_devices_table = QtWidgets.QTableWidget(0, 4)
        self.bt_devices_table.setHorizontalHeaderLabels([tr("Nome"), tr("Endereço"), tr("RSSI (dBm)"), tr("Tipo")])
        self.bt_devices_table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.bt_devices_table.setSelectionBehavior(
            QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        self.bt_devices_table.verticalHeader().setVisible(False)
        bt_hdr = self.bt_devices_table.horizontalHeader()
        bt_hdr.setSectionResizeMode(QtWidgets.QHeaderView.ResizeMode.ResizeToContents)
        bt_hdr.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeMode.Stretch)
        # Altura mínima/máxima ampliadas para evitar tabela "comida".
        # Em telas pequenas a scroll area da aba toma conta.
        self.bt_devices_table.setMinimumHeight(160)
        self.bt_devices_table.setMaximumHeight(260)
        bt_layout.addWidget(self.bt_devices_table)

        # Estado do scanner
        self._bt_scanner_thread = None

        layout.addWidget(bt_group)

        # ============================================================
        # Grupo de EXPANSAO — seletor multi-step de canais ativos + auto-detecção
        # ============================================================
        exp_group = QtWidgets.QGroupBox(tr("Expansão de Canais"))
        exp_layout = QtWidgets.QVBoxLayout(exp_group)
        exp_layout.setContentsMargins(10, 10, 10, 10); exp_layout.setSpacing(8)
        exp_row = QtWidgets.QHBoxLayout(); exp_row.setSpacing(10)

        exp_lbl = QtWidgets.QLabel(tr("Total de canais ativos:"))
        exp_lbl.setStyleSheet(
            f"color: {COLORS['expansion']}; font-weight: bold; font-size: 11pt;")
        exp_lbl.setMinimumHeight(28)
        exp_row.addWidget(exp_lbl)

        self.expansion_combo = QtWidgets.QComboBox()
        self.expansion_combo.setMinimumWidth(260)
        self.expansion_combo.setMinimumHeight(30)
        for n in EXPANSION_STEPS:
            extra = n - BASE_CHANNELS
            if n == BASE_CHANNELS:
                self.expansion_combo.addItem(tr("{0} canais — placa base").format(n), n)
            elif n <= CYTON_MAX_CHANNELS:
                self.expansion_combo.addItem(
                    tr("{0} canais — base + módulo Daisy (+{1})").format(n, extra), n)
            else:
                self.expansion_combo.addItem(
                    tr("{0} canais — base + {1} módulos de expansão (placa customizada)").format(n, extra//8), n)
        self.expansion_combo.setCurrentIndex(0)  # default: 8 canais
        self.expansion_combo.currentIndexChanged.connect(self._on_expansion_combo_changed)
        exp_row.addWidget(self.expansion_combo)
        exp_row.addStretch()
        detect_btn = QtWidgets.QPushButton(tr("Detectar expansão automaticamente"))
        detect_btn.setMinimumHeight(30)
        detect_btn.clicked.connect(self._detect_expansion)
        exp_row.addWidget(detect_btn)
        exp_layout.addLayout(exp_row)

        # Alias retrocompativel: muitos handlers usam self.expansion_toggle
        # como QCheckBox binario. Mantemos o checkbox oculto, sincronizado com
        # o combo (>= 16ch -> checked), de modo que codigo legado nao quebre.
        self.expansion_toggle = QtWidgets.QCheckBox()
        self.expansion_toggle.setVisible(False)
        self.expansion_toggle.toggled.connect(self._on_expansion_toggled)

        exp_info = QtWidgets.QLabel(
            tr("<b>Modos disponíveis:</b><br>&nbsp;&nbsp;• <b>8 canais</b>: apenas a "
               "placa base (Cyton sozinho — 250 Hz nativo).<br>&nbsp;&nbsp;• <b>16 "
               "canais</b>: placa base + módulo Daisy (Cyton+Daisy — 125 Hz "
               "efetivo).<br>&nbsp;&nbsp;• <b>24–64 canais</b>: placa customizada "
               "Bionica Lab com expansão multi-bloco (EEG / EMG / ECG / EoG multimodal, "
               "taxa configurável).<br><b>Detecção automática</b>: em <i>Playback</i>, "
               "conta as colunas do CSV e ajusta o modo; em <i>Hardware</i>, envia "
               "comando '?' ao dispositivo.<br><b>Canais base (CH1-{0})</b>: cor padrão "
               "da paleta. <b>Canais de expansão (CH{1}-{2})</b>: borda azulada para "
               "distinção visual.").format(BASE_CHANNELS, BASE_CHANNELS+1, MAX_CHANNELS)
        )
        exp_info.setStyleSheet(f"color: {COLORS['text_dim']};")
        exp_info.setWordWrap(True)
        exp_info.setMinimumHeight(110)
        exp_layout.addWidget(exp_info)
        layout.addWidget(exp_group)
        self._register_advanced("ui", bt_group, exp_group)

        # Botões
        btn_row = QtWidgets.QHBoxLayout()
        self.connect_btn = QtWidgets.QPushButton(tr("▶  Conectar"))
        self.connect_btn.setMinimumHeight(46)
        self.connect_btn.clicked.connect(self._toggle_connection)
        btn_row.addWidget(self.connect_btn)
        self.record_btn = QtWidgets.QPushButton(tr("●  Iniciar Gravação"))
        self.record_btn.setMinimumHeight(46); self.record_btn.setEnabled(False)
        self.record_btn.clicked.connect(self._toggle_recording)
        btn_row.addWidget(self.record_btn)
        # Demo 30s — protocolo automático
        self.demo_btn = QtWidgets.QPushButton(tr("Demo 30s"))
        self.demo_btn.setMinimumHeight(46)
        self.demo_btn.setToolTip(
            tr("Protocolo automático: simulação 30s alternando 'olhos_abertos'/"
            "'olhos_fechados' a cada 5s. Grava CSV + gera PDF ao final.")
        )
        self.demo_btn.clicked.connect(self._start_demo_mode)
        btn_row.addWidget(self.demo_btn)
        layout.addLayout(btn_row)
        # Ocultos no Simples (a barra de ação já tem Conectar/Gravar); nunca
        # destruídos: _sync_action_bar lê o texto e o estado deles.
        self._register_advanced("ui", self.connect_btn, self.record_btn,
                                self.demo_btn)

        self.playback_progress = QtWidgets.QProgressBar()
        self.playback_progress.setRange(0, 1000); self.playback_progress.setVisible(False)
        layout.addWidget(self.playback_progress)

        log_group = QtWidgets.QGroupBox(tr("Log da Sessão"))
        log_layout = QtWidgets.QVBoxLayout(log_group)
        self.log_view = QtWidgets.QTextEdit(); self.log_view.setReadOnly(True)
        self.log_view.setMinimumHeight(120)
        log_layout.addWidget(self.log_view)
        # O log é técnico e fica em português DE PROPÓSITO: é o mesmo texto do
        # session.log.txt que vai anexado a pedido de suporte. A dica diz
        # isso, e no Simples o painel some (ali ele ocupava a aba inteira).
        log_group.setToolTip(tr(
            "Registro técnico da sessão, sempre em português: é o mesmo texto "
            "do session.log.txt, que vai anexado a pedidos de suporte."))
        self._register_advanced("ui", log_group)
        layout.addWidget(log_group, stretch=1)

        # Envolve toda a aba em QScrollArea: garante que nenhum grupo seja
        # "comido" verticalmente em telas pequenas (corrige bug de labels
        # cortados em Parâmetros de Conexão, Bluetooth e Expansão).
        scroll = QtWidgets.QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        scroll.setHorizontalScrollBarPolicy(
            QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setVerticalScrollBarPolicy(
            QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        scroll.setWidget(inner)
        return scroll

    # ==================================================================
    # Focus / SSVEP — índice de foco/concentração baseado em bandas EEG
    # ==================================================================
    def _build_focus_tab(self):
        """Aba Focus / SSVEP — métrica de foco em tempo real.

        Calcula 2 razões clássicas a partir do PSD do canal selecionado:
            Engagement  = Beta / (Alpha + Theta)         (escala 0..2+)
            Calmness    = Alpha / Beta                    (escala 0..3+)
            SSVEP power = banda 1Hz em torno da freq alvo
        E mantém um histórico temporal das 3 métricas.
        """
        widget = QtWidgets.QWidget()
        outer = QtWidgets.QVBoxLayout(widget)
        outer.setContentsMargins(8, 8, 8, 8); outer.setSpacing(6)

        # === Controles ===
        ctrl = QtWidgets.QHBoxLayout()
        ctrl.addWidget(QtWidgets.QLabel(tr("Canal EEG:")))
        self.focus_channel_combo = QtWidgets.QComboBox()
        # So os canais que existem. Com placa de 8 canais o combo nascia com 64
        # itens e caía no CH20 (Oz), que nunca recebe amostra: os quatro
        # cartoes ficavam em 0,00 sem nenhum aviso na tela.
        for ch in range(self.num_channels):
            elec = self.config.channel_mapping[ch] if ch < len(self.config.channel_mapping) else f"E{ch+1}"
            self.focus_channel_combo.addItem(f"CH{ch+1} ({elec})", ch)
        idx_pref = self._focus_canal_preferido(self.num_channels)
        if idx_pref is not None:
            self.focus_channel_combo.setCurrentIndex(idx_pref)
        ctrl.addWidget(self.focus_channel_combo)
        ctrl.addSpacing(15)
        ctrl.addWidget(QtWidgets.QLabel(tr("Freq SSVEP alvo (Hz):")))
        self.focus_ssvep_freq = QtWidgets.QDoubleSpinBox()
        self.focus_ssvep_freq.setRange(4.0, 50.0)
        self.focus_ssvep_freq.setValue(12.0)
        self.focus_ssvep_freq.setSingleStep(1.0)
        self.focus_ssvep_freq.setSuffix(" Hz")
        self.focus_ssvep_freq.setToolTip(
            tr("Frequência do estímulo visual flicker (LED/tela). "
            "Comum: 7.5, 8.57, 10, 12, 15 Hz.")
        )
        ctrl.addWidget(self.focus_ssvep_freq)
        ctrl.addStretch()
        btn_baseline = QtWidgets.QPushButton(tr("Definir baseline (5s)"))
        btn_baseline.setToolTip(tr("Coleta 5s de baseline para normalizar o índice de foco."))
        btn_baseline.clicked.connect(self._focus_start_baseline)
        ctrl.addWidget(btn_baseline)
        btn_reset = QtWidgets.QPushButton(tr("Reset"))
        btn_reset.clicked.connect(self._focus_reset)
        ctrl.addWidget(btn_reset)
        outer.addLayout(ctrl)

        # === Cards de métricas ===
        cards = QtWidgets.QHBoxLayout()
        for key, label, color in (
            # Cores do TEMA: o verde e o ambar fixos davam 1,2:1 de contraste
            # sobre o branco do tema padrao. O cartao do SSVEP mostra um SNR,
            # nao potencia, e o nome passa a dizer isso.
            ("engagement", tr("Engagement"), COLORS["accent"]),
            ("calmness",   tr("Calmness"),   COLORS["expansion"]),
            ("ssvep",      tr("SNR SSVEP"),  COLORS["warning"]),
            ("state",      tr("Estado"),     COLORS["warning"]),
        ):
            box = QtWidgets.QVBoxLayout()
            val = QtWidgets.QLabel("--")
            val.setStyleSheet(
                f"color: {color}; font-size: 22pt; font-weight: bold; "
                f"font-family: {FONT_DATA_STACK}; padding: 4px 6px;")
            val.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            val.setMinimumHeight(50)
            box.addWidget(val)
            lbl = QtWidgets.QLabel(label)
            lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
            lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            box.addWidget(lbl)
            if not hasattr(self, "_focus_metric_lbls"):
                self._focus_metric_lbls = {}
            self._focus_metric_lbls[key] = val
            cards.addLayout(box)
            cards.addSpacing(20)
        cards.addStretch()
        outer.addLayout(cards)

        # === FFT + Histórico temporal ===
        split = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
        # FFT do canal
        left = QtWidgets.QWidget()
        ll = QtWidgets.QVBoxLayout(left); ll.setContentsMargins(2, 2, 2, 2)
        ll.addWidget(QtWidgets.QLabel(tr("Espectro do canal selecionado")))
        self.focus_fft_plot = pg.PlotWidget(enableMenu=False)
        self.focus_fft_plot.showGrid(x=True, y=True, alpha=0.15)
        self.focus_fft_plot.setLabel("left",   tr("Amplitude"), units="µV")
        self.focus_fft_plot.setLabel("bottom", tr("Freq"),      units="Hz")
        self.focus_fft_plot.setXRange(0, 40)
        self.focus_fft_plot.setMenuEnabled(False)
        self.focus_fft_curve = self.focus_fft_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=1.4))
        # Marca bandas Mu/Beta com linhas
        for _, (lo, _hi) in EEG_BANDS.items():
            self.focus_fft_plot.addItem(pg.InfiniteLine(
                pos=lo, angle=90,
                pen=pg.mkPen(COLORS["border"], style=QtCore.Qt.PenStyle.DashLine)))
        # Linha vertical em freq SSVEP alvo
        self.focus_ssvep_line = pg.InfiniteLine(
            pos=12.0, angle=90,
            pen=pg.mkPen(COLORS["warning"], width=2,
                         style=QtCore.Qt.PenStyle.DotLine))
        self.focus_fft_plot.addItem(self.focus_ssvep_line)
        self.focus_ssvep_freq.valueChanged.connect(
            lambda v: self.focus_ssvep_line.setPos(v))
        ll.addWidget(self.focus_fft_plot)
        split.addWidget(left)
        # Histórico temporal
        right = QtWidgets.QWidget()
        rl = QtWidgets.QVBoxLayout(right); rl.setContentsMargins(2, 2, 2, 2)
        # Legenda FORA da área de dados: as curvas de verdade (até ~33 na
        # escala bruta) atravessavam o texto da legenda interna.
        _leg = QtWidgets.QLabel(
            tr("Histórico (últimos ~60 s)") + "&nbsp;&nbsp;" + "&nbsp;&nbsp;".join(
                f"<span style='color:{c}'>━</span>&nbsp;{_html_escape(n)}"
                for c, n in ((COLORS["accent"], tr("Engagement")),
                             (COLORS["expansion"], tr("Calmness")),
                             (COLORS["warning"], "SSVEP"))))
        _leg.setTextFormat(QtCore.Qt.TextFormat.RichText)
        rl.addWidget(_leg)
        self.focus_time_plot = pg.PlotWidget(enableMenu=False)
        self.focus_time_plot.showGrid(x=True, y=True, alpha=0.15)
        # Antes da baseline as curvas sao valor absoluto; o rotulo fixo
        # "normalizada" mentia ate a calibracao e nao sinalizava a troca depois.
        self.focus_time_plot.setLabel("left", tr("Métrica (bruta)"))
        self.focus_time_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.focus_time_plot.setMenuEnabled(False)
        self.focus_eng_curve = self.focus_time_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=1.6), name=tr("Engagement"))
        self.focus_calm_curve = self.focus_time_plot.plot(
            pen=pg.mkPen(COLORS["expansion"], width=1.6), name=tr("Calmness"))
        self.focus_ssvep_curve = self.focus_time_plot.plot(
            pen=pg.mkPen(COLORS["warning"], width=1.6), name="SSVEP")
        rl.addWidget(self.focus_time_plot)
        split.addWidget(right)
        split.setSizes([520, 600])
        outer.addWidget(split, stretch=1)

        # Estado interno
        self._focus_history = {"t": [], "engagement": [], "calmness": [], "ssvep": []}
        self._focus_baseline = {"engagement": None, "calmness": None, "ssvep": None}
        self._focus_baseline_collecting = False
        self._focus_baseline_data = []
        self._focus_baseline_start_t = 0.0
        self._focus_baseline_falhou = False
        return widget

    def _focus_canal_preferido(self, n):
        """Melhor canal para foco/SSVEP entre os n canais ativos.

        A ordem vai do occipital (onde o SSVEP e maior) para o frontal: com 8
        canais cai em O1, com 32 ou 64 continua caindo em Oz como antes.
        """
        mapa = self.config.channel_mapping
        for alvo in ("Oz", "O1", "O2", "POz", "Pz", "Cz", "Fz"):
            for i in range(min(int(n), len(mapa))):
                if mapa[i] == alvo:
                    return i
        return 0 if n > 0 else None

    def _focus_reset(self):
        """Zera o histórico, a baseline e os indicadores da aba Focus/SSVEP."""
        self._focus_history = {"t": [], "engagement": [], "calmness": [], "ssvep": []}
        self._focus_baseline = {"engagement": None, "calmness": None, "ssvep": None}
        self._focus_baseline_falhou = False
        if hasattr(self, "focus_time_plot"):
            self.focus_time_plot.setLabel("left", tr("Métrica (bruta)"))
        if hasattr(self, "focus_eng_curve"):
            self.focus_eng_curve.setData([], [])
            self.focus_calm_curve.setData([], [])
            self.focus_ssvep_curve.setData([], [])
        for k in ("engagement", "calmness", "ssvep", "state"):
            if k in self._focus_metric_lbls:
                self._focus_metric_lbls[k].setText("--")

    def _focus_start_baseline(self):
        """Inicia coleta de baseline 5s para normalizar métricas."""
        self._focus_baseline_collecting = True
        self._focus_baseline_data = []
        self._focus_baseline_start_t = time.time()
        self._focus_baseline_falhou = False
        self._log("Coletando baseline de foco (5s — relaxe e olhe um ponto fixo)...")

    def _compute_focus_metrics(self, signal, fs, ssvep_freq, sig_ssvep=None):
        """Calcula engagement, calmness e SSVEP power do canal.

        `sig_ssvep` (opcional, alguns segundos) alimenta só o SNR do SSVEP,
        estimado por Welch com segmentos de 2 s."""
        if len(signal) < int(fs * 1.0):
            return None
        # PSD via FFT
        try:
            n = len(signal)
            # Remove DC + linear trend
            sig = signal - np.mean(signal)
            window = np.hanning(n)
            spec = np.fft.rfft(sig * window)
            freqs = np.fft.rfftfreq(n, 1.0 / fs)
            psd = (np.abs(spec) ** 2) / (n * fs)
        except Exception:
            return None
        # Bandas
        def band_power(f_lo, f_hi):
            """Integra o PSD já calculado dentro de uma faixa de frequência, para
            compor as razões de engajamento e calma.

            Usa freqs e psd do escopo de _compute_focus_metrics; devolve 0.0
            quando nenhum bin cai na faixa pedida.
            """
            mask = (freqs >= f_lo) & (freqs < f_hi)
            if not mask.any():
                return 0.0
            # Mesmo erro de meio-bin do compute_band_power, e aqui ele NÃO se
            # cancela na razão: Theta tem 4 bins (−25%) e Beta 17 (−6%), logo o
            # Engagement de Pope β/(α+θ) saía inflado ~20% por viés puramente de
            # largura de banda, não por fisiologia.
            dfb = float(freqs[1] - freqs[0]) if freqs.size > 1 else 1.0
            return float(np.sum(psd[mask]) * dfb)
        theta = band_power(4, 8)
        alpha = band_power(8, 13)
        beta  = band_power(13, 30)
        # Engagement = Beta / (Alpha + Theta) — Pope et al. 1995
        eng = beta / (alpha + theta) if (alpha + theta) > 0 else 0.0
        calm = alpha / beta if beta > 0 else 0.0
        # SSVEP: pico em ±0.5 Hz da freq alvo, normalizado pela vizinhança
        mask_s = (freqs >= ssvep_freq - 0.5) & (freqs <= ssvep_freq + 0.5)
        mask_n = ((freqs >= ssvep_freq - 2.0) & (freqs < ssvep_freq - 0.5)) | \
                 ((freqs > ssvep_freq + 0.5) & (freqs <= ssvep_freq + 2.0))
        # SNR do SSVEP: Welch (segmentos de 2 s) e MEDIANA dos dois lados. A
        # média no alvo contra a mediana no ruído dava 1/ln2 = 1,44 sem
        # estímulo nenhum, e um periodograma único de 2 s passava de 4,6 em 5%
        # dos quadros. Com o mesmo estimador, "sem resposta" fica perto de 1.
        # (Mediana no ruído também porque o alfa em 10 Hz cai na vizinhança
        # de um alvo de 12 Hz e, pela média, derrubava o SNR a ~0.)
        fr_s, ps_s = freqs, psd
        if sig_ssvep is not None and len(sig_ssvep) >= int(fs * 1.0):
            try:
                xs = np.asarray(sig_ssvep, float)
                fr_s, ps_s = scipy_signal.welch(
                    xs - np.mean(xs), fs=fs, nperseg=min(len(xs), int(2 * fs)))
            except Exception:
                fr_s, ps_s = freqs, psd
        m_s = (fr_s >= ssvep_freq - 0.5) & (fr_s <= ssvep_freq + 0.5)
        m_n = ((fr_s >= ssvep_freq - 2.0) & (fr_s < ssvep_freq - 0.5)) | \
              ((fr_s > ssvep_freq + 0.5) & (fr_s <= ssvep_freq + 2.0))
        if int(np.count_nonzero(m_n)) < 3 or not m_s.any():
            ssvep_snr = None     # vizinhanca curta demais: medida indefinida
        else:
            sig_p = float(np.median(ps_s[m_s]))
            noi_p = float(np.median(ps_s[m_n]))
            ssvep_snr = sig_p / max(noi_p, 1e-12)
        return {
            "engagement": eng,
            "calmness":   calm,
            "ssvep":      ssvep_snr,
            "freqs": freqs, "psd": psd,
        }

    def _update_focus_view(self):
        """Atualiza FFT, métricas e histórico de foco."""
        if not hasattr(self, "focus_fft_plot"): return
        ch = self.focus_channel_combo.currentData() if hasattr(self, "focus_channel_combo") else 0
        if ch is None or ch < 0: ch = 0
        data = self._ordered_buffer()
        if data.shape[1] < int(SAMPLE_RATE * 1.0): return
        sig = data[ch].astype(np.float64)
        # Pega último ~2s para latência menor
        n_win = min(len(sig), int(SAMPLE_RATE * 2.0))
        win = sig[-n_win:]
        # SNR do SSVEP sobre ~4 s (3 segmentos de 2 s): um quadro único oscilava
        # ordens de grandeza sem estímulo algum
        m = self._compute_focus_metrics(win, SAMPLE_RATE,
                                         self.focus_ssvep_freq.value(),
                                         sig_ssvep=sig[-min(len(sig), int(SAMPLE_RATE * 4.0)):])
        if m is None: return
        # FFT plot
        self.focus_fft_curve.setData(m["freqs"], np.sqrt(m["psd"]))
        # Baseline em coleta
        if self._focus_baseline_collecting:
            self._focus_baseline_data.append(
                (m["engagement"], m["calmness"],
                 m["ssvep"] if m["ssvep"] is not None else float("nan")))
            if (time.time() - self._focus_baseline_start_t) > 5.0:
                # Desliga a coleta ANTES de qualquer caixa: este bloco roda
                # dentro do temporizador de 50 ms e so pode avisar uma vez.
                self._focus_baseline_collecting = False
                vals = {}
                if self._focus_baseline_data:
                    arr = np.array(self._focus_baseline_data, dtype=float)
                    col_s = arr[:, 2]
                    vals = {
                        "engagement": float(np.mean(arr[:, 0])),
                        "calmness":   float(np.mean(arr[:, 1])),
                        "ssvep": (float(np.mean(col_s[np.isfinite(col_s)]))
                                  if np.any(np.isfinite(col_s)) else float("nan")),
                    }
                aceita = bool(vals) and all(np.isfinite(v) and v > 0
                                            for v in vals.values())
                if aceita:
                    self._focus_baseline = vals
                    self._focus_baseline_falhou = False
                    # Tudo o que esta no grafico passa a compartilhar a unidade
                    # nova: antes os pontos colhidos ANTES da calibracao eram
                    # divididos por uma baseline que ainda nao existia quando
                    # foram medidos.
                    self._focus_history = {"t": [], "engagement": [],
                                           "calmness": [], "ssvep": []}
                    self.focus_time_plot.setLabel("left", tr("Métrica (× baseline)"))
                    self._log(f"Baseline definido: Eng={vals['engagement']:.2f} "
                              f"Calm={vals['calmness']:.2f} (historico zerado)")
                else:
                    self._focus_baseline = {"engagement": None,
                                            "calmness": None, "ssvep": None}
                    self._focus_baseline_falhou = True
                    self.focus_time_plot.setLabel("left", tr("Métrica (bruta)"))
                    if float(np.std(win)) < 1e-9:
                        texto = tr("O canal CH{0} não tem sinal: a baseline saiu "
                                   "zerada e foi descartada. Escolha um canal "
                                   "ativo e tente de novo.").format(ch + 1)
                    else:
                        texto = tr("As métricas ficaram em zero durante os 5 s. "
                                   "A baseline foi descartada — confira "
                                   "eletrodos e filtros antes de repetir.")
                    self._log("Baseline de foco descartada: valores nulos.",
                              error=True)
                    QtWidgets.QMessageBox.information(
                        self, tr("Baseline não aceita"), texto)
        # Atualiza cards
        def show(key, fmt):
            """Escreve um card de métrica de foco, em múltiplos da baseline quando
            ela já foi coletada e em valor absoluto caso contrário.

            Com baseline o texto sai como "1.23×"; sem baseline aplica o
            formato passado em fmt.
            """
            v = m[key]
            if v is None or not np.isfinite(v):
                self._focus_metric_lbls[key].setText("--")
                return
            base = self._focus_baseline.get(key)
            if base is not None and base > 0:
                v_norm = v / base
                self._focus_metric_lbls[key].setText(fmt.format(v_norm) + "×")
            else:
                self._focus_metric_lbls[key].setText(fmt.format(v))
        show("engagement", "{:.2f}")
        show("calmness",   "{:.2f}")
        # uma casa: a segunda sugeria uma precisão que a razão não tem
        show("ssvep",      "{:.1f}")
        # Estado discreto
        base_eng = self._focus_baseline.get("engagement")
        if base_eng is not None and base_eng > 0:
            ratio = m["engagement"] / base_eng
            if   ratio > 1.4: state = "FOCADO"; color = COLORS["warning"]
            elif ratio < 0.8: state = "RELAXADO"; color = COLORS["expansion"]
            else:             state = "NORMAL"; color = COLORS["text"]
        elif getattr(self, "_focus_baseline_falhou", False):
            state = "Baseline falhou"; color = COLORS["error"]
        else:
            state = "(sem baseline)"; color = COLORS["text_dim"]
        self._focus_metric_lbls["state"].setText(tr(state))
        self._focus_metric_lbls["state"].setStyleSheet(
            f"color: {color}; font-size: 22pt; font-weight: bold;")
        # Histórico
        now = time.time()
        H = self._focus_history
        H["t"].append(now)
        H["engagement"].append(m["engagement"])
        H["calmness"].append(m["calmness"])
        H["ssvep"].append(m["ssvep"] if m["ssvep"] is not None else float("nan"))
        # Poda pelo RELOGIO, nao por contagem. O teto de 120 pontos supunha
        # 2 Hz, mas quem alimenta e o timer de 50 ms: o grafico cobria de 6 a
        # 16 s conforme a carga da maquina enquanto o titulo prometia ~60 s.
        JAN_FOCUS_S = 60.0
        corte = now - JAN_FOCUS_S
        k = 0
        while k < len(H["t"]) and H["t"][k] < corte:
            k += 1
        if k:
            for key in ("t", "engagement", "calmness", "ssvep"):
                H[key] = H[key][k:]
        if len(H["t"]) > 4000:        # rede de seguranca
            for key in ("t", "engagement", "calmness", "ssvep"):
                H[key] = H[key][-4000:]
        t0 = H["t"][0] if H["t"] else now
        t_rel = [t - t0 for t in H["t"]]
        # Normaliza com baseline (ou bruto)
        def norm(arr, key):
            """Converte uma série do histórico de Focus em múltiplos do baseline
            antes de plotá-la.

            Sem baseline devolve a lista original. Como o histórico e zerado no
            momento em que a baseline e aceita, todos os pontos na tela estão
            sempre na MESMA unidade, e o rótulo do eixo Y diz qual e ela.
            """
            base = self._focus_baseline.get(key)
            if base and base > 0:
                return [v / base for v in arr]
            return arr

        def desenha(curva, key):
            """Plota só os pontos finitos: o SNR de SSVEP fica indefinido
            quando a vizinhança de ruído tem menos de 3 bins."""
            ys = norm(H[key], key)
            pares = [(x, y) for x, y in zip(t_rel, ys) if np.isfinite(y)]
            curva.setData([p[0] for p in pares], [p[1] for p in pares])
        desenha(self.focus_eng_curve,   "engagement")
        desenha(self.focus_calm_curve,  "calmness")
        desenha(self.focus_ssvep_curve, "ssvep")

    # ==================================================================
    # EMG Joystick — mapeamento de 4 canais EMG para X/Y de joystick virtual
    # ==================================================================
    # ==================================================================
    # BCI Trainer (Motor Imagery — CSP + LDA simplificados)
    # ==================================================================
    def _build_bci_trainer_tab(self):
        """Treinador BCI de Imaginação Motora (Esquerda vs Direita).

        Pipeline:
            1. Calibração: N trials por classe (8s cada: 2s preparação + 4s MI + 2s descanso)
            2. Treino: CSP (6 filtros) + LDA binário
            3. Online: classifica em tempo real, mostra barra de feedback

        Sem dependência de scikit-learn: CSP via scipy eigh + LDA Fisher manual.
        """
        widget = QtWidgets.QWidget()
        outer = QtWidgets.QVBoxLayout(widget)
        outer.setContentsMargins(8, 8, 8, 8); outer.setSpacing(8)

