    def _bci_parse_channels(self):
        """Parse self.bci_channels_edit -> lista de índices 0-based."""
        chs = []
        try:
            for tok in self.bci_channels_edit.text().replace(";", ",").split(","):
                tok = tok.strip()
                if tok.isdigit():
                    v = int(tok) - 1
                    if 0 <= v < MAX_CHANNELS: chs.append(v)
        except Exception: pass
        return chs

    def _bci_record_trial(self, label):
        """Captura janela MI da última X segundos como trial."""
        chs = self._bci_parse_channels()
        if not chs:
            QtWidgets.QMessageBox.information(
                self, tr("Canais"), tr("Informe canais (ex.: 3,4).")); return
        data = self._ordered_buffer()
        dur = self.bci_dur_spin.value()
        n_w = int(dur * SAMPLE_RATE)
        if data.shape[1] < n_w:
            QtWidgets.QMessageBox.information(
                self, tr("Buffer insuficiente"),
                tr("Aguarde {0}s de sinal acumulado primeiro.").format(dur)); return
        # Sem cronometro nem pista, dois cliques seguidos gravavam quase a
        # mesma janela (91% de amostras em comum a 0,27 s de intervalo). Trials
        # correlacionados caem em folds diferentes e a acuracia "validada"
        # volta a medir memorizacao.
        marca = getattr(self, "_bci_last_sample", None)
        if marca is not None:
            novas = self.samples_total - marca
            if novas < n_w:
                if novas <= 0 and not self.serial_thread:
                    QtWidgets.QMessageBox.information(
                        self, tr("Trial ainda sobreposto"),
                        tr("Não há sinal novo chegando: conecte o equipamento "
                           "antes de gravar outro trial."))
                else:
                    falta = max(0.0, (n_w - novas) / float(SAMPLE_RATE))
                    QtWidgets.QMessageBox.information(
                        self, tr("Trial ainda sobreposto"),
                        tr("O trial anterior ainda ocupa esta janela. Espere "
                           "mais {0:.1f} s de sinal novo antes de gravar "
                           "outro.").format(falta))
                return
        win = data[chs, -n_w:].astype(np.float64)
        # Bandpass via filtro Butterworth ordem 4
        try:
            sos = scipy_signal.butter(4,
                [self.bci_band_lo.value() / (SAMPLE_RATE/2),
                 self.bci_band_hi.value() / (SAMPLE_RATE/2)],
                btype="bandpass", output="sos")
            win = scipy_signal.sosfiltfilt(sos, win, axis=1)
        except Exception: pass
        self._bci_trials[label].append(win)
        self._bci_last_sample = self.samples_total
        name = "ESQUERDA" if label == 0 else "DIREITA"
        n0 = len(self._bci_trials[0]); n1 = len(self._bci_trials[1])
        target = self.bci_trials_spin.value()
        self.bci_calib_progress.setValue(
            int(100 * min(1.0, (n0 + n1) / (2 * target))))
        self.bci_status_lbl.setText(
            tr("Trial {0} #{1} salvo. Total: {2}/{3} esq, {4}/{3} dir.").format(name, n0 if label==0 else n1, n0, target, n1))
        self._log(f"BCI trial gravado: {name} (n={n0 if label==0 else n1})")

    def _bci_train_classifier(self):
        """Treina CSP+LDA a partir dos trials gravados."""
        n0 = len(self._bci_trials[0]); n1 = len(self._bci_trials[1])
        if n0 < 5 or n1 < 5:
            QtWidgets.QMessageBox.information(
                self, tr("Trials insuficientes"),
                tr("Mínimo 5 trials por classe. Atual: esq={0}, dir={1}.").format(n0, n1)); return
        try:
            # Covariancia normalizada pelo TRACO (_mi_cov). Sem isso o autovalor
            # generalizado eigh(S0, Sc) e dominado pela amplitude bruta do trial:
            # eletrodo que soltou, impedancia que mudou ou artefato de movimento
            # concentrado numa das classes viram o "padrao espacial" aprendido.
            # Medido com o mesmo padrao espacial e so o ganho 4x diferente:
            # tr(S0)/tr(S1) era 16,2x; com _mi_cov e 1,0x.
            S0 = np.mean([_mi_cov(t) for t in self._bci_trials[0]], axis=0)
            S1 = np.mean([_mi_cov(t) for t in self._bci_trials[1]], axis=0)
            # Tikhonov proporcional ao traco: depois da normalizacao tr(S)=1, e o
            # 1e-6 absoluto de antes virava uma regularizacao de escala arbitraria.
            n_ch_cov = S0.shape[0]
            Sc = S0 + S1 + 1e-3 * np.trace(S0 + S1) / n_ch_cov * np.eye(n_ch_cov)
            # CSP: generalized eigenproblem S0 W = λ Sc W
            from scipy.linalg import eigh
            eigvals, eigvecs = eigh(S0, Sc)
            # Pega filtros extremos (mais discriminativos)
            n_ch = S0.shape[0]
            n_filt = min(6, n_ch)
            idxs = list(range(n_filt // 2)) + list(range(-n_filt // 2, 0))
            W = eigvecs[:, idxs].T  # (n_filters, n_ch)
            self._bci_csp_W = W
            # Features: log-variance dos sinais filtrados por CSP
            def features(trial):
                """Log-variância normalizada dos sinais projetados por CSP —
                o vetor de características que o LDA separa."""
                Y = W @ trial
                v = np.var(Y, axis=1)
                return np.log(v / np.sum(v))
            X0 = np.array([features(t) for t in self._bci_trials[0]])
            X1 = np.array([features(t) for t in self._bci_trials[1]])
            # LDA Fisher
            mu0 = X0.mean(0); mu1 = X1.mean(0)
            Sw = np.cov(X0.T) + np.cov(X1.T)
            w = np.linalg.pinv(Sw + 1e-6 * np.eye(Sw.shape[0])) @ (mu1 - mu0)
            self._bci_lda_w = w
            self._bci_lda_threshold = float(0.5 * w @ (mu0 + mu1))
            # A acuracia exibida antes era medida nos MESMOS trials usados para
            # ajustar CSP e LDA, entao nao media generalizacao nenhuma: com ruido
            # branco puro nas duas classes (zero informacao) o rotulo mostrava 72%
            # em media e batia 100,0% em 28 de 30 sementes com 8 canais x 5
            # trials/classe — o modelo so decorava os trials. Agora a acuracia vem
            # de k-fold estratificado com CSP e LDA reajustados DENTRO de cada
            # fold, acompanhada do teto de acaso binomial, para o operador nao
            # confundir sobreajuste com controle de BCI.
            ep_all = list(self._bci_trials[0]) + list(self._bci_trials[1])
            y_all = np.array([0] * n0 + [1] * n1)
            k = int(max(2, min(5, n0, n1)))
            cv = mi_cv_accuracy(ep_all, y_all, SAMPLE_RATE, method="csp", k=k)
            chance = mi_chance_ceiling(n0 + n1)
            if cv is None:
                acc = None
                self.bci_accuracy_lbl.setText(tr("Acurácia: NÃO VALIDADA"))
                self.bci_status_lbl.setText(
                    tr("Classificador treinado, mas sem trials suficientes para "
                    "validação cruzada — resultado não verificado."))
            else:
                acc = cv[0] / 100.0
                self.bci_accuracy_lbl.setText(
                    tr("Acurácia ({0}-fold CV): {1:.1f}% ± {2:.1f}% | acaso ≤ {3:.1f}%").format(k, cv[0], cv[1], chance))
                # duas frases inteiras: "ACIMA"/"DENTRO" solto no meio não se
                # traduz com a gramática certa
                if cv[0] > chance:
                    msg = tr("Classificador treinado. Acurácia validada por {0}-fold: "
                             "{1:.1f}% — ACIMA do nível de acaso ({2:.1f}%). Clique "
                             "'Iniciar Online' para feedback.")
                else:
                    msg = tr("Classificador treinado. Acurácia validada por {0}-fold: "
                             "{1:.1f}% — DENTRO do nível de acaso ({2:.1f}%). Clique "
                             "'Iniciar Online' para feedback.")
                self.bci_status_lbl.setText(msg.format(k, cv[0], chance))
            self.bci_online_btn.setEnabled(True)
            self._audit_event("bci_classifier_trained",
                              n_trials=(n0, n1), accuracy=acc,
                              cv_folds=k, chance_ceiling=float(chance))
        except Exception as exc:
            QtWidgets.QMessageBox.critical(
                self, tr("Falha no treino"), tr("Erro: {0}").format(exc))
            self._log(f"BCI training failed: {exc}", error=True)

    def _bci_toggle_online(self, checked):
        """Inicia/para classificação online com feedback."""
        if not checked:
            if self._bci_online_timer:
                self._bci_online_timer.stop()
                self._bci_online_timer = None
            self.bci_online_btn.setText(tr("Iniciar Online"))
            self.bci_status_lbl.setText(tr("Online: parado."))
            return
        if self._bci_csp_W is None:
            self.bci_online_btn.setChecked(False)
            QtWidgets.QMessageBox.information(
                self, tr("Sem classificador"), tr("Treine o classificador primeiro.")); return
        self._bci_online_timer = QTimer(self)
        self._bci_online_timer.timeout.connect(self._bci_online_step)
        self._bci_online_timer.start(250)
        self.bci_online_btn.setText(tr("Parar Online"))
        self.bci_status_lbl.setText(tr("Online: classificando MI a cada 250ms..."))
        self._audit_event("bci_online_started")

    def _bci_online_step(self):
        """Classifica janela atual e atualiza barra de feedback."""
        if self._bci_csp_W is None or self._bci_lda_w is None: return
        chs = self._bci_parse_channels()
        if not chs: return
        data = self._ordered_buffer()
        n_w = int(self.bci_dur_spin.value() * SAMPLE_RATE)
        if data.shape[1] < n_w: return
        try:
            win = data[chs, -n_w:].astype(np.float64)
            sos = scipy_signal.butter(4,
                [self.bci_band_lo.value() / (SAMPLE_RATE/2),
                 self.bci_band_hi.value() / (SAMPLE_RATE/2)],
                btype="bandpass", output="sos")
            win = scipy_signal.sosfiltfilt(sos, win, axis=1)
            Y = self._bci_csp_W @ win
            v = np.var(Y, axis=1)
            feat = np.log(v / np.sum(v))
            score = float(feat @ self._bci_lda_w - self._bci_lda_threshold)
            # Mapeia para -100..+100 com tanh
            val = int(100 * np.tanh(score))
            self.bci_feedback_bar.setValue(val)
            # So setText: este passo roda dentro de um temporizador de 250 ms.
            if abs(val) < 10:
                self.bci_decisao_lbl.setText(tr("Indeciso"))
            elif val < 0:
                self.bci_decisao_lbl.setText(
                    tr("Esquerda {0:.0f}%").format(abs(val)))
            else:
                self.bci_decisao_lbl.setText(tr("Direita {0:.0f}%").format(val))
        except Exception: pass

    def _bci_reset(self):
        """Descarta a calibração do treinador BCI e devolve a aba ao estado
        inicial.

        Apaga os trials das duas classes, o filtro CSP e os pesos do LDA —
        depois disso é obrigatório recalibrar. Para e descarta o timer do modo
        online, e desmarca/desabilita o botão Online.
        """
        self._bci_trials = {0: [], 1: []}
        self._bci_csp_W = None
        self._bci_lda_w = None
        self._bci_lda_threshold = 0.0
        if self._bci_online_timer:
            self._bci_online_timer.stop()
            self._bci_online_timer = None
        self.bci_online_btn.setChecked(False)
        self.bci_online_btn.setEnabled(False)
        self.bci_online_btn.setText(tr("Iniciar Online"))
        self.bci_calib_progress.setValue(0)
        self.bci_feedback_bar.setValue(0)
        self.bci_accuracy_lbl.setText(tr("Acurácia (validação cruzada): --"))
        self.bci_decisao_lbl.setText(tr("Sem classificação ainda."))
        self._bci_last_sample = None
        self.bci_status_lbl.setText(tr("Reset. Pronto para nova calibração."))

    def _build_emg_joystick_tab(self):
        """Aba EMG Joystick — controle proporcional via EMG.

        Mapeia 4 canais EMG para 4 direções (X+, X-, Y+, Y-).
        Calibração por canal: max EMG durante contração → normaliza saída [0,1].
        Dead zone evita drift quando músculos relaxados.
        Saída pode ser enviada via UDP (joystick virtual no PC alvo).
        """
        widget = QtWidgets.QWidget()
        outer = QtWidgets.QVBoxLayout(widget)
        outer.setContentsMargins(8, 8, 8, 8); outer.setSpacing(6)

        # === Mapeamento ===
        map_group = QtWidgets.QGroupBox(tr("Mapeamento dos 4 canais EMG → eixos"))
        mg = QtWidgets.QGridLayout(map_group)
        mg.addWidget(QtWidgets.QLabel(tr("Direção")),       0, 0)
        mg.addWidget(QtWidgets.QLabel(tr("Canal EMG")),     0, 1)
        mg.addWidget(QtWidgets.QLabel(tr("Envelope atual")),0, 2)
        mg.addWidget(QtWidgets.QLabel(tr("Max calibrado")), 0, 3)
        mg.addWidget(QtWidgets.QLabel(tr("Calibrar (3s contração)")), 0, 4)
        self._joy_axes = {}  # {direction: dict}
        directions = [
            (tr("X+ (direita)"), "+x"),
            (tr("X- (esquerda)"), "-x"),
            (tr("Y+ (cima)"),    "+y"),
            (tr("Y- (baixo)"),   "-y"),
        ]
        for row, (label, code) in enumerate(directions, start=1):
            dl = QtWidgets.QLabel(label)
            dl.setStyleSheet(f"color: {SIGNAL_TYPE_COLORS['EMG']}; font-weight: bold;")
            mg.addWidget(dl, row, 0)
            # Combo de canal EMG
            cb = QtWidgets.QComboBox()
            cb.setMinimumWidth(150)
            mg.addWidget(cb, row, 1)
            # Envelope atual
            env_lbl = QtWidgets.QLabel("0.0")
            env_lbl.setStyleSheet(f"color: {COLORS['text']}; font-family: {FONT_DATA_STACK};")
            env_lbl.setMinimumWidth(60)
            mg.addWidget(env_lbl, row, 2)
            # Max calibrado
            max_lbl = QtWidgets.QLabel("--")
            max_lbl.setStyleSheet(f"color: {COLORS['text_dim']}; font-family: {FONT_DATA_STACK};")
            max_lbl.setMinimumWidth(60)
            mg.addWidget(max_lbl, row, 3)
            # Botão calibrar
            btn = QtWidgets.QPushButton(tr("Calibrar"))
            btn.clicked.connect(lambda _ck, c=code: self._joy_calibrate(c))
            mg.addWidget(btn, row, 4)
            self._joy_axes[code] = {
                "combo": cb, "env_lbl": env_lbl, "max_lbl": max_lbl,
                "max_value": 100.0, "calibrating": False,
                "calibration_data": [], "calibration_start": 0.0,
            }
        outer.addWidget(map_group)
        self._joy_repopulate_combos()

        # === Configurações ===
        cfg_group = QtWidgets.QGroupBox(tr("Configurações"))
        cl = QtWidgets.QHBoxLayout(cfg_group)
        cl.addWidget(QtWidgets.QLabel(tr("Dead zone:")))
        self.joy_dead_zone_spin = QtWidgets.QDoubleSpinBox()
        self.joy_dead_zone_spin.setRange(0.0, 0.5)
        self.joy_dead_zone_spin.setValue(0.15)
        self.joy_dead_zone_spin.setSingleStep(0.05)
        self.joy_dead_zone_spin.setDecimals(2)
        cl.addWidget(self.joy_dead_zone_spin)
        cl.addSpacing(15)
        cl.addWidget(QtWidgets.QLabel(tr("Smoothing (frames):")))
        self.joy_smoothing_spin = QtWidgets.QSpinBox()
        self.joy_smoothing_spin.setRange(1, 20)
        self.joy_smoothing_spin.setValue(5)
        cl.addWidget(self.joy_smoothing_spin)
        cl.addStretch()
        # Output UDP
        self.joy_udp_check = QtWidgets.QCheckBox(tr("Enviar via UDP (\"joy\" namespace)"))
        self.joy_udp_check.setToolTip(
            tr("Quando ativo, envia {x, y} via UDP no canal de Rede e Eventos.")
        )
        cl.addWidget(self.joy_udp_check)
        outer.addWidget(cfg_group)

        # === Visualização + Plot histórico ===
        split = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
        # Joystick widget
        self.joystick_widget = _VirtualJoystickWidget()
        split.addWidget(self.joystick_widget)
        # Plot X/Y temporal
        right = QtWidgets.QWidget()
        rl = QtWidgets.QVBoxLayout(right); rl.setContentsMargins(2, 2, 2, 2)
        rl.addWidget(QtWidgets.QLabel(tr("X/Y ao longo do tempo (últimos ~30s)")))
        self.joy_plot = pg.PlotWidget(enableMenu=False)
        self.joy_plot.showGrid(x=True, y=True, alpha=0.15)
        self.joy_plot.setLabel("left", tr("Eixo"))
        self.joy_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.joy_plot.setMenuEnabled(False)
        self.joy_plot.addLegend(offset=(10, 10))
        self.joy_plot.setYRange(-1.1, 1.1)
        self.joy_x_curve = self.joy_plot.plot(
            pen=pg.mkPen(SIGNAL_TYPE_COLORS["EMG"], width=1.6), name="X")
        self.joy_y_curve = self.joy_plot.plot(
            pen=pg.mkPen("#66ddff", width=1.6), name="Y")
        rl.addWidget(self.joy_plot)
        split.addWidget(right)
        split.setSizes([300, 700])
        outer.addWidget(split, stretch=1)

        # Estado interno
        self._joy_history = {"t": [], "x": [], "y": []}
        self._joy_smooth = []  # buffer para smoothing
        return widget

    def _joy_repopulate_combos(self):
        """Popula combos de joystick com canais EMG disponíveis."""
        if not hasattr(self, "_joy_axes"): return
        # So' os canais que a placa tem: antes listava CH1..CH64 numa placa
        # de 8, e o canal inexistente so' dava tracado zerado, sem aviso.
        emg_channels = [(ch, f"CH{ch+1} ({self.config.channel_mapping[ch]})")
                        for ch in range(self.num_channels)
                        if ch < len(self.config.channel_signal_types)
                        and self.config.channel_signal_types[ch] == "EMG"]
        # Defaults sugeridos
        defaults = {"+x": 0, "-x": 1, "+y": 2, "-y": 3}
        for code, ax in self._joy_axes.items():
            cb = ax["combo"]
            cb.blockSignals(True)
            cb.clear()
            if not emg_channels:
                cb.addItem(tr("(nenhum canal EMG)"), -1)
            else:
                for ch, label in emg_channels:
                    cb.addItem(label, ch)
                d = defaults.get(code, 0)
                if d < len(emg_channels):
                    cb.setCurrentIndex(d)
            cb.blockSignals(False)

    def _joy_calibrate(self, code):
        """Inicia calibração 3s do canal mapeado para uma direção."""
        if code not in self._joy_axes: return
        ax = self._joy_axes[code]
        ch = ax["combo"].currentData()
        if ch is None or ch < 0:
            QtWidgets.QMessageBox.warning(
                self, tr("Sem canal"), tr("Selecione um canal EMG primeiro.")); return
        ax["calibrating"] = True
        ax["calibration_data"] = []
        ax["calibration_start"] = time.time()
        self._log(f"Calibrando {code}: contraia músculo por 3s...")

    def _update_emg_joystick_view(self):
        """Atualiza joystick: lê envelope dos canais mapeados, normaliza, plota."""
        if not hasattr(self, "_joy_axes"): return
        if not hasattr(self, "emg_rows"):
            return  # depende da aba EMG ter sido construída
        # Lê envelope atual dos canais mapeados (do bar da aba EMG)
        method = self.config.emg_envelope_method
        window_ms = self.config.emg_envelope_window_ms
        data = self._ordered_buffer()
        if data.shape[1] < int(SAMPLE_RATE * 0.1): return
        env_by_ch = {}
        for code, ax in self._joy_axes.items():
            ch = ax["combo"].currentData()
            if ch is None or ch < 0: continue
            if ch in env_by_ch:
                env_val = env_by_ch[ch]
            else:
                env_signal = self._compute_emg_envelope(data[ch], SAMPLE_RATE, method, window_ms)
                env_val = float(env_signal[-1]) if len(env_signal) > 0 else 0.0
                env_by_ch[ch] = env_val
            ax["env_lbl"].setText(f"{env_val:.1f}")
            # Calibração: coleta máximo durante 3s
            if ax["calibrating"]:
                ax["calibration_data"].append(env_val)
                if (time.time() - ax["calibration_start"]) > 3.0:
                    if ax["calibration_data"]:
                        ax["max_value"] = float(np.percentile(ax["calibration_data"], 90))
                        ax["max_lbl"].setText(f"{ax['max_value']:.1f}")
                        self._log(f"{code} calibrado: max={ax['max_value']:.1f} µV")
                    ax["calibrating"] = False
                    ax["calibration_data"] = []
        # Calcula axes [-1, +1]
        def norm_val(code):
            """Converte o envelope EMG do canal de um eixo em fração 0–1 da
            contração máxima calibrada.

            Satura em 1.0 e divide por max(max_value, 1e-6) para não estourar
            quando o eixo ainda não foi calibrado; eixo sem canal atribuído
            devolve 0.0. Lê env_by_ch, já calculado no laço anterior, e não
            recomputa o envelope.
            """
            ax = self._joy_axes[code]
            ch = ax["combo"].currentData()
            if ch is None or ch < 0: return 0.0
            env = env_by_ch.get(ch, 0.0)
            mx = max(ax["max_value"], 1e-6)
            return min(1.0, env / mx)
        pos_x = norm_val("+x"); neg_x = norm_val("-x")
        pos_y = norm_val("+y"); neg_y = norm_val("-y")
        x = pos_x - neg_x
        y = pos_y - neg_y
        # Dead zone
        dz = self.joy_dead_zone_spin.value()
        if abs(x) < dz: x = 0.0
        else: x = (x - dz * np.sign(x)) / (1.0 - dz)
        if abs(y) < dz: y = 0.0
        else: y = (y - dz * np.sign(y)) / (1.0 - dz)
        # Smoothing (moving average)
        sm_n = self.joy_smoothing_spin.value()
        self._joy_smooth.append((x, y))
        if len(self._joy_smooth) > sm_n:
            self._joy_smooth = self._joy_smooth[-sm_n:]
        if self._joy_smooth:
            arr = np.array(self._joy_smooth)
            x_s = float(np.mean(arr[:, 0]))
            y_s = float(np.mean(arr[:, 1]))
        else:
            x_s, y_s = x, y
        # Atualiza widget
        self.joystick_widget.set_axes(x_s, y_s, dz)
        # Histórico
        now = time.time()
        H = self._joy_history
        H["t"].append(now); H["x"].append(x_s); H["y"].append(y_s)
        # Mesma correcao do Focus: 300 pontos a 20 Hz nominais davam 15 s, na
        # pratica de 36 a 40 s, e o titulo promete ~30 s.
        JAN_JOY_S = 30.0
        corte = now - JAN_JOY_S
        k = 0
        while k < len(H["t"]) and H["t"][k] < corte:
            k += 1
        if k:
            for key in ("t", "x", "y"):
                H[key] = H[key][k:]
        if len(H["t"]) > 2000:        # rede de seguranca
            for key in ("t", "x", "y"):
                H[key] = H[key][-2000:]
        t0 = H["t"][0]
        t_rel = [t - t0 for t in H["t"]]
        self.joy_x_curve.setData(t_rel, H["x"])
        self.joy_y_curve.setData(t_rel, H["y"])
        # UDP opcional
        if self.joy_udp_check.isChecked() and getattr(self, "udp", None) and self.udp.enabled:
            try:
                self.udp.send_sample(time.time(), [x_s, y_s])
            except Exception:
                pass

    # ---- Tab: Tempo Real ----
    def _build_realtime_tab(self):
        """Monta a aba Tempo Real: barra de escala/janela, as duas vistas de sinal
        (empilhada e individual) e o gráfico do acelerômetro embaixo.

        Cria curvas para MAX_CHANNELS de uma vez nas duas vistas; a
        visibilidade por canal é ajustada depois, em outro método. A vista
        Individual é um GraphicsLayoutWidget dentro de um QScrollArea com
        altura fixa de 80 px por canal (_channels_per_plot_height), e todos os
        plots têm o eixo X linkado ao plot do canal 1.
        """
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(5, 5, 5, 5); layout.setSpacing(4)

        # --- Barra de controle ---
        ctrl = QtWidgets.QHBoxLayout()
        rt_view_lbl = QtWidgets.QLabel(tr("Visualização:"))
        ctrl.addWidget(rt_view_lbl)
        self.rt_view_combo = QtWidgets.QComboBox()
        self.rt_view_combo.addItems([
            tr("Empilhado (todos visíveis)"),
            tr("Individual (1 plot por canal, rolável)"),
        ])
        self.rt_view_combo.currentIndexChanged.connect(self._on_rt_view_changed)
        ctrl.addWidget(self.rt_view_combo)

        ctrl.addSpacing(16)
        rt_scale_lbl = QtWidgets.QLabel(tr("Escala:"))
        ctrl.addWidget(rt_scale_lbl)
        self.rt_scale_spin = QtWidgets.QDoubleSpinBox()
        self.rt_scale_spin.setRange(2.0, 5000.0)
        self.rt_scale_spin.setValue(100.0)
        self.rt_scale_spin.setDecimals(0)
        self.rt_scale_spin.setSingleStep(10.0)
        self.rt_scale_spin.setSuffix(tr(" µV/canal"))
        self.rt_scale_spin.setToolTip(tr("Quantos µV ocupam o espaço de 1 canal. "
                                       "Menor = ondas maiores."))
        ctrl.addWidget(self.rt_scale_spin)
        rt_scale_btns = []
        for label, val in (("50", 50), ("100", 100), ("200", 200), ("500", 500)):
            b = QtWidgets.QPushButton(label)
            b.setMinimumWidth(46)
            b.setToolTip(tr("Escala {0} µV/canal").format(val))
            b.clicked.connect(lambda _ck, v=val: self.rt_scale_spin.setValue(v))
            ctrl.addWidget(b)
            rt_scale_btns.append(b)
        b_auto = QtWidgets.QPushButton(tr("Auto"))
        b_auto.setMinimumWidth(60)
        b_auto.setToolTip(tr("Ajusta a escala automaticamente ao sinal atual"))
        b_auto.clicked.connect(self._rt_autoscale)
        ctrl.addWidget(b_auto)

        ctrl.addSpacing(16)
        rt_window_lbl = QtWidgets.QLabel(tr("Janela:"))
        ctrl.addWidget(rt_window_lbl)
        self.rt_window_spin = QtWidgets.QSpinBox()
        self.rt_window_spin.setRange(1, BUFFER_SECONDS)
        self.rt_window_spin.setValue(5)
        self.rt_window_spin.setSuffix(" s")
        # Vale para as duas vistas desde a correção do achado 16.
        self.rt_window_spin.setToolTip(
            tr("Quantos segundos de sinal aparecem no traçado."))
        ctrl.addWidget(self.rt_window_spin)
        ctrl.addStretch()
        layout.addLayout(ctrl)
        # Simples: só o traçado e o botão Auto
        self._register_advanced("ui", rt_view_lbl, self.rt_view_combo,
                                rt_scale_lbl, self.rt_scale_spin, *rt_scale_btns,
                                rt_window_lbl, self.rt_window_spin)

        splitter = QtWidgets.QSplitter(QtCore.Qt.Orientation.Vertical)
        splitter.setHandleWidth(4)

        # Stack: 0 = Empilhado (montagem clínica), 1 = Individual (rolável)
        self.rt_view_stack = QtWidgets.QStackedWidget()

        # ===== VIEW 0: EMPILHADO (single plot, offset vertical) =====
        self.montage_plot = pg.PlotWidget(enableMenu=False)
        self.montage_plot.showGrid(x=True, y=False, alpha=0.12)
        self.montage_plot.setMenuEnabled(False)
        self.montage_plot.setMouseEnabled(x=False, y=False)
        self.montage_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.montage_plot.getAxis("left").setWidth(70)
        self.montage_plot.hideButtons()
        self.montage_curves = []
        for ch in range(MAX_CHANNELS):
            cur = self.montage_plot.plot(
                pen=pg.mkPen(CHANNEL_COLORS[ch], width=1.1))
            # como no Individual: sinal maior que a escala custava 21 ms por
            # desenho e deixava a simulacao sem tempo de processador
            cur.setDownsampling(auto=True, method="peak")
            cur.setClipToView(True)
            self.montage_curves.append(cur)
        self.montage_marker_lines = []
        self.rt_view_stack.addWidget(self.montage_plot)

        # ===== VIEW 1: INDIVIDUAL (scrollable) =====
        self.channels_scroll = QtWidgets.QScrollArea()
        self.channels_scroll.setWidgetResizable(True)
        self.channels_scroll.setHorizontalScrollBarPolicy(
            QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.channels_scroll.setVerticalScrollBarPolicy(
            QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.channels_layout = pg.GraphicsLayoutWidget()
        try:
            self.channels_layout.ci.layout.setVerticalSpacing(6)
        except Exception: pass
        self._channels_per_plot_height = 80
        self.channels_layout.setMinimumHeight(
            BASE_CHANNELS * self._channels_per_plot_height)
        self.channels_scroll.setWidget(self.channels_layout)

        self.channel_plots  = []
        self.channel_curves = []
        self.channel_marker_lines = [[] for _ in range(MAX_CHANNELS)]
        for ch in range(MAX_CHANNELS):
            plot = self.channels_layout.addPlot(row=ch, col=0, enableMenu=False)
            plot.showGrid(x=True, y=True, alpha=0.15)
            plot.setLabel("left", f"CH{ch + 1}", units="uV", color=CHANNEL_COLORS[ch])
            left_axis = plot.getAxis("left")
            left_axis.setTextPen(CHANNEL_COLORS[ch])
            left_axis.setWidth(84)
            plot.setMouseEnabled(x=False, y=True)
            plot.setMenuEnabled(False)
            plot.enableAutoRange(axis="y", enable=True)
            plot.setAutoVisible(y=True)
            plot.setMinimumHeight(self._channels_per_plot_height - 4)
            if ch > 0:
                plot.setXLink(self.channel_plots[0])
            plot.setLabel("bottom", tr("Tempo"), units="s")
            plot.getAxis("bottom").setHeight(22)
            curve = plot.plot(pen=pg.mkPen(CHANNEL_COLORS[ch], width=1.2))
            curve.setDownsampling(auto=True, method="peak")  # menos CPU sem perda visual
            curve.setClipToView(True)
            self.channel_plots.append(plot)
            self.channel_curves.append(curve)
        self.rt_view_stack.addWidget(self.channels_scroll)

        self.rt_view_stack.setCurrentIndex(0)  # default: Empilhado
        splitter.addWidget(self.rt_view_stack)

        # Acelerômetro
        accel_widget = QtWidgets.QWidget()
        al = QtWidgets.QVBoxLayout(accel_widget)
        al.setContentsMargins(5, 5, 5, 5)
        accel_colors = ["#ff5555", "#55ff55", "#5599ff"]
        # Legenda FORA do gráfico, ao lado do título: dentro dos ~40 px úteis
        # ela ficava cortada (1600) ou sumia (1366).
        accel_title = QtWidgets.QLabel(
            tr("Acelerômetro (g — eixos X / Y / Z)") + "&nbsp;&nbsp;" + "&nbsp;".join(
                f"<span style='color:{c}'>■</span>&nbsp;{e}"
                for c, e in zip(accel_colors, ("X", "Y", "Z"))))
        accel_title.setTextFormat(QtCore.Qt.TextFormat.RichText)
        accel_title.setStyleSheet(f"color: {COLORS['text_dim']}; padding: 2px 8px;")
        al.addWidget(accel_title)
        self.accel_plot = pg.PlotWidget(enableMenu=False)
        self.accel_plot.showGrid(x=True, y=True, alpha=0.15)
        self.accel_plot.setLabel("left", "g")
        self.accel_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.accel_plot.setMenuEnabled(False)
        # marcas de 1 em 1 g: com o Z em 1 g (gravidade) as três marcas de
        # 0,5 g saíam umas por cima das outras em ~35 px
        self.accel_plot.getAxis("left").setTickSpacing(major=1.0, minor=1.0)
        self.accel_curves = []
        for i, axis in enumerate(("X", "Y", "Z")):
            curve = self.accel_plot.plot(pen=pg.mkPen(accel_colors[i], width=1.4), name=axis)
            curve.setDownsampling(auto=True, method="peak")
            curve.setClipToView(True)
            self.accel_curves.append(curve)
        al.addWidget(self.accel_plot, 1)
        splitter.addWidget(accel_widget)
        self._register_advanced("ui", accel_widget)   # rodapé some no Simples
        splitter.setSizes([760, 180])
        layout.addWidget(splitter)
        return widget

    def _on_rt_view_changed(self, idx):
        """Troca a vista de Tempo Real entre empilhada e individual conforme o
        combo de visualização.

        Ao voltar para a vista empilhada chama _refresh_montage_layout(), que
        reconstrói os offsets verticais e as linhas de marker acumuladas
        enquanto ela estava oculta.
        """
        self.rt_view_stack.setCurrentIndex(idx)
        # Limpa linhas de marker do modo montagem ao trocar
        if idx == 0 and hasattr(self, "montage_plot"):
            self._refresh_montage_layout()

    def _rt_autoscale(self):
        """Ajusta a escala (µV/canal) com base no desvio padrão atual."""
        data = self._ordered_buffer()
        if data.shape[1] < 10:
            return
        vis = [ch for ch in range(MAX_CHANNELS)
               if ch < self.num_channels and self.channel_active[ch]]
        if not vis:
            return
        # 4x o maior desvio padrão entre canais visíveis
        sd = max(float(np.std(data[ch])) for ch in vis)
        scale = max(10.0, min(5000.0, sd * 4.0))
        self.rt_scale_spin.setValue(round(scale))

    def _refresh_montage_layout(self):
        """Recalcula os ticks do eixo Y (nomes de canais) do modo Empilhado."""
        if not hasattr(self, "montage_plot"):
            return
        vis = [ch for ch in range(MAX_CHANNELS)
               if ch < self.num_channels and self.channel_active[ch]]
        n_vis = len(vis)
        ticks, linhas = [], []
        for k, ch in enumerate(vis):
            baseline = (n_vis - 1 - k)
            name = (self.config.channel_mapping[ch]
                    if ch < len(self.config.channel_mapping) else f"CH{ch+1}")
            # pelo tipo do canal: "CH2 Bíceps Braquial", "CH6 ECG" (o nome
            # 10-20 chamava o canal de músculo de eletrodo do cérebro; G13)
            tipos = getattr(self.config, "channel_signal_types", None) or []
            musc = getattr(self.config, "emg_channel_muscle", None) or []
            name = nome_canal_por_tipo(
                ch, name, tipos[ch] if ch < len(tipos) else "EEG",
                musc[ch] if ch < len(musc) else "", self._nivel_simples())
            ticks.append((baseline, self._pdf_rotulo_curto(f"CH{ch+1} {name}", 22)))
            # dica: onde fica cada eletrodo (só faz sentido em canal de EEG)
            desc = (descricao_posicao_10_20(name)
                    if (tipos[ch] if ch < len(tipos) else "EEG") == "EEG" else "")
            linhas.append(f"CH{ch+1} {name}" + (f" — {desc}" if desc else ""))
        ax = self.montage_plot.getAxis("left")
        # no Simples os nomes saem maiores: a 9 px "CH1 Fp1" não se lia (G37)
        try:
            simples = self._nivel_simples()
            ax.setStyle(tickFont=QtGui.QFont(FONT_UI if simples else FONT_DATA,
                                             _pt(11 if simples else 9)))
        except Exception:
            pass
        self.montage_plot.setToolTip(
            (tr("Onde fica cada eletrodo:") + "\n" + "\n".join(linhas)) if linhas else "")
        ax.setTicks([ticks])
        # largura do eixo pelo nome mais longo: com os 70 px fixos "CH1
        # músculo" não cabia e o pyqtgraph escondia todos os nomes (G13)
        try:
            fonte = ax.style.get("tickFont") or QtWidgets.QApplication.font()
            fm = QtGui.QFontMetrics(fonte)
            maior = max([fm.horizontalAdvance(lab) for _b, lab in ticks] or [0])
            base = int(round(70 * max(1.0, UI_FONT_SCALE)))
            ax.setWidth(min(220, max(base, maior + 16)))
        except Exception:
            pass
        self.montage_plot.setYRange(-0.6, max(0.6, n_vis - 0.4), padding=0)

    # ---- Tab: Análises ----
    def _build_analysis_tab(self):
        """Monta a aba Análise: espectro FFT e barras de potência por banda do
        canal escolhido, mais a tabela de estatísticas de todos os canais.

        A tabela é dimensionada para caber sem rolagem — linhas de 22 px e as
        duas barras de rolagem desligadas explicitamente. Aumentar MAX_CHANNELS
        passa a esconder linhas em vez de gerar scroll. As linhas tracejadas no
        gráfico de FFT marcam o limite inferior de cada banda de EEG_BANDS.
        """
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(10, 10, 10, 10); layout.setSpacing(10)

        sel_row = QtWidgets.QHBoxLayout()
        sel_row.addWidget(QtWidgets.QLabel(tr("Canal para FFT/Banda:")))
        self.analysis_channel = QtWidgets.QComboBox()
        for i in range(MAX_CHANNELS):
            self.analysis_channel.addItem(f"CH{i + 1}")
        self.analysis_channel.setMinimumWidth(120)
        sel_row.addWidget(self.analysis_channel); sel_row.addStretch()
        layout.addLayout(sel_row)

        graph_row = QtWidgets.QHBoxLayout()
        fft_group = QtWidgets.QGroupBox(tr("Espectro de Frequência (FFT)"))
        fft_layout = QtWidgets.QVBoxLayout(fft_group)
        self.fft_plot = pg.PlotWidget(enableMenu=False)
        self.fft_plot.showGrid(x=True, y=True, alpha=0.15)
        self.fft_plot.setLabel("left", tr("Amplitude"), units="uV")
        self.fft_plot.setLabel("bottom", tr("Frequência"), units="Hz")
        self.fft_plot.setXRange(0, 60); self.fft_plot.setMenuEnabled(False)
        self.fft_curve = self.fft_plot.plot(pen=pg.mkPen(COLORS["accent"], width=1.4))
        for _, (low, _h) in EEG_BANDS.items():
            line = pg.InfiniteLine(pos=low, angle=90,
                pen=pg.mkPen(COLORS["border"], style=QtCore.Qt.PenStyle.DashLine))
            self.fft_plot.addItem(line)
        fft_layout.addWidget(self.fft_plot)
        graph_row.addWidget(fft_group)

        band_group = QtWidgets.QGroupBox(tr("Bandas de Potência EEG"))
        band_layout = QtWidgets.QVBoxLayout(band_group)
        self.band_plot = pg.PlotWidget(enableMenu=False)
        self.band_plot.showGrid(x=False, y=True, alpha=0.15)
        # µV²: potência integrada na faixa, não densidade. Rotular µV²/Hz fazia
        # o número parecer independente da largura da banda — não é: no ruído
        # branco ele cresce ~proporcional a (high-low).
        self.band_plot.setLabel("left", tr("Potência"), units="µV²")
        self.band_plot.setMenuEnabled(False)
        self.band_plot.getAxis("bottom").setTicks([list(enumerate(EEG_BANDS.keys()))])
        self.band_bars = pg.BarGraphItem(
            x=list(range(len(EEG_BANDS))),
            height=[0.0] * len(EEG_BANDS), width=0.6,
            brushes=self._band_brushes(), pen=pg.mkPen(COLORS["border"]),
        )
        self.band_plot.addItem(self.band_bars)
        self.band_plot.setXRange(-0.5, len(EEG_BANDS) - 0.5)
        band_layout.addWidget(self.band_plot)
        graph_row.addWidget(band_group)
        layout.addLayout(graph_row, stretch=2)

        # Tabela de estatísticas — todos os canais (compacta, 16 linhas visíveis sem scroll)
        stats_group = QtWidgets.QGroupBox(tr("Estatísticas — Todos os Canais"))
        stats_layout = QtWidgets.QVBoxLayout(stats_group)
        stats_layout.setContentsMargins(8, 4, 8, 4)
        self.stats_table = QtWidgets.QTableWidget(MAX_CHANNELS, 4)
        self.stats_table.setHorizontalHeaderLabels([tr("Canal"), tr("Média (µV)"), tr("Desvio Padrão (µV)"), tr("RMS (µV)")])
        self.stats_table.verticalHeader().setVisible(False)
        self.stats_table.horizontalHeader().setSectionResizeMode(
            QtWidgets.QHeaderView.ResizeMode.Stretch)
        self.stats_table.setAlternatingRowColors(True)
        self.stats_table.setEditTriggers(QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        # Compacta: ~22px por linha -> 16 linhas + header cabem em ~380px
        STATS_ROW_H = 22
        self.stats_table.verticalHeader().setDefaultSectionSize(STATS_ROW_H)
        self.stats_table.horizontalHeader().setFixedHeight(26)
        self.stats_table.setHorizontalScrollBarPolicy(
            QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.stats_table.setVerticalScrollBarPolicy(
            QtCore.Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        for ch in range(MAX_CHANNELS):
            name_item = QtWidgets.QTableWidgetItem(f"CH{ch + 1}")
            name_item.setForeground(QtGui.QColor(CHANNEL_COLORS[ch]))
            name_item.setFont(QtGui.QFont(FONT_DATA, 10, QtGui.QFont.Weight.Bold))
            self.stats_table.setItem(ch, 0, name_item)
            for col in range(1, 4):
                it = QtWidgets.QTableWidgetItem("--")
                it.setTextAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
                self.stats_table.setItem(ch, col, it)
        stats_layout.addWidget(self.stats_table)
        layout.addWidget(stats_group, stretch=1)
        return widget

    # ---- Tab: Topografia ----
    def _build_topology_tab(self):
        """Monta a aba Topografia com as três vistas de head plot (2D IDW, 3D domo
        e tomografia) ao lado dos medidores de Focus e EMG.

        As três vistas ficam em self._topo_views e são alimentadas pelos
        métodos _topo_broadcast_*. O slider de profundidade afeta só a vista de
        tomografia (0% = escalpo, 100% = camada profunda), e o combo Mapa
        alterna interp/CSD apenas na vista 2D.
        """
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(10, 10, 10, 10); layout.setSpacing(10)

        ctrl_row = QtWidgets.QHBoxLayout()
        ctrl_row.addWidget(QtWidgets.QLabel(tr("Banda no Head Plot:")))
        self.topo_band_combo = QtWidgets.QComboBox()
        self.topo_band_combo.addItems(list(EEG_BANDS.keys()))
        self.topo_band_combo.setCurrentText("Alpha")
        ctrl_row.addWidget(self.topo_band_combo)
        ctrl_row.addSpacing(16)
        ctrl_row.addWidget(QtWidgets.QLabel(tr("Mapa:")))
        self.topo_mode_combo = QtWidgets.QComboBox()
        self.topo_mode_combo.addItems([tr("Interpolado (potencial)"),
                                       tr("CSD / Laplaciano (fonte)")])
        # O combo só age na vista 2D; o domo e a tomografia dizem POTÊNCIA
        # no título, e a dica avisa (antes nada dizia).
        self.topo_mode_combo.setToolTip(
            tr("Interpolado = potência de escalpo (spline esférica).\n"
               "CSD/Laplaciano = realça fontes locais e reduz condução de volume\n"
               "(McFarland 1997; Nunez & Srinivasan 2006).\n"
               "Vale só para a vista 2D: 3D e Tomografia mostram sempre a potência.")
            + "\n" + tr("Fora dos eletrodos o valor é interpolado, não medido: "
                         "longe de qualquer eletrodo a cor esmaece."))
        self.topo_mode_combo.currentTextChanged.connect(
            lambda t: self.head_plot.set_map_mode("csd" if "CSD" in t else "interp"))
        ctrl_row.addWidget(self.topo_mode_combo)
        ctrl_row.addStretch()
        ctrl_row.addWidget(QtWidgets.QLabel(tr("Canal para Focus:")))
        self.topo_channel_combo = QtWidgets.QComboBox()
        for i in range(MAX_CHANNELS):
            self.topo_channel_combo.addItem(f"CH{i+1}")
        ctrl_row.addWidget(self.topo_channel_combo)
        layout.addLayout(ctrl_row)

        main_split = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
        head_group = QtWidgets.QGroupBox(tr("Head Plot — Potência por Eletrodo (10-20)"))
        hl = QtWidgets.QVBoxLayout(head_group)
        # Três vistas: 2D, 3D (domo pseudo-3D) e Tomografia (isopotenciais)
        self.head_plot = HeadPlotWidget()
        # A classe baixou o mínimo para caber no painel do Layout Custom; aqui,
        # onde a aba é só da topografia, ele volta ao tamanho generoso e igual
        # ao das outras duas vistas (senão a aba muda de altura ao trocar).
        # 300 px de altura (não 420): a 1366x768 o quadro passava da área
        # visível e a barra com os números só aparecia rolando. Em quadro
        # baixo as três vistas põem a barra em pé, ao lado da cabeça.
        self.head_plot.setMinimumSize(360, 300)
        self.head_plot_3d = HeadPlotWidget3D()
        self.head_plot_3d.setMinimumSize(360, 300)
        self.head_plot_ct = HeadPlotWidgetCT()
        self.head_plot_ct.setMinimumSize(360, 270)
        self.head_plot_ct.mostra_rodape = False    # o rótulo do controle diz
        self._topo_views = [self.head_plot, self.head_plot_3d, self.head_plot_ct]
        self.head_plot_tabs = QtWidgets.QTabWidget()
        self.head_plot_tabs.addTab(self.head_plot, tr("2D (spline)"))
        self.head_plot_tabs.addTab(self.head_plot_3d, tr("3D (domo)"))
        # Tomografia + slider de profundidade
        ct_container = QtWidgets.QWidget()
        ct_l = QtWidgets.QVBoxLayout(ct_container)
        # Margem nas laterais: o rótulo encostava na borda do quadro.
        ct_l.setContentsMargins(8, 0, 8, 6); ct_l.setSpacing(4)
        ct_l.addWidget(self.head_plot_ct, stretch=1)
        depth_row = QtWidgets.QHBoxLayout()
        # Um rótulo só, com o valor (o desenho repetia "Profundidade da
        # camada: 0%" logo acima dele).
        self._topo_ct_rotulo = QtWidgets.QLabel()
        depth_row.addWidget(self._topo_ct_rotulo)
        self.topo_ct_depth = QtWidgets.QSlider(QtCore.Qt.Orientation.Horizontal)
        self.topo_ct_depth.setMinimum(0); self.topo_ct_depth.setMaximum(100)
        self.topo_ct_depth.setValue(0)
        self.topo_ct_depth.setToolTip(
            tr("Fatia camadas internas do modelo de condução de volume "
            "(0% = escalpo · 100% = camada profunda)."))
        self.topo_ct_depth.valueChanged.connect(self.head_plot_ct.set_slice_depth)
        self.topo_ct_depth.valueChanged.connect(self._topo_ct_rotulo_atualiza)
        self._topo_ct_rotulo_atualiza(0)
        depth_row.addWidget(self.topo_ct_depth, stretch=1)
        ct_l.addLayout(depth_row)
        self.head_plot_tabs.addTab(ct_container, tr("Tomografia"))
        self.head_plot_tabs.currentChanged.connect(self._topo_on_tab_changed)
        hl.addWidget(self.head_plot_tabs)
        # Em rolagem, como a do Offline: a 1366x768 a cabeça (mínimo de 420
        # px) passava 34 px da tela e levava O1/O2 e a barra de cor junto.
        head_scroll = QtWidgets.QScrollArea()
        head_scroll.setWidgetResizable(True)
        head_scroll.setFrameShape(QtWidgets.QFrame.Shape.NoFrame)
        head_scroll.setWidget(head_group)
        main_split.addWidget(head_scroll)

        side = QtWidgets.QSplitter(QtCore.Qt.Orientation.Vertical)
        focus_group = QtWidgets.QGroupBox(tr("Focus"))
        fl = QtWidgets.QVBoxLayout(focus_group)
        self.focus_meter = FocusMeterWidget()
        fl.addWidget(self.focus_meter)
        side.addWidget(focus_group)
        emg_group = QtWidgets.QGroupBox(tr("EMG"))
        el = QtWidgets.QVBoxLayout(emg_group)
        self.emg_widget = EMGEnvelopeWidget()
        el.addWidget(self.emg_widget)
        side.addWidget(emg_group)
        side.setSizes([300, 400])
        self._topo_lado = side          # esmaecido ao desconectar
        main_split.addWidget(side)
        main_split.setSizes([800, 600])
        layout.addWidget(main_split)
        return widget

    def _topo_ct_rotulo_atualiza(self, valor):
        """Rótulo do controle de profundidade da tomografia, com o valor."""
        lbl = getattr(self, "_topo_ct_rotulo", None)
        if lbl is not None:
            lbl.setText(tr("Profundidade da camada: {0:.0f}%  ·  {1} isopotenciais").format(
                float(valor), HeadPlotWidgetCT.LEVELS))

    # ---- Topografia: broadcast p/ as 3 vistas (2D/3D/CT) ----
    def _topo_broadcast_powers(self, powers, band_name):
        """Distribui as potências por eletrodo às três vistas de topografia e
        guarda a última leitura recebida.

        A cópia em self._topo_last_powers é o que _topo_on_tab_changed
        reaproveita quando uma vista oculta volta a aparecer. A variável local
        cur é calculada e nunca usada: hoje todas as vistas recebem set_powers,
        visíveis ou não.
        """
        self._topo_last_powers = (list(powers), band_name)
        cur = (self.head_plot_tabs.currentWidget()
               if hasattr(self, "head_plot_tabs") else None)
        for v in getattr(self, "_topo_views", [self.head_plot]):
            # atualiza a vista visível sempre; as ocultas recomputam leve (sem repaint)
            v.set_powers(powers, band_name)

    def _topo_broadcast_mapping(self, mapping):
        """Repassa o mapeamento canal→eletrodo 10-20 para as três vistas de
        topografia."""
        for v in getattr(self, "_topo_views", [getattr(self, "head_plot", None)]):
            if v is not None:
                v.set_mapping(mapping)

    def _topo_broadcast_nchan(self, n):
        """Informa às três vistas de topografia quantos canais estão ativos."""
        for v in getattr(self, "_topo_views", [getattr(self, "head_plot", None)]):
            if v is not None:
                v.set_num_channels(n)

    def _topo_on_tab_changed(self, _idx):
        # empurra os últimos dados p/ a vista recém-exibida (estava oculta)
        """Reenvia a última leitura de potências à vista de topografia que acabou
        de ficar visível.

        O teste com isAncestorOf é necessário porque a aba Tomografia é um
        container (head plot + slider de profundidade), não o widget de head
        plot em si.
        """
        last = getattr(self, "_topo_last_powers", None)
        if last:
            powers, band = last
            w = self.head_plot_tabs.currentWidget()
            for v in getattr(self, "_topo_views", []):
                if v is w or (hasattr(w, "isAncestorOf") and w.isAncestorOf(v)):
                    v.set_powers(powers, band)

    # ---- Tab: Espectrograma ----
    def _build_spectrogram_tab(self):
        """Monta a aba Espectrograma: seletor de canal e a imagem tempo×frequência
        com colormap escuro-para-claro.

        Cada quadro vale 0,25 s, então a janela mostrada é SPEC_FRAMES × 0,25 s
        e o eixo Y vai até SPEC_FMAX. Os níveis da ImageItem NÃO são mais fixos:
        eram [-80, 0] dB, faixa onde a PSD deste app nunca cai — um EEG comum de
        20 µV rms dá colunas inteiras entre +1 e +18 dB, isto é, 100% dos bins
        acima do teto e a tela toda numa cor só. Agora _update_spectrogram
        reescala por percentil a cada quadro e a ColorBarItem ao lado diz a que
        dB cada cor corresponde.
        """
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(10, 10, 10, 10)
        sel_row = QtWidgets.QHBoxLayout()
        sel_row.addWidget(QtWidgets.QLabel(tr("Canal:")))
        self.spec_channel = QtWidgets.QComboBox()
        for i in range(MAX_CHANNELS):
            self.spec_channel.addItem(f"CH{i + 1}")
        self.spec_channel.setMinimumWidth(120)
        sel_row.addWidget(self.spec_channel); sel_row.addStretch()
        # "dB normalizado" era rótulo falso: nada normalizava nada. E anunciar
        # uma "janela" só de tela escondia que cada coluna analisa SPEC_WINDOW_S
        # de sinal — os dois números precisam aparecer separados.
        sel_row.addWidget(QtWidgets.QLabel(
            tr("Tela: {0:.0f}s   Análise: {1:.0f}s/coluna   Freq: 0–{2} Hz   dB (auto "
               "p2–p98)").format(SPEC_FRAMES * 0.25, SPEC_WINDOW_S, SPEC_FMAX)))
        layout.addLayout(sel_row)
        self.spec_widget = pg.PlotWidget(enableMenu=False)
        self.spec_widget.setLabel("left", tr("Frequência"), units="Hz")
        self.spec_widget.setLabel("bottom", tr("Tempo"), units="s")
        self.spec_widget.setMenuEnabled(False)
        self.spec_image = pg.ImageItem()
        stops = np.array([0.0, 0.25, 0.5, 0.75, 1.0])
        colors_m = np.array([
            [0,   0,   0,   255],
            [80,  10,  80,  255],
            [160, 30,  60,  255],
            [255, 130, 30,  255],
            [255, 255, 180, 255],
        ], dtype=np.ubyte)
        cmap = pg.ColorMap(stops, colors_m)
        self.spec_image.setLookupTable(cmap.getLookupTable(0.0, 1.0, 256))
        # [-80, 0] dB é escala relativa (dBFS) aplicada a uma PSD absoluta em
        # µV²/Hz: com ruído de 20 µV rms a coluna sai de +1 a +18 dB, ou seja
        # 100% dos bins estouram o teto e a LUT de 256 cores rende 1 cor só.
        # Estes valores agora são apenas o estado inicial — _update_spectrogram
        # recalcula os níveis por percentil a cada 250 ms.
        self.spec_image.setLevels([0.0, 20.0])
        self.spec_widget.addItem(self.spec_image)
        # Escala automática sem barra de cor é número sem unidade: o mesmo tom
        # passaria a significar dB diferentes conforme o sinal. interactive=False
        # porque o timer reescreve os níveis 4x/s e arrastar não sobreviveria.
        self.spec_colorbar = None
        try:
            self.spec_colorbar = pg.ColorBarItem(
                values=(0.0, 20.0), colorMap=cmap, label="dB", interactive=False)
            self.spec_colorbar.setImageItem(
                self.spec_image, insert_in=self.spec_widget.getPlotItem())
        except Exception:
            self.spec_colorbar = None    # pyqtgraph sem ColorBarItem: segue sem barra
        self.spec_widget.setYRange(0, SPEC_FMAX)
        self.spec_widget.setXRange(0, SPEC_FRAMES * 0.25)
        layout.addWidget(self.spec_widget)
        return widget

    # ---- Tab: Filtros & Canais ----
    def _build_filters_tab(self):
        """Monta a aba Filtros & Canais: re-referenciação, notch, bandpass com
        presets, a grade de tipo/ativação por canal, a detecção de canais ruins
        e o seletor de modo do exame.

        A grade de canais é dividida em dois blocos de 8 linhas lado a lado
        (CH1-8 | CH9-16) justamente para caber sem rolagem. O spinbox de
        threshold EMG de cada linha só fica habilitado se o tipo do canal for
        EMG. O combo de modo aplica na hora, via currentIndexChanged —
        comentário no código registra que o antigo botão 'Aplicar modo' fazia o
        ajuste parecer quebrado.
        """
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(15, 15, 15, 15); layout.setSpacing(12)

        # ============================================================
        # Re-referenciação (CAR / Laplacian / Mastoide / Bipolar / REST)
        # ============================================================
        reref_group = QtWidgets.QGroupBox(tr("Re-referenciação (aplicada ANTES dos filtros)"))
        reref_l = QtWidgets.QHBoxLayout(reref_group)
        reref_l.addWidget(QtWidgets.QLabel(tr("Esquema:")))
        self.reref_combo = QtWidgets.QComboBox()
        # (label visível, código interno)
        self.reref_combo.addItem(tr("Nenhuma (sinal original)"),            "none")
        self.reref_combo.addItem(tr("CAR — Common Average Reference"),      "car")
        self.reref_combo.addItem(tr("Mastoide — média de canais ref. (M1+M2)/2"),
                                  "mastoid")
        self.reref_combo.addItem(tr("Laplaciano de Superfície (4 vizinhos)"),
                                  "laplacian")
        self.reref_combo.addItem(tr("Bipolar (ch_i − ch_i+1)"),             "bipolar")
        self.reref_combo.addItem(tr("REST (canais distantes — aprox.)"),    "rest")
        self.reref_combo.setToolTip(
            tr("Esquema de re-referência aplicado em tempo real:\n"
            "  CAR        : média de TODOS os canais subtraída (padrão para 32+ ch)\n"
            "  Mastoide   : usa eletrodos M1/M2 como referência clínica\n"
            "  Laplaciano : sinal de cada canal menos média dos 4 vizinhos\n"
            "  Bipolar    : útil para EMG (diferença entre eletrodos do par)\n"
            "  REST       : aproximação ZERO reference (Yao 2001)")
        )
        self.reref_combo.currentIndexChanged.connect(self._on_reref_changed)
        reref_l.addWidget(self.reref_combo, stretch=1)
        # Campo de canais de referência (para Mastoid)
        reref_l.addWidget(QtWidgets.QLabel(tr("Canais ref. (1-based, vírgula):")))
        self.reref_channels_edit = QtWidgets.QLineEdit()
        self.reref_channels_edit.setPlaceholderText("Ex.: 13,14 (TP9, TP10)")
        self.reref_channels_edit.setMaximumWidth(160)
        self.reref_channels_edit.editingFinished.connect(self._on_reref_changed)
        reref_l.addWidget(self.reref_channels_edit)
        layout.addWidget(reref_group)

        notch_group = QtWidgets.QGroupBox(tr("Filtro Notch (rejeição de banda)"))
        nl = QtWidgets.QHBoxLayout(notch_group)
        self.notch_enable = QtWidgets.QCheckBox(tr("Ativado"))
        self.notch_enable.toggled.connect(self._on_filter_change)
        nl.addWidget(self.notch_enable); nl.addSpacing(20)
        nl.addWidget(QtWidgets.QLabel(tr("Frequência (Hz):")))
        self.notch_freq = QtWidgets.QComboBox()
        self.notch_freq.addItems(["50", "60"]); self.notch_freq.setCurrentText("60")
        self.notch_freq.currentTextChanged.connect(self._on_filter_change)
        nl.addWidget(self.notch_freq); nl.addStretch()
        nl.addWidget(QtWidgets.QLabel(tr("(Q=30 — remove ruido de rede elétrica)")))
        layout.addWidget(notch_group)

        bp_group = QtWidgets.QGroupBox(tr("Filtro Bandpass (Butterworth, ordem 4)"))
        bp_outer = QtWidgets.QVBoxLayout(bp_group)
        bl = QtWidgets.QHBoxLayout()
        self.bp_enable = QtWidgets.QCheckBox(tr("Ativado"))
        self.bp_enable.toggled.connect(self._on_filter_change)
        bl.addWidget(self.bp_enable); bl.addSpacing(20)
        bl.addWidget(QtWidgets.QLabel(tr("Corte inferior (Hz):")))
        self.bp_low = QtWidgets.QDoubleSpinBox()
        self.bp_low.setRange(0.1, 100.0); self.bp_low.setDecimals(1); self.bp_low.setSingleStep(0.5)
        self.bp_low.setValue(1.0)
        self.bp_low.valueChanged.connect(self._on_filter_change)
        bl.addWidget(self.bp_low); bl.addSpacing(15)
        bl.addWidget(QtWidgets.QLabel(tr("Corte superior (Hz):")))
        self.bp_high = QtWidgets.QDoubleSpinBox()
        self.bp_high.setRange(0.5, 120.0); self.bp_high.setDecimals(1); self.bp_high.setSingleStep(0.5)
        self.bp_high.setValue(50.0)
        self.bp_high.valueChanged.connect(self._on_filter_change)
        bl.addWidget(self.bp_high); bl.addStretch()
        bp_outer.addLayout(bl)
        presets = QtWidgets.QHBoxLayout()
        presets.addWidget(QtWidgets.QLabel(tr("Presets:")))
        for name, low, high in ((tr("Largo 1-50"), 1, 50), (tr("Mu 8-13"), 8, 13),
                                 (tr("Beta 13-30"), 13, 30), (tr("Gamma 30-50"), 30, 50)):
            btn = QtWidgets.QPushButton(name)
            btn.clicked.connect(lambda _ck, l=low, h=high: self._apply_bp_preset(l, h))
            presets.addWidget(btn)
        presets.addStretch()
        bp_outer.addLayout(presets)
        layout.addWidget(bp_group)

        # Configuração por canal: ativo + tipo de sinal (multimodal)
        ch_group = QtWidgets.QGroupBox(tr("Canais — Ativação e Tipo de Sinal (multimodal: EEG / EMG / ECG / EoG)"))
        cl_outer = QtWidgets.QVBoxLayout(ch_group)
        # Botões rápidos para presets
        preset_row = QtWidgets.QHBoxLayout()
        preset_row.addWidget(QtWidgets.QLabel(tr("Presets:")))
        for label, setter in (
            (tr("Todos EEG"),  lambda: self._apply_signal_type_to_all("EEG")),
            (tr("Todos EMG"),  lambda: self._apply_signal_type_to_all("EMG")),
            (tr("Todos ECG"),  lambda: self._apply_signal_type_to_all("ECG")),
            (tr("Todos EoG"),  lambda: self._apply_signal_type_to_all("EoG")),
            (tr("1-8 EEG / 9-16 EMG"), lambda: self._apply_signal_type_split(8, "EEG", "EMG")),
        ):
            b = QtWidgets.QPushButton(label)
            b.clicked.connect(setter)
            preset_row.addWidget(b)
        preset_row.addStretch()
        cl_outer.addLayout(preset_row)

        cl = QtWidgets.QGridLayout()
        cl.setHorizontalSpacing(6); cl.setVerticalSpacing(2)
        # Cabeçalhos: um bloco de 8 canais por coluna (CH1-8 | CH9-16 | ...).
        # Os blocos sem canal em uso somem em
        # _sync_multimodal_tabs_with_channels, senao a grade pede 2766 px.
        self.channel_hdrs = []
        for block in range((MAX_CHANNELS + 7) // 8):
            base_col = block * 5
            hdrs = [tr("Ativo"), tr("Canal"), tr("Tipo"), tr("Filtro recomendado"), tr("Threshold EMG")]
            hdrs_bloco = []
            for i, h in enumerate(hdrs):
                lbl = QtWidgets.QLabel(h)
                lbl.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold;")
                cl.addWidget(lbl, 0, base_col + i)
                hdrs_bloco.append(lbl)
            self.channel_hdrs.append(hdrs_bloco)

        self.channel_ch_lbls = []
        self.channel_checks = []
        self.channel_type_combos = []
        self.channel_filter_hint_lbls = []
        self.channel_emg_thresh_inline = []
        for ch in range(MAX_CHANNELS):
            block = ch // 8  # 0 → coluna esquerda; 1 → coluna direita
            row = (ch % 8) + 1
            base_col = block * 5
            # Ativo
            cb = QtWidgets.QCheckBox()
            cb.setChecked(True)
            cb.setStyleSheet(f"QCheckBox {{ color: {CHANNEL_COLORS[ch]}; }}")
            cb.toggled.connect(lambda checked, c=ch: self._on_channel_toggle(c, checked))
            cl.addWidget(cb, row, base_col + 0)
            self.channel_checks.append(cb)
            # Nome canal
            ch_lbl = QtWidgets.QLabel(f"CH{ch+1}")
            ch_lbl.setStyleSheet(f"color: {CHANNEL_COLORS[ch]}; font-weight: bold;")
            ch_lbl.setMinimumWidth(46)
            cl.addWidget(ch_lbl, row, base_col + 1)
            self.channel_ch_lbls.append(ch_lbl)
            # Tipo (combo)
            tc = QtWidgets.QComboBox()
            # As siglas são iguais em todo idioma, mas "off" não é. Exibe
            # traduzido e guarda a chave, que é o que vai para o config e
            # indexa SIGNAL_FILTER_PRESETS.
            for stype in SIGNAL_TYPES:
                tc.addItem(tr(stype), stype)
            cur_type = (self.config.channel_signal_types[ch]
                        if ch < len(self.config.channel_signal_types) else "EEG")
            _k = tc.findData(cur_type)
            if _k >= 0:
                tc.setCurrentIndex(_k)
            tc.currentIndexChanged.connect(
                lambda _i, c=ch, cb=tc: self._on_channel_signal_type_changed(
                    c, cb.currentData()))
            cl.addWidget(tc, row, base_col + 2)
            self.channel_type_combos.append(tc)
            # Filtro recomendado (dinâmico)
            preset = SIGNAL_FILTER_PRESETS.get(cur_type, SIGNAL_FILTER_PRESETS["EEG"])
            hint = QtWidgets.QLabel(preset["label"])
            hint.setStyleSheet(
                f"color: {SIGNAL_TYPE_COLORS.get(cur_type, COLORS['text_dim'])}; "
                f"font-size: 9pt;")
            hint.setMinimumWidth(140)
            cl.addWidget(hint, row, base_col + 3)
            self.channel_filter_hint_lbls.append(hint)
            # Threshold EMG inline (visível se canal é EMG)
            th_inline = QtWidgets.QDoubleSpinBox()
            th_inline.setRange(1.0, 5000.0)
            th_inline.setDecimals(1)
            th_inline.setSingleStep(5.0)
            th_inline.setValue(self.config.emg_threshold_uV[ch]
                               if ch < len(self.config.emg_threshold_uV) else 50.0)
            th_inline.setSuffix(" µV")
            th_inline.setEnabled(cur_type == "EMG")
            th_inline.valueChanged.connect(
                lambda v, c=ch: self._emg_threshold_changed_inline(c, v))
            cl.addWidget(th_inline, row, base_col + 4)
            self.channel_emg_thresh_inline.append(th_inline)

        self.channel_grid = cl
        cl_outer.addLayout(cl)

        # Botão: aplicar preset de filtro do canal selecionado
        f_row = QtWidgets.QHBoxLayout()
        apply_preset_btn = QtWidgets.QPushButton(tr("Aplicar filtro do tipo de sinal (global)"))
        apply_preset_btn.setToolTip(
            tr("Aplica os parâmetros bandpass + notch recomendados para o tipo de sinal "
            "predominante. Se houver mistura EEG/EMG, usa o tipo da maioria.")
        )
        apply_preset_btn.clicked.connect(self._apply_dominant_signal_filter)
        f_row.addWidget(apply_preset_btn)
        f_row.addStretch()
        cl_outer.addLayout(f_row)

        layout.addWidget(ch_group)

        # ---- Detecção automática de canais ruins ----
        bad_group = QtWidgets.QGroupBox(tr("Detecção Automática de Canais Ruins (variância + correlação)"))
        bgl = QtWidgets.QHBoxLayout(bad_group)
        bgl.addWidget(QtWidgets.QLabel(
            tr("Identifica canais com variância anômala ou descorrelacionados "
            "dos vizinhos (eletrodo solto / saturação).")
        ))
        bgl.addStretch()
        self.bad_detect_btn = QtWidgets.QPushButton(tr("Detectar agora"))
        self.bad_detect_btn.clicked.connect(self._detect_bad_channels)
        bgl.addWidget(self.bad_detect_btn)
        self.bad_detect_status = QtWidgets.QLabel("--")
        self.bad_detect_status.setStyleSheet(f"color: {COLORS['text_dim']};")
        bgl.addWidget(self.bad_detect_status)
        layout.addWidget(bad_group)

        # ---- Modo do exame (define o que a interface inteira mostra) ----
        mode_group = QtWidgets.QGroupBox(tr("Modo do exame — o que você vai medir"))
        mode_l = QtWidgets.QHBoxLayout(mode_group)
        mode_l.addWidget(QtWidgets.QLabel(tr(
            "A interface mostra apenas o que pertence à modalidade escolhida. "
            "Use Multimodal se for combinar sinais (ex.: EMG junto com EEG)."
        )))
        mode_l.addStretch()
        self.mode_visibility_combo = QtWidgets.QComboBox()
        for code, label in (("EEG", tr("EEG · Cérebro")),
                             ("EMG", tr("EMG · Músculos")),
                             ("ECG", tr("ECG · Coração")),
                             ("EoG", tr("EOG · Olhos")),
                             ("Hibrido", tr("Multimodal (combinar sinais)"))):
            self.mode_visibility_combo.addItem(label, code)
        # Restaura o modo salvo; se não houver, usa o tipo predominante
        dom = getattr(self.config, "acquisition_mode", None)
        if dom not in ("EEG", "EMG", "ECG", "EoG", "Hibrido"):
            try:
                from collections import Counter as _C
                types = [t for t in self.config.channel_signal_types if t != "off"]
                dom = _C(types).most_common(1)[0][0] if types else "EEG"
            except Exception:
                dom = "EEG"
        idx_d = self.mode_visibility_combo.findData(dom)
        if idx_d >= 0:
            self.mode_visibility_combo.setCurrentIndex(idx_d)
        # Aplica na hora: o botão "Aplicar modo" fazia o ajuste parecer quebrado
        # (o operador trocava o combo e nada acontecia).
        self.mode_visibility_combo.currentIndexChanged.connect(
            self._on_mode_visibility_apply)
        mode_l.addWidget(self.mode_visibility_combo)
        layout.addWidget(mode_group)

        layout.addStretch()
        return widget

    def _on_mode_visibility_apply(self, _idx=None):
        """Aplica o modo escolhido no combo (ligado a currentIndexChanged, que
        envia o índice — daí o argumento opcional)."""
        if not hasattr(self, "mode_visibility_combo"): return
        code = self.mode_visibility_combo.currentData()
        if not code: return
        self._apply_signal_mode_visibility(code)

    # ---- Handlers de tipo de sinal por canal ----
    def _on_channel_signal_type_changed(self, ch, new_type):
        """Salva o tipo de sinal escolhido para um canal."""
        if ch < 0 or ch >= MAX_CHANNELS: return
        if new_type not in SIGNAL_TYPES: return
        while len(self.config.channel_signal_types) <= ch:
            self.config.channel_signal_types.append("EEG")
        self.config.channel_signal_types[ch] = new_type
        self.config.save()
        # Atualiza hint de filtro nesta aba
        if hasattr(self, "channel_filter_hint_lbls"):
            preset = SIGNAL_FILTER_PRESETS.get(new_type, SIGNAL_FILTER_PRESETS["EEG"])
            self.channel_filter_hint_lbls[ch].setText(preset["label"])
            self.channel_filter_hint_lbls[ch].setStyleSheet(
                f"color: {SIGNAL_TYPE_COLORS.get(new_type, COLORS['text_dim'])}; font-size: 9pt;")
        if hasattr(self, "channel_emg_thresh_inline"):
            self.channel_emg_thresh_inline[ch].setEnabled(new_type == "EMG")
        # Reflete na aba EMG, se já construída
        if hasattr(self, "emg_rows"):
            self._emg_refresh_channel_types()
        # ECG/EoG combos dependem do tipo
        if hasattr(self, "ecg_channel_combo"):
            self._populate_ecg_channel_combo()
        if hasattr(self, "eog_h_combo"):
            self._populate_eog_channel_combos()
        # EMG Joystick combos
        if hasattr(self, "_joy_axes"):
            self._joy_repopulate_combos()
        # Reenvia os tipos ao FilterChain: a máscara da média comum é lida só em
        # set_reref, então sem isto reclassificar um canal para ECG no meio da
        # sessão não o tirava da CAR — ele seguia sangrando QRS em todo o EEG.
        if hasattr(self, "filters") and hasattr(self.filters, "set_reref"):
            try:
                self.filters.set_reref(self.filters.reref_mode, None,
                                       list(self.config.channel_signal_types))
            except Exception as exc:
                self._log(f"Falha ao atualizar tipos na re-referência: {exc}", error=True)
        # A simulacao le isto uma vez por amostra e refaz o gerador: marcar um
        # canal como EMG passa a valer na hora, sem "reconecte para aplicar".
        _th = getattr(self, "serial_thread", None)
        if _th is not None and getattr(_th, "mode", "") == "simulation":
            _th._tipos_novos = list(self.config.channel_signal_types)
        self._log(f"CH{ch+1} agora é tipo {new_type}")
        self._atualiza_aviso_multimodal()
        # o nome do canal no Empilhado segue o tipo (G13)
        if hasattr(self, "montage_plot"):
            self._refresh_montage_layout()
        self._audit_event("channel_type_change", channel=ch+1, type=new_type)

    def _apply_signal_type_to_all(self, stype):
        """Atribui o mesmo tipo a todos os canais."""
        if stype not in SIGNAL_TYPES: return
        for ch in range(MAX_CHANNELS):
            if hasattr(self, "channel_type_combos"):
                self.channel_type_combos[ch].setCurrentText(stype)
            else:
                self._on_channel_signal_type_changed(ch, stype)

    def _apply_signal_type_split(self, split_at, type_a, type_b):
        """Aplica type_a aos primeiros split_at canais e type_b aos restantes."""
        for ch in range(MAX_CHANNELS):
            stype = type_a if ch < split_at else type_b
            if hasattr(self, "channel_type_combos"):
                self.channel_type_combos[ch].setCurrentText(stype)
            else:
                self._on_channel_signal_type_changed(ch, stype)

    def _tipos_em_uso(self):
        # so' os canais em uso: o launcher completa as 64 posicoes com "EEG",
        # e no Multimodal de 16 canais o "majoritario" saia EEG
        n = int(getattr(self, "num_channels", BASE_CHANNELS) or BASE_CHANNELS)
        return [t for t in list(self.config.channel_signal_types)[:n] if t != "off"]

    def _apply_dominant_signal_filter(self):
        """Aplica o preset de filtro do tipo majoritário entre os canais."""
        from collections import Counter
        types = self._tipos_em_uso()
        if not types:
            return
        dom = Counter(types).most_common(1)[0][0]
        preset = SIGNAL_FILTER_PRESETS.get(dom)
        if not preset: return
        # Aplica nos spinboxes de filtro
        if hasattr(self, "bp_low"):  self.bp_low.setValue(preset["hp"])
        if hasattr(self, "bp_high"): self.bp_high.setValue(preset["lp"])
        if hasattr(self, "bp_enable"): self.bp_enable.setChecked(True)
        if hasattr(self, "notch_enable"): self.notch_enable.setChecked(preset["notch"])
        self._on_filter_change()
        self._log(f"Filtro ajustado para {dom}: {preset['label']}")

    def _emg_threshold_changed_inline(self, ch, val):
        """Threshold ajustado na aba Filtros e Canais — sincroniza com aba EMG."""
        if ch < 0 or ch >= MAX_CHANNELS: return
        while len(self.config.emg_threshold_uV) <= ch:
            self.config.emg_threshold_uV.append(50.0)
        self.config.emg_threshold_uV[ch] = float(val)
        # Reflete na aba EMG (se construída)
        if hasattr(self, "emg_rows") and ch < len(self.emg_rows):
            spin = self.emg_rows[ch]["th_spin"]
            spin.blockSignals(True)
            spin.setValue(val)
            spin.blockSignals(False)
        if hasattr(self, "emg_threshold_lines"):
            self.emg_threshold_lines[ch].setPos(val)
        self.config.save()

    def _apply_bp_preset(self, low, high):
        """Aplica um preset de banda (Largo, Mu, Beta, Gamma) ao bandpass e já o
        liga."""
        self.bp_low.setValue(low); self.bp_high.setValue(high)
        self.bp_enable.setChecked(True); self._on_filter_change()

    # ---- Tab: Hardware ----
    def _build_hardware_tab(self):
        """Aba Hardware — mostra os 16 canais + controles sem rolagem."""
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(10, 8, 10, 8); layout.setSpacing(6)

        ch_group = QtWidgets.QGroupBox(
            tr("Configuração por Canal "
            "(formato comando: x CH PD GAIN INPUT BIAS SRB2 SRB1 X)")
        )
        cl = QtWidgets.QGridLayout(ch_group)
        cl.setHorizontalSpacing(6); cl.setVerticalSpacing(2)
        cl.setContentsMargins(8, 6, 8, 6)
        headers = [tr("Canal"), "Power", "Gain", "Input", "Bias", "SRB2", "SRB1"]
        for i, h in enumerate(headers):
            lbl = QtWidgets.QLabel(h)
            lbl.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold;")
            cl.addWidget(lbl, 0, i)

        self.hw_power = []; self.hw_gain  = []; self.hw_input = []
        self.hw_bias  = []; self.hw_srb2  = []; self.hw_srb1  = []
        self.hw_row_widgets = []

        gain_opts = [("1x", "0"), ("2x", "1"), ("4x", "2"), ("6x", "3"),
                     ("8x", "4"), ("12x", "5"), ("24x", "6")]
        input_opts = [
            ("Normal",   "0"), ("Shorted",  "1"), ("BIAS_MEAS","2"),
            ("MVDD",     "3"), ("Temp",     "4"), ("Test",     "5"),
            ("BIAS_DRP", "6"), ("BIAS_DRN", "7"),
        ]
        power_opts = [("ON", "0"), ("OFF", "1")]
        binary_opts = [(tr("Sim"), "1"), (tr("Não"), "0")]

        def make_combo(items, default_code):
            """Fabrica os combos compactos da grade de hardware a partir de pares
            (rótulo visível, código do comando).

            O código enviado à placa fica no userData de cada item, não no
            texto exibido. A altura é limitada a 24 px para os 16 canais
            caberem sem rolagem.
            """
            cb = QtWidgets.QComboBox()
            for label, code in items: cb.addItem(label, code)
            idx = next((i for i, (_, c) in enumerate(items) if c == default_code), 0)
            cb.setCurrentIndex(idx)
            cb.setMaximumHeight(24)  # compacto
            return cb

        for ch in range(MAX_CHANNELS):
            name = QtWidgets.QLabel(f"CH{ch + 1}")
            name.setStyleSheet(f"color: {CHANNEL_COLORS[ch]}; font-weight: bold;")
            row_widgets = [name]
            cl.addWidget(name, ch + 1, 0)
            pwr = make_combo(power_opts, "0"); cl.addWidget(pwr, ch + 1, 1); self.hw_power.append(pwr); row_widgets.append(pwr)
            g   = make_combo(gain_opts, "6");  cl.addWidget(g,   ch + 1, 2); self.hw_gain.append(g);   row_widgets.append(g)
            inp = make_combo(input_opts, "0"); cl.addWidget(inp, ch + 1, 3); self.hw_input.append(inp); row_widgets.append(inp)
            b   = make_combo(binary_opts, "1"); cl.addWidget(b,   ch + 1, 4); self.hw_bias.append(b);   row_widgets.append(b)
            s2  = make_combo(binary_opts, "1"); cl.addWidget(s2,  ch + 1, 5); self.hw_srb2.append(s2);  row_widgets.append(s2)
            s1  = make_combo(binary_opts, "0"); cl.addWidget(s1,  ch + 1, 6); self.hw_srb1.append(s1);  row_widgets.append(s1)
            self.hw_row_widgets.append(row_widgets)

        layout.addWidget(ch_group)

        # Botões + Quick + Manual em UMA linha cada (compactos)
        btn_row = QtWidgets.QHBoxLayout()
        apply_all = QtWidgets.QPushButton(tr("Aplicar aos canais ATIVOS"))
        apply_all.clicked.connect(self._apply_hardware_settings_all)
        btn_row.addWidget(apply_all)
        default_btn = QtWidgets.QPushButton(tr("Restaurar padrão"))
        default_btn.setToolTip(tr("24x, normal, bias on, SRB2 on"))
        default_btn.clicked.connect(self._restore_hw_defaults)
        btn_row.addWidget(default_btn)
        btn_row.addStretch()
        # Comandos rapidos na mesma linha
        for label, cmd, tip in (
            ("v", "v", tr("Versão do firmware")),
            ("?", "?", tr("Status dos canais")),
            ("d", "d", tr("Restaura defaults na placa")),
            ("[", "[", tr("Liga sinal de teste")),
            ("]", "]", tr("Desliga sinal de teste")),
            ("C", "C", tr("Expansão ON (16ch)")),
            ("c", "c", tr("Expansão OFF (8ch)")),
        ):
            b = QtWidgets.QPushButton(label)
            b.setMinimumWidth(30); b.setMaximumWidth(48)
            b.setToolTip(tr("Comando rápido: {0}").format(tip))
            b.clicked.connect(lambda _ck, c=cmd: self._send_quick_command(c))
            btn_row.addWidget(b)
        layout.addLayout(btn_row)

        # Comando manual em linha unica
        manual_row = QtWidgets.QHBoxLayout()
        manual_row.addWidget(QtWidgets.QLabel(tr("Comando manual:")))
        self.hw_cmd_edit = QtWidgets.QLineEdit()
        self.hw_cmd_edit.setPlaceholderText(tr("ex: x1060110X (CH1 normal 24x bias SRB2)"))
        manual_row.addWidget(self.hw_cmd_edit, stretch=1)
        send_btn = QtWidgets.QPushButton(tr("Enviar"))
        send_btn.clicked.connect(self._send_hardware_command)
        manual_row.addWidget(send_btn)
        layout.addLayout(manual_row)
        return widget

    def _restore_hw_defaults(self):
        """Devolve a grade de hardware aos valores padrão: power ON, ganho 24x,
        entrada Normal, bias e SRB2 ligados, SRB1 desligado.

        Usa índices fixos dos combos, então reordenar as listas de opções em
        _build_hardware_tab muda silenciosamente o padrão. Mexe só na
        interface: os comandos só chegam à placa ao clicar em 'Aplicar aos
        canais ATIVOS'.
        """
        for ch in range(MAX_CHANNELS):
            self.hw_power[ch].setCurrentIndex(0)
            self.hw_gain[ch].setCurrentIndex(6)
            self.hw_input[ch].setCurrentIndex(0)
            self.hw_bias[ch].setCurrentIndex(0)
            self.hw_srb2[ch].setCurrentIndex(0)
            self.hw_srb1[ch].setCurrentIndex(1)

    # ---- Tab: Rede & Eventos ----
    def _build_network_tab(self):
        """Monta a aba Rede & Eventos: streaming UDP em JSON, saída LSL, receptor
        de markers via LSL e o painel de injeção de marcadores.

        Quando HAS_LSL é falso os três botões de LSL ficam desabilitados com o
        texto trocado para a dica de instalação. Além de widgets, este método
        também inicializa o estado do receptor (_lslr_streams_found,
        _lslr_inlet, _lslr_timer) — não é construção pura de interface.
        """
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(15, 15, 15, 15); layout.setSpacing(12)

        udp_group = QtWidgets.QGroupBox(tr("Streaming UDP (JSON)"))
        ul = QtWidgets.QGridLayout(udp_group)
        ul.addWidget(QtWidgets.QLabel(tr("Host:")), 0, 0)
        self.udp_host_edit = QtWidgets.QLineEdit("127.0.0.1")
        ul.addWidget(self.udp_host_edit, 0, 1)
        ul.addWidget(QtWidgets.QLabel(tr("Porta:")), 0, 2)
        self.udp_port_spin = QtWidgets.QSpinBox()
        self.udp_port_spin.setRange(1, 65535); self.udp_port_spin.setValue(12345)
        ul.addWidget(self.udp_port_spin, 0, 3)
        self.udp_toggle_btn = QtWidgets.QPushButton(tr("Iniciar streaming"))
        self.udp_toggle_btn.setCheckable(True)
        self.udp_toggle_btn.clicked.connect(self._toggle_udp)
        ul.addWidget(self.udp_toggle_btn, 0, 4)
        info = QtWidgets.QLabel(
            tr("Envia cada amostra como UDP JSON {'t': float, 'n': int, 'v': [N floats]}. "
            "N varia conforme expansão (8 ou 16). "
            "Markers viram {'t': float, 'marker': str}."))
        info.setStyleSheet(f"color: {COLORS['text_dim']};"); info.setWordWrap(True)
        ul.addWidget(info, 1, 0, 1, 5)
        layout.addWidget(udp_group)

        # ===== LSL (Lab Streaming Layer) — padrão clínico/cientifico =====
        lsl_group = QtWidgets.QGroupBox(tr("Streaming LSL (Lab Streaming Layer)"))
        ll = QtWidgets.QGridLayout(lsl_group)
        ll.addWidget(QtWidgets.QLabel(tr("Nome do stream:")), 0, 0)
        self.lsl_name_edit = QtWidgets.QLineEdit("EEG_Data_Collector")
        ll.addWidget(self.lsl_name_edit, 0, 1, 1, 2)
        self.lsl_toggle_btn = QtWidgets.QPushButton(tr("Iniciar LSL"))
        self.lsl_toggle_btn.setCheckable(True)
        self.lsl_toggle_btn.clicked.connect(self._toggle_lsl)
        if not HAS_LSL:
            self.lsl_toggle_btn.setEnabled(False)
            self.lsl_toggle_btn.setText(tr("LSL indisponível (pip install pylsl)"))
        ll.addWidget(self.lsl_toggle_btn, 0, 3)
        lsl_info = QtWidgets.QLabel(
            tr("Sincronização sub-milissegundo cross-aplicação. Padrão de fato em "
            "laboratórios de neurociência — funciona com PsychoPy, OpenViBE, "
            "BCI2000, MATLAB, Unity, etc. Cria 2 outlets: dados EEG + markers.")
        )
        lsl_info.setStyleSheet(f"color: {COLORS['text_dim']};"); lsl_info.setWordWrap(True)
        ll.addWidget(lsl_info, 1, 0, 1, 4)
        layout.addWidget(lsl_group)

        # ===== LSL Receiver — recebe streams de outros apps =====
        lslr_group = QtWidgets.QGroupBox(tr("Receber via LSL (markers/eventos de PsychoPy, OpenViBE, etc.)"))
        lslr_l = QtWidgets.QVBoxLayout(lslr_group)
        lslr_row = QtWidgets.QHBoxLayout()
        self.lslr_resolve_btn = QtWidgets.QPushButton(tr("Procurar streams LSL"))
        self.lslr_resolve_btn.clicked.connect(self._lslr_resolve)
        if not HAS_LSL:
            self.lslr_resolve_btn.setEnabled(False)
            self.lslr_resolve_btn.setText(tr("LSL indisponível (pip install pylsl)"))
        lslr_row.addWidget(self.lslr_resolve_btn)
        lslr_row.addWidget(QtWidgets.QLabel(tr("Stream:")))
        self.lslr_streams_combo = QtWidgets.QComboBox()
        self.lslr_streams_combo.setMinimumWidth(280)
        lslr_row.addWidget(self.lslr_streams_combo, stretch=1)
        self.lslr_subscribe_btn = QtWidgets.QPushButton(tr("Assinar (markers)"))
        self.lslr_subscribe_btn.setCheckable(True)
        self.lslr_subscribe_btn.clicked.connect(self._lslr_toggle_subscribe)
        if not HAS_LSL:
            self.lslr_subscribe_btn.setEnabled(False)
        lslr_row.addWidget(self.lslr_subscribe_btn)
        lslr_l.addLayout(lslr_row)
        self.lslr_status_lbl = QtWidgets.QLabel(
            tr("Pronto. Procure streams LSL na rede (ex.: PsychoPy emite markers do experimento).")
        )
        self.lslr_status_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        self.lslr_status_lbl.setWordWrap(True)
        lslr_l.addWidget(self.lslr_status_lbl)
        layout.addWidget(lslr_group)

        # Estado interno do receiver
        self._lslr_streams_found = []   # lista de StreamInfo
        self._lslr_inlet = None         # pylsl.StreamInlet ativo
        self._lslr_timer = None         # QTimer que faz pull periódico

        mk_group = QtWidgets.QGroupBox(tr("Marcadores / Eventos (hotkey global: M)"))
        ml = QtWidgets.QVBoxLayout(mk_group)
        row = QtWidgets.QHBoxLayout()
        row.addWidget(QtWidgets.QLabel(tr("Rótulo:")))
        self.marker_edit = QtWidgets.QLineEdit()
        self.marker_edit.setPlaceholderText(tr("ex: olhos_abertos, estimulo_A, prova_1"))
        row.addWidget(self.marker_edit, stretch=1)
        inj_btn = QtWidgets.QPushButton(tr("Injetar marker"))
        inj_btn.clicked.connect(self._inject_marker_from_edit)
        row.addWidget(inj_btn)
        ml.addLayout(row)

        quick = QtWidgets.QHBoxLayout()
        quick.addWidget(QtWidgets.QLabel(tr("Atalhos rápidos:")))
        for label in ("REPOUSO", "ESTIMULO", "MOTOR", "PIQUE"):
            b = QtWidgets.QPushButton(label)
            b.clicked.connect(lambda _ck, lb=label: self._inject_marker_text(lb))
            quick.addWidget(b)
        quick.addStretch()
        ml.addLayout(quick)
        ml.addWidget(QtWidgets.QLabel(tr("Marcadores recentes:")))
        self.markers_view = QtWidgets.QTextEdit()
        self.markers_view.setReadOnly(True); self.markers_view.setMaximumHeight(220)
        ml.addWidget(self.markers_view)
        layout.addWidget(mk_group)
        layout.addStretch()
        return widget

    # ==================================================================
    # Bio Multimodal: container com 3 sub-abas (EMG, ECG, EoG)
    # ==================================================================
    def _build_bio_multimodal_tab(self):
        """Container das modalidades não-EEG: EMG / ECG / EoG.

        Cada sub-aba é independente — mostra cards/plots adequados ao tipo
        de bioelétrico. Só processa canais marcados com o respectivo tipo
        em 'Filtros e Canais → Tipo de sinal'.
        """
        outer = QtWidgets.QWidget()
        v = QtWidgets.QVBoxLayout(outer)
        v.setContentsMargins(4, 4, 4, 4); v.setSpacing(4)
        # Banner explicativo — só faz sentido no modo Multimodal. Em modo único
        # ele contradizia a escolha do operador ("placa multimodal" para quem
        # selecionou apenas EMG) e ainda o mandava para outra aba.
        self.bio_banner = QtWidgets.QLabel(
            tr("Modo Multimodal — sinais combinados. "
            "Defina o tipo de cada canal em <b>Filtros e Canais → Tipo de sinal</b>.")
        )
        self.bio_banner.setTextFormat(QtCore.Qt.TextFormat.RichText)
        self.bio_banner.setStyleSheet(
            f"color: {COLORS['text_dim']}; padding: 4px 8px; "
            f"background: {COLORS['surface_alt']}; border: 1px solid {COLORS['border']}; "
            f"border-radius: 3px;")
        self.bio_banner.setWordWrap(True)
        self.bio_banner.setVisible(False)
        v.addWidget(self.bio_banner)

        # Agora que a simulacao produz batimento e piscada plausiveis, quem
        # esta na aba Coracao ve "70 bpm" sem enxergar o selo do cabecalho.
        self.bio_sim_banner = QtWidgets.QLabel(tr(
            "Sinal simulado: os batimentos, as piscadas e as contrações são "
            "gerados pelo programa, não vêm de um aparelho."))
        self.bio_sim_banner.setStyleSheet(
            f"color: {COLORS['warning']}; padding: 4px 8px; "
            f"background: {COLORS['surface_alt']}; "
            f"border: 1px solid {COLORS['warning']}; border-radius: 3px;")
        self.bio_sim_banner.setWordWrap(True)
        self.bio_sim_banner.setVisible(False)
        v.addWidget(self.bio_sim_banner)

        # QTabWidget interno
        self.bio_tabs = QtWidgets.QTabWidget()
        self.bio_tabs.setDocumentMode(True)
        self.bio_tabs.setObjectName("bioTabs")
        # Sub-abas internas (cada uma envolvida em QScrollArea: conteúdo denso
        # com cards + plots + análise avançada — scroll vertical garante que
        # tudo seja acessível mesmo em telas menores).
        self.bio_tabs.addTab(self._wrap_scroll(self._build_emg_tab()),
                             tr("EMG · Músculos"))
        self.bio_tabs.addTab(self._wrap_scroll(self._build_ecg_tab()),
                             tr("ECG · Coração"))
        self.bio_tabs.addTab(self._wrap_scroll(self._build_eog_tab()),
                             tr("EOG · Olhos"))
        self.bio_tabs.addTab(self._wrap_scroll(self._build_accelerometer_tab()),
                             tr("Acel · Movimento"))
        v.addWidget(self.bio_tabs, stretch=1)
        return outer

    # ---- Tab: EMG / Músculos ----
    def _build_emg_tab(self):
        """Aba EMG — envelope, threshold e detecção de ativação muscular.

        A placa Bionica Lab é multimodal: cada canal pode ser EEG/EMG/ECG/EoG.
        Esta aba opera apenas nos canais marcados como EMG em
        config.channel_signal_types (configurável em 'Filtros e Canais').

        Cadeia de processamento EMG (por canal, em tempo real):
            sinal cru -> bandpass 20Hz-Nyquist + notch -> envelope
            (RMS móvel | |x|+LP | MAV) -> threshold com histerese -> LED ativo
        """
        widget = QtWidgets.QWidget()
        outer = QtWidgets.QVBoxLayout(widget)
        outer.setContentsMargins(8, 8, 8, 8); outer.setSpacing(6)

        # === Cabeçalho informativo + métricas globais ===
        info_row = QtWidgets.QHBoxLayout()
        # Instrução de TAREFA (o que fazer agora), não de configuração. O texto
        # antigo repetia o banner de cima e mandava o operador para outra aba.
        info = QtWidgets.QLabel(
            tr("Marque no corpo onde colou cada eletrodo, confira a barra de "
            "ativação do músculo e inicie a gravação.")
        )
        info.setTextFormat(QtCore.Qt.TextFormat.RichText)
        info.setStyleSheet(f"color: {COLORS['text_dim']};")
        info.setWordWrap(True)
        info_row.addWidget(info, stretch=3)
        self.emg_active_count_lbl = QtWidgets.QLabel(tr("0 canais EMG ativos"))
        self.emg_active_count_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['EMG']}; font-weight: bold; padding: 0 12px;"
            f"border: 1px solid {COLORS['border']}; border-radius: 3px;")
        info_row.addWidget(self.emg_active_count_lbl)
        outer.addLayout(info_row)
        # Seletor Simples/Avançado desta modalidade
        outer.addLayout(self._make_detail_toggle(
            "emg", tr("Exame de músculos — posicione os eletrodos e grave.")))

        # === Controles globais ===
        ctrl_group = QtWidgets.QGroupBox(tr("Configuração do Envelope EMG"))
        ctrl = QtWidgets.QHBoxLayout(ctrl_group)
        ctrl.setContentsMargins(8, 4, 8, 4)
        ctrl.addWidget(QtWidgets.QLabel(tr("Método:")))
        self.emg_method_combo = QtWidgets.QComboBox()
        self.emg_method_combo.addItems(["RMS", "|x|+LP", "MAV"])
        self.emg_method_combo.setCurrentText(self.config.emg_envelope_method)
        self.emg_method_combo.setToolTip(
            tr("RMS    : Root Mean Square em janela móvel — padrão clínico.\n"
            "|x|+LP : Retificação seguida de Low-Pass (~10Hz).\n"
            "MAV    : Mean Absolute Value (média móvel do valor absoluto).")
        )
        self.emg_method_combo.currentTextChanged.connect(self._on_emg_settings_changed)
        ctrl.addWidget(self.emg_method_combo)
        ctrl.addSpacing(15)
        ctrl.addWidget(QtWidgets.QLabel(tr("Janela (ms):")))
        self.emg_window_spin = QtWidgets.QSpinBox()
        self.emg_window_spin.setRange(10, 1000)
        self.emg_window_spin.setSingleStep(10)
        self.emg_window_spin.setValue(int(self.config.emg_envelope_window_ms))
        self.emg_window_spin.setToolTip(tr("Janela em ms para cálculo do envelope (RMS/MAV)."))
        self.emg_window_spin.valueChanged.connect(self._on_emg_settings_changed)
        ctrl.addWidget(self.emg_window_spin)
        ctrl.addSpacing(15)
        ctrl.addWidget(QtWidgets.QLabel(tr("Limiar geral:")))
        self.emg_global_thresh_spin = QtWidgets.QDoubleSpinBox()
        self.emg_global_thresh_spin.setRange(1.0, 5000.0)
        self.emg_global_thresh_spin.setDecimals(1)
        self.emg_global_thresh_spin.setSingleStep(5.0)
        self.emg_global_thresh_spin.setValue(50.0)
        self.emg_global_thresh_spin.setSuffix(" µV")
        ctrl.addWidget(self.emg_global_thresh_spin)
        btn_apply_all = QtWidgets.QPushButton(tr("Aplicar a todos"))
        btn_apply_all.clicked.connect(self._emg_apply_global_threshold)
        ctrl.addWidget(btn_apply_all)
        ctrl.addStretch()
        btn_reset_counters = QtWidgets.QPushButton(tr("Zerar contagens"))
        btn_reset_counters.setToolTip(tr("Zera contadores de ativação muscular por canal."))
        btn_reset_counters.clicked.connect(self._emg_reset_counters)
        ctrl.addWidget(btn_reset_counters)
        outer.addWidget(ctrl_group)

        # === Atlas muscular — a FIGURA vem primeiro ===
        # Antes ele era o 4º bloco da aba, abaixo de dois painéis grandes: o
        # operador rolava até o fim sem nunca ver a silhueta do corpo. É a peça
        # que se entende sem legenda, então abre a tela.
        outer.addWidget(self._build_emg_atlas_group())

        # === Splitter: cards por canal (esquerda) + plot temporal (direita) ===
        split = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)

        # ----- Painel esquerdo: cards por canal -----
        cards_widget = QtWidgets.QWidget()
        cards_layout = QtWidgets.QGridLayout(cards_widget)
        cards_layout.setHorizontalSpacing(6); cards_layout.setVerticalSpacing(4)
        cards_layout.setContentsMargins(2, 2, 2, 2)

        hdr_titles = ["CH", tr("Tipo"), tr("Eletrodo / músculo"), tr("Envelope (µV)"), tr("Pico"), tr("Limiar (µV)"), tr("Ativo"), tr("Contagem")]
        for c, h in enumerate(hdr_titles):
            lbl = QtWidgets.QLabel(h)
            lbl.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold;")
            cards_layout.addWidget(lbl, 0, c)
            if c == 5:
                self._emg_hdr_limiar = lbl      # "Sensibilidade" no Simples (G38)

        self.emg_rows = []  # lista de dicts por canal
        for ch in range(MAX_CHANNELS):
            row = ch + 1
            # CH
            ch_lbl = QtWidgets.QLabel(f"CH{ch+1}")
            ch_lbl.setStyleSheet(f"color: {CHANNEL_COLORS[ch]}; font-weight: bold;")
            cards_layout.addWidget(ch_lbl, row, 0)
            # Tipo (mostra tipo configurado; só "EMG" é processado por essa aba)
            type_lbl = QtWidgets.QLabel(self.config.channel_signal_types[ch])
            t_col = SIGNAL_TYPE_COLORS.get(self.config.channel_signal_types[ch], "#888")
            type_lbl.setStyleSheet(f"color: {t_col}; font-weight: bold;")
            cards_layout.addWidget(type_lbl, row, 1)
            # Eletrodo do mapeamento (canal nao-EMG) ou eletrodo/musculo do
            # Atlas (canal EMG) — ver _emg_rotulo_eletrodo.
            _sig_ch = (self.config.channel_signal_types[ch]
                       if ch < len(self.config.channel_signal_types) else "EEG")
            elec = self._emg_rotulo_eletrodo(
                ch, _sig_ch == "EMG" and ch < self.num_channels)
            elec_lbl = QtWidgets.QLabel(elec)
            elec_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
            cards_layout.addWidget(elec_lbl, row, 2)
            # Bar de envelope (QProgressBar)
            bar = QtWidgets.QProgressBar()
            bar.setRange(0, 500)  # µV — ajustado dinamicamente
            bar.setValue(0)
            bar.setTextVisible(True)
            bar.setFormat("%v µV")
            bar.setStyleSheet(
                f"QProgressBar {{ border: 1px solid {COLORS['border']}; "
                f"  background: {COLORS['background']}; height: 18px; }} "
                f"QProgressBar::chunk {{ background-color: {SIGNAL_TYPE_COLORS['EMG']}; }}")
            cards_layout.addWidget(bar, row, 3)
            # Pico
            peak_lbl = QtWidgets.QLabel("0")
            peak_lbl.setStyleSheet(f"color: {COLORS['text_dim']}; font-family: {FONT_DATA_STACK};")
            peak_lbl.setMinimumWidth(50)
            cards_layout.addWidget(peak_lbl, row, 4)
            # Threshold (µV)
            th_spin = QtWidgets.QDoubleSpinBox()
            th_spin.setRange(1.0, 5000.0)
            th_spin.setDecimals(1)
            th_spin.setSingleStep(5.0)
            th_spin.setValue(self.config.emg_threshold_uV[ch] if ch < len(self.config.emg_threshold_uV) else 50.0)
            th_spin.setSuffix(" µV")
            th_spin.valueChanged.connect(
                lambda v, c=ch: self._emg_threshold_changed(c, v))
            cards_layout.addWidget(th_spin, row, 5)
            # LED de ativação
            led = QtWidgets.QLabel("●")
            led.setStyleSheet("color: #555; font-size: 18pt;")
            led.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
            cards_layout.addWidget(led, row, 6)
            # Contagem de ativações
            cnt_lbl = QtWidgets.QLabel("0")
            cnt_lbl.setStyleSheet(f"color: {COLORS['text']}; font-family: {FONT_DATA_STACK};")
            cnt_lbl.setMinimumWidth(40)
            cards_layout.addWidget(cnt_lbl, row, 7)

            self.emg_rows.append({
                "ch_lbl": ch_lbl,
                "type_lbl": type_lbl, "elec_lbl": elec_lbl,
                "bar": bar, "peak_lbl": peak_lbl, "th_spin": th_spin,
                "led": led, "count_lbl": cnt_lbl,
                "is_active": False, "activations": 0,
                "peak_envelope": 0.0,
            })

        cards_layout.setColumnStretch(3, 1)
        cards_widget.setLayout(cards_layout)
        cards_scroll = QtWidgets.QScrollArea()
        cards_scroll.setWidget(cards_widget)
        cards_scroll.setWidgetResizable(True)
        cards_scroll.setHorizontalScrollBarPolicy(
            QtCore.Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        split.addWidget(cards_scroll)

        # ----- Painel direito: plot temporal do envelope -----
        right = QtWidgets.QWidget()
        rl = QtWidgets.QVBoxLayout(right)
        rl.setContentsMargins(2, 2, 2, 2)
        rl.addWidget(QtWidgets.QLabel(tr("Envelope EMG — últimos 10 s")))
        self.emg_plot = pg.PlotWidget(enableMenu=False)
        self.emg_plot.showGrid(x=True, y=True, alpha=0.15)
        self.emg_plot.setLabel("left", tr("Envelope"), units="µV")
        self.emg_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.emg_plot.addLegend(offset=(10, 10))
        self.emg_plot.setMenuEnabled(False)
        self.emg_curves = []
        for ch in range(MAX_CHANNELS):
            cur = self.emg_plot.plot(
                pen=pg.mkPen(CHANNEL_COLORS[ch], width=1.2),
                name=f"CH{ch+1}")
            cur.setVisible(False)
            self.emg_curves.append(cur)
        # Linhas de threshold (uma por canal — invisíveis até ser EMG)
        self.emg_threshold_lines = []
        for ch in range(MAX_CHANNELS):
            line = pg.InfiniteLine(
                pos=self.config.emg_threshold_uV[ch] if ch < len(self.config.emg_threshold_uV) else 50.0,
                angle=0,
                pen=pg.mkPen(CHANNEL_COLORS[ch],
                             style=QtCore.Qt.PenStyle.DashLine, width=1))
            line.setVisible(False)
            self.emg_plot.addItem(line)
            self.emg_threshold_lines.append(line)
        rl.addWidget(self.emg_plot)
        split.addWidget(right)
        split.setSizes([720, 600])
        outer.addWidget(split, stretch=2)

        # ===================================================================
        # SEÇÃO: Mapeamento Muscular + Análise Avançada
        # ===================================================================
        analysis_group = QtWidgets.QGroupBox(tr("Mapeamento Muscular e Análise Avançada (MVC, Fadiga, Co-contração)"))
        ag_l = QtWidgets.QVBoxLayout(analysis_group)
        ag_l.setContentsMargins(8, 6, 8, 8); ag_l.setSpacing(4)

        # Sub-controles superiores: indicadores globais
        gl = QtWidgets.QHBoxLayout()
        # Índice de fadiga global
        self.emg_fatigue_lbl = QtWidgets.QLabel(tr("Fadiga: --"))
        self.emg_fatigue_lbl.setStyleSheet(
            f"color: {COLORS['warning']}; font-weight: bold; padding: 4px 10px;"
            f"border: 1px solid {COLORS['border']}; border-radius: 4px;")
        self.emg_fatigue_lbl.setToolTip(
            tr("Índice de fadiga: queda da frequência mediana do espectro EMG "
            "ao longo da sessão. Queda >15% sugere fadiga muscular significativa.")
        )
        gl.addWidget(self.emg_fatigue_lbl)
        # Co-contração
        self.emg_cocontraction_lbl = QtWidgets.QLabel(tr("Co-contração: --"))
        self.emg_cocontraction_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['EMG']}; font-weight: bold; padding: 4px 10px;"
            f"border: 1px solid {COLORS['border']}; border-radius: 4px;")
        self.emg_cocontraction_lbl.setToolTip(
            tr("Índice de co-contração entre canais antagonistas (agonista/antagonista).\n"
            "0% = só agonista ativo. 100% = ativação simultânea total.\n"
            "Alta co-contração pode indicar estabilização articular ou ineficiência.")
        )
        gl.addWidget(self.emg_cocontraction_lbl)
        # Movimento dominante
        self.emg_movement_lbl = QtWidgets.QLabel(tr("Movimento: --"))
        self.emg_movement_lbl.setStyleSheet(
            f"color: {COLORS['accent']}; font-weight: bold; padding: 4px 10px;"
            f"border: 1px solid {COLORS['border']}; border-radius: 4px;")
        self.emg_movement_lbl.setToolTip(
            tr("Movimento dominante: para cada par agonista/antagonista mapeado, "
            "mostra qual está mais ativo (ex.: Flexão cotovelo / Extensão cotovelo).")
        )
        gl.addWidget(self.emg_movement_lbl)
        gl.addStretch()
        btn_reset_fatigue = QtWidgets.QPushButton(tr("Zerar fadiga (recalibra o início)"))
        btn_reset_fatigue.clicked.connect(self._emg_reset_fatigue_baseline)
        gl.addWidget(btn_reset_fatigue)
        btn_cocontr = QtWidgets.QPushButton(tr("Mapa de co-contração…"))
        btn_cocontr.setToolTip(tr(
            "Mapa de intenção de movimento a partir de um par agonista/"
            "antagonista: calibra um movimento de cada vez e mostra, ao vivo, "
            "para que lado a intenção pende."))
        btn_cocontr.clicked.connect(self._open_cocontraction_map)
        gl.addWidget(btn_cocontr)
        ag_l.addLayout(gl)

        # Tabela de mapeamento muscular por canal
        # Layout: 8 colunas (CH + Músculo + Ação + %MVC + Calibrar MVC),
        # 2 blocos lado a lado (CH1-8 | CH9-16)
        muscle_grid = QtWidgets.QGridLayout()
        muscle_grid.setHorizontalSpacing(6); muscle_grid.setVerticalSpacing(2)
        # Um cabecalho por bloco de 8 canais (os blocos 3 a 8 nasciam sem
        # cabecalho nenhum). Blocos sem canal em uso somem em
        # _sync_multimodal_tabs_with_channels: com 8 canais a grade pedia
        # 4067 px e a aba rolava na horizontal.
        self.emg_muscle_hdrs = []
        for block in range((MAX_CHANNELS + 7) // 8):
            base_col = block * 5
            hdrs_bloco = []
            for i, h in enumerate(["CH", tr("Músculo"), tr("Ação"), tr("% MVC"), tr("Calibrar MVC (3s)")]):
                lbl = QtWidgets.QLabel(h)
                lbl.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold;")
                muscle_grid.addWidget(lbl, 0, base_col + i)
                hdrs_bloco.append(lbl)
            self.emg_muscle_hdrs.append(hdrs_bloco)

        self.emg_muscle_combos = []
        self.emg_action_lbls   = []
        self.emg_mvc_pct_lbls  = []
        self.emg_ch_lbls       = []   # rotulo CHn da grade muscular
        self.emg_mvc_btns      = []   # botao Calibrar de cada canal
        for ch in range(MAX_CHANNELS):
            block = ch // 8
            row = (ch % 8) + 1
            base_col = block * 5
            # CH
            ch_lbl = QtWidgets.QLabel(f"CH{ch+1}")
            ch_lbl.setStyleSheet(f"color: {CHANNEL_COLORS[ch]}; font-weight: bold;")
            muscle_grid.addWidget(ch_lbl, row, base_col + 0)
            self.emg_ch_lbls.append(ch_lbl)
            # Combo de músculo
            mcb = QtWidgets.QComboBox()
            # O nome do músculo é EXIBIDO traduzido e GUARDADO em português:
            # ele é a chave de COMMON_MUSCLES e vai para o config. Traduzir o
            # texto sem separar a chave quebraria a gravação em outro idioma.
            for muscle_name in COMMON_MUSCLES.keys():
                mcb.addItem(tr(muscle_name), muscle_name)
            cur_muscle = (self.config.emg_channel_muscle[ch]
                          if ch < len(self.config.emg_channel_muscle) else "(não definido)")
            _i = mcb.findData(cur_muscle)
            if _i >= 0:
                mcb.setCurrentIndex(_i)
            mcb.currentIndexChanged.connect(
                lambda _i, c=ch, cb=mcb: self._emg_muscle_changed(
                    c, cb.currentData()))
            muscle_grid.addWidget(mcb, row, base_col + 1)
            self.emg_muscle_combos.append(mcb)
            # Ação (auto-preenchido a partir do músculo)
            action_lbl = QtWidgets.QLabel(
                tr(COMMON_MUSCLES.get(cur_muscle, {}).get("action", "")))
            action_lbl.setStyleSheet(f"color: {COLORS['text_dim']}; font-size: 9pt;")
            action_lbl.setMinimumWidth(110)
            muscle_grid.addWidget(action_lbl, row, base_col + 2)
            self.emg_action_lbls.append(action_lbl)
            # % MVC (atualizado em runtime)
            pct_lbl = QtWidgets.QLabel("--")
            pct_lbl.setStyleSheet(f"color: {COLORS['text']}; font-family: {FONT_DATA_STACK};")
            pct_lbl.setMinimumWidth(50)
            mvc_val = (self.config.emg_channel_mvc_uV[ch]
                       if ch < len(self.config.emg_channel_mvc_uV) else 0.0)
            pct_lbl.setToolTip(tr("MVC calibrado: {0:.1f} µV (use 'Calibrar MVC' para refazer)").format(mvc_val))
            muscle_grid.addWidget(pct_lbl, row, base_col + 3)
            self.emg_mvc_pct_lbls.append(pct_lbl)
            # Botão calibrar MVC
            cal_btn = QtWidgets.QPushButton(tr("Calibrar"))
            cal_btn.setMaximumWidth(80)
            cal_btn.setToolTip(
                tr("Faz contração máxima por 3s para definir referência "
                "(MVC = Maximum Voluntary Contraction).")
            )
            cal_btn.clicked.connect(lambda _ck, c=ch: self._emg_mvc_calibrate(c))
            muscle_grid.addWidget(cal_btn, row, base_col + 4)
            self.emg_mvc_btns.append(cal_btn)

        self.emg_muscle_grid = muscle_grid
        muscle_grid.setColumnStretch(1, 1); muscle_grid.setColumnStretch(2, 1)
        muscle_grid.setColumnStretch(6, 1); muscle_grid.setColumnStretch(7, 1)
        ag_l.addLayout(muscle_grid)
        outer.addWidget(analysis_group)

        # (O Atlas Muscular foi promovido para o topo da aba — ver acima.)

        # ===================================================================
        # SEÇÃO: MNF / MDF temporal (rastreamento de fadiga muscular)
        # ===================================================================
        mnfdf_group = QtWidgets.QGroupBox(tr("Frequência Mediana (MDF) e Média (MNF) — Rastreamento de Fadiga"))
        mnfdf_l = QtWidgets.QVBoxLayout(mnfdf_group)
        mnfdf_l.setContentsMargins(8, 6, 8, 6)
        # Controles
        mnfdf_ctrl = QtWidgets.QHBoxLayout()
        mnfdf_ctrl.addWidget(QtWidgets.QLabel(tr("Canal EMG:")))
        self.emg_mnfdf_channel = QtWidgets.QComboBox()
        for ch in range(MAX_CHANNELS):
            self.emg_mnfdf_channel.addItem(f"CH{ch+1}", ch)
        mnfdf_ctrl.addWidget(self.emg_mnfdf_channel)
        mnfdf_ctrl.addSpacing(15)
        self.emg_mnfdf_status_lbl = QtWidgets.QLabel(
            tr("MDF/MNF é a métrica clínica padrão (SENIAM): queda de 8-15% "
            "indica fadiga muscular.")
        )
        self.emg_mnfdf_status_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        mnfdf_ctrl.addWidget(self.emg_mnfdf_status_lbl, stretch=1)
        mnfdf_l.addLayout(mnfdf_ctrl)
        # Plot
        self.emg_mnfdf_plot = pg.PlotWidget(enableMenu=False)
        self.emg_mnfdf_plot.showGrid(x=True, y=True, alpha=0.15)
        self.emg_mnfdf_plot.setLabel("left", tr("Frequência"), units="Hz")
        self.emg_mnfdf_plot.setLabel("bottom", tr("Janela (~1s cada)"))
        self.emg_mnfdf_plot.setMenuEnabled(False)
        self.emg_mnfdf_plot.addLegend(offset=(10, 10))
        self.emg_mdf_curve = self.emg_mnfdf_plot.plot(
            pen=None, symbol="o", symbolSize=4,
            symbolBrush=SIGNAL_TYPE_COLORS["EMG"], name=tr("MDF (mediana)"))
        self.emg_mnf_curve = self.emg_mnfdf_plot.plot(
            pen=pg.mkPen(COLORS["warning"], width=1,
                         style=QtCore.Qt.PenStyle.DashLine), name=tr("MNF (média)"))
        # Linha de TENDÊNCIA de fadiga (regressão linear do MDF) — assinatura
        # EMGworks/Noraxon: slope negativo = fadiga.
        self.emg_mdf_fit_curve = self.emg_mnfdf_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=2), name=tr("Tendência (regressão)"))
        # Linha tracejada do baseline
        self.emg_mnfdf_baseline_line = pg.InfiniteLine(
            pos=0, angle=0,
            pen=pg.mkPen(COLORS["text_dim"], style=QtCore.Qt.PenStyle.DotLine))
        # Parada em 0 ela entrava no autoscale e esticava o eixo de ~6 Hz para
        # ~91 Hz: a variacao do MDF, que e o assunto do painel, virava uma reta.
        self.emg_mnfdf_baseline_line.setVisible(False)
        self.emg_mnfdf_plot.addItem(self.emg_mnfdf_baseline_line, ignoreBounds=True)
        self.emg_mnfdf_plot.setMinimumHeight(160)
        mnfdf_l.addWidget(self.emg_mnfdf_plot)
        # Métricas de fadiga estilo laboratório (slope, R², Dimitrov, bursts)
        self.emg_fatigue_metrics_lbl = QtWidgets.QLabel(
            tr("Inclinação MDF: —   ·   Dimitrov FInsm5: —   ·   Ativações (TKEO): —"))
        self.emg_fatigue_metrics_lbl.setStyleSheet(
            f"color: {COLORS['text_dim']}; font-family: {FONT_DATA_STACK};")
        self.emg_fatigue_metrics_lbl.setToolTip(
            tr("Inclinação da regressão do MDF (Hz/min; negativo = fadiga) + R².\n"
            "Dimitrov FInsm5 = M(-1)/M(5) dos momentos espectrais (mais sensível "
            "que o MDF; sobe com a fadiga) [Dimitrov 2006].\n"
            "Ativações = onset/offset por TKEO (Teager-Kaiser) + duplo limiar."))
        self.emg_fatigue_metrics_lbl.setWordWrap(True)
        mnfdf_l.addWidget(self.emg_fatigue_metrics_lbl)
        self._emg_dimitrov_history = {ch: [] for ch in range(MAX_CHANNELS)}
        outer.addWidget(mnfdf_group)
        self._register_advanced("emg", mnfdf_group)

        # Buffer adicional para MNF (mean frequency)
        self._emg_mean_freq_history = {ch: [] for ch in range(MAX_CHANNELS)}

        # Buffer circular para envelope EMG (10 s)
        self.emg_envelope_buffer = np.zeros((MAX_CHANNELS, BUFFER_SIZE))
        # Histerese: True = canal já está em "ativo"; só sai quando cai abaixo de threshold*0.7
        self._emg_active_state = [False] * MAX_CHANNELS
        # MVC calibration state
        self._emg_mvc_calibrating = {}     # ch -> (start_time, data_list)
        # Fadiga: histórico da freq mediana por canal
        self._emg_median_freq_history = {ch: [] for ch in range(MAX_CHANNELS)}
        self._emg_fatigue_baseline = {ch: None for ch in range(MAX_CHANNELS)}

        # ===================================================================
        # SEÇÃO: Análise Tempo×Frequência (espectrograma) + Atividade muscular
        # ===================================================================
        _g_adv = self._build_emg_advanced_group()
        _g_erg = self._build_emg_ergonomics_group()
        outer.addWidget(_g_adv)
        outer.addWidget(_g_erg)
        # Blocos de pesquisa: espectrograma/atividade, APDF e fadiga comparativa,
        # configuração do envelope e a grade de mapeamento muscular (64 linhas).
        self._register_advanced("emg", _g_adv, _g_erg, ctrl_group, analysis_group)
        # Modo Simples é o padrão — a tela abre enxuta para o operador.
        self._apply_detail_level("emg")

        # Aplica visibilidade inicial conforme channel_signal_types
        self._emg_refresh_channel_types()
        return widget

    def _build_emg_ergonomics_group(self):
        """APDF (distribuição de amplitude — ergonomia) + comparação de fadiga
        (MDF %vs início) entre os músculos/canais EMG."""
        grp = QtWidgets.QGroupBox(tr("Ergonomia (APDF) e Comparação de Fadiga entre Músculos"))
        root = QtWidgets.QHBoxLayout(grp)
        root.setContentsMargins(8, 6, 8, 8); root.setSpacing(10)
        # --- esquerda: APDF ---
        left = QtWidgets.QVBoxLayout(); left.setSpacing(3)
        lc = QtWidgets.QHBoxLayout()
        lc.addWidget(QtWidgets.QLabel(tr("Canal EMG:")))
        self.emg_apdf_channel = QtWidgets.QComboBox()
        for ch in range(MAX_CHANNELS):
            self.emg_apdf_channel.addItem(f"CH{ch+1}", ch)
        lc.addWidget(self.emg_apdf_channel); lc.addStretch()
        left.addLayout(lc)
        self.emg_apdf_plot = pg.PlotWidget(enableMenu=False)
        self.emg_apdf_plot.showGrid(x=True, y=True, alpha=0.15)
        self.emg_apdf_plot.setLabel("left", tr("% do tempo (acumulado)"))
        self.emg_apdf_plot.setLabel("bottom", tr("Amplitude (%MVC ou µV)"))
        self.emg_apdf_plot.setMenuEnabled(False); self.emg_apdf_plot.setYRange(0, 100)
        self.emg_apdf_curve = self.emg_apdf_plot.plot(
            pen=pg.mkPen(SIGNAL_TYPE_COLORS["EMG"], width=2))
        # linhas P10 (estático) / P50 (mediano) / P90 (pico)
        self.emg_apdf_lines = {}
        for pct, col in (("P10", COLORS.get("success", "#2e9e50")),
                         ("P50", COLORS.get("warning", "#d9a520")),
                         ("P90", COLORS.get("error", "#d1495b"))):
            ln = pg.InfiniteLine(pos=0, angle=90,
                                 pen=pg.mkPen(col, style=QtCore.Qt.PenStyle.DashLine))
            self.emg_apdf_plot.addItem(ln); self.emg_apdf_lines[pct] = ln
        self.emg_apdf_plot.setMinimumHeight(180)
        left.addWidget(self.emg_apdf_plot)
        self.emg_apdf_lbl = QtWidgets.QLabel(
            tr("APDF: P10 (estático/repouso) · P50 (mediano) · P90 (pico). "
            "P10 alto = músculo sem repouso (risco ergonômico)."))
        self.emg_apdf_lbl.setStyleSheet(f"color: {COLORS['text_dim']}; font-size: 9pt;")
        self.emg_apdf_lbl.setWordWrap(True)
        left.addWidget(self.emg_apdf_lbl)
        root.addLayout(left, stretch=1)
        # --- direita: comparação de fadiga (MDF %vs início) ---
        right = QtWidgets.QVBoxLayout(); right.setSpacing(3)
        right.addWidget(QtWidgets.QLabel(
            tr("MDF por músculo (% vs início) — quem fadiga mais rápido "
            "(descendo = fadigando)")))
        self.emg_fatcmp_plot = pg.PlotWidget(enableMenu=False)
        self.emg_fatcmp_plot.showGrid(x=True, y=True, alpha=0.15)
        self.emg_fatcmp_plot.setLabel("left", tr("MDF (% vs início)"))
        self.emg_fatcmp_plot.setLabel("bottom", tr("Janela (~1 s cada)"))
        self.emg_fatcmp_plot.setMenuEnabled(False)
        self.emg_fatcmp_plot.addLegend(offset=(-10, 10))
        self.emg_fatcmp_baseline = pg.InfiniteLine(
            pos=100, angle=0, pen=pg.mkPen(COLORS["text_dim"],
                                           style=QtCore.Qt.PenStyle.DotLine))
        self.emg_fatcmp_plot.addItem(self.emg_fatcmp_baseline)
        self.emg_fatcmp_curves = {}   # ch -> PlotDataItem (criado sob demanda)
        self.emg_fatcmp_plot.setMinimumHeight(180)
        right.addWidget(self.emg_fatcmp_plot)
        root.addLayout(right, stretch=1)
        return grp

    def _build_emg_advanced_group(self):
        """Gráficos temporais fiéis: espectrograma EMG (freq×tempo, fadiga) e
        mapa de atividade muscular (canais×tempo)."""
        grp = QtWidgets.QGroupBox(tr("Análise Tempo×Frequência (fadiga) e Atividade Muscular no tempo"))
        root = QtWidgets.QHBoxLayout(grp)
        root.setContentsMargins(8, 6, 8, 8); root.setSpacing(10)
        self.EMG_ADV_FRAMES = 160          # nº de colunas temporais (~40 s @ 0,25 s)
        self.EMG_ADV_STEP = max(1, SAMPLE_RATE // 4)
        self._emg_adv_fmax = float(SAMPLE_RATE) / 2.0
        nfreq = int(SAMPLE_RATE // 2)      # bins de 1 Hz até Nyquist
        # LUT tipo "magma" (pip-free)
        _stops = np.array([0.0, 0.25, 0.5, 0.75, 1.0])
        _cols = np.array([[0, 0, 4], [80, 18, 90], [182, 54, 121],
                          [252, 137, 97], [252, 253, 191]])
        self._emg_spec_lut = pg.ColorMap(_stops, _cols).getLookupTable(0.0, 1.0, 256)

        # --- esquerda: espectrograma ---
        left = QtWidgets.QVBoxLayout(); left.setSpacing(3)
        lc = QtWidgets.QHBoxLayout()
        lc.addWidget(QtWidgets.QLabel(tr("Canal EMG:")))
        self.emg_spec_channel = QtWidgets.QComboBox()
        for ch in range(MAX_CHANNELS):
            self.emg_spec_channel.addItem(f"CH{ch+1}", ch)
        lc.addWidget(self.emg_spec_channel); lc.addStretch()
        lc.addWidget(QtWidgets.QLabel(tr("<span style='color:#888'>MDF desce ⇒ fadiga</span>")))
        left.addLayout(lc)
        self.emg_spec_widget = pg.PlotWidget(enableMenu=False)
        self.emg_spec_widget.setLabel("left", tr("Frequência"), units="Hz")
        self.emg_spec_widget.setLabel("bottom", tr("Tempo (s, recente à direita)"))
        self.emg_spec_widget.setMenuEnabled(False)
        self.emg_spec_img = pg.ImageItem()
        self.emg_spec_img.setLookupTable(self._emg_spec_lut)
        self.emg_spec_widget.addItem(self.emg_spec_img)
        self.emg_spec_mdf = self.emg_spec_widget.plot(
            pen=pg.mkPen("#66ffcc", width=2))     # curva MDF sobre o espectrograma
        self.emg_spec_widget.setMinimumHeight(200)
        self.emg_spec_widget.setYRange(0, min(150.0, self._emg_adv_fmax))
        left.addWidget(self.emg_spec_widget)
        root.addLayout(left, stretch=1)

        # --- direita: heatmap de atividade (canais × tempo) ---
        right = QtWidgets.QVBoxLayout(); right.setSpacing(3)
        right.addWidget(QtWidgets.QLabel(
            tr("Atividade muscular (canais × tempo) — cor = %MVC (ou envelope)")))
        self.emg_activity_widget = pg.PlotWidget(enableMenu=False)
        self.emg_activity_widget.setLabel("left", tr("Canal EMG"))
        self.emg_activity_widget.setLabel("bottom", tr("Tempo (s, recente à direita)"))
        self.emg_activity_widget.setMenuEnabled(False)
        self.emg_activity_img = pg.ImageItem()
        self.emg_activity_img.setLookupTable(
            HeadPlotWidget._VIRIDIS and pg.ColorMap(
                np.linspace(0, 1, 5),
                np.array([[68, 1, 84], [59, 82, 139], [33, 145, 140],
                          [94, 201, 98], [253, 231, 37]])).getLookupTable(0.0, 1.0, 256))
        self.emg_activity_widget.addItem(self.emg_activity_img)
        self.emg_activity_widget.setMinimumHeight(200)
        right.addWidget(self.emg_activity_widget)
        root.addLayout(right, stretch=1)

        # buffers rolantes (piso -3 = log10(1e-3) p/ região vazia ficar escura)
        self._emg_spec_buf = np.full((self.EMG_ADV_FRAMES, nfreq), -3.0, dtype=np.float32)
        self._emg_spec_mdf_hist = np.full(self.EMG_ADV_FRAMES, np.nan, dtype=np.float32)
        self._emg_activity_buf = np.zeros((MAX_CHANNELS, self.EMG_ADV_FRAMES), dtype=np.float32)
        self._emg_adv_nfreq = nfreq
        return grp

    # ==================================================================
    #  ATLAS MUSCULAR — construção da UI + handlers
    # ==================================================================
    def _build_emg_atlas_group(self):
        """Monta o grupo Atlas Muscular: o desenho do corpo com os eletrodos
        posicionáveis, a tabela de eletrodos e o histórico de montagens.

        Devolve um QGroupBox, não uma aba inteira. No final carrega a montagem
        salva em config.emg_electrode_montage e recarrega o histórico, então já
        retorna populado. As colunas de %MVC e Qualidade da tabela são
        preenchidas ao vivo pelo laço EMG, não aqui.
        """
        # '&' cru vira mnemonico no Qt: o caractere seguinte some e o espaco
        # sai sublinhado ("Atlas Muscular _Posicionamento"). Escapa no widget e
        # deixa a chave do dicionario (e as 8 traducoes) como estao.
        grp = QtWidgets.QGroupBox(
            tr("Atlas Muscular & Posicionamento de Eletrodos").replace("&", "&&"))
        self._emg_atlas_grp = grp           # título por nível (G38)
        grp.setToolTip(
            tr("Destaque os músculos trabalhados, registre onde cada eletrodo foi "
            "posicionado e acompanhe a qualidade/acurácia do contato."))
        root = QtWidgets.QHBoxLayout(grp)
        root.setContentsMargins(8, 6, 8, 8); root.setSpacing(10)

        # ---- coluna esquerda: o atlas ----
        left = QtWidgets.QVBoxLayout(); left.setSpacing(4)
        self.emg_atlas = MuscleAtlasWidget()
        self.emg_atlas.setMinimumWidth(300)
        self.emg_atlas.sigElectrodesChanged.connect(self._emg_atlas_on_changed)
        self.emg_atlas.sigElectrodeSelected.connect(self._emg_atlas_on_selected)
        left.addWidget(self.emg_atlas, stretch=1)
        hint = QtWidgets.QLabel(
            tr("Dica: ative <b>＋ Adicionar</b> e clique no corpo. Arraste p/ ajustar · "
            "duplo-clique renomeia · Delete remove."))
        hint.setTextFormat(QtCore.Qt.TextFormat.RichText)
        hint.setWordWrap(True)
        hint.setStyleSheet(f"color: {COLORS['text_dim']}; font-size: 8pt;")
        left.addWidget(hint)
        root.addLayout(left, stretch=0)

        # ---- coluna direita: controles + tabelas ----
        right = QtWidgets.QVBoxLayout(); right.setSpacing(6)
        ctl = QtWidgets.QHBoxLayout()
        ctl.addWidget(QtWidgets.QLabel(tr("Vista:")))
        self.emg_atlas_view = QtWidgets.QComboBox()
        self.emg_atlas_view.addItems([tr("Frontal (anterior)"), tr("Posterior")])
        self.emg_atlas_view.setMinimumWidth(150)
        self.emg_atlas_view.currentIndexChanged.connect(
            lambda i: self.emg_atlas.set_view("back" if i == 1 else "front"))
        ctl.addWidget(self.emg_atlas_view)
        # Zoom por REGIÃO: no corpo inteiro, antebraço e mão ficam com poucos
        # pixels e posicionar eletrodo ali vira sorte.
        ctl.addWidget(QtWidgets.QLabel(tr("Zoom:")))
        self.emg_atlas_regiao = QtWidgets.QComboBox()
        self.emg_atlas_regiao.setMinimumWidth(160)
        for rot, _z, _fx, _fy in MuscleAtlasWidget.REGIOES:
            self.emg_atlas_regiao.addItem(tr(rot), rot)
        self.emg_atlas_regiao.setToolTip(tr(
            "Aproxima numa região do corpo. Também dá para usar a roda do "
            "mouse sobre o desenho, e arrastar com o botão direito para "
            "deslocar a vista."))
        self.emg_atlas_regiao.currentIndexChanged.connect(
            lambda i: self.emg_atlas.zoom_regiao(
                self.emg_atlas_regiao.itemData(i)))
        ctl.addWidget(self.emg_atlas_regiao)
        # A roda do mouse muda o zoom sem passar pelo combo; o combo tem de
        # acompanhar, senão fica dizendo "Corpo inteiro" com a tela ampliada.
        self.emg_atlas.sigZoomChanged.connect(self._emg_atlas_zoom_mudou)
        self.emg_atlas_add_btn = QtWidgets.QPushButton(tr("＋ Adicionar eletrodo"))
        self.emg_atlas_add_btn.setCheckable(True)
        self.emg_atlas_add_btn.setToolTip(
            tr("Ative e clique no corpo para posicionar um novo eletrodo."))
        self.emg_atlas_add_btn.toggled.connect(self._emg_atlas_toggle_place)
        ctl.addWidget(self.emg_atlas_add_btn)
        ctl.addStretch()
        lbl_chk = QtWidgets.QCheckBox(tr("Rótulos"))
        lbl_chk.setChecked(True)
        lbl_chk.toggled.connect(self.emg_atlas.set_show_labels)
        ctl.addWidget(lbl_chk)
        right.addLayout(ctl)

        # tabela de eletrodos
        self.emg_atlas_table = QtWidgets.QTableWidget(0, 6)
        self.emg_atlas_table.setHorizontalHeaderLabels([tr("Nº"), tr("Nome"), tr("Canal"), tr("Músculo"), tr("% MVC"), tr("Qualidade")])
        self.emg_atlas_table.verticalHeader().setVisible(False)
        self.emg_atlas_table.setSelectionBehavior(
            QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        self.emg_atlas_table.setSelectionMode(
            QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)
        self.emg_atlas_table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        _h = self.emg_atlas_table.horizontalHeader()
        _h.setSectionResizeMode(1, QtWidgets.QHeaderView.ResizeMode.Stretch)
        _h.setSectionResizeMode(3, QtWidgets.QHeaderView.ResizeMode.Stretch)
        self.emg_atlas_table.setColumnWidth(0, 40)
        self.emg_atlas_table.setColumnWidth(2, 90)
        self.emg_atlas_table.setColumnWidth(4, 70)
        self.emg_atlas_table.setColumnWidth(5, 90)
        self.emg_atlas_table.setMinimumHeight(150)
        self.emg_atlas_table.itemSelectionChanged.connect(
            self._emg_atlas_table_row_selected)
        right.addWidget(self.emg_atlas_table, stretch=1)

        # botões de ação
        act = QtWidgets.QHBoxLayout()
        b_ren = QtWidgets.QPushButton(tr("Renomear"))
        b_ren.clicked.connect(self._emg_atlas_rename_selected)
        act.addWidget(b_ren)
        b_del = QtWidgets.QPushButton(tr("Remover"))
        b_del.clicked.connect(lambda: self.emg_atlas.remove_selected())
        act.addWidget(b_del)
        b_exp = QtWidgets.QPushButton(tr("Exportar imagem (PNG)"))
        b_exp.setToolTip(tr("Salva a imagem final do atlas em alta resolução (2×)."))
        b_exp.clicked.connect(self._emg_atlas_export_image)
        act.addWidget(b_exp)
        b_hist = QtWidgets.QPushButton(tr("Registrar no histórico"))
        b_hist.setToolTip(tr("Guarda a montagem atual (nº de eletrodos + qualidade média)."))
        b_hist.clicked.connect(self._emg_atlas_snapshot_history)
        act.addWidget(b_hist)
        act.addStretch()
        b_clr = QtWidgets.QPushButton(tr("Limpar"))
        b_clr.clicked.connect(self._emg_atlas_clear)
        act.addWidget(b_clr)
        right.addLayout(act)

        # histórico
        hist_lbl = QtWidgets.QLabel(tr("Histórico de montagens (qualidade / acurácia):"))
        hist_lbl.setStyleSheet(f"color: {COLORS['accent']}; font-weight: bold;")
        right.addWidget(hist_lbl)
        self.emg_atlas_hist_table = QtWidgets.QTableWidget(0, 5)
        self.emg_atlas_hist_table.setHorizontalHeaderLabels([tr("Data / Hora"), tr("Voluntário"), tr("Nº eletr."), tr("Qualidade média"), tr("Vista")])
        self.emg_atlas_hist_table.verticalHeader().setVisible(False)
        self.emg_atlas_hist_table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        _hh = self.emg_atlas_hist_table.horizontalHeader()
        _hh.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeMode.Stretch)
        # As quatro seguintes nasciam com 100 px fixos e cortavam "Qualidade
        # média" (123 px); em alemão é pior ainda.
        for _c in (1, 2, 3, 4):
            _hh.setSectionResizeMode(
                _c, QtWidgets.QHeaderView.ResizeMode.ResizeToContents)
        self.emg_atlas_hist_table.setMinimumHeight(110)
        right.addWidget(self.emg_atlas_hist_table, stretch=0)
        # histórico de montagens (qualidade / acurácia) é de pesquisa (G38)
        self._register_advanced("emg", hist_lbl, self.emg_atlas_hist_table, b_hist)
        root.addLayout(right, stretch=1)

        # estado interno + carrega montagem/histórico salvos
        self._emg_atlas_building = False
        self.emg_atlas.set_electrodes(self.config.emg_electrode_montage)
        self._emg_atlas_rebuild_table()
        self._emg_atlas_reload_history()
        return grp

    def _emg_atlas_toggle_place(self, on):
        """Liga o modo de inserção de eletrodo no atlas e troca o texto do botão
        para indicar que se espera um clique no corpo."""
        self.emg_atlas.set_place_mode(on)
        if on:
            self.emg_atlas_add_btn.setText(tr("Clique no corpo…"))
        else:
            self.emg_atlas_add_btn.setText(tr("＋ Adicionar eletrodo"))

    def _emg_atlas_on_changed(self):
        """Eletrodos adicionados/removidos/renomeados: persiste + reconstrói tabela."""
        self.config.emg_electrode_montage = self.emg_atlas.get_electrodes()
        try:
            self.config.save()
        except Exception:
            pass
        # ao terminar de posicionar 1 eletrodo, desarma o modo de inserção
        if self.emg_atlas_add_btn.isChecked():
            self.emg_atlas_add_btn.setChecked(False)
        self._emg_atlas_rebuild_table()
        # A coluna "Eletrodo / músculo" dos cards vem do Atlas: sem isto ela so
        # mudava quando o tipo de sinal do canal mudava.
        if hasattr(self, "emg_rows"):
            try: self._emg_refresh_channel_types()
            except Exception: pass

    def _emg_atlas_on_selected(self, eid):
        """Sincroniza a tabela quando o usuário seleciona um eletrodo clicando no
        desenho do atlas.

        Sai cedo durante _emg_atlas_rebuild_table (flag _emg_atlas_building) e
        bloqueia os sinais da tabela ao trocar a linha — as duas proteções
        existem para cortar o eco atlas→tabela→atlas.
        """
        if getattr(self, "_emg_atlas_building", False):
            return
        # sincroniza seleção da tabela
        for r in range(self.emg_atlas_table.rowCount()):
            it = self.emg_atlas_table.item(r, 0)
            if it and it.data(QtCore.Qt.ItemDataRole.UserRole) == eid:
                self.emg_atlas_table.blockSignals(True)
                self.emg_atlas_table.selectRow(r)
                self.emg_atlas_table.blockSignals(False)
                break

    def _emg_atlas_rebuild_table(self):
        """Reconstrói do zero a tabela de eletrodos do atlas depois de adicionar,
        remover ou renomear um eletrodo.

        Mantém _emg_atlas_building em True durante toda a reconstrução para que
        os sinais dos combos recém-criados não sejam tratados como edição do
        usuário. O id do eletrodo é guardado no UserRole da coluna 0 — é por
        ele que as outras rotinas localizam a linha. %MVC e Qualidade entram
        como '—' e são preenchidas depois por _emg_atlas_update_live.
        """
        self._emg_atlas_building = True
        try:
            electrodes = self.emg_atlas.get_electrodes()
            self.emg_atlas_table.setRowCount(len(electrodes))
            for r, e in enumerate(electrodes):
                # Nº (guarda id no UserRole)
                it0 = QtWidgets.QTableWidgetItem(str(e["id"]))
                it0.setData(QtCore.Qt.ItemDataRole.UserRole, e["id"])
                it0.setTextAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
                self.emg_atlas_table.setItem(r, 0, it0)
                # Nome
                self.emg_atlas_table.setItem(
                    r, 1, QtWidgets.QTableWidgetItem(e["name"]))
                # Canal (combo)
                ccb = QtWidgets.QComboBox()
                ccb.addItem("—", -1)
                for ch in range(MAX_CHANNELS):
                    ccb.addItem(f"CH{ch+1}", ch)
                idx = ccb.findData(e["channel"])
                ccb.setCurrentIndex(idx if idx >= 0 else 0)
                ccb.currentIndexChanged.connect(
                    lambda _i, eid=e["id"], cb=ccb: self._emg_atlas_set_channel(eid, cb))
                self.emg_atlas_table.setCellWidget(r, 2, ccb)
                # Músculo (combo)
                mcb = QtWidgets.QComboBox()
                for mn in COMMON_MUSCLES.keys():
                    mcb.addItem(tr(mn), mn)          # exibe traduzido, guarda a chave
                if e["muscle"] in COMMON_MUSCLES:
                    _j = mcb.findData(e["muscle"])
                    if _j >= 0:
                        mcb.setCurrentIndex(_j)
                mcb.currentIndexChanged.connect(
                    lambda _i, eid=e["id"], cb=mcb: self._emg_atlas_set_muscle(
                        eid, cb.currentData()))
                self.emg_atlas_table.setCellWidget(r, 3, mcb)
                # % MVC + Qualidade (preenchidos ao vivo)
                for c in (4, 5):
                    ph = QtWidgets.QTableWidgetItem("—")
                    ph.setTextAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
                    self.emg_atlas_table.setItem(r, c, ph)
        finally:
            self._emg_atlas_building = False

    def _emg_atlas_set_channel(self, eid, combo):
        """Associa um eletrodo do atlas ao canal escolhido no combo da linha da
        tabela.

        Se o canal já tiver músculo definido em config.emg_channel_muscle, o
        eletrodo o herda; o valor '(não definido)' não é herdado. Canal vazio
        vira -1.
        """
        if getattr(self, "_emg_atlas_building", False):
            return
        ch = combo.currentData()
        # herda músculo do canal se o eletrodo ainda não tem um
        muscle = None
        if isinstance(ch, int) and 0 <= ch < len(self.config.emg_channel_muscle):
            m = self.config.emg_channel_muscle[ch]
            if m in COMMON_MUSCLES and m != "(não definido)":
                muscle = m
        self.emg_atlas.set_channel(eid, ch if ch is not None else -1, muscle=muscle)

    def _emg_atlas_set_muscle(self, eid, muscle):
        """Grava no eletrodo do atlas o músculo escolhido no combo da tabela.

        Atualiza config.emg_electrode_montage em memória mas não chama
        config.save(): a persistência depende de outro caminho salvar a
        configuração depois.
        """
        if getattr(self, "_emg_atlas_building", False):
            return
        e = self.emg_atlas._find(eid)
        if e is not None:
            e["muscle"] = muscle
            self.config.emg_electrode_montage = self.emg_atlas.get_electrodes()

    def _emg_atlas_table_row_selected(self):
        """Destaca no desenho do atlas o eletrodo correspondente à linha
        selecionada na tabela.

        A comparação selected_id() != eid interrompe o vaivém de seleção com
        _emg_atlas_on_selected.
        """
        if getattr(self, "_emg_atlas_building", False):
            return
        rows = self.emg_atlas_table.selectionModel().selectedRows()
        if not rows:
            return
        it = self.emg_atlas_table.item(rows[0].row(), 0)
        if it is not None:
            eid = it.data(QtCore.Qt.ItemDataRole.UserRole)
            if eid is not None and self.emg_atlas.selected_id() != eid:
                self.emg_atlas.select(int(eid))

    def _emg_atlas_rename_selected(self):
        """Abre o diálogo de renomear para o eletrodo selecionado no atlas.

        A seleção consultada é a do widget do atlas (selected_id), não a da
        tabela; se nada estiver selecionado só exibe um aviso. Nome em branco é
        ignorado.
        """
        eid = self.emg_atlas.selected_id()
        if eid < 0:
            QtWidgets.QMessageBox.information(
                self, tr("Renomear"), tr("Selecione um eletrodo (na tabela ou no atlas)."))
            return
        e = self.emg_atlas._find(eid)
        cur = e["name"] if e else ""
        new, ok = pede_texto(
            self, tr("Renomear eletrodo"), tr("Nome do eletrodo:"),
            QtWidgets.QLineEdit.EchoMode.Normal, cur)
        if ok and new.strip():
            self.emg_atlas.rename(eid, new.strip())

    def _emg_atlas_clear(self):
        """Remove todos os eletrodos posicionados no atlas, pedindo confirmação
        antes."""
        if not self.emg_atlas.get_electrodes():
            return
        if QtWidgets.QMessageBox.question(
                self, tr("Limpar atlas"),
                tr("Remover TODOS os eletrodos posicionados?")) \
                == QtWidgets.QMessageBox.StandardButton.Yes:
            self.emg_atlas.clear_all()

    def _emg_atlas_export_image(self):
        """Exporta o atlas como imagem PNG em alta resolução, para anexar em
        relatório.

        Renderiza em escala 2× com o nome do voluntário no título. O nome de
        arquivo sugerido combina sujeito e vista (front/back) dentro de
        config.save_directory.
        """
        subj = getattr(self.config, "subject", "voluntario") or "voluntario"
        default = os.path.join(
            self.config.save_directory,
            f"atlas_muscular_{subj}_{self.emg_atlas.get_view()}.png")
        path, _f = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Exportar imagem do atlas"), default, tr("Imagem PNG (*.png)"))
        if not path:
            return
        title = f"Atlas muscular — {subj}"
        try:
            pm = self.emg_atlas.render_highres(scale=2.0, title=title)
            if pm.save(path, "PNG"):
                self._log(f"Atlas exportado: {path}")
                QtWidgets.QMessageBox.information(
                    self, tr("Exportado"), tr("Imagem salva em:\n{0}").format(path))
            else:
                raise RuntimeError("QPixmap.save retornou False")
        except Exception as exc:
            QtWidgets.QMessageBox.warning(
                self, tr("Erro ao exportar"), tr("Não foi possível salvar:\n{0}").format(exc))

    def _emg_atlas_snapshot_history(self):
        """Registra a montagem atual de eletrodos no histórico, junto com a
        qualidade média de contato.

        A média só considera canais com qualidade viva em _emg_atlas_live, que
        o laço EMG preenche durante a aquisição — sem aquisição rodando,
        quality_mean fica None. O histórico é truncado nos últimos 100
        registros antes de salvar na config.
        """
        electrodes = self.emg_atlas.get_electrodes()
        if not electrodes:
            QtWidgets.QMessageBox.information(
                self, tr("Histórico"), tr("Posicione ao menos um eletrodo primeiro."))
            return
        # qualidade média (usa os valores ao vivo quando disponíveis)
        quals = []
        live = getattr(self, "_emg_atlas_live", {})
        for e in electrodes:
            v = live.get(e["channel"])
            if v is not None and v[1] is not None:
                quals.append(float(v[1]))
        qmean = (sum(quals) / len(quals)) if quals else None
        rec = {
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
            "subject": getattr(self.config, "subject", "") or "",
            "n_electrodes": len(electrodes),
            "quality_mean": (round(qmean, 1) if qmean is not None else None),
            "view": self.emg_atlas.get_view(),
            "electrodes": electrodes,
        }
        self.config.emg_atlas_history.append(rec)
        self.config.emg_atlas_history = self.config.emg_atlas_history[-100:]
        try:
            self.config.save()
        except Exception:
            pass
        self._emg_atlas_reload_history()
        self._audit_event("emg_atlas_snapshot", n_electrodes=len(electrodes),
                          quality_mean=rec["quality_mean"])
        self._log(f"Montagem registrada no histórico ({len(electrodes)} eletrodos).")

    def _emg_atlas_reload_history(self):
        """Repreenche a tabela de histórico de montagens a partir de
        config.emg_atlas_history.

        Percorre a lista invertida para deixar o registro mais recente na
        primeira linha; a vista salva como 'back' é exibida como 'Posterior'.
        """
        hist = list(getattr(self.config, "emg_atlas_history", []))
        self.emg_atlas_hist_table.setRowCount(len(hist))
        for r, rec in enumerate(reversed(hist)):  # mais recente no topo
            vals = [
                rec.get("timestamp", ""),
                rec.get("subject", ""),
                str(rec.get("n_electrodes", "")),
                ("—" if rec.get("quality_mean") is None
                 else f"{rec['quality_mean']:.1f}"),
                (tr("Posterior") if rec.get("view") == "back" else "Frontal"),
            ]
            for c, v in enumerate(vals):
                it = QtWidgets.QTableWidgetItem(str(v))
                if c >= 2:
                    it.setTextAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
                self.emg_atlas_hist_table.setItem(r, c, it)

    def _emg_update_advanced(self, data, env_map, n):
        """Atualiza o espectrograma EMG (freq×tempo + MDF) do canal selecionado e
        o mapa de atividade muscular (canais×tempo). Gráficos fiéis à sequência
        temporal do sinal."""
        if not hasattr(self, "emg_spec_img") or n < SAMPLE_RATE:
            return
        fmax = self._emg_adv_fmax; nfreq = self._emg_adv_nfreq
        step_s = self.EMG_ADV_STEP / float(SAMPLE_RATE)
        window = self.EMG_ADV_FRAMES * step_s
        # ---- Espectrograma do canal selecionado ----
        sel = self.emg_spec_channel.currentData()
        if isinstance(sel, int) and 0 <= sel < data.shape[0]:
            seg = data[sel, -SAMPLE_RATE:].astype(np.float64)
            seg = seg - np.mean(seg)
            spec = np.abs(np.fft.rfft(seg * np.hanning(len(seg))))
            freqs = np.fft.rfftfreq(len(seg), 1.0 / SAMPLE_RATE)
            grid = np.linspace(0.0, fmax, nfreq)
            col = np.log10(np.interp(grid, freqs, spec) + 1e-3)
            self._emg_spec_buf = np.roll(self._emg_spec_buf, -1, axis=0)
            self._emg_spec_buf[-1] = col.astype(np.float32)
            # MDF desta janela — mesma banda >=20 Hz do painel MDF/MNF
            # (ISEK/SENIAM). Integrando desde 0 Hz, a curva verde sobre o
            # espectrograma colava no chão a cada artefato de movimento e passava
            # a contradizer o MDF do painel de fadiga, que agora é >=20 Hz —
            # dois números com o mesmo nome discordando na mesma tela.
            f_bnd = (freqs >= 20.0) & (freqs <= min(500.0, freqs[-1]))
            f_fat = freqs[f_bnd]
            psd = (spec ** 2)[f_bnd]; tot = float(np.sum(psd))
            mdf = 0.0
            if tot > 0 and f_fat.size > 1:
                cs = np.cumsum(psd)
                mdf = float(f_fat[min(int(np.searchsorted(cs, tot / 2.0)), len(f_fat) - 1)])
            self._emg_spec_mdf_hist = np.roll(self._emg_spec_mdf_hist, -1)
            self._emg_spec_mdf_hist[-1] = mdf
            lo = float(np.percentile(self._emg_spec_buf, 5))
            hi = float(np.percentile(self._emg_spec_buf, 99))
            self.emg_spec_img.setImage(self._emg_spec_buf, autoLevels=False,
                                       levels=(lo, max(hi, lo + 1e-3)))
            self.emg_spec_img.setRect(QtCore.QRectF(-window, 0.0, window, fmax))
            tx = np.linspace(-window, 0.0, self.EMG_ADV_FRAMES)
            self.emg_spec_mdf.setData(tx, self._emg_spec_mdf_hist, connect="finite")
        # ---- Atividade muscular (canais × tempo) ----
        emg_chs = [ch for ch in range(MAX_CHANNELS)
                   if (self.config.channel_signal_types[ch]
                       if ch < len(self.config.channel_signal_types) else "EEG") == "EMG"]
        self._emg_activity_buf = np.roll(self._emg_activity_buf, -1, axis=1)
        for ch in range(MAX_CHANNELS):
            env = env_map.get(ch)
            if env is None or not len(env):
                self._emg_activity_buf[ch, -1] = 0.0; continue
            cur = float(env[-1])
            mvc = (self.config.emg_channel_mvc_uV[ch]
                   if ch < len(self.config.emg_channel_mvc_uV) else 0.0)
            val = (cur / mvc * 100.0) if mvc > 0 else min(100.0, cur)   # %MVC ou envelope
            self._emg_activity_buf[ch, -1] = float(np.clip(val, 0, 150))
        if emg_chs:
            sub = self._emg_activity_buf[emg_chs]              # (n_emg, frames)
            self.emg_activity_img.setImage(sub.T, autoLevels=False, levels=(0, 100))
            self.emg_activity_img.setRect(QtCore.QRectF(-window, 0.0, window, float(len(emg_chs))))
            ax = self.emg_activity_widget.getAxis("left")
            ax.setTicks([[(i + 0.5, f"CH{emg_chs[i]+1}") for i in range(len(emg_chs))]])
            self.emg_activity_widget.setYRange(0, len(emg_chs))
        # ---- Marcadores de onset/offset (TKEO) sobre o envelope ----
        if not hasattr(self, "_emg_onset_regions"):
            self._emg_onset_regions = []
        if isinstance(sel, int) and 0 <= sel < data.shape[0] and n >= SAMPLE_RATE:
            try:
                onsets = emg_onset_tkeo(data[sel].astype(np.float64), SAMPLE_RATE)
            except Exception:
                onsets = []
            onsets = onsets[-30:]                       # limita p/ performance
            col = QtGui.QColor(SIGNAL_TYPE_COLORS["EMG"]); col.setAlpha(45)
            while len(self._emg_onset_regions) < len(onsets):
                reg = pg.LinearRegionItem(movable=False, brush=QtGui.QBrush(col))
                reg.setZValue(-10)
                for ln in reg.lines:
                    ln.setPen(pg.mkPen(SIGNAL_TYPE_COLORS["EMG"], width=1))
                self.emg_plot.addItem(reg); self._emg_onset_regions.append(reg)
            for i, reg in enumerate(self._emg_onset_regions):
                if i < len(onsets):
                    reg.setRegion((float(onsets[i][0]), float(onsets[i][1])))
                    reg.setVisible(True)
                else:
                    reg.setVisible(False)

    def _emg_update_ergonomics(self, env_map):
        """APDF (distribuição de amplitude) do canal selecionado + comparação de
        fadiga (MDF %vs início) entre os músculos EMG."""
        if not hasattr(self, "emg_apdf_curve"):
            return
        # ---- APDF ----
        sel = self.emg_apdf_channel.currentData()
        env = env_map.get(sel) if isinstance(sel, int) else None
        if env is not None and len(env) > 10:
            mvc = (self.config.emg_channel_mvc_uV[sel]
                   if sel < len(self.config.emg_channel_mvc_uV) else 0.0)
            amp = (np.asarray(env) / mvc * 100.0) if mvc > 0 else np.asarray(env)
            amp = np.clip(amp[np.isfinite(amp)], 0, None)
            if amp.size > 10:
                s = np.sort(amp)
                cdf = np.arange(1, s.size + 1) / s.size * 100.0
                self.emg_apdf_curve.setData(s, cdf)
                p10, p50, p90 = np.percentile(amp, [10, 50, 90])
                self.emg_apdf_lines["P10"].setPos(p10)
                self.emg_apdf_lines["P50"].setPos(p50)
                self.emg_apdf_lines["P90"].setPos(p90)
                un = "%MVC" if mvc > 0 else "µV"
                mus = (self.config.emg_channel_muscle[sel]
                       if sel < len(self.config.emg_channel_muscle) else "")
                self.emg_apdf_lbl.setText(
                    tr("{0}APDF · P10 (estático)={1:.1f} · P50 (mediano)={2:.1f} · P90 "
                       "(pico)={3:.1f} {4}. P10 alto = músculo sem repouso.").format(('['+mus+'] ') if mus and mus!='(não definido)' else '', p10, p50, p90, un))
        # ---- Comparação de fadiga (MDF %vs início) entre músculos ----
        pens = None
        any_curve = False
        for ch in range(MAX_CHANNELS):
            is_emg = (self.config.channel_signal_types[ch]
                      if ch < len(self.config.channel_signal_types) else "EEG") == "EMG"
            hist = self._emg_median_freq_history.get(ch, [])
            if not is_emg or len(hist) < 3:
                if ch in self.emg_fatcmp_curves:
                    self.emg_fatcmp_curves[ch].setData([], [])
                continue
            base = float(np.mean(hist[:5])) if len(hist) >= 5 else float(np.mean(hist[:3]))
            if base <= 1e-6:
                continue
            pct = [100.0 * v / base for v in hist]
            if ch not in self.emg_fatcmp_curves:
                mus = (self.config.emg_channel_muscle[ch]
                       if ch < len(self.config.emg_channel_muscle) else "")
                nm = mus if (mus and mus != "(não definido)") else f"CH{ch+1}"
                self.emg_fatcmp_curves[ch] = self.emg_fatcmp_plot.plot(
                    pen=pg.mkPen(CHANNEL_COLORS[ch], width=1.6), name=nm[:16])
            self.emg_fatcmp_curves[ch].setData(list(range(len(pct))), pct)
            any_curve = True

    def _emg_atlas_update_live(self, data, env_map):
        """Atualiza heatmap %MVC + qualidade/acurácia por canal e a tabela.
        Chamado ~2×/s pelo laço EMG. 'data' = buffer cru (canais × amostras);
        'env_map' = {canal: envelope EMG (np.array)}."""
        if not hasattr(self, "emg_atlas"):
            return
        muscle_act = {}      # músculo -> pct
        live = {}            # canal -> (pct, quality)
        electrodes = self.emg_atlas.get_electrodes()
        channels = sorted({e["channel"] for e in electrodes
                           if isinstance(e["channel"], int) and e["channel"] >= 0})
        for ch in channels:
            if ch >= MAX_CHANNELS:
                continue
            env = env_map.get(ch)
            if env is None or not len(env):
                live[ch] = (None, None)
                continue
            # % MVC a partir do envelope
            cur = float(env[-1])
            mvc = (self.config.emg_channel_mvc_uV[ch]
                   if ch < len(self.config.emg_channel_mvc_uV) else 0.0)
            pct = (cur / mvc * 100.0) if mvc > 0 else None
            # qualidade/acurácia do contato: SNR do envelope + contaminação de rede
            qual = self._emg_channel_quality(data, ch, env)
            live[ch] = (pct, qual)
            # músculo do canal (para o heatmap)
            m = (self.config.emg_channel_muscle[ch]
                 if ch < len(self.config.emg_channel_muscle) else "")
            if m in ATLAS_MUSCLE_XY and pct is not None:
                muscle_act[m] = max(muscle_act.get(m, 0.0), pct)
        self._emg_atlas_live = live
        self.emg_atlas.set_muscle_activations(muscle_act)
        self.emg_atlas.set_live_channel_data(live)
        # atualiza colunas %MVC / Qualidade da tabela sem reconstruí-la
        for r in range(self.emg_atlas_table.rowCount()):
            it0 = self.emg_atlas_table.item(r, 0)
            if it0 is None:
                continue
            eid = it0.data(QtCore.Qt.ItemDataRole.UserRole)
            e = self.emg_atlas._find(eid) if eid is not None else None
            ch = e["channel"] if e else -1
            pv = live.get(ch)
            pct_it = self.emg_atlas_table.item(r, 4)
            q_it = self.emg_atlas_table.item(r, 5)
            if pv is None:
                if pct_it: pct_it.setText("—")
                if q_it: q_it.setText("—")
                continue
            pct, qual = pv
            if pct_it:
                pct_it.setText("—" if pct is None else f"{pct:.0f}%")
            if q_it:
                if qual is None:
                    q_it.setText("—")
                else:
                    q_it.setText(f"{qual:.0f}")
                    q_it.setForeground(MuscleAtlasWidget._quality_color(qual))

    def _emg_channel_quality(self, data, ch, env):
        """Índice 0..100 de qualidade/acurácia do eletrodo:
        combina SNR do envelope (sinal/ruído de base) e a contaminação de
        rede elétrica (50/60 Hz) na janela de 1 s."""
        try:
            seg = env[-min(env.size, SAMPLE_RATE * 3):]
            if seg.size < 10:
                return None
            noise = float(np.percentile(seg, 20))
            sig = float(np.percentile(seg, 95))
            if noise <= 1e-9:
                snr_q = 100.0 if sig > 1e-6 else 0.0
            else:
                snr_db = 20.0 * np.log10(max(sig, 1e-9) / noise)
                snr_q = float(np.clip((snr_db - 4.0) / (24.0 - 4.0) * 100.0, 0, 100))
            # contaminação de rede na última 1 s de sinal cru
            line_q = 100.0
            if data is not None and ch < data.shape[0] and data.shape[1] >= SAMPLE_RATE:
                x = data[ch, -SAMPLE_RATE:].astype(np.float64)
                x = x - np.mean(x)
                if np.any(x):
                    spec = np.abs(np.fft.rfft(x * np.hanning(len(x)))) ** 2
                    freqs = np.fft.rfftfreq(len(x), 1.0 / SAMPLE_RATE)
                    total = float(np.sum(spec)) + 1e-12
                    line_pw = 0.0
                    for f0 in (50.0, 60.0):
                        band = (freqs >= f0 - 2) & (freqs <= f0 + 2)
                        line_pw = max(line_pw, float(np.sum(spec[band])))
                    ratio = line_pw / total
                    line_q = float(np.clip(100.0 - 300.0 * ratio, 0, 100))
            return round(0.6 * snr_q + 0.4 * line_q, 0)
        except Exception:
            return None

    # ---- Mapeamento muscular / MVC / Fadiga / Co-contração ----
    def _emg_muscle_changed(self, ch, muscle_name):
        """Registra qual músculo está sendo medido em um canal EMG e atualiza o
        rótulo da ação correspondente.

        Preenche config.emg_channel_muscle com '(não definido)' até alcançar o
        índice do canal antes de gravar. Salva a config na hora e emite evento
        de auditoria com o canal em base 1.
        """
        if ch < 0 or ch >= MAX_CHANNELS: return
        if muscle_name not in COMMON_MUSCLES: return
        while len(self.config.emg_channel_muscle) <= ch:
            self.config.emg_channel_muscle.append("(não definido)")
        self.config.emg_channel_muscle[ch] = muscle_name
        # Atualiza label de ação
        info = COMMON_MUSCLES.get(muscle_name, {})
        if hasattr(self, "emg_action_lbls") and ch < len(self.emg_action_lbls):
            self.emg_action_lbls[ch].setText(tr(info.get("action", "")))
        self.config.save()
        if hasattr(self, "emg_rows"):
            try: self._emg_refresh_channel_types()
            except Exception: pass
        # o nome do canal no Empilhado passa a ser o músculo (G13)
        if hasattr(self, "montage_plot"):
            self._refresh_montage_layout()
        self._audit_event("emg_muscle_assignment", channel=ch+1, muscle=muscle_name)

    def _emg_mvc_calibrate(self, ch):
        """Inicia calibração MVC: 3 segundos de contração máxima."""
        if ch < 0 or ch >= MAX_CHANNELS: return
        self._emg_mvc_calibrating[ch] = (time.time(), [])
        muscle = self.config.emg_channel_muscle[ch] if ch < len(self.config.emg_channel_muscle) else "?"
        self._log(f"MVC CH{ch+1} ({muscle}): contraia ao máximo por 3s...")

    def _emg_reset_fatigue_baseline(self):
        """Reset baseline de fadiga para todos os canais."""
        self._emg_median_freq_history = {ch: [] for ch in range(MAX_CHANNELS)}
        self._emg_fatigue_baseline = {ch: None for ch in range(MAX_CHANNELS)}
        # -10**9 e nao 0: com 0 o primeiro bloco depois do reset nao dispararia.
        self._emg_mdf_last_st = -10 ** 9
        self._emg_atlas_last_st = -10 ** 9
        self._emg_adv_last_st = -10 ** 9
        # Sem isto a linha ficava parada no valor antigo depois do reset.
        if hasattr(self, "emg_mnfdf_baseline_line"):
            self.emg_mnfdf_baseline_line.setVisible(False)
        if hasattr(self, "emg_fatigue_lbl"):
            self.emg_fatigue_lbl.setText(tr("Fadiga: -- (baseline resetado)"))
        self._log("Baseline de fadiga EMG resetado.")

    # ---- Handlers EMG ----
    def _emg_threshold_changed(self, ch, val):
        """Usuário ajustou threshold de um canal."""
        if ch < 0 or ch >= MAX_CHANNELS: return
        # Estende lista se necessário
        while len(self.config.emg_threshold_uV) <= ch:
            self.config.emg_threshold_uV.append(50.0)
        self.config.emg_threshold_uV[ch] = float(val)
        if hasattr(self, "emg_threshold_lines"):
            self.emg_threshold_lines[ch].setPos(val)
        self.config.save()

    def _emg_apply_global_threshold(self):
        """Aplica o threshold global a todos os canais EMG."""
        if not hasattr(self, "emg_global_thresh_spin"): return
        val = self.emg_global_thresh_spin.value()
        for ch in range(MAX_CHANNELS):
            self.emg_rows[ch]["th_spin"].setValue(val)
        self._log(f"Threshold EMG aplicado a todos os canais: {val:.1f} µV")

    def _emg_reset_counters(self):
        """Zera contadores e picos."""
        for ch in range(MAX_CHANNELS):
            self.emg_rows[ch]["activations"] = 0
            self.emg_rows[ch]["peak_envelope"] = 0.0
            self.emg_rows[ch]["count_lbl"].setText("0")
            self.emg_rows[ch]["peak_lbl"].setText("0")

    def _on_emg_settings_changed(self, *_args):
        """Salva mudanças em método/janela do envelope."""
        if not hasattr(self, "emg_method_combo"): return
        self.config.emg_envelope_method = self.emg_method_combo.currentText()
        self.config.emg_envelope_window_ms = float(self.emg_window_spin.value())
        self.config.save()

    def _emg_refresh_channel_types(self):
        """Atualiza visibilidade dos canais conforme tipo configurado."""
        if not hasattr(self, "emg_rows"): return
        emg_count = 0
        for ch in range(MAX_CHANNELS):
            sig = (self.config.channel_signal_types[ch]
                   if ch < len(self.config.channel_signal_types) else "EEG")
            color = SIGNAL_TYPE_COLORS.get(sig, "#888")
            row = self.emg_rows[ch]
            row["type_lbl"].setText(sig)
            row["type_lbl"].setStyleSheet(f"color: {color}; font-weight: bold;")
            # Canal alem da placa nao existe: contava-se ate 64 e o rotulo
            # dizia "64 canais EMG ativos" numa placa de 8.
            is_emg = (sig == "EMG") and ch < self.num_channels
            # Eletrodo atualizado (musculo/eletrodo do Atlas quando for EMG)
            row["elec_lbl"].setText(self._emg_rotulo_eletrodo(ch, is_emg))
            # Habilita/desabilita controles
            row["bar"].setEnabled(is_emg)
            row["th_spin"].setEnabled(is_emg)
            if is_emg:
                emg_count += 1
            else:
                # Apaga LED
                row["led"].setStyleSheet("color: #333; font-size: 18pt;")
                row["bar"].setValue(0)
            # Linhas e curvas no plot
            if hasattr(self, "emg_curves"):
                self.emg_curves[ch].setVisible(is_emg)
            if hasattr(self, "emg_threshold_lines"):
                self.emg_threshold_lines[ch].setVisible(is_emg)
        if hasattr(self, "emg_active_count_lbl"):
            if emg_count:
                self.emg_active_count_lbl.setText(
                    tr("{0} canais EMG ativos").format(emg_count))
            else:
                self.emg_active_count_lbl.setText(self._msg_sem_canal("EMG"))

    def _emg_rotulo_eletrodo(self, ch, is_emg):
        """Texto da coluna "Eletrodo / músculo" de um canal.

        Canal nao-EMG continua mostrando o eletrodo do mapeamento (Fp1, C3...).
        Canal EMG mostra o eletrodo posicionado no Atlas e o musculo escolhido:
        numa coleta muscular o nome de couro cabeludo nao existe no protocolo.
        O nome do musculo e chave (fica em portugues no config); so o texto
        exibido passa por tr().
        """
        mapeado = (self.config.channel_mapping[ch]
                   if ch < len(self.config.channel_mapping) else f"E{ch+1}")
        if not is_emg:
            return mapeado
        nome, mus_atlas = "", ""
        # hasattr: os cards sao montados antes do Atlas em parte das ordens.
        if hasattr(self, "emg_atlas"):
            try:
                for e in self.emg_atlas.get_electrodes():
                    if int(e.get("channel", -1)) == ch:
                        nome = str(e.get("name", "") or "")
                        mus_atlas = str(e.get("muscle", "") or "")
                        break
            except Exception:
                nome, mus_atlas = "", ""
        mus = (self.config.emg_channel_muscle[ch]
               if ch < len(self.config.emg_channel_muscle) else "")
        if mus in ("", "(não definido)"):
            mus = mus_atlas
        if nome and mus:
            return tr("{0} · {1}").format(nome, tr(mus))
        if nome:
            return nome
        if mus:
            return tr(mus)
        return tr("(sem eletrodo)")

    def _compute_emg_envelope(self, signal, fs, method, window_ms):
        """Calcula envelope EMG conforme método. signal: 1D ndarray."""
        if len(signal) == 0:
            return signal
        # A janela nunca pode passar do trecho recebido: np.convolve com
        # mode="same" devolve max(sinal, kernel) e o envelope saia mais longo
        # que o proprio tracado nos primeiros quadros da aquisicao.
        w = max(1, min(int(fs * window_ms / 1000.0), len(signal)))
        w = max(2, w) if len(signal) >= 2 else 1
        # Normaliza o rotulo: chamadas antigas passavam "rms" minusculo e caiam
        # no ramo final sem ninguem perceber.
        met = str(method).strip().upper()
        # Retifica primeiro
        rect = np.abs(signal)
        if met == "RMS":
            # RMS móvel = sqrt(media(x^2)) em janela w
            sq = signal * signal
            # Média móvel via convolução (boxcar)
            kernel = np.ones(w) / w
            ms = np.convolve(sq, kernel, mode="same")
            env = np.sqrt(np.maximum(ms, 0.0))
        elif met == "MAV":
            kernel = np.ones(w) / w
            env = np.convolve(rect, kernel, mode="same")
        else:  # "|x|+LP"
            # |x| seguido de média móvel (low-pass simples) com mesma janela
            kernel = np.ones(w) / w
            env = np.convolve(rect, kernel, mode="same")
        return env

    def _update_emg_view(self):
        """Atualiza envelope, LEDs, plot temporal, MVC, fadiga e co-contração."""
        if not hasattr(self, "emg_rows"):
            return
        data = self._ordered_buffer()
        n = data.shape[1]
        if n < 20:
            return
        method = self.config.emg_envelope_method
        window_ms = self.config.emg_envelope_window_ms
        t_axis = np.arange(n) / SAMPLE_RATE
        # Cadencia dos blocos caros. Antes era a congruencia samples_total %
        # SAMPLE_RATE == 0: com a aquisicao parada o contador congela e, se
        # parasse num multiplo, cada tique de 50 ms recalculava a MESMA PSD e
        # empilhava o mesmo valor no historico de fadiga (600 pontos iguais em
        # 41 s de tela parada, achatando a regressao). Agora so roda quando
        # entrou pelo menos um bloco novo de amostras.
        st = int(getattr(self, "samples_total", 0))
        if st < getattr(self, "_emg_mdf_last_st", 0):
            # Nova conexao zera samples_total: destrava os tres portoes.
            self._emg_mdf_last_st = -10 ** 9
            self._emg_atlas_last_st = -10 ** 9
            self._emg_adv_last_st = -10 ** 9
        fazer_fadiga = (n > SAMPLE_RATE
                        and st - getattr(self, "_emg_mdf_last_st", -10 ** 9) >= SAMPLE_RATE)
        emg_count_active = 0
        # Armazena envelope atual por canal para análises agregadas
        ch_envelope_current = {}
        ch_env_full = {}            # canal -> envelope completo (p/ atlas/qualidade)
        for ch in range(MAX_CHANNELS):
            sig = (self.config.channel_signal_types[ch]
                   if ch < len(self.config.channel_signal_types) else "EEG")
            if sig != "EMG":
                continue
            emg_count_active += 1
            try:
                env = self._compute_emg_envelope(data[ch], SAMPLE_RATE, method, window_ms)
            except Exception:
                continue
            row = self.emg_rows[ch]
            cur_val = float(env[-1]) if len(env) > 0 else 0.0
            peak_val = float(np.max(env)) if len(env) > 0 else 0.0
            ch_envelope_current[ch] = cur_val
            ch_env_full[ch] = env
            # Bar (escala automática: range = 2*threshold ou 100, o maior)
            th = row["th_spin"].value()
            bar_max = max(100, int(th * 3))
            row["bar"].setRange(0, bar_max)
            row["bar"].setValue(min(int(cur_val), bar_max))
            row["bar"].setFormat(f"{cur_val:.1f} µV")
            # Pico (acumula)
            if peak_val > row["peak_envelope"]:
                row["peak_envelope"] = peak_val
                row["peak_lbl"].setText(f"{peak_val:.1f}")
            # Histerese: ON quando > threshold, OFF quando < 0.7 * threshold
            was_active = self._emg_active_state[ch]
            if not was_active and cur_val > th:
                self._emg_active_state[ch] = True
                row["activations"] += 1
                row["count_lbl"].setText(str(row["activations"]))
                row["led"].setStyleSheet(
                    f"color: {SIGNAL_TYPE_COLORS['EMG']}; font-size: 18pt;")
            elif was_active and cur_val < 0.7 * th:
                self._emg_active_state[ch] = False
                row["led"].setStyleSheet("color: #555; font-size: 18pt;")
            # Curva temporal
            self.emg_curves[ch].setData(t_axis, env)

            # ---- MVC Calibration (3s contração máxima) ----
            if ch in self._emg_mvc_calibrating:
                start_t, samples = self._emg_mvc_calibrating[ch]
                samples.append(cur_val)
                if (time.time() - start_t) > 3.0:
                    # Finaliza: percentil 90 dos valores coletados
                    if samples:
                        mvc = float(np.percentile(samples, 90))
                        while len(self.config.emg_channel_mvc_uV) <= ch:
                            self.config.emg_channel_mvc_uV.append(0.0)
                        self.config.emg_channel_mvc_uV[ch] = mvc
                        self.config.save()
                        self._log(f"MVC CH{ch+1} calibrado: {mvc:.1f} µV")
                    self._emg_mvc_calibrating.pop(ch, None)

            # ---- % MVC ----
            if hasattr(self, "emg_mvc_pct_lbls") and ch < len(self.emg_mvc_pct_lbls):
                mvc = (self.config.emg_channel_mvc_uV[ch]
                       if ch < len(self.config.emg_channel_mvc_uV) else 0.0)
                if mvc > 0:
                    pct = (cur_val / mvc) * 100.0
                    color = (SIGNAL_TYPE_COLORS["EMG"] if pct < 80
                             else COLORS["warning"] if pct < 100
                             else COLORS["error"])
                    self.emg_mvc_pct_lbls[ch].setText(f"{pct:5.1f}%")
                    self.emg_mvc_pct_lbls[ch].setStyleSheet(
                        f"color: {color}; font-family: {FONT_DATA_STACK}; font-weight: bold;")
                else:
                    self.emg_mvc_pct_lbls[ch].setText(tr("(cal)"))

            # ---- Fadiga: mediana de freq do espectro ----
            # Atualiza só a cada ~1 s de sinal NOVO (ver fazer_fadiga acima).
            if fazer_fadiga:
                try:
                    # FFT do último 1s
                    sig_win = data[ch, -SAMPLE_RATE:].astype(np.float64)
                    sig_win = sig_win - np.mean(sig_win)
                    spec = np.fft.rfft(sig_win * np.hanning(len(sig_win)))
                    psd  = (np.abs(spec) ** 2)
                    freqs = np.fft.rfftfreq(len(sig_win), 1.0 / SAMPLE_RATE)
                    # ISEK/SENIAM: MDF/MNF só têm sentido de 20 Hz para cima.
                    # Abaixo disso o espectro é artefato de movimento/cabo, não
                    # unidade motora — integrando a PSD inteira (0-125 Hz), um
                    # artefato de 2 Hz puxava o MDF de ~78 Hz para 2 Hz e o painel
                    # anunciava "queda de 97%" com o músculo em repouso. O Dimitrov
                    # dez linhas abaixo já filtrava >=20 Hz e não se mexia: os dois
                    # números saíam da MESMA PSD e se contradiziam na tela.
                    f_bnd = (freqs >= 20.0) & (freqs <= min(500.0, freqs[-1]))
                    f_fat, p_fat = freqs[f_bnd], psd[f_bnd]
                    total = float(np.sum(p_fat))
                    if total > 0 and f_fat.size > 1:
                        cumsum = np.cumsum(p_fat)
                        med_idx = int(np.searchsorted(cumsum, total / 2.0))
                        med_freq = float(f_fat[min(med_idx, len(f_fat) - 1)])
                        # MNF = média ponderada pela PSD (Σ f·P / Σ P), mesma banda
                        mean_freq = float(np.sum(f_fat * p_fat) / total)
                        hist  = self._emg_median_freq_history.setdefault(ch, [])
                        mhist = self._emg_mean_freq_history.setdefault(ch, [])
                        hist.append(med_freq)
                        mhist.append(mean_freq)
                        if len(hist) > 600:   hist[:]  = hist[-600:]
                        if len(mhist) > 600:  mhist[:] = mhist[-600:]
                        if self._emg_fatigue_baseline.get(ch) is None and len(hist) >= 5:
                            self._emg_fatigue_baseline[ch] = float(np.mean(hist[:5]))
                        # Dimitrov FInsm5 = M(-1)/M(5) (índice espectral de fadiga,
                        # mais sensível que o MDF) [Dimitrov 2006].
                        band = (freqs >= 20.0) & (freqs <= min(500.0, freqs[-1]))
                        fb, pb = freqs[band], psd[band]
                        if fb.size > 4:
                            fsafe = np.where(fb > 0, fb, 1e-6)
                            m_neg1 = float(np.trapz(pb / fsafe, fb))
                            m_5 = float(np.trapz(pb * fb ** 5, fb))
                            finsm5 = m_neg1 / m_5 if m_5 > 0 else 0.0
                            dh = self._emg_dimitrov_history.setdefault(ch, [])
                            dh.append(finsm5)
                            if len(dh) > 600: dh[:] = dh[-600:]
                except Exception:
                    pass

        # Marca UMA VEZ POR QUADRO (o portao e lido dentro do laço de canais).
        if fazer_fadiga:
            self._emg_mdf_last_st = st

        # ---- Atlas muscular: heatmap %MVC + qualidade/acurácia (~2×/s) ----
        if (hasattr(self, "emg_atlas")
                and st - getattr(self, "_emg_atlas_last_st", -10 ** 9) >= max(1, SAMPLE_RATE // 2)):
            self._emg_atlas_last_st = st
            try:
                self._emg_atlas_update_live(data, ch_env_full)
            except Exception:
                pass

        # ---- Espectrograma EMG + atividade muscular no tempo (~4×/s) ----
        if (hasattr(self, "emg_spec_img")
                and st - getattr(self, "_emg_adv_last_st", -10 ** 9)
                >= getattr(self, "EMG_ADV_STEP", SAMPLE_RATE)):
            self._emg_adv_last_st = st
            try:
                self._emg_update_advanced(data, ch_env_full, n)
            except Exception:
                pass
            try:
                self._emg_update_ergonomics(ch_env_full)
            except Exception:
                pass

        # ---- Plot MNF/MDF temporal ----
        if hasattr(self, "emg_mdf_curve"):
            sel = self.emg_mnfdf_channel.currentData() if hasattr(self, "emg_mnfdf_channel") else 0
            if isinstance(sel, int) and sel >= 0:
                mdf = self._emg_median_freq_history.get(sel, [])
                mnf = self._emg_mean_freq_history.get(sel, [])
                if mdf:
                    self.emg_mdf_curve.setData(list(range(len(mdf))), mdf)
                if mnf:
                    self.emg_mnf_curve.setData(list(range(len(mnf))), mnf)
                base = self._emg_fatigue_baseline.get(sel)
                if base:
                    self.emg_mnfdf_baseline_line.setPos(base)
                    self.emg_mnfdf_baseline_line.setVisible(True)
                else:
                    self.emg_mnfdf_baseline_line.setVisible(False)
                # ---- Tendência de fadiga (regressão do MDF) + Dimitrov + TKEO ----
                slope_txt, r2 = "—", None
                if len(mdf) >= 4:
                    xx = np.arange(len(mdf), dtype=float); yy = np.asarray(mdf, float)
                    a, b = np.polyfit(xx, yy, 1)          # janelas de ~1 s
                    self.emg_mdf_fit_curve.setData(xx.tolist(), (a * xx + b).tolist())
                    ss_res = float(np.sum((yy - (a * xx + b)) ** 2))
                    ss_tot = float(np.sum((yy - yy.mean()) ** 2))
                    r2 = 1.0 - ss_res / ss_tot if ss_tot > 0 else 0.0
                    slope_txt = f"{a * 60.0:+.2f} Hz/min (R²={r2:.2f})"
                else:
                    self.emg_mdf_fit_curve.setData([], [])
                dim = self._emg_dimitrov_history.get(sel, [])
                if len(dim) >= 5:               # relativo ao início (sobe c/ fadiga)
                    base_d = float(np.mean(dim[:5])) or 1e-30
                    dim_txt = tr("×{0:.2f} vs início").format(dim[-1] / base_d)
                elif dim:
                    dim_txt = "calibrando…"
                else:
                    dim_txt = "—"
                try:
                    seg = np.asarray(data[sel][-int(3 * SAMPLE_RATE):], float)
                    onsets = emg_onset_tkeo(seg, SAMPLE_RATE)
                    if onsets:
                        durs = [o[1] - o[0] for o in onsets]
                        act_txt = tr("{0} (dur média {1:.0f} ms)").format(len(onsets), np.mean(durs)*1000)
                    else:
                        act_txt = "0"
                except Exception:
                    act_txt = "—"
                if hasattr(self, "emg_fatigue_metrics_lbl"):
                    self.emg_fatigue_metrics_lbl.setText(
                        tr("Inclinação MDF: {0}   ·   Dimitrov FInsm5: {1}   ·   Ativações TKEO "
                           "(últ. 3 s): {2}").format(slope_txt, dim_txt, act_txt))
                # Status: queda atual
                if base and len(mdf) >= 3:
                    drop = (1.0 - float(np.mean(mdf[-3:])) / base) * 100.0
                    if hasattr(self, "emg_mnfdf_status_lbl"):
                        col = (SIGNAL_TYPE_COLORS["EMG"] if drop < 5
                               else COLORS["warning"] if drop < 15
                               else COLORS["error"])
                        self.emg_mnfdf_status_lbl.setText(
                            tr("Queda MDF: {0:+5.1f}% vs baseline ({1:.1f} Hz)").format(drop, base)
                        )
                        self.emg_mnfdf_status_lbl.setStyleSheet(f"color: {col}; font-weight: bold;")

        # ---- Indicadores globais (fadiga + co-contração + movimento) ----
        if hasattr(self, "emg_fatigue_lbl"):
            # Fadiga média: queda % da freq mediana vs baseline
            drops = []
            for ch, hist in self._emg_median_freq_history.items():
                base = self._emg_fatigue_baseline.get(ch)
                if base and base > 0 and len(hist) >= 3:
                    recent = float(np.mean(hist[-3:]))
                    drop = (1.0 - recent / base) * 100.0
                    drops.append(drop)
            if drops:
                mean_drop = float(np.mean(drops))
                if   mean_drop < 5:  color = SIGNAL_TYPE_COLORS["EMG"]; state = "OK"
                elif mean_drop < 15: color = COLORS["warning"];          state = "leve"
                else:                color = COLORS["error"];            state = "alta"
                self.emg_fatigue_lbl.setText(tr("Fadiga: {0:+5.1f}% ({1})").format(mean_drop, tr(state)))
                self.emg_fatigue_lbl.setStyleSheet(
                    f"color: {color}; font-weight: bold; padding: 4px 10px;"
                    f"border: 1px solid {COLORS['border']}; border-radius: 4px;")

        # Publica o envelope atual por canal para quem observa de fora — hoje o
        # mapa de co-contração, que precisa do valor AO VIVO para calibrar e
        # para desenhar o ponto de intenção.
        self._emg_env_atual = dict(ch_envelope_current)
        alvo = getattr(self, "_cocontr_dialog", None)
        if alvo is not None:
            try:
                alvo.alimentar(self._emg_env_atual)
            except RuntimeError:      # diálogo já destruído pelo Qt
                self._cocontr_dialog = None

        # ---- Co-contração e movimento dominante ----
        if hasattr(self, "emg_cocontraction_lbl"):
            cocontr_pairs = []
            dominant_moves = []
            for ch, env_val in ch_envelope_current.items():
                muscle = (self.config.emg_channel_muscle[ch]
                          if ch < len(self.config.emg_channel_muscle) else "(não definido)")
                if muscle == "(não definido)": continue
                info = COMMON_MUSCLES.get(muscle, {})
                antagonist = info.get("antagonist", "")
                if not antagonist: continue
                # Procura canal antagonista
                ant_ch = next((c for c in ch_envelope_current
                               if c < len(self.config.emg_channel_muscle)
                               and self.config.emg_channel_muscle[c] == antagonist), None)
                if ant_ch is None: continue
                ago_env = env_val
                ant_env = ch_envelope_current[ant_ch]
                if ago_env < 5 and ant_env < 5: continue  # ambos em repouso
                # Co-contração de Falconer-Winter: 2 * min / (a+b)
                cocontr = (2 * min(ago_env, ant_env)) / max(ago_env + ant_env, 1e-6) * 100.0
                cocontr_pairs.append(cocontr)
                # Movimento dominante: o agonista mais ativo
                if ago_env > ant_env * 1.2:
                    action = info.get("action", muscle)
                    dominant_moves.append(action)
                elif ant_env > ago_env * 1.2:
                    ant_info = COMMON_MUSCLES.get(antagonist, {})
                    action = ant_info.get("action", antagonist)
                    dominant_moves.append(action)
            if cocontr_pairs:
                mean_cc = float(np.mean(cocontr_pairs))
                self.emg_cocontraction_lbl.setText(f"{tr('Co-contração:')} {mean_cc:5.1f}%")
            else:
                self.emg_cocontraction_lbl.setText(tr("Co-contração: -- (sem par)"))
            if hasattr(self, "emg_movement_lbl"):
                if dominant_moves:
                    # Pega o mais comum
                    from collections import Counter as _C
                    top = _C(dominant_moves).most_common(1)[0][0]
                    self.emg_movement_lbl.setText(f"{tr('Movimento:')} {tr(top)}")
                else:
                    self.emg_movement_lbl.setText(tr("Movimento: --"))

    # ==================================================================
    # ECG / Coração — detecção de R-peak (Pan-Tompkins simplificado),
    # BPM, HRV (RMSSD, SDNN, pNN50) e Poincaré plot
    # ==================================================================
    def _build_ecg_tab(self):
        """Aba ECG — frequência cardíaca + HRV.

        Algoritmo:
            1. Bandpass 5-15 Hz (banda do QRS)
            2. Derivada (acentua bordas)
            3. Quadrado
            4. Média móvel (~150ms) = sinal MWA
            5. Threshold adaptativo (0.5 * média do MWA recente)
            6. Refratório: ignora picos < 200ms após o anterior
        """
        widget = QtWidgets.QWidget()
        outer = QtWidgets.QVBoxLayout(widget)
        outer.setContentsMargins(8, 8, 8, 8); outer.setSpacing(6)

        # === Controles superiores ===
        ctrl = QtWidgets.QHBoxLayout()
        ctrl.addWidget(QtWidgets.QLabel(tr("Canal ECG:")))
        self.ecg_channel_combo = QtWidgets.QComboBox()
        # Popula com canais marcados ECG; se nenhum, adiciona "Auto (1º canal ECG)"
        self._populate_ecg_channel_combo()
        self.ecg_channel_combo.currentIndexChanged.connect(self._ecg_reset_history)
        ctrl.addWidget(self.ecg_channel_combo)
        ctrl.addSpacing(20)
        # Coração anatômico que pulsa a cada batimento — ampliado: junto do BPM
        # é o par que o operador (e o próprio voluntário) lê de imediato.
        self.ecg_heart = HeartWidget()
        self.ecg_heart.setFixedSize(190, 205)
        self.ecg_heart.setToolTip(tr("Pulsa a cada batimento (pico R). Fica vermelho "
                                  "quando o ritmo está irregular."))
        ctrl.addWidget(self.ecg_heart)
        self._ecg_last_peak_count = 0
        ctrl.addSpacing(10)
        # BPM grande
        self.ecg_bpm_lbl = QtWidgets.QLabel(tr("-- bpm"))
        self.ecg_bpm_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['ECG']}; font-size: 26pt; font-weight: bold; "
            f"font-family: {FONT_DATA_STACK}; padding: 4px 16px;")
        self.ecg_bpm_lbl.setMinimumHeight(56)
        ctrl.addWidget(self.ecg_bpm_lbl)
        # LED de batimento (círculo pulsante — sem emoji)
        self.ecg_heartbeat_led = QtWidgets.QLabel("●")
        self.ecg_heartbeat_led.setStyleSheet(
            f"color: #555; font-size: 26pt; padding: 0 6px;")
        self.ecg_heartbeat_led.setToolTip(tr("Pisca a cada batimento detectado."))
        ctrl.addWidget(self.ecg_heartbeat_led)
        ctrl.addStretch()
        # Métricas HRV
        self.ecg_hrv_lbl = QtWidgets.QLabel(tr("RMSSD: --  SDNN: --  pNN50: --"))
        self.ecg_hrv_lbl.setStyleSheet(
            f"color: {COLORS['text_dim']}; font-family: {FONT_DATA_STACK};")
        ctrl.addWidget(self.ecg_hrv_lbl)
        # RMSSD/SDNN/pNN50 são índices de pesquisa (G38)
        self._register_advanced("ecg", self.ecg_hrv_lbl)
        btn_reset = QtWidgets.QPushButton(tr("Zerar"))
        btn_reset.setToolTip(tr("Recomeça a contagem dos batimentos."))
        btn_reset.clicked.connect(self._ecg_reset_history)
        ctrl.addWidget(btn_reset)
        outer.addLayout(ctrl)
        outer.addLayout(self._make_detail_toggle(
            "ecg", tr("Exame do coração — confira o traçado e a frequência.")))

        # === Splitter: sinal cru + sinal MWA (esquerda) / Poincaré (direita) ===
        split = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)

        # Painel esquerdo: 2 plots empilhados
        left = QtWidgets.QWidget()
        ll = QtWidgets.QVBoxLayout(left)
        ll.setContentsMargins(2, 2, 2, 2)

        # Rótulo honesto: esta curva recebe o sinal COMO ESTÁ no buffer. O
        # passa-banda 5-15 Hz é interno ao detector de picos (Pan-Tompkins) e
        # não é o que se vê aqui.
        self._ecg_raw_lbl = QtWidgets.QLabel(
            tr("Sinal ECG (como registrado) + picos R detectados"))
        ll.addWidget(self._ecg_raw_lbl)
        self.ecg_raw_plot = pg.PlotWidget(enableMenu=False)
        self.ecg_raw_plot.showGrid(x=True, y=True, alpha=0.15)
        self.ecg_raw_plot.setLabel("left", tr("Amplitude"), units="µV")
        self.ecg_raw_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.ecg_raw_plot.setMenuEnabled(False)
        self.ecg_raw_curve = self.ecg_raw_plot.plot(
            pen=pg.mkPen(SIGNAL_TYPE_COLORS["ECG"], width=1.4))
        # Marcadores de R-peak (ScatterPlotItem)
        self.ecg_rpeak_scatter = pg.ScatterPlotItem(
            size=10, brush=pg.mkBrush("#ffff00"),
            pen=pg.mkPen("#ffffff", width=1), symbol="t")
        self.ecg_raw_plot.addItem(self.ecg_rpeak_scatter)
        ll.addWidget(self.ecg_raw_plot)

        # O MWA é o sinal INTERNO do detector de picos (derivada→quadrado→média
        # móvel). Não significa nada para quem aplica o exame — fica em Avançado.
        _lbl_mwa = QtWidgets.QLabel(tr("MWA (integral) + limiar"))
        ll.addWidget(_lbl_mwa)
        self.ecg_mwa_plot = pg.PlotWidget(enableMenu=False)
        self.ecg_mwa_plot.showGrid(x=True, y=True, alpha=0.15)
        self.ecg_mwa_plot.setLabel("left", "MWA", units="µV²")
        self.ecg_mwa_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.ecg_mwa_plot.setMenuEnabled(False)
        self.ecg_mwa_curve = self.ecg_mwa_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=1.2))
        self.ecg_threshold_line = pg.InfiniteLine(
            pos=0, angle=0,
            pen=pg.mkPen("#ff6677", style=QtCore.Qt.PenStyle.DashLine))
        self.ecg_mwa_plot.addItem(self.ecg_threshold_line)
        ll.addWidget(self.ecg_mwa_plot)

        # Sincronizar X dos dois plots
        self.ecg_mwa_plot.setXLink(self.ecg_raw_plot)

        split.addWidget(left)
        self._register_advanced("ecg", _lbl_mwa, self.ecg_mwa_plot)

        # Painel direito: tacograma + Poincaré
        right = QtWidgets.QWidget()
        rl = QtWidgets.QVBoxLayout(right)
        rl.setContentsMargins(2, 2, 2, 2)

        rl.addWidget(QtWidgets.QLabel(tr("Tacograma — intervalos RR (ms)")))
        self.ecg_tacho_plot = pg.PlotWidget(enableMenu=False)
        self.ecg_tacho_plot.showGrid(x=True, y=True, alpha=0.15)
        self.ecg_tacho_plot.setLabel("left", "RR", units="ms")
        # 'ms' ja e um prefixo: acima de 1000 o pyqtgraph escrevia "kms".
        self.ecg_tacho_plot.getAxis("left").enableAutoSIPrefix(False)
        self.ecg_tacho_plot.setLabel("bottom", tr("Batimento #"))
        self.ecg_tacho_plot.setMenuEnabled(False)
        self.ecg_tacho_curve = self.ecg_tacho_plot.plot(
            pen=pg.mkPen(SIGNAL_TYPE_COLORS["ECG"], width=1.4),
            symbol="o", symbolSize=4,
            symbolBrush=SIGNAL_TYPE_COLORS["ECG"], symbolPen=None)
        rl.addWidget(self.ecg_tacho_plot)

        rl.addWidget(QtWidgets.QLabel(tr("Poincaré — RR(n) × RR(n+1)")))
        self.ecg_poincare_plot = pg.PlotWidget(enableMenu=False)
        self.ecg_poincare_plot.showGrid(x=True, y=True, alpha=0.15)
        self.ecg_poincare_plot.setLabel("left",   "RR(n+1)", units="ms")
        self.ecg_poincare_plot.setLabel("bottom", "RR(n)",   units="ms")
        # Com aspecto travado a faixa de X passa de 1000 antes da de Y e os dois
        # eixos do grafico de identidade saiam em unidades diferentes (kms x ms).
        self.ecg_poincare_plot.getAxis("left").enableAutoSIPrefix(False)
        self.ecg_poincare_plot.getAxis("bottom").enableAutoSIPrefix(False)
        self.ecg_poincare_plot.setMenuEnabled(False)
        self.ecg_poincare_plot.setAspectLocked(True)
        # Linha identidade
        self.ecg_poincare_plot.addItem(pg.InfiniteLine(
            angle=45, pos=(0, 0),
            pen=pg.mkPen(COLORS["border"], style=QtCore.Qt.PenStyle.DashLine)))
        self.ecg_poincare_scatter = pg.ScatterPlotItem(
            size=6, brush=pg.mkBrush(SIGNAL_TYPE_COLORS["ECG"] + "aa"),
            pen=pg.mkPen(SIGNAL_TYPE_COLORS["ECG"]))
        self.ecg_poincare_plot.addItem(self.ecg_poincare_scatter)
        # Elipse SD1/SD2 ajustada (assinatura Kubios): semi-eixos 2·SD1 (transversal)
        # e 2·SD2 (longitudinal), girada 45° e centrada na média RR.
        self.ecg_poincare_ellipse = self.ecg_poincare_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=2))
        self.ecg_poincare_axes = self.ecg_poincare_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=1,
                         style=QtCore.Qt.PenStyle.DotLine))
        rl.addWidget(self.ecg_poincare_plot)

        split.addWidget(right)
        split.setSizes([720, 600])
        outer.addWidget(split, stretch=2)

        # ===================================================================
        # SEÇÃO: Zonas Karvonen + Arritmia + Recuperação + LF/HF
        # ===================================================================
        zone_group = QtWidgets.QGroupBox(tr("Zonas de Treino (Karvonen) + Detecção de Arritmia + Recuperação"))
        zg = QtWidgets.QHBoxLayout(zone_group)
        zg.setContentsMargins(8, 6, 8, 8); zg.setSpacing(10)

        # Idade (afeta HRmax)
        age_box = QtWidgets.QVBoxLayout()
        age_box.addWidget(QtWidgets.QLabel(tr("Idade (HRmax = 220 - idade):")))
        age_row = QtWidgets.QHBoxLayout()
        self.ecg_age_spin = QtWidgets.QSpinBox()
        self.ecg_age_spin.setRange(5, 120); self.ecg_age_spin.setValue(25)
        self.ecg_age_spin.setSuffix(tr(" anos"))
        # Tenta pegar do voluntário ativo
        try:
            active = self.volunteers.get_active() if hasattr(self.volunteers, "get_active") else None
            if active and "idade" in active:
                idade = int(active.get("idade", 25))
                if 5 <= idade <= 120:
                    self.ecg_age_spin.setValue(idade)
        except Exception:
            pass
        self.ecg_age_spin.valueChanged.connect(self._ecg_recompute_zones)
        age_row.addWidget(self.ecg_age_spin)
        self.ecg_hrmax_lbl = QtWidgets.QLabel(tr("HRmax: 195 bpm"))
        self.ecg_hrmax_lbl.setStyleSheet(
            f"color: {COLORS['warning']}; font-family: {FONT_DATA_STACK}; font-weight: bold;")
        age_row.addWidget(self.ecg_hrmax_lbl)
        age_row.addStretch()
        age_box.addLayout(age_row)
        zg.addLayout(age_box)
        zg.addSpacing(15)

        # Zona atual
        zone_box = QtWidgets.QVBoxLayout()
        self.ecg_zone_lbl = QtWidgets.QLabel("Z1")
        self.ecg_zone_lbl.setStyleSheet(
            f"color: {COLORS['accent']}; font-size: 22pt; font-weight: bold;"
            f"padding: 6px 14px; border: 2px solid {COLORS['border']}; border-radius: 6px;")
        self.ecg_zone_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.ecg_zone_lbl.setToolTip(
            tr("Zona Karvonen:\n"
            "  Z1 (50-60%): Recuperação ativa\n"
            "  Z2 (60-70%): Aeróbica leve - queima de gordura\n"
            "  Z3 (70-80%): Aeróbica - condicionamento\n"
            "  Z4 (80-90%): Limiar anaeróbico\n"
            "  Z5 (90-100%): Máximo / VO2max")
        )
        zone_box.addWidget(self.ecg_zone_lbl)
        zone_name_lbl = QtWidgets.QLabel(tr("Zona de Treino"))
        zone_name_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        zone_name_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        zone_box.addWidget(zone_name_lbl)
        zg.addLayout(zone_box)
        zg.addSpacing(10)

        # Arritmia
        arr_box = QtWidgets.QVBoxLayout()
        self.ecg_arrhythmia_lbl = QtWidgets.QLabel("--")
        self.ecg_arrhythmia_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['ECG']}; font-size: 18pt; font-weight: bold;"
            f"padding: 6px 12px; border: 2px solid {COLORS['border']}; border-radius: 6px;")
        self.ecg_arrhythmia_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.ecg_arrhythmia_lbl.setMinimumWidth(160)
        self.ecg_arrhythmia_lbl.setToolTip(
            tr("Detecção simples baseada em coef. de variação dos intervalos RR:\n"
            "  CV<5%: Ritmo Regular\n  CV 5-15%: Variável (normal)\n"
            "  CV>15%: Irregular (verificar)\n"
            "Não é diagnóstico clínico — alerta heurístico.")
        )
        arr_box.addWidget(self.ecg_arrhythmia_lbl)
        arr_lbl = QtWidgets.QLabel(tr("Ritmo"))
        arr_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        arr_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        arr_box.addWidget(arr_lbl)
        zg.addLayout(arr_box)
        zg.addSpacing(10)

        # BPM pico / Recuperação
        rec_box = QtWidgets.QVBoxLayout()
        self.ecg_peak_bpm_lbl = QtWidgets.QLabel(tr("Pico: -- bpm"))
        self.ecg_peak_bpm_lbl.setStyleSheet(
            f"color: {COLORS['warning']}; font-family: {FONT_DATA_STACK}; font-weight: bold;")
        rec_box.addWidget(self.ecg_peak_bpm_lbl)
        self.ecg_recovery_lbl = QtWidgets.QLabel(tr("Recuperação: --"))
        self.ecg_recovery_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['ECG']}; font-family: {FONT_DATA_STACK};")
        rec_box.addWidget(self.ecg_recovery_lbl)
        # HRV freq (LF/HF)
        self.ecg_lfhf_lbl = QtWidgets.QLabel("LF/HF: --")
        self.ecg_lfhf_lbl.setStyleSheet(
            f"color: {COLORS['accent']}; font-family: {FONT_DATA_STACK};")
        self.ecg_lfhf_lbl.setToolTip(
            tr("Razão LF/HF (HRV espectral):\n"
            "LF = 0.04-0.15 Hz (simpático+parassimpático)\n"
            "HF = 0.15-0.4 Hz (parassimpático)\n"
            "Razão >2 sugere predominância simpática (estresse).")
        )
        rec_box.addWidget(self.ecg_lfhf_lbl)
        zg.addLayout(rec_box)
        zg.addStretch()

        outer.addWidget(zone_group)

        # ===================================================================
        # SEÇÃO: HRV não-linear (Kubios-style) — DFA, Entropia, Poincaré SD1/SD2
        # ===================================================================
        nlhrv_group = QtWidgets.QGroupBox(tr("HRV não-linear (Kubios-style) — DFA, Entropia, Poincaré"))
        nlhrv = QtWidgets.QHBoxLayout(nlhrv_group)
        nlhrv.setContentsMargins(8, 6, 8, 8); nlhrv.setSpacing(12)
        # Card DFA α1 / α2
        dfa_box = QtWidgets.QVBoxLayout()
        self.ecg_dfa_lbl = QtWidgets.QLabel(tr("DFA α1: --  α2: --"))
        self.ecg_dfa_lbl.setStyleSheet(
            f"color: {COLORS['accent']}; font-size: 14pt; font-weight: bold;"
            f"font-family: {FONT_DATA_STACK}; padding: 4px 8px;")
        self.ecg_dfa_lbl.setMinimumHeight(40)
        self.ecg_dfa_lbl.setToolTip(
            tr("Detrended Fluctuation Analysis:\n"
            "α1 (escalas curtas 4-16): saudável ~1.0; fadiga/risco <0.75\n"
            "α2 (escalas longas 16-64): saudável ~1.0\n"
            "Peng et al. (1995) — biomarcador de saúde cardíaca.")
        )
        dfa_box.addWidget(self.ecg_dfa_lbl)
        dfa_lbl2 = QtWidgets.QLabel(tr("Detrended Fluctuation Analysis"))
        dfa_lbl2.setStyleSheet(f"color: {COLORS['text_dim']};")
        dfa_box.addWidget(dfa_lbl2)
        nlhrv.addLayout(dfa_box)

        # Card Entropia
        ent_box = QtWidgets.QVBoxLayout()
        self.ecg_entropy_lbl = QtWidgets.QLabel(tr("ApEn: --  SampEn: --"))
        self.ecg_entropy_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['ECG']}; font-size: 14pt; font-weight: bold;"
            f"font-family: {FONT_DATA_STACK}; padding: 4px 8px;")
        self.ecg_entropy_lbl.setMinimumHeight(40)
        self.ecg_entropy_lbl.setToolTip(
            tr("Entropia da série RR (complexidade/regularidade):\n"
            "  ApEn  (Pincus 1991): 0.5-1.5 é fisiológico\n"
            "  SampEn (Richman 2000): mais robusto, baseado em ApEn\n"
            "Valores baixos = ritmo regular; altos = caótico.")
        )
        ent_box.addWidget(self.ecg_entropy_lbl)
        ent_lbl2 = QtWidgets.QLabel(tr("Entropia da série RR"))
        ent_lbl2.setStyleSheet(f"color: {COLORS['text_dim']};")
        ent_box.addWidget(ent_lbl2)
        nlhrv.addLayout(ent_box)

        # Card Poincaré SD1/SD2
        poin_box = QtWidgets.QVBoxLayout()
        self.ecg_poincare_sd_lbl = QtWidgets.QLabel("SD1: --  SD2: --  SD1/SD2: --")
        self.ecg_poincare_sd_lbl.setStyleSheet(
            f"color: {COLORS['warning']}; font-size: 14pt; font-weight: bold;"
            f"font-family: {FONT_DATA_STACK}; padding: 4px 8px;")
        self.ecg_poincare_sd_lbl.setMinimumHeight(40)
        self.ecg_poincare_sd_lbl.setToolTip(
            tr("Poincaré plot — descritores nuvem RR(n) × RR(n+1):\n"
            "  SD1: dispersão perpendicular (curto prazo, parassimpático)\n"
            "  SD2: dispersão paralela (longo prazo, simpático+parassimpático)\n"
            "  SD1/SD2: razão de balanço autonômico")
        )
        poin_box.addWidget(self.ecg_poincare_sd_lbl)
        poin_lbl = QtWidgets.QLabel(tr("Poincaré (Brennan 2001)"))
        poin_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        poin_box.addWidget(poin_lbl)
        nlhrv.addLayout(poin_box)
        nlhrv.addStretch()

        outer.addWidget(nlhrv_group)

        # ===================================================================
        # SEÇÃO: HRV Espectral (PSD) + Geométrica (histograma RR)
        # ===================================================================
        spec_group = QtWidgets.QGroupBox(tr("HRV Espectral (Welch/FFT) + Geométrica — bandas VLF/LF/HF e índice triangular"))
        sgl = QtWidgets.QHBoxLayout(spec_group)
        sgl.setContentsMargins(6, 6, 6, 6); sgl.setSpacing(8)

        # --- Espectro HRV (esquerda) ---
        psd_col = QtWidgets.QVBoxLayout(); psd_col.setSpacing(2)
        psd_col.addWidget(QtWidgets.QLabel(
            tr("Espectro HRV — PSD da série RR interpolada a 4 Hz (VLF · LF · HF)")))
        self.ecg_psd_plot = pg.PlotWidget(enableMenu=False)
        self.ecg_psd_plot.showGrid(x=True, y=True, alpha=0.15)
        self.ecg_psd_plot.setLabel("left", "PSD", units="ms²/Hz")
        self.ecg_psd_plot.setLabel("bottom", tr("Frequência"), units="Hz")
        self.ecg_psd_plot.setMenuEnabled(False)
        self.ecg_psd_plot.setXRange(0, 0.5)
        # Bandas sombreadas: VLF (0.0033-0.04), LF (0.04-0.15), HF (0.15-0.40)
        for lo, hi, col in ((0.0033, 0.04, "#8888ff"),
                            (0.04, 0.15, "#eebb33"),
                            (0.15, 0.40, "#44dd88")):
            reg = pg.LinearRegionItem(
                values=(lo, hi), movable=False,
                brush=pg.mkBrush(col + "22"), pen=pg.mkPen(None))
            reg.setZValue(-10)
            self.ecg_psd_plot.addItem(reg)
        self.ecg_psd_curve = self.ecg_psd_plot.plot(
            pen=pg.mkPen(SIGNAL_TYPE_COLORS["ECG"], width=1.6),
            fillLevel=0, brush=pg.mkBrush(SIGNAL_TYPE_COLORS["ECG"] + "33"))
        psd_col.addWidget(self.ecg_psd_plot)
        self.ecg_psd_lbl = QtWidgets.QLabel(
            tr("VLF: --  LF: --  HF: -- ms²  ·  Total: --  ·  LFnu/HFnu: --/--"))
        self.ecg_psd_lbl.setStyleSheet(
            f"color: {COLORS['text_dim']}; font-family: {FONT_DATA_STACK};")
        self.ecg_psd_lbl.setToolTip(
            tr("Densidade espectral de potência (PSD) da série RR (Task Force 1996):\n"
            "  VLF (0.0033-0.04 Hz): termorregulação / RAAS (precisa registro longo)\n"
            "  LF  (0.04-0.15 Hz): barorreflexo (simpático + parassimpático)\n"
            "  HF  (0.15-0.40 Hz): parassimpático (arritmia sinusal respiratória)\n"
            "  n.u. = potência normalizada = banda / (LF+HF) × 100"))
        psd_col.addWidget(self.ecg_psd_lbl)
        sgl.addLayout(psd_col, stretch=3)

        # --- Histograma RR geométrico (direita) ---
        hist_col = QtWidgets.QVBoxLayout(); hist_col.setSpacing(2)
        hist_col.addWidget(QtWidgets.QLabel(
            tr("Histograma RR — índice triangular (HTI) e TINN")))
        self.ecg_rrhist_plot = pg.PlotWidget(enableMenu=False)
        self.ecg_rrhist_plot.showGrid(x=True, y=True, alpha=0.15)
        self.ecg_rrhist_plot.setLabel("left", tr("Contagem"))
        self.ecg_rrhist_plot.setLabel("bottom", "RR", units="ms")
        self.ecg_rrhist_plot.getAxis("bottom").enableAutoSIPrefix(False)
        self.ecg_rrhist_plot.setMenuEnabled(False)
        self.ecg_rrhist_bars = pg.BarGraphItem(
            x=[0], height=[0], width=7, brush=SIGNAL_TYPE_COLORS["ECG"] + "cc")
        self.ecg_rrhist_plot.addItem(self.ecg_rrhist_bars)
        # Triângulo interpolado (base = TINN, ápice no modo)
        self.ecg_rrhist_tri = self.ecg_rrhist_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=1.6,
                         style=QtCore.Qt.PenStyle.DashLine))
        hist_col.addWidget(self.ecg_rrhist_plot)
        self.ecg_hti_lbl = QtWidgets.QLabel(tr("HTI: --  TINN: -- ms"))
        self.ecg_hti_lbl.setStyleSheet(
            f"color: {COLORS['text_dim']}; font-family: {FONT_DATA_STACK};")
        self.ecg_hti_lbl.setToolTip(
            tr("HRV geométrica (robusta a ectópicos; Task Force 1996):\n"
            "  HTI (índice triangular) = N total de RR / altura do modo do histograma\n"
            "  TINN = largura da base do triângulo interpolado (ms)\n"
            "Valores maiores = maior variabilidade global (bins de 1/128 s ≈ 7,8 ms)."))
        hist_col.addWidget(self.ecg_hti_lbl)
        sgl.addLayout(hist_col, stretch=2)

        outer.addWidget(spec_group)
        # Blocos de pesquisa do ECG: tacograma+Poincaré (painel direito), zonas
        # de treino, HRV não-linear (DFA/entropia) e HRV espectral/geométrica.
        # Vários deles exigem 2-5 min de registro e ficam vazios num exame curto.
        self._register_advanced("ecg", right, zone_group, nlhrv_group, spec_group)
        self._apply_detail_level("ecg")

        # Estado interno
        self._ecg_rpeak_times = []    # lista de timestamps (s) dos picos R
        self._ecg_rr_intervals_ms = []  # ms entre picos
        self._ecg_last_beat_t = 0.0    # último tempo de batimento (para LED pulsante)
        self._ecg_threshold_adaptive = 0.0
        self._ecg_peak_bpm = 0.0       # BPM máximo observado na sessão
        self._ecg_peak_bpm_t = 0.0     # momento do pico
        self._ecg_recovery_60s = None  # diferença BPM 60s após o pico
        self._ecg_recompute_zones()
        return widget

    def _ecg_recompute_zones(self):
        """Recalcula HRmax (220 - idade) e exibe."""
        if not hasattr(self, "ecg_age_spin"): return
        age = self.ecg_age_spin.value()
        hrmax = 220 - age
        self._ecg_hrmax = hrmax
        if hasattr(self, "ecg_hrmax_lbl"):
            self.ecg_hrmax_lbl.setText(f"HRmax: {hrmax} bpm")

    def _populate_ecg_channel_combo(self):
        """(Re)popula combo com canais marcados ECG."""
        if not hasattr(self, "ecg_channel_combo"): return
        cur = self.ecg_channel_combo.currentText()
        self.ecg_channel_combo.blockSignals(True)
        self.ecg_channel_combo.clear()
        # so' os canais que a placa tem (ver _joy_repopulate_combos)
        ecg_channels = [ch for ch in range(self.num_channels)
                        if ch < len(self.config.channel_signal_types)
                        and self.config.channel_signal_types[ch] == "ECG"]
        if not ecg_channels:
            self.ecg_channel_combo.addItem(self._msg_sem_canal("ECG"), -1)
        else:
            for ch in ecg_channels:
                self.ecg_channel_combo.addItem(f"CH{ch+1}", ch)
        # Restaura seleção
        idx = self.ecg_channel_combo.findText(cur)
        if idx >= 0:
            self.ecg_channel_combo.setCurrentIndex(idx)
        self.ecg_channel_combo.blockSignals(False)

    def _ecg_reset_history(self):
        """Limpa histórico de picos R e RR."""
        # _ecg_rpeak_times agora guarda os picos R da SESSÃO inteira — é dele que
        # sai toda a série RR do HRV —, então zerar aqui é o que separa um
        # registro do seguinte. _ecg_nl_last_t volta a 0 para o bloco não-linear
        # recalcular na primeira oportunidade, sem esperar o período de throttle.
        self._ecg_rpeak_times = []
        self._ecg_rr_intervals_ms = []
        self._ecg_nl_last_t = 0.0
        if hasattr(self, "ecg_bpm_lbl"):
            self.ecg_bpm_lbl.setText(tr("-- bpm"))
        if hasattr(self, "ecg_hrv_lbl"):
            self.ecg_hrv_lbl.setText(tr("RMSSD: --  SDNN: --  pNN50: --"))
        if hasattr(self, "ecg_rpeak_scatter"):
            self.ecg_rpeak_scatter.setData([], [])
        if hasattr(self, "ecg_tacho_curve"):
            self.ecg_tacho_curve.setData([], [])
        if hasattr(self, "ecg_poincare_scatter"):
            self.ecg_poincare_scatter.setData([], [])
        if hasattr(self, "ecg_psd_curve"):
            self.ecg_psd_curve.setData([], [])
            self.ecg_psd_lbl.setText(
                tr("VLF: --  LF: --  HF: -- ms²  ·  Total: --  ·  LFnu/HFnu: --/--"))
        if hasattr(self, "ecg_rrhist_bars"):
            self.ecg_rrhist_bars.setOpts(x=[0], height=[0])
            self.ecg_rrhist_tri.setData([], [])
            self.ecg_hti_lbl.setText(tr("HTI: --  TINN: -- ms"))

    def _pan_tompkins_detect(self, signal, fs):
        """Pan-Tompkins simplificado. Retorna (indices_dos_picos_R, mwa_signal, threshold).

        Etapas: bandpass 5-15 Hz (aplicado aqui) -> derivada -> quadrado
        -> média móvel ~150ms -> threshold adaptativo + refratário 200ms.
        """
        n = len(signal)
        if n < int(fs * 0.5):
            return np.array([], dtype=int), np.zeros(n), 0.0
        signal = np.asarray(signal, dtype=float)
        # Bandpass 5-15 Hz do Pan-Tompkins — NAO assume filtragem previa (o filtro
        # global do app e banda-EEG); remove deriva de linha de base e ruido alto.
        try:
            ny = 0.5 * fs
            lo, hi = 5.0 / ny, min(15.0, ny * 0.95) / ny
            if 0 < lo < hi < 1 and np.all(np.isfinite(signal)):
                b, a = scipy_signal.butter(2, [lo, hi], btype="band")
                signal = scipy_signal.filtfilt(b, a, signal)
        except Exception:
            pass
        # Derivada
        diff = np.diff(signal, prepend=signal[0])
        # Quadrado
        sq = diff * diff
        # MWA (~150ms)
        w = max(2, int(fs * 0.15))
        kernel = np.ones(w) / w
        mwa = np.convolve(sq, kernel, mode="same")
        # Threshold adaptativo: 50% da média dos últimos 5s
        recent = mwa[-int(fs * 5):] if n >= int(fs * 5) else mwa
        peak_baseline = float(np.percentile(recent, 90))
        noise_baseline = float(np.percentile(recent, 30))
        threshold = noise_baseline + 0.5 * (peak_baseline - noise_baseline)
        threshold = max(threshold, 1e-6)
        # Detecção local de máximos acima do threshold com refratário 200ms
        refractory = int(fs * 0.2)
        peaks = []
        i = 1
        while i < n - 1:
            if mwa[i] > threshold and mwa[i] >= mwa[i-1] and mwa[i] >= mwa[i+1]:
                # encontra o máximo local em uma janela de ±25ms
                lo = max(0, i - int(fs * 0.025))
                hi = min(n, i + int(fs * 0.025) + 1)
                local_max = lo + int(np.argmax(mwa[lo:hi]))
                if not peaks or (local_max - peaks[-1]) >= refractory:
                    peaks.append(local_max)
                i = local_max + refractory
            else:
                i += 1
        # REFINO NA ONDA R. Até aqui o pico é o máximo do ENVELOPE (MWA), que é
        # energia integrada em 150 ms: ele marca a REGIÃO do QRS, não o instante
        # da onda R. O viés é quase constante (~-47 ms) e some na diferença, mas
        # o JITTER não: medido contra 374 batimentos de RR conhecido, ele espalha
        # ±19 ms, entra em quadratura no RMSSD e o inflou de 22 ms reais para
        # 52 ms — e RMSSD é justamente o índice vagal de referência. Procurar o
        # extremo do sinal FILTRADO dentro da janela do envelope devolve o
        # instante da onda R. Usa |sinal| porque a derivação pode ter R negativa
        # (aVR, eletrodo invertido) — aí o extremo é o mínimo.
        if peaks:
            meia = max(2, int(fs * 0.06))    # ±60 ms: cobre o QRS, não o vizinho
            abs_sig = np.abs(signal)
            peaks = [max(0, p - meia) + int(np.argmax(
                abs_sig[max(0, p - meia):min(n, p + meia + 1)])) for p in peaks]
        return np.array(peaks, dtype=int), mwa, threshold

    def _update_ecg_view(self):
        """Atualiza ECG: roda Pan-Tompkins na janela atual, computa BPM e HRV."""
        if not hasattr(self, "ecg_raw_plot"): return
        # Canal selecionado
        ch = self.ecg_channel_combo.currentData() if hasattr(self, "ecg_channel_combo") else -1
        if ch is None or ch < 0:
            return
        if ch >= len(self.config.channel_signal_types) or \
                self.config.channel_signal_types[ch] != "ECG":
            return
        data = self._ordered_buffer()
        if data.shape[1] < int(SAMPLE_RATE * 1):
            return
        sig = data[ch].astype(np.float64)
        t_axis = np.arange(len(sig)) / SAMPLE_RATE
        # Atualiza curva crua (assumimos filtro bandpass já configurado no geral)
        self.ecg_raw_curve.setData(t_axis, sig)
        # Pan-Tompkins
        peaks, mwa, thr = self._pan_tompkins_detect(sig, SAMPLE_RATE)
        self.ecg_mwa_curve.setData(t_axis, mwa)
        self.ecg_threshold_line.setPos(thr)
        if len(peaks) > 0:
            self.ecg_rpeak_scatter.setData(
                t_axis[peaks].tolist(),
                sig[peaks].tolist())
            # RR da JANELA (10 s) — daqui saem só BPM, LED e o detector de
            # arritmia, que são leituras instantâneas e não índices de HRV.
            rr_samples = np.diff(peaks)
            rr_ms = rr_samples * 1000.0 / SAMPLE_RATE
            # Filtra outliers (faixa fisiológica 300-2000 ms ~ 30-200 bpm)
            rr_ms = rr_ms[(rr_ms > 300) & (rr_ms < 2000)]
            # SÉRIE RR DA SESSÃO. Antes daqui saía apenas
            # self._ecg_rr_intervals_ms = list(rr_ms): a cada refresh a história
            # inteira era descartada e TODO o painel de HRV era calculado sobre
            # os ~11 RR da janela de 10 s. Os portões herdados disso eram
            # inalcançáveis — o >= 32 do bloco não-linear pedia 198 bpm e o
            # >= 20 do espectral pedia 126 bpm dentro de 10 s — e o aviso < 120
            # nunca podia ser falso, porque em 10 s cabem no máximo 32 RR.
            # Agora os picos R entram numa série em tempo ABSOLUTO da sessão;
            # comparar com o último pico já registrado deduplica os batimentos
            # que reaparecem na janela seguinte, já que as janelas consecutivas
            # se sobrepõem.
            # ZONA DE BORDA. Como cada pico entra na série no PRIMEIRO
            # avistamento, sem esta guarda ele entraria sempre pela cauda da
            # janela — exatamente onde o transitório do filtfilt do detector
            # deforma o QRS. Medido: com a série montada assim o RMSSD dava
            # 22,8 ms contra 18,0 ms reais, embora o detector isolado acertasse
            # 18,2 ms. Ignorar os últimos 250 ms só adia o batimento por alguns
            # refreshes (o timer anda 50 ms), e ele entra já no miolo da janela.
            guarda = int(SAMPLE_RATE * 0.25)
            t_win0 = (int(getattr(self, "samples_total", 0)) - len(sig)) / SAMPLE_RATE
            t_last = self._ecg_rpeak_times[-1] if self._ecg_rpeak_times else -1e9
            miolo = peaks[peaks < max(1, len(sig) - guarda)]
            for t_pk in (t_win0 + miolo / SAMPLE_RATE):
                if t_pk > t_last + 0.2:      # 200 ms = refratário do Pan-Tompkins
                    t_last = float(t_pk)
                    self._ecg_rpeak_times.append(t_last)
            if len(self._ecg_rpeak_times) > ECG_RR_HISTORY_MAX:
                del self._ecg_rpeak_times[:-ECG_RR_HISTORY_MAX]
            rr_hist = np.diff(np.asarray(self._ecg_rpeak_times, dtype=np.float64))
            rr_hist = rr_hist * 1000.0
            rr_hist = rr_hist[(rr_hist > 300) & (rr_hist < 2000)]
            # CORREÇÃO DE ECTÓPICOS (Lipponen-Tarvainen) — obrigatória a montante
            # do HRV: um batimento ectópico corrompe RMSSD/HF. Anota os corrigidos.
            rr_hist, ecto_idx = correct_ectopic_rr(rr_hist, threshold=0.30)
            rr_hist = np.asarray(rr_hist, dtype=np.float64)
            self._ecg_ectopic_count = len(ecto_idx)
            self._ecg_rr_intervals_ms = list(rr_hist)
            n_hist = len(rr_hist)
            if len(rr_ms) > 0:
                # BPM = 60000/média RR
                mean_rr = float(np.mean(rr_ms[-10:]))  # média dos últimos 10
                bpm = 60000.0 / mean_rr if mean_rr > 0 else 0
                # Cor por faixa: <50 azul (baixa), 50-100 verde, 100-150 amarelo, >150 vermelho
                if bpm < 50:
                    color = "#88aaff"
                elif bpm < 100:
                    color = SIGNAL_TYPE_COLORS["ECG"]
                elif bpm < 150:
                    color = "#eebb33"
                else:
                    color = "#ee5566"
                self.ecg_bpm_lbl.setText(f"{bpm:.0f} bpm")
                self.ecg_bpm_lbl.setStyleSheet(
                    f"color: {color}; font-size: 26pt; font-weight: bold; "
                    f"font-family: {FONT_DATA_STACK}; padding: 4px 16px;")
                if hasattr(self, "ecg_heart"):
                    self.ecg_heart.set_bpm(bpm)
                # HRV no domínio do tempo — sobre a série ACUMULADA, e cada
                # índice só é impresso quando tem N; senão sai "—" e o que falta.
                p_rm = hrv_pendente(n_hist, "rmssd")
                p_sd = hrv_pendente(n_hist, "sdnn")
                if n_hist >= 2:
                    d_h = np.diff(rr_hist)
                    s_rm = p_rm or f"{float(np.sqrt(np.mean(d_h * d_h))):5.1f} ms"
                    s_sd = p_sd or f"{float(np.std(rr_hist)):5.1f} ms"
                    s_pn = p_sd or f"{float(np.sum(np.abs(d_h) > 50) / len(d_h) * 100):4.1f}%"
                else:
                    s_rm, s_sd, s_pn = p_rm, p_sd, p_sd
                self.ecg_hrv_lbl.setText(
                    f"RMSSD: {s_rm}  SDNN: {s_sd}  pNN50: {s_pn}")
                # Tacograma e Poincaré são GRÁFICOS, não índices: podem mostrar a
                # série inteira desde o primeiro batimento, sem mínimo.
                self.ecg_tacho_curve.setData(np.arange(n_hist), rr_hist)
                if n_hist >= 2:
                    self.ecg_poincare_scatter.setData(
                        rr_hist[:-1].tolist(), rr_hist[1:].tolist())
                # LED pulsante: se o último pico está nos últimos 200ms da janela
                last_peak_t = float(t_axis[peaks[-1]])
                last_t = float(t_axis[-1])
                if (last_t - last_peak_t) < 0.25:
                    self.ecg_heartbeat_led.setStyleSheet(
                        f"color: {SIGNAL_TYPE_COLORS['ECG']}; font-size: 26pt; padding: 0 6px;")
                else:
                    self.ecg_heartbeat_led.setStyleSheet(
                        f"color: #555; font-size: 26pt; padding: 0 6px;")
                # Coração anatômico: pulsa 1x por batimento (latch no pico recente)
                fresh = (last_t - last_peak_t) < 0.15
                if hasattr(self, "ecg_heart"):
                    if fresh and not getattr(self, "_ecg_beat_latched", False):
                        self.ecg_heart.beat()
                        self._ecg_beat_latched = True
                    elif not fresh:
                        self._ecg_beat_latched = False

                # ===== ZONA KARVONEN =====
                hrmax = getattr(self, "_ecg_hrmax", 195)
                # HR reserve usa HRrest = 70 como aproximação; uso direto % HRmax
                pct_hrmax = (bpm / hrmax) * 100.0 if hrmax > 0 else 0
                if   pct_hrmax < 60:  zone, zc = "Z1", "#88aaff"
                elif pct_hrmax < 70:  zone, zc = "Z2", SIGNAL_TYPE_COLORS["EoG"]
                elif pct_hrmax < 80:  zone, zc = "Z3", SIGNAL_TYPE_COLORS["EEG"]
                elif pct_hrmax < 90:  zone, zc = "Z4", COLORS["warning"]
                else:                 zone, zc = "Z5", COLORS["error"]
                if hasattr(self, "ecg_zone_lbl"):
                    self.ecg_zone_lbl.setText(f"{zone}  {pct_hrmax:.0f}%")
                    self.ecg_zone_lbl.setStyleSheet(
                        f"color: {zc}; font-size: 22pt; font-weight: bold;"
                        f"padding: 6px 14px; border: 2px solid {zc}; border-radius: 6px;")

                # ===== ARRITMIA (coef. variação RR) =====
                if hasattr(self, "ecg_arrhythmia_lbl") and len(rr_ms) >= 5:
                    cv = (float(np.std(rr_ms)) / max(float(np.mean(rr_ms)), 1e-6)) * 100.0
                    # outliers (RR > 1.5x mean ou < 0.5x mean)
                    mean_rr = float(np.mean(rr_ms))
                    outliers = np.sum((rr_ms > 1.5 * mean_rr) | (rr_ms < 0.5 * mean_rr))
                    if   cv < 5 and outliers == 0: status = "Regular";    sc = SIGNAL_TYPE_COLORS["ECG"]
                    elif cv < 15 and outliers <= 1: status = "Variável";  sc = COLORS["accent"]
                    elif cv < 25:                  status = "Irregular"; sc = COLORS["warning"]
                    else:                          status = "Verificar"; sc = COLORS["error"]
                    self.ecg_arrhythmia_lbl.setText(f"{tr(status)}\nCV={cv:.0f}%")
                    self.ecg_arrhythmia_lbl.setStyleSheet(
                        f"color: {sc}; font-size: 14pt; font-weight: bold;"
                        f"padding: 6px 12px; border: 2px solid {sc}; border-radius: 6px;")
                    # O coração agora cumpre o que o tooltip promete: fica em
                    # alerta quando o ritmo sai do regular. `set_alert` existia
                    # desde sempre e nunca era chamado de lugar nenhum.
                    if hasattr(self, "ecg_heart"):
                        self.ecg_heart.set_alert(status in ("Irregular", "Verificar"))

                # ===== BPM PICO + RECUPERAÇÃO =====
                if bpm > self._ecg_peak_bpm:
                    self._ecg_peak_bpm = bpm
                    self._ecg_peak_bpm_t = time.time()
                    self._ecg_recovery_60s = None
                if hasattr(self, "ecg_peak_bpm_lbl"):
                    self.ecg_peak_bpm_lbl.setText(tr("Pico: {0:.0f} bpm").format(self._ecg_peak_bpm))
                # Recuperação: queda de BPM 60s após o pico
                if self._ecg_peak_bpm > 0:
                    elapsed = time.time() - self._ecg_peak_bpm_t
                    if 50 < elapsed < 70 and self._ecg_recovery_60s is None:
                        self._ecg_recovery_60s = self._ecg_peak_bpm - bpm
                    if self._ecg_recovery_60s is not None:
                        if   self._ecg_recovery_60s >= 25: rec_text = "Excelente"; rc = SIGNAL_TYPE_COLORS["EEG"]
                        elif self._ecg_recovery_60s >= 15: rec_text = "Boa";       rc = SIGNAL_TYPE_COLORS["ECG"]
                        elif self._ecg_recovery_60s >= 5:  rec_text = "Lenta";     rc = COLORS["warning"]
                        else:                              rec_text = "Pobre";     rc = COLORS["error"]
                        if hasattr(self, "ecg_recovery_lbl"):
                            self.ecg_recovery_lbl.setText(
                                tr("Recuperação 60s: -{0:.0f} bpm ({1})").format(self._ecg_recovery_60s, rec_text))
                            self.ecg_recovery_lbl.setStyleSheet(
                                f"color: {rc}; font-family: {FONT_DATA_STACK};")

                # ===== LF/HF (HRV espectral) =====
                # O portão era len(rr_ms) >= 20 sobre a janela de 10 s: exigia
                # 126 bpm só para rodar e, quando rodava, estimava a banda LF
                # (0,04 Hz = 25 s de período) a partir de 10 s de sinal.
                p_lfhf = hrv_pendente(n_hist, "lfhf")
                if hasattr(self, "ecg_lfhf_lbl") and p_lfhf:
                    self.ecg_lfhf_lbl.setText(f"LF/HF: {p_lfhf}")
                    if hasattr(self, "ecg_psd_lbl"):
                        self.ecg_psd_lbl.setText(f"VLF/LF/HF: {p_lfhf}")
                if hasattr(self, "ecg_lfhf_lbl") and not p_lfhf:
                    try:
                        # Interpola RR a 4 Hz (tempo regular)
                        t_rr = np.cumsum(rr_hist) / 1000.0  # tempo cumulativo em s
                        t_rr = t_rr - t_rr[0]
                        fs_interp = 4.0
                        n_interp = int(t_rr[-1] * fs_interp)
                        if n_interp > 16:
                            t_uniform = np.linspace(0, t_rr[-1], n_interp)
                            # Interpola a série da sessão, não a janela: a FFT
                            # abaixo só resolve 0,04 Hz se o trecho for longo.
                            rr_interp = np.interp(t_uniform, t_rr, rr_hist)
                            rr_interp = rr_interp - np.mean(rr_interp)
                            # FFT
                            spec = np.fft.rfft(rr_interp * np.hanning(len(rr_interp)))
                            freqs = np.fft.rfftfreq(len(rr_interp), 1.0 / fs_interp)
                            psd = (np.abs(spec) ** 2) / (len(rr_interp) * fs_interp)
                            lf_mask = (freqs >= 0.04) & (freqs < 0.15)
                            hf_mask = (freqs >= 0.15) & (freqs < 0.4)
                            lf_p = float(_TRAPEZOID(psd[lf_mask], freqs[lf_mask])) if lf_mask.any() else 0
                            hf_p = float(_TRAPEZOID(psd[hf_mask], freqs[hf_mask])) if hf_mask.any() else 0
                            ratio = lf_p / max(hf_p, 1e-9)
                            # O aviso antigo comparava com a janela de 10 s, onde
                            # cabem no máximo 32 RR: ficava aceso a sessão inteira
                            # e virou ruído que o usuário aprende a ignorar. Agora
                            # mede o que falta para os 5 min que a Task Force 1996
                            # pede em índices espectrais, e apaga sozinho.
                            mins = float(np.sum(rr_hist)) / 60000.0
                            caveat = "" if mins >= 5.0 else f"  ⚠ {mins:.1f}/5 min"
                            self.ecg_lfhf_lbl.setText(f"LF/HF: {ratio:.2f}{caveat}")
                            # --- Espectro HRV (plot) + potências por banda ---
                            if hasattr(self, "ecg_psd_curve"):
                                vlf_mask = (freqs >= 0.0033) & (freqs < 0.04)
                                vlf_p = (float(_TRAPEZOID(psd[vlf_mask], freqs[vlf_mask]))
                                         if vlf_mask.any() else 0.0)
                                total_p = vlf_p + lf_p + hf_p
                                lf_hf_sum = max(lf_p + hf_p, 1e-9)
                                lf_nu = lf_p / lf_hf_sum * 100.0
                                hf_nu = hf_p / lf_hf_sum * 100.0
                                band = freqs <= 0.5
                                self.ecg_psd_curve.setData(
                                    freqs[band].tolist(), psd[band].tolist())
                                self.ecg_psd_lbl.setText(
                                    tr("VLF: {0:.0f}  LF: {1:.0f}  HF: {2:.0f} ms²  ·  Total: {3:.0f} ms²  ·  "
                                       "LFnu/HFnu: {4:.0f}/{5:.0f}").format(vlf_p, lf_p, hf_p, total_p, lf_nu, hf_nu))
                    except Exception:
                        pass

                # ===== HRV GEOMÉTRICA: histograma RR + índice triangular =====
                # HTI = N_total / altura do modo. Sobre os ~11 RR da janela o
                # modo tinha altura 1 e o "índice" degenerava no próprio N — só
                # faz sentido com histograma povoado, daí o mínimo "geom".
                p_geom = hrv_pendente(n_hist, "geom")
                if hasattr(self, "ecg_hti_lbl") and p_geom:
                    self.ecg_hti_lbl.setText(f"HTI: {p_geom}  TINN: —")
                if hasattr(self, "ecg_rrhist_bars") and not p_geom:
                    try:
                        rr_h = np.asarray(rr_hist, dtype=np.float64)
                        binw = 1000.0 / 128.0  # 7,8125 ms (padrão Task Force)
                        lo = np.floor(rr_h.min() / binw) * binw
                        hi = np.ceil(rr_h.max() / binw) * binw
                        nb = int(round((hi - lo) / binw))
                        if nb >= 2 and hi > lo:
                            counts, edges = np.histogram(
                                rr_h, bins=nb, range=(float(lo), float(hi)))
                            centers = (edges[:-1] + edges[1:]) / 2.0
                            self.ecg_rrhist_bars.setOpts(
                                x=centers.tolist(), height=counts.tolist(),
                                width=binw * 0.9)
                            self.ecg_rrhist_plot.setXRange(float(lo), float(hi))
                            peak_h = int(counts.max()) if counts.size else 0
                            hti = float(len(rr_h) / peak_h) if peak_h > 0 else float("nan")
                            # TINN: base do triângulo interpolado (bins não-nulos)
                            nz = np.nonzero(counts)[0]
                            if nz.size:
                                x0 = float(edges[nz[0]]); x1 = float(edges[nz[-1] + 1])
                                tinn = x1 - x0
                                # Triângulo: ápice no modo (altura = pico), base em [x0,x1]
                                xm = float(centers[int(np.argmax(counts))])
                                self.ecg_rrhist_tri.setData(
                                    [x0, xm, x1], [0.0, float(peak_h), 0.0])
                            else:
                                tinn = float("nan")
                            self.ecg_hti_lbl.setText(
                                f"HTI: {hti:.1f}  TINN: {tinn:.0f} ms")
                    except Exception:
                        pass

                # ===== HRV NÃO-LINEAR (Kubios-style) =====
                # O portão len(rr_ms) >= 32 sobre 10 s exigia 198 bpm: este bloco
                # inteiro NUNCA executou num registro fisiológico. Agora roda
                # sobre a série da sessão, com mínimo próprio por métrica.
                p_poin = hrv_pendente(n_hist, "poincare")
                p_dfa1 = hrv_pendente(n_hist, "dfa1")
                p_ent  = hrv_pendente(n_hist, "entropy")
                if hasattr(self, "ecg_poincare_sd_lbl") and p_poin:
                    self.ecg_poincare_sd_lbl.setText(f"SD1/SD2: {p_poin}")
                if hasattr(self, "ecg_dfa_lbl") and p_dfa1:
                    self.ecg_dfa_lbl.setText(f"DFA α1: {p_dfa1}  α2: —")
                if hasattr(self, "ecg_entropy_lbl") and p_ent:
                    self.ecg_entropy_lbl.setText(f"ApEn: {p_ent}  SampEn: —")
                if not p_poin:
                    try:
                        rr_arr = np.asarray(rr_hist, dtype=np.float64)
                        # Poincaré SD1, SD2 (Brennan 2001)
                        diff = np.diff(rr_arr)
                        sd1 = float(np.std(diff) / np.sqrt(2.0))
                        sd2 = float(np.sqrt(max(0.0, 2 * np.var(rr_arr)
                                               - 0.5 * np.var(diff))))
                        sd_ratio = sd1 / max(sd2, 1e-9)
                        ecto = getattr(self, "_ecg_ectopic_count", 0)
                        if hasattr(self, "ecg_poincare_sd_lbl"):
                            self.ecg_poincare_sd_lbl.setText(
                                f"SD1: {sd1:5.1f} ms  SD2: {sd2:5.1f} ms  "
                                f"SD1/SD2: {sd_ratio:.2f}"
                                + (tr("   ·  ectópicos corrigidos: {0}").format(ecto) if ecto else "")
                            )
                        # Elipse SD1/SD2 girada 45° e centrada na média (Kubios)
                        if hasattr(self, "ecg_poincare_ellipse"):
                            cx = cy = float(np.mean(rr_arr))
                            th = np.linspace(0, 2 * np.pi, 80)
                            # eixo maior (SD2) ao longo da identidade (45°); menor = SD1
                            ex = 2 * sd2 * np.cos(th); ey = 2 * sd1 * np.sin(th)
                            c, s = np.cos(np.pi / 4), np.sin(np.pi / 4)
                            self.ecg_poincare_ellipse.setData(
                                (cx + ex * c - ey * s).tolist(),
                                (cy + ex * s + ey * c).tolist())
                            self.ecg_poincare_axes.setData(   # eixo maior (SD2)
                                [cx - 2 * sd2 * c, cx + 2 * sd2 * c],
                                [cy - 2 * sd2 * s, cy + 2 * sd2 * s])
                        # Com a série acumulada o custo destes quatro índices
                        # deixa de ser trivial: ApEn/SampEn são O(N²) em Python
                        # puro (0,21 s a 150 RR, 7 s a 800) e este método está no
                        # timer de 20 Hz da GUI — sem teto e sem throttle a
                        # interface travaria assim que a sessão passasse de 1 min.
                        _now = time.time()
                        if (_now - getattr(self, "_ecg_nl_last_t", 0.0)
                                >= ECG_NONLINEAR_PERIOD_S):
                            self._ecg_nl_last_t = _now
                            # DFA α1 / α2 (Peng 1995)
                            if not p_dfa1:
                                rr_dfa = rr_arr[-ECG_DFA_MAX_N:]
                                p_dfa2 = hrv_pendente(n_hist, "dfa2")
                                a1 = self._compute_dfa(rr_dfa, n_min=4, n_max=16)
                                s_a2 = p_dfa2 or "{:.2f}".format(self._compute_dfa(
                                    rr_dfa, n_min=16, n_max=min(64, len(rr_dfa) // 4)))
                                if hasattr(self, "ecg_dfa_lbl"):
                                    self.ecg_dfa_lbl.setText(
                                        f"DFA α1: {a1:.2f}  α2: {s_a2}")
                            # ApEn / SampEn
                            if not p_ent:
                                rr_e = rr_arr[-ECG_ENTROPY_MAX_N:]
                                r_e = 0.2 * float(np.std(rr_e))
                                apen = self._compute_apen(rr_e, m=2, r=r_e)
                                sampen = self._compute_sampen(rr_e, m=2, r=r_e)
                                if hasattr(self, "ecg_entropy_lbl"):
                                    self.ecg_entropy_lbl.setText(
                                        f"ApEn: {apen:.3f}  SampEn: {sampen:.3f}")
                    except Exception:
                        pass
        else:
            self.ecg_rpeak_scatter.setData([], [])

    # ---- HRV não-linear (DFA, ApEn, SampEn) ----
    @staticmethod
    def _compute_dfa(x, n_min=4, n_max=64):
        """Detrended Fluctuation Analysis (Peng 1995).

        Retorna o expoente α (escala log-log de F(n) vs n).
        x: série temporal (RR em ms ou outro).
        """
        x = np.asarray(x, dtype=np.float64)
        N = len(x)
        if N < max(2 * n_max, 16):
            return float("nan")
        # Cumulative sum centralizada
        y = np.cumsum(x - np.mean(x))
        scales = np.unique(np.round(np.logspace(
            np.log10(max(n_min, 4)), np.log10(min(n_max, N // 4)), 8)).astype(int))
        # Guarda a escala JUNTO com o F dela. Antes o laço fazia `continue` nas
        # escalas inválidas e a regressão pareava com `scales[:len(F)]`, o que
        # só estaria certo se as puladas fossem sempre as últimas — uma escala
        # descartada no começo deslocava todo o pareamento e enviesava o α.
        escalas_ok, F = [], []
        for n in scales:
            if n < 4 or n >= N: continue
            # Divide em blocos não-sobrepostos
            n_blocks = N // n
            if n_blocks < 2: continue
            errs = []
            for i in range(n_blocks):
                seg = y[i * n: (i + 1) * n]
                t = np.arange(n)
                # Ajuste linear (detrend)
                coef = np.polyfit(t, seg, 1)
                trend = np.polyval(coef, t)
                errs.append(np.mean((seg - trend) ** 2))
            if errs:
                f_n = float(np.sqrt(np.mean(errs)))
                # F = 0 acontece em série constante ou perfeitamente linear
                # (RR "quadrado" de simulação): log10(0) = -inf contamina a
                # regressão inteira e o α sai NaN sem aviso nenhum.
                if f_n > 0.0:
                    escalas_ok.append(int(n))
                    F.append(f_n)
        if len(F) < 3:
            return float("nan")
        log_n = np.log10(escalas_ok)
        log_F = np.log10(F)
        # α = slope da regressão log-log
        slope = np.polyfit(log_n, log_F, 1)[0]
        return float(slope)

    @staticmethod
    def _compute_apen(x, m=2, r=None):
        """Approximate Entropy (Pincus 1991). Lower = more regular."""
        x = np.asarray(x, dtype=np.float64)
        N = len(x)
        if N < m + 1 or r is None or r <= 0:
            return float("nan")

        def _phi(m_val):
            """Calcula a estatística Φ(m) — média dos logaritmos das correlações
            de templates — cuja diferença define a Approximate Entropy.

            Laço duplo em Python puro, O(N²) por chamada, e a função é chamada
            duas vezes (m e m+1): aplicar sobre janelas longas trava a
            interface. A tolerância r vem do escopo externo, não é parâmetro.
            """
            count = 0
            total = 0
            for i in range(N - m_val + 1):
                template = x[i:i + m_val]
                hits = 0
                for j in range(N - m_val + 1):
                    if np.max(np.abs(x[j:j + m_val] - template)) <= r:
                        hits += 1
                if hits > 0:
                    count += np.log(hits / (N - m_val + 1))
                    total += 1
            return count / max(total, 1)

        return float(_phi(m) - _phi(m + 1))

    @staticmethod
    def _compute_sampen(x, m=2, r=None):
        """Sample Entropy (Richman 2000). Mais robusto que ApEn."""
        x = np.asarray(x, dtype=np.float64)
        N = len(x)
        if N < m + 1 or r is None or r <= 0:
            return float("nan")
        # Constrói templates de tamanho m e m+1
        def _count(m_val):
            """Conta os pares de templates de tamanho m que ficam dentro da
            tolerância r, excluindo o auto-casamento.

            O 'if i == j: continue' é exatamente o que separa SampEn de ApEn.
            Também O(N²) e chamado duas vezes (m e m+1); r vem do escopo
            externo.
            """
            B = 0
            for i in range(N - m_val):
                template = x[i:i + m_val]
                # excluindo self-match
                for j in range(N - m_val):
                    if i == j: continue
                    if np.max(np.abs(x[j:j + m_val] - template)) <= r:
                        B += 1
            return B
        Bm  = _count(m)
        Bmp = _count(m + 1)
        if Bm == 0 or Bmp == 0:
            return float("nan")
        return float(-np.log(Bmp / Bm))

    # ==================================================================
    # EoG / Olhos — eletrooculograma, detecção de blink + gaze direction
    # ==================================================================
    def _build_eog_tab(self):
        """Aba EoG — detecção de blink e estimativa de direção do olhar.

        Convenções:
            VEoG = canal vertical (cima/baixo) — eletrodo sobre/abaixo do olho
            HEoG = canal horizontal (esquerda/direita) — eletrodo lateral

        Detecção de blink:
            VEoG positivo > threshold por 100-400ms = piscada.
        Direção do olhar:
            VEoG > +T -> Cima
            VEoG < -T -> Baixo
            HEoG > +T -> Direita
            HEoG < -T -> Esquerda
            |V|<T e |H|<T -> Centro
        """
        widget = QtWidgets.QWidget()
        outer = QtWidgets.QVBoxLayout(widget)
        outer.setContentsMargins(8, 8, 8, 8); outer.setSpacing(6)

        # === Controles ===
        ctrl = QtWidgets.QHBoxLayout()
        # textos por nível em _aplicar_nomes_bio (G38)
        self._eog_h_lbl = QtWidgets.QLabel(tr("Canal HEOG (horizontal):"))
        ctrl.addWidget(self._eog_h_lbl)
        self.eog_h_combo = QtWidgets.QComboBox()
        ctrl.addWidget(self.eog_h_combo)
        ctrl.addSpacing(10)
        self._eog_v_lbl = QtWidgets.QLabel(tr("Canal VEOG (vertical):"))
        ctrl.addWidget(self._eog_v_lbl)
        self.eog_v_combo = QtWidgets.QComboBox()
        ctrl.addWidget(self.eog_v_combo)
        ctrl.addSpacing(20)
        self._eog_thr_lbl = QtWidgets.QLabel(tr("Limiar (µV):"))
        ctrl.addWidget(self._eog_thr_lbl)
        self.eog_threshold_spin = QtWidgets.QDoubleSpinBox()
        self.eog_threshold_spin.setRange(5.0, 500.0)
        self.eog_threshold_spin.setValue(80.0)
        self.eog_threshold_spin.setSingleStep(5.0)
        self.eog_threshold_spin.setSuffix(" µV")
        ctrl.addWidget(self.eog_threshold_spin)
        ctrl.addStretch()
        btn_reset = QtWidgets.QPushButton(tr("Zerar"))
        btn_reset.setToolTip(tr("Recomeça a contagem de piscadas e movimentos."))
        btn_reset.clicked.connect(self._eog_reset)
        ctrl.addWidget(btn_reset)
        eog_reg_btn = QtWidgets.QPushButton(tr("Regressão ocular → EEG…"))
        # limpeza do EEG por regressão é de pesquisa (G38)
        self._register_advanced("eog", eog_reg_btn)
        eog_reg_btn.setToolTip(
            tr("Remove o artefato ocular do EEG por REGRESSÃO (Gratton-Coles):\n"
            "EEG_limpo = EEG − β·VEoG, com β = cov(EEG,VEoG)/var(VEoG) por canal.\n"
            "Método clássico e rápido — alternativa ao ICA. Mostra a redução de "
            "variância (maior nos canais frontais, onde a piscada domina)."))
        eog_reg_btn.clicked.connect(self._eog_regression_demo)
        ctrl.addWidget(eog_reg_btn)
        outer.addLayout(ctrl)
        outer.addLayout(self._make_detail_toggle(
            "eog", tr("Exame dos olhos — acompanhe piscadas e direção do olhar.")))
        self._populate_eog_channel_combos()
        self.eog_h_combo.currentIndexChanged.connect(self._eog_reset)
        self.eog_v_combo.currentIndexChanged.connect(self._eog_reset)

        # === Cards de métricas ===
        cards = QtWidgets.QHBoxLayout()
        # Direção atual
        self.eog_dir_lbl = QtWidgets.QLabel(tr("Centro"))
        self.eog_dir_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['EoG']}; font-size: 22pt; font-weight: bold; "
            f"padding: 10px 16px; border: 2px solid {COLORS['border']}; border-radius: 6px;")
        self.eog_dir_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.eog_dir_lbl.setMinimumSize(180, 60)
        cards.addWidget(self.eog_dir_lbl)
        # Blinks
        blink_box = QtWidgets.QVBoxLayout()
        self.eog_blink_count_lbl = QtWidgets.QLabel("0")
        self.eog_blink_count_lbl.setStyleSheet(
            f"color: {COLORS['accent']}; font-size: 24pt; font-weight: bold; padding: 4px;")
        self.eog_blink_count_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.eog_blink_count_lbl.setMinimumHeight(50)
        blink_box.addWidget(self.eog_blink_count_lbl)
        blink_lbl = QtWidgets.QLabel(tr("piscadas detectadas"))
        blink_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        blink_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        blink_box.addWidget(blink_lbl)
        cards.addLayout(blink_box)
        cards.addSpacing(15)
        # Blink rate (pisca/min)
        rate_box = QtWidgets.QVBoxLayout()
        self.eog_blink_rate_lbl = QtWidgets.QLabel("--")
        self.eog_blink_rate_lbl.setStyleSheet(
            f"color: {COLORS['warning']}; font-size: 28pt; font-weight: bold;")
        self.eog_blink_rate_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        # A janela de 60 s conta tempo de SINAL, nao de relogio: com a
        # aquisicao parada a taxa congela no ultimo valor em vez de escorrer.
        self.eog_blink_rate_lbl.setToolTip(
            tr("Taxa medida sobre o tempo de sinal recebido, não sobre o "
               "relógio do computador."))
        rate_box.addWidget(self.eog_blink_rate_lbl)
        rate_lbl = QtWidgets.QLabel(tr("piscadas/min"))
        rate_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        rate_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        rate_box.addWidget(rate_lbl)
        cards.addLayout(rate_box)
        cards.addStretch()
        # Olho anatômico: pisca ao detectar blink e a pupila segue o olhar.
        # É o elemento que se entende em 1 segundo, sem legenda — por isso vem
        # ampliado (antes competia de igual para igual com rótulos de texto).
        eye_box = QtWidgets.QVBoxLayout(); eye_box.setSpacing(2)
        self.eog_eye = EyeWidget()
        self.eog_eye.setMinimumSize(300, 200)
        self.eog_eye.setMaximumSize(380, 250)
        eye_box.addWidget(self.eog_eye)
        eye_cap = QtWidgets.QLabel(tr("olho (pisca ao detectar)"))
        eye_cap.setStyleSheet(f"color: {COLORS['text_dim']};")
        eye_cap.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        eye_box.addWidget(eye_cap)
        cards.addLayout(eye_box)
        cards.addSpacing(10)
        # Diagrama XY do olhar (dot que se move)
        self.eog_gaze_widget = _EogGazeWidget()
        self.eog_gaze_widget.setMinimumSize(220, 220)
        self.eog_gaze_widget.setMaximumSize(280, 280)
        cards.addWidget(self.eog_gaze_widget)
        outer.addLayout(cards)

        # === Plot dos 2 canais ===
        self.eog_plot = pg.PlotWidget(enableMenu=False)
        self.eog_plot.showGrid(x=True, y=True, alpha=0.15)
        self.eog_plot.setLabel("left", tr("Amplitude"), units="µV")
        self.eog_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.eog_plot.setMenuEnabled(False)
        self.eog_plot.addLegend(offset=(10, 10))
        self.eog_h_curve = self.eog_plot.plot(
            pen=pg.mkPen("#66ddff", width=1.4), name=tr("HEOG (horizontal)"))
        self.eog_v_curve = self.eog_plot.plot(
            pen=pg.mkPen("#ffaadd", width=1.4), name=tr("VEOG (vertical)"))
        # Linhas de threshold (+/-)
        self.eog_thresh_pos_line = pg.InfiniteLine(
            pos=80, angle=0,
            pen=pg.mkPen(COLORS["border"], style=QtCore.Qt.PenStyle.DashLine))
        self.eog_thresh_neg_line = pg.InfiniteLine(
            pos=-80, angle=0,
            pen=pg.mkPen(COLORS["border"], style=QtCore.Qt.PenStyle.DashLine))
        self.eog_plot.addItem(self.eog_thresh_pos_line)
        self.eog_plot.addItem(self.eog_thresh_neg_line)
        # Scatter para marcar blinks detectados
        self.eog_blink_scatter = pg.ScatterPlotItem(
            size=10, brush=pg.mkBrush("#ffff00"),
            pen=pg.mkPen("#ffffff", width=1), symbol="t")
        self.eog_plot.addItem(self.eog_blink_scatter)
        # Scatter para sacadas
        self.eog_saccade_scatter = pg.ScatterPlotItem(
            size=8, brush=pg.mkBrush("#ff66ff"),
            pen=pg.mkPen("#ffffff", width=1), symbol="d")
        self.eog_plot.addItem(self.eog_saccade_scatter)
        outer.addWidget(self.eog_plot, stretch=2)
        # Listener de threshold
        self.eog_threshold_spin.valueChanged.connect(
            lambda v: (self.eog_thresh_pos_line.setPos(v),
                       self.eog_thresh_neg_line.setPos(-v)))

        # ===================================================================
        # SEÇÃO: Estado de Alerta + Sacadas + Fixação
        # ===================================================================
        alert_group = QtWidgets.QGroupBox(tr("Estado de Alerta (sonolência) + Sacadas + Fixação"))
        self._eog_alert_group = alert_group
        ag = QtWidgets.QHBoxLayout(alert_group)
