    def _populate_eog_channel_combos(self):
        """Popula combos H e V com canais marcados EoG."""
        if not hasattr(self, "eog_h_combo"): return
        for cb in (self.eog_h_combo, self.eog_v_combo):
            cb.blockSignals(True)
            cb.clear()
            # so' os canais que a placa tem (ver _joy_repopulate_combos)
            eog_channels = [ch for ch in range(self.num_channels)
                            if ch < len(self.config.channel_signal_types)
                            and self.config.channel_signal_types[ch] == "EoG"]
            if not eog_channels:
                cb.addItem(self._msg_sem_canal("EoG"), -1)
            else:
                for ch in eog_channels:
                    cb.addItem(f"CH{ch+1}", ch)
            cb.blockSignals(False)
        # Se houver pelo menos 2 canais EoG, default: 1º para H, 2º para V
        if self.eog_h_combo.count() >= 2 and self.eog_h_combo.itemData(0) is not None:
            self.eog_v_combo.setCurrentIndex(min(1, self.eog_v_combo.count()-1))

    def _eog_reset(self):
        """Zera contadores, históricos e gráficos de piscadas e sacadas da aba
        EoG.

        Além do botão Reset, dispara ao trocar o canal HEoG ou VEoG — as
        métricas acumuladas deixam de valer quando o eletrodo muda. Os hasattr
        protegem a execução antes de a aba estar totalmente construída. Também
        limpa a main sequence, o histórico de blink rate e o t0 da sessão.
        """
        self._eog_blink_count = 0
        self._eog_blink_times = []
        self._eog_blink_durations = []
        self._eog_in_blink = False
        self._eog_saccade_idx = []
        self._eog_saccade_count = 0
        if hasattr(self, "eog_blink_count_lbl"):
            self.eog_blink_count_lbl.setText("0")
        if hasattr(self, "eog_blink_rate_lbl"):
            self.eog_blink_rate_lbl.setText("--")
        if hasattr(self, "eog_blink_scatter"):
            self.eog_blink_scatter.setData([], [])
        if hasattr(self, "eog_saccade_scatter"):
            self.eog_saccade_scatter.setData([], [])
        if hasattr(self, "eog_saccade_count_lbl"):
            self.eog_saccade_count_lbl.setText("0")
        if hasattr(self, "eog_alert_state_lbl"):
            self.eog_alert_state_lbl.setText("--")
        if hasattr(self, "eog_fixation_pct_lbl"):
            self.eog_fixation_pct_lbl.setText("--")
        if hasattr(self, "eog_blink_dur_lbl"):
            self.eog_blink_dur_lbl.setText("--")
        # Oculometria estendida
        self._eog_saccade_ampl = []
        self._eog_saccade_pvel = []
        self._eog_blink_idx = []
        self._eog_blinkrate_hist = []
        self._eog_last_rate_sample_st = -10 ** 9
        self._eog_last_microsleep_st = -10 ** 9
        # amostra do Reset: a taxa e o historico contam a partir daqui (a
        # janela vinha de samples_total, que o Reset nao zera, e a taxa saia
        # subestimada por 60 s)
        self._eog_st0 = int(getattr(self, "samples_total", 0) or 0)
        if hasattr(self, "eog_mainseq_scatter"):
            self.eog_mainseq_scatter.setData([], [])
            self.eog_mainseq_fit.setData([], [])
            self.eog_mainseq_lbl.setText("n=0  ·  V ≈ k·A^b:  k=--  b=--")
        if hasattr(self, "eog_blinkrate_curve"):
            self.eog_blinkrate_curve.setData([], [])
            self.eog_perclos_lbl.setText(tr("PERCLOS: --  ·  tendência: --"))

    def _eog_regression_demo(self):
        """Aplica a REGRESSÃO ocular (Gratton-Coles) ao buffer atual usando o VEoG
        como referência e relata a redução de variância no EEG (demonstração)."""
        ch_v = self.eog_v_combo.currentData() if hasattr(self, "eog_v_combo") else -1
        ch_h = self.eog_h_combo.currentData() if hasattr(self, "eog_h_combo") else -1
        if ch_v is None or ch_v < 0:
            QtWidgets.QMessageBox.information(
                self, tr("Regressão ocular"), tr("Selecione o canal VEoG primeiro."))
            return
        data = self._ordered_buffer()
        if data.shape[1] < int(SAMPLE_RATE):
            QtWidgets.QMessageBox.information(
                self, tr("Regressão ocular"),
                tr("Sinal insuficiente no buffer. Conecte/rode a coleta (ou o Modo "
                "Simulação) e tente de novo."))
            return
        ref = np.asarray(data[ch_v], float)
        rows = []
        for c in range(data.shape[0]):
            if c in (ch_h, ch_v):
                continue
            x = np.asarray(data[c], float)
            v0 = float(np.var(x))
            if v0 <= 1e-9:
                continue
            v1 = float(np.var(eog_regression(x, ref)))
            name = (self.config.channel_mapping[c]
                    if c < len(self.config.channel_mapping) else f"CH{c+1}")
            rows.append((name, 100.0 * (1.0 - v1 / v0)))
        if not rows:
            QtWidgets.QMessageBox.information(
                self, tr("Regressão ocular"), tr("Não há canais EEG para limpar."))
            return
        rows.sort(key=lambda r: -r[1])
        mean_red = float(np.mean([r[1] for r in rows]))
        top = "\n".join(tr("  {0:>5}:  −{1:4.1f}% variância").format(nm, red) for nm, red in rows[:8])
        QtWidgets.QMessageBox.information(
            self, tr("Regressão ocular (Gratton-Coles)"),
            tr("EEG_limpo = EEG − β·VEoG  (β por canal).\n\nRedução MÉDIA de variância: "
               "−{0:.1f}%\n(os canais frontais tendem a cair mais — é onde a piscada "
               "domina)\n\nMaiores reduções:\n{1}\n\nDemonstração no buffer atual. Para "
               "limpar uma sessão GRAVADA e salvar o resultado, use o botão ‘Limpar "
               "artefatos (ICA)’ na aba Offline.").format(mean_red, top))

    def _update_eog_view(self):
        """Atualiza canais H/V, detecta blinks e estima direção."""
        if not hasattr(self, "eog_plot"): return
        ch_h = self.eog_h_combo.currentData() if hasattr(self, "eog_h_combo") else -1
        ch_v = self.eog_v_combo.currentData() if hasattr(self, "eog_v_combo") else -1
        if ch_h is None or ch_v is None or ch_h < 0 or ch_v < 0:
            return
        data = self._ordered_buffer()
        if data.shape[1] < int(SAMPLE_RATE * 0.5): return
        sig_h = data[ch_h]; sig_v = data[ch_v]
        t_axis = np.arange(data.shape[1]) / SAMPLE_RATE
        self.eog_h_curve.setData(t_axis, sig_h)
        self.eog_v_curve.setData(t_axis, sig_v)

        th = self.eog_threshold_spin.value()
        # Direção atual: média dos últimos 250 ms, RELATIVA à baseline (mediana do
        # buffer) — remove a deriva lenta que travava a direção em Cima/Baixo.
        n_recent = int(SAMPLE_RATE * 0.25)
        h_base = float(np.median(sig_h)); v_base = float(np.median(sig_v))
        h_mean = float(np.mean(sig_h[-n_recent:])) - h_base
        v_mean = float(np.mean(sig_v[-n_recent:])) - v_base
        # Decisão direção
        if   v_mean >  th: direction = "Cima"
        elif v_mean < -th: direction = "Baixo"
        elif h_mean >  th: direction = "Direita"
        elif h_mean < -th: direction = "Esquerda"
        else:              direction = "Centro"
        self.eog_dir_lbl.setText(direction)
        # Atualiza gaze widget + olho anatômico
        gx = h_mean / max(th * 2, 1); gy = v_mean / max(th * 2, 1)
        self.eog_gaze_widget.set_gaze(gx, gy)
        if hasattr(self, "eog_eye"):
            self.eog_eye.set_gaze(gx, gy)

        # Detecção de blink: pico de VEoG positivo > 1.5*th por 50-400ms
        # Faz busca local apenas na última janela curta para evitar reprocessar
        # picos antigos.
        n = len(sig_v)
        win = min(n, int(SAMPLE_RATE * 1.5))
        # Relativo à linha de base LOCAL, a mesma do relatório: com a mediana
        # do buffer, olhar para cima e ficar lá passava do limiar e virava
        # "piscada" (e PERCLOS) enquanto durasse.
        resid_v = sig_v - eog_linha_base(sig_v, SAMPLE_RATE)
        local = resid_v[-win:]
        peaks_h = []
        thr_blink = th * 1.5
        # Só vale o pico cujo trecho acima do limiar dura >= 50 ms, a duração
        # mínima de piscada do relatório (eog_piscadas): a borda de um degrau
        # do olhar deixa no resíduo um bico de poucas amostras.
        # a MESMA função do relatório (eog_piscadas_tela): a tela e o PDF
        # contavam com critérios diferentes e a mesma gravação dava 11 na
        # tela e 27 no PDF
        peaks_h = [q[4] for q in eog_piscadas_tela(local, SAMPLE_RATE, th,
                                                   dedup_s=0.0, residuo=True)]
        # Dedup por TEMPO ABSOLUTO (relógio), como já é feito nas sacadas: o
        # buffer é circular, então a MESMA piscada reaparece a cada quadro num
        # t_p MENOR. Comparar t_p com o último t_p guardado saturava o critério
        # assim que o buffer enchia — o último valor gravado fica colado no fim
        # do eixo e nenhum pico novo consegue superá-lo por +0,2 s, então a
        # contagem congelava nas poucas piscadas dos primeiros segundos.
        st = int(getattr(self, "samples_total", 0))
        # Reconexao zera samples_total: os indices antigos ficariam no futuro.
        if self._eog_blink_idx and self._eog_blink_idx[-1] > st:
            self._eog_reset()
            return
        st0 = int(getattr(self, "_eog_st0", 0) or 0)
        if st0 > st:
            # reconexao sem piscada guardada: recomeca do zero
            self._eog_st0 = st0 = 0
        dedup_blink = max(1, int(0.2 * SAMPLE_RATE))
        for p in peaks_h:
            t_p = float(t_axis[-win + p])
            idx_abs = st - (win - p)      # indice da amostra da piscada
            if any(abs(idx_abs - iw) < dedup_blink
                   for iw in self._eog_blink_idx[-16:]):
                continue
            self._eog_blink_times.append(t_p)
            self._eog_blink_idx.append(idx_abs)
            self._eog_blink_count += 1
            if hasattr(self, "eog_eye"):
                self.eog_eye.blink()      # anima a piscada no olho
        # Limita a lista (memória; evita a taxa fossilizar em sessão longa)
        if len(self._eog_blink_times) > 500:
            self._eog_blink_times = self._eog_blink_times[-500:]
        if len(self._eog_blink_idx) > 2000:
            self._eog_blink_idx = self._eog_blink_idx[-2000:]
        # Marcadores: reprojeta o instante de RELÓGIO de cada piscada no eixo do
        # buffer, que rola sob elas. O t gravado na detecção envelhece junto com
        # o buffer, então o filtro (last_t - t) nunca descartava nada e as
        # piscadas antigas ficavam empilhadas em posições que já saíram da tela.
        last_t = float(t_axis[-1])
        # Quantas amostras atras cada piscada ficou; so as que ainda estao no
        # buffer aparecem, e o y sai da AMOSTRA da piscada.
        off_blinks = [st - iw for iw in self._eog_blink_idx]
        off_blinks = [o for o in off_blinks if 0 <= o < n]
        visible_blinks = [last_t - o / SAMPLE_RATE for o in off_blinks]
        # Atualiza scatter (sempre, inclusive vazio: com o "if" os marcadores
        # do quadro anterior ficavam parados na tela)
        ys = [float(sig_v[n - 1 - o]) for o in off_blinks]
        self.eog_blink_scatter.setData(visible_blinks, ys)
        # Atualiza UI
        self.eog_blink_count_lbl.setText(str(self._eog_blink_count))
        # Taxa: piscadas/min medidas no RELÓGIO, em janela deslizante de 60 s.
        # O denominador antigo vinha do eixo do buffer (last_t - primeiro t) e
        # nunca passa de BUFFER_SECONDS: dividir uma contagem que cresce a sessão
        # inteira por no máximo 10 s inflava a taxa em ordens de grandeza e
        # prendia o Estado de Alerta em FADIGA. rate = -1 sinaliza "janela ainda
        # curta demais para medir" e não é um valor de taxa.
        span_rate = min(60.0, (st - st0) / float(SAMPLE_RATE))
        if span_rate >= 10.0:
            recent_bl = [iw for iw in self._eog_blink_idx
                         if iw >= st - 60 * SAMPLE_RATE]
            rate = len(recent_bl) / span_rate * 60.0
            self.eog_blink_rate_lbl.setText(f"{rate:.0f}")
        else:
            rate = -1.0
            self.eog_blink_rate_lbl.setText("--")

        # ===== DURAÇÃO DA PISCADA + MICROSLEEP =====
        # Para cada blink, estima duração via FWHM ao redor do pico
        try:
            durations = []
            for _off in off_blinks:
                idx = n - 1 - _off
                if idx < 0 or idx >= n: continue
                peak_val = float(resid_v[idx])
                half = peak_val * 0.5
                # caminho para esquerda (no resíduo: meia altura da piscada,
                # não do nível em que o olhar estava)
                left = idx
                while left > 0 and resid_v[left] > half:
                    left -= 1
                right = idx
                while right < n - 1 and resid_v[right] > half:
                    right += 1
                dur_ms = (right - left) * 1000.0 / SAMPLE_RATE
                if 50 < dur_ms < 1500:
                    durations.append(dur_ms)
            if durations:
                mean_dur = float(np.mean(durations))
                self.eog_blink_dur_lbl.setText(f"{mean_dur:.0f}")
                # Microsleep: alguma piscada > 500 ms nos últimos 5 s
                long_blinks = [d for d in durations if d > 500]
                if long_blinks:
                    self._eog_last_microsleep_st = st
                # Mantém LED aceso por 2 s de sinal. Era comparado com last_t,
                # que para de crescer quando o buffer enche: o LED nunca apagava.
                if (st - self._eog_last_microsleep_st) < 2.0 * SAMPLE_RATE:
                    self.eog_microsleep_lbl.setStyleSheet(
                        f"color: {COLORS['error']}; font-size: 30pt; padding: 0 10px;")
                    self.eog_microsleep_lbl.setToolTip(tr("MICROSLEEP detectado!"))
                else:
                    self.eog_microsleep_lbl.setStyleSheet(
                        f"color: #555; font-size: 30pt; padding: 0 10px;")
        except Exception:
            pass

        # ===== ESTADO DE ALERTA =====
        # rate < 0 = janela ainda curta, não dá para julgar. rate == 0 é medida
        # legítima (ninguém piscou em 60 s), que é justamente o caso SONOLENTO /
        # olhos fechados: o teste antigo (> 0) descartava esse caso e deixava o
        # rótulo congelado no último estado exibido.
        if rate >= 0:
            if   rate < 8:  state = "SONOLENTO";  color = COLORS["error"]
            elif rate > 22: state = "FADIGA";     color = COLORS["warning"]
            elif rate < 18: state = "ALERTA";     color = SIGNAL_TYPE_COLORS["EoG"]
            else:           state = "FADIGA?";    color = COLORS["warning"]
            self.eog_alert_state_lbl.setText(tr(state))
            self.eog_alert_state_lbl.setStyleSheet(
                f"color: {color}; font-size: 22pt; font-weight: bold; "
                f"padding: 6px 12px; border: 2px solid {color}; border-radius: 6px;")

        # ===== SACADAS (derivada de HEoG > threshold) =====
        # Sacada = movimento rápido (velocidade > 30°/s)
        # Aproximamos via derivada de HEoG: dHEoG/dt > ~3*th por amostra
        try:
            n_h = len(sig_h)
            if n_h > SAMPLE_RATE:
                window_sac = sig_h[-SAMPLE_RATE:]  # último 1s
                dH = np.diff(window_sac)
                sac_thresh = th * 0.6  # µV por amostra
                # Encontra picos da derivada absoluta. Dedup por TEMPO ABSOLUTO
                # (relógio): o instante físico da sacada não muda com o buffer
                # deslizando, então cada sacada é contada uma única vez — corrige
                # a recontagem/omissão do refratório relativo ao buffer.
                half_w = int(SAMPLE_RATE * 0.12)  # ±120 ms p/ medir a sacada
                dedup_sac = max(1, int(0.1 * SAMPLE_RATE))
                for i in range(1, len(dH) - 1):
                    if (abs(dH[i]) > sac_thresh and
                            abs(dH[i]) >= abs(dH[i-1]) and
                            abs(dH[i]) >= abs(dH[i+1])):
                        samples_from_end = len(dH) - i
                        idx_abs = st - samples_from_end
                        if any(abs(idx_abs - iw) < dedup_sac
                               for iw in self._eog_saccade_idx[-16:]):
                            continue
                        self._eog_saccade_idx.append(idx_abs)
                        self._eog_saccade_count += 1
                        # --- Amplitude + velocidade de pico (main sequence) ---
                        gi = n_h - SAMPLE_RATE + (i + 1)
                        a = max(0, gi - half_w); b = min(n_h, gi + half_w)
                        seg = sig_h[a:b]
                        if seg.size >= 3:
                            ampl = float(np.ptp(seg))                       # µV
                            pvel = float(np.max(np.abs(np.diff(seg)))) * SAMPLE_RATE  # µV/s
                            if ampl > 1.0:  # descarta ruído mínimo
                                self._eog_saccade_ampl.append(ampl)
                                self._eog_saccade_pvel.append(pvel)
                if len(self._eog_saccade_idx) > 600:
                    self._eog_saccade_idx = self._eog_saccade_idx[-600:]
                # Cap das listas de main sequence
                if len(self._eog_saccade_ampl) > 400:
                    self._eog_saccade_ampl = self._eog_saccade_ampl[-400:]
                    self._eog_saccade_pvel = self._eog_saccade_pvel[-400:]
                # Scatter: so as sacadas que ainda estao dentro do buffer. O
                # tempo gravado antes envelhecia junto com o eixo e nenhuma era
                # descartada — todas se empilhavam na borda direita do grafico.
                off_sac = [st - iw for iw in self._eog_saccade_idx]
                off_sac = [o for o in off_sac if 0 <= o < n_h]
                vis_sac = [last_t - o / SAMPLE_RATE for o in off_sac]
                ys = [float(sig_h[n_h - 1 - o]) for o in off_sac]
                self.eog_saccade_scatter.setData(vis_sac, ys)
                self.eog_saccade_count_lbl.setText(str(self._eog_saccade_count))
                # --- Sequência principal: scatter + ajuste log-log V=k·A^b ---
                if hasattr(self, "eog_mainseq_scatter") and self._eog_saccade_ampl:
                    A = np.asarray(self._eog_saccade_ampl, dtype=np.float64)
                    V = np.asarray(self._eog_saccade_pvel, dtype=np.float64)
                    self.eog_mainseq_scatter.setData(A.tolist(), V.tolist())
                    # O expoente da sequência principal é a INCLINAÇÃO de uma
                    # reta em log-log. Se todas as sacadas têm amplitude
                    # parecida, não há alavanca para estimar inclinação: o
                    # polyfit devolve um número, avisa "poorly conditioned" —
                    # milhares de vezes no log — e o rótulo exibia esse número
                    # como se fosse medida. O critério é o mesmo dos índices de
                    # HRV: abaixo do mínimo, diga o que falta.
                    m = (A > 0) & (V > 0)
                    faixa = 0.0
                    if m.sum() >= 2:
                        la = np.log(A[m])
                        faixa = float(la.max() - la.min())
                    if m.sum() >= 8 and faixa >= 0.5:
                        try:
                            bexp, loga = np.polyfit(
                                np.log(A[m]), np.log(V[m]), 1)
                            k = float(np.exp(loga))
                            xf = np.linspace(A[m].min(), A[m].max(), 40)
                            self.eog_mainseq_fit.setData(
                                xf.tolist(), (k * xf ** bexp).tolist())
                            self.eog_mainseq_lbl.setText(
                                f"n={A.size}  ·  V ≈ k·A^b:  "
                                f"k={num_loc(k, 1)}  b={num_loc(bexp, 2)}")
                        except Exception:
                            pass
                    else:
                        self.eog_mainseq_fit.setData([], [])
                        motivo = (tr("faltam sacadas") if m.sum() < 8
                                  else tr("amplitudes muito parecidas"))
                        self.eog_mainseq_lbl.setText(
                            f"n={A.size}  ·  V ≈ k·A^b: — ({motivo})")
        except Exception:
            pass

        # ===== FIXAÇÃO (% do tempo sem movimento) =====
        # Heurística: tempo em que |dH/dt| e |dV/dt| ambos < threshold/4
        try:
            if n > SAMPLE_RATE:
                window_fix = min(n, int(SAMPLE_RATE * BUFFER_SECONDS))
                wh = sig_h[-window_fix:]
                wv = sig_v[-window_fix:]
                dH = np.abs(np.diff(wh))
                dV = np.abs(np.diff(wv))
                no_move_mask = (dH < th * 0.15) & (dV < th * 0.15)
                pct = float(np.mean(no_move_mask)) * 100.0
                self.eog_fixation_pct_lbl.setText(num_loc(pct, 1) + "%")
        except Exception:
            pass

        # ===== TAXA DE PISCADAS NO TEMPO (sonolência) + PERCLOS =====
        try:
            elapsed_s = (st - st0) / float(SAMPLE_RATE)
            # Amostra a cada ~1,5 s de SINAL para não inflar a série
            if ((st - self._eog_last_rate_sample_st) >= 1.5 * SAMPLE_RATE
                    and elapsed_s > 2.0):
                self._eog_last_rate_sample_st = st
                # Taxa: piscadas na janela deslizante de 60 s, normalizada p/ min
                w0 = st - 60 * SAMPLE_RATE
                recent = [iw for iw in self._eog_blink_idx if iw >= w0]
                span_min = min(60.0, elapsed_s) / 60.0
                rate_t = (len(recent) / span_min) if span_min > 0 else 0.0
                self._eog_blinkrate_hist.append((elapsed_s / 60.0, rate_t))
                if len(self._eog_blinkrate_hist) > 800:
                    self._eog_blinkrate_hist = self._eog_blinkrate_hist[-800:]
                xs = [p[0] for p in self._eog_blinkrate_hist]
                ys = [p[1] for p in self._eog_blinkrate_hist]
                self.eog_blinkrate_curve.setData(xs, ys)
                # PERCLOS ≈ % do tempo (buffer) com |VEoG-baseline| acima do limiar
                perclos = float(np.mean(np.abs(resid_v) > thr_blink)) * 100.0
                # Tendência: inclinação das últimas ~10 amostras
                trend = tr("estável")
                if len(ys) >= 6:
                    yy = np.asarray(ys[-10:]); xx = np.arange(yy.size)
                    slope = float(np.polyfit(xx, yy, 1)[0])
                    if slope > 0.4:   trend = tr("subindo (fadiga?)")
                    elif slope < -0.4: trend = tr("caindo (sonolência?)")
                self.eog_perclos_lbl.setText(
                    tr("PERCLOS: {0}%  ·  tendência: {1}").format(num_loc(perclos, 1), trend))
        except Exception:
            pass

    # ==================================================================
    # Acelerômetro · Movimento — histórico completo da sessão + postura
    # ==================================================================
    def _build_accelerometer_tab(self):
        """Aba Acelerômetro — histórico de movimento da sessão inteira.

        Métricas:
            - X/Y/Z em g (gravidade) ao longo do tempo
            - Magnitude |g| = sqrt(x²+y²+z²)
            - Roll  = atan2(y, z) — inclinação lateral
            - Pitch = atan2(-x, sqrt(y²+z²)) — inclinação frontal
            - Activity Index = std móvel da magnitude (movimento detectado)
        """
        widget = QtWidgets.QWidget()
        outer = QtWidgets.QVBoxLayout(widget)
        outer.setContentsMargins(8, 8, 8, 8); outer.setSpacing(6)

        # === Cards superiores ===
        cards = QtWidgets.QHBoxLayout()
        # Postura (roll/pitch)
        post_box = QtWidgets.QVBoxLayout()
        self.accel_posture_lbl = QtWidgets.QLabel("--")
        self.accel_posture_lbl.setStyleSheet(
            f"color: {COLORS['accent']}; font-size: 18pt; font-weight: bold; "
            f"padding: 6px 12px; border: 2px solid {COLORS['border']}; border-radius: 6px;")
        self.accel_posture_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.accel_posture_lbl.setMinimumWidth(220)
        self.accel_posture_lbl.setToolTip(
            tr("Postura inferida a partir da gravidade:\n"
            "  Vertical: -10° < pitch < 10°\n"
            "  Inclinado frente: pitch > 30°\n"
            "  Inclinado trás:  pitch < -30°\n"
            "  Lateral esq/dir: |roll| > 30°")
        )
        post_box.addWidget(self.accel_posture_lbl)
        post_lbl = QtWidgets.QLabel(tr("Postura"))
        post_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        post_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        post_box.addWidget(post_lbl)
        cards.addLayout(post_box)
        cards.addSpacing(12)

        # Atividade
        act_box = QtWidgets.QVBoxLayout()
        self.accel_activity_lbl = QtWidgets.QLabel("--")
        self.accel_activity_lbl.setStyleSheet(
            f"color: {SIGNAL_TYPE_COLORS['EMG']}; font-size: 18pt; font-weight: bold; "
            f"padding: 6px 12px; border: 2px solid {COLORS['border']}; border-radius: 6px;")
        self.accel_activity_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        self.accel_activity_lbl.setMinimumWidth(150)
        self.accel_activity_lbl.setToolTip(
            tr("Índice de atividade:\n"
            "  PARADO:    std < 0.05 g\n"
            "  LEVE:      0.05-0.15 g\n"
            "  MODERADO:  0.15-0.5 g\n"
            "  INTENSO:   > 0.5 g")
        )
        act_box.addWidget(self.accel_activity_lbl)
        act_lbl2 = QtWidgets.QLabel(tr("Atividade"))
        act_lbl2.setStyleSheet(f"color: {COLORS['text_dim']};")
        act_lbl2.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        act_box.addWidget(act_lbl2)
        cards.addLayout(act_box)
        cards.addSpacing(12)

        # Roll / Pitch numéricos
        rp_box = QtWidgets.QVBoxLayout()
        self.accel_roll_lbl = QtWidgets.QLabel(tr("Roll:  +0.0°"))
        self.accel_roll_lbl.setStyleSheet(
            f"color: {COLORS['text']}; font-family: {FONT_DATA_STACK};")
        rp_box.addWidget(self.accel_roll_lbl)
        self.accel_pitch_lbl = QtWidgets.QLabel(tr("Pitch: +0.0°"))
        self.accel_pitch_lbl.setStyleSheet(
            f"color: {COLORS['text']}; font-family: {FONT_DATA_STACK};")
        rp_box.addWidget(self.accel_pitch_lbl)
        self.accel_mag_lbl = QtWidgets.QLabel("|g|:    1.00")
        self.accel_mag_lbl.setStyleSheet(
            f"color: {COLORS['text']}; font-family: {FONT_DATA_STACK};")
        rp_box.addWidget(self.accel_mag_lbl)
        cards.addLayout(rp_box)
        cards.addStretch()

        # Total de eventos de movimento
        ev_box = QtWidgets.QVBoxLayout()
        self.accel_event_count_lbl = QtWidgets.QLabel("0")
        self.accel_event_count_lbl.setStyleSheet(
            f"color: {COLORS['warning']}; font-size: 22pt; font-weight: bold;")
        self.accel_event_count_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        ev_box.addWidget(self.accel_event_count_lbl)
        ev_lbl = QtWidgets.QLabel(tr("eventos de movimento"))
        ev_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
        ev_lbl.setAlignment(QtCore.Qt.AlignmentFlag.AlignCenter)
        ev_box.addWidget(ev_lbl)
        cards.addLayout(ev_box)
        outer.addLayout(cards)

        # === Plot principal: histórico completo da sessão ===
        # 2 plots empilhados: (1) X/Y/Z (2) Magnitude + activity
        split = QtWidgets.QSplitter(QtCore.Qt.Orientation.Vertical)

        # Plot 1: X/Y/Z históricos
        top_w = QtWidgets.QWidget()
        tl = QtWidgets.QVBoxLayout(top_w); tl.setContentsMargins(2, 2, 2, 2)
        tl.addWidget(QtWidgets.QLabel(tr("Acelerômetro X / Y / Z (sessão completa)")))
        self.accel_history_plot = pg.PlotWidget(enableMenu=False)
        self.accel_history_plot.showGrid(x=True, y=True, alpha=0.15)
        self.accel_history_plot.setLabel("left", tr("Aceleração"), units="g")
        self.accel_history_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.accel_history_plot.addLegend(offset=(10, 10))
        self.accel_history_plot.setMenuEnabled(False)
        self.accel_x_curve = self.accel_history_plot.plot(
            pen=pg.mkPen("#ff6677", width=1.4), name=tr("X (lateral)"))
        self.accel_y_curve = self.accel_history_plot.plot(
            pen=pg.mkPen("#a3ff66", width=1.4), name=tr("Y (frontal)"))
        self.accel_z_curve = self.accel_history_plot.plot(
            pen=pg.mkPen("#66ddff", width=1.4), name=tr("Z (vertical)"))
        tl.addWidget(self.accel_history_plot)
        split.addWidget(top_w)

        # Plot 2: magnitude + activity
        bot_w = QtWidgets.QWidget()
        bl = QtWidgets.QVBoxLayout(bot_w); bl.setContentsMargins(2, 2, 2, 2)
        bl.addWidget(QtWidgets.QLabel(tr("Magnitude |g| e Índice de Atividade")))
        self.accel_mag_plot = pg.PlotWidget(enableMenu=False)
        self.accel_mag_plot.showGrid(x=True, y=True, alpha=0.15)
        self.accel_mag_plot.setLabel("left", tr("Magnitude/atividade"))
        self.accel_mag_plot.setLabel("bottom", tr("Tempo"), units="s")
        self.accel_mag_plot.addLegend(offset=(10, 10))
        self.accel_mag_plot.setMenuEnabled(False)
        self.accel_mag_curve = self.accel_mag_plot.plot(
            pen=pg.mkPen(COLORS["accent"], width=1.4), name="|g|")
        self.accel_activity_curve = self.accel_mag_plot.plot(
            pen=pg.mkPen(SIGNAL_TYPE_COLORS["EMG"], width=1.4), name=tr("Atividade"))
        # Eventos de movimento (scatter)
        self.accel_event_scatter = pg.ScatterPlotItem(
            size=8, brush=pg.mkBrush("#ffaa55"),
            pen=pg.mkPen("#ffffff", width=1), symbol="t")
        self.accel_mag_plot.addItem(self.accel_event_scatter)
        # Linha activity threshold
        self.accel_activity_thr_line = pg.InfiniteLine(
            pos=0.15, angle=0,
            pen=pg.mkPen(COLORS["warning"], style=QtCore.Qt.PenStyle.DashLine))
        self.accel_mag_plot.addItem(self.accel_activity_thr_line)
        bl.addWidget(self.accel_mag_plot)
        split.addWidget(bot_w)
        split.setSizes([350, 250])
        outer.addWidget(split, stretch=1)

        # Estado interno: histórico downsampled da sessão (~10 Hz)
        self._accel_full_t = []  # tempo desde session_start (s)
        self._accel_full_x = []
        self._accel_full_y = []
        self._accel_full_z = []
        self._accel_full_mag = []
        self._accel_full_activity = []
        self._accel_last_log_t = 0.0
        self._accel_event_count = 0
        self._accel_event_times = []
        self._accel_in_event = False
        return widget

    def _update_accelerometer_view(self):
        """Atualiza histórico de acelerômetro, postura e atividade."""
        if not hasattr(self, "accel_history_plot"): return
        accel_data = self._ordered_accel()  # shape (3, N) últimos 10s
        if accel_data.shape[1] < 4: return
        # Valores atuais (média dos últimos 100 ms)
        n_recent = min(accel_data.shape[1], int(SAMPLE_RATE * 0.1))
        x_now = float(np.mean(accel_data[0, -n_recent:]))
        y_now = float(np.mean(accel_data[1, -n_recent:]))
        z_now = float(np.mean(accel_data[2, -n_recent:]))
        mag = float(np.sqrt(x_now**2 + y_now**2 + z_now**2))

        # Roll / Pitch (graus)
        import math
        roll  = math.degrees(math.atan2(y_now, max(abs(z_now), 1e-6) * (1 if z_now >= 0 else -1)))
        pitch = math.degrees(math.atan2(-x_now, math.sqrt(y_now**2 + z_now**2)))
        # Activity = std da magnitude no buffer recente
        n_w = min(accel_data.shape[1], int(SAMPLE_RATE * 1.0))
        mag_window = np.sqrt(accel_data[0, -n_w:]**2 +
                              accel_data[1, -n_w:]**2 +
                              accel_data[2, -n_w:]**2)
        activity = float(np.std(mag_window))

        # Cards
        self.accel_roll_lbl.setText(f"Roll:  {roll:+6.1f}°")
        self.accel_pitch_lbl.setText(f"Pitch: {pitch:+6.1f}°")
        self.accel_mag_lbl.setText(f"|g|:   {mag:5.2f}")

        # Postura
        if   abs(pitch) > 30:
            posture = tr("Inclinado para a frente") if pitch > 0 else tr("Inclinado para trás")
        elif abs(roll) > 30:
            posture = tr("Lateral dir") if roll > 0 else tr("Lateral esq")
        elif mag < 0.5:
            posture = tr("Queda detectada!")
        else:
            posture = tr("Vertical (OK)")
        self.accel_posture_lbl.setText(posture)

        # Atividade
        if   activity < 0.05: act_text = "PARADO";    ac = SIGNAL_TYPE_COLORS["EoG"]
        elif activity < 0.15: act_text = "LEVE";      ac = SIGNAL_TYPE_COLORS["EEG"]
        elif activity < 0.5:  act_text = "MODERADO";  ac = COLORS["warning"]
        else:                 act_text = "INTENSO";   ac = COLORS["error"]
        self.accel_activity_lbl.setText(f"{act_text}\n{activity:.3f} g")
        self.accel_activity_lbl.setStyleSheet(
            f"color: {ac}; font-size: 16pt; font-weight: bold; "
            f"padding: 6px 12px; border: 2px solid {ac}; border-radius: 6px;")

        # Detecção de evento (entrada em estado MODERADO/INTENSO)
        was_in_event = self._accel_in_event
        now_in_event = activity > 0.15
        if now_in_event and not was_in_event:
            self._accel_event_count += 1
            self._accel_event_times.append(time.time())
            self.accel_event_count_lbl.setText(str(self._accel_event_count))
        self._accel_in_event = now_in_event

        # ===== Histórico downsampled (~10 Hz) =====
        now = time.time()
        if (now - self._accel_last_log_t) >= 0.1:
            self._accel_last_log_t = now
            t_rel = now - (self.session_start or now)
            self._accel_full_t.append(t_rel)
            self._accel_full_x.append(x_now)
            self._accel_full_y.append(y_now)
            self._accel_full_z.append(z_now)
            self._accel_full_mag.append(mag)
            self._accel_full_activity.append(activity)
            # Limita histórico a 1h (~36k pontos)
            max_pts = 36000
            if len(self._accel_full_t) > max_pts:
                for arr in (self._accel_full_t, self._accel_full_x,
                            self._accel_full_y, self._accel_full_z,
                            self._accel_full_mag, self._accel_full_activity):
                    del arr[: len(arr) - max_pts]
        # Atualiza plots (a cada chamada, dados já estão prontos)
        if self._accel_full_t:
            self.accel_x_curve.setData(self._accel_full_t, self._accel_full_x)
            self.accel_y_curve.setData(self._accel_full_t, self._accel_full_y)
            self.accel_z_curve.setData(self._accel_full_t, self._accel_full_z)
            self.accel_mag_curve.setData(self._accel_full_t, self._accel_full_mag)
            self.accel_activity_curve.setData(self._accel_full_t, self._accel_full_activity)
        # Scatter de eventos
        if self._accel_event_times and self.session_start:
            t_evs = [t - self.session_start for t in self._accel_event_times]
            ys = [0.3] * len(t_evs)
            self.accel_event_scatter.setData(t_evs, ys)

    # ---- Tab: Histórico ----
    def _build_history_tab(self):
        """Monta a aba Histórico: um único gráfico com todos os canais sobrepostos
        ao longo do buffer inteiro.

        A janela exibida é BUFFER_SECONDS. Cria curvas para MAX_CHANNELS mesmo
        quando há menos canais ativos.
        """
        widget = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(widget)
        layout.setContentsMargins(10, 10, 10, 10)
        info = QtWidgets.QLabel(
            tr("Ultimos {0} segundos — todos os canais sobrepostos").format(BUFFER_SECONDS))
        info.setStyleSheet(f"color: {COLORS['text_dim']}; padding: 4px;")
        layout.addWidget(info)
        self.history_plot = pg.PlotWidget(enableMenu=False)
        self.history_plot.showGrid(x=True, y=True, alpha=0.15)
        self.history_plot.setLabel("left", tr("Amplitude"), units="uV")
        self.history_plot.setLabel("bottom", tr("Tempo"), units="s")
        # 4 colunas: com 8 canais a legenda cai de 8 linhas para 2 e para de
        # cobrir a borda esquerda do tracado.
        self.history_plot.addLegend(offset=(10, 10), colCount=4)
        self.history_curves = []
        for ch in range(MAX_CHANNELS):
            curve = self.history_plot.plot(
                pen=pg.mkPen(CHANNEL_COLORS[ch], width=1.0), name=f"CH{ch + 1}")
            self.history_curves.append(curve)
        layout.addWidget(self.history_plot)
        return widget

    # ==================================================================
    # Expansão multi-step (8 → 16 → 24 → 32 → 40 → 48 → 56 → 64 canais)
    # ==================================================================
    def _snap_to_expansion_step(self, n):
        """Arredonda n para o passo válido mais próximo em EXPANSION_STEPS."""
        try:
            n = int(n)
        except (TypeError, ValueError):
            return BASE_CHANNELS
        n = max(BASE_CHANNELS, min(MAX_CHANNELS, n))
        if n in EXPANSION_STEPS:
            return n
        return min(EXPANSION_STEPS, key=lambda s: abs(s - n))

    def _refresh_mapping_rows(self):
        """Mostra no Mapeamento de Canais só os canais em uso; o resto fica
        opcional atrás da caixa \"Mostrar todos\"."""
        linhas = getattr(self, "_map_rows", None)
        if not linhas:
            return
        todos = (hasattr(self, "map_show_all_chk")
                 and self.map_show_all_chk.isChecked())
        for ch, (lbl, cb) in enumerate(linhas):
            vis = todos or ch < self.num_channels
            if lbl is not None:
                lbl.setVisible(vis)
            cb.setVisible(vis)

    def _show_channel_count_menu(self):
        """Menu do badge \"Nch\" do cabeçalho: escolhe a contagem de canais em
        uso sem sair da tela.

        Não duplica lógica: seleciona o índice no combo de Expansão, cujo
        handler (_on_expansion_combo_changed) já cuida de tudo — snap, daisy,
        comando à placa e propagação para as abas.
        """
        menu = QtWidgets.QMenu(self)
        atual = self.num_channels
        for n in EXPANSION_STEPS:
            ac = menu.addAction(tr("{0} canais").format(n) + ("   ✓" if n == atual else ""))
            ac.setData(n)
        menu.addSeparator()
        dica = menu.addAction(tr("Definir tipo de cada canal…"))
        dica.setData("tipos")
        escolha = menu.exec(QtGui.QCursor.pos())
        if escolha is None:
            return
        if escolha.data() == "tipos":
            # atalho para Configurar → Filtros e Canais, onde os tipos moram
            self.tabs.setCurrentIndex(0)
            g = self.tabs.currentWidget()
            if isinstance(g, QtWidgets.QTabWidget) and g.count() > 2:
                g.setCurrentIndex(self._pos_aba("setup", 2))
            return
        n = int(escolha.data())
        if hasattr(self, "expansion_combo"):
            try:
                i = EXPANSION_STEPS.index(n)
                if self.expansion_combo.currentIndex() == i:
                    return                       # já está nesse passo
                self.expansion_combo.setCurrentIndex(i)   # dispara o handler
                return
            except ValueError:
                pass
        self._set_num_channels(n)                # fallback sem combo

    def _on_expansion_combo_changed(self, idx):
        """Handler principal — chamado quando o usuário escolhe um novo passo."""
        if not hasattr(self, "expansion_combo"): return
        n = self.expansion_combo.itemData(idx)
        if n is None: return
        new_n = self._snap_to_expansion_step(int(n))
        self.daisy_enabled = (new_n > BASE_CHANNELS)
        self._set_num_channels(new_n)
        # Hardware: envia comando Cyton apenas para 8/16 (protocolo OpenBCI nativo)
        if self.serial_thread and self.serial_thread.isRunning() \
           and self.serial_thread.mode == "hardware":
            if new_n <= CYTON_MAX_CHANNELS:
                cmd = "C" if new_n > BASE_CHANNELS else "c"
                self.serial_thread.send_command(cmd)
                self._log(f"[Expansão] Comando '{cmd}' enviado à placa Cyton")
            else:
                self._log(
                    f"[Expansão] {new_n} canais excedem o protocolo Cyton+Daisy "
                    f"(máx {CYTON_MAX_CHANNELS}). Aplicando apenas no host — "
                    f"para hardware customizado (Bionica Lab) com mais módulos.",
                    error=False)

    def _on_expansion_toggled(self, checked):
        """Handler legacy (QCheckBox binário oculto) — mantido para compat."""
        self.daisy_enabled = bool(checked)
        new_n = CYTON_MAX_CHANNELS if self.daisy_enabled else BASE_CHANNELS
        self._set_num_channels(new_n)
        if self.serial_thread and self.serial_thread.isRunning() \
           and self.serial_thread.mode == "hardware":
            cmd = "C" if self.daisy_enabled else "c"
            self.serial_thread.send_command(cmd)
            self._log(f"[Expansão] Comando '{cmd}' enviado à placa")

    def _effective_sample_rate(self, mode=None):
        """Taxa que de fato chega em _on_sample, dados o modo e a expansão.

        Só o hardware com expansão divide por 2: _read_packet emparelha dois
        pacotes de 8 canais para formar uma amostra de 16, então 250 pacotes/s
        viram 125 amostras/s (medido: 1000 pacotes -> 500 amostras). Simulação
        segue o marcapasso de SAMPLE_RATE e playback anda no ritmo do CSV, por
        isso ambos continuam nominais. Sem thread (mode=None) mantém o nominal —
        _connect chama de novo já com o modo real.
        """
        if mode is None:
            mode = getattr(getattr(self, "serial_thread", None), "mode", None)
        if mode == "hardware" and getattr(self, "daisy_enabled", False):
            return float(SAMPLE_RATE) / 2.0
        return float(SAMPLE_RATE)

    def _update_session_sample_rate(self, mode=None):
        """Fixa self.sample_rate e RECONSTRÓI o FilterChain quando a taxa muda.

        Era o elo que não existia: a expansão mexia em num_channels e em
        daisy_enabled, mas ninguém avisava a cadeia de filtros, que seguia
        projetada para o dobro da taxa real do sinal.
        """
        sr = self._effective_sample_rate(mode)
        if abs(sr - getattr(self, "sample_rate", 0.0)) < 1e-9:
            return
        self.sample_rate = sr
        fc = getattr(self, "filters", None)
        if fc is not None and fc.set_sample_rate(sr):
            self._log(f"Taxa de amostragem da sessão: {sr:.0f} Hz — "
                      f"filtros reconstruídos (Nyquist {sr / 2:.1f} Hz)")

    def _set_num_channels(self, n):
        """Ponto único de mudança do número de canais ativos: atualiza o
        indicador, sincroniza os controles e propaga a mudança para as demais
        abas.

        Faz snap para um passo válido de EXPANSION_STEPS e retorna sem efeito
        se o valor não mudou. Bloqueia os sinais do combo de expansão e do
        checkbox legado (oculto) para evitar reentrância. daisy_enabled passa a
        ser apenas n > BASE_CHANNELS. Não envia comando à placa — quem faz isso
        é o chamador.
        """
        n = self._snap_to_expansion_step(n)
        if n == self.num_channels:
            return
        self.num_channels = n
        self._atualiza_aviso_multimodal()
        self.expansion_label.setText(f"{n}ch")
        if n > BASE_CHANNELS:
            self.expansion_label.setStyleSheet(
                f"color: {COLORS['expansion']}; font-weight: bold; padding: 0 6px;"
                f"border: 1px solid {COLORS['expansion']}; border-radius: 3px;")
        else:
            self.expansion_label.setStyleSheet(
                f"color: {COLORS['text_dim']}; font-weight: bold; padding: 0 6px;"
                f"border: 1px solid {COLORS['border']}; border-radius: 3px;")
        # Sincroniza o combo principal sem reentrar no handler
        if hasattr(self, "expansion_combo"):
            try:
                target_idx = EXPANSION_STEPS.index(n)
            except ValueError:
                target_idx = 0
            if self.expansion_combo.currentIndex() != target_idx:
                self.expansion_combo.blockSignals(True)
                self.expansion_combo.setCurrentIndex(target_idx)
                self.expansion_combo.blockSignals(False)
        # Sincroniza o checkbox legacy (oculto) sem reentrar no handler
        want_checked = (n > BASE_CHANNELS)
        if hasattr(self, "expansion_toggle") and \
           self.expansion_toggle.isChecked() != want_checked:
            self.expansion_toggle.blockSignals(True)
            self.expansion_toggle.setChecked(want_checked)
            self.expansion_toggle.blockSignals(False)
        self.daisy_enabled = want_checked
        # A expansão acabou de mudar a taxa real de aquisição; sem esta chamada
        # o FilterChain seguiria com os coeficientes da taxa anterior, que é o
        # que fazia o notch de 60 Hz cair em 30 Hz no modo 16 canais.
        self._update_session_sample_rate()
        self._apply_channel_visibility()
        self._topo_broadcast_nchan(n)
        self.emg_widget.set_num_channels(n)
        # O rotulo "N canais EMG ativos" tambem depende da placa
        if hasattr(self, "emg_rows"):
            try: self._emg_refresh_channel_types()
            except Exception: pass
        # Propaga para combos de canal das abas multimodais (EMG / EoG / ECG / Focus)
        self._sync_multimodal_tabs_with_channels()
        # Mapeamento de Canais acompanha: só os canais em uso ficam visíveis
        self._refresh_mapping_rows()
        self._log(f"Canais ativos: {n}")

    def _sync_multimodal_tabs_with_channels(self):
        """Propaga `num_channels` para TODAS as abas que listam canais.

        Quando o usuário escolhe na aba Conexão (ex.: 32 canais), todas as
        abas dependentes refletem isso automaticamente — sem precisar
        reconfigurar manualmente.

        Cobre:
            - Cards EMG (linhas + mapeamento muscular)
            - Combos ECG / EoG (filtra apenas canais marcados)
            - EMG Joystick (4 combos)
            - Focus / SSVEP (canal único EEG)
            - Aba Filtros e Canais (channel_type_combos, threshold inline,
              filter hint labels)
        """
        n = getattr(self, "num_channels", MAX_CHANNELS)
        # ---- EMG joystick — 4 combos por direção ----
        if hasattr(self, "_joy_axes"):
            try: self._joy_repopulate_combos()
            except Exception: pass
        # ---- ECG — combo de canal cardíaco ----
        if hasattr(self, "ecg_channel_combo"):
            try: self._populate_ecg_channel_combo()
            except Exception: pass
        # ---- EoG — combos H/V ----
        if hasattr(self, "eog_h_combo") and hasattr(self, "eog_v_combo"):
            try: self._populate_eog_channel_combos()
            except Exception: pass
        # ---- Focus — combo de canal único ----
        if hasattr(self, "focus_channel_combo"):
            try:
                prev = self.focus_channel_combo.currentData()
            except Exception:
                prev = None
            self.focus_channel_combo.blockSignals(True)
            self.focus_channel_combo.clear()
            for ch in range(n):
                elec = (self.config.channel_mapping[ch]
                        if ch < len(self.config.channel_mapping)
                        else f"E{ch+1}")
                self.focus_channel_combo.addItem(f"CH{ch+1} ({elec})", ch)
            idx = -1
            if prev is not None and isinstance(prev, int) and prev < n:
                idx = self.focus_channel_combo.findData(prev)
            if idx < 0:
                # Sem isto o combo caía no indice 0 (Fp1), o pior eletrodo
                # possivel para foco e para SSVEP.
                pref = self._focus_canal_preferido(n)
                idx = (self.focus_channel_combo.findData(pref)
                       if pref is not None else -1)
            if idx >= 0:
                self.focus_channel_combo.setCurrentIndex(idx)
            self.focus_channel_combo.blockSignals(False)
        # ---- Cards EMG (cada CH tem uma linha de widgets) ----
        if hasattr(self, "emg_rows"):
            for ch, row in enumerate(self.emg_rows):
                visible = (ch < n)
                # ch_lbl entrou na lista: com placa de 8 canais os rótulos
                # CH9…CH64 ficavam sozinhos, sem linha, embaixo de CH8
                for key in ("ch_lbl", "type_lbl", "elec_lbl", "bar", "peak_lbl",
                            "th_spin", "led", "count_lbl"):
                    w = row.get(key)
                    if w is not None:
                        w.setVisible(visible)
        # ---- Mapeamento muscular EMG (combos + ação + %MVC) ----
        if hasattr(self, "emg_muscle_combos"):
            for ch in range(min(len(self.emg_muscle_combos), MAX_CHANNELS)):
                self.emg_muscle_combos[ch].setVisible(ch < n)
        if hasattr(self, "emg_action_lbls"):
            for ch in range(min(len(self.emg_action_lbls), MAX_CHANNELS)):
                self.emg_action_lbls[ch].setVisible(ch < n)
        if hasattr(self, "emg_mvc_pct_lbls"):
            for ch in range(min(len(self.emg_mvc_pct_lbls), MAX_CHANNELS)):
                self.emg_mvc_pct_lbls[ch].setVisible(ch < n)
        # ---- Aba Filtros e Canais: combos de tipo + hint + threshold ----
        if hasattr(self, "channel_type_combos"):
            for ch in range(min(len(self.channel_type_combos), MAX_CHANNELS)):
                self.channel_type_combos[ch].setVisible(ch < n)
        if hasattr(self, "channel_filter_hint_lbls"):
            for ch in range(min(len(self.channel_filter_hint_lbls), MAX_CHANNELS)):
                self.channel_filter_hint_lbls[ch].setVisible(ch < n)
        if hasattr(self, "channel_emg_thresh_inline"):
            for ch in range(min(len(self.channel_emg_thresh_inline), MAX_CHANNELS)):
                self.channel_emg_thresh_inline[ch].setVisible(ch < n)
        if hasattr(self, "channel_ch_lbls"):
            for ch in range(min(len(self.channel_ch_lbls), MAX_CHANNELS)):
                self.channel_ch_lbls[ch].setVisible(ch < n)
        # ---- Cabecalhos dos blocos de 8 canais (grade muscular e Filtros) ----
        # Sem isto os 5 cabecalhos de cada bloco vazio seguravam a largura da
        # grade inteira e a aba rolava na horizontal.
        n_blocos = (max(1, n) + 7) // 8
        for _hdrs in (getattr(self, "emg_muscle_hdrs", []),
                      getattr(self, "channel_hdrs", [])):
            for b, bloco in enumerate(_hdrs):
                for lbl in bloco:
                    lbl.setVisible(b < n_blocos)
        if hasattr(self, "emg_ch_lbls"):
            for ch in range(min(len(self.emg_ch_lbls), MAX_CHANNELS)):
                self.emg_ch_lbls[ch].setVisible(ch < n)
        if hasattr(self, "emg_mvc_btns"):
            for ch in range(min(len(self.emg_mvc_btns), MAX_CHANNELS)):
                self.emg_mvc_btns[ch].setVisible(ch < n)
        # O sizeHint da grade fica em cache: sem invalidar, a aba continua
        # pedindo a largura dos 8 blocos mesmo com 7 deles escondidos.
        for _grade in (getattr(self, "emg_muscle_grid", None),
                       getattr(self, "channel_grid", None)):
            if _grade is None:
                continue
            try:
                _grade.invalidate()
                _grade.activate()
            except Exception:
                pass

    def _sincroniza_legenda_historico(self, ch, visivel):
        """Tira da legenda do Historico a curva escondida e devolve a que volta.

        As 64 curvas nasciam registradas: com 8 canais em uso as outras 56
        continuavam listadas (com o icone de olho riscado) e a legenda ficava
        mais alta que o proprio grafico.
        """
        plot_item = getattr(getattr(self, "history_plot", None), "plotItem", None)
        leg = getattr(plot_item, "legend", None) if plot_item is not None else None
        if leg is None or not hasattr(self, "history_curves"):
            return
        if not hasattr(self, "_hist_leg_on"):
            # Todas nascem na legenda (o name= do plot() registra na hora).
            self._hist_leg_on = set(range(MAX_CHANNELS))
        nome = "CH%d" % (ch + 1)
        curva = self.history_curves[ch]
        try:
            if visivel and ch not in self._hist_leg_on:
                leg.addItem(curva, nome)
                self._hist_leg_on.add(ch)
            elif not visivel and ch in self._hist_leg_on:
                try:
                    leg.removeItem(curva)
                except Exception:
                    leg.removeItem(nome)
                self._hist_leg_on.discard(ch)
        except Exception:
            pass

    def _apply_channel_visibility(self):
        """Mostra/esconde widgets dos canais 9-16 conforme num_channels atual."""
        n = self.num_channels
        for ch in range(MAX_CHANNELS):
            visible = (ch < n) and self.channel_active[ch]
            if hasattr(self, "channel_plots"):
                self.channel_plots[ch].setVisible(visible)
            if hasattr(self, "history_curves"):
                self.history_curves[ch].setVisible(visible)
                self._sincroniza_legenda_historico(ch, visible)
            if hasattr(self, "channel_checks"):
                self.channel_checks[ch].setEnabled(ch < n)
                self.channel_checks[ch].setVisible(ch < n)
            # Stats table rows
            if hasattr(self, "stats_table"):
                self.stats_table.setRowHidden(ch, ch >= n)
            # Combos: habilita/desabilita itens 9-16
            for combo in (getattr(self, "analysis_channel", None),
                          getattr(self, "spec_channel", None),
                          getattr(self, "topo_channel_combo", None)):
                if combo is not None:
                    item = combo.model().item(ch)
                    if item is not None:
                        item.setEnabled(ch < n)
                    if ch < n and combo.currentIndex() >= n:
                        combo.setCurrentIndex(0)
            # Hardware grid rows
            if hasattr(self, "hw_row_widgets") and ch < len(self.hw_row_widgets):
                for w in self.hw_row_widgets[ch]:
                    w.setVisible(ch < n)
            # LEDs de qualidade
            if hasattr(self, "quality_leds") and ch < len(self.quality_leds):
                self.quality_leds[ch].setVisible(ch < n)

        # --- Atualiza altura mínima do GraphicsLayoutWidget ---
        # Sem isso, 16 canais ficariam espremidos em 700 px (zoom inviavel).
        # Com altura mínima por canal, ScrollArea aparece e zoom Y funciona limpo.
        if hasattr(self, "channels_layout") and hasattr(self, "_channels_per_plot_height"):
            n_visible = sum(1 for ch in range(MAX_CHANNELS)
                            if ch < n and self.channel_active[ch])
            total_h = max(1, n_visible) * self._channels_per_plot_height + 30
            self.channels_layout.setMinimumHeight(total_h)
            # Label "Tempo" so no ultimo canal visivel (limpo)
            last_visible = -1
            for ch in range(MAX_CHANNELS):
                if ch < n and self.channel_active[ch]:
                    last_visible = ch
            for ch in range(MAX_CHANNELS):
                if not hasattr(self, "channel_plots"): break
                show_xlabel = (ch == last_visible)
                bx = self.channel_plots[ch].getAxis("bottom")
                bx.setLabel(tr("Tempo") if show_xlabel else "", units="s" if show_xlabel else "")
                bx.showLabel(show_xlabel)

        # Recalcula layout do modo Empilhado (ticks de canal)
        self._montage_last_nvis = -1   # força refresh no próximo _update_montage
        if hasattr(self, "montage_plot"):
            self._refresh_montage_layout()

    def _detect_expansion(self):
        """Tenta detectar automaticamente o número de canais ativo.

        Em Playback, conta as colunas do CSV: estrutura esperada é
        ``timestamp + N_canais + ax + ay + az [+ marker]`` (≥ 1 + N + 3).
        Snap-a para o passo mais próximo em EXPANSION_STEPS (8, 16, ..., 64).
        Em Hardware, envia '?' para a placa (apenas Cyton suporta esse
        protocolo; placas customizadas devem implementar resposta análoga).
        """
        mode_idx = self.mode_combo.currentIndex()
        if mode_idx == 2:  # Playback
            path = self.playback_path_edit.text().strip()
            if not path or not os.path.exists(path):
                self._log("Selecione um CSV de playback antes de detectar", error=True); return
            try:
                with open(path, "r", encoding="utf-8") as f:
                    header = f.readline()
                ncols = header.count(",") + 1
                # canais inferidos = ncols - 1 (timestamp) - 3 (accel) - até 1 (marker)
                inferred = ncols - 1 - 3
                # Tenta sem marker e com marker
                candidates = [inferred, inferred - 1]
                detected = None
                for c in candidates:
                    if c in EXPANSION_STEPS:
                        detected = c; break
                if detected is None:
                    # snap ao passo mais próximo se estiver dentro do range
                    if BASE_CHANNELS <= inferred <= MAX_CHANNELS:
                        detected = self._snap_to_expansion_step(inferred)
                if detected is not None:
                    self._set_num_channels(detected)
                    extra = detected - BASE_CHANNELS
                    desc = ("placa base" if detected == BASE_CHANNELS
                            else f"base + {extra//8} módulo(s) de expansão")
                    self._log(f"✓ Auto-detecção: CSV tem {ncols} colunas → "
                              f"modo {detected} canais ({desc})")
                else:
                    self._log(f"Auto-detecção: CSV não reconhecido ({ncols} colunas, "
                              f"~{inferred} canais inferidos)", error=True)
            except Exception as exc:
                self._log(f"Erro lendo cabeçalho do CSV: {exc}", error=True)
        elif mode_idx == 1:  # Simulação
            self._log("Modo simulação: escolha o número de canais no seletor "
                      "(8 / 16 / 24 / 32 / 40 / 48 / 56 / 64)")
        else:  # Hardware
            if not (self.serial_thread and self.serial_thread.isRunning()):
                self._log("Conecte primeiro em modo Hardware para detectar via dispositivo", error=True); return
            self.serial_thread.send_command("?")  # pede status (Cyton)
            self._log("[Expansão] Comando '?' enviado — verifique resposta no log do dispositivo. "
                      "Em seguida, ajuste manualmente o seletor de canais conforme detectado.")

    # ==================================================================
    # Handlers
    # ==================================================================
    def _refresh_ports(self):
        """Repopula o combo de portas seriais com o que o sistema enumera no
        momento.

        O device (ex.: COM7) fica no userData e o texto exibido inclui a
        descrição; sem portas, insere um item com data None, que o código de
        conexão precisa tratar. Não confundir com o método homônimo de
        LauncherScreen, que preenche outro combo.
        """
        self.port_combo.clear()
        ports = list(serial.tools.list_ports.comports())
        if not ports:
            self.port_combo.addItem(tr("(nenhuma porta detectada)"), None)
        else:
            for p in ports:
                self.port_combo.addItem(f"{p.device} — {p.description}", p.device)
        self._log(f"Portas atualizadas — {len(ports)} encontrada(s)")

    # ==================================================================
    # Bluetooth — scan BLE async + ajuda de pareamento
    # ==================================================================
    def _bt_scan_start(self):
        """Inicia scan BLE em thread separada (não bloqueia UI)."""
        if not hasattr(self, "bt_devices_table"): return
        # Se já tem scan em andamento, avisa
        if self._bt_scanner_thread and self._bt_scanner_thread.isRunning():
            self.bt_status_lbl.setText(tr("Já tem um scan em andamento..."))
            return
        if not HAS_BLEAK:
            QtWidgets.QMessageBox.information(
                self, tr("Bluetooth indisponível"),
                tr("Para varrer dispositivos BLE, instale a biblioteca:\n\n"
                "    pip install bleak\n\n"
                "Para dispositivos Bluetooth Clássico (HC-05, módulos seriais), "
                "pareie diretamente pelo Windows (Configurações → Bluetooth) — "
                "uma porta COM virtual será criada e aparecerá na lista de portas.")
            )
            self.bt_status_lbl.setText(tr("bleak não instalado — pip install bleak"))
            return
        self.bt_devices_table.setRowCount(0)
        self.bt_scan_btn.setEnabled(False)
        self.bt_status_lbl.setText(tr("Procurando dispositivos BLE (8 s)..."))
        self.bt_status_lbl.setStyleSheet(f"color: {COLORS['warning']};")
        # Cria e lança thread
        self._bt_scanner_thread = _BluetoothScanThread(duration_s=8.0, parent=self)
        self._bt_scanner_thread.scan_done.connect(self._bt_on_scan_done)
        self._bt_scanner_thread.scan_failed.connect(self._bt_on_scan_failed)
        self._bt_scanner_thread.finished.connect(
            lambda: self.bt_scan_btn.setEnabled(True))
        self._bt_scanner_thread.start()
        self._audit_event("bluetooth_scan_started", duration_s=8)

    def _bt_on_scan_done(self, devices):
        """Recebe lista de devices e popula tabela."""
        if not hasattr(self, "bt_devices_table"): return
        # Ordena por RSSI (mais forte primeiro)
        devices_sorted = sorted(
            devices,
            key=lambda d: (-d.get("rssi", -999) if d.get("rssi") is not None else 999)
        )
        self.bt_devices_table.setRowCount(len(devices_sorted))
        for i, dev in enumerate(devices_sorted):
            name_item = QtWidgets.QTableWidgetItem(dev.get("name", ""))
            addr_item = QtWidgets.QTableWidgetItem(dev.get("address", ""))
            rssi = dev.get("rssi")
            rssi_item = QtWidgets.QTableWidgetItem(f"{rssi}" if rssi is not None else "-")
            # Cor por força de sinal
            if rssi is not None:
                if rssi > -60:   rssi_item.setForeground(QtGui.QColor(SIGNAL_TYPE_COLORS["EEG"]))
                elif rssi > -75: rssi_item.setForeground(QtGui.QColor(COLORS["warning"]))
                else:            rssi_item.setForeground(QtGui.QColor(COLORS["error"]))
            type_item = QtWidgets.QTableWidgetItem(dev.get("type", "BLE"))
            self.bt_devices_table.setItem(i, 0, name_item)
            self.bt_devices_table.setItem(i, 1, addr_item)
            self.bt_devices_table.setItem(i, 2, rssi_item)
            self.bt_devices_table.setItem(i, 3, type_item)
        self.bt_status_lbl.setText(tr("{0} dispositivo(s) encontrado(s).").format(len(devices_sorted)))
        self.bt_status_lbl.setStyleSheet(f"color: {SIGNAL_TYPE_COLORS['EEG']};")
        self._log(f"Bluetooth scan concluído: {len(devices_sorted)} dispositivos")
        self._audit_event("bluetooth_scan_done", count=len(devices_sorted))

    def _bt_on_scan_failed(self, error_msg):
        """Mostra no painel Bluetooth a mensagem de erro emitida pela thread de
        scan BLE."""
        self.bt_status_lbl.setText(tr("Falha: {0}").format(error_msg))
        self.bt_status_lbl.setStyleSheet(f"color: {COLORS['error']};")
        self._log(f"Bluetooth scan falhou: {error_msg}", error=True)

    def _bt_show_pair_help(self):
        """Mostra instruções de pareamento Bluetooth no Windows."""
        QtWidgets.QMessageBox.information(
            self, tr("Como parear via Bluetooth (Windows)"),
            tr("<b>Para placas com BT Serial (HC-05 / HC-06 / Cyton-BT):</b><br><br>"
            "1. Abra <b>Configurações → Dispositivos → Bluetooth e outros</b><br>"
            "2. Clique em <b>Adicionar Bluetooth</b> → Bluetooth<br>"
            "3. Selecione sua placa (PIN comum: <code>1234</code> ou <code>0000</code>)<br>"
            "4. Após parear, abra <b>Mais opções de Bluetooth → COM Ports</b><br>"
            "5. Anote a porta COM <b>outgoing</b> (ex.: COM7)<br>"
            "6. Volte aqui, clique <b>Atualizar</b> na lista de portas, "
            "selecione a COMx e conecte normalmente.<br><br>"
            "<b>Para placas BLE puras (Ganglion):</b> use o scan acima — "
            "a conexão BLE direta exige firmware específico que sua placa "
            "Bionica Lab deve implementar (GATT services com characteristic "
            "para streaming de amostras EEG).")
        )

    def _on_mode_changed(self, idx):
        """Habilita os controles de playback só quando o modo escolhido é replay
        de CSV e atualiza a marca d'água da tela.

        O índice 2 é posicional: reordenar os itens de mode_combo quebra a
        detecção de playback.
        """
        is_playback = (idx == 2)
        self.playback_path_edit.setEnabled(is_playback)
        self.playback_browse_btn.setEnabled(is_playback)
        self.playback_progress.setVisible(is_playback)
        # Watermark "SIMULAÇÃO / PLAYBACK"
        if hasattr(self, "mode_combo"):
            self._update_simulation_overlay(self.mode_combo.currentText())

    def _select_playback_file(self):
        """Abre o diálogo de arquivo para escolher o CSV que será reproduzido no
        modo Playback.

        Depois de preencher o campo de caminho chama _detect_expansion(), que
        ajusta o número de canais a partir do próprio arquivo escolhido.
        """
        path, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Selecionar CSV para playback"), self.config.save_directory,
            tr("CSV (*.csv);;Todos (*)"))
        if path:
            self.playback_path_edit.setText(path)
            # Auto-detecta canais ao escolher o arquivo
            self._detect_expansion()

    def _detect_bad_channels(self):
        """Detecta canais ruins via 3 critérios:
        1) Variância > 5× mediana das variâncias (saturação/ruído)
        2) Variância < 0.05× mediana (canal "morto" / desconectado)
        3) Correlação média com vizinhos < 0.2 (eletrodo solto)
        """
        if not hasattr(self, "_ordered_buffer"):
            return
        data = self._ordered_buffer()
        n_total = data.shape[1]
        if n_total < SAMPLE_RATE * 2:
            self.bad_detect_status.setText(tr("Coletar pelo menos 2s de sinal antes."))
            self.bad_detect_status.setStyleSheet(f"color: {COLORS['warning']};")
            return
        n = getattr(self, "num_channels", MAX_CHANNELS)
        bad = []
        reasons = {}
        # Variâncias por canal
        var_per_ch = np.var(data[:n], axis=1)
        med_var = float(np.median(var_per_ch[var_per_ch > 0])) if (var_per_ch > 0).any() else 1.0
        # Correlação com vizinhos
        for ch in range(n):
            r = []
            # Variância anômala
            if var_per_ch[ch] > 5 * med_var:
                bad.append(ch); reasons[ch] = f"var alta ({var_per_ch[ch]:.0f})"; continue
            if var_per_ch[ch] < 0.05 * med_var:
                bad.append(ch); reasons[ch] = f"var baixa ({var_per_ch[ch]:.1f})"; continue
            # Correlação com até 4 vizinhos
            for j in range(max(0, ch-2), min(n, ch+3)):
                if j == ch: continue
                s_ch = data[ch] - np.mean(data[ch])
                s_j  = data[j]  - np.mean(data[j])
                denom = np.std(data[ch]) * np.std(data[j])
                if denom > 0:
                    r.append(abs(float(np.mean(s_ch * s_j) / denom)))
            if r and float(np.mean(r)) < 0.2:
                bad.append(ch); reasons[ch] = f"corr={float(np.mean(r)):.2f}"
        # Resultado
        if not bad:
            self.bad_detect_status.setText(tr("Nenhum canal ruim detectado."))
            self.bad_detect_status.setStyleSheet(
                f"color: {SIGNAL_TYPE_COLORS['EEG']}; font-weight: bold;")
            self._log("Detecção de canais ruins: OK (nenhum canal flagged)")
            return
        # Marca como inativos
        msg = ", ".join(f"CH{c+1} ({reasons[c]})" for c in bad)
        confirm = QtWidgets.QMessageBox.question(
            self, tr("Canais ruins detectados"),
            tr("<b>{0} canais marcados como ruins:</b><br>{1}<br><br>Deseja "
               "desabilitá-los automaticamente?").format(len(bad), msg),
            QtWidgets.QMessageBox.StandardButton.Yes |
            QtWidgets.QMessageBox.StandardButton.No)
        if confirm == QtWidgets.QMessageBox.StandardButton.Yes:
            for ch in bad:
                if hasattr(self, "channel_checks") and ch < len(self.channel_checks):
                    self.channel_checks[ch].setChecked(False)
            self.bad_detect_status.setText(
                tr("{0} canais desabilitados: {1}").format(len(bad), [c+1 for c in bad]))
            self.bad_detect_status.setStyleSheet(
                f"color: {COLORS['warning']}; font-weight: bold;")
            self._audit_event("bad_channels_detected", channels=[c+1 for c in bad])
            self._log(f"Canais ruins desabilitados: {[c+1 for c in bad]}")

    def _on_reref_changed(self, *_):
        """Aplica o esquema de re-referenciação ao FilterChain."""
        if not hasattr(self, "reref_combo"): return
        mode = self.reref_combo.currentData()
        # Parse canais 1-based -> 0-based
        ref_chs = []
        try:
            raw = self.reref_channels_edit.text().strip()
            if raw:
                for tok in raw.replace(";", ",").split(","):
                    tok = tok.strip()
                    if tok.isdigit():
                        v = int(tok) - 1
                        if 0 <= v < MAX_CHANNELS:
                            ref_chs.append(v)
        except Exception:
            ref_chs = []
        # Os tipos por canal vão junto: sem eles o FilterChain cai no modo legado
        # e volta a somar ECG/EMG na média comum. Reenviados a cada troca porque o
        # usuário pode ter reclassificado canais em 'Filtros e Canais'.
        sig_types = list(getattr(self.config, "channel_signal_types", []) or [])
        try:
            self.filters.set_reref(mode, ref_chs, sig_types)
            n_eeg = sum(1 for s in sig_types if s == "EEG")
            self._log(f"Re-referenciação: {mode} (canais ref: {ref_chs or 'auto'}; "
                      f"{n_eeg} canais EEG na média)")
            self._audit_event("reref_change", mode=mode, ref_channels=ref_chs)
        except Exception as exc:
            self._log(f"Erro ao aplicar re-referenciação: {exc}", error=True)

    def _on_filter_change(self, *_):
        """Copia o estado dos controles de notch e passa-faixa para o FilterChain
        e manda reconstruir os coeficientes.

        Os atributos do FilterChain são atribuídos antes do try: se rebuild()
        falhar, o objeto já ficou com os novos parâmetros e o erro só aparece
        no log.
        """
        # Qualquer mudança que não veio do automático do Simples é do
        # operador: a partir dela o filtro deixa de ser "ligado sozinho".
        if not getattr(self, "_aplicando_filtro_auto", False):
            self._filtros_auto = False
        self.filters.notch_enabled    = self.notch_enable.isChecked()
        self.filters.notch_freq       = float(self.notch_freq.currentText())
        self.filters.bandpass_enabled = self.bp_enable.isChecked()
        self.filters.bp_low           = float(self.bp_low.value())
        self.filters.bp_high          = float(self.bp_high.value())
        try:
            self.filters.rebuild()
            self._log(
                f"Filtros: notch={'ON' if self.filters.notch_enabled else 'OFF'} "
                f"@ {self.filters.notch_freq:.0f}Hz | "
                f"bandpass={'ON' if self.filters.bandpass_enabled else 'OFF'} "
                f"{self.filters.bp_low:.1f}-{self.filters.bp_high:.1f}Hz")
            self._audit_event("filter_change",
                              notch=self.filters.notch_enabled,
                              notch_freq=self.filters.notch_freq,
                              bp=self.filters.bandpass_enabled,
                              bp_low=self.filters.bp_low,
                              bp_high=self.filters.bp_high)
        except Exception as exc:
            self._log(f"ERRO no filtro: {exc}", error=True)

    def _on_channel_toggle(self, ch, active):
        """Marca um canal como ativo/inativo e reaplica a visibilidade nos
        gráficos."""
        self.channel_active[ch] = active
        self._apply_channel_visibility()

    def _toggle_connection(self):
        """Botão único de conectar/desconectar: escolhe qual das duas ações
        executar pelo estado da thread serial."""
        if self.serial_thread and self.serial_thread.isRunning():
            gravava = bool(self.is_recording)
            self._disconnect()
            if gravava:
                # Quem clica ■ Desconectar em vez de ■ Parar também vê o diálogo;
                # singleShot(0): thread já parada e slot devolvido ao loop.
                QtCore.QTimer.singleShot(0, self._dialogo_sessao_gravada)
        else:
            self._connect()

    def _connect(self):
        """Monta e inicia a SerialReaderThread no modo escolhido (hardware,
        simulação ou playback), zerando os buffers antes.

        Além dos buffers de EEG, acelerômetro e espectrograma, reseta o estado
        dos filtros e as métricas de temporização (jitter, drops) — sem isso os
        números da sessão anterior contaminariam a nova. num_channels é passado
        explicitamente porque a thread precisa saber se opera em 8/16 (Cyton)
        ou 24 a 64 (placa customizada). Em simulação/playback, se o usuário
        ainda estiver na aba Configurar, a view pula direto para Tempo Real.
        """
        mode_idx = self.mode_combo.currentIndex()
        mode = ["hardware", "simulation", "playback"][mode_idx]
        # No Simples o Modo e o arquivo de playback estão ocultos: playback
        # sem arquivo só pode ser engano, e o que resta é o aparelho.
        if (mode == "playback" and self._nivel_simples()
                and not self.playback_path_edit.text().strip()):
            self.mode_combo.setCurrentIndex(0)
            mode = "hardware"
        # Um clique novo em Conectar apaga o erro anterior da dica
        self._erro_conexao_txt = None
        self._conexao_sem_dados = False
        # Conectar (ou treinar) começa um exame novo: a gravação aberta antes
        # no Analisar deixa de mandar no selo ("Gravação aberta: …") e o
        # relatório dela deixa de ser oferecido na dica (G05/G03)
        self._gravacao_aberta_de = None
        self._pdf_gerado = None
        self._vendo_gravacao = False
        self._dica_aviso = None          # o aviso anterior ("Figura salva") já era
        # só a gravação que JÁ estava aberta deixa de mandar no passo; uma
        # carregada depois de conectar conta de novo (é a mesma referência)
        self._offline_info_antiga = getattr(self, "_offline_session_info", None)
        if hasattr(self, "volunteer_label") and hasattr(self, "volunteers"):
            try:
                self._volunteer_update_indicator()
            except Exception:
                pass
        # _filtros_auto NÃO é zerado aqui: na reconexão o filtro ligado pelo
        # programa continua ligado; só o operador mexendo (_on_filter_change) zera.
        port, playback_path = None, None
        if mode == "hardware":
            port = self.port_combo.currentData()
            if not port:
                self._log("ERRO: nenhuma porta COM válida selecionada", error=True)
                self._erro_conexao(tr("Nenhuma porta foi encontrada. Ligue o "
                                      "equipamento no USB e clique em Atualizar."))
                return
        elif mode == "playback":
            playback_path = self.playback_path_edit.text().strip()
            if not playback_path:
                self._log("ERRO: selecione um arquivo CSV de playback", error=True)
                self._erro_conexao(tr("Selecione um arquivo CSV de playback."))
                return
            port = "PLAYBACK"
        else:
            port = "SIMULACAO"
        try:
            baud = int(self.baud_combo.currentText().strip())
        except ValueError:
            self._log("ERRO: baud rate inválido", error=True)
            self._erro_conexao(tr("Baud rate inválido. Escolha um valor numérico (ex.: 115200)."))
            return

        self.buffer.fill(0.0); self.buffer_pos = 0; self.samples_total = 0
        # Os contadores de piscada/sacada andam pelo indice da amostra: sem
        # zerar aqui eles somariam a sessao anterior.
        if hasattr(self, "eog_plot"):
            try: self._eog_reset()
            except Exception: pass
        # samples_total volta a zero aqui; a guarda de trial sobreposto do BCI
        # precisa esquecer a marca antiga, senao barraria o primeiro trial.
        self._bci_last_sample = None
        self.accel_buffer.fill(0.0); self.accel_pos = 0
        self.spec_buffer.fill(-80.0); self.spec_pos = 0
        # O modo (hardware/simulação/playback) só é conhecido aqui, e
        # _set_num_channels não cobre quem conecta já com 16 canais escolhidos:
        # ele sai cedo quando a contagem não muda, e a cadeia ficaria a 250 Hz.
        self._update_session_sample_rate(mode)
        self.filters.reset_state()
        self._clear_marker_lines()
        # Reset timing audit
        self._last_sample_t = None
        self._dt_window.clear()
        self._dt_total = 0
        self._dt_mean = self._dt_jitter = 0.0
        self._dropped_count = 0
        self._atraso_count = 0
        self._taxa_ref = None
        self._atraso_tela_s = 0.0
        self._perda_ref = (0, 0, 0)

        # Passa explicitamente num_channels: a thread precisa saber se devemos
        # operar em 8/16 (Cyton) ou 24/32/.../64 (placa customizada).
        self.serial_thread = SerialReaderThread(
            port=port, baud_rate=baud, mode=mode, playback_path=playback_path,
            daisy=self.daisy_enabled, num_channels=self.num_channels,
            signal_types=list(self.config.channel_signal_types),
            channel_mapping=list(self.config.channel_mapping))
        self.serial_thread.data_received.connect(self._on_sample)
        self.serial_thread.bloco_recebido.connect(self._on_bloco)
        self.serial_thread.error.connect(self._on_thread_error)
        self.serial_thread.connection_state.connect(self._on_connection_state)
        self.serial_thread.progress.connect(self._on_playback_progress)
        self.serial_thread.expansion_detected.connect(self._on_expansion_detected)
        self.serial_thread.start()
        self.connect_btn.setText(tr("■  Desconectar"))
        self._log(f"Conectando a {port} @ {baud} (modo={mode}, daisy={self.daisy_enabled})")
        self._audit_event("connect", port=str(port), baud=baud, mode=mode,
                          expansion=self.daisy_enabled, playback=playback_path)
        # Simulação / Playback não têm nada para configurar: se o usuário está
        # na aba Conexão, leva-o direto para Tempo Real para ver o sinal.
        if mode in ("simulation", "playback") and hasattr(self, "_main_tabs"):
            if self._main_tabs.currentIndex() == 0:   # ainda em "Configurar"
                self._goto_realtime_view()

    def _on_expansion_detected(self, n):
        """Disparado pela thread quando detecta canais (ex: CSV com 16ch)."""
        if n != self.num_channels:
            self._log(f"Expansão detectada automaticamente: {n} canais")
            self._set_num_channels(n)

    def _disconnect(self):
        """Encerra a thread de aquisição e, se houver gravação em curso, a
        finaliza antes.

        O evento de auditoria de desconexão carrega o fechamento das métricas
        da sessão: Δt médio, jitter, amostras perdidas e total de amostras.
        """
        if self.is_recording:
            self._stop_recording()
        if getattr(self, "_vigia_dados", None) is not None:
            self._vigia_dados.stop()
        if self.serial_thread:
            self.serial_thread.stop()
            self.serial_thread = None
        self.connect_btn.setText(tr("▶  Conectar"))
        self._log("Desconectado")
        self._audit_event("disconnect",
                          dt_mean_ms=round(self._dt_mean, 3),
                          dt_jitter_ms=round(self._dt_jitter, 3),
                          dropped=self._dropped_count,
                          samples_total=self.samples_total)

    def _on_connection_state(self, connected):
        """Reflete na interface (LED, rótulo de estado, botão de gravar, título da
        janela) o sinal de conexão emitido pela thread.

        É aqui que session_start recebe time.time(): esse instante é o t=0 de
        todos os timestamps do data.csv e dos marcadores.
        """
        if connected:
            self.session_start = time.time()
            self._pinta_estado_conexao(True)
            self.record_btn.setEnabled(True)
            self._log("Conexão estabelecida — recebendo dados")
            self._ao_conectar()
        else:
            self._pinta_estado_conexao(False)
            self.record_btn.setEnabled(False)
            self.connect_btn.setText(tr("▶  Conectar"))
            if getattr(self, "_vigia_dados", None) is not None:
                self._vigia_dados.stop()
            self._semaforo_neutro()
            self._telemetria_neutra()
        if hasattr(self, "bio_sim_banner"):
            _modo = getattr(self.serial_thread, "mode", "") if connected else ""
            self.bio_sim_banner.setVisible(_modo == "simulation")
        self._esmaece_tracados(not connected)
        # O semáforo só volta a avaliar com conexão viva (ver
        # _update_channel_quality); _connect já zera amostras e perdas.
        self._semaforo_parado = not connected
        # Atualiza status bar e título da janela
        self._update_status_state()
        self._update_window_title()
        # a prévia do nome da próxima gravação sabe se é treino (G25/G04)
        self._refresh_session_preview()

    def _esmaece_tracados(self, esmaecer):
        """Depois de desconectar, o último traçado ficava na tela com a cor
        cheia ao lado de "DESCONECTADO" e parecia sinal chegando. Fica a 30%
        (continua legível para quem quer olhar) até a próxima conexão."""
        alfa = 0.3 if esmaecer else 1.0
        for nome in ("montage_curves", "channel_curves", "accel_curves", "emg_curves"):
            for c in getattr(self, nome, None) or []:
                try:
                    c.setOpacity(alfa)
                except (RuntimeError, AttributeError):
                    pass
        # Topografia, Foco e envoltória de EMG param junto (_update_topology);
        # a última imagem fica, esmaecida, para não parecer sinal chegando.
        # 0,4 e não 0,3: um mapa de cor a 30% sobre o fundo fica ilegível.
        for nome in ("head_plot_tabs", "_topo_lado"):
            wdg = getattr(self, nome, None)
            if wdg is None:
                continue
            try:
                if esmaecer:
                    ef = QtWidgets.QGraphicsOpacityEffect(wdg)
                    ef.setOpacity(0.4)
                    wdg.setGraphicsEffect(ef)
                else:
                    wdg.setGraphicsEffect(None)
            except RuntimeError:
                pass

    def _semaforo_neutro(self):
        """Semáforo do cabeçalho de volta ao estado de antes de conectar.
        "perdendo amostras N%" (ou "Sinal OK") de uma conexão encerrada ficava
        na tela ao lado de DESCONECTADO, porque o buffer e os contadores da
        sessão continuam na memória depois de desconectar."""
        lbl = getattr(self, "quality_summary", None)
        if lbl is None:
            return
        lbl.setText(tr("Sinal: —"))
        self._pinta_resumo_sinal(
            "neutro", "color: #888; font-size: 9pt; font-weight: bold; padding: 0 8px;")
        lbl.setToolTip(
            tr("Prontidão geral do sinal (resumo de todos os canais ativos)."))
        try:
            self._update_header_responsive()
        except Exception:
            pass

    def _telemetria_neutra(self):
        """Amostras, g, LEDs de canal e Δt de volta ao estado de antes de
        conectar, como o semáforo (_semaforo_neutro). Os números e os LEDs
        verdes da conexão encerrada ficavam ao lado de DESCONECTADO e
        pareciam sinal chegando."""
        if hasattr(self, "samples_label"):
            self.samples_label.setText(tr("Amostras: 0"))
        if hasattr(self, "accel_label"):
            self.accel_label.setText("g: -.--  -.--  -.--")
        for i, led in enumerate(getattr(self, "quality_leds", None) or []):
            led.setText("●")
            led.setStyleSheet("color: #444; font-size: 10pt;")
            led.setToolTip(tr("CH{0}: aguardando dados").format(i + 1))
        # reservas de Amostras e Δt de volta ao tamanho inicial (cresceram
        # com a conexão encerrada: dígitos, drops)
        self._reserva_telemetria("samples_label")
        self._reserva_telemetria("timing_label")
        lbl = getattr(self, "timing_label", None)
        if lbl is not None:
            lbl.setText("Δt: -.-- ms  ±-.-- ms")
            lbl.setStyleSheet(
                f"color: {COLORS['text_dim']}; padding: 2px 5px; font-family: {FONT_DATA_STACK};")
            lbl.setToolTip(
                tr("Δt = média do intervalo entre amostras (esperado: {0:.1f} ms a {1} "
                   "Hz)\nJitter = desvio padrão de Δt (menor = melhor)\nDropped = pacotes "
                   "perdidos detectados").format(1000.0/SAMPLE_RATE, SAMPLE_RATE))
        try:
            self._update_header_responsive()
        except Exception:
            pass

    def _on_thread_error(self, msg):
        # Erro técnico para o log, mensagem amigável para o usuário
        """Recebe erros da thread de aquisição, manda o texto técnico ao log e
        mostra ao usuário uma explicação traduzida quando existe.

        O diálogo modal só aparece se _friendly_error_message reconhecer o
        padrão do erro; caso contrário a falha fica apenas no log e na barra de
        status.
        """
        self._log(f"ERRO: {msg}", error=True)
        self._update_status_state(tr("Erro na conexão — veja o log para detalhes"))
        # Mensagens amigáveis para erros comuns
        friendly = self._friendly_error_message(msg)
        # A dica fica vermelha mesmo quando não há tradução amigável. Só a 1ª
        # linha: o texto amigável tem várias e inflava a barra; o texto
        # inteiro já vai na caixa abaixo (e o técnico, no log).
        curto = (friendly or msg or "").strip().split("\n")[0]
        if not friendly and len(curto) > 90:
            curto = curto[:89] + "…"
        self._erro_conexao_txt = curto
        self._sync_action_bar()
        if friendly:
            QtWidgets.QMessageBox.warning(self, tr("Problema na conexão"), friendly)

    def _erro_conexao(self, texto):
        """Erro de conexão inline na dica (vermelho + "Procurar de novo") e, se
        o operador não está na aba Conexão para ver o log, também em caixa."""
        self._erro_conexao_txt = texto
        self._sync_action_bar()
        if hasattr(self, "_main_tabs") and self._main_tabs.currentIndex() != 0:
            QtWidgets.QMessageBox.warning(self, tr("Problema na conexão"), texto)

    def _ao_conectar(self):
        """Pós-conexão: zera a dica, leva ao sinal, escala automática, filtro
        do exame no Simples e vigia de 5 s para porta aberta sem dados."""
        self._erro_conexao_txt = None
        self._ultima_sessao_parada = None
        self._conexao_sem_dados = False
        thread = self.serial_thread
        modo = getattr(thread, "mode", "") if thread is not None else ""
        # No Simples, hardware também vai ao sinal quando o operador ainda
        # está em Configurar (simulação/playback já vão em _connect). No
        # Avançado não: o pesquisador conecta para seguir ajustando
        # Filtros/Hardware/Calibração com o aparelho ligado.
        if (self._nivel_simples() and modo == "hardware"
                and hasattr(self, "_main_tabs")
                and self._main_tabs.currentIndex() == 0):
            self._goto_realtime_view()
        # Na simulacao a escala se ajusta tambem no Avancado: o EMG simulado
        # (120-180 uV) numa escala de 100 uV/canal enchia a tela de traco.
        if self._nivel_simples() or modo == "simulation":
            QtCore.QTimer.singleShot(2000, self._rt_autoscale)
        if self._nivel_simples():
            # O leigo precisa ver um traçado limpo: liga o preset do tipo de
            # sinal só quando notch e passa-faixa estão ambos desligados.
            # Fica registrado no log e no summary.json (filters_auto).
            if (SIMPLES_LIGA_FILTRO and hasattr(self, "notch_enable")
                    and hasattr(self, "bp_enable")
                    and not self.notch_enable.isChecked()
                    and not self.bp_enable.isChecked()):
                try:
                    # a flag impede _on_filter_change de tomar isto por
                    # ajuste manual do operador
                    self._aplicando_filtro_auto = True
                    # Tipos misturados (Multimodal): a cadeia de filtros e'
                    # global e o data.csv grava o sinal filtrado. O 0,5-70 Hz
                    # do EEG cortava de vez a banda alta do EMG e do ECG; so' a
                    # rede eletrica e' segura para todos.
                    misto = len(set(self._tipos_em_uso())) > 1
                    try:
                        if misto:
                            self.notch_enable.setChecked(True)
                            self._on_filter_change()
                        else:
                            self._apply_dominant_signal_filter()
                    finally:
                        self._aplicando_filtro_auto = False
                    self._filtros_auto = bool(self.notch_enable.isChecked()
                                              or self.bp_enable.isChecked())
                    if self._filtros_auto and misto:
                        self._log("Modo simples: tipos de sinal misturados — só o "
                                  "filtro da rede elétrica foi ligado ao conectar.")
                        self._dica_temporaria(
                            tr("Filtro da rede elétrica ligado. Com tipos de sinal "
                               "misturados, o passa-faixa fica a seu critério."),
                            anexa=True)
                    elif self._filtros_auto:
                        self._log("Modo simples: filtro do exame ligado ao conectar "
                                  "(rede elétrica + passa-faixa).")
                        # "passa-faixa" não diz nada a quem aplica o exame (G37)
                        # anexa ao "Passo 2 de 3": o aviso escondia o passo por
                        # 5 s e quem gravava antes disso nunca o via (G05)
                        self._dica_temporaria(
                            tr("Filtro do exame ligado: tira o ruído da tomada.")
                            if self._nivel_simples() else
                            tr("Filtro do exame ligado (rede elétrica + passa-faixa)."),
                            anexa=True)
                except Exception as exc:
                    self._log(f"Falha ao ligar o filtro do exame: {exc}", error=True)
        # Timer de instância: reconectar reinicia a contagem e desconectar a
        # cancela. Um singleShot solto disparava durante a conexão SEGUINTE.
        if getattr(self, "_vigia_dados", None) is None:
            self._vigia_dados = QtCore.QTimer(self)
            self._vigia_dados.setSingleShot(True)
            self._vigia_dados.timeout.connect(self._checar_chegada_dados)
        self._vigia_dados.start(5000)
        self._sync_action_bar()

    def _checar_chegada_dados(self):
        """Vigia de 5 s: uma COM aberta e muda (ex.: Bluetooth virtual) dá
        CONECTADO sem nenhum pacote — connection_state(True) sai antes de
        qualquer dado. É o único aviso possível para o operador."""
        if not (self.serial_thread and self.serial_thread.isRunning()):
            return
        if self.samples_total == 0:
            self._conexao_sem_dados = True
            self._log("Conectado há 5 s sem receber nenhuma amostra — confira "
                      "a placa e a porta.", error=True)
            self._sync_action_bar()

    @staticmethod
    def _friendly_error_message(raw_msg):
        """Converte mensagens técnicas em explicações amigáveis."""
        low = raw_msg.lower()
        if "could not open port" in low or "permissionerror" in low:
            return (tr("Não foi possível abrir a porta COM selecionada.\n\n"
                    "Verifique se:\n"
                    " • O dispositivo está conectado e ligado\n"
                    " • Nenhum outro programa (OpenBCI GUI, Arduino IDE, etc.) "
                    "está usando a porta\n"
                    " • A porta selecionada é a correta"))
        if "filenotfounderror" in low or "no such file" in low:
            return (tr("Arquivo não encontrado.\n\nVerifique se o caminho está "
                    "correto e se o arquivo ainda existe."))
        if "no module" in low:
            return (tr("Uma biblioteca necessária não está instalada.\n\n"
                    "Detalhe técnico para suporte: ") + raw_msg)
        if "csv de playback" in low:
            return (tr("Arquivo CSV de playback não foi encontrado.\n"
                    "Verifique se selecionou um arquivo válido."))
        return None

    def _notify_error(self, code, detail="", exc=None, blocking=None):
        """Sinaliza um erro catalogado (Erro E0XX) ao usuário: SEMPRE loga e
        reflete na barra de status; abre diálogo modal se for bloqueante."""
        title, _msg, blk = error_info(code)
        if blocking is None:
            blocking = blk
        try:
            if hasattr(self, "status_state_lbl"):
                self.status_state_lbl.setText(tr("⚠ Erro {0}: {1}").format(code, title))
            self.statusBar().showMessage(tr("Erro {0}: {1}").format(code, title), 8000)
        except Exception:
            pass
        if blocking:
            notify_error(code, detail, parent=self, exc=exc, blocking=True)
        else:
            logging.getLogger("eeg").warning(
                "[%s] %s%s", code, title, (" | " + str(detail)) if detail else "")

    def _on_playback_progress(self, frac):
        """Move a barra de progresso do playback conforme a fração do CSV já
        reproduzida.

        A barra trabalha em milésimos (0 a 1000), por isso a fração recebida é
        multiplicada por 1000.
        """
        self.playback_progress.setValue(int(frac * 1000))

    # ==================================================================
    # Sample handler
    # ==================================================================
    def _taxa_efetiva_recente(self):
        # amostras por segundo de ORIGEM desde a conexao; None antes de 3 s
        ref = getattr(self, "_taxa_ref", None)
        ult = getattr(self, "_last_sample_t", None)
        if not ref or ult is None or (ult - ref[0]) < 3.0:
            return None
        return (int(self.samples_total) - ref[1]) / (ult - ref[0])

    def _on_bloco(self, amostras, accels, tempos):
        # bloco da simulacao atrasada: mesma porta de entrada, amostra a amostra
        for i in range(len(tempos)):
            self._on_sample(amostras[i], accels[i], float(tempos[i]))

    def _on_sample(self, sample, accel, t_mono=None):
        # --- Sample timing audit (jitter / drops) ---
        """Ponto de entrada de cada amostra vinda da thread de aquisição: filtra,
        grava nos buffers circulares e repassa para CSV, UDP e LSL.

        Chega por sinal Qt vindo de outra thread, ou seja, executa em fila no
        thread da GUI a SAMPLE_RATE amostras por segundo — trabalho pesado aqui
        trava a interface. Se apply_sample() falhar, a amostra CRUA segue para
        o arquivo mesmo assim: por isso a falha incrementa _filter_fail_count,
        liga _filter_degraded e é logada com throttle (primeira ocorrência e a
        cada 250). O marcador pendente é consumido e zerado nesta função, então
        cai na linha do CSV da amostra atual.
        """
        # Mede o intervalo pelo carimbo da ORIGEM, nao pelo instante em que a
        # GUI conseguiu processar: senao o "jitter" media a lentidao do desenho.
        now = t_mono if t_mono is not None else time.perf_counter()
        if self._last_sample_t is not None:
            dt_ms = (now - self._last_sample_t) * 1000.0
            self._dt_window.append(dt_ms)
            self._dt_total += 1
            expected_ms = 1000.0 / SAMPLE_RATE
            # Um buraco entre chegadas NAO e' amostra perdida: o marcapasso
            # mira prazo absoluto e dispara em rajada depois de um atraso do
            # SO. Medido, 60 s de simulacao com o arquivo integro: este contador
            # marcava 34% de "perda" e o data.csv tinha 248,4 Hz e o pico do
            # espectro no lugar certo. Aqui so' medimos o ATRASO DA TELA; a
            # perda de verdade vem da thread (SerialReaderThread.perdidas).
            if dt_ms > 2.0 * expected_ms:
                self._atraso_count += int(round(dt_ms / expected_ms)) - 1
            # média e jitter (sd) da janela
            if len(self._dt_window) >= 5:
                arr = np.fromiter(self._dt_window, dtype=np.float64,
                                  count=len(self._dt_window))
                self._dt_mean   = float(np.mean(arr))
                self._dt_jitter = float(np.std(arr))
        self._last_sample_t = now
        # taxa efetiva desde a conexao e atraso da fila ate' a tela
        if getattr(self, "_taxa_ref", None) is None:
            self._taxa_ref = (now, int(self.samples_total))
        self._atraso_tela_s = time.perf_counter() - now
        _th = self.serial_thread
        if _th is not None:
            self._dropped_count = int(getattr(_th, "perdidas", 0) or 0)

        try:
            sample = self.filters.apply_sample(sample)
        except Exception as exc:
            # NAO engolir em silencio: do contrario gravariamos a amostra CRUA
            # rotulada como filtrada. Conta, marca a sessao como degradada e
            # loga com throttle (1a falha + a cada 250).
            self._filter_fail_count = getattr(self, "_filter_fail_count", 0) + 1
            self._filter_degraded = True
            if self._filter_fail_count == 1 or self._filter_fail_count % 250 == 0:
                logging.getLogger("eeg").warning(
                    "Falha na filtragem em tempo real (#%d): %s — amostra gravada CRUA",
                    self._filter_fail_count, exc)
        self.last_accel = accel
        n = len(sample)
        # Buffer EEG (preenche só os canais ativos)
        self.buffer[:n, self.buffer_pos] = sample
        if n < MAX_CHANNELS:
            self.buffer[n:, self.buffer_pos] = 0.0
        self.buffer_pos = (self.buffer_pos + 1) % BUFFER_SIZE
        self.samples_total += 1
        if self._conexao_sem_dados:
            self._conexao_sem_dados = False    # chegou dado: apaga o aviso
        # Acelerômetro
        self.accel_buffer[:, self.accel_pos] = accel
        self.accel_pos = (self.accel_pos + 1) % ACCEL_BUFFER_SIZE
        # CSV
        if self.is_recording and self.csv_writer is not None:
            try:
                # t=0 e o inicio da GRAVACAO (nao o da conexao) e vem do
                # relogio monotonico — e o que faz duration_s do CSV, do
                # summary.json e da tela finalmente concordarem.
                if self._rec_first_mono is None:
                    self._rec_first_mono = now       # 1a amostra => t = 0
                ts = now - self._rec_first_mono
                self._rec_last_ts = ts
                marker = self.pending_marker or ""
                self.pending_marker = None
                # 6 casas = microssegundo. Com 4 casas (0,1 ms) duas
                # amostras muito proximas arredondavam para o MESMO texto e
                # reapareciam como timestamp duplicado no arquivo — o defeito
                # que cegava a medicao de taxa.
                row = [f"{ts:.6f}"] + [f"{v:.4f}" for v in sample]
                row += [f"{accel[0]:.4f}", f"{accel[1]:.4f}", f"{accel[2]:.4f}", marker]
                self.csv_writer.writerow(row)
            except Exception as exc:
                self._log(f"Erro na gravação CSV: {exc}", error=True)
        if self.udp.enabled:
            t = time.time() - (self.session_start or time.time())
            self.udp.send_sample(t, sample)
        # LSL — só os canais ativos
        if self.lsl.enabled:
            self.lsl.send_sample(sample[:self.num_channels])

    def _ordered_buffer(self):
        """Desenrola o buffer circular de EEG numa matriz em ordem cronológica,
        base de todos os gráficos e análises.

        Enquanto samples_total < BUFFER_SIZE devolve apenas a fatia preenchida;
        depois disso concatena as duas metades, o que copia o buffer inteiro a
        cada chamada.
        """
        if self.samples_total == 0:
            return np.zeros((MAX_CHANNELS, 0))
        if self.samples_total < BUFFER_SIZE:
            return self.buffer[:, : self.samples_total]
        return np.concatenate(
            (self.buffer[:, self.buffer_pos:], self.buffer[:, : self.buffer_pos]),
            axis=1)

    def _ordered_accel(self):
        """Faz a mesma desenrolada do buffer circular para os três eixos do
        acelerômetro.

        Usa ACCEL_BUFFER_SIZE, que é independente do BUFFER_SIZE do EEG — as
        duas séries não têm necessariamente o mesmo comprimento.
        """
        if self.samples_total == 0:
            return np.zeros((3, 0))
        n = min(self.samples_total, ACCEL_BUFFER_SIZE)
        if self.samples_total < ACCEL_BUFFER_SIZE:
            return self.accel_buffer[:, :n]
        return np.concatenate(
            (self.accel_buffer[:, self.accel_pos:], self.accel_buffer[:, : self.accel_pos]),
            axis=1)

    # ==================================================================
    # Update timers
    # ==================================================================
    def _update_plots(self):
        """Redesenha os gráficos de tempo real a cada 50 ms e atualiza a
        telemetria do cabeçalho (amostras, g, Δt/jitter/drops).

        Todos os blocos rodam dentro de try/except porque no PySide6 uma
        exceção não tratada num slot de QTimer pode abortar o app; cada origem
        de erro é logada uma única vez via flags _err_logged_*. O Histórico é
        sempre alimentado, mas as curvas individuais só recebem dados quando a
        view de canais está selecionada. A cor do indicador de timing é
        vermelha se houver drops, amarela se o jitter passar de 20% do Δt
        esperado, verde caso contrário.
        """
        data = self._ordered_buffer()
        n_samples = data.shape[1]
        if n_samples == 0: return
        t_axis = np.arange(n_samples) / SAMPLE_RATE
        # O controle "Janela:" so valia no Empilhado: mexer nele nao mudava nada
        # na vista Individual, que mostrava o buffer inteiro.
        win_s = (self.rt_window_spin.value()
                 if hasattr(self, "rt_window_spin") else BUFFER_SECONDS)
        win_n = min(n_samples, max(2, int(win_s * SAMPLE_RATE)))
        t_ind = np.arange(win_n) / SAMPLE_RATE
        # Guardado para o marcador nascer ja na borda direita da janela.
        self._rt_win_n = win_n

        view_idx = self.rt_view_stack.currentIndex() if hasattr(self, "rt_view_stack") else 1

        # Histórico sempre atualiza (aba Histórico) + Individual se ativo.
        # Protegido: uma falha num canal não pode derrubar o timer de 50ms
        # (no PySide6 uma exceção não tratada num slot de timer pode abortar o app).
        try:
            for ch in range(MAX_CHANNELS):
                active = (ch < self.num_channels and self.channel_active[ch])
                if not active:
                    self.channel_curves[ch].setData([], [])
                    self.history_curves[ch].setData([], [])
                    continue
                self.history_curves[ch].setData(t_axis, data[ch])
                if view_idx == 1:
                    self.channel_curves[ch].setData(t_ind, data[ch, -win_n:])

            if view_idx == 1:
                self._reposiciona_marcadores_canais(win_n)
            # Modo Empilhado (montagem clínica) — todos os canais num único plot
            if view_idx == 0 and hasattr(self, "montage_plot"):
                self._update_montage(data)
        except Exception as exc:
            if not getattr(self, "_err_logged_core_plot", False):
                self._log(f"Erro ao atualizar gráficos: {exc}", error=True)
                self._err_logged_core_plot = True

        # Atualizações das modalidades Bio + saídas BCI — sempre protegidas
        # por try/except para que falhas nelas não derrubem o timer principal.
        def _safe(fn_name):
            """Invoca por nome um dos atualizadores de modalidade (EMG, ECG, EoG,
            foco, joystick, acelerômetro) isolando exceções.

            Loga o erro só na primeira ocorrência de cada função, com uma flag
            _err_logged_<nome>, para não inundar o log a 20 Hz. Se o método não
            existir, sai em silêncio.
            """
            fn = getattr(self, fn_name, None)
            if fn is None: return
            try:
                fn()
            except Exception as exc:
                flag = f"_err_logged_{fn_name}"
                if not getattr(self, flag, False):
                    self._log(f"Erro {fn_name}: {exc}", error=True)
                    setattr(self, flag, True)

        # EMG view (aba EMG / Músculos)
        if hasattr(self, "emg_rows"):
            _safe("_update_emg_view")
        # ECG view (aba ECG / Coração)
        if hasattr(self, "ecg_raw_plot"):
            _safe("_update_ecg_view")
        # EoG view (aba EoG / Olhos)
        if hasattr(self, "eog_plot"):
            _safe("_update_eog_view")
        # Focus / SSVEP (aba em Analisar)
        if hasattr(self, "focus_fft_plot"):
            _safe("_update_focus_view")
        # EMG Joystick (aba em Analisar)
        if hasattr(self, "_joy_axes"):
            _safe("_update_emg_joystick_view")
        # Acelerômetro · Movimento (sub-aba em Bio)
        if hasattr(self, "accel_history_plot"):
            _safe("_update_accelerometer_view")

        accel_data = self._ordered_accel()
        if accel_data.shape[1] > 0:
            t_a = np.arange(accel_data.shape[1]) / SAMPLE_RATE
            for i in range(3):
                self.accel_curves[i].setData(t_a, accel_data[i])
        # Desconectado, a telemetria fica neutra (_telemetria_neutra): o buffer
        # antigo continua na memória e reescrevia a cada quadro os números da
        # conexão encerrada.
        parado = bool(getattr(self, "_semaforo_parado", False))
        if not parado:
            _txt_am = f"Amostras: {self.samples_total:,}".replace(",", ".")
            self.samples_label.setText(_txt_am)
            self._reserva_telemetria("samples_label", re.sub(r"\d", "9", _txt_am))
            a = self.last_accel
            self.accel_label.setText(f"g: {a[0]:+.2f}  {a[1]:+.2f}  {a[2]:+.2f}")
        # Timing / jitter / drops
        if hasattr(self, "timing_label") and not parado:
            expected = 1000.0 / SAMPLE_RATE
            if self._dt_total >= 5:
                drift_pct = (self._dt_mean - expected) / expected * 100.0
                # O drift saiu do texto e foi para a dica: a reserva de
                # pior caso deste rotulo ocupava um terco do cabecalho.
                txt = f"Δt: {self._dt_mean:5.2f} ms  ±{self._dt_jitter:.2f}"
                if self._dropped_count > 0:
                    txt += f"  drops: {self._dropped_count}"
                self.timing_label.setToolTip(tr(
                    "Δt = média do intervalo entre amostras (esperado {0:.1f} ms "
                    "a {1} Hz)\nJitter = desvio padrão de Δt (menor = melhor)\n"
                    "Deriva da cadência: {2}%\nAmostras perdidas pelo aparelho: "
                    "{3}").format(expected, SAMPLE_RATE, f"{drift_pct:+.1f}",
                                  self._dropped_count))
                # cor: verde se ok, amarelo se jitter alto, vermelho se drops
                if self._dropped_count > 0:
                    col = COLORS["error"]
                elif self._dt_jitter > expected * 0.20:
                    col = COLORS["warning"]
                else:
                    col = COLORS["accent"]
                # padding IGUAL ao da construção — trocar o padding aqui
                # mudava a largura do rótulo e fazia o cabeçalho tremer
                self.timing_label.setStyleSheet(
                    f"color: {col}; padding: 2px 5px; font-family: {FONT_DATA_STACK};")
                self.timing_label.setText(txt)
                self._reserva_telemetria("timing_label", re.sub(r"\d", "9", txt))

    def _reposiciona_marcadores_canais(self, win_n):
        """Recoloca as linhas de marcador da vista Individual a cada quadro.

        A posicao vem do indice absoluto da amostra em que o marcador nasceu:
        como o traco desliza, uma posicao fixa em segundos saia do grafico. A
        linha que rolou para fora da janela e removida na hora, o que tambem
        impede o acumulo de milhares de InfiniteLine numa sessao longa.
        """
        if not hasattr(self, "channel_marker_lines"):
            return
        st = int(self.samples_total)
        plots = getattr(self, "channel_plots", [])
        for ch, ch_lines in enumerate(self.channel_marker_lines):
            if not ch_lines:
                continue
            plot = plots[ch] if ch < len(plots) else None
            for item in list(ch_lines):
                s_abs, line = item
                x = (win_n - (st - s_abs)) / float(SAMPLE_RATE)
                if x < 0:
                    if plot is not None:
                        try: plot.removeItem(line)
                        except Exception: pass
                    try: ch_lines.remove(item)
                    except ValueError: pass
                else:
                    line.setPos(x)

    def _update_montage(self, data):
        """Desenha todos os canais visíveis empilhados num único plot,
        cada um com offset vertical (estilo montagem clínica EEG)."""
        n_total = data.shape[1]
        win_s = self.rt_window_spin.value()
        win_n = min(n_total, int(win_s * SAMPLE_RATE))
        seg = data[:, -win_n:]
        t = np.arange(win_n) / SAMPLE_RATE
        scale = max(1e-6, self.rt_scale_spin.value())

        vis = [ch for ch in range(MAX_CHANNELS)
               if ch < self.num_channels and self.channel_active[ch]]
        n_vis = len(vis)
        for k, ch in enumerate(vis):
            baseline = (n_vis - 1 - k)
            # Centraliza no baseline e escala: 1 "slot" = `scale` µV
            y = (seg[ch] - float(np.mean(seg[ch]))) / scale + baseline
            self.montage_curves[ch].setData(t, y)
        # Esconde curvas de canais não visíveis
        for ch in range(MAX_CHANNELS):
            if ch not in vis:
                self.montage_curves[ch].setData([], [])
        self.montage_plot.setXRange(0, win_s, padding=0)
        # Marcadores acompanham o traco: a linha ficava parada na borda direita
        # enquanto o sinal andava para a esquerda, e doze rotulos se empilhavam
        # na mesma coordenada.
        if getattr(self, "montage_marker_lines", None):
            st = int(self.samples_total)
            for item in list(self.montage_marker_lines):
                s_abs, mline = item
                x = win_s - (st - s_abs) / float(SAMPLE_RATE)
                if x < 0:
                    try: self.montage_plot.removeItem(mline)
                    except Exception: pass
                    try: self.montage_marker_lines.remove(item)
                    except ValueError: pass
                else:
                    mline.setPos(x)
        # Atualiza ticks só se mudou o nº de canais visíveis
        if getattr(self, "_montage_last_nvis", -1) != n_vis:
            self._montage_last_nvis = n_vis
            self._refresh_montage_layout()

    def _update_analysis(self):
        """Atualiza a FFT, as barras de potência por banda e a tabela de
        estatísticas do painel de análise, a cada 500 ms.

        Exige pelo menos 1 s de sinal no buffer (SAMPLE_RATE amostras) antes de
        calcular. FFT e bandas usam só o canal escolhido no combo; a tabela
        cobre todos os canais e mostra '--' nos que estão além de num_channels.
        """
        data = self._ordered_buffer()
        if data.shape[1] < SAMPLE_RATE: return
        ch = self.analysis_channel.currentIndex()
        if ch >= self.num_channels: ch = 0
        freqs, fft_vals = SignalProcessor.compute_fft(data[ch])
        if freqs.size:
            self.fft_curve.setData(freqs, fft_vals)
        powers = SignalProcessor.compute_band_powers(data[ch])
        self.band_bars.setOpts(height=list(powers.values()))
        for c in range(MAX_CHANNELS):
            if c >= self.num_channels:
                self.stats_table.item(c, 1).setText("--")
                self.stats_table.item(c, 2).setText("--")
                self.stats_table.item(c, 3).setText("--")
                continue
            stats = SignalProcessor.compute_statistics(data[c])
            self.stats_table.item(c, 1).setText(f"{stats['mean']:+.3f}")
            self.stats_table.item(c, 2).setText(f"{stats['std']:.3f}")
            self.stats_table.item(c, 3).setText(f"{stats['rms']:.3f}")

    def _update_spectrogram(self):
        """Acrescenta uma coluna de PSD ao espectrograma rolante de cada canal e
        exibe o do canal selecionado.

        O spec_buffer é circular com SPEC_FRAMES colunas; o eixo horizontal é
        desenhado como SPEC_FRAMES × 0,25 s porque o timer dispara a cada 250
        ms — mudar o intervalo do timer desalinha a escala de tempo.

        Cada coluna analisa só os últimos SPEC_WINDOW_S segundos. Passando o
        buffer inteiro (10 s), colunas vizinhas compartilhavam 97,5% das
        amostras: um burst de 1 s medido em 40 Hz deixava rastro de 7,25 s na
        tela, num eixo que promete 0,25 s por coluna.
        """
        data = self._ordered_buffer()
        if data.shape[1] < SAMPLE_RATE: return
        # Janela curta em vez de data[ch] inteiro: medido com burst de 40 Hz de
        # 1,0 s, o buffer de 10 s espalhava o evento por 29 colunas (7,25 s);
        # com 2 s cai para 7 colunas (1,75 s), coerente com o eixo.
        win = min(int(SAMPLE_RATE * SPEC_WINDOW_S), data.shape[1])
        for ch in range(self.num_channels):
            col = SignalProcessor.compute_psd_column(data[ch, -win:])
            self.spec_buffer[ch, :, self.spec_pos] = col
        self.spec_pos = (self.spec_pos + 1) % SPEC_FRAMES
        ch = self.spec_channel.currentIndex()
        if ch >= self.num_channels: ch = 0
        view = np.concatenate(
            (self.spec_buffer[ch, :, self.spec_pos:],
             self.spec_buffer[ch, :, : self.spec_pos]),
            axis=1)
        # p2/p98 (e não min/max) para que um único artefato não achate o resto.
        # O filtro != -80.0 descarta a sentinela de "coluna ainda não gravada"
        # (spec_buffer nasce em -80): sem ele, nos primeiros 37 s a escala iria
        # de -80 dB até o sinal e o EEG real ocuparia metade da LUT.
        vals = view[np.isfinite(view) & (view != -80.0)]
        if vals.size < 16:
            vals = view[np.isfinite(view)]
        if vals.size:
            lo = float(np.percentile(vals, 2)); hi = float(np.percentile(vals, 98))
        else:
            lo, hi = 0.0, 20.0
        if hi - lo < 1.0: hi = lo + 1.0     # canal chapado: faixa nula = tela preta
        self.spec_image.setImage(view.T, autoLevels=False, levels=(lo, hi))
        if getattr(self, "spec_colorbar", None) is not None:
            self.spec_colorbar.setLevels((lo, hi))
        self.spec_image.setRect(QtCore.QRectF(0.0, 0.0,
                                              SPEC_FRAMES * 0.25, SPEC_FMAX))

    def _update_topology(self):
        """Calcula a potência da banda selecionada em todos os canais e distribui
        o resultado para o mapa topográfico, o medidor de foco e o widget de
        EMG.

        Roda a cada 500 ms e exige 1 s de sinal. Canais além de num_channels
        entram com potência 0,0 para manter o vetor com MAX_CHANNELS posições.
        O widget de EMG recebe apenas os últimos 3 s do canal dele.
        """
        # Desconectado, o buffer é o da conexão encerrada: recalcular a cada
        # 500 ms reescrevia mapa, Foco e envoltória com dado velho (e
        # sobrescrevia qualquer valor posto nas vistas). Volta ao conectar.
        if getattr(self, "_semaforo_parado", False):
            return
        data = self._ordered_buffer()
        if data.shape[1] < SAMPLE_RATE: return
        band_name = self.topo_band_combo.currentText()
        low, high = EEG_BANDS_CATALOGO[band_name]
        powers = []
        for c in range(MAX_CHANNELS):
            if c < self.num_channels:
                powers.append(SignalProcessor.compute_band_power(data[c], low, high))
            else:
                powers.append(0.0)
        self._topo_broadcast_powers(powers, band_name)
        ch = self.topo_channel_combo.currentIndex()
        if ch >= self.num_channels: ch = 0
        try:
            focus = SignalProcessor.compute_focus_index(data[ch])
            self.focus_meter.update_value(focus)
        except Exception: pass
        emg_ch = self.emg_widget.channel_combo.currentIndex()
        if emg_ch >= self.num_channels: emg_ch = 0
        n_last = min(int(SAMPLE_RATE * 3), data.shape[1])
        self.emg_widget.update_signal(data[emg_ch, -n_last:])

    # ==================================================================
    # Qualidade de sinal por canal — LEDs no header
    # ==================================================================
    def _update_channel_quality(self):
        """Classifica cada canal como OK / NOISY / BAD com base em:
        - amplitude saturada (clipping)
        - variância fora da faixa de EEG (~0.5–200 µV²)
        - razão de potência em ~50/60 Hz (rede elétrica) vs total
        """
        if getattr(self, "_semaforo_parado", False):
            # Desconectado: LEDs e semáforo ficam no estado neutro deixado por
            # _telemetria_neutra (o buffer antigo pintava os LEDs de verde ao
            # lado de DESCONECTADO); só a quantidade acompanha a placa.
            for ch in range(MAX_CHANNELS):
                self.quality_leds[ch].setVisible(ch < self.num_channels)
            return
        data = self._ordered_buffer()
        n = data.shape[1]
        if n < SAMPLE_RATE // 2:
            return
        last = data[:, -int(SAMPLE_RATE * 2):]  # últimos 2s
        tipos = list(getattr(self.config, "channel_signal_types", None) or [])
        # Faixas absolutas — Cyton: signal aceitável típico é ~10–80 µV RMS
        # Saturação: >2000 µV pico-a-pico = ruim
        # Cores semânticas (escurecidas p/ contraste tanto no claro quanto no
        # escuro) e SÍMBOLO por estado (acessibilidade — não depender só de cor).
        n_ok = n_noisy = n_bad = 0
        ruins, ruidosos = [], []      # nomes dos canais, para a dica (G17)
        for ch in range(MAX_CHANNELS):
            if ch >= self.num_channels:
                self.quality_leds[ch].setVisible(False)
                continue
            self.quality_leds[ch].setVisible(True)
            try:
                # Limiares do TIPO do canal (classifica_qualidade_canal): o
                # olhar desviado do EoG e a contração do EMG passavam de
                # 150 µV RMS e viravam "ruidoso" com o sinal certo.
                tipo = tipos[ch] if ch < len(tipos) else "EEG"
                estado, pp, rms, line_ratio = classifica_qualidade_canal(
                    last[ch], SAMPLE_RATE, tipo)
                ele = self.config.channel_mapping[ch] if ch < len(self.config.channel_mapping) else f"CH{ch+1}"
                if estado == "off":
                    # canal desligado: LED apagado e fora da contagem (o
                    # ruído de ±1,5 µV dele contava como "OK")
                    self.quality_leds[ch].setText("○")
                    self.quality_leds[ch].setStyleSheet("color: #666666; font-size: 11pt;")
                    self.quality_leds[ch].setToolTip(
                        "CH%d (%s): %s" % (ch + 1, ele, tr("off")))
                    continue
                # Classificação heurística -> (cor, símbolo, severidade, texto)
                if estado == "sat":
                    color, glyph, sev, status = ("#d4364f", "■", "bad",
                        f"SATURADO (pp={pp:.0f}µV)")
                elif estado == "flat":
                    color, glyph, sev, status = ("#d4364f", "■", "bad",
                        f"FLAT (rms={rms:.2f}µV)")
                elif estado == "noisy":
                    color, glyph, sev, status = ("#d68a00", "▲", "noisy",
                        f"RUIDOSO (rms={rms:.0f}µV, rede {line_ratio*100:.0f}%)")
                else:
                    color, glyph, sev, status = ("#1d9e75", "●", "ok",
                        f"OK (rms={rms:.0f}µV)")
                if sev == "bad":
                    n_bad += 1
                    ruins.append(f"CH{ch+1} ({ele})")
                elif sev == "noisy":
                    n_noisy += 1
                    ruidosos.append(f"CH{ch+1} ({ele})")
                else:
                    n_ok += 1
                self.quality_leds[ch].setText(glyph)
                self.quality_leds[ch].setStyleSheet(f"color: {color}; font-size: 11pt;")
                self.quality_leds[ch].setToolTip(f"CH{ch+1} ({ele}): {status}")
            except Exception:
                pass

        # ---- Semáforo agregado "Pronto para gravar" (cor + símbolo + rótulo) ----
        if hasattr(self, "quality_summary"):
            if getattr(self, "_semaforo_parado", False):
                # Desconectado: o buffer antigo não diz nada sobre o sinal de
                # agora. Fica neutro até _on_connection_state(True).
                return
            active = n_ok + n_noisy + n_bad
            # A INTEGRIDADE DA AQUISIÇÃO vem antes da qualidade do eletrodo:
            # não adianta dizer "Sinal OK" enquanto o programa perde amostras.
            # Era possível ver "● Sinal OK" e "drops: 90439" lado a lado, sem
            # hierarquia — o indicador verde tem precedência visual e o usuário
            # gravava confiante.
            # Duas coisas DIFERENTES, que antes eram a mesma: amostra que o
            # aparelho mandou e nao chegou (o arquivo fica incompleto) e tela
            # que nao acompanhou o sinal (o arquivo continua inteiro).
            perdidas = int(getattr(self, "_dropped_count", 0) or 0)
            atrasadas = int(getattr(self, "_atraso_count", 0) or 0)
            recebidas = int(getattr(self, "samples_total", 0) or 0)
            if self.is_recording:
                perdidas = max(0, perdidas - int(getattr(self, "_rec_dropped_ini", 0)))
                atrasadas = max(0, atrasadas - int(getattr(self, "_rec_atraso_ini", 0)))
                recebidas = max(0, recebidas - int(getattr(self, "_rec_samples_ini", 0)))
            else:
                # fora da gravação a conta recomeça na última troca de tema ou
                # de letra: o travamento dessa troca perde amostras e a
                # pílula ficava "▲ perdendo amostras 5%" até desconectar,
                # como se fosse falha do aparelho
                ref = getattr(self, "_perda_ref", None) or (0, 0, 0)
                perdidas = max(0, perdidas - int(ref[0]))
                atrasadas = max(0, atrasadas - int(ref[1]))
                recebidas = max(0, recebidas - int(ref[2]))
            perda_pct = (100.0 * perdidas / max(1, perdidas + recebidas)
                         if (perdidas + recebidas) else 0.0)
            atraso_pct = (100.0 * atrasadas / max(1, atrasadas + recebidas)
                          if (atrasadas + recebidas) else 0.0)
            if active and perda_pct >= 2.0:
                grave = perda_pct >= 10.0
                self.quality_summary.setText(
                    f"{'■' if grave else '▲'} {tr('perdendo amostras')} "
                    f"{perda_pct:.0f}%")
                if getattr(self.serial_thread, "mode", "") == "simulation":
                    self.quality_summary.setToolTip(tr(
                        "O simulador ficou sem tempo de processador e pulou "
                        "{0} amostras: o arquivo tem menos amostras que o "
                        "nominal. Feche abas de gráfico pesadas (Tempo Real, "
                        "Espectrograma).").format(perdidas))
                else:
                    self.quality_summary.setToolTip(tr(
                        "O aparelho enviou amostras que não chegaram ao programa "
                        "({0} até agora). Confira o cabo e a porta USB.").format(
                            perdidas))
                self._pinta_resumo_sinal(
                    "erro" if grave else "aviso",
                    f"color: {'#d4364f' if grave else '#d68a00'}; font-size: 9pt; "
                    f"font-weight: bold; padding: 0 8px;")
                try:
                    self._update_header_responsive()
                except Exception:
                    pass
                return
            # Sem perda nenhuma e a tela para tras: e' um aviso de desempenho,
            # nao de integridade. No Simples nem aparece — nao ha o que fazer
            # com ele e o operador so' se assustaria.
            # atraso da fila (amostra que chegou e a tela ainda nao tratou)
            atraso_fila = float(getattr(self, "_atraso_tela_s", 0.0) or 0.0)
            if (active and (atraso_pct >= 2.0 or atraso_fila >= 1.0)
                    and not self._nivel_simples()):
                if atraso_pct >= 2.0:
                    self.quality_summary.setText(
                        tr("▲ tela atrasada {0}%").format(int(round(atraso_pct))))
                else:
                    self.quality_summary.setText(
                        tr("▲ tela {0:.1f} s atrasada").format(atraso_fila))
                # "arquivo completo" so' vale com a taxa efetiva na nominal:
                # a 51 Hz de 250 esta dica afirmava o contrario do data.csv
                taxa = self._taxa_efetiva_recente()
                nominal = float(getattr(self, "sample_rate", SAMPLE_RATE) or SAMPLE_RATE)
                if taxa is not None and abs(taxa - nominal) > 0.05 * nominal:
                    self.quality_summary.setToolTip(tr(
                        "A tela não está acompanhando o sinal, e a taxa efetiva "
                        "está em {0:.0f} Hz (nominal {1:.0f} Hz): o arquivo pode "
                        "ficar com menos amostras que o esperado. Confira "
                        "sample_rate_ok no summary.json e feche abas de gráfico "
                        "pesadas (Tempo Real, Espectrograma).").format(taxa, nominal))
                else:
                    self.quality_summary.setToolTip(tr(
                        "A tela não está acompanhando o sinal. O arquivo continua "
                        "completo — nenhuma amostra foi perdida. Feche abas de "
                        "gráfico pesadas (Tempo Real, Espectrograma) para a tela "
                        "voltar a acompanhar."))
                self._pinta_resumo_sinal(
                    "aviso", "color: #d68a00; font-size: 9pt; font-weight: bold; "
                    "padding: 0 8px;")
                try:
                    self._update_header_responsive()
                except Exception:
                    pass
                return
            simples = self._nivel_simples()
            # Dicas com a ação recomendada e os canais (validação com leigos,
            # G17); no Simples o ícone da pílula de sinal é ✓, não ●, para
            # não se confundir com a de conexão.
            if active == 0:
                txt, col, tip = "—", "#888", tr("Sinal: aguardando dados")
            elif n_bad:
                txt, col = tr("■ {0} ruim(ns)").format(n_bad), "#d4364f"
                tip = tr("Sinal ruim em {0}: eletrodo solto, sem contato ou "
                         "saturado. Recoloque o eletrodo (ou confira o cabo) "
                         "desses canais antes de gravar.").format(_lista_canais(ruins))
            elif n_noisy:
                txt, col = tr("▲ {0} ruidoso(s)").format(n_noisy), "#d68a00"
                tip = tr("Sinal com ruído em {0}. Peça para a pessoa relaxar e "
                         "ficar parada, confira se o eletrodo está bem encostado "
                         "e afaste os cabos da tomada. Dá para gravar, mas o "
                         "relatório fica menos confiável.").format(_lista_canais(ruidosos))
            elif simples and self._modo_treino():
                # sinal de exemplo: não há eletrodo para avaliar (G16)
                txt, col = "✓ " + tr("Sinal de treino"), "#1d9e75"
                tip = tr("Sinal de exemplo gerado pelo programa: serve para "
                         "praticar; não há eletrodos para avaliar.")
            else:
                txt, col = ("✓ " if simples else "● ") + tr("Sinal OK"), "#1d9e75"
                tip = (tr("Sinal pronto para gravar") + "\n"
                       + tr("Eletrodos com bom contato nos {0} canais em uso.")
                       .format(active))
            self.quality_summary.setText(txt)
            self.quality_summary.setToolTip(tip)
            self._pinta_resumo_sinal(
                {"#1d9e75": "ok", "#d4364f": "erro", "#d68a00": "aviso"}.get(col, "neutro"),
                f"color: {col}; font-size: 9pt; font-weight: bold; padding: 0 8px;")
        # Re-flui o header responsivo: a telemetria muda de largura ao longo da
        # sessão (Amostras, g, drift) sem disparar resize — reavaliamos aqui.
        try:
            self._update_header_responsive()
        except Exception:
            pass

    # ==================================================================
    # Markers
    # ==================================================================
    def _clear_marker_lines(self):
        """Remove dos gráficos todas as linhas verticais de marcadores, tanto na
        visão por canal quanto na empilhada.

        Chamado no início de cada conexão. Cada linha é removida apenas do
        plot em que foi inserida, usando o índice guardado na lista do canal.
        """
        if hasattr(self, "channel_marker_lines"):
            plots = getattr(self, "channel_plots", [])
            for ch, ch_lines in enumerate(self.channel_marker_lines):
                plot = plots[ch] if ch < len(plots) else None
                for _s, line in ch_lines:
                    if plot is None:
                        continue
                    try: plot.removeItem(line)
                    except Exception: pass
                ch_lines.clear()
        # Limpa markers do modo Empilhado
        if hasattr(self, "montage_marker_lines"):
            for _t, mline in self.montage_marker_lines:
                try: self.montage_plot.removeItem(mline)
                except Exception: pass
            self.montage_marker_lines.clear()

    def _inject_marker_from_edit(self):
        """Envia como marcador o texto digitado na caixa e limpa o campo."""
        label = self.marker_edit.text().strip()
        if not label:
            self._log("Marker vazio ignorado", error=True); return
        self._inject_marker_text(label)
        self.marker_edit.clear()

    def _inject_marker_text(self, label):
        """Registra um marcador na sessão: guarda tempo e rótulo, escreve no
        events.csv, publica em UDP/LSL e desenha a linha vertical nos gráficos.

        O rótulo fica em pending_marker e é consumido pela próxima amostra em
        _on_sample, então ele cai na linha do data.csv correspondente. O tempo
        é relativo a session_start (0,0 se ainda não houver sessão). No modo
        Empilhado só as 12 linhas mais recentes permanecem no gráfico; as
        antigas são removidas.
        """
        # Tempo relativo ao INÍCIO DA GRAVAÇÃO (monotônico) quando gravando;
        # fora do REC, relativo à conexão, só para exibir na lista.
        if self.is_recording and self._rec_start_mono is not None:
            t = time.perf_counter() - self._rec_start_mono
        else:
            t = (time.time() - self.session_start) if self.session_start else 0.0
        self.markers.append((t, label))
        self.pending_marker = label
        self._audit_event("marker", label=label, t_session=round(t, 3))
        if self.is_recording:
            # Confirmação na barra e contador no botão: nada mudava na tela
            # fora do traçado, e quem estava na aba Músculos só via o evento
            # no PDF (validação com leigos)
            n = int(getattr(self, "_eventos_gravacao", 0) or 0) + 1
            self._eventos_gravacao = n
            if hasattr(self, "ab_marker_btn"):
                self.ab_marker_btn.setText(tr("⚑  Marcar evento") + " (%d)" % n)
            self._dica_temporaria(
                tr("Evento {0} marcado aos {1} s.").format(n, num_loc(t, 0)), ms=3000)
        # events.csv — o índice tem de ser a LINHA DO data.csv, ou seja, contado
        # a partir do REC. Antes ia samples_total, acumulado desde a CONEXÃO:
        # um marcador na linha 718 era gravado como 17.087 e qualquer script
        # que alinhasse eventos por índice estourava ou errava em silêncio.
        if self.is_recording:
            idx = max(0, int(self.samples_total) - int(self._rec_samples_ini))
            self.events_logger.log(label, idx, t)
        self.markers_view.append(
            f'<span style="color:{COLORS["text_dim"]}">[{t:7.2f}s]</span> '
            f'<span style="color:{COLORS["accent"]}; font-weight:bold;">{label}</span>')
        if self.udp.enabled:
            self.udp.send_marker(t, label)
        if self.lsl.enabled:
            self.lsl.send_marker(label)
        self._log(f"Marker: {label} @ {t:.2f}s")
        if hasattr(self, "channel_plots"):
            # Guarda o indice ABSOLUTO da amostra; a posicao em segundos e
            # recalculada a cada quadro por _reposiciona_marcadores_canais.
            # Antes a linha nascia no tempo desde a CONEXAO e caia fora do
            # traco, que cobre so os ultimos segundos do buffer.
            s_abs = int(self.samples_total)
            win_n = int(getattr(self, "_rt_win_n", 0) or 0)
            x0 = win_n / float(SAMPLE_RATE) if win_n else 0.0
            # So os canais em uso: desenhar nos 64 plots criava 64 objetos por
            # marcador, quase todos invisiveis.
            n_plots = min(int(self.num_channels), len(self.channel_plots))
            for ch in range(n_plots):
                plot = self.channel_plots[ch]
                line = pg.InfiniteLine(
                    pos=x0, angle=90,
                    pen=pg.mkPen(COLORS["warning"], width=2, style=QtCore.Qt.PenStyle.DashLine))
                plot.addItem(line)
                self.channel_marker_lines[ch].append((s_abs, line))
        # Linha de marker no modo Empilhado (na posição = fim da janela)
        if hasattr(self, "montage_plot"):
            win_s = self.rt_window_spin.value() if hasattr(self, "rt_window_spin") else 5
            mline = pg.InfiniteLine(
                pos=win_s, angle=90,
                pen=pg.mkPen(COLORS["warning"], width=2,
                              style=QtCore.Qt.PenStyle.DashLine),
                label=label,
                labelOpts={"color": COLORS["warning"],
                           # Alterna a altura para rotulos proximos nao se
                           # sobreporem no canto superior direito.
                           "position": 0.95 if len(self.montage_marker_lines) % 2 == 0 else 0.85})
            self.montage_plot.addItem(mline)
            # Indice absoluto da amostra no lugar do relogio: _update_montage
            # reprojeta a linha a cada quadro para ela andar junto com o traco.
            self.montage_marker_lines.append((int(self.samples_total), mline))
            # Mantém só os últimos 12 markers visíveis (limpa antigos)
            while len(self.montage_marker_lines) > 12:
                _t, old = self.montage_marker_lines.pop(0)
                try: self.montage_plot.removeItem(old)
                except Exception: pass

    # ==================================================================
    # Gravação
    # ==================================================================
    def _toggle_recording(self):
        """Botão único de iniciar/parar gravação."""
        if self.is_recording:
            self._stop_recording()
            # Modal só depois de o slot devolver o loop (arquivos já fechados)
            QtCore.QTimer.singleShot(0, self._dialogo_sessao_gravada)
        else:
            self._start_recording()

    def _dialogo_sessao_gravada(self):
        """Caixa "Sessão gravada" após parar pelo botão, nos dois níveis. Não é
        chamada de _stop_recording (que também serve a _disconnect, closeEvent
        e demo): só de _toggle_recording e _toggle_connection."""
        ultima = getattr(self, "_ultima_sessao_parada", None)
        if (not ultima or not ultima[0] or getattr(self, "_closing", False)
                or getattr(self, "_demo_running", False)):
            return
        pasta = ultima[0]
        msg = QtWidgets.QMessageBox(self)
        msg.setIcon(QtWidgets.QMessageBox.Icon.Information)
        if self._nivel_simples():
            # Frase curta com quem e quando; o caminho inteiro fica na dica
            # de ferramenta e em "Abrir pasta" (validação com leigos, G25)
            msg.setWindowTitle(tr("Gravação salva"))
            msg.setText(self._frase_gravacao_salva(pasta) + "\n\n"
                        + tr("O que você quer fazer agora?"))
            msg.setToolTip(str(pasta))
        else:
            msg.setWindowTitle(tr("Sessão gravada"))
            msg.setText(tr("Gravação salva em:\n{0}\n\nO que você quer fazer agora?").format(
                self._caminho_quebravel(pasta)))
        b_pdf = msg.addButton(tr("→ Relatório PDF"),
                              QtWidgets.QMessageBox.ButtonRole.ActionRole)
        b_abrir = msg.addButton(tr("Abrir pasta"),
                                QtWidgets.QMessageBox.ButtonRole.ActionRole)
        b_fechar = msg.addButton(tr("Fechar"),
                                 QtWidgets.QMessageBox.ButtonRole.RejectRole)
        msg.setDefaultButton(b_fechar)
        if self._nivel_simples():
            # O relatório é a ação cheia; "Abrir pasta" e "Fechar" em contorno
            # neutro legível. O Enter continua em Fechar.
            d = _dens
            self._papel_botao(b_pdf, "primaria", d(46, 40))
            for b in (b_abrir, b_fechar):
                self._papel_botao(b, "secundaria", d(40, 34))
            lbl = msg.findChild(QtWidgets.QLabel, "qt_msgbox_label")
            if lbl is not None:
                lbl.setMinimumWidth(d(460, 400))       # o caminho quebra menos
                lbl.setStyleSheet("font-size: 11pt;")
                lbl.setToolTip(tr("Pasta da gravação:") + "\n" + str(pasta))
            if msg.layout() is not None:
                msg.layout().setContentsMargins(d(26, 20), d(22, 16),
                                                d(26, 20), d(20, 14))
        msg.exec()
        if msg.clickedButton() is b_pdf:
            self._export_pdf_report(csv_path=os.path.join(pasta, "data.csv"))
        elif msg.clickedButton() is b_abrir:
            self._abrir_pasta(pasta)

    def _frase_gravacao_salva(self, pasta):
        """"Salva na pasta de Maria Teste, 27/09 às 10:15." (G25)."""
        quando = None
        try:
            with open(os.path.join(pasta, "summary.json"), "r",
                      encoding="utf-8") as fh:
                ini = str(json.load(fh).get("started_at") or "")
            quando = datetime.fromisoformat(ini[:19])
        except Exception:
            pass
        if quando is None:
            quando = datetime.now()
        q = tr("{0} às {1}").format(quando.strftime("%d/%m"),
                                    quando.strftime("%H:%M"))
        vol = self.volunteers.current() if hasattr(self, "volunteers") else None
        if vol:
            return tr("Salva na pasta de {0}, {1}.").format(
                vol.get("nome") or vol.get("vid") or "", q)
        # nome digitado vem antes do treino: é ele que dá nome à pasta
        suj = sujeito_digitado(getattr(self.config, "subject", ""))
        if suj:
            return tr("Salva com o nome {0}, {1}.").format(suj, q)
        # sem paciente a gravação vai para a pasta geral: diz o NOME da pasta
        # e como achá-la de novo (validação com leigos)
        nome_pasta = os.path.basename(os.path.normpath(str(pasta)))
        achar = tr("Você acha de novo em Início → Abrir uma gravação.")
        if self._modo_treino():
            return (tr("Treino salvo na pasta de gravações como {0} (sem paciente), {1}.")
                    .format(nome_pasta, q) + " " + achar)
        return (tr("Salva na pasta geral (sem paciente) como {0}, {1}.")
                .format(nome_pasta, q) + " " + achar)

    def _risco_pasta_sessao(self, pasta):
        """Avalia o destino da gravação. Devolve (é_grave, texto) ou None.

        Três perigos, em ordem de gravidade:
          1. pasta temporária do sistema — a Limpeza de Disco apaga sozinha;
          2. sem permissão de escrita ou sem espaço — a coleta morre no meio;
          3. pasta sincronizada (OneDrive/Drive/Dropbox) — gravar linha a linha
             gera reupload constante e o arquivo pode ficar travado.
        """
        try:
            alvo = os.path.abspath(pasta)
        except Exception:
            return (True, tr("Não consegui interpretar a pasta de gravação."))
        baixo = alvo.lower()

        temp = [t for t in (os.environ.get("TEMP"), os.environ.get("TMP"),
                            tempfile.gettempdir()) if t]
        for t in temp:
            try:
                if os.path.commonpath([alvo, os.path.abspath(t)]) == os.path.abspath(t):
                    return (True, tr(
                        "A pasta de gravação está dentro da pasta TEMPORÁRIA do "
                        "Windows:\n\n{}\n\nO Windows apaga essa pasta sozinho "
                        "(Limpeza de Disco / Sensor de Armazenamento). Uma "
                        "coleta gravada aí pode desaparecer.\n\nMude em Sistema "
                        "→ Configurações antes de gravar.").format(alvo))
            except (ValueError, OSError):
                continue

        # escrita e espaço
        try:
            teste = os.path.join(alvo, ".roa_escrita_teste")
            with open(teste, "w") as f:
                f.write("x")
            os.remove(teste)
        except Exception:
            return (True, tr(
                "Não consigo escrever na pasta de gravação:\n\n{}\n\n"
                "Escolha outra em Sistema → Configurações.").format(alvo))
        try:
            livre_mb = shutil.disk_usage(alvo).free / (1024 * 1024)
            if livre_mb < 200:
                return (True, tr(
                    "Só restam {:.0f} MB livres no disco da pasta de gravação. "
                    "Uma hora de coleta a {} Hz ocupa algumas centenas de MB e "
                    "a gravação pode parar no meio.").format(livre_mb, SAMPLE_RATE))
        except Exception:
            pass

        for nuvem in ("onedrive", "dropbox", "google drive", "\\\\"):
            if nuvem in baixo:
                return (False, tr(
                    "Aviso: a pasta de gravação está numa área sincronizada "
                    "({}). O arquivo é escrito linha a linha durante a coleta, "
                    "o que gera reenvio constante e pode travar o arquivo. Para "
                    "coleta longa, prefira uma pasta local.").format(nuvem))
        return None

    def _modo_treino(self):
        """True quando o sinal é simulado (treino sem aparelho)."""
        th = getattr(self, "serial_thread", None)
        # só a thread que está rodando manda: depois de desconectar o modo
        # antigo ficava colado e a pasta seguinte saía "treino_" no aparelho
        if th is not None and getattr(th, "mode", None):
            try:
                if th.isRunning():
                    return th.mode == "simulation"
            except RuntimeError:
                pass
        combo = getattr(self, "mode_combo", None)
        return combo is not None and combo.currentIndex() == 1

    def _pergunta_paciente_antes_de_gravar(self):
        """No Simples, com o aparelho real e sem paciente em uso, abre "De quem
        é este exame?". Devolve False se a pessoa desistiu (G25)."""
        if not self._nivel_simples() or self._modo_treino():
            return True
        if not hasattr(self, "volunteers") or self.volunteers.current():
            return True
        if getattr(self, "_demo_running", False) or getattr(self, "_closing", False):
            return True
        res = self._dialogo_de_quem_e_o_exame()
        if res is None:
            self._log("Gravação cancelada: nenhum paciente escolhido.")
            return False
        if res:
            try:
                prof = self.volunteers.select_volunteer(res)
                self._log(f"Voluntário ativo: {prof.get('vid')} — {prof.get('nome')}")
                self._audit_event("volunteer_selected", vid=prof.get("vid"))
                if hasattr(self, "_volunteer_refresh_table"):
                    self._volunteer_refresh_table()
                self._volunteer_update_indicator()
            except Exception as exc:
                self._log(f"Não foi possível ativar o paciente: {exc}", error=True)
        return True

    def _canais_emg_sem_musculo(self):
        """Índices dos canais de EMG em uso sem músculo marcado (None quando
        não há canal de EMG em uso)."""
        tipos = list(getattr(self.config, "channel_signal_types", None) or [])
        musc = list(getattr(self.config, "emg_channel_muscle", None) or [])
        n = int(getattr(self, "num_channels", BASE_CHANNELS) or BASE_CHANNELS)
        emg = [i for i in range(n) if i < len(tipos) and tipos[i] == "EMG"]
        if not emg:
            return None
        sem = []
        for i in emg:
            m = str(musc[i]).strip() if i < len(musc) else ""
            if not m or m == "(não definido)":
                sem.append(i)
        return sem

    def _ir_para_musculos(self):
        """Visualizar → Músculos (aba Bio, primeira sub-aba)."""
        try:
            self._main_tabs.setCurrentIndex(1)
            view = self._sub_tabs.get("view")
            if view is not None:
                view.setCurrentIndex(self._pos_aba("view", 3))
            if hasattr(self, "bio_tabs") and self.bio_tabs.count():
                self.bio_tabs.setCurrentIndex(0)
        except Exception as exc:
            self._log(f"Falha ao ir para a aba Músculos: {exc}", error=True)

    def _pergunta_musculos_antes_de_gravar(self):
        """No Simples, num exame de músculos sem NENHUM músculo marcado, abre
        "Músculos não marcados" com Marcar músculos / Gravar assim mesmo /
        Cancelar. Devolve False quando a gravação não deve começar
        (validação com leigos)."""
        if not self._nivel_simples() or getattr(self, "_signal_mode", None) != "EMG":
            return True
        if getattr(self, "_demo_running", False) or getattr(self, "_closing", False):
            return True
        sem = self._canais_emg_sem_musculo()
        if sem is None or len(sem) < len([1 for i in range(int(self.num_channels))
                                           if i < len(self.config.channel_signal_types)
                                           and self.config.channel_signal_types[i] == "EMG"]):
            return True                 # nenhum canal de EMG, ou algum já marcado
        msg = QtWidgets.QMessageBox(self)
        msg.setIcon(QtWidgets.QMessageBox.Icon.Question)
        msg.setWindowTitle(tr("Músculos não marcados"))
        msg.setText(tr("Você não marcou o músculo de nenhum canal. O relatório vai "
                       "chamar os canais só de \"CH1 músculo\", \"CH2 músculo\"… "
                       "Gravar assim mesmo?"))
        R = QtWidgets.QMessageBox.ButtonRole
        b_marcar = msg.addButton(tr("Marcar músculos"), R.ActionRole)
        b_gravar = msg.addButton(tr("Gravar assim mesmo"), R.AcceptRole)
        b_cancel = msg.addButton(tr("Cancelar"), R.RejectRole)
        msg.setDefaultButton(b_gravar)
        msg.setEscapeButton(b_cancel)
        msg.exec()
        cl = msg.clickedButton()
        if cl is b_marcar:
            self._ir_para_musculos()
            return False
        if cl is b_cancel:
            self._log("Gravação cancelada: músculos não marcados.")
            return False
        return True

    def _monta_dialogo_de_quem(self):
        """Diálogo "De quem é este exame?": lista de pacientes, "+ Novo",
        "Gravar para este paciente", "Gravar sem paciente" e "Cancelar". O
        resultado fica em dlg.resultado: pasta do paciente, "" (sem
        paciente) ou None (cancelou). Separado de exec() para o teste."""
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(tr("De quem é este exame?"))
        dlg.resultado = None
        v = QtWidgets.QVBoxLayout(dlg)
        v.setContentsMargins(18, 16, 18, 14); v.setSpacing(8)
        lbl = QtWidgets.QLabel(
            tr("Nenhum paciente está em uso. Escolha o paciente para guardar "
               "esta gravação na pasta dele."))
        lbl.setWordWrap(True)
        v.addWidget(lbl)
        linha = QtWidgets.QHBoxLayout(); linha.setSpacing(6)
        combo = QtWidgets.QComboBox()
        linha.addWidget(combo, stretch=1)
        b_novo = QtWidgets.QPushButton(tr("+ Novo"))
        b_novo.setToolTip(tr("Cadastra um paciente só pelo nome."))
        linha.addWidget(b_novo)
        v.addLayout(linha)
        b_gravar = QtWidgets.QPushButton(tr("Gravar para este paciente"))
        b_sem = QtWidgets.QPushButton(tr("Gravar sem paciente"))
        b_sem.setToolTip(tr("A gravação vai para a pasta geral, sem ficha."))
        b_cancel = QtWidgets.QPushButton(tr("Cancelar"))
        botoes = QtWidgets.QHBoxLayout(); botoes.setSpacing(8)
        botoes.addStretch()
        for b in (b_gravar, b_sem, b_cancel):
            botoes.addWidget(b)
        v.addSpacing(6)
        v.addLayout(botoes)

        def _preenche(escolher=None):
            combo.clear()
            for p in self.volunteers.list_volunteers():
                combo.addItem(tr("{0} (código {1})").format(
                    p.get("nome", ""), p.get("vid", "")), p.get("_dirname"))
            if escolher:
                i = combo.findData(escolher)
                if i >= 0:
                    combo.setCurrentIndex(i)
            b_gravar.setEnabled(combo.count() > 0)

        def _novo():
            titulo = tr("Cadastrar novo paciente")
            nome, ok = pede_texto(dlg, titulo, tr("Nome do paciente:"))
            nome = (nome or "").strip()
            if not ok or not nome:
                return
            try:
                if any((p.get("nome") or "").strip().casefold() == nome.casefold()
                       for p in self.volunteers.list_volunteers()):
                    raise ValueError(nome)
                prof = self.volunteers.create_volunteer(
                    {"vid": self.volunteers.next_vid(), "nome": nome})
            except ValueError:
                QtWidgets.QMessageBox.warning(
                    dlg, titulo,
                    tr("Já existe um paciente com esse nome. Escolha-o na lista "
                       "ou use outro nome."))
                return
            except Exception as exc:
                QtWidgets.QMessageBox.warning(dlg, titulo, str(exc))
                return
            # create_volunteer já deixa o novo em uso; a lista o mostra marcado
            _preenche(prof.get("_dirname"))

        def _gravar():
            dlg.resultado = combo.currentData() or ""
            dlg.accept()

        def _sem():
            dlg.resultado = ""
            dlg.accept()

        b_novo.clicked.connect(lambda _=False: _novo())
        b_gravar.clicked.connect(lambda _=False: _gravar())
        b_sem.clicked.connect(lambda _=False: _sem())
        b_cancel.clicked.connect(dlg.reject)
        b_gravar.setDefault(True)
        _preenche()
        if self._nivel_simples():
            d = _dens
            self._papel_botao(b_gravar, "primaria", d(46, 40))
            for b in (b_sem, b_cancel, b_novo):
                self._papel_botao(b, "secundaria", d(40, 34))
        dlg.combo, dlg.b_novo, dlg.b_gravar = combo, b_novo, b_gravar
        dlg.b_sem, dlg.b_cancel = b_sem, b_cancel
        return dlg

    def _dialogo_de_quem_e_o_exame(self):
        """Abre o diálogo de _monta_dialogo_de_quem e devolve dlg.resultado."""
        dlg = self._monta_dialogo_de_quem()
        dlg.exec()
        return dlg.resultado

    def _start_recording(self):
        # ---- Pasta de sessão customizada ----
        """Cria a pasta da sessão, abre todos os arquivos de saída (data.csv,
        session.log.txt, summary.json, events.csv) e liga o modo REC.

        Se o diretório configurado for inválido, cai para
        DEFAULT_SAVE_DIRECTORY e persiste essa mudança na config. Com
        voluntário ativo a sessão vai para volunteers/<VID_Nome>/ e o nome
        ganha o VID como prefixo; colisão de nome recebe sufixo _1, _2… O
        cabeçalho do CSV usa os rótulos do mapeamento (ex.: Fp1_uV), não
        CHn_uV. O disparo do protocolo automático vem por último de propósito:
        o primeiro marcador só faz sentido depois que o events.csv existe.
        """
        # Simples, com o aparelho de verdade e sem paciente em uso: pergunta
        # de quem é o exame antes de criar a pasta (validação com leigos, G25)
        if not self._pergunta_paciente_antes_de_gravar():
            return
        # Simples, exame de músculos sem nenhum músculo marcado: pergunta agora
        # (o PDF só avisava no fim: "Músculo não informado em CH1-CH8")
        if not self._pergunta_musculos_antes_de_gravar():
            return
        # Gravação nova: o passo volta a "gravando" e o relatório anterior
        # deixa de ser oferecido (G05); a gravação aberta de outro paciente
        # deixa de mandar no selo (G03)
        self._ultima_sessao_parada = None
        self._pdf_gerado = None
        self._gravacao_aberta_de = None
        # o contador de eventos do botão recomeça a cada gravação
        self._eventos_gravacao = 0
        if hasattr(self, "ab_marker_btn"):
            self.ab_marker_btn.setText(tr("⚑  Marcar evento"))
        save_root = self.config.save_directory
        try:
            os.makedirs(save_root, exist_ok=True)
        except Exception as exc:
            self._log(f"Diretório de salvamento inválido ({save_root}): {exc} — "
                      f"caindo para o padrão", error=True)
            save_root = DEFAULT_SAVE_DIRECTORY
            os.makedirs(save_root, exist_ok=True)
            self.config.save_directory = save_root
            self.config.save()
        # ANTES de gravar, confere para ONDE vai. Já foi encontrada instalação
        # apontando para %TEMP%: a Limpeza de Disco do Windows apaga aquilo sem
        # avisar, e a coleta de um voluntário some. É o tipo de perda que não
        # se refaz, então aqui é bloqueio, não recado no log.
        risco = self._risco_pasta_sessao(save_root)
        if risco:
            grave, texto = risco
            if grave:
                resp = QtWidgets.QMessageBox.warning(
                    self, tr("Onde a gravação vai ser salva"), texto,
                    QtWidgets.QMessageBox.StandardButton.Cancel
                    | QtWidgets.QMessageBox.StandardButton.Ignore,
                    QtWidgets.QMessageBox.StandardButton.Cancel)
                if resp != QtWidgets.QMessageBox.StandardButton.Ignore:
                    self._log("Gravação cancelada: pasta de destino insegura.",
                              error=True)
                    return
            else:
                self._log(texto)
        # O mesmo nome que a prévia de Sistema mostra, já com o VID (G04)
        self.session_name = self._nome_pasta_proxima_gravacao()
        # Se houver voluntário ativo, a sessão vai para volunteers/<VID_Nome>/
        vol = self.volunteers.current() if hasattr(self, "volunteers") else None
        if vol:
            self.volunteers.set_base_dir(save_root)
            vol_dir = self.volunteers.current_dir()
            os.makedirs(vol_dir, exist_ok=True)
            self.current_session_dir = os.path.join(vol_dir, self.session_name)
        else:
            self.current_session_dir = os.path.join(save_root, self.session_name)
        # garante unicidade se já existir
        suffix = 1
        base = self.current_session_dir
        while os.path.exists(self.current_session_dir):
            self.current_session_dir = f"{base}_{suffix}"
            suffix += 1
        os.makedirs(self.current_session_dir, exist_ok=True)
        os.makedirs(os.path.join(self.current_session_dir, "snapshots"), exist_ok=True)

        csv_path    = os.path.join(self.current_session_dir, "data.csv")
        log_path    = os.path.join(self.current_session_dir, "session.log.txt")
        meta_path   = os.path.join(self.current_session_dir, "summary.json")
        events_path = os.path.join(self.current_session_dir, "events.csv")

        # events.csv — mapeia markers → linhas do data.csv (análise futura)
        self.events_logger.start(events_path)

        # Snapshot da ficha do voluntário dentro da sessão
        if vol:
            try:
                with open(os.path.join(self.current_session_dir,
                                       "volunteer_profile.json"),
                          "w", encoding="utf-8") as f:
                    json.dump(vol, f, ensure_ascii=False, indent=2)
            except Exception: pass
        try:
            self.csv_file = open(csv_path, "w", newline="", encoding="utf-8")
            self.csv_writer = csv.writer(self.csv_file)
            # Cabeçalho usa os nomes do mapeamento (ex: Fp1_uV) em vez de CHn_uV
            mapping = self.config.channel_mapping
            ch_names = [f"{mapping[i]}_uV" if i < len(mapping) else f"CH{i+1}_uV"
                        for i in range(self.num_channels)]
            header = (["timestamp_s"] + ch_names
                      + ["ax_g", "ay_g", "az_g", "marker"])
            self.csv_writer.writerow(header)
            self.log_file = open(log_path, "w", encoding="utf-8")
            self.log_file.write(
                f"=== Sessão '{self.session_name}' iniciada em {datetime.now().isoformat()} ===\n"
                f"Gerado por: {APP_NAME} v{APP_VERSION} ({APP_EDITION}) — {CODE_URL}\n"
                f"Sujeito: {self.config.subject or '(não informado)'}\n"
                f"Porta/modo: {self.port_combo.currentText()} | {self.mode_combo.currentText()}\n"
                f"Baud: {self.baud_combo.currentText()}\n"
                f"Número de canais: {self.num_channels} "
                f"({'com módulo de expansão' if self.num_channels > BASE_CHANNELS else 'placa base'})\n"
                f"Sample Rate: {SAMPLE_RATE} Hz\n"
                f"Mapeamento: {mapping[:self.num_channels]}\n"
                f"Canais ativos: "
                f"{[mapping[i] for i, a in enumerate(self.channel_active[:self.num_channels]) if a]}\n"
                f"Filtros: notch={'ON' if self.filters.notch_enabled else 'OFF'} "
                f"@ {self.filters.notch_freq:.0f}Hz | "
                f"bandpass={'ON' if self.filters.bandpass_enabled else 'OFF'} "
                f"{self.filters.bp_low:.1f}-{self.filters.bp_high:.1f}Hz\n"
                f"Tema: {self.config.theme}\n"
                f"Snapshot interval: {self.config.snapshot_interval}s\n"
                f"Pasta: {self.current_session_dir}\n\n")
            self.log_file.flush()
            # summary.json
            try:
                with open(meta_path, "w", encoding="utf-8") as f:
                    json.dump({
                        # Proveniencia (reprodutibilidade/auditoria): qual versao
                        # do app e de onde veio o codigo geraram este registro.
                        "generated_by": {
                            "app":          APP_NAME,
                            "app_version":  APP_VERSION,
                            "app_edition":  APP_EDITION,
                            "code_url":     CODE_URL,
                        },
                        "session_name": self.session_name,
                        "started_at":   datetime.now().isoformat(),
                        "subject":      self.config.subject,
                        "num_channels": self.num_channels,
                        "mapping":      mapping[:self.num_channels],
                        "sample_rate":  SAMPLE_RATE,
                        "filters": {
                            "notch_on":   self.filters.notch_enabled,
                            "notch_freq": self.filters.notch_freq,
                            "bp_on":      self.filters.bandpass_enabled,
                            "bp_low":     self.filters.bp_low,
                            "bp_high":    self.filters.bp_high,
                            "phase":      "causal (online, sosfilt+zi)",
                        },
                        # filtro ligado sozinho ao conectar no modo Simples (só
                        # vale enquanto algum filtro segue ligado)
                        "filters_auto": bool(
                            getattr(self, "_filtros_auto", False)
                            and (self.filters.notch_enabled
                                 or self.filters.bandpass_enabled)),
                        # modalidade da sessão: o relatório PDF titula por ela
                        "acquisition_mode": getattr(self, "_signal_mode", None),
                        # canais escolhidos nas abas Coração e Olhos: o PDF usa
                        # os mesmos da tela (chave nova; G09/G10)
                        "report_channels": self._canais_escolhidos_na_tela(),
                        # G-04 metadados obrigatórios de aquisição:
                        "hardware":     self._gather_hardware(),
                        # G-01/G-02/G-06 reprodutibilidade (seed, versões, receita DSP):
                        "provenance":   self._gather_provenance(),
                        # G-05/GOV-07 privacidade (LGPD art.11 — biossinal sensível):
                        "privacy": {
                            "data_class": "biossinal (dado sensível, LGPD art.11; "
                                          "quase-biométrico)",
                            "note": "PII (nome/DOB) NÃO deve estar no dado; fica só no "
                                    "perfil local do voluntário. Pseudonimize por ID.",
                        },
                        "theme":        self.config.theme,
                        "volunteer":    (self.volunteers.current()
                                         if hasattr(self, "volunteers") else None),
                    }, f, ensure_ascii=False, indent=2)
            except Exception: pass
        except OSError as exc:
            self._log(f"Falha ao criar arquivo: {exc}", error=True)
            self._close_record_files(); return

        # t=0 e as bases dos contadores pertencem a GRAVACAO, nao a conexao
        self._rec_start_mono = time.perf_counter()
        # as piscadas e a taxa por minuto contam desde o início da GRAVAÇÃO,
        # como no relatório; antes só zeravam ao conectar (G10)
        if hasattr(self, "eog_v_combo"):
            try:
                self._eog_reset()
            except Exception:
                pass
        self._rec_first_mono = None
        self._rec_last_ts = None
        self._rec_dropped_ini = int(getattr(self, '_dropped_count', 0))
        self._rec_atraso_ini = int(getattr(self, '_atraso_count', 0))
        self._rec_samples_ini = int(getattr(self, 'samples_total', 0))
        self.is_recording = True
        self._snapshot_counter = 0
        self.record_btn.setText(tr("■  Parar Gravação"))
        self.record_btn.setStyleSheet(
            f"background-color: {COLORS['error']}; color: white; "
            f"border-color: {COLORS['error']};")
        self._pinta_rec(True)
        self._log(f"Gravação iniciada — {self.session_name}/data.csv "
                  f"({self.num_channels} canais)")
        self._update_status_state()
        self._update_window_title()
        # Reabre o audit log na pasta da nova sessão
        self._close_audit_log()
        self._open_audit_log()
        self._audit_event("recording_start",
                          path=csv_path, num_channels=self.num_channels,
                          mapping=self.config.channel_mapping[:self.num_channels],
                          filters={"notch": self.filters.notch_enabled,
                                   "notch_freq": self.filters.notch_freq,
                                   "bp": self.filters.bandpass_enabled,
                                   "bp_low": self.filters.bp_low,
                                   "bp_high": self.filters.bp_high})

        # Snapshot inicial + timer para snapshots periódicos
        if self.config.snapshot_interval > 0:
            self._save_snapshot(reason="início")
            if not hasattr(self, "snapshot_timer") or self.snapshot_timer is None:
                self.snapshot_timer = QTimer(self)
                self.snapshot_timer.timeout.connect(
                    lambda: self._save_snapshot(reason="auto")
                )
            self.snapshot_timer.start(self.config.snapshot_interval * 1000)

        # Dispara a sequência de tempo junto com a gravação, se configurado.
        # Vem por último de propósito: o primeiro marcador do protocolo só faz
        # sentido depois que o events.csv já existe.
        if (getattr(self.config, "protocol_auto_start", False)
                and getattr(self, "_proto_run_t0", None) is None):
            try:
                self._proto_iniciar()
            except Exception as exc:
                self._log(f"Falha ao iniciar o protocolo: {exc}", error=True)

    def _stop_recording(self):
        # Parar de gravar encerra o protocolo: deixá-lo correndo produziria
        # marcadores que não vão para arquivo nenhum.
        """Encerra a gravação: para o protocolo, tira o snapshot final, fecha os
        arquivos, registra a execução do voluntário e assina a sessão.

        A ordem importa: _sign_session_files() (SHA-256 + nonce) é o último
        passo porque precisa do data.csv já fechado. O events.csv é fechado
        aqui por events_logger.stop(), fora de _close_record_files().
        """
        # Guarda a última sessão para a dica e o diálogo "Sessão gravada".
        # NENHUM diálogo aqui: também é chamada por _disconnect, closeEvent e demo.
        self._ultima_sessao_parada = (self.current_session_dir, self.session_name)
        # o contador "(n)" do botão de evento é da gravação que acabou
        if hasattr(self, "ab_marker_btn"):
            self.ab_marker_btn.setText(tr("⚑  Marcar evento"))
        try:
            if getattr(self, "_proto_run_t0", None) is not None:
                self._proto_parar(motivo="gravação encerrada")
        except Exception:
            pass
        # Snapshot final antes de fechar (capta o estado atual)
        try:
            if self.current_session_dir:
                self._save_snapshot(reason="fim")
        except Exception: pass
        if hasattr(self, "snapshot_timer") and self.snapshot_timer is not None:
            self.snapshot_timer.stop()
        self.is_recording = False
        if self.log_file:
            try:
                self.log_file.write(
                    f"\n=== Sessão finalizada em {datetime.now().isoformat()} ===\n"
                    f"Total de amostras gravadas: {self.samples_total}\n"
                    f"Total de marcadores: {len(self.markers)}\n"
                    f"Snapshots capturados: {self._snapshot_counter}\n")
            except Exception: pass
        self._close_record_files()
        self.record_btn.setText(tr("●  Iniciar Gravação"))
        self.record_btn.setStyleSheet("")
        self._pinta_rec(False)
        self._log(f"Gravação finalizada — pasta: {self.session_name}")
        self._update_status_state()
        self._update_window_title()
        self._audit_event("recording_stop",
                          samples=self.samples_total,
                          markers=len(self.markers),
                          dropped=self._dropped_count,
                          dt_mean_ms=round(self._dt_mean, 3),
                          dt_jitter_ms=round(self._dt_jitter, 3))
        # Fecha events.csv
        self.events_logger.stop()
        # Registra execução no progress.json do voluntário ativo
        if hasattr(self, "volunteers") and self.volunteers.current():
            try:
                self.volunteers.add_execution(
                    self.session_name, self.samples_total, len(self.markers))
                if hasattr(self, "_volunteer_show_history"):
                    self._volunteer_show_history()
                # a coluna Gravações ficava em 0 até "Atualizar lista" (G35)
                if hasattr(self, "vol_table"):
                    self._volunteer_refresh_table()
            except Exception as exc:
                self._log(f"Falha atualizando progresso do voluntário: {exc}",
                          error=True)
        # SHA-256 + nonce (prova de integridade — validação clínica)
        self._sign_session_files()
        # A sessão já aparece na tabela do Offline, sem diálogo. Só a linha
        # nova (nada de varrer o acervo) e nunca com o programa fechando.
        try:
            if (hasattr(self, "offline_table")
                    and not getattr(self, "_closing", False)):
                self._offline_inserir_sessao(self._ultima_sessao_parada[0])
        except Exception as exc:
            self._log(f"Falha ao atualizar a lista do Offline: {exc}", error=True)
        self._sync_action_bar()

    def _show_cpp_core_status(self):
        """Status + auto-teste da ponte Python↔C++ (núcleo ob_core, ARQ-01/02)."""
        import importlib, time as _t
        info = []
        try:
            if SCRIPT_DIR not in sys.path:
                sys.path.insert(0, SCRIPT_DIR)
            ob = importlib.import_module("ob_core.ob_bridge")
            dev = ob.OBCore(board_id=0, n_channels=8, srate=250.0).start()
            backend = dev.backend
            _t.sleep(0.4)
            x = dev.read()
            drp = dev.dropped()
            dev.stop(); dev.close()
            info.append(tr("Backend ativo: <b>{0}</b>").format(backend))
            info.append(tr("Biblioteca C++: {0}").format(
                tr("<b>ob_core.dll/.so encontrada</b>") if backend == "c++" else
                tr("não compilada — usando <b>fallback Python</b> (mesma API)")))
            info.append(tr("Auto-teste (device sintético, 0,4 s): leu <b>{0}</b> frames × {1} canais "
                           "@250 Hz.").format(x.shape[0], x.shape[1] if x.ndim == 2 else 0))
            info.append(tr("Amostras perdidas (backpressure): {0}").format(drp))
        except Exception as exc:
            info.append(tr("Ponte indisponível: {0}").format(exc))
        dim = COLORS.get("text_dim", "#777")
        html = (
            tr("<h3>Núcleo de aquisição C++ (ob_core)</h3>"
            "<p>Ponte <b>Python↔C++</b> (estilo BrainFlow) que <b>desacopla o "
            "data-path do Python</b>: ring buffer <b>lock-free</b>, thread de "
            "aquisição própria e clock monotônico. É <b>agnóstico de placa</b> — a "
            "placa (Cyton, iCelera, sua própria) é apenas um <i>Device</i> "
            "plugável, não uma dependência.</p>")
            + "<ul><li>" + "</li><li>".join(info) + "</li></ul>"
            + "<p style='color:%s'>" % dim
            + tr("Para compilar o núcleo C++: pasta "
            "<code>ob_core/</code> → <code>build.bat</code> (Windows/MSVC) ou "
            "<code>build.sh</code> (Linux/mac). Sem ele, o app usa o fallback "
            "Python. O <b>driver da placa real</b> entra em <code>ob_core.cpp</code> "
            "(função <code>produce_serial</code>) quando houver hardware para testar; "
            "até lá, use o <b>modo push</b> (a leitura em Python alimenta o ring C++).")
            + "</p>")
        dlg = QtWidgets.QDialog(self)
        dlg.setWindowTitle(tr("Núcleo de aquisição C++"))
        dlg.setMinimumSize(580, 400)
        v = QtWidgets.QVBoxLayout(dlg)
        tb = QtWidgets.QTextBrowser(); tb.setHtml(html); v.addWidget(tb, 1)
        bb = QtWidgets.QDialogButtonBox(
            QtWidgets.QDialogButtonBox.StandardButton.Close)
        traduz_botao_fechar(bb)
        bb.rejected.connect(dlg.reject); bb.accepted.connect(dlg.accept)
        v.addWidget(bb)
        try: dlg.setStyleSheet(build_stylesheet(COLORS))
        except Exception: pass
        dlg.exec()

    def _gather_provenance(self):
        """Metadados de REPRODUTIBILIDADE (Regras de Ouro G-01/G-02/G-06): seed,
        versões de pacotes, receita de DSP com FASE causal declarada e hash dos
        parâmetros — o registro fica re-executável e auditável."""
        import platform
        def _ver(mod):
            """Devolve a versão de um pacote instalado, ou '?' quando ele não pode
            ser importado."""
            try: return __import__(mod).__version__
            except Exception: return "?"
        f = self.filters
        dsp = {
            "reref_mode": getattr(f, "reref_mode", "none"),
            "notch": {"on": bool(f.notch_enabled), "freq_hz": f.notch_freq,
                      "type": "iirnotch", "Q": 30, "phase": "causal"},
            "bandpass": {"on": bool(f.bandpass_enabled), "low_hz": f.bp_low,
                         "high_hz": f.bp_high, "type": "butter", "order": 4,
                         "output": "sos", "phase": "causal"},
            "phase_note": "Online = CAUSAL (sosfilt com estado zi persistido). "
                          "Análises offline usam fase-zero (sosfiltfilt) e NÃO "
                          "devem ser re-aplicadas a um stream ao vivo.",
        }
        prov = {
            "raw_is_filtered": bool(f.notch_enabled or f.bandpass_enabled),
            "seed": 42,
            "packages": {"python": platform.python_version(),
                         "numpy": _ver("numpy"), "scipy": _ver("scipy"),
                         "PySide6": _ver("PySide6"), "app": APP_VERSION},
            "os": platform.platform(),
            "dsp": dsp,
        }
        try:
            prov["params_sha256"] = hashlib.sha256(
                json.dumps(dsp, sort_keys=True, ensure_ascii=False).encode("utf-8")
            ).hexdigest()
        except Exception:
            prov["params_sha256"] = None
        return prov

    def _canais_escolhidos_na_tela(self):
        """Canais escolhidos nos combos das abas Coração e Olhos, em base 0
        (None sem escolha ou sem a aba): gravados no summary.json como
        "report_channels" para o relatório PDF usar os mesmos da tela
        (validação com leigos, G09 e G10)."""
        def _dado(nome):
            cb = getattr(self, nome, None)
            if cb is None:
                return None
            try:
                v = cb.currentData()
            except Exception:
                return None
            return int(v) if isinstance(v, int) and v >= 0 else None
        out = {"ecg": _dado("ecg_channel_combo"),
               "eog_v": _dado("eog_v_combo"),
               "eog_h": _dado("eog_h_combo")}
        # sensibilidade das piscadas da aba Olhos: o PDF conta com o mesmo
        # critério da tela (chave nova; gravações antigas caem no detector
        # do módulo)
        spin = getattr(self, "eog_threshold_spin", None)
        if spin is not None:
            try:
                out["eog_threshold"] = float(spin.value())
            except Exception:
                pass
        return out

    def _gather_hardware(self):
        """Metadados OBRIGATÓRIOS de aquisição (Regra de Ouro G-04)."""
        cfg = self.config
        types = list(getattr(cfg, "channel_signal_types", []))[:self.num_channels]
        mus = list(getattr(cfg, "emg_channel_muscle", None) or [])
        # DE ONDE veio o sinal. Sem este campo, uma sessão do Modo Simulação
        # saía com o bloco de hardware completo (chip ADS1299, 24 bits, 4,5 V)
        # e assinada em SHA-256 — um arquivo sintético atestado como se tivesse
        # tocado um eletrodo. O único indício era o título da janela, que ainda
        # some durante a gravação.
        modo = "hardware"
        if self.serial_thread is not None:
            modo = getattr(self.serial_thread, "mode", "hardware")
        sintetico = modo in ("simulation", "playback")
        info = {
            "data_source": ("synthetic" if modo == "simulation"
                            else "replay" if modo == "playback" else "hardware"),
            "is_real_signal": not sintetico,
            "sample_rate_nominal_hz": SAMPLE_RATE,
            "num_channels": self.num_channels,
            "reference": {
                "reref_mode": getattr(self.filters, "reref_mode", "none"),
                "note": "Referência física definida pela montagem (SRB/BIAS do "
                        "amplificador); a re-referência de software é reversível.",
            },
            "channel_types": types,
            # músculo de cada canal de EMG (chave em português, como no
            # config; "" nos demais): o PDF rotula o canal de EMG por ele,
            # não pelo nome 10-20 do mapeamento padrão
            "channel_muscles": [
                (str(mus[i]) if (i < len(mus) and types[i] == "EMG"
                                 and mus[i] not in ("", "(não definido)")) else "")
                for i in range(len(types))],
            "power_line_hz": (self.filters.notch_freq
                              if self.filters.notch_enabled else None),
        }
        if sintetico:
            info["aviso"] = (
                "SINAL SINTÉTICO — gerado pelo próprio programa, nenhum "
                "eletrodo envolvido. Não use para conclusão sobre pessoa "
                "alguma.")
        else:
            # o bloco do amplificador só entra quando havia amplificador
            info["board"] = ("OpenBCI Cyton+Daisy"
                             if getattr(self, "daisy_enabled", False)
                             else "OpenBCI Cyton / compatível")
            info["adc"] = {"chip": "ADS1299", "bits": 24, "vref_v": 4.5}
        return info

    def _sign_session_files(self):
        """Calcula SHA-256 do data.csv + nonce + atualiza summary.json.
        Permite provar mais tarde que o arquivo não foi alterado."""
        if not self.current_session_dir: return
        csv_path  = os.path.join(self.current_session_dir, "data.csv")
        meta_path = os.path.join(self.current_session_dir, "summary.json")
        if not os.path.exists(csv_path): return
        try:
            h = hashlib.sha256()
            with open(csv_path, "rb") as f:
                for chunk in iter(lambda: f.read(1 << 20), b""):
                    h.update(chunk)
            digest = h.hexdigest()
            nonce  = secrets.token_hex(16)
            n_bytes = os.path.getsize(csv_path)
            integrity = {
                "data_csv_sha256": digest,
                "data_csv_bytes":  n_bytes,
                "nonce":           nonce,
                "signed_at":       datetime.now().isoformat(timespec="milliseconds"),
            }
            # Mescla com summary.json
            meta = {}
            if os.path.exists(meta_path):
                try:
                    with open(meta_path, "r", encoding="utf-8") as f:
                        meta = json.load(f)
                except Exception: pass
            meta["integrity"] = integrity
            # canais escolhidos na tela ao parar (podem ter mudado durante a
            # gravação); chave nova, o PDF lê daqui (G09/G10)
            meta["report_channels"] = self._canais_escolhidos_na_tela()
            # G-03/G-07: taxa efetiva medida (vs nominal) + amostras perdidas
            try:
                n_rows = 0
                with open(csv_path, "rb") as fr:
                    for _ in fr:
                        n_rows += 1
                n_samples = max(0, n_rows - 1)      # menos o header
                # A duração é a da GRAVAÇÃO, medida em relógio monotônico.
                # Antes vinha de session_start (definido na CONEXÃO) com
                # time.time(), e por isso o summary declarava 691 s para uma
                # sessão de 148 s — e derivava dali uma "taxa efetiva" de
                # 23,9 Hz, fisicamente impossível para EEG.
                # Duracao = VAO DO DADO (1a a ultima amostra), exatamente a
                # conta que o leitor offline faz. Medir do clique no RET ate o
                # stop incluia a criacao dos arquivos e o encerramento, e as
                # duas duracoes nunca batiam.
                dur_s = None
                span = getattr(self, "_rec_last_ts", None)
                if span and n_samples > 1:
                    dur_s = max(1e-6, float(span))
                elif getattr(self, "_rec_start_mono", None) is not None:
                    dur_s = max(1e-6, time.perf_counter() - self._rec_start_mono)
                # Perdas e amostras contadas DESTE trecho gravado, não desde a
                # conexão.
                perdidas = max(0, int(getattr(self, "_dropped_count", 0) or 0)
                               - int(getattr(self, "_rec_dropped_ini", 0)))
                # (n-1)/vao: um vao de N-1 intervalos, nao N — a mesma
                # formula do leitor offline.
                sr_ef = (round((n_samples - 1) / dur_s, 3)
                         if (dur_s and n_samples > 1) else None)
                meta["acquisition"] = {
                    "sample_rate_nominal_hz": SAMPLE_RATE,
                    "n_samples": n_samples,
                    "dropped_samples": perdidas,
                    "duration_s": round(dur_s, 3) if dur_s else None,
                    "sample_rate_effective_hz": sr_ef,
                    "clock_source": "monotonic (time.perf_counter), t=0 no REC",
                    # Deixa EXPLÍCITO quando o efetivo se afasta do nominal, em
                    # vez de o leitor ter de comparar dois campos e concluir
                    # sozinho que o arquivo está comprimido no tempo.
                    "sample_rate_ok": (bool(sr_ef and
                                            abs(sr_ef - SAMPLE_RATE)
                                            <= 0.05 * SAMPLE_RATE)
                                       if sr_ef else None),
                    "aviso": ((f"taxa efetiva {sr_ef} Hz difere do nominal "
                               f"{SAMPLE_RATE} Hz em mais de 5% — o eixo de "
                               f"tempo deste arquivo NÃO é o nominal")
                              if (sr_ef and abs(sr_ef - SAMPLE_RATE)
                                  > 0.05 * SAMPLE_RATE) else None),
                }
            except Exception:
                pass
            with open(meta_path, "w", encoding="utf-8") as f:
                json.dump(meta, f, ensure_ascii=False, indent=2)
            # Tambem grava em arquivo proprio para conveniência
            sig_path = os.path.join(self.current_session_dir, "data.csv.sha256")
            with open(sig_path, "w", encoding="utf-8") as f:
                f.write(f"{digest}  data.csv\n")
                f.write(f"# nonce: {nonce}\n")
                f.write(f"# bytes: {n_bytes}\n")
                f.write(f"# signed_at: {integrity['signed_at']}\n")
            self._log(f"✓ Integridade: SHA-256 {digest[:16]}... salvo em summary.json")
            self._audit_event("session_signed",
                              sha256=digest, nonce=nonce, bytes=n_bytes)
        except Exception as exc:
            self._log(f"Falha ao assinar sessão: {exc}", error=True)

    # ==================================================================
    # Snapshot — salva PNGs do estado atual de cada visualização
    # ==================================================================
    def _save_snapshot(self, reason="manual"):
        """Salva imagens das visualizações na pasta da sessão atual."""
        if not self.current_session_dir:
            return
        snap_dir = os.path.join(self.current_session_dir, "snapshots")
        # A pasta nunca era criada aqui: se ela não existisse, todo save()
        # falhava e o log ainda anunciava "salvo em snapshots/".
        try:
            os.makedirs(snap_dir, exist_ok=True)
        except Exception as exc:
            self._log(f"Snapshot #{self._snapshot_counter + 1}: não deu para criar "
                      f"snapshots/ ({exc})", error=True)
            return
        ts = datetime.now().strftime("%H-%M-%S")
        self._snapshot_counter += 1
        idx = self._snapshot_counter
        falhas = []

        def _save(widget, name):
            """Captura um widget como PNG dentro da pasta snapshots/ da sessão.

            Devolve True (gravou), False (falhou, e o motivo fica em `falhas`)
            ou None quando o painel não está montado na tela e não há o que
            capturar. Uma captura que não sai não interrompe a sequência, mas
            também não é mais dada como gravada. O nome do arquivo segue o
            padrão <índice 4 dígitos>_<HH-MM-SS>_<nome>.png.
            """
            try:
                pm = widget.grab()
                if pm.isNull():
                    # Painel escondido pelo modo do exame ou em aba nunca
                    # montada: sai da conta em silêncio, não é erro.
                    return None
                if not pm.save(os.path.join(snap_dir, f"{idx:04d}_{ts}_{name}.png"), "PNG"):
                    falhas.append(f"{name} (gravação recusada)")
                    return False
                return True
            except Exception as exc:
                falhas.append(f"{name} ({exc})")
                return False

        # Captura cada visualização principal
        alvos = []
        if hasattr(self, "channels_layout"): alvos.append((self.channels_layout, "tempo_real"))
        if hasattr(self, "fft_plot"):        alvos.append((self.fft_plot,        "fft"))
        if hasattr(self, "band_plot"):       alvos.append((self.band_plot,       "bandas"))
        if hasattr(self, "stats_table"):     alvos.append((self.stats_table,     "estatísticas"))
        if hasattr(self, "head_plot"):       alvos.append((self.head_plot,       "head_plot"))
        if hasattr(self, "spec_widget"):     alvos.append((self.spec_widget,     "espectrograma"))
        if hasattr(self, "history_plot"):    alvos.append((self.history_plot,    "histórico"))
        if hasattr(self, "accel_plot"):      alvos.append((self.accel_plot,      "acelerômetro"))
        resultados = [_save(w, nome) for w, nome in alvos]
        tentadas = [r for r in resultados if r is not None]
        ok = sum(1 for r in tentadas if r)
        self._log(f"Snapshot #{idx} ({reason}): {ok}/{len(tentadas)} imagens em snapshots/")
        if falhas:
            self._log(f"Snapshot #{idx}: falharam {', '.join(falhas)}", error=True)

    def _preaquece_analises(self):
        """Abre e fecha uma vez a aba Analisar → Análises só para o Qt dar aos
        gráficos o tamanho real.

        Os PNG de FFT, bandas e estatísticas do snapshot saíam no tamanho de
        construção (264x197 e 580x80) enquanto a aba nunca tivesse sido aberta
        — e no nível Simples ela fica oculta, então saíam cortados a sessão
        inteira. Como a troca acontece com updates desligados e volta no mesmo
        ciclo, nada pisca na tela. Precisa de singleShot(0): antes do show() a
        janela ainda não tem geometria e o pré-aquecimento não serviria de
        nada.
        """
        tabs = getattr(self, "_main_tabs", None)
        sub = getattr(self, "_sub_tabs", {}).get("analyse")
        if tabs is None or sub is None:
            return
        central = None
        try:
            central = self.centralWidget()
        except Exception:
            central = None
        top0, sub0 = tabs.currentIndex(), sub.currentIndex()
        try:
            if central is not None:
                central.setUpdatesEnabled(False)
            tabs.setCurrentWidget(sub)   # grupo Analisar
            sub.setCurrentIndex(max(0, self._pos_aba("analyse", 0)))   # Análises
            QtWidgets.QApplication.processEvents()
        except Exception:
            pass
        finally:
            try:
                sub.setCurrentIndex(sub0)
                tabs.setCurrentIndex(top0)
            except Exception:
                pass
            if central is not None:
                try: central.setUpdatesEnabled(True)
                except Exception: pass

    def _close_record_files(self):
        """Fecha o data.csv e o session.log.txt e zera as referências de gravação.

        Não fecha o events.csv — quem faz isso é events_logger.stop(), chamado
        em _stop_recording.
        """
        if self.csv_file:
            try: self.csv_file.close()
            except: pass
        if self.log_file:
            try: self.log_file.close()
            except: pass
        self.csv_file = self.csv_writer = self.log_file = None

    # ==================================================================
    # UDP
    # ==================================================================
    def _toggle_udp(self, checked):
        """Liga e desliga o streaming UDP das amostras, lendo host e porta dos
        campos da aba.

        Se start() falhar, o botão é desmarcado programaticamente para o estado
        visual não mentir. Host vazio cai para 127.0.0.1.
        """
        if checked:
            self.udp.host = self.udp_host_edit.text().strip() or "127.0.0.1"
            self.udp.port = self.udp_port_spin.value()
            ok = self.udp.start()
            if ok:
                self.udp_toggle_btn.setText(tr("Parar streaming"))
                self._log(f"UDP streaming ON → {self.udp.host}:{self.udp.port}")
            else:
                self.udp_toggle_btn.setChecked(False)
                self._log("Falha ao iniciar UDP", error=True)
        else:
            self.udp.stop()
            self.udp_toggle_btn.setText(tr("Iniciar streaming"))
            self._log("UDP streaming OFF")

    # ==================================================================
    # LSL Receiver — assinar streams externos (markers de PsychoPy/OpenViBE)
    # ==================================================================
    def _lslr_resolve(self):
        """Procura streams LSL na rede e popula combo."""
        if not HAS_LSL:
            return
        try:
            import pylsl  # lazy
            streams = pylsl.resolve_streams(wait_time=2.0)
        except Exception as exc:
            self.lslr_status_lbl.setText(tr("Falha: {0}").format(exc))
            self.lslr_status_lbl.setStyleSheet(f"color: {COLORS['error']};")
            return
        self._lslr_streams_found = streams
        self.lslr_streams_combo.clear()
        if not streams:
            self.lslr_streams_combo.addItem(tr("(nenhum stream encontrado)"), -1)
            self.lslr_status_lbl.setText(
                tr("Nenhum stream LSL ativo. Verifique se o app emissor "
                "(PsychoPy/OpenViBE/etc.) está rodando."))
            self.lslr_status_lbl.setStyleSheet(f"color: {COLORS['warning']};")
            return
        for i, s in enumerate(streams):
            name = s.name() or "?"
            stype = s.type() or "?"
            srate = s.nominal_srate()
            self.lslr_streams_combo.addItem(
                f"{name} · {stype} · {srate:.0f} Hz", i
            )
        self.lslr_status_lbl.setText(
            tr("{0} stream(s) encontrado(s). Selecione um e clique 'Assinar'.").format(len(streams)))
        self.lslr_status_lbl.setStyleSheet(f"color: {SIGNAL_TYPE_COLORS['EEG']};")
        self._log(f"LSL: {len(streams)} stream(s) descoberto(s)")

    def _lslr_toggle_subscribe(self, checked):
        """Assina/cancela assinatura do stream selecionado."""
        if not HAS_LSL:
            return
        if not checked:
            # Cancela assinatura
            if self._lslr_timer:
                self._lslr_timer.stop()
                self._lslr_timer = None
            if self._lslr_inlet:
                try: self._lslr_inlet.close_stream()
                except Exception: pass
                self._lslr_inlet = None
            self.lslr_subscribe_btn.setText(tr("Assinar (markers)"))
            self.lslr_status_lbl.setText(tr("Assinatura cancelada."))
            self.lslr_status_lbl.setStyleSheet(f"color: {COLORS['text_dim']};")
            return
        # Assina
        idx = self.lslr_streams_combo.currentData()
        if idx is None or idx < 0 or idx >= len(self._lslr_streams_found):
            self.lslr_subscribe_btn.setChecked(False)
            QtWidgets.QMessageBox.information(
                self, tr("Sem stream"),
                tr("Selecione um stream da lista primeiro (clique 'Procurar streams LSL')."))
            return
        try:
            import pylsl  # lazy
            self._lslr_inlet = pylsl.StreamInlet(self._lslr_streams_found[idx])
            self.lslr_subscribe_btn.setText(tr("Cancelar assinatura"))
            self.lslr_status_lbl.setText(
                tr("Assinado: {0}. Markers serão injetados na sessão automaticamente.").format(self.lslr_streams_combo.currentText())
            )
            self.lslr_status_lbl.setStyleSheet(
                f"color: {SIGNAL_TYPE_COLORS['EEG']}; font-weight: bold;")
            # Timer de pull
            self._lslr_timer = QTimer(self)
            self._lslr_timer.timeout.connect(self._lslr_pull)
            self._lslr_timer.start(50)  # 20 Hz
            self._audit_event("lsl_receiver_subscribed",
                              stream=self.lslr_streams_combo.currentText())
        except Exception as exc:
            self.lslr_subscribe_btn.setChecked(False)
            self.lslr_status_lbl.setText(tr("Falha ao assinar: {0}").format(exc))
            self.lslr_status_lbl.setStyleSheet(f"color: {COLORS['error']};")

    def _lslr_pull(self):
        """Busca novas amostras do stream LSL e injeta como markers."""
        if not self._lslr_inlet: return
        try:
            sample, ts = self._lslr_inlet.pull_sample(timeout=0.0)
            if sample is not None:
                # Cada sample pode ter múltiplos canais — concatena como label
                lbl = str(sample[0]) if len(sample) == 1 else "|".join(str(v) for v in sample)
                self.pending_marker = f"LSL:{lbl}"
                self._log(f"LSL marker recebido: {lbl}")
        except Exception:
            pass

    def _toggle_lsl(self, checked):
        """Liga e desliga a publicação do stream LSL de saída com os canais
        ativos.

        Publica num_channels canais a SAMPLE_RATE Hz usando os rótulos do
        mapeamento; nome vazio vira 'EEG_Data_Collector'. Não confundir com o
        receptor LSL (métodos _lslr_*), que assina streams externos em vez de
        publicar.
        """
        if checked:
            self.lsl.stream_name = self.lsl_name_edit.text().strip() or "EEG_Data_Collector"
            ch_labels = self.config.channel_mapping[:self.num_channels]
            ok = self.lsl.start(num_channels=self.num_channels,
                                 sample_rate=SAMPLE_RATE,
                                 ch_labels=ch_labels)
            if ok:
                self.lsl_toggle_btn.setText(tr("Parar LSL"))
                self._log(f"LSL ON → stream '{self.lsl.stream_name}' "
                          f"({self.num_channels}ch @ {SAMPLE_RATE} Hz)")
                self._audit_event("lsl_start", stream=self.lsl.stream_name)
            else:
                self.lsl_toggle_btn.setChecked(False)
                self._log("Falha ao iniciar LSL", error=True)
        else:
            self.lsl.stop()
            self.lsl_toggle_btn.setText(tr("Iniciar LSL"))
            self._log("LSL OFF")
            self._audit_event("lsl_stop")

    # ==================================================================
    # Hardware
    # ==================================================================
    def _send_hardware_command(self):
        """Envia à placa o comando digitado na caixa de texto livre da aba
        Hardware."""
        cmd = self.hw_cmd_edit.text().strip()
        if not cmd: return
        self._send_quick_command(cmd)

    def _send_quick_command(self, cmd):
        """Envia um comando pela serial, recusando e logando quando não há conexão
        ativa em modo Hardware."""
        if self.serial_thread and self.serial_thread.isRunning() and self.serial_thread.mode == "hardware":
            ok = self.serial_thread.send_command(cmd)
            if ok: self._log(f"[HW] Enviado: {cmd!r}")
            else:  self._log(f"[HW] Falha ao enviar: {cmd!r}", error=True)
        else:
            self._log("[HW] Não conectado em modo Hardware — comando ignorado", error=True)

    def _apply_hardware_settings_all(self):
        """Percorre todos os canais e envia à placa o comando de configuração
        montado a partir dos combos da aba Hardware.

        Dispara os comandos em sequência, sem esperar confirmação da placa
        entre um e outro.
        """
        if not (self.serial_thread and self.serial_thread.isRunning()
                and self.serial_thread.mode == "hardware"):
            self._log("[HW] Conecte em modo Hardware antes de aplicar", error=True); return
        for ch in range(self.num_channels):
            cmd = self._build_channel_command(ch)
            self.serial_thread.send_command(cmd)
            self._log(f"[HW] CH{ch+1} → {cmd}")

    def _build_channel_command(self, ch):
        # Cyton CH1-8 usa digitos "1".."8";
        # Módulo expansão CH9-16 usa codigos "Q"/"W"/"E"/"R"/"T"/"Y"/"U"/"I"
        """Monta a string de configuração de um canal no formato
        x<canal><power><gain><input><bias><srb2><srb1>X do protocolo OpenBCI.

        Canais 9 a 16 usam as letras de 'QWERTYUI' no lugar do dígito; a partir
        do índice 16 essa indexação estoura, então o método não cobre placas de
        mais de 16 canais.
        """
        if ch < 8:
            ch_code = str(ch + 1)
        else:
            ch_code = "QWERTYUI"[ch - 8]
        pwr  = self.hw_power[ch].currentData()
        gain = self.hw_gain[ch].currentData()
        inp  = self.hw_input[ch].currentData()
        bias = self.hw_bias[ch].currentData()
        srb2 = self.hw_srb2[ch].currentData()
        srb1 = self.hw_srb1[ch].currentData()
        return f"x{ch_code}{pwr}{gain}{inp}{bias}{srb2}{srb1}X"

    # ==================================================================
    # Log + close
    # ==================================================================
    def _log(self, msg, error=False):
        """Escreve uma linha com hora no painel de log da interface e, quando há
        gravação, também no session.log.txt.

        A mensagem é inserida como HTML no QTextEdit: caracteres como '<' e '&'
        vindos de exceções podem ser interpretados como marcação e sumir da
        tela.
        """
        ts = datetime.now().strftime("%H:%M:%S")
        color = COLORS["error"] if error else COLORS["accent"]
        self.log_view.append(
            f'<span style="color:{COLORS["text_dim"]}">[{ts}]</span> '
            f'<span style="color:{color}">{msg}</span>')
        if self.log_file:
            try:
                self.log_file.write(f"[{ts}] {msg}\n"); self.log_file.flush()
            except Exception: pass

