    def _pos_aba(self, key, i):
        # posição ATUAL da sub-aba de índice canônico i (ordem de _build_ui);
        # -1 se não existe. No Avançado o usuário pode ter arrastado as abas.
        sub = getattr(self, "_sub_tabs", {}).get(key)
        if sub is None:
            return -1
        pags = getattr(self, "_paginas_sub", {}).get(key)
        if not pags:
            return i if 0 <= i < sub.count() else -1
        if i < 0 or i >= len(pags):
            return -1
        return sub.indexOf(pags[i])

    def _ir_para_aba(self, top_idx, key, sub_idx):
        """Vai ao grupo `top_idx` e à sub-aba `sub_idx` de `key`; se ela estiver
        oculta (modo do exame ou nível Simples), cai na primeira visível. O Qt
        deixa tornar corrente uma aba oculta — a página apareceria sem aba."""
        if not hasattr(self, "_main_tabs"):
            return
        try:
            self._main_tabs.setCurrentIndex(top_idx)
            sub = getattr(self, "_sub_tabs", {}).get(key)
            if not sub:
                return
            pos = self._pos_aba(key, sub_idx)
            if 0 <= pos < sub.count() and sub.isTabVisible(pos):
                sub.setCurrentIndex(pos)
                return
            for i in range(sub.count()):
                if sub.isTabVisible(i):
                    sub.setCurrentIndex(i)
                    break
        except Exception:
            pass

    def _aba_esta_visivel(self, grupo, indice):
        """A sub-aba de índice `índice` do grupo `grupo` está em primeiro plano?

        Serve para os timers pesados não calcularem nada quando o usuário não
        está olhando — inclusive quando a aba foi ocultada pelo modo escolhido.

        A comparação é por ÍNDICE, não pelo texto: os rótulos são traduzidos
        (Conectividade/Connectivity/Conectividad) e comparar texto deixaria a
        guarda sempre falsa fora do português.
        """
        try:
            sub = getattr(self, "_sub_tabs", {}).get(grupo)
            if sub is None:
                return True                      # sem informação: não bloqueia
            idx_grupo = {"setup": 0, "view": 1, "analyse": 2, "system": 3}.get(grupo)
            if (idx_grupo is not None and hasattr(self, "_main_tabs")
                    and self._main_tabs.currentIndex() != idx_grupo):
                return False
            i = sub.currentIndex()
            return i == self._pos_aba(grupo, indice) and sub.isTabVisible(i)
        except Exception:
            return True

    # Índices das sub-abas (espelham a ordem de criação em _build_ui)
    ABA_CONECTIVIDADE = 3      # Analisar → Conectividade
    ABA_LAYOUT_CUSTOM = 5      # Visualizar → Layout Custom

    def _criar_atalho_desktop(self):
        """Cria/refaz o atalho na Área de Trabalho (botão em Configurações)."""
        ok, info = criar_atalho_area_de_trabalho()
        if ok:
            QtWidgets.QMessageBox.information(
                self, tr("Atalho criado"),
                tr("Atalho criado na Área de Trabalho:\n{0}").format(info))
            self._log(f"Atalho criado: {info}")
        else:
            QtWidgets.QMessageBox.warning(
                self, tr("Atalho"),
                tr("Não consegui criar o atalho:\n{0}").format(info))
            self._log(f"Falha criando atalho: {info}", error=True)

    def _apply_signal_mode_visibility(self, acq_type):
        """Mostra/oculta sub-abas conforme o tipo de aquisição.

        Para modos não-EEG, esconde abas que dependem do sistema 10-20
        (Topografia, ERP, ERS/ERD, Conectividade, Focus/SSVEP).
        Para EEG puro, esconde Bio Multimodal e EMG Joystick.
        Para Híbrido, tudo visível.
        """
        if not hasattr(self, "_sub_tabs"):
            return
        # O modo é ESTADO: fica guardado, é exibido no cabeçalho e persiste
        # entre sessões (antes ele se perdia no instante seguinte ao clique).
        self._signal_mode = acq_type
        try:
            self.config.acquisition_mode = acq_type
            self.config.save()
        except Exception:
            pass
        self._update_mode_badge(acq_type)

        # Títulos canônicos (em pt-BR) por índice — espelha _build_ui
        title_map = {
            "setup":   ["Voluntários", "Conexão", "Filtros e Canais",
                        "Hardware", "Calibração"],
            "view":    ["Tempo Real", "Topografia", "Espectrograma",
                        "Bio (EMG/ECG/EoG)", "Histórico", "Layout Custom"],
            "analyse": ["Análises", "Offline", "ERP", "Conectividade",
                        "ERS/ERD", "Focus / SSVEP", "EMG Joystick",
                        "BCI Trainer (MI)", "Estudo por Paciente"],
            "system":  ["Rede e Eventos", "Configurações",
                        "Referências"],
            "bio":     ["EMG · Músculos", "ECG · Coração",
                        "EOG · Olhos", "Acel · Movimento"],
        }
        rules = self.MODE_TAB_VISIBILITY.get(acq_type)
        multimodal = rules is None
        if multimodal:
            # Multimodal — tudo visível (é a aba a mais, para interação entre
            # modalidades). Sem `return`: o nível Simples ainda corta por cima.
            rules = {k: set(title_map[k])
                     for k in ("setup", "view", "analyse", "system", "bio")}
        simples = self._nivel_simples()

        def _primeira_visivel(tabs):
            # Só troca quando a aba corrente ficou oculta — trocar de nível
            # com a janela aberta não pode arrancar o usuário da tela onde está.
            if tabs.isTabVisible(tabs.currentIndex()):
                return
            for i in range(tabs.count()):
                if tabs.isTabVisible(i):
                    tabs.setCurrentIndex(i)
                    break

        # Agora percorre os QUATRO grupos — antes só 'view' e 'analyse' eram
        # filtrados, e por isso Configurar/Sistema ficavam sempre à mostra.
        for key in ("setup", "view", "analyse", "system"):
            sub = self._sub_tabs.get(key)
            if not sub: continue
            allowed = rules.get(key)
            if simples:
                allowed = ((allowed if allowed is not None else set(title_map[key]))
                           & self.SIMPLE_TAB_VISIBILITY[key])
            if allowed is None:      # sem regra p/ este grupo => mantém tudo
                continue
            titles = title_map[key]
            n_vis = 0
            for i, t in enumerate(titles):
                pos = self._pos_aba(key, i)
                if pos < 0: continue
                vis = t in allowed
                sub.setTabVisible(pos, vis)
                n_vis += int(vis)
            # Não deixa o usuário em uma aba oculta (acontece ao mudar de modo
            # Híbrido para EEG, por ex)
            _primeira_visivel(sub)
            # Sobrou uma só sub-aba: a barra vira ruído — some (volta no Avançado)
            sub.tabBar().setVisible(n_vis > 1)
            # Barra ainda nunca mostrada (grupo não aberto) não refaz o layout
            # ao reexibir abas: EEG→EMG→EEG deixava "Análises" sob "Offline".
            # Reescrever um rótulo força o cálculo das posições.
            if sub.count():
                sub.tabBar().setTabText(0, sub.tabBar().tabText(0))

        # Bio sub-tabs internas
        if hasattr(self, "bio_tabs"):
            allowed_bio = rules.get("bio", set())
            if simples:
                allowed_bio = allowed_bio & self.SIMPLE_TAB_VISIBILITY["bio"]
            n_vis = 0
            for i, t in enumerate(title_map["bio"]):
                if i >= self.bio_tabs.count(): break
                vis = t in allowed_bio
                self.bio_tabs.setTabVisible(i, vis)
                n_vis += int(vis)
            _primeira_visivel(self.bio_tabs)
            # Com uma única modalidade não há o que escolher: some a barra de
            # abas interna e o operador perde um nível de aninhamento.
            self.bio_tabs.tabBar().setVisible(n_vis > 1)
            if self.bio_tabs.count():      # mesmo motivo das sub-abas acima
                self.bio_tabs.tabBar().setTabText(0, self.bio_tabs.tabBar().tabText(0))

        # Sistema → Configurações: no Simples só Tema e Cores + Sessão e Arquivos
        st = getattr(self, "settings_sub_tabs", None)
        if st is not None:
            titulos_cfg = ["Tema e Cores", "Mapeamento de Canais",
                           "Sessão e Arquivos", "Protocolo (tempos)",
                           "Caminhos e Auditoria"]
            n_vis = 0
            for i, t in enumerate(titulos_cfg):
                if i >= st.count(): break
                vis = (not simples) or (t in self.SIMPLE_SETTINGS_TABS)
                st.setTabVisible(i, vis)
                n_vis += int(vis)
            _primeira_visivel(st)
            st.tabBar().setVisible(n_vis > 1)

        if multimodal:
            # Restaura inclusive o rótulo original da aba Bio ("EOG" no
            # Simples, como o nome do exame "EOG · Olhos").
            self._set_bio_tab_title(tr("Bio (EMG/ECG/EOG)") if simples
                                    else tr("Bio (EMG/ECG/EoG)"))
            if hasattr(self, "bio_banner"):
                # o banner manda a Filtros e Canais, que some no Simples
                self.bio_banner.setVisible(not simples)
            if simples:
                self._log("Modo Multimodal (tela simples): Tempo Real + Bio.")
            else:
                self._log("Modo Multimodal: todas as abas visíveis "
                          "(para uso combinado de modalidades).")
            return

        # A aba deixa de anunciar as três modalidades quando só uma está ativa
        self._set_bio_tab_title(self.MODE_BIO_TAB_TITLE.get(
            acq_type, "Bio (EMG/ECG/EoG)"))
        if hasattr(self, "bio_banner"):
            self.bio_banner.setVisible(False)

        # uma linha por troca: na abertura o mesmo modo era aplicado duas vezes
        if getattr(self, "_ult_modo_logado", None) != acq_type:
            self._ult_modo_logado = acq_type
            self._log(f"Modo de aquisição aplicado: {acq_type} — "
                      f"a interface agora mostra apenas o que pertence a {acq_type}.")

    def _set_bio_tab_title(self, titulo):
        """Renomeia a aba Bio conforme o modo (em modo único ela vira só
        'Músculos'/'Coração'/'Olhos')."""
        sub = getattr(self, "_sub_tabs", {}).get("view")
        if not sub: return
        for i in range(sub.count()):
            t = sub.tabText(i)
            if t.startswith("Bio") or t in ("Músculos", "Coração", "Olhos"):
                sub.setTabText(i, titulo); return

    def _nome_modalidade(self, code=None):
        """Rótulo de tela da modalidade (o mesmo do badge do cabeçalho). Sem
        `code`, usa o modo em vigor."""
        nomes = {"EEG": "EEG · Cérebro", "EMG": "EMG · Músculos",
                 "ECG": "ECG · Coração", "EoG": "EOG · Olhos",
                 "Hibrido": "Multimodal"}
        if not code:
            code = (getattr(self, "_signal_mode", None)
                    or getattr(self.config, "acquisition_mode", "EEG"))
        return tr(nomes.get(code, code))

    def _update_mode_badge(self, acq_type):
        """Mostra o modo ativo no cabeçalho — âncora de contexto que não existia."""
        # passa por aqui em toda troca de exame, de nível e de tema
        self._atualiza_aviso_multimodal()
        lbl = getattr(self, "mode_badge_label", None)
        if lbl is None: return
        if self._nivel_simples():
            # Contorno neutro (o azul cheio competia com a ação) e o ▾ que diz
            # que ali se troca o exame; montado aqui, com teto e elisão.
            P = paleta_simples(COLORS)
            lbl.setStyleSheet(self._estilo_selo(P["texto"], P["borda"]))
            lbl.ensurePolished()
            teto = self._teto_selo(260, 200)
            folga = 2 * _dens(14, 10) + 8
            texto = self._nome_modalidade(acq_type) + "  ▾"
            fm = lbl.fontMetrics()
            texto = fm.elidedText(texto, QtCore.Qt.TextElideMode.ElideMiddle,
                                  teto - folga)
            self._emblema_cabecalho(lbl, texto)
            lbl.setMinimumWidth(min(teto, fm.horizontalAdvance(texto) + folga))
            lbl.setMaximumWidth(teto)
            lbl.setSizePolicy(lbl.sizePolicy().horizontalPolicy(),
                              QtWidgets.QSizePolicy.Policy.Fixed)
            self._arredonda_selo(lbl)
        else:
            lbl.setStyleSheet(
                f"color: {COLORS['background']}; background: {COLORS['accent']}; "
                f"font-weight: bold; padding: 4px 12px; border-radius: 3px;")
            lbl.setMaximumWidth(16777215)
            self._emblema_cabecalho(lbl, self._nome_modalidade(acq_type))
        lbl.setVisible(True)

    def _msg_sem_canal(self, tipo):
        """Aviso de "nenhum canal deste tipo" com o caminho que EXISTE no
        nível: no Simples a aba Filtros e Canais está escondida."""
        n = int(getattr(self, "num_channels", BASE_CHANNELS) or BASE_CHANNELS)
        if self._nivel_simples():
            if tipo == "EMG":
                return tr("Nenhum canal EMG entre os {0} canais em uso — clique "
                          "no distintivo da modalidade, no topo, e escolha o "
                          "exame de novo para marcá-los.").format(n)
            if tipo == "ECG":
                return tr("(Nenhum canal ECG — clique no distintivo da "
                          "modalidade, no topo, para marcá-lo)")
            return tr("(Nenhum canal de olhos — clique no distintivo da "
                      "modalidade, no topo, para marcá-los)")
        if tipo == "EMG":
            return tr("Nenhum canal EMG entre os {0} canais em uso — marque os "
                      "canais em Filtros e Canais.").format(n)
        if tipo == "ECG":
            return tr("(Nenhum canal ECG — configure em Filtros e Canais)")
        return tr("(Nenhum canal EoG — configure em Filtros e Canais)")

    def _refaz_avisos_sem_canal(self):
        """Reescreve os três avisos no texto do nível em vigor."""
        try:
            if hasattr(self, "emg_rows"):
                self._emg_refresh_channel_types()
            if hasattr(self, "ecg_channel_combo"):
                self._populate_ecg_channel_combo()
            if hasattr(self, "eog_h_combo"):
                self._populate_eog_channel_combos()
        except Exception:
            pass

    def _build_aviso_multimodal(self):
        """Faixa âmbar, só no Simples, quando o exame é Multimodal e todos os
        canais em uso estão marcados como EEG: a gravação sairia como um EEG
        comum sem ninguém perceber (validação com leigos, G11). O botão marca
        músculos, coração e olhos pela divisão de layout_multimodal."""
        w = QtWidgets.QWidget()
        w.setObjectName("avisoMultimodal")
        h = QtWidgets.QHBoxLayout(w)
        h.setContentsMargins(12, 8, 12, 8); h.setSpacing(12)
        self.multimodal_aviso_lbl = QtWidgets.QLabel("")
        self.multimodal_aviso_lbl.setWordWrap(True)
        h.addWidget(self.multimodal_aviso_lbl, stretch=1)
        self.multimodal_aviso_btn = QtWidgets.QPushButton(
            tr("Marcar músculos, coração e olhos"))
        self.multimodal_aviso_btn.clicked.connect(
            lambda _=False: self._oferecer_canais_do_exame("Hibrido"))
        h.addWidget(self.multimodal_aviso_btn)
        w.setVisible(False)
        self.multimodal_aviso = w
        return w

    def _multimodal_so_eeg(self):
        """Exame Multimodal com todos os canais em uso marcados como EEG (ou
        desligados)."""
        if getattr(self, "_signal_mode", None) != "Hibrido":
            return False
        n = int(getattr(self, "num_channels", BASE_CHANNELS) or BASE_CHANNELS)
        tipos = list(getattr(self.config, "channel_signal_types", None) or [])[:n]
        return bool(tipos) and all(t in ("EEG", "off") for t in tipos)

    def _atualiza_aviso_multimodal(self):
        """Mostra/esconde a faixa de _build_aviso_multimodal (só no Simples)."""
        w = getattr(self, "multimodal_aviso", None)
        if w is None:
            return
        mostrar = self._nivel_simples() and self._multimodal_so_eeg()
        if mostrar:
            n = int(getattr(self, "num_channels", BASE_CHANNELS) or BASE_CHANNELS)
            P = paleta_simples(COLORS)
            w.setStyleSheet(
                f"QWidget#avisoMultimodal {{ background-color: {P['aviso_fundo']}; "
                f"border: 1px solid {P['aviso_borda']}; border-radius: 8px; }}")
            self.multimodal_aviso_lbl.setStyleSheet(
                f"color: {P['aviso']}; font-weight: bold; background: transparent;")
            self.multimodal_aviso_lbl.setText(tr(
                "Exame Multimodal, mas os {0} canais em uso estão todos marcados "
                "como cérebro (EEG): a gravação vai sair só com EEG.").format(n))
            self.multimodal_aviso_btn.setToolTip(
                tr("Divide os canais assim: {0}.").format(descreve_layout_multimodal(n)))
        try:
            w.setVisible(mostrar)
        except RuntimeError:
            pass

    def _oferecer_canais_do_exame(self, code):
        """Escolher o exame não marcava canal nenhum: a aba do exame abria com
        "nenhum canal" e, no Simples, sem caminho para sair disso. Oferece
        marcar os canais ali mesmo."""
        n = int(getattr(self, "num_channels", BASE_CHANNELS) or BASE_CHANNELS)
        if code == "Hibrido":
            # Multimodal só com EEG: oferece a divisão por tipo (G11)
            if not self._multimodal_so_eeg():
                return
            r = QtWidgets.QMessageBox.question(
                self, tr("Marcar os canais do exame"),
                tr("Exame Multimodal, mas os {0} canais em uso estão todos "
                   "marcados como cérebro (EEG). Marcar agora assim: {1}?")
                .format(n, descreve_layout_multimodal(n)),
                QtWidgets.QMessageBox.StandardButton.Yes
                | QtWidgets.QMessageBox.StandardButton.No,
                QtWidgets.QMessageBox.StandardButton.Yes)
            if r != QtWidgets.QMessageBox.StandardButton.Yes:
                return
            tipos = layout_multimodal(n)
            combos = getattr(self, "channel_type_combos", None)
            for ch in range(n):
                # Direto no handler (grava e propaga) e o combo acompanha em
                # silêncio: pelo combo, um canal cujo combo já mostrava o tipo
                # não emitia sinal e continuava EEG no config.
                self._on_channel_signal_type_changed(ch, tipos[ch])
                if combos and ch < len(combos):
                    k = combos[ch].findData(tipos[ch])
                    if k >= 0 and combos[ch].currentIndex() != k:
                        combos[ch].blockSignals(True)
                        combos[ch].setCurrentIndex(k)
                        combos[ch].blockSignals(False)
            self._atualiza_aviso_multimodal()
            return
        if code not in ("EMG", "ECG", "EoG"):
            return
        if code in list(self.config.channel_signal_types)[:n]:
            return
        alvo = min(2, n) if code == "EoG" else n
        r = QtWidgets.QMessageBox.question(
            self, tr("Marcar os canais do exame"),
            tr("Nenhum dos {0} canais em uso está marcado como {1}. Marcar "
               "{2} canal(is) como {1} agora?").format(n, code, alvo),
            QtWidgets.QMessageBox.StandardButton.Yes
            | QtWidgets.QMessageBox.StandardButton.No,
            QtWidgets.QMessageBox.StandardButton.Yes)
        if r != QtWidgets.QMessageBox.StandardButton.Yes:
            return
        combos = getattr(self, "channel_type_combos", None)
        for ch in range(alvo):
            if combos and ch < len(combos):
                combos[ch].setCurrentText(code)   # o handler grava e propaga
            else:
                self._on_channel_signal_type_changed(ch, code)

    def _menu_trocar_modalidade(self):
        """Menu do badge de modalidade: troca o modo do exame sem passar por
        Filtros e Canais (que some no Simples). Seleciona no combo — o handler
        dele aplica tudo, e combo e badge ficam sincronizados."""
        combo = getattr(self, "mode_visibility_combo", None)
        if combo is None:
            return
        menu = QtWidgets.QMenu(self)
        # O ✓ segue o modo REAL da janela, não a posição do combo
        atual = combo.findData(getattr(self, "_signal_mode", None))
        if atual < 0:
            atual = combo.currentIndex()
        for i in range(combo.count()):
            ac = menu.addAction(combo.itemText(i) + ("   ✓" if i == atual else ""))
            ac.setData(i)
        escolha = menu.exec(QtGui.QCursor.pos())
        if escolha is None:
            return
        idx = int(escolha.data())
        code = combo.itemData(idx)
        if idx == atual:
            # escolher o mesmo exame de novo é o caminho do Simples para
            # marcar os canais que faltam
            self._oferecer_canais_do_exame(code)
            return
        if combo.currentIndex() == idx:
            # combo já estava nesse item (dessincronizado): não emite sinal
            self._on_mode_visibility_apply()
        else:
            combo.setCurrentIndex(idx)
        self._oferecer_canais_do_exame(code)

    # ==================================================================
    # Launcher integration — aplica a escolha vinda da LauncherScreen
    # ==================================================================
    def apply_launcher_choice(self, choice):
        """Aplica a escolha do usuário feita na tela inicial.

        choice dict:
            mode             -> 'live' | 'offline' | 'bci' | 'sim' | 'settings'
            port             -> 'COM3' ou None
            num_channels     -> 8..64 (passo de 8) escolhido no Pré-Flight
            expansion_16ch   -> bool (compatibilidade legada)
            acquisition_type -> 'EEG' | 'EMG' | 'ECG' | 'Hibrido'
            volunteer_dir    -> nome da pasta do voluntário ou None
            selected_csv     -> caminho de CSV a abrir no Offline (opcional)
        """
        if not choice:
            return
        self._pending_launcher_choice = choice
        # "Abrir uma gravação" no Simples: o aparelho já foi desligado ao voltar
        # ao início; a pílula vira "○ Vendo gravação" (neutra) e a dica diz
        # como gravar de novo, em vez de "■ DESCONECTADO" vermelho
        self._vendo_gravacao = (choice.get("mode") == "offline"
                                and self._nivel_simples())
        try:
            # 1) Porta COM
            port = choice.get("port")
            porta_ok = False
            if port and hasattr(self, "port_combo"):
                idx = self.port_combo.findData(port)
                if idx >= 0:
                    self.port_combo.setCurrentIndex(idx)
                    porta_ok = True

            # 2) Modo de aquisição (Hardware/Simulação/Playback)
            mode = choice.get("mode", "live")
            if hasattr(self, "mode_combo"):
                if mode == "sim":
                    self.mode_combo.setCurrentIndex(1)  # Simulação
                elif mode in ("live", "bci"):
                    self.mode_combo.setCurrentIndex(0)  # Hardware
                elif mode == "offline":
                    # Playback é o mais próximo; no Simples o combo está
                    # oculto e prenderia o ▶ Conectar num erro sem saída.
                    self.mode_combo.setCurrentIndex(
                        0 if self._nivel_simples() else 2)

            # 3) Número de canais escolhido no Pré-Flight (8..64). Usa
            #    _set_num_channels para sincronizar TUDO (head_plot, emg_widget,
            #    combos, label, abas multimodais). Antes fazia
            #    self.num_channels = MAX_CHANNELS (=64!) o que descasava os
            #    widgets e quebrava a visualização. O valor vem direto do combo
            #    do launcher; expansion_16ch fica como compatibilidade legada.
            n_ch = choice.get("num_channels")
            if isinstance(n_ch, int) and n_ch in EXPANSION_STEPS \
                    and hasattr(self, "_set_num_channels"):
                self._set_num_channels(n_ch)
            elif choice.get("expansion_16ch") and hasattr(self, "_set_num_channels"):
                self._set_num_channels(CYTON_MAX_CHANNELS)  # legado: 16 canais

            # 4) Tipo de aquisição -> channel_signal_types
            acq = choice.get("acquisition_type", "EEG")
            if acq == "EEG":
                self.config.channel_signal_types = ["EEG"] * MAX_CHANNELS
            elif acq == "EMG":
                self.config.channel_signal_types = ["EMG"] * MAX_CHANNELS
            elif acq == "ECG":
                self.config.channel_signal_types = ["ECG"] * MAX_CHANNELS
            elif acq == "EoG":
                # EoG usa 2 canais (horizontal + vertical); o resto fica off
                self.config.channel_signal_types = (
                    ["EoG"] * 2 + ["off"] * (MAX_CHANNELS - 2))
            elif acq == "Hibrido":
                # Divisão pelo número de canais em uso (layout_multimodal):
                # com 8 canais o layout de 16 deixava todos em EEG (G11).
                # Completa até MAX_CHANNELS (como o padrão do AppConfig): com
                # 16 itens o laço abaixo estourava o índice e a escolha
                # Multimodal da tela inicial não era aplicada.
                self.config.channel_signal_types = layout_multimodal(
                    getattr(self, "num_channels", BASE_CHANNELS))
            self.config.save()
            # Sincroniza combos da aba Filtros e Canais se já criados
            if hasattr(self, "channel_type_combos"):
                for ch, tc in enumerate(self.channel_type_combos):
                    if ch < len(self.config.channel_signal_types):
                        tc.blockSignals(True)
                        tc.setCurrentText(self.config.channel_signal_types[ch])
                        tc.blockSignals(False)
                # Atualiza filtro recomendado (label) e habilitação do threshold
                for ch in range(MAX_CHANNELS):
                    stype = self.config.channel_signal_types[ch]
                    if ch < len(self.channel_filter_hint_lbls):
                        preset = SIGNAL_FILTER_PRESETS.get(stype, SIGNAL_FILTER_PRESETS["EEG"])
                        self.channel_filter_hint_lbls[ch].setText(preset["label"])
                        self.channel_filter_hint_lbls[ch].setStyleSheet(
                            f"color: {SIGNAL_TYPE_COLORS.get(stype, COLORS['text_dim'])}; "
                            f"font-size: 9pt;")
                    if ch < len(self.channel_emg_thresh_inline):
                        self.channel_emg_thresh_inline[ch].setEnabled(stype == "EMG")
            # Reflete nas abas dependentes
            if hasattr(self, "emg_rows"):
                self._emg_refresh_channel_types()
            if hasattr(self, "ecg_channel_combo"):
                self._populate_ecg_channel_combo()
            if hasattr(self, "eog_h_combo"):
                self._populate_eog_channel_combos()
            if hasattr(self, "_joy_axes"):
                self._joy_repopulate_combos()
            # os nomes dos canais do Empilhado seguem o tipo do exame (G13):
            # os combos foram sincronizados com os sinais bloqueados
            if hasattr(self, "montage_plot"):
                self._refresh_montage_layout()

            # 5) Voluntário ativo (se houver)
            vol_dir = choice.get("volunteer_dir")
            if vol_dir and hasattr(self, "volunteers"):
                try:
                    # set_active nunca existiu: o paciente do launcher jamais
                    # ficava ativo. select_volunteer relê a ficha do disco (o
                    # launcher usa outro VolunteerRegistry, criado no main).
                    prof = self.volunteers.select_volunteer(vol_dir)
                    self._log(f"Voluntário ativo: {prof.get('vid')} — "
                              f"{prof.get('nome')}")
                    if hasattr(self, "_volunteer_refresh_table"):
                        self._volunteer_refresh_table()
                    if hasattr(self, "_volunteer_update_indicator"):
                        self._volunteer_update_indicator()
                except Exception as exc:
                    self._log(f"Não foi possível ativar o voluntário "
                              f"{vol_dir}: {exc}", error=True)
            elif (choice.get("volunteer_escolhido") and hasattr(self, "volunteers")
                    and self.volunteers.current()):
                # "(nenhum — selecione ou cadastre)" escolhido de propósito na
                # tela inicial: a janela continuava com o paciente anterior e
                # o próximo exame ia para a pasta dele sem avisar
                self.volunteers.clear_current()
                self._log("Tela inicial: exame sem paciente (o anterior foi "
                          "deixado de lado).")
                if hasattr(self, "_volunteer_update_indicator"):
                    self._volunteer_update_indicator()

            # 6) Visibilidade de abas conforme o tipo de aquisição
            #    (esconde Topografia/ERP/ERS-ERD para EMG, ECG, EoG, etc.)
            #    O combo de Filtros e Canais acompanha: o menu do badge lê
            #    dele, e ficava em EEG com a janela em EMG.
            combo_modo = getattr(self, "mode_visibility_combo", None)
            if combo_modo is not None:
                i_modo = combo_modo.findData(acq)
                if i_modo >= 0:
                    combo_modo.blockSignals(True)
                    combo_modo.setCurrentIndex(i_modo)
                    combo_modo.blockSignals(False)
            self._apply_signal_mode_visibility(acq)

            # 7) Navega para a aba apropriada conforme o modo. No Simples,
            #    "Nova sessão" vai direto à tela do sinal da modalidade (a
            #    aba Conexão não tem nada para o leigo fazer).
            if mode == "live" and self._nivel_simples():
                self._goto_realtime_view()
            else:
                self._navigate_for_launcher_mode(mode, choice.get("selected_csv"))

            # 7b) Simples: a porta já foi resolvida na tela inicial, então
            #     conecta sozinho. singleShot para a janela já estar visível.
            #     No Avançado continua caindo em Conexão, sem conectar.
            if mode == "live" and port and self._nivel_simples():
                if porta_ok:
                    QtCore.QTimer.singleShot(400, self._connect)
                else:
                    # a porta sumiu entre a tela inicial e a janela
                    QtCore.QTimer.singleShot(400, lambda: self._erro_conexao(tr(
                        "Nenhuma porta foi encontrada. Ligue o equipamento "
                        "no USB e clique em Atualizar.")))

            # 8) Modo Simulação: inicia o streaming sintético automaticamente.
            #    Antes o usuário caía na aba Conexão sem nada acontecer e achava
            #    que "a simulação não funcionava". Agora a simulação já começa e
            #    a aba Tempo Real mostra o sinal imediatamente. Usa singleShot
            #    para garantir que a janela já esteja construída/visível.
            if mode == "sim":
                QtCore.QTimer.singleShot(400, self._autostart_simulation)

            if self._vendo_gravacao and hasattr(self, "status_label"):
                self._pinta_estado_conexao(False)
                self._dica_temporaria(
                    tr("Para gravar de novo, clique em ▶ Conectar."), ms=6000,
                    anexa=True)
            self._log(f"[Launcher] aplicado: mode={mode} acq={acq} "
                      f"port={port} canais={choice.get('num_channels') or '?'}")
        except Exception as exc:
            self._log(f"Erro aplicando choice do launcher: {exc}", error=True)

    def _navigate_for_launcher_mode(self, mode, csv_path=None):
        """Navega para a aba/sub-aba apropriada conforme o modo escolhido."""
        if not hasattr(self, "_main_tabs"): return
        # Mapas index conforme criação em _build_ui()
        nav_map = {
            "live":     (0, ("setup",   1)),   # Configurar → Conexão
            "sim":      (1, ("view",    0)),   # Visualizar → Tempo Real (sinal já visível)
            "offline":  (2, ("analyse", 1)),   # Analisar → Offline
            "bci":      (2, ("analyse", 5)),   # Analisar → Focus
            "settings": (3, ("system",  1)),   # Sistema → Configurações
        }
        target = nav_map.get(mode)
        if not target: return
        top_idx, (sub_key, sub_idx) = target
        # Se a sub-aba estiver oculta pelo modo/nível, cai na primeira visível
        self._ir_para_aba(top_idx, sub_key, sub_idx)
        # Carrega CSV no Offline se foi clicado em uma sessão recente
        if mode == "offline" and csv_path and hasattr(self, "_offline_load_csv"):
            try:
                self._offline_load_csv(csv_path)
            except Exception as exc:
                self._log(f"Falha ao carregar CSV {csv_path}: {exc}", error=True)

    def _goto_realtime_view(self):
        """Leva o usuário à tela onde o SINAL DA MODALIDADE aparece.

        Antes ia sempre para Tempo Real; quem escolhia EMG/ECG/EoG caía numa
        tela de EEG e tinha de descobrir sozinho o caminho até a sua medida.
        """
        if not hasattr(self, "_main_tabs"):
            return
        modo = getattr(self, "_signal_mode",
                       getattr(self.config, "acquisition_mode", "EEG"))
        try:
            self._main_tabs.setCurrentIndex(1)          # Visualizar
            view = self._sub_tabs.get("view")
            if not view: return
            if modo in ("EMG", "ECG", "EoG") and hasattr(self, "bio_tabs"):
                view.setCurrentIndex(self._pos_aba("view", 3))   # Bio (renomeada p/ o modo)
                alvo = {"EMG": 0, "ECG": 1, "EoG": 2}[modo]
                if alvo < self.bio_tabs.count():
                    self.bio_tabs.setCurrentIndex(alvo)
            else:
                view.setCurrentIndex(self._pos_aba("view", 0))   # Tempo Real (EEG/Multimodal)
        except Exception:
            pass

    def _autostart_simulation(self):
        """Inicia a simulação automaticamente (chamado pelo launcher).

        Garante que o combo de modo esteja em 'Simulação' e que ainda não
        haja uma thread rodando, então conecta. Idempotente: se já estiver
        conectado, apenas leva o usuário para a aba Tempo Real.
        """
        try:
            if hasattr(self, "mode_combo") and self.mode_combo.currentIndex() != 1:
                self.mode_combo.setCurrentIndex(1)      # Simulação
            already = bool(self.serial_thread and self.serial_thread.isRunning())
            if not already:
                self._connect()
            self._goto_realtime_view()
        except Exception as exc:
            self._log(f"Falha ao iniciar simulação automática: {exc}", error=True)

    def _setup_usability(self):
        """Configura: barra de status, menu Ajuda, atalhos de teclado.
        Chamada ao fim de __init__."""
        # ---- Barra de status (no rodapé) ----
        sb = self.statusBar()
        sb.setStyleSheet(
            f"QStatusBar {{ background-color: {COLORS['surface']}; "
            f"color: {COLORS['text_dim']}; "
            f"border-top: 1px solid {COLORS['border']}; }}")
        self.status_state_lbl = QtWidgets.QLabel(tr("Pronto."))
        self.status_state_lbl.setStyleSheet(
            f"color: {COLORS['text_dim']}; padding: 0 8px;")
        sb.addWidget(self.status_state_lbl, stretch=1)
        version_lbl = QtWidgets.QLabel(
            f"{APP_NAME} v{APP_VERSION}")
        version_lbl.setStyleSheet(
            f"color: {COLORS['text_dim']}; padding: 0 8px;")
        sb.addPermanentWidget(version_lbl)

        # ---- Menu Ajuda ----
        menubar = self.menuBar()
        menubar.setStyleSheet(
            f"QMenuBar {{ background-color: {COLORS['surface']}; "
            f"color: {COLORS['text']}; border-bottom: 1px solid {COLORS['border']}; }}"
            f"QMenuBar::item:selected {{ background-color: {COLORS['accent_dim']}; "
            f"color: {COLORS['background']}; }}"
            f"QMenu {{ background-color: {COLORS['surface_alt']}; "
            f"color: {COLORS['text']}; border: 1px solid {COLORS['border']}; }}"
            f"QMenu::item:selected {{ background-color: {COLORS['accent_dim']}; "
            f"color: {COLORS['background']}; }}")
        # Menu Arquivo: a tela do exame não tinha Sair nem volta ao início
        # (validação com leigos, G18)
        arquivo_menu = menubar.addMenu(tr("Arquivo"))
        self._arquivo_menu = arquivo_menu
        self._act_voltar_inicio = arquivo_menu.addAction(
            tr("Voltar ao início (trocar paciente ou exame)"))
        self._act_voltar_inicio.triggered.connect(
            lambda _=False: self._voltar_ao_inicio())
        arquivo_menu.addSeparator()
        act_sair = arquivo_menu.addAction(tr("Sair"))
        act_sair.setShortcut("Ctrl+Q")
        act_sair.triggered.connect(self.close)
        tools_menu = menubar.addMenu(tr("Ferramentas"))
        self._tools_menu_act = tools_menu.menuAction()   # some no Simples
        act_prof_exp = tools_menu.addAction(tr("Exportar perfil de protocolo..."))
        act_prof_exp.triggered.connect(self._export_protocol_profile)
        act_prof_imp = tools_menu.addAction(tr("Importar perfil de protocolo..."))
        act_prof_imp.triggered.connect(self._import_protocol_profile)
        tools_menu.addSeparator()
        act_maker = tools_menu.addAction(tr("Área Maker (receitas de análise)..."))
        act_maker.triggered.connect(self._open_recipe)
        act_logs = tools_menu.addAction(tr("Abrir pasta de logs"))
        act_logs.triggered.connect(self._open_logs_dir)
        act_core = tools_menu.addAction(tr("Núcleo de aquisição C++ (status/teste)..."))
        act_core.triggered.connect(self._show_cpp_core_status)
        help_menu = menubar.addMenu(tr("Ajuda"))
        # Manual em PDF: primeiro item, é o que o operador mais procura.
        act_manual = help_menu.addAction(tr("Manual do usuário (PDF)"))
        act_manual.triggered.connect(self._abrir_manual_usuario)
        act_manual.setEnabled(self._caminho_manual_usuario() is not None)
        # Troca de nível: o texto diz para onde o clique leva, sem marca de
        # seleção. Antes o item era marcável e o texto alternava, e no modo
        # completo aparecia "✓ Modo simples (exame)" (validação com leigos, G29).
        self._act_modo_completo = help_menu.addAction(tr("Mudar para Completo (pesquisa)"))
        self._act_modo_completo.triggered.connect(
            lambda _=False: self._definir_nivel(
                "avancado" if self._nivel_simples() else "simples"))
        help_menu.addSeparator()
        act_help = help_menu.addAction(tr("Assistente de ajuda..."))
        act_help.setShortcut("F1")
        act_help.triggered.connect(self._show_help_assistant)
        help_menu.addSeparator()
        act_about = help_menu.addAction(tr("Sobre o aplicativo..."))
        act_about.triggered.connect(self._show_about_dialog)
        act_shortcuts = help_menu.addAction(tr("Atalhos de teclado"))
        act_shortcuts.triggered.connect(self._show_shortcuts_dialog)
        help_menu.addSeparator()
        act_docs = help_menu.addAction(tr("Pasta de configuração / sessões"))
        act_docs.triggered.connect(self._open_save_dir)
        self._act_docs = act_docs           # texto por nível (_aplicar_nomes_nivel)
        if self._nivel_simples():
            # o menu é montado depois de _aplicar_nomes_nivel: nasce certo
            act_docs.setText(tr("Pasta do programa / gravações"))
        act_terms = help_menu.addAction(tr("Termo de uso e privacidade..."))
        act_terms.triggered.connect(self._show_terms_dialog)
        help_menu.addSeparator()
        act_update = help_menu.addAction(tr("Verificar atualizações..."))
        act_update.triggered.connect(self._check_updates_manual)
        act_diag = help_menu.addAction(tr("Diagnóstico de erros (simular)..."))
        act_diag.triggered.connect(self._show_error_diagnostics)
        self._act_diag = act_diag                        # some no Simples
        # Os menus nascem depois de _build_ui (que já aplicou o nível): ajusta agora.
        self._aplicar_nivel_menus()

        # ---- Atalhos de teclado ----
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+R"), self,
                         activated=self._toggle_recording)
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+Shift+C"), self,
                         activated=self._toggle_connection)
        QtGui.QShortcut(QtGui.QKeySequence("F5"), self,
                         activated=self._refresh_ports)
        # Ctrl+Q é do item Sair do menu Arquivo: um QShortcut igual aqui
        # deixaria o atalho ambíguo e nenhum dos dois responderia.
        # Comando palette + screenshot + modo apresentação
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+Shift+P"), self,
                         activated=self._show_command_palette)
        QtGui.QShortcut(QtGui.QKeySequence("Ctrl+P"), self,
                         activated=self._screenshot_current_tab)
        QtGui.QShortcut(QtGui.QKeySequence("F11"), self,
                         activated=self._toggle_presentation_mode)
        # F1 era PROMETIDO em três lugares do texto de ajuda ("Pressione F1")
        # e nunca existiu: nenhum QShortcut o registrava, e o diálogo de
        # atalhos ainda o anunciava como "Sobre o aplicativo". Quem apertava
        # não recebia nada — pior que não ter atalho.
        QtGui.QShortcut(QtGui.QKeySequence("F1"), self,
                         activated=self._show_help_assistant)

    def _screenshot_current_tab(self):
        """Captura aba atual como PNG, salvo em sessions/screenshots/."""
        try:
            # Captura a janela toda (ou só o widget central)
            central = self.centralWidget() or self
            pixmap = central.grab()
            # Pasta de destino
            shots_dir = os.path.join(self.config.save_directory, "screenshots")
            os.makedirs(shots_dir, exist_ok=True)
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            # Nome da aba atual (para nome do arquivo)
            tab_name = "tab"
            try:
                top_i = self._main_tabs.currentIndex()
                top_name = self._main_tabs.tabText(top_i).replace(" ", "_")
                # Pega sub-aba atual
                sub = self._main_tabs.widget(top_i)
                if isinstance(sub, QtWidgets.QTabWidget):
                    sub_name = sub.tabText(sub.currentIndex()).replace(" ", "_")
                    tab_name = f"{top_name}__{sub_name}"
                else:
                    tab_name = top_name
            except Exception: pass
            # O nome da aba vira nome de arquivo: "Bio (EMG/ECG/EoG)" levava a
            # barra para o caminho, o Qt tentava gravar numa subpasta que não
            # existe e devolvia False em silêncio — o Ctrl+P não salvava nada
            # nas abas Bio do modo Multimodal.
            tab_name = re.sub(r'[<>:"/\\|?*\x00-\x1f()·]+', "_", tab_name)
            tab_name = re.sub(r"_+", "_", tab_name).strip("_") or "tab"
            out_path = os.path.join(shots_dir, f"screenshot_{tab_name}_{ts}.png")
            if pixmap.save(out_path, "PNG"):
                self._log(f"Screenshot salvo: {out_path}")
                self._audit_event("screenshot_captured", path=out_path)
                # Notifica via status bar
                if hasattr(self, "status_state_lbl"):
                    self.status_state_lbl.setText(f"Screenshot: {os.path.basename(out_path)}")
            else:
                self._log(f"Falha ao gravar screenshot em {out_path}", error=True)
                if hasattr(self, "status_state_lbl"):
                    self.status_state_lbl.setText(tr("Falha ao salvar a captura de tela"))
        except Exception as exc:
            self._log(f"Falha ao capturar screenshot: {exc}", error=True)

    def _toggle_presentation_mode(self):
        """Alterna modo apresentação: fullscreen + esconde menu/status bar."""
        self._presentation_mode = not getattr(self, "_presentation_mode", False)
        if self._presentation_mode:
            self._pre_pres_state = self.windowState()
            self.showFullScreen()
            if hasattr(self, "menuBar"):
                self.menuBar().setVisible(False)
            sb = self.statusBar() if hasattr(self, "statusBar") else None
            if sb: sb.setVisible(False)
            if hasattr(self, "header_widget"):
                self.header_widget.setVisible(False)
            self._log("Modo apresentação ATIVADO (F11 para sair).")
        else:
            self.setWindowState(QtCore.Qt.WindowState.WindowNoState)
            self.showNormal()
            if hasattr(self, "menuBar"):
                self.menuBar().setVisible(True)
            sb = self.statusBar() if hasattr(self, "statusBar") else None
            if sb: sb.setVisible(True)
            if hasattr(self, "header_widget"):
                self.header_widget.setVisible(True)
            self._log("Modo apresentação desativado.")

    def _aplicar_nivel_menus(self):
        """Menus por nível: Ferramentas e Diagnóstico só no Avançado; o item de
        Ajuda mostra para onde o clique leva (completo ↔ simples)."""
        simples = self._nivel_simples()
        act = getattr(self, "_tools_menu_act", None)
        if act is not None:
            act.setVisible(not simples)
        act = getattr(self, "_act_diag", None)
        if act is not None:
            act.setVisible(not simples)
        act = getattr(self, "_act_modo_completo", None)
        if act is not None:
            act.setText(tr("Mudar para Completo (pesquisa)") if simples
                        else tr("Voltar para Simples (exame)"))
        # ⌂ Início na barra de ação nos dois níveis: no Completo ele sumia e
        # a pessoa não achava o caminho de volta (validação com leigos)
        b = getattr(self, "ab_inicio_btn", None)
        if b is not None:
            b.setVisible(True)

    def _abrir_tela_inicial(self):
        """Reabre a tela inicial sobre a janela escondida e devolve (código,
        escolha). Separado para o teste substituir sem exec()."""
        app = QtWidgets.QApplication.instance()
        # a janela principal fica escondida enquanto a tela inicial está
        # aberta: sem isto o Qt encerraria o programa ao fechá-la
        antes = app.quitOnLastWindowClosed() if app is not None else True
        if app is not None:
            app.setQuitOnLastWindowClosed(False)
        try:
            while True:
                la = LauncherScreen(config=self.config, volunteers_mgr=self.volunteers)
                res = la.exec()
                if res != LauncherScreen.TROCAR_PARA_COMPLETO:
                    break
                # a tela inicial gravou o nível novo: a janela acompanha
                self._definir_nivel(self.config.ui_level)
            return res, la.get_choice()
        finally:
            if app is not None:
                app.setQuitOnLastWindowClosed(antes)

    def _voltar_ao_inicio(self):
        """Menu Arquivo / botão ⌂ Início: para a gravação (com confirmação),
        desconecta e volta à tela inicial; a escolha nova é aplicada nesta
        mesma janela (validação com leigos, G18). "Sair" lá fecha o programa."""
        if getattr(self, "is_recording", False):
            resp = QtWidgets.QMessageBox.question(
                self, tr("Gravando"),
                tr("A gravação ainda está em andamento. Parar a gravação e "
                   "voltar ao início?"),
                QtWidgets.QMessageBox.StandardButton.Yes
                | QtWidgets.QMessageBox.StandardButton.No,
                QtWidgets.QMessageBox.StandardButton.No)
            if resp != QtWidgets.QMessageBox.StandardButton.Yes:
                return
        if self.serial_thread:
            self._disconnect()      # para a gravação também
        # a tela inicial recomeça do passo 1
        self._ultima_sessao_parada = None
        self._pdf_gerado = None
        self._gravacao_aberta_de = None
        self._sync_action_bar()
        self.hide()
        try:
            res, escolha = self._abrir_tela_inicial()
        except Exception as exc:
            self._log(f"Falha ao reabrir a tela inicial: {exc}", error=True)
            res, escolha = QtWidgets.QDialog.DialogCode.Rejected, None
            self.show()
            return
        if res != QtWidgets.QDialog.DialogCode.Accepted or not escolha:
            self._log("Tela inicial: Sair.")
            self.close()
            # a janela já estava escondida (hide) quando fechou: o Qt só
            # encerra o programa quando a ÚLTIMA JANELA VISÍVEL fecha, e
            # app.exec() ficava rodando invisível (processo fantasma)
            self._encerrar_programa()
            return
        # Idioma e nível podem ter mudado lá dentro (config é o mesmo objeto)
        if self.config.ui_level != ("simples" if self._nivel_simples() else "avancado"):
            self._definir_nivel(self.config.ui_level)
        self.show()
        self.apply_launcher_choice(escolha)

    @staticmethod
    def _encerrar_programa():
        """Pede ao Qt para sair do laço principal no próximo tique (depois
        de o close() terminar). Separado para o teste espiar."""
        app = QtWidgets.QApplication.instance()
        if app is not None:
            # exit(0), não quit(): o quit() do Qt 6 só encerra o laço
            # principal (um laço aninhado, como o dos testes, ficava rodando)
            QtCore.QTimer.singleShot(0, lambda: app.exit(0))

    def _caminho_manual_usuario(self):
        """Primeiro PDF do manual que existir ao lado do script (ou no .exe)."""
        bases = [SCRIPT_DIR] + ([_MEIPASS_DIR] if _MEIPASS_DIR else [])
        # O manual existe nos 9 idiomas: quem usa a interface em japonês não
        # deve cair no PDF em português. Sem o do idioma, vale o português.
        por_idioma = "Manual_ROA_%s.pdf" % I18N.current
        for base in bases:
            for rel in (("Manual_ROA", "idiomas", por_idioma),
                        ("Manual_ROA", por_idioma),
                        ("Manual_ROA", "manual_usuario.pdf"),
                        ("Manual_ROA", "Manual_ROA_9_idiomas.pdf"),
                        ("manual_usuario.pdf",),
                        ("Manual_ROA_9_idiomas.pdf",)):
                p = os.path.join(base, *rel)
                if os.path.isfile(p):
                    return p
        return None

    def _abrir_manual_usuario(self):
        """Ajuda → Manual do usuário (PDF): abre no leitor padrão do sistema."""
        p = self._caminho_manual_usuario()
        if not p:
            QtWidgets.QMessageBox.information(
                self, tr("Manual do usuário (PDF)"),
                tr("O manual em PDF não foi encontrado ao lado do programa."))
            return
        self._abrir_pasta(p)

    def _abrir_pasta(self, path):
        """Abre uma pasta (ou arquivo) no explorador/leitor padrão do SO."""
        try:
            if sys.platform.startswith("win"):
                os.startfile(path)
            elif sys.platform == "darwin":
                import subprocess; subprocess.Popen(["open", path])
            else:
                import subprocess; subprocess.Popen(["xdg-open", path])
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self, tr("Abrir pasta"), str(exc))

    @staticmethod
    def _caminho_quebravel(caminho):
        """Caminho só para EXIBIR: espaço de largura zero (U+200B) depois de
        cada separador, para a caixa quebrar a linha nas pastas. Sem isso o Qt
        quebrava logo depois de "C:". Não usar o resultado como caminho."""
        zw = chr(0x200B)
        return str(caminho).replace("\\", "\\" + zw).replace("/", "/" + zw)

    def _frase_arquivo_salvo(self, sess_dir, caminho, tipo):
        """Simples: "Relatório salvo na pasta de Maria Teste, 27/09 às 19:26
        (Relatorio_EEG_….pdf)." no lugar do caminho inteiro em 7 linhas; o
        caminho completo fica na dica de ferramenta e em "Abrir pasta"
        (validação com leigos, G25). `tipo` é "relatorio" ou "figura"."""
        quando = None
        try:
            with open(os.path.join(sess_dir, "summary.json"), "r",
                      encoding="utf-8") as fh:
                ini = str(json.load(fh).get("started_at") or "")
            quando = datetime.fromisoformat(ini[:19])
        except Exception:
            pass
        dono = self._dono_da_gravacao(sess_dir)
        quem = (dono.get("nome") or dono.get("vid") or "") if dono else ""
        nome = os.path.basename(str(caminho))
        pasta = os.path.basename(os.path.normpath(str(sess_dir)))
        if quem and quando is not None:
            q = tr("{0} às {1}").format(quando.strftime("%d/%m"),
                                        quando.strftime("%H:%M"))
            if tipo == "figura":
                return tr("Figura salva na pasta de {0}, {1} ({2}).").format(quem, q, nome)
            return tr("Relatório salvo na pasta de {0}, {1} ({2}).").format(quem, q, nome)
        if tipo == "figura":
            return tr("Figura salva na pasta da gravação {0} ({1}).").format(pasta, nome)
        return tr("Relatório salvo na pasta da gravação {0} ({1}).").format(pasta, nome)

    def _caixa_abrir_pasta(self, titulo, texto, pasta, arquivo=None,
                           rotulo_arquivo=None, dica=None):
        """Caixa de conclusão (PDF gerado, figura salva) com "Abrir pasta".
        Com `arquivo`, "Abrir relatório" (ou `rotulo_arquivo`, ex. "Abrir
        figura") é o botão padrão e abre o arquivo no programa do sistema;
        "Abrir pasta" fica secundário (G06, G15). `dica`: o caminho inteiro,
        na dica de ferramenta da caixa (G25)."""
        msg = QtWidgets.QMessageBox(self)
        msg.setIcon(QtWidgets.QMessageBox.Icon.Information)
        msg.setWindowTitle(titulo)
        msg.setText(texto)
        if dica:
            msg.setToolTip(str(dica))
            lbl = msg.findChild(QtWidgets.QLabel, "qt_msgbox_label")
            if lbl is not None:
                lbl.setToolTip(str(dica))
        b_arq = None
        if arquivo:
            b_arq = msg.addButton(rotulo_arquivo or tr("Abrir relatório"),
                                  QtWidgets.QMessageBox.ButtonRole.AcceptRole)
        b_abrir = msg.addButton(tr("Abrir pasta"),
                                QtWidgets.QMessageBox.ButtonRole.ActionRole)
        b_fechar = msg.addButton(tr("Fechar"),
                                 QtWidgets.QMessageBox.ButtonRole.RejectRole)
        msg.setDefaultButton(b_arq or b_fechar)
        if self._nivel_simples() and b_arq is not None:
            # a ação cheia é abrir o relatório; o resto em contorno
            d = _dens
            self._papel_botao(b_arq, "primaria", d(46, 40))
            for b in (b_abrir, b_fechar):
                self._papel_botao(b, "secundaria", d(40, 34))
        msg.exec()
        if b_arq is not None and msg.clickedButton() is b_arq:
            self._abrir_pasta(arquivo)
        elif msg.clickedButton() is b_abrir:
            self._abrir_pasta(pasta)

    def _show_command_palette(self):
        """Abre paleta de comandos (Ctrl+Shift+P) — busca global de abas/comandos."""
        commands = self._build_palette_commands()
        dlg = _CommandPalette(commands, parent=self)
        # Centraliza sobre a janela principal
        geo = self.geometry()
        dlg.move(geo.x() + (geo.width() - dlg.width()) // 2,
                  geo.y() + 80)
        dlg.exec()

    def _build_palette_commands(self):
        """Constrói a lista de comandos para a paleta."""
        cmds = []
        # ---- Abas top-level ----
        if hasattr(self, "_main_tabs") and hasattr(self, "_sub_tabs"):
            top_titles = ["Configurar", "Visualizar", "Analisar", "Sistema"]
            for i, title in enumerate(top_titles):
                if i < self._main_tabs.count():
                    cmds.append({
                        "label": tr(title), "category": "Grupo",
                        "action": (lambda idx=i: self._main_tabs.setCurrentIndex(idx)),
                    })
            # Sub-abas
            sub_specs = [
                ("setup",   ["Voluntários", "Conexão", "Filtros e Canais",
                              "Hardware", "Calibração"]),
                ("view",    ["Tempo Real", "Topografia", "Espectrograma",
                              "Bio (EMG/ECG/EoG)", "Histórico", "Layout Custom"]),
                ("analyse", ["Análises", "Offline", "ERP", "Conectividade",
                              "ERS/ERD", "Focus / SSVEP", "EMG Joystick",
                              "BCI Trainer (MI)", "Estudo por Paciente"]),
                ("system",  ["Rede e Eventos", "Configurações",
                              "Referências"]),
            ]
            top_map = {"setup": 0, "view": 1, "analyse": 2, "system": 3}
            for key, titles in sub_specs:
                sub = self._sub_tabs.get(key); top_i = top_map[key]
                if not sub: continue
                for i, t in enumerate(titles):
                    pos = self._pos_aba(key, i)
                    if pos < 0: continue
                    if not sub.isTabVisible(pos): continue   # oculta pelo modo/nível
                    # o nome que a barra mostra (já traduzido): em modo único
                    # a aba Bio se chama "Músculos"/"Coração"/"Olhos" e a
                    # paleta oferecia "Bio (EMG/ECG/EoG)", que não está na tela
                    cmds.append({
                        "label": sub.tabText(pos) or tr(t), "category": "Aba",
                        "action": (lambda ti=top_i, k=key, si=i:
                                   self._ir_para_aba(ti, k, si)),
                    })
        # ---- Comandos de hardware/gravação ----
        common = [
            ("Conectar/Desconectar (Ctrl+Shift+C)", "Comando", self._toggle_connection),
            ("Iniciar/Parar gravação (Ctrl+R)",     "Comando", self._toggle_recording),
            ("Atualizar lista de portas (F5)",      "Comando", self._refresh_ports),
            ("Captura de tela da aba (Ctrl+P)",     "Comando", self._screenshot_current_tab),
            ("Modo apresentação (F11)",             "Comando", self._toggle_presentation_mode),
            ("Abrir pasta de sessões",              "Comando", self._open_save_dir),
            ("Sobre o aplicativo",                  "Comando", self._show_about_dialog),
            ("Atalhos de teclado",                  "Comando", self._show_shortcuts_dialog),
            ("Detectar canais ruins",               "Comando", self._detect_bad_channels),
            ("Exportar para EDF",                   "Comando", self._export_to_edf),
            ("Exportar para FIF (MNE) + script",    "Comando", self._export_to_fif),
            ("Exportar BIDS-EEG",                   "Comando", self._export_to_bids),
            ("Relatório PDF",                       "Comando",
             lambda _=False: self._export_pdf_report()),
            # Interruptor do nível: o rótulo diz para onde o comando leva
            (("Mudar para Completo (pesquisa)" if self._nivel_simples()
              else "Voltar para Simples (exame)"), "Comando",
             lambda: self._definir_nivel(
                 "avancado" if self._nivel_simples() else "simples")),
        ]
        for label, cat, action in common:
            if action is not None:
                cmds.append({"label": tr(label), "category": cat, "action": action})
        # ---- Voluntários ----
        try:
            for prof in self.volunteers.list_volunteers():
                vid = prof.get("vid", "?")
                nome = prof.get("nome", "")
                cmds.append({
                    "label": f"{tr('Selecionar voluntário:')} {vid} — {nome}",
                    "category": "Voluntário",
                    "action": (lambda dn=prof.get("_dirname"):
                               (self.volunteers.select_volunteer(dn),
                                self._volunteer_update_indicator())),
                })
        except Exception:
            pass
        return cmds

