    def _export_protocol_profile(self):
        """Exporta a montagem/setup (mapeamento, tipos de sinal, EMG, impedância)
        como um perfil .json reutilizável entre máquinas."""
        prof = {
            "profile_version": "1.0",
            "channel_mapping": self.config.channel_mapping,
            "channel_signal_types": self.config.channel_signal_types,
            "emg_threshold_uV": self.config.emg_threshold_uV,
            "emg_channel_muscle": self.config.emg_channel_muscle,
            "emg_channel_mvc_uV": self.config.emg_channel_mvc_uV,
            "emg_envelope_method": self.config.emg_envelope_method,
            "emg_envelope_window_ms": self.config.emg_envelope_window_ms,
            "imp_good_max": self.config.imp_good_max,
            "imp_acceptable_max": self.config.imp_acceptable_max,
        }
        p, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Exportar perfil de protocolo"), "perfil_protocolo.json",
            tr("Perfil (*.json)"))
        if not p:
            return
        try:
            with open(p, "w", encoding="utf-8") as f:
                json.dump(prof, f, ensure_ascii=False, indent=2)
            QtWidgets.QMessageBox.information(self, tr("Perfil de protocolo"),
                                              tr("Perfil salvo:\n{0}").format(p))
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self, tr("Perfil de protocolo"),
                                          tr("Falha ao salvar: {0}").format(exc))

    def _import_protocol_profile(self):
        """Importa um perfil de protocolo .json (validação defensiva), salva no
        config e pede para reabrir para aplicar tudo."""
        p, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Importar perfil de protocolo"), "", tr("Perfil (*.json)"))
        if not p:
            return
        try:
            with open(p, encoding="utf-8") as f:
                prof = json.load(f)
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self, tr("Perfil de protocolo"),
                                          tr("Falha ao ler: {0}").format(exc))
            return
        cm = prof.get("channel_mapping")
        if isinstance(cm, list) and len(cm) == len(self.config.channel_mapping):
            self.config.channel_mapping = cm
        for key in ("channel_signal_types", "emg_threshold_uV",
                    "emg_channel_muscle", "emg_channel_mvc_uV"):
            v = prof.get(key)
            if isinstance(v, list):
                setattr(self.config, key, v)
        if isinstance(prof.get("emg_envelope_method"), str):
            self.config.emg_envelope_method = prof["emg_envelope_method"]
        for key in ("emg_envelope_window_ms", "imp_good_max", "imp_acceptable_max"):
            try:
                setattr(self.config, key,
                        type(getattr(self.config, key))(prof[key]))
            except Exception:
                pass
        self.config.save()
        # Os combos do Mapeamento de Canais ficaram exibindo o mapeamento
        # ANTIGO. Sem este ressincronismo, a primeira edição de qualquer combo
        # regrava a lista inteira a partir do que está na tela e desfaz o
        # perfil que acabou de ser importado.
        self._reload_mapping_combos()
        QtWidgets.QMessageBox.information(
            self, tr("Perfil de protocolo"),
            tr("Perfil importado e salvo. Reabra o programa para aplicar "
               "totalmente (mapeamento e tipos de sinal)."))

    def _reload_mapping_combos(self):
        """Repõe nos combos do Mapeamento de Canais o que está na config.

        Usado depois de importar um perfil de protocolo, que troca
        config.channel_mapping por baixo da interface. Bloqueia os sinais para
        a reposição não disparar _on_mapping_changed 64 vezes.
        """
        combos = getattr(self, "map_combos", None)
        if not combos:
            return
        mapa = list(getattr(self.config, "channel_mapping", []) or [])
        for ch, cb in enumerate(combos):
            if ch >= len(mapa):
                break
            i = cb.findText(str(mapa[ch]))
            if i < 0:
                continue
            antigo = cb.blockSignals(True)
            cb.setCurrentIndex(i)
            cb.blockSignals(antigo)
        self._refresh_mapping_rows()

    def _emg_atlas_zoom_mudou(self, z):
        """Mantém o combo de região honesto quando o zoom vem da roda do mouse.

        Sem isto o combo continuaria marcando "Corpo inteiro" com a vista
        ampliada. Ao ampliar na mão, marca "(livre)"; ao voltar a 1×, volta
        para "Corpo inteiro".
        """
        cb = getattr(self, "emg_atlas_regiao", None)
        if cb is None:
            return
        antigo = cb.blockSignals(True)
        if abs(z - 1.0) < 1e-6:
            cb.setCurrentIndex(0)
        else:
            i = cb.findData("__livre__")
            if i < 0:
                cb.addItem(tr("(livre)"), "__livre__")
                i = cb.count() - 1
            cb.setCurrentIndex(i)
        cb.blockSignals(antigo)

    def _open_cocontraction_map(self):
        """Abre o mapa de co-contração agonista/antagonista.

        Sem modal (show, não exec) de propósito: ele precisa receber o envelope
        do EMG enquanto a coleta continua rodando atrás.
        """
        dlg = getattr(self, "_cocontr_dialog", None)
        if dlg is not None:
            try:
                dlg.raise_(); dlg.activateWindow(); return
            except RuntimeError:
                self._cocontr_dialog = None
        CoContractionMapDialog(self).show()

