        layout.addStretch()
        sub_tabs.addTab(theme_page, tr("Tema e Cores"))

        # ============== Sub-aba: CANAIS (mapeamento 10-20) ==============
        ch_page = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(ch_page)
        layout.setContentsMargins(10, 8, 10, 8); layout.setSpacing(8)

        # ---- Mapeamento de canais ----
        map_group = QtWidgets.QGroupBox(tr("Mapeamento de Canais (qual eletrodo cada CHn representa)"))
        ml = QtWidgets.QVBoxLayout(map_group)
        info = QtWidgets.QLabel(
            tr("Selecione manualmente qual eletrodo do sistema 10-20 cada canal "
            "ocupa. Inclui Fz, Cz, Pz, FCz, CPz, POz, Oz, etc. A configuração "
            "fica salva e e usada no Head Plot/Heatmap, FFT e gravação CSV.")
        )
        info.setStyleSheet(f"color: {COLORS['text_dim']};")
        info.setWordWrap(True)
        ml.addWidget(info)

        grid = QtWidgets.QGridLayout()
        grid.setHorizontalSpacing(8); grid.setVerticalSpacing(4)
        self.map_combos = []
        # Layout 8 linhas x 2 canais por linha (4 colunas: lbl1, cb1, lbl2, cb2).
        # Cabe todos os 16 canais SEM corte horizontal mesmo em telas pequenas.
        grid.setHorizontalSpacing(10); grid.setVerticalSpacing(4)
        for ch in range(MAX_CHANNELS):
            lbl = QtWidgets.QLabel(f"CH{ch + 1}")
            lbl.setStyleSheet(f"color: {CHANNEL_COLORS[ch]}; font-weight: bold;")
            lbl.setMinimumWidth(46)
            cb = QtWidgets.QComboBox()
            cb.addItems(ELECTRODE_NAMES)
            cb.setMinimumWidth(110)
            cur = self.config.channel_mapping[ch] if ch < len(self.config.channel_mapping) else DEFAULT_MAPPING[ch]
            idx = cb.findText(cur)
            cb.setCurrentIndex(idx if idx >= 0 else 0)
            cb.currentTextChanged.connect(self._on_mapping_changed)
            self.map_combos.append(cb)
            row, col = ch // 2, (ch % 2) * 2
            grid.addWidget(lbl, row, col)
            grid.addWidget(cb,  row, col + 1)
        ml.addLayout(grid)
        # guarda os pares rótulo+combo para poder ocultar os canais fora de uso
        self._map_rows = list(zip(
            (grid.itemAtPosition(ch // 2, (ch % 2) * 2).widget()
             for ch in range(MAX_CHANNELS)), self.map_combos))

        # Pedido de usuário: com 8 canais em uso, a página listava os 64 e
        # virava um paredão. Agora mostra só os canais ATIVOS; os demais são
        # opcionais, atrás desta caixa.
        self.map_show_all_chk = QtWidgets.QCheckBox(
            tr("Mostrar todos os 64 canais (opcional — além dos em uso)"))
        self.map_show_all_chk.toggled.connect(
            lambda _v: self._refresh_mapping_rows())
        ml.addWidget(self.map_show_all_chk)

        btn_row = QtWidgets.QHBoxLayout()
        save_map = QtWidgets.QPushButton(tr("Salvar mapeamento"))
        save_map.clicked.connect(self._save_mapping_and_apply)
        reset_map = QtWidgets.QPushButton(tr("Restaurar mapeamento padrão"))
        reset_map.clicked.connect(self._reset_mapping_to_default)
        btn_row.addWidget(save_map); btn_row.addWidget(reset_map); btn_row.addStretch()
        ml.addLayout(btn_row)
        layout.addWidget(map_group)
        layout.addStretch()
        self._refresh_mapping_rows()
        sub_tabs.addTab(ch_page, tr("Mapeamento de Canais"))

        # ============== Sub-aba: SESSÃO ==============
        sess_page = QtWidgets.QWidget()
        layout = QtWidgets.QVBoxLayout(sess_page)
        layout.setContentsMargins(10, 8, 10, 8); layout.setSpacing(8)

        # ---- Sessão ----
        sess_group = QtWidgets.QGroupBox(tr("Organização de Sessões"))
        self._sess_group = sess_group        # título por nível (G36)
        sl = QtWidgets.QGridLayout(sess_group)
        suj_lbl = QtWidgets.QLabel(tr("Nome do voluntário (sem cadastro):"))
        sl.addWidget(suj_lbl, 0, 0)
        self.subject_edit = QtWidgets.QLineEdit(self.config.subject)
        self.subject_edit.textChanged.connect(self._on_subject_changed)
        sl.addWidget(self.subject_edit, 0, 1)
        # com voluntário ativo o campo não vale: fica desligado e a nota diz
        # por quê (G04; _volunteer_update_indicator liga/desliga)
        self._subject_nota = QtWidgets.QLabel(tr("Só vale sem voluntário ativo."))
        self._subject_nota.setStyleSheet(f"color: {COLORS['text_dim']}; font-style: italic;")
        self._subject_nota.setVisible(False)
        sl.addWidget(self._subject_nota, 0, 2)
        # Simples: o paciente vem do cadastro; o campo livre mostrava o valor
