        self.export_edf_btn = QtWidgets.QPushButton(tr("→ EDF (clínico)"))
        self.export_edf_btn.setToolTip(tr("European Data Format (clínico, lido por Persyst/Polysmith/EEGLAB)"))
        self.export_edf_btn.clicked.connect(self._export_to_edf)
