        if not (HAS_REPORTLAB and HAS_MPL):
            self.export_pdf_btn.setEnabled(False)
            self.export_pdf_btn.setText(tr("PDF indisponível (matplotlib/reportlab)"))
        eg.addWidget(self.export_pdf_btn, 0, 3)
