            # Botão Padrão
            btn_default = QtWidgets.QPushButton(tr("Padrão"))
            btn_default.setToolTip(tr("Restaurar para: {0}").format(default_val))
            btn_default.setEnabled(editable)
            btn_default.clicked.connect(lambda _c, k=key: self._reset_system_path(k))
            grid.addWidget(btn_default, row, 3)

            # Botão Abrir pasta
            btn_open = QtWidgets.QPushButton(tr("Abrir"))
            btn_open.setToolTip(tr("Abre o caminho no explorador de arquivos"))
            btn_open.clicked.connect(lambda _c, k=key: self._open_system_path(k))
            grid.addWidget(btn_open, row, 4)

            # Botão Copiar
            btn_copy = QtWidgets.QPushButton(tr("Copiar"))
            btn_copy.setToolTip(tr("Copia o caminho para a área de transferência"))
            btn_copy.clicked.connect(lambda _c, k=key: self._copy_system_path(k))
            grid.addWidget(btn_copy, row, 5)

