def error_info(code):
    """Retorna (título, mensagem, bloqueante) do código; fallback genérico.

    Título e mensagem passam por tr(): o catálogo é escrito em português e,
    até a 1.8.3, o diálogo de erro saía em português em qualquer idioma da
    interface — o único texto do programa que não acompanhava a língua.
    """
    t, m, b = ERROR_CATALOG.get(code, ("Erro", "Ocorreu um erro nao catalogado.", True))
    return tr(t), tr(m), b


def notify_error(code, detail="", parent=None, exc=None, blocking=None):
    """Sinaliza um erro ao usuário como 'Erro {código}': loga SEMPRE e mostra
    um diálogo (bloqueante) ou deixa para a barra de status (aviso). Seguro fora
    da GUI (cai para print)."""
    title, msg, blk = error_info(code)
    if blocking is None:
        blocking = blk
    try:
        logging.getLogger("eeg").error(
            "[%s] %s%s", code, title, (" | " + str(detail)) if detail else "",
            exc_info=(exc is not None))
    except Exception:
        pass
    app = QtWidgets.QApplication.instance()
    if app is None:
        print(f"[Erro {code}] {title}: {detail}")
        return
    body = msg + (f"\n\n{tr('Detalhe técnico')}: {detail}" if detail else "")
    box = QtWidgets.QMessageBox(parent)
    box.setIcon(QtWidgets.QMessageBox.Icon.Critical if blocking
                else QtWidgets.QMessageBox.Icon.Warning)
    box.setWindowTitle(f"{tr('Erro')} {code}")
    box.setText(f"<b>{tr('Erro')} {code} \u2014 {title}</b>")
    box.setInformativeText(body)
    if exc is not None:
        try:
            box.setDetailedText("".join(
                traceback.format_exception(type(exc), exc, exc.__traceback__)))
        except Exception:
            pass
    box.exec()


class ErrorDiagnosticsDialog(QtWidgets.QDialog):
    """Lista o catálogo de erros e permite SIMULAR cada notificacao (Erro E0XX),
    para o usuário conhecer/testar as mensagens que o programa pode exibir."""

    def __init__(self, parent=None):
        """Monta a janela de diagnóstico: texto explicativo, campo de filtro,
        tabela de códigos, painel de pré-visualização e os botões
        Simular/Fechar.

        Guarda o catálogo ordenado em self._rows e reconstrói a tabela a cada
        filtro; por isso o código selecionado é lido do texto da célula
        (_current_code), nunca do índice da linha.
        """
        super().__init__(parent)
        self.setWindowTitle(tr("Diagnóstico de erros — simular notificações"))
        self.setMinimumSize(780, 580)
        v = QtWidgets.QVBoxLayout(self)
        v.addWidget(QtWidgets.QLabel(
            tr("<b>Catálogo de erros do programa.</b> Selecione um código e clique em "
            "<b>Simular</b> para ver a notificação. No uso real, <i>avisos</i> "
            "aparecem na barra de status (rodapé) e <i>bloqueantes</i> abrem um "
            "diálogo; aqui mostramos o diálogo para você conhecer cada um.")))
        self.filter_edit = QtWidgets.QLineEdit()
        self.filter_edit.setPlaceholderText(tr("Filtrar por código ou texto…"))
        self.filter_edit.textChanged.connect(self._refilter)
        v.addWidget(self.filter_edit)
        self.table = QtWidgets.QTableWidget(0, 3)
        self.table.setHorizontalHeaderLabels([tr("Código"), tr("Tipo"), tr("Título")])
        self.table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        self.table.setSelectionBehavior(
            QtWidgets.QAbstractItemView.SelectionBehavior.SelectRows)
        self.table.setSelectionMode(
            QtWidgets.QAbstractItemView.SelectionMode.SingleSelection)
        self.table.verticalHeader().setVisible(False)
        self.table.horizontalHeader().setStretchLastSection(True)
        v.addWidget(self.table, 1)
        self._rows = sorted(ERROR_CATALOG.items())
        self._fill(self._rows)
        self.table.itemSelectionChanged.connect(self._preview)
        self.table.doubleClicked.connect(self._simulate)
        self.preview = QtWidgets.QPlainTextEdit(); self.preview.setReadOnly(True)
        self.preview.setMaximumHeight(120)
        v.addWidget(self.preview)
        h = QtWidgets.QHBoxLayout()
        self.count_lbl = QtWidgets.QLabel(tr("{0} códigos catalogados").format(len(self._rows)))
        btn_sim = QtWidgets.QPushButton(tr("▶ Simular notificação"))
        btn_sim.clicked.connect(self._simulate)
        btn_close = QtWidgets.QPushButton(tr("Fechar")); btn_close.clicked.connect(self.accept)
        h.addWidget(self.count_lbl); h.addStretch(1)
        h.addWidget(btn_sim); h.addWidget(btn_close)
        v.addLayout(h)
        try: self.setStyleSheet(build_stylesheet(COLORS))
        except Exception: pass
        if self.table.rowCount(): self.table.selectRow(0)

    def _fill(self, rows):
        """Repopula a tabela com a lista de códigos recebida, uma linha por erro.

        Traduz o terceiro campo do catálogo (booleano) para o texto
        'Bloqueante'/'Aviso' da coluna Tipo. É chamado tanto na construção
        quanto a cada refiltragem.
        """
        self.table.setRowCount(len(rows))
        for r, (code, (title, _msg, blk)) in enumerate(rows):
            self.table.setItem(r, 0, QtWidgets.QTableWidgetItem(code))
            self.table.setItem(r, 1, QtWidgets.QTableWidgetItem(
                tr("Bloqueante") if blk else tr("Aviso")))
            self.table.setItem(r, 2, QtWidgets.QTableWidgetItem(tr(title)))
        self.table.resizeColumnToContents(0)
        self.table.resizeColumnToContents(1)

    def _refilter(self, text):
        """Slot do campo de busca: refaz a tabela apenas com os códigos cujo
        código, título ou mensagem contenham o texto digitado.

        A comparação é por substring em minúsculas, sem remoção de acentos (não
        usa _help_norm), então 'sessão' não encontra 'sessão'.
        """
        t = (text or "").lower().strip()
        # procura no texto em português e no exibido (o usuário digita no
        # idioma da tela)
        rows = [it for it in self._rows if (t in it[0].lower()
                or t in it[1][0].lower() or t in it[1][1].lower()
                or t in tr(it[1][0]).lower() or t in tr(it[1][1]).lower())]
        self._fill(rows)
        self.count_lbl.setText(tr("{0} de {1} códigos").format(len(rows), len(self._rows)))
        if self.table.rowCount(): self.table.selectRow(0)

    def _current_code(self):
        """Devolve o código de erro da linha atualmente selecionada, ou None se
        não houver seleção."""
        r = self.table.currentRow()
        it = self.table.item(r, 0) if r >= 0 else None
        return it.text() if it else None

    def _preview(self):
        """Mostra no painel inferior o título, o tipo e a mensagem completa do
        código selecionado."""
        code = self._current_code()
        if not code: return
        title, msg, blk = error_info(code)
        self.preview.setPlainText(
            tr("Erro {0} — {1}  [{2}]\n\n{3}").format(
                code, title, tr('Bloqueante') if blk else tr('Aviso'), msg))

    def _simulate(self, *_):
        """Dispara notify_error para o código selecionado, permitindo ao usuário
        ver a notificação real antes de encontrá-la em uso.

        Força blocking=True e passa o detalhe '(simulação)', então mesmo os
        códigos classificados como aviso aparecem aqui como diálogo modal.
        """
        code = self._current_code()
        if not code:
            QtWidgets.QMessageBox.information(self, tr("Simular"),
                                              tr("Selecione um código na lista."))
            return
        notify_error(code, tr("(simulação)"), parent=self, blocking=True)


