def _guia_html(g):
    """Monta o HTML de um guia de solução: objetivo, passos, cuidados, saídas.

    Os passos saem numerados de propósito. A resposta antiga era um parágrafo
    corrido que dizia o nome da tela e parava ali; quem estava travado no meio
    do caminho não tinha como saber em que ponto estava.
    """
    # Todo texto do guia passa pelo tr(): o conteúdo nasceu em português e o
    # programa fala nove idiomas — deixar os guias fora da tradução seria
    # recriar a mistura de línguas que já foi corrigida no resto da interface.
    p = [("<b>" + tr("O que você terá no fim:") + "</b> " + tr(g["obj"]))
         if g.get("obj") else ""]
    if g.get("passos"):
        p.append("<br><b>" + tr("Passo a passo") + "</b><ol>"
                 + "".join(f"<li>{tr(x)}</li>" for x in g["passos"]) + "</ol>")
    if g.get("cuidados"):
        p.append("<b>" + tr("O que costuma dar errado") + "</b><ul>"
                 + "".join(f"<li>{tr(x)}</li>" for x in g["cuidados"]) + "</ul>")
    if g.get("erros"):
        p.append("<b>" + tr("Se acontecer isso") + "</b><ul>"
                 + "".join(f"<li><i>{tr(x)}</i> → {tr(y)}</li>"
                           for x, y in g["erros"]) + "</ul>")
    return "".join(x for x in p if x)


def _metodo_html(m):
    """Cartão de um método: o que mede, como usar, fórmula e de onde vem.

    A ordem é a da dúvida real de quem pergunta: primeiro para que serve,
    depois o passo a passo, e só então a matemática. Quem quer a fórmula
    rola até ela; quem quer usar não precisa passar por ela.
    """
    ref = REFS_METODOS.get(m.get("ref")) or {}
    onde = "%s → %s → %s" % (tr("Analisar"), tr("Área Maker"),
                             tr("Modalidade") + ": " + m["modalidade"])
    h = ["<b>%s</b> &nbsp;<span style='color:#78909c'>(%s%s)</span><br><br>"
         % (tr(m["rotulo"]), m["modalidade"],
            "" if m.get("unidade") in (None, "", "—")
            else " · " + tr(m["unidade"]))]
    h.append("%s<br><br>" % tr(m["aplicacao"]))
    passos = m.get("guia") or []
    if passos:
        h.append("<i>%s</i><ol>" % tr("Como usar"))
        for p in passos:
            h.append("<li>%s</li>" % tr(p))
        h.append("</ol>")
    if m.get("par"):
        h.append("<i>%s</i> %s<br><br>"
                 % (tr("Atenção:"),
                    tr("é métrica de PAR — informe os canais dois a dois, e a "
                       "ordem importa.")))
    if m.get("multicanal"):
        h.append("<i>%s</i> %s<br><br>"
                 % (tr("Atenção:"),
                    tr("precisa de vários canais do mesmo registro.")))
    if m.get("banda"):
        h.append("<i>%s</i> %s<br><br>"
                 % (tr("Atenção:"),
                    tr("usa o seletor de banda ao lado da métrica.")))
    if m.get("formula"):
        h.append("<i>%s</i><br><code>%s</code><br><br>"
                 % (tr("Fórmula"), tr(m["formula"])))
    h.append("<i>%s</i> %s" % (tr("Onde fica:"), onde))
    if ref:
        cita = "%s %s. %s, %s." % (ref["autores"], ref["titulo"],
                                   ref["veiculo"], ref["ano"])
        h.append("<br><br><i>%s</i><br><span style='font-size:9pt'>%s</span>"
                 % (tr("Referência"), cita))
        if ref.get("doi"):
            h.append("<br><span style='font-size:9pt'>DOI: "
                     "<a href='https://doi.org/%s'>%s</a></span>"
                     % (ref["doi"], ref["doi"]))
    return "".join(h)


def _help_docs_metodos():
    """Um documento de ajuda por método do catálogo.

    Antes disto, perguntar "como uso a MPR?" não tinha onde cair: o
    assistente conhecia as telas do programa, mas não os métodos que o
    programa calcula.
    """
    docs = []
    for m in CATALOGO_METODOS:
        ref = REFS_METODOS.get(m.get("ref")) or {}
        cru = [m["rotulo"], m["modalidade"], m.get("grupo", "") or "",
               m.get("aplicacao", ""), m.get("formula", ""),
               m.get("unidade", "") or "", ref.get("autores", ""),
               ref.get("titulo", "")] + list(m.get("guia") or [])
        docs.append({
            "title": "%s — %s" % (tr(m["rotulo"]), m["modalidade"]),
            "kind": "metodo", "peso": 1.60,
            "ref": "%s → %s" % (tr("Analisar"), tr("Área Maker")),
            "answer": _metodo_html(m),
            "modalidade": m["modalidade"],
            # A fórmula traduzida (1.8.4) fica fora do índice: ela repete as
            # palavras de cartões vizinhos ("mediana das piscadas
            # detectadas") e fazia "まばたきの検出" cair na duração das
            # piscadas em vez do cartão de detecção. Antes da tradução, tr()
            # da fórmula devolvia o próprio português — o índice fica igual.
            "text": " ".join(cru + [tr(x) for x in cru
                                    if x and x != m.get("formula")]),
        })
    return docs


_HELP_MOD_PISTAS = {
    "EMG": ("emg", "musculo", "muscular", "eletromiografia", "fadiga",
            "contracao", "biceps", "triceps", "cvm", "sinergia", "mioeletrico",
            "эмг", "мышц", "肌电", "肌肉", "筋電", "筋肉"),
    "EEG": ("eeg", "cerebro", "cerebral", "eletroencefalografia", "alfa",
            "beta", "teta", "delta", "gama", "mu", "erd", "ers", "banda",
            "imagetica", "bci", "cortical",
            "ээг", "мозг", "脑电", "脳波"),
    "ECG": ("ecg", "coracao", "cardiaco", "eletrocardiograma", "hrv", "vfc",
            "batimento", "bpm", "qrs", "rr", "qt", "poincare", "arritmia",
            "экг", "сердц", "心电", "心率", "心電", "心拍"),
    "EoG": ("eog", "olho", "ocular", "piscada", "sacada", "perclos",
            "fixacao", "sonolencia", "eletroculografia", "olhar",
            "эог", "глаз", "морга", "眼电", "眨眼", "眼電", "まばたき"),
}


def _help_modalidade_da_pergunta(qn):
    """Modalidade que a pergunta sugere, ou None se não der para dizer.

    Serve para desempatar: "como meço fadiga?" existe em EMG e em EoG, e sem
    esta pista o assistente escolhia pela contagem de tokens, que é loteria.
    """
    contagem = {}
    palavras = set(qn.split())
    for mod, pistas in _HELP_MOD_PISTAS.items():
        n = sum(1 for p in pistas if p in palavras or p in qn)
        if n:
            contagem[mod] = n
    if not contagem:
        return None
    melhor = max(contagem.values())
    vencedores = [m for m, n in contagem.items() if n == melhor]
    return vencedores[0] if len(vencedores) == 1 else None


# Telas e recursos que o nível Simples esconde. Um guia ou verbete que manda
# a pessoa a uma delas não serve a quem está no Simples: a resposta "vá em
# Configurar → Calibração" apontava para uma aba que não existia na tela
# (validação com leigos, G22). Conferido com a janela real: no Simples ficam
# Pacientes, Conexão, Tempo Real (+ a aba do exame), Offline, Tema e Cores e
# Sessão e Arquivos.
_HELP_TELAS_SO_COMPLETO = tuple(re.compile(p) for p in (
    r"Filtros e Canais", r"Calibra[çc][ãa]o", r"\bHardware\b", r"Imped[âa]ncia",
    r"Topografia", r"Espectrograma", r"Hist[óo]rico", r"\bAn[áa]lises\b",
    r"\bERP\b", r"Conectividade", r"ERS/ERD", r"Focus / SSVEP", r"BCI Trainer",
    r"Treinador BCI", r"Estudo por Paciente", r"Refer[êe]ncias",
    r"Mapeamento de Canais", r"\bProtocolo\b", r"Caminhos e Auditoria",
    r"Estat[íi]stica guiada", r"Comparar condi[çc][õo]es", r"[ÁA]rea Maker",
    r"\bBancada\b", r"\bICA\b", r"Abrir EDF", r"iCelera", r"Importar arquivos",
    r"\bBIDS\b", r"\bFIF\b", r"\bMNE\b", r"\bLSL\b", r"Playback",
    r"Modo Simula[çc][ãa]o", r"summary\.json", r"Rede e Eventos", r"Layout Custom",
    r"\bReceitas\b", r"Regress[ãa]o ocular", r"\bnotch\b", r"Sistema → Volunt"))


def _help_cita_tela_oculta(texto):
    """O texto (em português, como está na fonte) manda para uma tela que o
    Simples não mostra?"""
    t = _help_strip_html(texto or "")
    return any(p.search(t) for p in _HELP_TELAS_SO_COMPLETO)


def _help_guias_do_nivel(nivel):
    """Guias que fazem sentido no nível: no Simples ficam de fora os que
    passam por telas ocultas (G22)."""
    if nivel != "simples":
        return list(HELP_GUIAS)
    return [g for g in HELP_GUIAS if not _help_cita_tela_oculta(
        " ".join([g["t"], g.get("obj", "")] + list(g.get("passos", []))
                 + list(g.get("cuidados", []))
                 + [x + " " + y for x, y in g.get("erros", [])]))]


def _help_corpus():
    """Monta (1x) o corpus indexado: guias de solução + glossário + FAQ +
    base de conhecimento (manual) + catálogo de erros, com IDF para
    ranqueamento TF-IDF. Tudo OFFLINE.

    Cada documento leva "so_completo": True quando cita uma tela que o
    Simples esconde; help_answer(nivel="simples") pula esses (G22)."""
    # O cache passa a ser POR IDIOMA: como os documentos agora carregam texto
    # traduzido, um corpus montado em português continuaria em uso depois de
    # trocar a língua da interface.
    global _HELP_CORPUS, _HELP_IDF, _HELP_CORPUS_LANG
    if _HELP_CORPUS is not None and _HELP_CORPUS_LANG == I18N.current:
        return _HELP_CORPUS, _HELP_IDF
    _HELP_CORPUS_LANG = I18N.current
    docs = []
    for g in HELP_GUIAS:                                 # guias de solucao
        # Entram primeiro e com peso: quem pergunta "como faço X" quer o
        # caminho até o fim, não a frase que diz onde fica a tela.
        # O texto indexado junta o original em português e a tradução ativa:
        # assim a busca acha tanto quem digitou no idioma da interface quanto
        # quem digitou o termo em português, que é como o material de campo e
        # os artigos do laboratório costumam estar escritos.
        cru = [g["k"], g["t"], g.get("obj", "")] + list(g.get("passos", []))             + list(g.get("cuidados", []))             + [x + " " + y for x, y in g.get("erros", [])]
        docs.append({"title": tr(g["t"]), "kind": "guia",
                     "ref": tr(g["ref"]) if g.get("ref") else "",
                     "answer": _guia_html(g), "peso": 1.55,
                     "so_completo": _help_cita_tela_oculta(" ".join(cru)),
                     "text": " ".join(cru + [tr(x) for x in cru if x])})
    # Um documento por método do catálogo: é o que dá ao
    # assistente conhecimento sobre o que o programa CALCULA, e
    # não só sobre onde ficam as telas.
    docs.extend(_help_docs_metodos())
    for sig, (nome, oque, onde) in HELP_GLOSSARIO.items():   # glossario
        # Uma sigla sozinha é um token só: sem verbete próprio, "o que é HRV?"
        # não tinha onde cair e a busca devolvia vazio ou o vizinho errado.
        docs.append({"title": f"{sig.upper()} — {tr(nome)}", "kind": "glo",
                     "ref": tr(onde), "peso": 1.15, "sigla": sig.lower(),
                     "answer": (f"<b>{sig.upper()}</b> — {tr(nome)}.<br><br>"
                                f"{tr(oque)}<br><br><i>" + tr("No ROA:")
                                + f"</i> {tr(onde)}"),
                     "text": f"{sig} {sig} {nome} {oque} {onde} "
                             f"{tr(nome)} {tr(oque)} " + tr("significa "
                             "definicao sigla o que e")})
    for e in HELP_FAQ:                                   # FAQ curada (precisao)
        # título e resposta traduzidos; o texto indexado leva as duas formas,
        # para a pergunta em qualquer língua achar a mesma entrada
        docs.append({"title": tr(e["t"]), "kind": "faq", "ref": tr(e.get("ref", "")),
                     "answer": tr(e["a"]),
                     # resposta própria do Simples, quando a do Completo cita
                     # um item de menu que só existe lá (G22)
                     "answer_simples": tr(e["a_simples"]) if e.get("a_simples") else None,
                     "so_completo": _help_cita_tela_oculta(
                         e["t"] + " " + (e.get("a_simples") or e["a"])),
                     "text": e["k"] + " " + e["t"] + " " + _help_strip_html(e["a"])
                     + " " + tr(e["t"]) + " " + _help_strip_html(tr(e["a"]))})
    for title, body in _help_read_kb():                  # manual (cobertura)
        docs.append({"title": title, "kind": "kb", "ref": "Manual do usuário",
                     "answer": _help_kb_to_html(body), "text": title + " " + body,
                     "so_completo": _help_cita_tela_oculta(title + " " + body)})
    for code, (t, msg, _b) in ERROR_CATALOG.items():     # catalogo de erros
        docs.append({"title": f"{tr('Erro')} {code} — {tr(t)}", "kind": "err",
                     "ref": tr("Ajuda → Diagnóstico de erros"), "answer": tr(msg),
                     "text": f"{code} {t} {msg} {tr(t)} {_help_strip_html(tr(msg))}"})
    df = {}
    for d in docs:
        d["tok"] = _help_tokens(d["text"])
        for term in d["tok"]:
            df[term] = df.get(term, 0) + 1
    n = max(1, len(docs))
    _HELP_IDF = {term: math.log((n + 1) / (c + 1)) + 1.0 for term, c in df.items()}
    _HELP_CORPUS = docs
    return _HELP_CORPUS, _HELP_IDF


# Sinônimos e coloquialismos → termos canônicos do índice. O usuário pergunta
# "como salvo os dados?" e a FAQ fala em "exportar": sem esta ponte a busca
# TF-IDF não encontra nada e o consultor responde "tema não mapeado".
_HELP_SINONIMOS = {
    "salvar":     ("exportar", "dados"),
    "baixar":     ("exportar",),
    "extrair":    ("exportar",),
    "planilha":   ("csv", "tabela"),
    "excel":      ("csv", "tabela"),
    "figura":     ("grafico",),
    "figuras":    ("grafico",),
    "imagem":     ("grafico", "captura"),
    "print":      ("grafico", "captura"),
    "onda":       ("bandas",),
    "ondas":      ("bandas",),
    "smr":        ("mu", "sensorio", "motor"),
    "sensoriomotor": ("mu", "sensorio", "motor"),
    "melhora":    ("evolucao", "paciente"),
    "melhorou":   ("evolucao", "paciente"),
    "piora":      ("evolucao", "paciente"),
    "piorou":     ("evolucao", "paciente"),
    "progresso":  ("evolucao", "paciente"),
    "acompanhamento": ("evolucao", "historico"),
    "upar":       ("importar", "arquivo"),
    "upload":     ("importar", "arquivo"),
    "abrir":      ("importar", "carregar"),
    "eletrodo":   ("canais", "mapeamento"),
    "eletrodos":  ("canais", "mapeamento"),
    "touca":      ("impedancia", "calibracao"),
    "ingles":     ("idioma",),
    "espanhol":   ("idioma",),
    "language":   ("idioma",),
    "cronometro": ("protocolo", "tempos"),
    "piscada":    ("eog", "piscadas"),
    "coracao":    ("ecg", "hrv"),
    "musculo":    ("emg",),
    "musculos":   ("emg",),
    "fadiga":     ("mdf", "emg"),
}


def _help_quer_definicao(qn):
    """A pergunta (já normalizada) pede uma DEFINIÇÃO ("o que é", "o que quer
    dizer", "significa")? Vale para o glossário passar na frente e para o guia
    de procedimento NÃO ser promovido (G22)."""
    return bool(re.search(
        r"\b(o que (e|eh|sao|significa|quer dizer)|que (e|eh) (o|a)?|significa|"
        r"defini(cao|r)|sigla|abreviacao)\b", qn)
        # russo, japonês e chinês: sem \b, porque kana e ideograma são letra
        # colada na sigla ("hrvとは", "hrv是什么")
        or re.search(r"что такое|что значит|что означает|расшифров|"
                     r"とは|意味|定義|是什么|什么是|含义|定义|意思", qn))


def help_answer(query, limit=3, nivel=None, modalidade=None):
    """Busca OFFLINE por recuperacao TF-IDF sobre FAQ + manual + erros. Retorna
    [(título, resposta_html, ref, tipo)]. NADA sai da máquina.

    `nivel` "simples": ficam de fora os documentos que citam telas ocultas e
    os cartões de método (Área Maker). `modalidade` (EEG/EMG/ECG/EoG, o exame
    em uso) desempata quando a pergunta não cita nenhuma (G22)."""
    q = (query or "").strip()
    if not q:
        return []
    m = _HELP_CODIGO_ERRO.search(q.upper())              # codigo de erro explicito
    if m and m.group() in ERROR_CATALOG:
        code = m.group(); title, msg, _b = error_info(code)
        return [(f"Erro {code} — {title}", msg,
                 "Ajuda → Diagnóstico de erros", "err")]
    qtok = _help_tokens(q)
    if not qtok:
        return []
    # expansão por sinônimos: cada termo coloquial adiciona seus canônicos
    extra = set()
    for t in list(qtok):
        for s in _HELP_SINONIMOS.get(t, ()):
            extra |= _help_tokens(s)
    # A expansão por sinônimo vale METADE da palavra digitada. Com peso
    # igual, "fadiga" (que expande para "mdf") fazia "MPR fadiga EMG" cair
    # no cartão da MDF em vez do da MPR: o sinônimo pesava tanto quanto o
    # nome do método que a pessoa escreveu.
    literal = set(qtok)
    # Quem escreve o NOME de um método fez uma pergunta específica: a
    # expansão por sinônimo ("fadiga" → "mdf") existe para a pergunta vaga
    # e, aplicada aqui, levava "MPR fadiga EMG" para o cartão da MDF.
    if not _help_pergunta_nomeia_metodo(q):
        qtok = qtok | extra
    docs, idf = _help_corpus()
    qn = _help_norm(q)
    # "o que é HRV?" e "como leio a HRV?" são perguntas diferentes e a segunda
    # abafava a primeira: o guia de ECG cita a sigla dezenas de vezes, o
    # verbete do glossário cita uma. Quando a frase é pedido de DEFINIÇÃO, o
    # glossário passa na frente; nas demais, ele fica atrás dos guias.
    quer_definicao = _help_quer_definicao(qn)
    # a modalidade CITADA na pergunta decide (×1.9 / ×0.45); o exame em uso
    # só desempata de leve, para não esconder o guia de procedimento atrás
    # dos cartões de método do exame (G22)
    mod_citada = _help_modalidade_da_pergunta(qn)
    mod_alvo = mod_citada or (modalidade if modalidade in _HELP_MOD_PISTAS else None)
    fator_mod = (1.9, 0.45) if mod_citada else (1.25, 1.0)
    simples = (nivel == "simples")
    scored = []
    for d in docs:
        # no Simples, nada que mande para tela oculta nem cartão de método
        if simples and (d.get("so_completo") or d["kind"] == "metodo"):
            continue
        inter = qtok & d["tok"]
        if not inter:
            continue
        score = sum(idf.get(term, 1.0) * (1.0 if term in literal else 0.5)
                    for term in inter)
        score *= d.get("peso", 1.35 if d["kind"] == "faq" else 1.0)
        if d["kind"] == "kb":
            # Seção do manual é texto corrido e comprido: acumula colisão de
            # token só por tamanho. Normalizar pelo comprimento resolveria
            # isso e criaria outro problema — os verbetes de erro, que são
            # curtíssimos, passariam a ganhar de tudo (medido: a acurácia da
            # busca caiu de 21/22 para 8/16). O desconto fixo corrige o viés
            # sem inverter a balança; o manual continua sendo a rede que pega
            # o que os guias não cobrem.
            score *= 0.80
        if d["kind"] == "glo":
            # "o que é HRV?" (sigla na pergunta) vai para o verbete; "o que
            # significa Sinal OK?" não é sigla e fica com a FAQ leiga (G22)
            if quer_definicao:
                score *= 2.2 if d.get("sigla") in qtok else 1.4
            else:
                score *= 0.7
        if d["kind"] == "metodo" and quer_definicao and not (
                qtok & _help_tokens(d["title"])):
            # "o que é impedância?" tem definição no glossário. O cartão de
            # método que apenas CITA a palavra no passo a passo não pode
            # passar na frente do verbete que a define.
            score *= 0.55
        if d["kind"] in ("faq", "guia"):                  # conteudo curado na frente
            score += difflib.SequenceMatcher(None, qn, _help_norm(d["text"][:120])).ratio()
        if d["kind"] == "metodo":
            # O TÍTULO pesa mais que o corpo. Com 101 métodos, cartões irmãos
            # se citam no passo a passo ("compare com a inclinação da MPR"),
            # e "MPR fadiga EMG" passou a cair no cartão da MDF, cujo guia
            # menciona a MPR. Os tokens que batem no título contam de novo,
            # pelo mesmo IDF: quem tem a palavra no NOME ganha de quem só a
            # cita.
            # Contado por PALAVRA da pergunta, não por token: o radical e a
            # palavra inteira viram dois tokens ("fadig" e "fadiga"), e por
            # token "fadiga" pesava o dobro de "MPR". E só a partir de duas
            # palavras no título: uma palavra rara sozinha ("piscadas") não
            # pode tirar da frente o guia de procedimento que a cita.
            # Em chinês e japonês não há espaço entre palavras, e a contagem
            # sai das sequências de bigramas (ver _help_bate_titulo).
            n_bate, bonus_titulo = _help_bate_titulo(
                qn, _help_tokens(d["title"]), idf)
            if n_bate >= 2:
                score += bonus_titulo
            # A pergunta que cita a modalidade quer o método daquela
            # modalidade. Sem este desempate, "como meço fadiga?" caía tanto
            # em EMG quanto em EoG pela contagem de tokens, que é loteria.
            # A penalidade não se aplica quando o TÍTULO casa com três ou
            # mais palavras: "correção ocular por regressão do EoG" é um
            # método de EEG cujo nome cita o EoG, e a pista de modalidade
            # (que lê "ocular", "eog") o jogava para trás dos cartões de EoG.
            if mod_alvo and d.get("modalidade") == mod_alvo:
                score *= fator_mod[0]
            elif mod_alvo and n_bate < 3:
                score *= fator_mod[1]
        no_titulo = qtok & _help_tokens(d["title"])
        if no_titulo:
            # O bônus é proporcional à RARIDADE do que casou. Com bônus fixo,
            # "Dimitrov" no título valia o mesmo que "banda", e a pergunta
            # "para que serve o índice de Dimitrov?" era vencida por um
            # documento que só tinha as palavras comuns. Nome próprio de
            # método tem IDF alto justamente por ser distintivo.
            score += 1.0 + 1.5 * sum(idf.get(t, 1.0) for t in no_titulo) /                 len(no_titulo)
        # A pergunta que traz o TÍTULO INTEIRO de uma FAQ ou guia ("onde ficam
        # minhas gravações") quer aquele verbete: o guia de atualização, que
        # repete "gravações" dez vezes, passava na frente da FAQ com esse
        # exato nome (validação com leigos, G22).
        if d["kind"] in ("faq", "guia"):
            tit_n = _help_norm(d["title"])
            if len(tit_n) >= 12 and tit_n in qn:
                score *= 2.0
        scored.append((score, d))
    if not scored:
        return []
    scored.sort(key=lambda x: x[0], reverse=True)
    if scored[0][0] < 1.2:                               # limiar de relevancia
        return []
    # ASSUNTO DE FORA. "qual a receita de brigadeiro?" casava com o verbete de
    # Receitas de análise: a palavra existe mesmo no índice, e o limiar de
    # pontuação sozinho não distingue colisão de vocabulário de pergunta de
    # verdade. O sinal melhor é o resto da frase — se a maior parte das
    # palavras da pergunta é desconhecida ao programa inteiro, o encontro numa
    # palavra só é coincidência. Devolver vazio faz o assistente mostrar o
    # índice de guias, que ajuda mais que uma resposta confiante e errada.
    # Só as palavras COMO FORAM ESCRITAS: _help_tokens devolve palavra e
    # radical, e contar os dois faria "brigadeiro" valer por dois, empatando a
    # conta que esta guarda existe para desempatar.
    base = {t for cjk, t in _help_trechos(qn)
            if not cjk and len(t) > 3 and t not in _HELP_STOP}
    if len(base) >= 2:
        # Conhecida = a palavra OU o radical dela está no índice. Exigir a
        # forma escrita reprovaria "exporto", que só existe no índice como
        # "export" — e a pergunta escrita em primeira pessoa é justamente a
        # que mais aparece.
        conhecidas = {t for t in base
                      if t in idf or _help_radical(t) in idf}
        if len(conhecidas) <= 1:
            return []
    # O mesmo juízo para chinês e japonês, onde não há palavra para contar.
    # Bigrama solto engana: "チョコレートケーキの作り方" achava a "COMポート"
    # pelo pedaço "ート" de チョコレート. Aqui a pergunta é outra: o documento
    # que ficou em primeiro cobre ao menos metade dos caracteres da pergunta?
    # Pergunta de verdade cobre (ノッチフィルタの設定 → a ficha de filtros
    # tem ノッチ, フィルタ e 設定); colisão de sílaba não.
    cob = _help_cobertura_cjk(qn, scored[0][1]["tok"])
    if cob is not None and cob < 0.5:
        return []
    out, seen = [], set()
    for _s, d in scored:
        if d["title"] in seen:
            continue
        seen.add(d["title"])
        # O tipo vai junto: quem consome precisa saber se ganhou um guia
        # (procedimento) ou um verbete, para decidir a ordem da cascata.
        resposta = (d["answer_simples"] if (simples and d.get("answer_simples"))
                    else d["answer"])
        out.append((d["title"], resposta, d["ref"], d["kind"]))
        if len(out) >= limit:
            break
    return out


# ============================================================
# Consultor metodológico — raciocínio focado sobre GUIA_METODOLOGICO.md
# (offline: nada sai da máquina; respostas embasadas em literatura)
# ============================================================
_GUIA_CACHE = None


def _html_escape(s):
    """Escapa texto antes de embuti-lo no HTML dos balões do consultor.

    Usado principalmente nos links 'ask:' de aprofundamento, onde rótulo e
    pergunta vão parar dentro de um atributo href entre aspas simples.
    """
    return (str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace("'", "&#39;").replace('"', "&quot;"))


def _help_read_guia():
    """Lê GUIA_METODOLOGICO.md e devolve [(título, corpo, refs)] por seção '## '.
    Separa a linha '> Refs:' do corpo. Cacheado. Tudo OFFLINE."""
    global _GUIA_CACHE
    if _GUIA_CACHE is not None:
        return _GUIA_CACHE
    txt = _help_load_text("GUIA_METODOLOGICO.md", GUIA_METODOLOGICO_EMBED)
    out = []
    for chunk in re.split(r"\n##\s+", txt or ""):
        chunk = chunk.strip()
        if not chunk or chunk.startswith("#"):
            continue
        parts = chunk.split("\n", 1)
        title = parts[0].lstrip("# ").strip()
        if title.lower().startswith("refer"):
            continue
        body = parts[1].strip() if len(parts) > 1 else ""
        refs = ""
        mref = re.search(r"(?ms)^>\s*Refs?:\s*(.+?)\s*$", body)
        if mref:
            refs = re.sub(r"\s+", " ", mref.group(1)).strip().rstrip(".")
            body = body[:mref.start()].strip()
        if len(body) > 20:
            out.append((title, body, refs))
    _GUIA_CACHE = out
    return out


def _md_to_chat_html(text):
    """Converte um trecho markdown (do guia) em HTML de balão de chat:
    **negrito**, *itálico*, listas numeradas/marcadas e citações [Autor ANO]."""
    import html as _html
    acc = COLORS.get("accent", "#0f9d75")

    def fmt(t):
        """Aplica a formatação inline de um bloco do guia: escapa HTML, converte
        **negrito** e *itálico* e realça citações bibliográficas na cor de
        destaque.

        A citação é reconhecida por qualquer colchete que contenha 4 dígitos (o
        ano), não por uma lista de autores.
        """
        t = _html.escape(t)
        t = re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", t)
        t = re.sub(r"\*(.+?)\*", r"<i>\1</i>", t)
        t = re.sub(r"\[([^\]\[]*?\d{4}[^\]\[]*?)\]",
                   r"<span style='color:%s'>[\1]</span>" % acc, t)
        return t

    # 1) junta linhas QUEBRADAS da fonte em blocos (parágrafo/item de lista) até
    #    linha em branco ou novo marcador — senão '**negrito**' partido em duas
    #    linhas do .md não é formatado.
    blocks, cur = [], None
    for ln in text.split("\n"):
        s = ln.rstrip()
        if not s.strip() or s.lstrip().startswith(">"):
            if cur:
                blocks.append(cur); cur = None
            continue
        m_num = re.match(r"^\s*(\d+)\.\s+(.*)", s)
        m_bul = re.match(r"^\s*[-•]\s+(.*)", s)
        if m_num:
            if cur:
                blocks.append(cur)
            cur = ["num", m_num.group(1), m_num.group(2)]
        elif m_bul:
            if cur:
                blocks.append(cur)
            cur = ["bul", None, m_bul.group(1)]
        elif cur:                       # continuação: anexa ao bloco atual
            cur[2] += " " + s.strip()
        else:
            cur = ["p", None, s.strip()]
    if cur:
        blocks.append(cur)
    # 2) renderiza
    html, in_ul = [], False
    for typ, mark, txt in blocks:
        if typ == "bul":
            if not in_ul:
                html.append("<ul style='margin:3px 0 3px 4px'>"); in_ul = True
            html.append("<li style='margin:2px 0'>%s</li>" % fmt(txt))
            continue
        if in_ul:
            html.append("</ul>"); in_ul = False
        if typ == "num":
            html.append("<div style='margin:3px 0'><b>%s.</b> %s</div>"
                        % (mark, fmt(txt)))
        else:
            html.append("<div style='margin:4px 0'>%s</div>" % fmt(txt))
    if in_ul:
        html.append("</ul>")
    return "".join(html)


