def consultor_answer(query):
    """Consultor metodológico: classifica a INTENÇÃO e devolve UMA resposta
    focada (não despeja trechos). Retorna dict ou None. Base: GUIA + literatura."""
    secs = _help_read_guia()
    if not secs:
        return None
    qtok = _help_tokens(query)
    if not qtok:
        return None
    best, best_score = None, 0
    for meta in _GUIA_META:
        score = len(qtok & _help_tokens(meta["hint"]))
        score += 2 * len(qtok & _help_tokens(meta.get("strong", "")))
        if score > best_score:
            best_score, best = score, meta
    if not best or best_score < 1:
        return None
    sec = next((s for s in secs
                if _help_norm(best["match"]) in _help_norm(s[0])), None)
    if not sec:
        return None
    title, body, refs = sec
    return {"kind": "guia", "title": title, "lead": best["lead"],
            "body_html": _md_to_chat_html(body), "refs": refs,
            "follow": best["follow"], "score": best_score}


# Quanto o consultor precisa pontuar para tomar a frente de um cartão de
# método. Os seis temas dele pontuam de 8 a 23 quando a pergunta é mesmo
# deles; acidente de vocabulário fica entre 1 e 7.
_HELP_CONSULTOR_FORTE = 8


def _help_consultor_vence(c, hits, pergunta):
    """Decide se o consultor metodológico responde antes da busca.

    O consultor cobre seis temas de metodologia de EEG/BCI e pontua por
    contagem de palavras, o que o fazia ganhar longe do tema quando uma
    palavra tinha dois sentidos. "fadiga" aparece no texto sobre número de
    trials, então "MPR fadiga EMG" era respondido com imagética motora;
    "EMG" e "muscular" aparecem no texto sobre artefato no EEG, então "como
    medir fadiga muscular por EMG" era respondido com ICA. Nos dois casos a
    busca tinha o cartão certo em primeiro lugar.

    Regra: acerto direto da busca — um guia ou um cartão de método — só perde
    para o consultor quando ele pontua alto E a pergunta não é de outra
    modalidade.
    """
    if not c or c["score"] < 2:
        return False
    if not hits:
        return True
    tipo = hits[0][3]
    if tipo not in ("guia", "metodo"):
        return True
    if tipo == "guia":
        return False
    mod = _help_modalidade_da_pergunta(_help_norm(pergunta))
    return (c["score"] >= _HELP_CONSULTOR_FORTE
            and mod in (None, "EEG"))


def _help_pergunta_nomeia_metodo(pergunta):
    """A pergunta cita o nome de algum método do catálogo?

    É o que separa "o sinal está cheio de ruído, o que faço?" — que não cita
    nada e quer um procedimento — de "SDNN ECG", que cita e quer a ficha
    daquele método.
    """
    qn = " %s " % _help_norm(pergunta)
    for m in CATALOGO_METODOS:
        # O nome vale no português do catálogo e no idioma ativo: quem usa a
        # interface em russo escreve "Амплитуда Уиллисона", não "Amplitude
        # Willison". NFKC troca os parênteses de largura cheia do chinês e do
        # japonês ("（SSC）") pelos comuns, que o recorte abaixo procura.
        for cru in dict.fromkeys((m["rotulo"],
                                  unicodedata.normalize("NFKC", tr(m["rotulo"])))):
            # _help_norm apaga a pontuação, então os pedaços do rótulo saem do
            # texto CRU: "MDF (frequência mediana)" vira os candidatos "MDF",
            # "frequência mediana" e o rótulo inteiro.
            pedacos = [cru, cru.split("(")[0]] + re.findall(r"\(([^)]+)\)", cru)
            # A sigla que abre o rótulo também é nome do método: "MPR fadiga"
            # cita a MPR, mesmo sem escrever "MPR média/baixa" inteiro.
            primeira = cru.split()[0] if cru.split() else ""
            if len(primeira) >= 3 and primeira.isupper():
                pedacos.append(primeira)
            for parte in pedacos:
                parte = _help_norm(parte).strip()
                if _HELP_CJK.search(parte):
                    # sem espaço entre palavras: basta o nome aparecer
                    if len(parte) >= 2 and parte in qn:
                        return True
                elif len(parte) >= 3 and (" %s " % parte) in qn:
                    return True
    return False


def _help_promove_guia(hits, pergunta):
    """Põe na frente o guia que estiver entre os primeiros resultados.

    "o sinal está cheio de ruído, o que faço?" é pergunta de procedimento e
    tem um guia inteiro chamado "Deixar o sinal limpo antes de gravar" — que
    saía em segundo lugar, atrás de um cartão de método. O guia responde
    COMO; é o que a pessoa quer quando descreve um problema.

    Promover sempre era pior do que não promover: "SDNN ECG" passava a cair
    no guia de leitura do painel de HRV em vez da ficha do SDNN. Por isso a
    promoção só vale quando a pergunta não cita nenhum método pelo nome.
    """
    if not hits or hits[0][3] == "guia":
        return hits
    if _help_pergunta_nomeia_metodo(pergunta):
        return hits
    # "o que quer dizer Sinal OK?" pede uma explicação, não um procedimento:
    # o verbete fica na frente do guia (G22)
    if _help_quer_definicao(_help_norm(pergunta)):
        return hits
    i = next((k for k, h in enumerate(hits) if h[3] == "guia"), None)
    if i is None:
        return hits
    return [hits[i]] + [h for k, h in enumerate(hits) if k != i]


class HelpAssistantDialog(QtWidgets.QDialog):
    """Consultor ROA (OFFLINE): raciocina sobre a intenção e responde de
    forma FOCADA — metodologia embasada (GUIA + literatura), uso do software
    (FAQ/manual) e erros (catálogo). NENHUMA informação sai da máquina."""

    def __init__(self, parent=None):
        """Monta a janela do consultor offline: área de conversa, botões-atalho
        por tema, campo de pergunta e botão Perguntar.

        setOpenLinks/setOpenExternalLinks são desligados de propósito porque os
        links 'ask:' são interceptados por _on_anchor. O histórico fica em
        self._html e é reescrito por inteiro a cada nova mensagem.
        """
        super().__init__(parent)
        self.setWindowTitle(tr("Consultor ROA (offline)"))
        self.setMinimumSize(720, 640)
        v = QtWidgets.QVBoxLayout(self)
        self.view = QtWidgets.QTextBrowser()
        # a folha do app põe monoespaçada em QTextEdit (dados) e o QTextBrowser
        # herdava: a conversa saía em letra de máquina de escrever (G22)
        self.view.setStyleSheet("QTextBrowser { font-family: %s; font-size: %dpt; }"
                                % (FONT_UI_STACK, _pt(11)))
        self.view.setOpenLinks(False)          # tratamos os links (ask:/http)
        self.view.setOpenExternalLinks(False)
        self.view.anchorClicked.connect(self._on_anchor)
        v.addWidget(self.view, 1)
        # atalhos por tema (metodologia + software)
        chips = QtWidgets.QHBoxLayout()
        atalhos = ((tr("Planejar estudo (MS)"), "como abordar estudo de imaginação "
                    "motora de membro superior"),
                   (tr("ERD/ERS"), "o que é ERD/ERS e como calcular"),
                   (tr("Artefatos/ICA"), "como limpar artefatos piscadas ICA"),
                   (tr("Validação"), "classificação e validação sem vazamento"),
                   (tr("Topografia/LORETA"), "topografia LORETA localização de fonte"),
                   (tr("Erros (E0XX)"), "código de erro"))
        # No modo simples os atalhos são as 4 tarefas do operador de exame.
        # A pergunta é o título da entrada do FAQ (em pt, como nos guias): a
        # busca devolve o guia passo a passo e a própria entrada.
        cfg = getattr(parent, "config", None)
        # nível e exame em uso entram na busca (G22)
        self._nivel = (getattr(cfg, "ui_level", "simples") if cfg is not None
                       else "avancado")
        self._modalidade = getattr(cfg, "acquisition_mode", None) if cfg is not None else None
        if self._nivel == "simples":
            atalhos = ((tr("Ligar o aparelho"), "Ligar o aparelho"),
                       (tr("Gravar um exame"), "Gravar um exame"),
                       (tr("Onde ficam minhas gravações"),
                        "Onde ficam minhas gravações"),
                       (tr("Salvar relatório em PDF"), "Salvar relatório em PDF"),
                       (tr("O que quer dizer Sinal OK"),
                        "O que quer dizer Sinal OK (e as cores)"))
        for label, q in atalhos:
            b = QtWidgets.QPushButton(label)
            b.setCursor(QtCore.Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _=False, t=q: self._ask(t))
            chips.addWidget(b)
        chips.addStretch(1)
        v.addLayout(chips)
        h = QtWidgets.QHBoxLayout()
        self.input = QtWidgets.QLineEdit()
        self.input.setPlaceholderText(
            tr("Pergunte com suas palavras (ex.: 'como ligo o aparelho?' · "
               "'o que quer dizer Sinal OK?' · 'onde fica o relatório?')…")
            if self._nivel == "simples" else
            tr("Pergunte como um consultor (ex.: 'como abordo EEG de membro superior?' · "
            "'qual banda para MI?' · 'E115')…"))
        self.input.returnPressed.connect(self._on_send)
        btn = QtWidgets.QPushButton(tr("Perguntar")); btn.clicked.connect(self._on_send)
        btn.setDefault(True)
        h.addWidget(self.input, 1); h.addWidget(btn)
        v.addLayout(h)
        try: self.setStyleSheet(build_stylesheet(COLORS))
        except Exception: pass
        self._html = []
        self._intro()

    # ---------- apresentação (balões) ----------
    def _intro(self):
        """Emite a mensagem de boas-vindas do consultor, delimitando o escopo
        (metodologia, uso do programa e códigos de erro) e oferecendo três
        perguntas de partida."""
        self._say("assistant",
                  tr("Olá! Sou o <b>Consultor ROA</b> — trabalho <b>100% offline</b> "
                     "(nada sai da sua máquina).<br><br>Pergunte do jeito que você "
                     "falaria: <i>“o sinal está cheio de ruído, o que faço?”</i>. "
                     "Quando a pergunta é <b>como fazer</b>, eu respondo com o "
                     "caminho inteiro — passo a passo, o que costuma dar errado e "
                     "a saída para cada tropeço. Quando é <b>o que é</b>, respondo "
                     "com a definição. E se você citar um código de erro (ex.: "
                     "<b>E115</b>), vou direto nele."),
                  # no Simples os dois estudos levam a guias ocultos (G22)
                  follow=[(tr("Ver todos os guias"), "guias")] + ([] if self._nivel == "simples" else [
                          (tr("Planejar um estudo de MS"),
                           "como abordar estudo de imaginação motora de membro superior"),
                          (tr("Comparar antes × depois"),
                           "como comparar antes e depois estatística")]))

    def _say(self, who, html, follow=None, refs=None):
        """Acrescenta um balão de conversa (do consultor ou do usuário), com
        referências e links de aprofundamento opcionais, e rola a view para o
        fim.

        Os balões são montados com <table>/bgcolor porque o QTextBrowser do Qt
        só entende um subconjunto antigo de HTML/CSS. Cada chamada faz setHtml
        da conversa inteira, então o custo cresce com o tamanho do histórico.
        """
        acc = COLORS.get("accent", "#0f9d75")
        surf = COLORS.get("surface_alt", "#efefef")
        usr = COLORS.get("surface", "#ffffff")
        dim = COLORS.get("text_dim", "#777")
        inner = html
        if refs:
            inner += (f"<div style='margin-top:8px;color:{dim};font-size:11px'>"
                      f"📚 <i>{refs}</i></div>")
        if follow:
            links = " &nbsp;·&nbsp; ".join(
                f"<a href='ask:{_html_escape(q)}' style='color:{acc};"
                f"text-decoration:none'>▸ {_html_escape(lbl)}</a>"
                for lbl, q in follow)
            inner += (f"<div style='margin-top:9px'>"
                      f"<span style='color:{dim};font-size:11px'>" + tr("Aprofundar:")
                      + "</span><br>"
                      f"{links}</div>")
        if who == "assistant":
            bubble = (
                f"<table cellspacing='0' cellpadding='0' width='88%'><tr>"
                f"<td width='4' bgcolor='{acc}'></td>"
                f"<td bgcolor='{surf}' style='padding:9px 12px'>"
                f"<b style='color:{acc}'>🤝 " + tr("Consultor") + f"</b><br>{inner}"
                f"</td></tr></table>")
            align = "left"
        else:
            bubble = (
                f"<table cellspacing='0' cellpadding='0' width='78%'><tr>"
                f"<td bgcolor='{usr}' style='padding:8px 12px;border:1px solid {surf}'>"
                f"<b style='color:{dim}'>" + tr("Você") + f"</b><br>{inner}"
                f"</td></tr></table>")
            align = "right"
        self._html.append(
            f"<table width='100%' cellspacing='0' cellpadding='0' "
            f"style='margin:7px 0'><tr><td align='{align}'>{bubble}</td></tr></table>")
        self.view.setHtml("".join(self._html))
        sb = self.view.verticalScrollBar(); sb.setValue(sb.maximum())

    def _on_send(self):
        """Envia o conteúdo do campo de texto (Enter ou botão) para o pipeline de
        resposta e limpa a caixa."""
        t = self.input.text().strip()
        if t:
            self.input.clear(); self._ask(t)

    def _on_anchor(self, url):
        """Trata cliques nos links dos balões: 'ask:' vira uma nova pergunta ao
        consultor, qualquer outro esquema é aberto no navegador do sistema.

        A pergunta chega percent-encoded dentro do href, daí o unquote antes de
        repassá-la.
        """
        s = url.toString()
        if s.startswith("ask:"):
            from urllib.parse import unquote
            self._ask(unquote(s[4:]))
        else:
            try: QtGui.QDesktopServices.openUrl(url)
            except Exception: pass

    # ---------- raciocínio: erro → consultor → software → escalonar ----------
    def _ask(self, text):
        """Pipeline de resposta do consultor, em cascata: código de erro E0XX,
        consultor metodológico, FAQ/manual e, por fim, uma mensagem honesta de
        tema não mapeado.

        O consultor metodológico só vence na primeira passagem com score maior
        ou igual a 2; abaixo disso o FAQ tem prioridade e a resposta do
        consultor é reaproveitada como terceira tentativa. O código de erro é
        achado por expressão regular — a letra E seguida de três dígitos, em
        qualquer ponto da frase.
        """
        self._say("user", text)
        # Pedido explícito do índice: quem digita "guias" quer ver o cardápio,
        # não a melhor correspondência para a palavra "guias".
        # A palavra vale em qualquer um dos nove idiomas: os manuais
        # traduzidos mandam digitá-la na língua do leitor.
        if _help_pede_guias(text):
            acc = COLORS.get("accent", "#0f9d75")
            self._say("assistant",
                      tr("Estes são os caminhos que eu percorro com você do "
                         "começo ao fim. Clique em um:")
                      + "<ol>" + "".join(
                          f"<li><a href='ask:{_html_escape(g['t'])}' "
                          f"style='color:{acc};text-decoration:none'>{tr(g['t'])}</a>"
                          f"</li>" for g in _help_guias_do_nivel(self._nivel)) + "</ol>")
            return
        up = text.upper()
        mcode = _HELP_CODIGO_ERRO.search(up)
        if mcode and mcode.group() in ERROR_CATALOG:
            code = mcode.group(); title, msg, _b = error_info(code)
            self._say("assistant",
                      f"<b>Erro {code} — {title}</b><br>{msg}", refs=None,
                      follow=[("Ver todos os erros", "código de erro"),
                              ("Onde fica o log", "onde fica o log de erros")])
            return
        # 1) Consultor metodológico e busca nos guias, avaliados JUNTOS.
        # Antes o consultor tinha a primeira palavra sempre que pontuava 2, e
        # com isso "o sinal está cheio de ruído, o que faço?" — uma pergunta
        # de procedimento — recebia uma aula sobre remoção de artefato por ICA
        # depois da coleta. São perguntas de naturezas diferentes: o consultor
        # responde POR QUE, o guia responde COMO. Quando a busca acha um guia,
        # ele vem primeiro e o consultor fica como aprofundamento.
        c = consultor_answer(text)
        hits = help_answer(text, limit=3, nivel=self._nivel,
                           modalidade=self._modalidade)
        # A promoção do guia é uma reordenação ENTRE resultados de busca, e
        # tem que vir depois da disputa com o consultor. Promovendo antes,
        # "como abordar um estudo de imaginação motora" — tema do consultor —
        # perdia para o guia de medir ERD/ERS, porque a promoção punha um
        # guia no topo e o guia faz o consultor recuar por regra.
        vence = _help_consultor_vence(c, hits, text)
        # no Simples sobram poucos guias e a promoção trazia o guia errado
        # ("Atualizar o programa…" para "como gravo um exame"); a FAQ leiga
        # responde (G22)
        hits = (hits if (vence or self._nivel == "simples")
                else _help_promove_guia(hits, text))
        if vence:
            self._say("assistant",
                      f"{c['lead']}<br><br>{c['body_html']}",
                      refs=c["refs"], follow=c["follow"])
            return
        # 2) Uso do software (guias + glossário + FAQ + manual + erros)
        if hits:
            title, ans, ref, _kind = hits[0]
            dim = COLORS.get("text_dim", "#777")
            # o cartão de método já começa pelo próprio título (G22)
            body = ans if _kind == "metodo" else f"<b>{title}</b><br>{ans}"
            if ref:
                body += f"<br><span style='color:{dim};font-size:11px'>↳ {ref}</span>"
            # no Simples os links de aprofundar são só FAQ e guias: "SNR —
            # Signal-to-Noise Ratio" e a metodologia são do Completo (G22)
            simples = (self._nivel == "simples")
            fol = [(t2, f"{t2}") for t2, _a, _r, _k in hits[1:3]
                   if not simples or _k in ("faq", "guia")]
            if c and not simples:                  # o "por quê" fica a um clique
                fol.append((tr("Por trás disso (metodologia)"), text + " metodologia"))
            fol.append((tr("Ver todos os guias"), "guias"))
            self._say("assistant", body, follow=fol)
            return
        # 3) fraco no consultor mas relevante? entrega mesmo assim
        if c:
            self._say("assistant",
                      f"{c['lead']}<br><br>{c['body_html']}",
                      refs=c["refs"], follow=c["follow"])
            return
        # 4) Não mapeado → mostrar O QUE EXISTE, não pedir para reformular.
        # A resposta antiga dizia "não tenho esse tema" e sugeria tentar outra
        # palavra-chave, o que devolve o problema para quem já não sabia o que
        # perguntar. Agora ela entrega o índice dos guias clicáveis: mesmo
        # errando a pergunta, a pessoa vê o caminho inteiro que existe.
        acc = COLORS.get("accent", "#0f9d75")
        indice = "".join(
            f"<li><a href='ask:{_html_escape(g['t'])}' "
            f"style='color:{acc};text-decoration:none'>{tr(g['t'])}</a></li>"
            for g in _help_guias_do_nivel(self._nivel))
        self._say("assistant",
                  tr("Não achei essa pergunta na minha base — e prefiro dizer "
                     "isso a inventar uma resposta. Estes são os caminhos que "
                     "eu sei percorrer com você do começo ao fim:")
                  + f"<ol>{indice}</ol>"
                  + tr("Se for uma sigla, pergunte <i>“o que é …?”</i>. Se for "
                       "um erro na tela, cite o código (ex.: <b>E001</b>)."),
                  follow=[(tr("Planejar um estudo (MS)"),
                           "como abordar estudo de membro superior"),
                          (tr("Ver temas de metodologia"), "metodologia"),
                          (tr("Diagnóstico de erros"), "código de erro")])


# ============================================================
# Bancada — grafo de blocos da Área Maker
# ------------------------------------------------------------
# O formulário de receita (métrica + banda + canais) resolve um caso e trava
# em qualquer outro. A Bancada é o degrau seguinte: blocos ligados por fios,
# como num editor de fluxo, para montar a análise que o laboratório precisa
# sem esperar que ela vire funcionalidade do programa.
#
# A ideia de editor de grafo com portas tipadas é comum a várias ferramentas
# da área (OpenViBE, Simulink, Node-RED). Aqui está ESCRITA DO ZERO, de
# propósito: o OpenViBE é AGPL-3 e o ROA é MIT — aproveitar a arquitetura é
# livre, copiar código tornaria o ROA inteiro AGPL.
# ============================================================

# Tipos que trafegam pelos fios. A porta só aceita ligação do mesmo tipo, o que
# impede montar um grafo que só quebraria na hora de rodar.
PORTA_TIPOS = {
    # chave        rótulo                       cor do fio
    "sinal":      ("Sinal (canais × tempo)",    "#1a23e0"),
    "tabela":     ("Tabela (rótulo → valor)",   "#0f9d75"),
    "numero":     ("Número",                    "#b8730a"),
    "texto":      ("Texto",                     "#6a1b9a"),
}


class ErroBloco(Exception):
    """Falha de um bloco, com o nome dele já embutido na mensagem.

    Existe para o erro chegar ao usuário dizendo QUAL bloco falhou. Uma
    exceção crua de numpy no meio de um grafo de 10 blocos não diz nada a
    quem montou o grafo.
    """


def _sinal_valido(v):
    """Confere o contrato do tipo 'sinal' e devolve (dados, sr, nomes)."""
    if not isinstance(v, dict) or "eeg" not in v:
        raise ErroBloco("esperava um sinal na entrada")
    eeg = np.asarray(v["eeg"], dtype=float)
    if eeg.ndim != 2 or eeg.size == 0:
        raise ErroBloco("o sinal está vazio ou não é canais × tempo")
    sr = float(v.get("sr") or SAMPLE_RATE)
    nomes = list(v.get("ch_names") or
                 [f"CH{i + 1}" for i in range(eeg.shape[0])])
    return eeg, sr, nomes


def _sinal(eeg, sr, nomes):
    """Monta o dicionário do tipo 'sinal'."""
    return {"eeg": np.asarray(eeg, dtype=float), "sr": float(sr),
            "ch_names": list(nomes)}


def _bl_entrada(ctx, _e, p):
    """Fonte: entrega a sessão carregada na Bancada."""
    ses = ctx.get("sessao")
    if not ses:
        raise ErroBloco("nenhuma sessão carregada na Bancada")
    eeg, sr, nomes = _sinal_valido(ses)
    return {"sinal": _sinal(eeg, sr, nomes)}


def _bl_canais(_c, e, p):
    """Fica só com os canais escolhidos (1-based, como o usuário conta)."""
    eeg, sr, nomes = _sinal_valido(e["sinal"])
    txt = str(p.get("canais", "")).strip()
    if not txt:
        return {"sinal": _sinal(eeg, sr, nomes)}
    idx = []
    for parte in txt.replace(";", ",").split(","):
        parte = parte.strip()
        if not parte:
            continue
        try:
            i = int(parte) - 1
        except ValueError:
            raise ErroBloco(f"'{parte}' não é número de canal")
        if not (0 <= i < eeg.shape[0]):
            raise ErroBloco(f"o sinal não tem o canal {parte}")
        idx.append(i)
    if not idx:
        raise ErroBloco("nenhum canal selecionado")
    return {"sinal": _sinal(eeg[idx], sr, [nomes[i] for i in idx])}


def _bl_recorte(_c, e, p):
    """Recorta um trecho de tempo, em segundos."""
    eeg, sr, nomes = _sinal_valido(e["sinal"])
    n = eeg.shape[1]
    t0 = p.get("t0"); t1 = p.get("t1")
    i0 = int(max(0.0, float(t0)) * sr) if t0 not in (None, "") else 0
    i1 = int(float(t1) * sr) if t1 not in (None, "") else n
    i0 = max(0, min(i0, n)); i1 = max(i0 + 1, min(i1, n))
    if i1 - i0 < 8:
        raise ErroBloco("o recorte ficou curto demais (menos de 8 amostras)")
    return {"sinal": _sinal(eeg[:, i0:i1], sr, nomes)}


def _bl_filtro(_c, e, p):
    """Passa-faixa Butterworth de fase zero (filtfilt), sem atraso."""
    eeg, sr, nomes = _sinal_valido(e["sinal"])
    lo = float(p.get("lo", 1.0)); hi = float(p.get("hi", 40.0))
    ny = 0.5 * sr
    lo_n, hi_n = max(1e-4, lo / ny), min(0.999, hi / ny)
    if not (0 < lo_n < hi_n < 1):
        raise ErroBloco(f"faixa inválida para {sr:.0f} Hz "
                        f"(o máximo é {ny:.0f} Hz)")
    if eeg.shape[1] < 25:
        raise ErroBloco("sinal curto demais para filtrar")
    sos = scipy_signal.butter(4, [lo_n, hi_n], btype="band", output="sos")
    return {"sinal": _sinal(scipy_signal.sosfiltfilt(sos, eeg, axis=1),
                            sr, nomes)}


def _bl_notch(_c, e, p):
    """Remove a frequência da rede elétrica (e harmônicos, se pedido)."""
    eeg, sr, nomes = _sinal_valido(e["sinal"])
    f0 = float(p.get("f0", 60.0)); q = float(p.get("q", 30.0))
    out = eeg.copy()
    n_harm = int(p.get("harmonicos", 1))
    for k in range(1, max(1, n_harm) + 1):
        f = f0 * k
        if f >= 0.49 * sr:
            break
        b, a = scipy_signal.iirnotch(f / (0.5 * sr), q)
        out = scipy_signal.filtfilt(b, a, out, axis=1)
    return {"sinal": _sinal(out, sr, nomes)}


def _bl_potencia(_c, e, p):
    """Potência numa faixa, canal a canal — a métrica mais usada em EEG."""
    eeg, sr, nomes = _sinal_valido(e["sinal"])
    lo = float(p.get("lo", 8.0)); hi = float(p.get("hi", 13.0))
    return {"tabela": {nomes[i]: SignalProcessor.compute_band_power(
        eeg[i], lo, hi, sr) for i in range(eeg.shape[0])}}


def _bl_rms(_c, e, _p):
    """RMS por canal — amplitude, a leitura padrão em EMG."""
    eeg, _sr, nomes = _sinal_valido(e["sinal"])
    return {"tabela": {nomes[i]: float(np.sqrt(np.mean(eeg[i] ** 2)))
                       for i in range(eeg.shape[0])}}


def _bl_envelope(_c, e, p):
    """Envelope RMS móvel — o traço que se usa para ver a ativação muscular."""
    eeg, sr, nomes = _sinal_valido(e["sinal"])
    jan = max(1, int(float(p.get("janela_ms", 150)) * sr / 1000.0))
    nucleo = np.ones(jan) / jan
    env = np.vstack([np.sqrt(np.convolve(eeg[i] ** 2, nucleo, mode="same"))
                     for i in range(eeg.shape[0])])
    return {"sinal": _sinal(env, sr, nomes)}


def _bl_cocontracao(_c, e, _p):
    """Co-contração (Falconer & Winter) entre pares de canais vizinhos."""
    eeg, _sr, nomes = _sinal_valido(e["sinal"])
    if eeg.shape[0] < 2:
        raise ErroBloco("são precisos pelo menos 2 canais para formar um par")
    out = {}
    for k in range(0, eeg.shape[0] - 1, 2):
        a = float(np.sqrt(np.mean(eeg[k] ** 2)))
        b = float(np.sqrt(np.mean(eeg[k + 1] ** 2)))
        s = a + b
        out[f"{nomes[k]}×{nomes[k + 1]}"] = (
            2.0 * min(a, b) / s * 100.0 if s > 1e-12 else 0.0)
    return {"tabela": out}


def _bl_razao(_c, e, _p):
    """Divide duas tabelas, chave a chave (ex.: teta ÷ beta)."""
    a, b = e["a"], e["b"]
    if not isinstance(a, dict) or not isinstance(b, dict):
        raise ErroBloco("as duas entradas têm de ser tabelas")
    comuns = [k for k in a if k in b]
    if not comuns:
        raise ErroBloco("as tabelas não têm nenhum rótulo em comum")
    return {"tabela": {k: (float(a[k]) / float(b[k])
                           if abs(float(b[k])) > 1e-12 else float("nan"))
                       for k in comuns}}


def _bl_normaliza(_c, e, p):
    """Põe a tabela em porcentagem de uma referência (máximo, soma ou valor)."""
    tab = e["tabela"]
    if not isinstance(tab, dict) or not tab:
        raise ErroBloco("tabela vazia")
    modo = str(p.get("modo", "maximo"))
    vals = [float(v) for v in tab.values() if np.isfinite(v)]
    if not vals:
        raise ErroBloco("a tabela não tem nenhum número válido")
    if modo == "soma":
        ref = float(np.sum(vals))
    elif modo == "valor":
        ref = float(p.get("referencia", 1.0) or 1.0)
    else:
        ref = float(np.max(vals))
    if abs(ref) < 1e-12:
        raise ErroBloco("a referência de normalização é zero")
    return {"tabela": {k: float(v) / ref * 100.0 for k, v in tab.items()}}


def _bl_estatistica(_c, e, _p):
    """Resumo da tabela: média, desvio, mínimo, máximo e n."""
    tab = e["tabela"]
    vals = np.array([float(v) for v in (tab or {}).values()], dtype=float)
    vals = vals[np.isfinite(vals)]
    if vals.size == 0:
        raise ErroBloco("a tabela não tem número válido para resumir")
    return {"tabela": {"média": float(np.mean(vals)),
                       "desvio padrão": float(np.std(vals, ddof=1))
                       if vals.size > 1 else 0.0,
                       "mínimo": float(np.min(vals)),
                       "máximo": float(np.max(vals)),
                       "n": float(vals.size)}}


def _bl_codigo(ctx, e, p):
    """Bloco AUTORAL: roda o Python que o usuário escreveu.

    Contrato: o código recebe `entrada` (o que chegou no fio), `np` e `sinal`
    (o módulo scipy.signal) e tem de atribuir o resultado a `saida`. O tipo de
    `saida` decide o que sai pela porta — dicionário com "eeg" vira sinal,
    dicionário simples vira tabela.

    ISTO NÃO É UMA CAIXA-FORTE. O código roda no mesmo processo do programa:
    dá para ler e apagar arquivo. O que existe aqui é um TRAVESSEIRO contra
    engano (nomes perigosos fora do alcance), não uma barreira contra quem
    queira fazer mal. Por isso a Bancada pede confirmação antes de rodar
    código vindo de um arquivo que você não escreveu.
    """
    codigo = str(p.get("codigo", "")).strip()
    if not codigo:
        raise ErroBloco("o bloco de código está vazio")
    if not ctx.get("codigo_liberado", True):
        raise ErroBloco("execução de código autoral não autorizada nesta sessão")
    escopo = {
        "np": np, "numpy": np, "sinal": scipy_signal, "math": math,
        "entrada": e.get("entrada"), "saida": None,
        # atalhos para não obrigar a saber o formato interno
        "monta_sinal": _sinal,
    }
    try:
        exec(compile(codigo, "<bloco de código>", "exec"), escopo)  # noqa: S102
    except ErroBloco:
        raise
    except Exception as exc:
        raise ErroBloco(f"{type(exc).__name__}: {exc}")
    saida = escopo.get("saida")
    if saida is None:
        raise ErroBloco("o código não atribuiu nada a `saida`")
    if isinstance(saida, dict) and "eeg" in saida:
        eeg, sr, nomes = _sinal_valido(saida)
        return {"saida": _sinal(eeg, sr, nomes)}
    if isinstance(saida, dict):
        return {"saida": {str(k): float(v) for k, v in saida.items()}}
    if isinstance(saida, (int, float, np.floating, np.integer)):
        return {"saida": {"resultado": float(saida)}}
    if isinstance(saida, np.ndarray):
        arr = np.atleast_2d(saida)
        return {"saida": _sinal(arr, SAMPLE_RATE,
                                [f"CH{i + 1}" for i in range(arr.shape[0])])}
    raise ErroBloco("`saida` tem de ser dicionário, número ou matriz")


def _bl_resultado(_c, e, _p):
    """Sumidouro: o que chega aqui é o que a Bancada mostra na tabela."""
    return {"_final": e.get("tabela")}


# Catálogo. Cada bloco declara o que consome e o que produz, e as portas são
# TIPADAS: a ligação só é aceita quando os tipos batem, então um grafo que o
# editor deixa montar é um grafo que roda.
BANCADA_BLOCOS = {
    "entrada":     {"nome": "Sessão carregada", "cat": "Fonte",
                    "ent": {}, "sai": {"sinal": "sinal"},
                    "params": {}, "fn": _bl_entrada,
                    "ajuda": "De onde o sinal entra no grafo."},
    "canais":      {"nome": "Escolher canais", "cat": "Sinal",
                    "ent": {"sinal": "sinal"}, "sai": {"sinal": "sinal"},
                    "params": {"canais": ""}, "fn": _bl_canais,
                    "ajuda": "Ex.: 1,2,5 (numeração que aparece na tela)."},
    "recorte":     {"nome": "Recortar tempo", "cat": "Sinal",
                    "ent": {"sinal": "sinal"}, "sai": {"sinal": "sinal"},
                    "params": {"t0": "", "t1": ""}, "fn": _bl_recorte,
                    "ajuda": "Início e fim em segundos. Vazio = tudo."},
    "filtro":      {"nome": "Passa-faixa", "cat": "Sinal",
                    "ent": {"sinal": "sinal"}, "sai": {"sinal": "sinal"},
                    "params": {"lo": 1.0, "hi": 40.0}, "fn": _bl_filtro,
                    "ajuda": "Butterworth de fase zero (não atrasa o sinal)."},
    "notch":       {"nome": "Tirar rede elétrica", "cat": "Sinal",
                    "ent": {"sinal": "sinal"}, "sai": {"sinal": "sinal"},
                    "params": {"f0": 60.0, "q": 30.0, "harmonicos": 1},
                    "fn": _bl_notch,
                    "ajuda": "60 Hz no Brasil, 50 Hz na Europa."},
    "envelope":    {"nome": "Envelope (EMG)", "cat": "Sinal",
                    "ent": {"sinal": "sinal"}, "sai": {"sinal": "sinal"},
                    "params": {"janela_ms": 150}, "fn": _bl_envelope,
                    "ajuda": "RMS móvel — o traço da ativação muscular."},
    "potencia":    {"nome": "Potência de banda", "cat": "Medida",
                    "ent": {"sinal": "sinal"}, "sai": {"tabela": "tabela"},
                    "params": {"lo": 8.0, "hi": 13.0}, "fn": _bl_potencia,
                    "ajuda": "Integral da PSD na faixa, por canal (µV²)."},
    "rms":         {"nome": "RMS por canal", "cat": "Medida",
                    "ent": {"sinal": "sinal"}, "sai": {"tabela": "tabela"},
                    "params": {}, "fn": _bl_rms,
                    "ajuda": "Amplitude eficaz — padrão em EMG."},
    "cocontracao": {"nome": "Co-contração (pares)", "cat": "Medida",
                    "ent": {"sinal": "sinal"}, "sai": {"tabela": "tabela"},
                    "params": {}, "fn": _bl_cocontracao,
                    "ajuda": "Lê os canais dois a dois: 1×2, 3×4, ..."},
    "razao":       {"nome": "Razão entre tabelas", "cat": "Combinar",
                    "ent": {"a": "tabela", "b": "tabela"},
                    "sai": {"tabela": "tabela"},
                    "params": {}, "fn": _bl_razao,
                    "ajuda": "Ex.: teta ÷ beta (TBR)."},
    "normaliza":   {"nome": "Normalizar (%)", "cat": "Combinar",
                    "ent": {"tabela": "tabela"}, "sai": {"tabela": "tabela"},
                    "params": {"modo": "maximo", "referencia": 1.0},
                    "fn": _bl_normaliza,
                    "ajuda": "modo: maximo, soma ou valor."},
    "estatistica": {"nome": "Resumo estatístico", "cat": "Combinar",
                    "ent": {"tabela": "tabela"}, "sai": {"tabela": "tabela"},
                    "params": {}, "fn": _bl_estatistica,
                    "ajuda": "Média, desvio, mínimo, máximo e n."},
    "codigo":      {"nome": "Código (Python)", "cat": "Autoral",
                    "ent": {"entrada": "sinal"}, "sai": {"saida": "tabela"},
                    "params": {"codigo": "# entrada: o sinal que chega\n"
                                         "# defina `saida`\n"
                                         "saida = {n: float(np.std(x))\n"
                                         "         for n, x in zip(\n"
                                         "             entrada['ch_names'],\n"
                                         "             entrada['eeg'])}\n"},
                    "fn": _bl_codigo,
                    "ajuda": "Seu próprio Python. Atribua o resultado a `saida`."},
    "resultado":   {"nome": "Resultado", "cat": "Saída",
                    "ent": {"tabela": "tabela"}, "sai": {},
                    "params": {}, "fn": _bl_resultado,
                    "ajuda": "O que chega aqui aparece na tabela final."},
}

BANCADA_VERSAO = "2.0"


class GrafoBancada:
    """O grafo: blocos, ligações, validação e execução.

    Separado da interface de propósito — dá para montar e rodar um grafo sem
    abrir janela nenhuma, o que torna isto testável e permite rodar uma
    bancada salva em lote, sobre várias sessões.
    """

    def __init__(self):
        """Cria um grafo vazio."""
        self.blocos = {}        # id -> {"tipo", "x", "y", "params"}
        self.ligacoes = []      # (id_orig, porta_saida, id_dest, porta_entrada)
        self._seq = 0

    # ---------------- montagem ----------------
    def add(self, tipo, x=0.0, y=0.0, params=None, bid=None):
        """Acrescenta um bloco e devolve o id dele."""
        if tipo not in BANCADA_BLOCOS:
            raise ErroBloco(f"bloco desconhecido: {tipo}")
        self._seq += 1
        bid = bid or f"b{self._seq}"
        base = dict(BANCADA_BLOCOS[tipo]["params"])
        base.update(params or {})
        self.blocos[bid] = {"tipo": tipo, "x": float(x), "y": float(y),
                            "params": base}
        return bid

    def remove(self, bid):
        """Tira o bloco e todos os fios presos nele."""
        self.blocos.pop(bid, None)
        self.ligacoes = [l for l in self.ligacoes
                         if l[0] != bid and l[2] != bid]

    def pode_ligar(self, orig, p_sai, dest, p_ent):
        """Diz se a ligação é válida — e, se não for, PORQUÊ.

        Devolve (True, "") ou (False, motivo). O motivo vai para a tela: um
        fio recusado sem explicação é a pior parte de um editor de grafo.
        """
        if orig not in self.blocos or dest not in self.blocos:
            raise ErroBloco("bloco inexistente")
        if orig == dest:
            return False, tr("um bloco não pode se ligar a si mesmo")
        t_sai = BANCADA_BLOCOS[self.blocos[orig]["tipo"]]["sai"].get(p_sai)
        t_ent = BANCADA_BLOCOS[self.blocos[dest]["tipo"]]["ent"].get(p_ent)
        if t_sai is None or t_ent is None:
            return False, tr("porta inexistente")
        if t_sai != t_ent:
            return False, tr("tipos diferentes: {} não encaixa em {}").format(
                PORTA_TIPOS.get(t_sai, (t_sai,))[0],
                PORTA_TIPOS.get(t_ent, (t_ent,))[0])
        if any(l[2] == dest and l[3] == p_ent for l in self.ligacoes):
            return False, tr("essa entrada já está ocupada")
        # ciclo: seguir de dest para frente não pode chegar em orig
        if self._alcanca(dest, orig):
            return False, tr("isso fecharia um ciclo")
        return True, ""

    def ligar(self, orig, p_sai, dest, p_ent):
        """Cria a ligação, se ela for válida."""
        ok, motivo = self.pode_ligar(orig, p_sai, dest, p_ent)
        if not ok:
            raise ErroBloco(motivo)
        self.ligacoes.append((orig, p_sai, dest, p_ent))

    def desligar(self, orig, p_sai, dest, p_ent):
        """Remove uma ligação específica."""
        self.ligacoes = [l for l in self.ligacoes
                         if l != (orig, p_sai, dest, p_ent)]

    def _alcanca(self, de, ate):
        """Existe caminho de `de` até `ate` seguindo os fios?"""
        vistos, pilha = set(), [de]
        while pilha:
            atual = pilha.pop()
            if atual == ate:
                return True
            if atual in vistos:
                continue
            vistos.add(atual)
            pilha.extend(l[2] for l in self.ligacoes if l[0] == atual)
        return False

    # ---------------- execução ----------------
    def ordem(self):
        """Ordem topológica: cada bloco só roda depois de quem o alimenta."""
        pend = {b: 0 for b in self.blocos}
        for _o, _ps, d, _pe in self.ligacoes:
            pend[d] = pend.get(d, 0) + 1
        fila = [b for b, n in pend.items() if n == 0]
        saida = []
        while fila:
            b = fila.pop(0)
            saida.append(b)
            for l in self.ligacoes:
                if l[0] == b:
                    pend[l[2]] -= 1
                    if pend[l[2]] == 0:
                        fila.append(l[2])
        if len(saida) != len(self.blocos):
            raise ErroBloco(tr("o grafo tem um ciclo"))
        return saida

    def executar(self, sessao, codigo_liberado=True):
        """Roda o grafo sobre uma sessão. Devolve (resultados, avisos).

        `resultados` mapeia id do bloco -> saídas dele, e a chave "_final"
        junta o que chegou aos blocos de Resultado. Bloco sem entrada ligada
        é PULADO com aviso, em vez de estourar: num grafo em construção é
        normal ter ponta solta, e travar tudo por isso atrapalha.
        """
        ctx = {"sessao": sessao, "codigo_liberado": bool(codigo_liberado)}
        valores, avisos, finais = {}, [], {}
        for bid in self.ordem():
            b = self.blocos[bid]
            spec = BANCADA_BLOCOS[b["tipo"]]
            entradas, faltou = {}, []
            for porta in spec["ent"]:
                fonte = next((l for l in self.ligacoes
                              if l[2] == bid and l[3] == porta), None)
                if fonte is None or fonte[0] not in valores:
                    faltou.append(porta)
                    continue
                entradas[porta] = valores[fonte[0]].get(fonte[1])
            if faltou:
                avisos.append(tr("{}: entrada '{}' não está ligada — pulado")
                              .format(tr(spec["nome"]), ", ".join(faltou)))
                continue
            try:
                valores[bid] = spec["fn"](ctx, entradas, b["params"]) or {}
            except ErroBloco as exc:
                avisos.append(f"{tr(spec['nome'])}: {exc}")
                continue
            except Exception as exc:      # noqa: BLE001 — bloco pode fazer tudo
                avisos.append(f"{tr(spec['nome'])}: {type(exc).__name__}: {exc}")
                continue
            if "_final" in valores[bid] and valores[bid]["_final"]:
                finais[bid] = valores[bid]["_final"]
        return {"blocos": valores, "finais": finais}, avisos

    # ---------------- arquivo ----------------
    def para_dict(self):
        """Serializa a bancada para .json."""
        return {"bancada_versao": BANCADA_VERSAO,
                "gerado_por": f"{APP_NAME} v{APP_VERSION}",
                "blocos": {b: dict(v) for b, v in self.blocos.items()},
                "ligacoes": [list(l) for l in self.ligacoes]}

    @classmethod
    def de_dict(cls, d):
        """Recria a bancada a partir do .json, ignorando o que não reconhece."""
        g = cls()
        for bid, b in (d.get("blocos") or {}).items():
            if b.get("tipo") not in BANCADA_BLOCOS:
                continue
            g.add(b["tipo"], b.get("x", 0), b.get("y", 0),
                  b.get("params"), bid=bid)
            try:
                g._seq = max(g._seq, int(str(bid).lstrip("b")))
            except ValueError:
                pass
        for l in (d.get("ligacoes") or []):
            if len(l) == 4 and l[0] in g.blocos and l[2] in g.blocos:
                ok, _m = g.pode_ligar(*l)
                if ok:
                    g.ligacoes.append(tuple(l))
        return g

    def tem_codigo(self):
        """Há bloco de código autoral? Decide se é preciso pedir permissão."""
        return any(b["tipo"] == "codigo" for b in self.blocos.values())


def bancada_exemplos():
    """Bancadas prontas, para começar de algo que já roda.

    Vale mais que documentação: o usuário abre, vê os fios ligados e mexe.
    """
    ex = {}

    g = GrafoBancada()
    a = g.add("entrada", 40, 120)
    b = g.add("notch", 240, 120, {"f0": 60.0})
    c = g.add("filtro", 440, 120, {"lo": 8.0, "hi": 13.0})
    d = g.add("potencia", 640, 120, {"lo": 8.0, "hi": 13.0})
    e = g.add("resultado", 840, 120)
    g.ligar(a, "sinal", b, "sinal"); g.ligar(b, "sinal", c, "sinal")
    g.ligar(c, "sinal", d, "sinal"); g.ligar(d, "tabela", e, "tabela")
    ex["Alfa por canal (EEG)"] = g

    g = GrafoBancada()
    a = g.add("entrada", 40, 60)
    t = g.add("potencia", 260, 20, {"lo": 4.0, "hi": 8.0})
    be = g.add("potencia", 260, 180, {"lo": 13.0, "hi": 30.0})
    r = g.add("razao", 500, 100)
    s = g.add("resultado", 720, 100)
    g.ligar(a, "sinal", t, "sinal"); g.ligar(a, "sinal", be, "sinal")
    g.ligar(t, "tabela", r, "a"); g.ligar(be, "tabela", r, "b")
    g.ligar(r, "tabela", s, "tabela")
    ex["Razão teta/beta (TBR)"] = g

    g = GrafoBancada()
    a = g.add("entrada", 40, 120)
    f = g.add("filtro", 220, 120, {"lo": 20.0, "hi": 120.0})
    en = g.add("envelope", 400, 120, {"janela_ms": 150})
    cc = g.add("cocontracao", 580, 120)
    s = g.add("resultado", 780, 120)
    g.ligar(a, "sinal", f, "sinal"); g.ligar(f, "sinal", en, "sinal")
    g.ligar(en, "sinal", cc, "sinal"); g.ligar(cc, "tabela", s, "tabela")
    ex["Co-contração de pares (EMG)"] = g

    g = GrafoBancada()
    a = g.add("entrada", 40, 120)
    f = g.add("filtro", 230, 120, {"lo": 1.0, "hi": 40.0})
    k = g.add("codigo", 420, 120, {"codigo":
        "# Fator de crista: pico dividido pelo RMS, canal a canal.\n"
        "# Serve para achar canal com artefato — um espigão sobe o pico\n"
        "# sem mexer muito no RMS.\n"
        "saida = {}\n"
        "for nome, x in zip(entrada['ch_names'], entrada['eeg']):\n"
        "    rms = float(np.sqrt(np.mean(x ** 2)))\n"
        "    saida[nome] = float(np.max(np.abs(x)) / rms) if rms > 0 else 0.0\n"})
    s = g.add("resultado", 640, 120)
    g.ligar(a, "sinal", f, "sinal"); g.ligar(f, "sinal", k, "entrada")
    g.ligar(k, "saida", s, "tabela")
    ex["Bloco autoral: fator de crista"] = g
    return ex


class _ItemPorta(QtWidgets.QGraphicsEllipseItem):
    """Bolinha de conexão. Guarda a que bloco/porta pertence e de que tipo é."""

    R = 6.0

    def __init__(self, bloco_item, nome, tipo, entrada):
        """Cria a bolinha, colorida pelo tipo que ela transporta."""
        super().__init__(-self.R, -self.R, 2 * self.R, 2 * self.R, bloco_item)
        self.bloco_item = bloco_item
        self.nome, self.tipo, self.entrada = nome, tipo, entrada
        cor = QtGui.QColor(PORTA_TIPOS.get(tipo, ("", "#888"))[1])
        self.setBrush(QtGui.QBrush(cor))
        self.setPen(QtGui.QPen(QtGui.QColor(COLORS["surface"]), 1.5))
        self.setToolTip(f"{tr(nome)} — {tr(PORTA_TIPOS.get(tipo, (tipo,))[0])}")
        self.setAcceptHoverEvents(True)
        self.setZValue(3)

    def hoverEnterEvent(self, ev):
        """Cresce ao passar o mouse: alvo pequeno é difícil de acertar."""
        self.setScale(1.5)
        super().hoverEnterEvent(ev)

    def hoverLeaveEvent(self, ev):
        """Volta ao tamanho normal."""
        self.setScale(1.0)
        super().hoverLeaveEvent(ev)


class _ItemBloco(QtWidgets.QGraphicsItem):
    """Caixa de um bloco: título, portas de entrada à esquerda e saídas à direita."""

    L, ALT_BASE, ESP = 170.0, 34.0, 22.0

    def __init__(self, bid, tipo, cena):
        """Monta a caixa e as portas do bloco, na altura que couber nelas."""
        super().__init__()
        self.bid, self.tipo, self.cena_b = bid, tipo, cena
        spec = BANCADA_BLOCOS[tipo]
        self.setFlags(QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemIsMovable
                      | QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemIsSelectable
                      | QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemSendsGeometryChanges)
        self.setToolTip(tr(spec.get("ajuda", "")))
        n = max(len(spec["ent"]), len(spec["sai"]), 1)
        self.alt = self.ALT_BASE + n * self.ESP
        self.portas = []
        for i, (nome, tipo_p) in enumerate(spec["ent"].items()):
            p = _ItemPorta(self, nome, tipo_p, True)
            p.setPos(0, self.ALT_BASE + i * self.ESP + self.ESP / 2)
            self.portas.append(p)
        for i, (nome, tipo_p) in enumerate(spec["sai"].items()):
            p = _ItemPorta(self, nome, tipo_p, False)
            p.setPos(self.L, self.ALT_BASE + i * self.ESP + self.ESP / 2)
            self.portas.append(p)

    def boundingRect(self):
        """Área do item, com folga para a borda de seleção."""
        return QtCore.QRectF(-8, -2, self.L + 16, self.alt + 6)

    def paint(self, p, _o, _w):
        """Desenha a caixa, a faixa do título e o nome das portas."""
        spec = BANCADA_BLOCOS[self.tipo]
        r = QtCore.QRectF(0, 0, self.L, self.alt)
        sel = self.isSelected()
        p.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        p.setBrush(QtGui.QBrush(QtGui.QColor(COLORS["surface"])))
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["accent"] if sel
                                         else COLORS["border"]),
                            2.0 if sel else 1.0))
        p.drawRoundedRect(r, 7, 7)
        # faixa do título, colorida pela categoria
        cores = {"Fonte": COLORS["accent"], "Sinal": "#2563c9",
                 "Medida": "#0f9d75", "Combinar": "#b8730a",
                 "Autoral": "#6a1b9a", "Saída": COLORS["error"]}
        p.setBrush(QtGui.QBrush(QtGui.QColor(cores.get(spec["cat"],
                                                       COLORS["accent"]))))
        p.setPen(QtCore.Qt.PenStyle.NoPen)
        cam = QtGui.QPainterPath()
        cam.addRoundedRect(QtCore.QRectF(0, 0, self.L, self.ALT_BASE - 6), 7, 7)
        cam.addRect(QtCore.QRectF(0, self.ALT_BASE - 14, self.L, 8))
        p.drawPath(cam)
        p.setPen(QtGui.QPen(QtGui.QColor("#ffffff")))
        f = p.font(); f.setBold(True); f.setPointSizeF(8.5); p.setFont(f)
        p.drawText(QtCore.QRectF(8, 0, self.L - 16, self.ALT_BASE - 6),
                   QtCore.Qt.AlignmentFlag.AlignVCenter, tr(spec["nome"]))
        # nome das portas (a chave da ligação continua a palavra em português)
        f.setBold(False); f.setPointSizeF(7.5); p.setFont(f)
        p.setPen(QtGui.QPen(QtGui.QColor(COLORS["text_dim"])))
        for porta in self.portas:
            y = porta.pos().y()
            if porta.entrada:
                p.drawText(QtCore.QRectF(10, y - 8, self.L / 2, 16),
                           QtCore.Qt.AlignmentFlag.AlignVCenter, tr(porta.nome))
            else:
                p.drawText(QtCore.QRectF(self.L / 2 - 10, y - 8,
                                         self.L / 2, 16),
                           QtCore.Qt.AlignmentFlag.AlignRight
                           | QtCore.Qt.AlignmentFlag.AlignVCenter, tr(porta.nome))

    def itemChange(self, mudanca, valor):
        """Ao mover o bloco, redesenha os fios presos nele."""
        if mudanca == QtWidgets.QGraphicsItem.GraphicsItemChange.ItemPositionHasChanged:
            self.cena_b.redesenhar_fios()
        return super().itemChange(mudanca, valor)


class _ItemFio(QtWidgets.QGraphicsPathItem):
    """Fio entre duas portas, desenhado como curva."""

    def __init__(self, lig, cor):
        """Cria o fio de uma ligação, na cor do tipo que ele carrega."""
        super().__init__()
        self.lig = lig
        self.setPen(QtGui.QPen(QtGui.QColor(cor), 2.2))
        self.setZValue(-1)
        self.setFlag(QtWidgets.QGraphicsItem.GraphicsItemFlag.ItemIsSelectable, True)

    def desenhar(self, p1, p2):
        """Curva de Bézier horizontal — lê melhor que reta quando há vários."""
        dx = max(40.0, abs(p2.x() - p1.x()) * 0.5)
        cam = QtGui.QPainterPath(p1)
        cam.cubicTo(p1 + QtCore.QPointF(dx, 0), p2 - QtCore.QPointF(dx, 0), p2)
        self.setPath(cam)


class BancadaCena(QtWidgets.QGraphicsScene):
    """Cena do editor: mantém a tela em sincronia com o GrafoBancada."""

    sigSelecionado = QtCore.Signal(str)      # id do bloco (ou "")
    sigAviso = QtCore.Signal(str)

    def __init__(self, grafo, parent=None):
        """Liga a cena a um GrafoBancada; a cena é só o espelho visual dele."""
        super().__init__(parent)
        self.grafo = grafo
        self.itens = {}          # bid -> _ItemBloco
        self.fios = []           # _ItemFio
        self._arrasto = None     # (porta_origem, linha_provisoria)
        self.selectionChanged.connect(self._mudou_selecao)

    def recarregar(self):
        """Redesenha tudo a partir do grafo — usado ao abrir um arquivo."""
        self.clear(); self.itens.clear(); self.fios.clear()
        for bid, b in self.grafo.blocos.items():
            item = _ItemBloco(bid, b["tipo"], self)
            item.setPos(b["x"], b["y"])
            self.addItem(item); self.itens[bid] = item
        self.redesenhar_fios()

    def _porta_em(self, bid, nome, entrada):
        """Acha o item de uma porta pelo bloco e nome."""
        item = self.itens.get(bid)
        if item is None:
            return None
        return next((p for p in item.portas
                     if p.nome == nome and p.entrada == entrada), None)

    def redesenhar_fios(self):
        """Refaz todos os fios (barato: são poucos, e assim nunca dessincroniza)."""
        for f in self.fios:
            self.removeItem(f)
        self.fios.clear()
        for lig in self.grafo.ligacoes:
            o, ps, d, pe = lig
            pa, pb = self._porta_em(o, ps, False), self._porta_em(d, pe, True)
            if pa is None or pb is None:
                continue
            fio = _ItemFio(lig, PORTA_TIPOS.get(pa.tipo, ("", "#888"))[1])
            fio.desenhar(pa.scenePos(), pb.scenePos())
            self.addItem(fio); self.fios.append(fio)

    def _mudou_selecao(self):
        """Avisa a janela qual bloco está selecionado, para mostrar os parâmetros."""
        sel = [i for i in self.selectedItems() if isinstance(i, _ItemBloco)]
        self.sigSelecionado.emit(sel[0].bid if sel else "")

    # ---- ligar arrastando de uma porta para outra ----
    def mousePressEvent(self, ev):
        """Começa um fio quando o clique cai numa porta."""
        item = self.itemAt(ev.scenePos(), QtGui.QTransform())
        if isinstance(item, _ItemPorta):
            linha = QtWidgets.QGraphicsPathItem()
            linha.setPen(QtGui.QPen(QtGui.QColor(COLORS["accent"]), 2.0,
                                    QtCore.Qt.PenStyle.DashLine))
            self.addItem(linha)
            self._arrasto = (item, linha)
            ev.accept(); return
        super().mousePressEvent(ev)

    def mouseMoveEvent(self, ev):
        """Acompanha o cursor com o fio provisório."""
        if self._arrasto:
            porta, linha = self._arrasto
            cam = QtGui.QPainterPath(porta.scenePos())
            cam.lineTo(ev.scenePos())
            linha.setPath(cam)
            ev.accept(); return
        super().mouseMoveEvent(ev)

    def mouseReleaseEvent(self, ev):
        """Fecha a ligação se soltou numa porta compatível; senão explica."""
        if self._arrasto:
            porta, linha = self._arrasto
            self.removeItem(linha)
            self._arrasto = None
            alvo = self.itemAt(ev.scenePos(), QtGui.QTransform())
            if isinstance(alvo, _ItemPorta) and alvo is not porta:
                # aceita arrastar nos dois sentidos: saída→entrada ou o inverso
                a, b = (porta, alvo) if not porta.entrada else (alvo, porta)
                if a.entrada or not b.entrada:
                    self.sigAviso.emit(tr("ligue uma saída a uma entrada"))
                else:
                    try:
                        ok, motivo = self.grafo.pode_ligar(
                            a.bloco_item.bid, a.nome, b.bloco_item.bid, b.nome)
                        if ok:
                            self.grafo.ligar(a.bloco_item.bid, a.nome,
                                             b.bloco_item.bid, b.nome)
                            self.redesenhar_fios()
                        else:
                            self.sigAviso.emit(motivo)
                    except ErroBloco as exc:
                        self.sigAviso.emit(str(exc))
            ev.accept(); return
        super().mouseReleaseEvent(ev)

    def keyPressEvent(self, ev):
        """Delete apaga o que estiver selecionado (bloco ou fio)."""
        if ev.key() in (QtCore.Qt.Key.Key_Delete, QtCore.Qt.Key.Key_Backspace):
            for item in list(self.selectedItems()):
                if isinstance(item, _ItemBloco):
                    self.grafo.remove(item.bid)
                    self.itens.pop(item.bid, None)
                    self.removeItem(item)
                elif isinstance(item, _ItemFio):
                    self.grafo.desligar(*item.lig)
            self.redesenhar_fios()
            self.sigSelecionado.emit("")
            ev.accept(); return
        super().keyPressEvent(ev)


class BancadaDialog(QtWidgets.QDialog):
    """A Bancada: monte a análise ligando blocos, rode e veja o resultado."""

    def __init__(self, main, sessao=None):
        """Monta paleta, tela do grafo, painel de parâmetros e área de resultado."""
        super().__init__(main)
        self.main = main
        self.sessao = sessao
        self.grafo = GrafoBancada()
        self._codigo_liberado = True     # grafo próprio: pode rodar código
        self.setWindowTitle(tr("Bancada — montar análise ligando blocos"))
        self.resize(1280, 780)

        raiz = QtWidgets.QVBoxLayout(self)
        intro = QtWidgets.QLabel(tr(
            "Arraste um bloco da lista para a tela, ligue a <b>saída</b> de um "
            "à <b>entrada</b> de outro e clique em <b>Rodar</b>. As portas são "
            "tipadas: o programa só deixa ligar o que encaixa, e diz o motivo "
            "quando recusa. Comece por um exemplo se preferir."))
        intro.setWordWrap(True)
        intro.setTextFormat(QtCore.Qt.TextFormat.RichText)
        raiz.addWidget(intro)

        div = QtWidgets.QSplitter(QtCore.Qt.Orientation.Horizontal)
        raiz.addWidget(div, 1)

        # ---- paleta ----
        esq = QtWidgets.QWidget(); ve = QtWidgets.QVBoxLayout(esq)
        ve.setContentsMargins(0, 0, 0, 0)
        ve.addWidget(QtWidgets.QLabel(tr("Blocos (duplo clique para inserir)")))
        self.paleta = QtWidgets.QTreeWidget()
        self.paleta.setHeaderHidden(True)
        self.paleta.setMinimumWidth(210)
        cats = {}
        for chave, spec in BANCADA_BLOCOS.items():
            pai = cats.get(spec["cat"])
            if pai is None:
                pai = QtWidgets.QTreeWidgetItem([tr(spec["cat"])])
                self.paleta.addTopLevelItem(pai); pai.setExpanded(True)
                cats[spec["cat"]] = pai
            it = QtWidgets.QTreeWidgetItem([tr(spec["nome"])])
            it.setData(0, QtCore.Qt.ItemDataRole.UserRole, chave)
            it.setToolTip(0, tr(spec.get("ajuda", "")))
            pai.addChild(it)
        self.paleta.itemDoubleClicked.connect(self._inserir_da_paleta)
        ve.addWidget(self.paleta, 1)
        div.addWidget(esq)

        # ---- tela do grafo ----
        self.cena = BancadaCena(self.grafo, self)
        self.cena.setSceneRect(0, 0, 2400, 1400)
        self.cena.sigSelecionado.connect(self._mostrar_params)
        self.cena.sigAviso.connect(self._avisar)
        self.vista = QtWidgets.QGraphicsView(self.cena)
        self.vista.setRenderHint(QtGui.QPainter.RenderHint.Antialiasing, True)
        self.vista.setDragMode(
            QtWidgets.QGraphicsView.DragMode.RubberBandDrag)
        self.vista.setBackgroundBrush(QtGui.QBrush(
            QtGui.QColor(COLORS["surface_alt"])))
        div.addWidget(self.vista)

        # ---- parâmetros + resultado ----
        dir_ = QtWidgets.QWidget(); vd = QtWidgets.QVBoxLayout(dir_)
        vd.setContentsMargins(0, 0, 0, 0)
        vd.addWidget(QtWidgets.QLabel(tr("Parâmetros do bloco selecionado")))
        self.caixa_params = QtWidgets.QWidget()
        self.form_params = QtWidgets.QFormLayout(self.caixa_params)
        self.form_params.setContentsMargins(0, 0, 0, 0)
        rolo = QtWidgets.QScrollArea(); rolo.setWidgetResizable(True)
        rolo.setWidget(self.caixa_params); rolo.setMinimumWidth(280)
        vd.addWidget(rolo, 1)
        vd.addWidget(QtWidgets.QLabel(tr("Resultado")))
        self.tabela = QtWidgets.QTableWidget(0, 2)
        self.tabela.setHorizontalHeaderLabels([tr("Rótulo"), tr("Valor")])
        self.tabela.horizontalHeader().setStretchLastSection(True)
        vd.addWidget(self.tabela, 1)
        self.log = QtWidgets.QPlainTextEdit(); self.log.setReadOnly(True)
        self.log.setMaximumHeight(90)
        vd.addWidget(self.log)
        div.addWidget(dir_)
        div.setSizes([210, 720, 330])

        # ---- barra de ações ----
        bt = QtWidgets.QHBoxLayout()
        self.cb_ex = QtWidgets.QComboBox()
        self.cb_ex.addItem(tr("— exemplos prontos —"), None)
        for nome in bancada_exemplos():
            self.cb_ex.addItem(tr(nome), nome)
        self.cb_ex.currentIndexChanged.connect(self._carregar_exemplo)
        bt.addWidget(self.cb_ex)
        b_ses = QtWidgets.QPushButton(tr("Carregar sessão…"))
        b_ses.clicked.connect(self._escolher_sessao)
        bt.addWidget(b_ses)
        self.lbl_ses = QtWidgets.QLabel(tr("(nenhuma sessão)"))
        self.lbl_ses.setStyleSheet(f"color:{COLORS['text_dim']};")
        bt.addWidget(self.lbl_ses, 1)
        b_rodar = QtWidgets.QPushButton(tr("▶ Rodar"))
        b_rodar.clicked.connect(self._rodar)
        bt.addWidget(b_rodar)
        b_abrir = QtWidgets.QPushButton(tr("Abrir…"))
        b_abrir.clicked.connect(self._abrir)
        bt.addWidget(b_abrir)
        b_salvar = QtWidgets.QPushButton(tr("Salvar…"))
        b_salvar.clicked.connect(self._salvar)
        bt.addWidget(b_salvar)
        b_csv = QtWidgets.QPushButton(tr("Exportar CSV…"))
        b_csv.clicked.connect(self._exportar)
        bt.addWidget(b_csv)
        raiz.addLayout(bt)

        self._ultimo = {}
        self._atualiza_rotulo_sessao()

    # ------------------------------------------------------------------
    def _avisar(self, texto):
        """Mostra um recado na área de mensagens (e não em caixa de diálogo)."""
        if texto:
            self.log.appendPlainText("• " + texto)

    def enquadrar(self):
        """Traz os blocos para dentro da vista.

        A cena é grande (2400×1400) para dar espaço de montagem, mas a vista
        abre no meio dela. Sem isto, um grafo desenhado à esquerda ficava fora
        de quadro e a tela parecia vazia — foi o que aconteceu na primeira
        captura.
        """
        if not self.cena.itens:
            return
        r = QtCore.QRectF()
        for item in self.cena.itens.values():
            r = r.united(item.sceneBoundingRect())
        if r.isEmpty():
            return
        r.adjust(-40, -40, 40, 40)
        self.vista.fitInView(r, QtCore.Qt.AspectRatioMode.KeepAspectRatio)
        # não deixa ampliar além de 1:1 — grafo de 2 blocos ficava gigante
        if self.vista.transform().m11() > 1.0:
            self.vista.resetTransform()
            self.vista.centerOn(r.center())

    def showEvent(self, ev):
        """Enquadra ao abrir, quando a vista já tem tamanho real."""
        super().showEvent(ev)
        QtCore.QTimer.singleShot(0, self.enquadrar)

    def _atualiza_rotulo_sessao(self):
        """Mostra qual sessão está carregada, e o tamanho dela."""
        if not self.sessao:
            self.lbl_ses.setText(tr("(nenhuma sessão — carregue uma para rodar)"))
            return
        eeg = np.asarray(self.sessao.get("eeg"))
        sr = float(self.sessao.get("sr") or SAMPLE_RATE)
        self.lbl_ses.setText(
            f"{eeg.shape[0]} {tr('canais')} · {eeg.shape[1] / sr:.1f} s · "
            f"{sr:.0f} Hz")

    def _inserir_da_paleta(self, item, _col):
        """Duplo clique na paleta insere o bloco no meio da vista."""
        chave = item.data(0, QtCore.Qt.ItemDataRole.UserRole)
        if not chave:
            return
        centro = self.vista.mapToScene(self.vista.viewport().rect().center())
        bid = self.grafo.add(chave, centro.x() - 85, centro.y() - 30)
        novo = _ItemBloco(bid, chave, self.cena)
        novo.setPos(self.grafo.blocos[bid]["x"], self.grafo.blocos[bid]["y"])
        self.cena.addItem(novo); self.cena.itens[bid] = novo
        self.cena.clearSelection(); novo.setSelected(True)

    def _mostrar_params(self, bid):
        """Reconstrói o painel de parâmetros para o bloco selecionado."""
        while self.form_params.count():
            w = self.form_params.takeAt(0).widget()
            if w:
                w.deleteLater()
        if not bid or bid not in self.grafo.blocos:
            return
        b = self.grafo.blocos[bid]
        spec = BANCADA_BLOCOS[b["tipo"]]
        cab = QtWidgets.QLabel(f"<b>{tr(spec['nome'])}</b><br>"
                               f"<span style='color:{COLORS['text_dim']}'>"
                               f"{tr(spec.get('ajuda',''))}</span>")
        cab.setWordWrap(True); cab.setTextFormat(QtCore.Qt.TextFormat.RichText)
        self.form_params.addRow(cab)
        for chave, valor in b["params"].items():
            if chave == "codigo":
                ed = QtWidgets.QPlainTextEdit(str(valor))
                ed.setMinimumHeight(220)
                ed.setStyleSheet(f"font-family:{FONT_DATA_STACK}; font-size:9pt;")
                ed.textChanged.connect(
                    lambda e=ed, k=chave, i=bid:
                    self.grafo.blocos[i]["params"].__setitem__(
                        k, e.toPlainText()))
                self.form_params.addRow(ed)
                nota = QtWidgets.QLabel(tr(
                    "Recebe <code>entrada</code> e precisa definir "
                    "<code>saida</code>. Tem <code>np</code> e "
                    "<code>sinal</code> (scipy.signal) à disposição.<br>"
                    "<b>Atenção:</b> este código roda dentro do programa, com "
                    "os seus arquivos ao alcance. Só rode código que você "
                    "escreveu ou de quem você confia."))
                nota.setWordWrap(True)
                nota.setTextFormat(QtCore.Qt.TextFormat.RichText)
                nota.setStyleSheet(f"color:{COLORS['text_dim']}; font-size:8pt;")
                self.form_params.addRow(nota)
                continue
            ed = QtWidgets.QLineEdit(str(valor))
            ed.editingFinished.connect(
                lambda e=ed, k=chave, i=bid: self._guardar_param(i, k, e.text()))
            self.form_params.addRow(chave, ed)

    def _guardar_param(self, bid, chave, texto):
        """Guarda o parâmetro, convertendo para número quando faz sentido."""
        if bid not in self.grafo.blocos:
            return
        try:
            valor = float(texto) if texto.strip() and texto.strip().replace(
                ".", "", 1).replace("-", "", 1).isdigit() else texto
        except ValueError:
            valor = texto
        self.grafo.blocos[bid]["params"][chave] = valor

    def _carregar_exemplo(self, _i):
        """Substitui a bancada por um exemplo pronto."""
        nome = self.cb_ex.currentData()
        if not nome:
            return
        self.grafo = bancada_exemplos()[nome]
        self._codigo_liberado = True        # exemplo é do próprio programa
        self.cena.grafo = self.grafo
        self.cena.recarregar()
        self.enquadrar()
        self.log.clear()
        self._avisar(tr("exemplo carregado: {}").format(tr(nome)))

    def _escolher_sessao(self):
        """Carrega uma sessão gravada para servir de entrada do grafo."""
        inicio = getattr(self.main.config, "save_directory", "")
        caminho, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Sessão para a Bancada"), inicio, tr("CSV (*.csv);;Todos (*)"))
        if not caminho:
            return
        d = self.main._load_session_csv(caminho)
        if not d:
            self._avisar(tr("não consegui ler essa sessão"))
            return
        self.sessao = d
        self._atualiza_rotulo_sessao()

    def _rodar(self):
        """Executa o grafo e mostra a primeira tabela que chegar ao Resultado."""
        self.log.clear()
        if not self.sessao:
            self._avisar(tr("carregue uma sessão antes de rodar"))
            return
        if not self.grafo.blocos:
            self._avisar(tr("a bancada está vazia"))
            return
        try:
            res, avisos = self.grafo.executar(
                self.sessao, codigo_liberado=self._codigo_liberado)
        except ErroBloco as exc:
            self._avisar(str(exc)); return
        for a in avisos:
            self._avisar(a)
        finais = res.get("finais") or {}
        if not finais:
            self._avisar(tr("nenhum bloco de Resultado recebeu dados"))
            self.tabela.setRowCount(0); return
        tabela = list(finais.values())[0]
        self._ultimo = tabela
        itens = list(tabela.items())
        self.tabela.setRowCount(len(itens))
        for i, (k, v) in enumerate(itens):
            self.tabela.setItem(i, 0, QtWidgets.QTableWidgetItem(tr(str(k))))
            self.tabela.setItem(i, 1, QtWidgets.QTableWidgetItem(f"{v:.4g}"))
        self.tabela.resizeColumnsToContents()
        if not avisos:
            self._avisar(tr("pronto — {} linhas").format(len(itens)))

    def _salvar(self):
        """Grava a bancada em .json, reutilizável e compartilhável."""
        inicio = getattr(self.main.config, "save_directory", "")
        caminho, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Salvar bancada"), os.path.join(inicio, "bancada.json"),
            "JSON (*.json)")
        if not caminho:
            return
        for bid, item in self.cena.itens.items():     # posições atuais
            if bid in self.grafo.blocos:
                self.grafo.blocos[bid]["x"] = float(item.pos().x())
                self.grafo.blocos[bid]["y"] = float(item.pos().y())
        try:
            with open(caminho, "w", encoding="utf-8") as f:
                json.dump(self.grafo.para_dict(), f, ensure_ascii=False,
                          indent=2)
        except Exception as exc:
            self._avisar(str(exc)); return
        self._avisar(tr("salvo em {}").format(caminho))

    def _abrir(self):
        """Abre uma bancada salva.

        Se ela trouxer bloco de código, PERGUNTA antes de permitir a execução:
        um .json com Python dentro é código de outra pessoa rodando na sua
        máquina, e isso tem de ser uma escolha consciente.
        """
        inicio = getattr(self.main.config, "save_directory", "")
        caminho, _ = QtWidgets.QFileDialog.getOpenFileName(
            self, tr("Abrir bancada"), inicio, "JSON (*.json)")
        if not caminho:
            return
        try:
            with open(caminho, encoding="utf-8") as f:
                d = json.load(f)
            g = GrafoBancada.de_dict(d)
        except Exception as exc:
            self._avisar(tr("arquivo inválido: {}").format(exc)); return
        self._codigo_liberado = True
        if g.tem_codigo():
            resp = QtWidgets.QMessageBox.warning(
                self, tr("Esta bancada traz código"),
                tr("O arquivo tem um bloco de código em Python, que roda "
                   "DENTRO do programa e alcança os seus arquivos.\n\n"
                   "Abra o bloco e leia o código antes de rodar, se ele não "
                   "for seu.\n\nQuer permitir a execução desse código?"),
                QtWidgets.QMessageBox.StandardButton.Yes
                | QtWidgets.QMessageBox.StandardButton.No,
                QtWidgets.QMessageBox.StandardButton.No)
            self._codigo_liberado = (
                resp == QtWidgets.QMessageBox.StandardButton.Yes)
        self.grafo = g
        self.cena.grafo = g
        self.cena.recarregar()
        self.enquadrar()
        self.log.clear()
        self._avisar(tr("bancada aberta: {} blocos").format(len(g.blocos)))
        if not self._codigo_liberado:
            self._avisar(tr("o bloco de código ficará bloqueado ao rodar"))

    def _exportar(self):
        """Exporta o resultado no formato que a planilha do usuário abre."""
        if not self._ultimo:
            self._avisar(tr("rode a bancada primeiro")); return
        inicio = getattr(self.main.config, "save_directory", "")
        caminho, _ = QtWidgets.QFileDialog.getSaveFileName(
            self, tr("Exportar resultado"),
            os.path.join(inicio, "bancada_resultado.csv"), "CSV (*.csv)")
        if not caminho:
            return
        escreve_csv_planilha(caminho, [tr("Rótulo"), tr("Valor")],
                             list(self._ultimo.items()))
        self._avisar(tr("exportado para {}").format(caminho))


