def run_recipe(recipe, session):
    """Pipeline de análise sobre uma sessão: RECORTE temporal -> PRE-FILTRO
    (passa-banda) -> Métrica por canal. Retorna [(rotulo_canal, valor)]."""
    eeg = np.asarray(session.get("eeg")) if session else None
    if eeg is None or eeg.ndim != 2 or eeg.size == 0:
        return []
    sr = float(session.get("sr", SAMPLE_RATE))
    names = session.get("ch_names") or [f"CH{i+1}" for i in range(eeg.shape[0])]
    metric = recipe.get("metrica", "band")
    band = recipe.get("banda", "Alpha")
    sel = recipe.get("canais")
    idxs = (list(range(eeg.shape[0])) if (not sel or sel == "all")
            else [c for c in sel if 0 <= c < eeg.shape[0]])
    # --- etapa: recorte temporal (segundos) ---
    n_total = eeg.shape[1]
    t0, t1 = recipe.get("t0"), recipe.get("t1")
    i0 = int(max(0.0, float(t0)) * sr) if t0 not in (None, "") else 0
    i1 = int(float(t1) * sr) if t1 not in (None, "") else n_total
    i0 = max(0, min(i0, n_total)); i1 = max(i0, min(i1, n_total))
    # --- etapa: janela de baseline (para ERD%) ---
    bl = recipe.get("baseline") or {}
    b0, b1 = bl.get("b0"), bl.get("b1")
    j0 = int(float(b0) * sr) if b0 not in (None, "") else 0
    j1 = int(float(b1) * sr) if b1 not in (None, "") else int(min(2.0 * sr, n_total))
    j0 = max(0, min(j0, n_total)); j1 = max(j0 + 1, min(j1, n_total))
    hi_tot = min(40.0, 0.49 * sr)   # banda "total" para potência relativa
    # --- etapa: pre-filtro (passa-banda) ---
    sos = None
    filt = recipe.get("filtro")
    if filt:
        try:
            ny = 0.5 * sr
            lo_n = max(1e-4, float(filt.get("low", 0)) / ny)
            hi_n = min(0.999, float(filt.get("high", 0)) / ny)
            if 0 < lo_n < hi_n < 1:
                sos = scipy_signal.butter(4, [lo_n, hi_n], btype="band", output="sos")
        except Exception:
            sos = None
    def _prepara(c):
        """Recorta, filtra e devolve o trecho de um canal (ou None)."""
        s = np.asarray(eeg[c], dtype=float)[i0:i1]
        s = s[np.isfinite(s)]
        if s.size < 2:
            return None
        if sos is not None and s.size > 18:
            try:
                s = scipy_signal.sosfiltfilt(sos, s)
            except Exception:
                pass
        return s

    # --- métricas por PAR de canais (agonista×antagonista, E×D) -------------
    # Saem antes do laço normal porque a unidade de resultado é o PAR, não o
    # canal: a tabela mostra "CH1×CH2" numa linha só.
    if metric in RECIPE_PAIR_METRICS:
        out = []
        for k in range(0, len(idxs) - 1, 2):
            ca, cb = idxs[k], idxs[k + 1]
            rot = f"{names[ca]}×{names[cb]}"
            sa, sb = _prepara(ca), _prepara(cb)
            if sa is None or sb is None:
                out.append((rot, 0.0)); continue
            if metric == "assimetria_alfa":
                # EEG: ln(direita) − ln(esquerda) na banda alfa
                # [Davidson 2004]. A ordem dos canais é esquerda, direita.
                nper = int(min(2048, sa.size))
                fr, pe = scipy_signal.welch(sa, fs=sr, nperseg=nper)
                _, pd = scipy_signal.welch(sb, fs=sr, nperseg=nper)
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_assimetria_alfa(pe, pd, fr, (lo, hi))
            elif metric == "coh_beta":  # EMG: Farmer 1993
                val, _lim = emg_coerencia_intermuscular(sa, sb, sr)
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "plv":  # EEG: Lachaux 1999
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_plv(sa, sb, sr, (lo, hi))
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "pli":  # EEG: Stam 2007
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_pli(sa, sb, sr, (lo, hi))
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "wpli":  # EEG: Vinck 2011
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_wpli(sa, sb, sr, (lo, hi))
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "ciplv":  # EEG: Bruña 2018
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_ciplv(sa, sb, sr, (lo, hi))
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "dpli":  # EEG: Stam & van Straaten 2012
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_dpli(sa, sb, sr, (lo, hi))
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "imcoh":  # EEG: Nolte 2004
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_imcoh(sa, sb, sr, (lo, hi))
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "xcorr_env":  # EMG: Nelson-Wong 2008
                val, _lag = emg_xcorr_envelopes(sa, sb, sr)
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "xcorr_lag":  # EMG: Nelson-Wong 2008
                _r, val = emg_xcorr_envelopes(sa, sb, sr)
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "aec":  # EEG: Hipp 2012
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                val = eeg_aec_ortogonal(sa, sb, sr, (lo, hi))
                if not np.isfinite(val):
                    val = 0.0
            elif metric == "bcea":
                # EoG: o par é horizontal e vertical do MESMO olho
                # [Crossland & Rubin 2002]
                val = eog_estabilidade_fixacao(sa, sb)
            elif metric == "li":
                # lateralidade sobre POTÊNCIA de banda: 100·(A−B)/(A+B).
                # Positivo = o primeiro canal domina.
                lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                a = SignalProcessor.compute_band_power(sa, lo, hi, sr)
                b = SignalProcessor.compute_band_power(sb, lo, hi, sr)
                soma = a + b
                val = (100.0 * (a - b) / soma) if soma > 1e-12 else 0.0
            else:
                # co-contração e razão usam AMPLITUDE (RMS), que é o que
                # representa o esforço do músculo
                a = float(np.sqrt(np.mean(sa ** 2)))
                b = float(np.sqrt(np.mean(sb ** 2)))
                if metric == "cci":
                    soma = a + b
                    val = (2.0 * min(a, b) / soma * 100.0) if soma > 1e-12 else 0.0
                else:                                  # ratio_pair
                    val = (a / b) if b > 1e-12 else float("nan")
            out.append((rot, float(val) if np.isfinite(val) else 0.0))
        return out

    out = []
    for c in idxs:
        sig = _prepara(c)
        if sig is None:
            out.append((names[c], 0.0)); continue
        # --- etapa: metrica ---
        if metric == "band":
            lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
            val = SignalProcessor.compute_band_power(sig, lo, hi, sr)
        elif metric == "relband":                        # potência relativa (%)
            lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
            pb = SignalProcessor.compute_band_power(sig, lo, hi, sr)
            pt = SignalProcessor.compute_band_power(sig, 1.0, hi_tot, sr)
            val = 100.0 * pb / pt if pt > 0 else 0.0
        elif metric == "erd":                            # ERD% vs baseline
            lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
            # eeg[c] e não `chan`: essa variável nunca existiu neste escopo e
            # o ERD levantava NameError sempre que era pedido pela receita —
            # justamente a métrica central de imagética motora.
            base = np.asarray(eeg[c], dtype=float)[j0:j1]
            base = base[np.isfinite(base)]
            if sos is not None and base.size > 18:
                try: base = scipy_signal.sosfiltfilt(sos, base)
                except Exception: pass
            p_act = SignalProcessor.compute_band_power(sig, lo, hi, sr)
            p_base = (SignalProcessor.compute_band_power(base, lo, hi, sr)
                      if base.size >= 2 else 0.0)
            val = 100.0 * (p_act - p_base) / p_base if p_base > 0 else 0.0
        elif metric == "rms":
            val = float(np.sqrt(np.mean(sig ** 2)))
        elif metric == "ptp":
            val = float(np.ptp(sig))
        elif metric == "mav":                              # EMG: Mean Absolute Value
            val = float(np.mean(np.abs(sig)))
        elif metric == "iemg":                             # EMG: integrado (Σ|x|)
            val = float(np.sum(np.abs(sig)))
        elif metric == "wl":                               # EMG: comprimento de onda
            val = float(np.sum(np.abs(np.diff(sig))))
        elif metric == "zcr":                              # EMG: cruzamentos por zero /s
            s = sig - np.mean(sig)
            thr = 0.01 * (np.std(s) + 1e-12)
            zc = np.sum((s[:-1] * s[1:] < 0) & (np.abs(s[:-1] - s[1:]) > thr))
            val = float(zc) / (len(sig) / sr) if len(sig) > 1 else 0.0
        elif metric in ("mdf", "mnf"):                     # EMG: freq. mediana/média
            if sig.size >= 32:
                fr, psd = scipy_signal.welch(sig, fs=sr, nperseg=min(256, sig.size))
                # Mesma banda do Dimitrov logo abaixo (ISEK/SENIAM: >=20 Hz). O
                # pré-filtro da receita é um checkbox: bastava o usuário desmarcá-lo
                # para a PSD ir de 0 Hz e um artefato de movimento de 2 Hz derrubar
                # o MDF de ~77 Hz para ~2 Hz — e a tabela não dava nenhum sinal
                # disso, porque o Dimitrov na coluna vizinha continuava correto.
                f_bnd = (fr >= 20.0) & (fr <= min(500.0, fr[-1]))
                fr, psd = fr[f_bnd], psd[f_bnd]
                tot = float(np.sum(psd))
                if tot > 0 and fr.size > 1 and metric == "mdf":
                    # Interpolada entre os dois pontos do espectro que cercam
                    # a metade da potência. Pegar o primeiro ponto acima dela
                    # prendia a MDF à grade do Welch (1000/256 = 3,9 Hz): duas
                    # gravações pareciam diferentes por um degrau da grade, e
                    # uma "queda de fadiga" podia ser só esse degrau.
                    cs = np.cumsum(psd)
                    meio = tot / 2.0
                    k = min(int(np.searchsorted(cs, meio)), len(fr) - 1)
                    if k > 0 and cs[k] > cs[k - 1]:
                        val = float(fr[k - 1] + (meio - cs[k - 1]) /
                                    (cs[k] - cs[k - 1]) * (fr[k] - fr[k - 1]))
                    else:
                        val = float(fr[k])
                elif tot > 0 and fr.size > 1:
                    val = float(np.sum(fr * psd) / tot)
                else:
                    val = 0.0
            else:
                val = 0.0
        elif metric == "dimitrov":                         # EMG: FInsm5 [Dimitrov 2006]
            if sig.size >= 32:
                fr, psd = scipy_signal.welch(sig, fs=sr, nperseg=min(256, sig.size))
                band = (fr >= 20.0) & (fr <= min(500.0, fr[-1]))
                fb, pb = fr[band], psd[band]
                if fb.size > 4:
                    fsafe = np.where(fb > 0, fb, 1e-6)
                    m_neg1 = float(_TRAPEZOID(pb / fsafe, fb))
                    m5 = float(_TRAPEZOID(pb * fb ** 5, fb))
                    val = m_neg1 / m5 if m5 > 0 else 0.0
                else:
                    val = 0.0
            else:
                val = 0.0
        elif metric == "emg_active":                       # EMG: % do tempo ativo (TKEO)
            try:
                onsets = emg_onset_tkeo(sig, sr)
                active = sum(max(0.0, o[1] - o[0]) for o in onsets)
                val = 100.0 * active / (len(sig) / sr) if len(sig) > 0 else 0.0
            except Exception:
                val = 0.0
        elif metric in ("aper_expoente", "aper_deslocamento", "sef95",
                        "pot_periodica"):
            # EEG: fundo aperiódico e o que sobra acima dele
            # [Donoghue et al. 2020]
            if sig.size >= int(2 * sr):
                nper = int(min(2048, sig.size))
                fr, psd = scipy_signal.welch(sig, fs=sr, nperseg=nper)
                if metric == "sef95":
                    val = eeg_sef(psd, fr)
                elif metric == "pot_periodica":
                    lo, hi = RECIPE_BANDS.get(band, (8.0, 13.0))
                    val = eeg_potencia_periodica(psd, fr, (lo, hi))
                else:
                    ap = eeg_aperiodico(psd, fr)
                    val = ap["expoente"] if metric == "aper_expoente" \
                        else ap["deslocamento"]
            else:
                val = None
        elif metric in ("hjorth_mobilidade", "hjorth_complexidade"):
            hj = eeg_hjorth(sig)                           # [Hjorth 1970]
            val = hj["mobilidade"] if metric.endswith("mobilidade") \
                else hj["complexidade"]
        elif metric == "entropia_perm":                    # [Bandt & Pompe 2002]
            val = eeg_entropia_permutacao(sig, ordem=4)
        elif metric == "lz_complexidade":                  # [Lempel & Ziv 1976]
            val = eeg_lempel_ziv(sig)
        elif metric == "dfa_alfa":                         # [Peng et al. 1994]
            val = eeg_dfa(sig)
        elif metric == "pac_tort":                         # [Tort et al. 2010]
            val = eeg_pac_tort(sig, sr)
        elif metric in ("qrs_pan_tompkins", "hrv_sdnn", "hrv_rmssd",
                        "hrv_pnn50", "poincare_sd1", "poincare_sd2",
                        "edr", "rsa"):
            # ECG: tudo depende de achar o R primeiro [Pan & Tompkins 1985]
            picos = ecg_pan_tompkins(sig, sr)
            if metric == "qrs_pan_tompkins":
                val = float(picos.size)
            elif metric == "edr":
                val = ecg_edr(sig, sr, picos)[2]
            elif picos.size < 4:
                val = None
            else:
                rr = ecg_rr(picos, sr)
                if metric == "rsa":
                    val = ecg_rsa(rr, picos, sr)
                elif metric.startswith("poincare"):
                    pc = ecg_poincare(rr)
                    val = pc["sd1"] if metric.endswith("sd1") else pc["sd2"]
                else:
                    val = ecg_hrv_tempo(rr)[metric.split("_", 1)[1]]
        elif metric in ("sacadas", "sequencia_principal", "piscadas",
                        "taxa_piscadas", "perclos"):
            # EoG [Engbert & Kliegl 2003; Bahill 1975; Wierwille 1994]
            if metric in ("sacadas", "sequencia_principal"):
                sac = eog_sacadas(sig, sr)
                val = float(len(sac)) if metric == "sacadas" \
                    else eog_sequencia_principal(sac)["expoente"]
            elif metric == "piscadas":
                val = float(len(eog_piscadas(sig, sr)))
            elif metric == "taxa_piscadas":
                val = eog_taxa_piscadas(sig, sr)
            else:
                val = eog_perclos(sig, sr)
        elif metric == "ssc":                              # EMG: Hudgins 1993
            val = emg_ssc(sig)
        elif metric == "wamp":                             # EMG: Phinyomark 2012
            val = emg_wamp(sig)
        elif metric == "myop":                             # EMG: taxa de mioimpulso
            val = emg_myop(sig)
        elif metric == "log_det":                          # EMG: detector logarítmico
            val = emg_log_detector(sig)
        elif metric == "dasdv":                            # EMG: DASDV
            val = emg_dasdv(sig)
        elif metric == "aac":                              # EMG: mudança média de amplitude
            val = emg_aac(sig)
        elif metric == "mavs":                             # EMG: inclinação do MAV
            val = emg_mavs(sig)
        elif metric == "sampen":                           # EMG: Richman & Moorman 2000
            val = emg_sampen(sig)
        elif metric == "higuchi":                          # EMG: Higuchi 1988
            val = emg_higuchi(sig)
        elif metric in ("mpr_ml", "mpr_hl", "mpr_ml_slope", "mpr_hl_slope"):
            # EMG: razões de potência média da distribuição B
            # [Karthick & Ramakrishnan 2016]. A inclinação é o índice de
            # fadiga do artigo e exige contração sustentada: em janela curta
            # a regressão não tem o que medir e o valor sai como ausente.
            try:
                linha = detect_line_freq(sig, sr)
                bandas = emg_mpr_bandas(linha, nyquist=sr / 2.0)
                t_mpr, ml, hl = emg_mpr(sig, sr, bandas=bandas)
                curva = ml if metric.startswith("mpr_ml") else hl
                if metric.endswith("_slope"):
                    val = (emg_inclinacao(t_mpr, curva)[0]
                           if (len(sig) / float(sr)) >= 2.0 else None)
                else:
                    val = float(np.nanmean(curva)) if np.any(
                        np.isfinite(curva)) else None
            except Exception:
                val = None
        elif metric == "onset_lat":  # EMG: Hodges & Bui 1996
            base = np.asarray(eeg[c], dtype=float)[j0:j1]
            base = base[np.isfinite(base)]
            val = emg_onset_latencia(sig, sr, 0, base)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "mdf_slope":  # EMG: Merletti 1990
            val = emg_mdf_inclinacao(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "gaps_min":  # EMG: Veiersted 1990
            cvm = recipe.get("cvm")
            if cvm:
                lim = 0.005 * float(cvm)
            else:
                base = np.asarray(eeg[c], dtype=float)[j0:j1]
                base = base[np.isfinite(base)]
                lim = 2.0 * float(np.sqrt(np.mean(base ** 2))) if base.size else float("nan")
            val, _pct = emg_gaps(sig, sr, lim)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "repouso_pct":  # EMG: Veiersted 1990
            cvm = recipe.get("cvm")
            if cvm:
                lim = 0.005 * float(cvm)
            else:
                base = np.asarray(eeg[c], dtype=float)[j0:j1]
                base = base[np.isfinite(base)]
                lim = 2.0 * float(np.sqrt(np.mean(base ** 2))) if base.size else float("nan")
            _g, val = emg_gaps(sig, sr, lim)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "apdf_p10":  # EMG: Jonsson 1982
            val = emg_apdf(sig, sr, recipe.get("cvm"))["p10"]
            if not np.isfinite(val):
                val = 0.0
        elif metric == "apdf_p50":  # EMG: Jonsson 1982
            val = emg_apdf(sig, sr, recipe.get("cvm"))["p50"]
            if not np.isfinite(val):
                val = 0.0
        elif metric == "apdf_p90":  # EMG: Jonsson 1982
            val = emg_apdf(sig, sr, recipe.get("cvm"))["p90"]
            if not np.isfinite(val):
                val = 0.0
        elif metric == "fuzzyen":  # EMG: Chen 2007
            val = emg_fuzzyen(sig)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "mse":  # EEG: Costa 2002
            val = eeg_mse(sig)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "engajamento":  # EEG: Pope 1995
            val = eeg_engajamento(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "surtos_beta":  # EEG: Shin 2017
            val, _dur = eeg_surtos_beta(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "higuchi_eeg":  # EEG: Higuchi 1988
            val = emg_higuchi(sig)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "sampen_eeg":  # EEG: Richman 2000
            val = emg_sampen(sig)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "fc_media":  # ECG: FC média
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = ecg_hrv_tempo(rr)["fc_media"] if rr.size >= 2 else 0.0
            if not np.isfinite(val):
                val = 0.0
        elif metric == "baevsky_si":  # ECG: Baevsky
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = ecg_stress_index(rr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "dc":  # ECG: Bauer 2006
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = ecg_deceleration_capacity(rr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "pip":  # ECG: Costa 2017
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = ecg_pip(rr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "sampen_rr":  # ECG: SampEn dos RR
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = emg_sampen(rr) if rr.size >= 50 else 0.0
            if not np.isfinite(val):
                val = 0.0
        elif metric == "ectopicos_pct":  # ECG: ectópicos
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            _rc, ruins = correct_ectopic_rr(rr)
            val = 100.0 * len(ruins) / rr.size if rr.size else 0.0
        elif metric == "ksqi":  # ECG: kSQI
            val = ecg_ksqi(sig)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "psqi":  # ECG: pSQI
            val = ecg_psqi(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "dur_piscadas":  # EoG: Caffier 2003
            val = eog_duracao_piscadas(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "dur_fixacoes":  # EoG: Salvucci 2000
            val, _fpm = eog_fixacoes_idt(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "fixacoes_min":  # EoG: Salvucci 2000
            _d, val = eog_fixacoes_idt(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "sem_pct":  # EoG: Magosso 2006
            val = eog_sem_fracao(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "rer":  # EMG: Aagaard 2002
            base = np.asarray(eeg[c], dtype=float)[j0:j1]
            base = base[np.isfinite(base)]
            val = emg_rer(sig, sr, base, emg_max=recipe.get('cvm'))
            if not np.isfinite(val):
                val = 0.0
        elif metric == "rms_slope":  # EMG: Luttmann 2000
            val = emg_rms_inclinacao(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "regressao_eog":  # EEG: Gratton 1983 (correção, não métrica)
            raise ValueError(tr('Regressão ocular é uma correção do sinal, não uma métrica: use Visualizar → Bio (EMG/ECG/EoG) → Regressão ocular → EEG.'))
        elif metric == "csi":  # ECG: Toichi 1997
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = ecg_csi_cvi(rr)['csi']
            if not np.isfinite(val):
                val = 0.0
        elif metric == "cvi":  # ECG: Toichi 1997
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = ecg_csi_cvi(rr)['cvi']
            if not np.isfinite(val):
                val = 0.0
        elif metric == "mse_rr":  # ECG: Costa 2002
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            val = eeg_mse(rr, escalas=range(1, 6)) if rr.size >= 100 else 0.0
            if not np.isfinite(val):
                val = 0.0
        elif metric == "avr_piscadas":  # EoG: Johns 2007
            val = eog_avr_piscadas(sig, sr)
            if not np.isfinite(val):
                val = 0.0
        elif metric == "percent_cvm":         # EMG: Hermens 2000
            # Sem referência de CVM na receita (campo "cvm", em µV), a
            # normalização usa o máximo do PRÓPRIO registro: compara
            # trechos da mesma sessão, não pessoas.
            cvm = recipe.get("cvm") or emg_cvm_referencia(
                np.asarray(eeg[c], dtype=float), sr)
            pc = emg_percent_cvm(sig, sr, cvm)
            val = float(np.mean(pc)) if pc is not None and len(pc) else 0.0
        elif metric == "qtc":                  # ECG: Bazett 1920 (QT pela tangente)
            picos = ecg_pan_tompkins(sig, sr)
            rr = ecg_rr(picos, sr)
            qt = ecg_qt_intervalo(sig, sr, picos)
            val = (ecg_qtc(qt, float(np.mean(rr)), "bazett")
                   if np.isfinite(qt) and rr.size else 0.0)
            if val is None or not np.isfinite(val):
                val = 0.0
        elif metric == "bandratio":            # razão banda escolhida / Beta
            lo, hi = RECIPE_BANDS.get(band, (4.0, 8.0))
            pa = SignalProcessor.compute_band_power(sig, lo, hi, sr)
            pbeta = SignalProcessor.compute_band_power(sig, 13.0, 30.0, sr)
            val = pa / pbeta if pbeta > 0 else 0.0
        elif metric == "iaf":                  # frequência de pico alfa (IAF)
            if sig.size >= int(2 * sr):
                fr, psd = scipy_signal.welch(sig, fs=sr,
                                             nperseg=min(1024, sig.size))
                m = (fr >= 7.0) & (fr <= 14.0)
                # SUAVIZA a PSD antes de testar o pico: bin a bin, ruído
                # branco flutua tanto que max/mediana passa de 2× fácil e o
                # teste "inventava" um IAF onde não há alfa. Após a média
                # móvel de 5 bins o ruído aplaina e só pico real sobrevive.
                if np.any(m) and psd[m].size >= 7:
                    pz = np.convolve(psd[m], np.ones(5) / 5.0, mode="same")
                    if pz.max() > 1.6 * np.median(pz):
                        val = float(fr[m][int(np.argmax(pz))])
                    else:
                        val = 0.0          # sem alfa resolvível — não inventa
                else:
                    val = 0.0
            else:
                val = 0.0
        elif metric == "specent":              # entropia espectral normalizada
            if sig.size >= 64:
                fr, psd = scipy_signal.welch(sig, fs=sr,
                                             nperseg=min(256, sig.size))
                m = (fr >= 1.0) & (fr <= min(40.0, fr[-1]))
                p = psd[m]
                tot = float(np.sum(p))
                if tot > 0 and p.size > 1:
                    p = p / tot
                    ent = -float(np.sum(p * np.log2(p + 1e-24)))
                    val = ent / np.log2(p.size)      # 0 = tom puro, 1 = ruído
                else:
                    val = 0.0
            else:
                val = 0.0
        else:
            # Antes: val = std(sig), em silêncio. Uma métrica sem ramo saía
            # como um número plausível com o rótulo errado na tabela.
            raise ValueError(tr("Métrica sem implementação no motor de "
                                "receitas: {}").format(metric))
        out.append((names[c], float(val)))
    return out


# ============================================================
# Estudo por Paciente — análise em lote organizada por paciente e por data
# ============================================================
# Uma pasta com muitas gravações vira uma pasta por paciente e, dentro dela,
# uma subpasta por data. Foi feito para o caso em que os resultados chegam
# reunidos num bloco só e é preciso acompanhar cada pessoa ao longo do tempo.
#
# O que este módulo NÃO faz: inventar significado onde não há sinal. Toda
# medida sai acompanhada de um veredito de qualidade do canal, porque um
# número de amplitude comparado entre datas sem essa coluna pode ser apenas
# a interferência da rede elétrica mudando de uma sessão para outra.

ESTUDO_FASES_REPOUSO = ("RELAXAR", "REPOUSO", "REST", "RELAX", "BASELINE",
                        "IDLE", "PAUSA")

# métrica interna do run_recipe, rótulo, unidade
ESTUDO_METRICAS = [
    ("rms", "RMS", "µV"),
    ("mav", "MAV", "µV"),
    ("ptp", "Pico a pico", "µV"),
    ("iemg", "iEMG", "µV·amostras"),
    ("wl", "Comprimento de onda", "µV"),
    ("zcr", "Cruzamentos por zero", "1/s"),
    ("mdf", "MDF (frequência mediana)", "Hz"),
    ("mnf", "MNF (frequência média)", "Hz"),
    ("dimitrov", "Dimitrov FInsm5 (fadiga)", "—"),
    ("emg_active", "Tempo ativo (TKEO)", "%"),
]
ESTUDO_METRICAS_PADRAO = ["rms", "mav", "ptp", "iemg", "mdf", "emg_active"]

# Limiares do veredito de qualidade do canal.
ESTUDO_RAZAO_BOA = 1.5        # energia de ação sobre energia de repouso
ESTUDO_RAZAO_MARGINAL = 1.2
ESTUDO_ALINHA_BOA = 65.0      # % do envelope forte que cai dentro da ação
ESTUDO_ALINHA_MARGINAL = 60.0
ESTUDO_REDE_ALTA = 20.0       # % da potência em ±1 Hz da rede
# mesmo piso que estudo_metricas usa para descartar bloco curto: abaixo
# disso a gravação foi interrompida e o canal não sustenta comparação
ESTUDO_MIN_ACAO_S = 0.5

ESTUDO_VEREDITOS = ("utilizável", "marginal", "não utilizável", "sem fases")

_ESTUDO_RE_DATA = re.compile(r"(20\d{2})[-_]?(\d{2})[-_]?(\d{2})")
_ESTUDO_RE_HORA = re.compile(r"_(\d{2})(\d{2})(\d{2})(?:_|\.)")


def estudo_normaliza_fase(txt):
    """Rótulo de fase em caixa alta e sem acento, para comparar sem surpresa."""
    t = unicodedata.normalize("NFKD", str(txt or "").strip().upper())
    return "".join(c for c in t if not unicodedata.combining(c))


def estudo_e_repouso(fase):
    """A fase é repouso? Aceita os rótulos mais comuns em português e inglês."""
    return estudo_normaliza_fase(fase) in ESTUDO_FASES_REPOUSO


def estudo_le_csv(caminho):
    """Lê um CSV clínico com cabeçalho em comentário e coluna de fase.

    Entende o formato exportado pelo Symbios/MyoSym e, de modo geral,
    qualquer CSV que tenha linhas de comentário iniciadas por '#', uma
    coluna de estado/fase e colunas numéricas de sinal. Devolve a sessão no
    mesmo formato que o run_recipe consome.
    """
    cab, linhas = {}, []
    with io.open(caminho, "r", encoding="utf-8", errors="replace") as f:
        for lin in f:
            if lin.startswith("#"):
                partes = lin.lstrip("#").strip().split(":", 1)
                if len(partes) == 2:
                    cab[partes[0].strip().lower()] = partes[1].strip().strip(",")
            elif lin.strip():
                linhas.append(lin)
    if not linhas:
        raise ValueError("arquivo sem linhas de dados")
    leitor = csv.reader(linhas)
    colunas = [c.strip() for c in next(leitor)]
    corpo = [l for l in leitor if l]

    # a coluna de fase é a que tem texto repetido; as de sinal são numéricas
    i_fase, i_sinal = None, []
    for j, nome in enumerate(colunas):
        alvo = nome.strip().lower()
        if alvo in ("recording_state", "state", "fase", "estado", "phase",
                    "event", "label"):
            i_fase = j
        elif alvo in ("sample_index", "index", "sample", "time", "tempo",
                      "timestamp"):
            continue
        else:
            try:
                float(corpo[0][j])
                i_sinal.append(j)
            except (ValueError, IndexError):
                if i_fase is None:
                    i_fase = j
    if not i_sinal:
        raise ValueError("nenhuma coluna de sinal reconhecida")

    n = len(corpo)
    sinais = np.zeros((len(i_sinal), n), dtype=float)
    fases = np.empty(n, dtype=object)
    for k, lin in enumerate(corpo):
        for c, j in enumerate(i_sinal):
            try:
                sinais[c, k] = float(lin[j])
            except (ValueError, IndexError):
                sinais[c, k] = np.nan
        fases[k] = lin[i_fase] if (i_fase is not None and
                                   i_fase < len(lin)) else "—"
    sinais = np.nan_to_num(sinais)

    sr = 0.0
    for chave in ("sampling_frequency_hz", "sample_rate", "fs",
                  "sampling_rate_hz"):
        if chave in cab:
            try:
                sr = float(cab[chave])
                break
            except ValueError:
                pass
    if sr <= 0:
        sr = 1000.0

    nomes = []
    for j in i_sinal:
        nomes.append(colunas[j].replace("_Raw", "").replace("_Filtered", "")
                     .replace("_", " ").strip() or "Ch%d" % (len(nomes) + 1))

    tipo = (cab.get("data type") or cab.get("data_type") or "").upper()
    if not tipo:
        tipo = "FILTERED" if "_filtered" in os.path.basename(caminho).lower() \
            else "RAW"
    return {
        "eeg": sinais, "sr": sr, "ch_names": nomes,          # o run_recipe pede
        "fases": fases, "signal_type": "EMG",
        "cabecalho": cab, "tipo": tipo,
        "arquivo": os.path.basename(caminho), "caminho": caminho,
        "n_amostras": n, "duracao_s": n / sr if sr else 0.0,
        "retificado": str(cab.get("rectifier_enabled", "")).lower() == "true",
        "notch_declarado": str(cab.get("notch_enabled", "")).lower() == "true",
    }


def estudo_blocos_de_fase(fases):
    """Trechos contíguos de mesma fase: [(fase, i_inicio, i_fim), ...]."""
    fases = np.asarray(fases, dtype=object)
    if fases.size == 0:
        return []
    troca = np.flatnonzero(np.array([fases[i] != fases[i - 1]
                                     for i in range(1, fases.size)])) + 1
    inicios = np.concatenate(([0], troca))
    fins = np.concatenate((troca, [fases.size]))
    return [(str(fases[a]), int(a), int(b)) for a, b in zip(inicios, fins)]


def estudo_identifica(caminho, sessao, raiz):
    """Descobre paciente, data, hora, exercício e grupo a partir do arquivo.

    A ordem de preferência é cabeçalho, depois nome do arquivo, depois pasta.
    O grupo (antes/depois, pré/pós) sai do nome de alguma pasta do caminho,
    que é como as coletas costumam ser separadas.
    """
    nome = os.path.splitext(os.path.basename(caminho))[0]
    cab = sessao.get("cabecalho", {})

    paciente = ""
    for chave in ("patient", "paciente", "subject", "sujeito", "volunteer",
                  "participant", "patient name", "subject id"):
        if cab.get(chave):
            paciente = cab[chave]
            break
    if not paciente:
        # o padrão do Symbios é NOME_EMG_AAAAMMDD_HHMMSS_Exercicio
        m = re.split(r"_(?:EMG|EEG|ECG|EOG)_", nome, maxsplit=1)
        paciente = m[0] if len(m) > 1 else ""
    if not paciente:
        rel = os.path.relpath(caminho, raiz).replace("\\", "/").split("/")
        paciente = rel[0] if len(rel) > 1 else "SEM IDENTIFICACAO"

    data = ""
    bruto = (cab.get("original recording date") or cab.get("recording date")
             or cab.get("data") or "")
    m = _ESTUDO_RE_DATA.search(bruto) or _ESTUDO_RE_DATA.search(nome)
    if not m:
        m = _ESTUDO_RE_DATA.search(caminho.replace("\\", "/"))
    data = "%s-%s-%s" % m.groups() if m else "sem data"

    hora = ""
    if len(bruto.split()) > 1:
        hora = bruto.split()[1][:8]
    else:
        mh = _ESTUDO_RE_HORA.search(os.path.basename(caminho))
        if mh:
            hora = ":".join(mh.groups())

    exercicio = (cab.get("exercise") or cab.get("exercicio") or "").strip()
    if not exercicio:
        pedacos = nome.split("_")
        exercicio = " ".join(pedacos[4:]) if len(pedacos) > 4 else nome
        exercicio = re.sub(r"\b(raw|filtered)\b", "", exercicio,
                           flags=re.I).strip(" _-") or nome

    grupo = ""
    for parte in os.path.relpath(caminho, raiz).replace("\\", "/").lower().split("/"):
        if parte in ("antes", "depois", "pre", "pos", "pré", "pós", "before",
                     "after", "baseline", "seguimento"):
            grupo = parte
            break
    return {"paciente": str(paciente).strip() or "SEM IDENTIFICACAO",
            "data": data, "hora": hora,
            "exercicio": exercicio.replace("_", " ").strip(),
            "grupo": grupo or "único"}


def estudo_limpa(sinal, sr, usar_notch=True, harmonicos=3):
    """Tira a interferência da rede com o notch do próprio ROA.

    Devolve (sinal, frequência da rede detectada). Sem notch, devolve o
    sinal como veio — a opção existe para quem já exportou filtrado.
    """
    x = np.nan_to_num(np.asarray(sinal, dtype=float))
    linha = detect_line_freq(x, sr)
    if not usar_notch:
        return x, linha
    return notch_harmonics(x, sr, base=linha,
                           n_harmonics=max(0, int(harmonicos)), Q=30.0), linha


def estudo_pct_rede(sinal, sr, linha=60.0):
    """% da potência dentro de ±1 Hz da rede: o quanto do registro é tomada."""
    x = np.nan_to_num(np.asarray(sinal, dtype=float))
    if x.size < 1024 or sr <= 0:
        return float("nan")
    nper = int(min(4096, x.size))
    fr, psd = scipy_signal.welch(x, fs=sr, nperseg=nper)
    faixa = (fr >= 5) & (fr <= min(480.0, fr[-1]))
    total = float(_TRAPEZOID(psd[faixa], fr[faixa])) if faixa.any() else 0.0
    if total <= 0:
        return float("nan")
    perto = (fr >= linha - 1) & (fr <= linha + 1)
    if not perto.any():
        return 0.0
    return 100.0 * float(_TRAPEZOID(psd[perto], fr[perto])) / total


def estudo_envelope(sinal, sr, janela_s=0.10):
    """Envelope RMS por janela deslizante."""
    n = max(1, int(janela_s * sr))
    x = np.nan_to_num(np.asarray(sinal, dtype=float))
    return np.sqrt(np.convolve(x ** 2, np.ones(n) / n, mode="same"))


def estudo_qualidade(bruto, limpo, fases, sr, linha):
    """Veredito de qualidade do canal, com os números que o sustentam.

    Três perguntas: a fase de ação tem mais energia que o repouso; o pico do
    envelope cai dentro das fases de ação; e quanto do registro original era
    rede elétrica. O veredito é o que impede alguém de comparar ruído entre
    datas achando que compara músculo.
    """
    p_rede = estudo_pct_rede(bruto, sr, linha)
    rep = np.array([estudo_e_repouso(f) for f in fases], dtype=bool)
    aco = ~rep
    vazio = {"veredito": "sem fases", "razao": float("nan"),
             "razao_bruta": float("nan"), "pct_rede": p_rede,
             "alinhamento": float("nan"), "crista": float("nan"),
             "rms_acao": float("nan"), "rms_repouso": float("nan"),
             "rms_bruto_acao": float("nan"), "acao_curta": False}
    if not rep.any() or not aco.any():
        return vazio
    # gravação interrompida: menos de meio segundo de ação no registro
    # inteiro. Os números continuam medidos, mas o veredito cai.
    acao_curta = float(aco.sum()) / float(sr) < ESTUDO_MIN_ACAO_S
    limpo = np.nan_to_num(np.asarray(limpo, dtype=float))
    bruto = np.nan_to_num(np.asarray(bruto, dtype=float))
    r_rep = float(np.sqrt(np.mean(limpo[rep] ** 2)))
    r_aco = float(np.sqrt(np.mean(limpo[aco] ** 2)))
    razao = r_aco / r_rep if r_rep > 0 else float("nan")
    b_rep = float(np.sqrt(np.mean(bruto[rep] ** 2)))
    b_aco = float(np.sqrt(np.mean(bruto[aco] ** 2)))
    razao_bruta = b_aco / b_rep if b_rep > 0 else float("nan")

    env = estudo_envelope(limpo, sr)
    mediana = float(np.median(env))
    crista = float(np.percentile(env, 95)) / mediana if mediana > 0 \
        else float("nan")
    fortes = env >= np.percentile(env, 95)
    alinha = 100.0 * float(np.mean(aco[fortes])) if fortes.any() \
        else float("nan")

    boa_razao = np.isfinite(razao) and razao >= ESTUDO_RAZAO_BOA
    boa_alinha = np.isfinite(alinha) and alinha >= ESTUDO_ALINHA_BOA
    if acao_curta:
        veredito = "não utilizável"
    elif boa_razao and boa_alinha:
        veredito = "utilizável"
    elif (np.isfinite(razao) and razao >= ESTUDO_RAZAO_MARGINAL) or \
         (np.isfinite(alinha) and alinha >= ESTUDO_ALINHA_MARGINAL):
        veredito = "marginal"
    else:
        veredito = "não utilizável"
    return {"veredito": veredito, "razao": razao, "razao_bruta": razao_bruta,
            "pct_rede": p_rede, "alinhamento": alinha, "crista": crista,
            "rms_acao": r_aco, "rms_repouso": r_rep, "rms_bruto_acao": b_aco,
            "acao_curta": bool(acao_curta)}


def estudo_metricas(sinais, sr, nomes, blocos, metricas, filtro=(20.0, 450.0)):
    """Roda o run_recipe em cada bloco de fase e agrega por mediana.

    Bloco a bloco, e não no registro inteiro: cada repetição de contração e
    cada repouso entram separados. Concatenar os trechos criaria degraus
    artificiais no espectro e falsearia MDF e MNF.
    """
    acum = {}
    for fase, ini, fim in blocos:
        if fim - ini < int(0.5 * sr):
            continue
        grupo = "repouso" if estudo_e_repouso(fase) else "acao"
        sessao = {"eeg": sinais[:, ini:fim], "sr": sr, "ch_names": nomes}
        for chave in metricas:
            receita = {"metrica": chave, "canais": "all",
                       "filtro": {"low": filtro[0], "high": filtro[1]}}
            try:
                pares = run_recipe(receita, sessao)
            except Exception:
                continue
            for rotulo, valor in pares:
                if valor is None or not np.isfinite(valor):
                    continue
                acum.setdefault(grupo, {}).setdefault(rotulo, {}) \
                    .setdefault(chave, []).append(float(valor))
    return {g: {ch: {m: float(np.median(v)) for m, v in mets.items()}
                for ch, mets in canais.items()}
            for g, canais in acum.items()}


def estudo_analisa_arquivo(caminho, raiz, cfg=None):
    """Uma gravação: identificação, qualidade por canal e métricas por fase."""
    cfg = cfg or {}
    sessao = estudo_le_csv(caminho)
    sr = sessao["sr"]
    ident = estudo_identifica(caminho, sessao, raiz)
    blocos = estudo_blocos_de_fase(sessao["fases"])
    metricas = cfg.get("metricas") or ESTUDO_METRICAS_PADRAO
    usar_notch = cfg.get("notch", True)
    filtro = (float(cfg.get("passa_baixa", 20.0)),
              float(cfg.get("passa_alta", 450.0)))

    limpos = np.zeros(sessao["eeg"].shape, dtype=float)
    qualidade, linha = {}, 60.0
    for c, ch in enumerate(sessao["ch_names"]):
        y, linha = estudo_limpa(sessao["eeg"][c], sr, usar_notch,
                                cfg.get("harmonicos", 3))
        limpos[c] = y
        qualidade[ch] = estudo_qualidade(sessao["eeg"][c], y, sessao["fases"],
                                         sr, linha)
    valores = estudo_metricas(limpos, sr, sessao["ch_names"], blocos,
                              metricas, filtro)
    acoes = [(f, a, b) for f, a, b in blocos if not estudo_e_repouso(f)]
    reg = dict(ident)
    reg.update({
        "arquivo": sessao["arquivo"], "caminho": caminho, "sr": sr,
        "canais": list(sessao["ch_names"]), "tipo": sessao["tipo"],
        "duracao_s": round(sessao["duracao_s"], 1),
        "freq_rede": float(linha), "notch_declarado": sessao["notch_declarado"],
        "n_repeticoes": len(acoes),
        "tempo_acao_s": round(sum(b - a for _f, a, b in acoes) / sr, 1),
        "tempo_repouso_s": round(sum(b - a for f, a, b in blocos
                                     if estudo_e_repouso(f)) / sr, 1),
        "blocos": [(f, round((b - a) / sr, 2)) for f, a, b in blocos],
        "qualidade": qualidade, "metricas": valores,
    })
    return reg


def estudo_lista_arquivos(raiz, padrao="*_raw.csv"):
    """Todos os arquivos da pasta e subpastas que casam com o padrão."""
    import fnmatch
    achados = []
    for base, _dirs, arqs in os.walk(raiz):
        for a in sorted(arqs):
            if fnmatch.fnmatch(a.lower(), padrao.lower()):
                achados.append(os.path.join(base, a))
    return sorted(achados)


def estudo_varre(raiz, cfg=None, progresso=None, cancelado=None):
    """Analisa a pasta inteira. `progresso(i, total, texto)` acompanha."""
    cfg = cfg or {}
    alvos = estudo_lista_arquivos(raiz, cfg.get("padrao", "*_raw.csv"))
    registros, falhas = [], []
    for i, caminho in enumerate(alvos, 1):
        if cancelado is not None and cancelado():
            break
        try:
            reg = estudo_analisa_arquivo(caminho, raiz, cfg)
            registros.append(reg)
            texto = "%s · %s · %s" % (reg["paciente"], reg["data"],
                                      reg["exercicio"])
        except Exception as exc:
            falhas.append((os.path.basename(caminho), str(exc)))
            texto = "%s — %s" % (os.path.basename(caminho), exc)
        if progresso is not None:
            progresso(i, len(alvos), texto)
    return registros, falhas


def estudo_agrupa(registros):
    """{paciente: {data: [registros]}} na ordem cronológica de leitura."""
    ordem_grupo = {"antes": 0, "pre": 0, "pré": 0, "before": 0, "baseline": 0,
                   "depois": 1, "pos": 1, "pós": 1, "after": 1}
    ordenados = sorted(registros, key=lambda r: (
        r["paciente"], r["data"], ordem_grupo.get(r["grupo"], 5),
        r["exercicio"]))
    arvore = {}
    for r in ordenados:
        arvore.setdefault(r["paciente"], {}).setdefault(r["data"], []).append(r)
    return arvore


def estudo_conta_vereditos(registros):
    """Quantos canais de cada veredito no conjunto informado."""
    contagem = dict.fromkeys(ESTUDO_VEREDITOS, 0)
    for r in registros:
        for ch in r["canais"]:
            v = r["qualidade"].get(ch, {}).get("veredito", "sem fases")
            contagem[v] = contagem.get(v, 0) + 1
    return contagem

