ESTUDO_COR = {"utilizável": "#2e7d32", "marginal": "#ef6c00",
              "não utilizável": "#c62828", "sem fases": "#9e9e9e"}


def _estudo_plt():
    """matplotlib carregado só na hora de desenhar, como no resto do app."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    plt.rcParams.update({"figure.dpi": 110, "font.size": 8,
                         "axes.grid": True, "grid.alpha": 0.25})
    return matplotlib, plt


def estudo_fig_sinal(registro, destino, titulo, cfg=None):
    """Traçado limpo dos canais com as fases de ação sombreadas."""
    _mpl, plt = _estudo_plt()
    cfg = cfg or {}
    sessao = estudo_le_csv(registro["caminho"])
    sr = sessao["sr"]
    n = len(sessao["ch_names"])
    fig, eixos = plt.subplots(n, 1, figsize=(9.2, 1.5 * n + 0.7), sharex=True)
    eixos = np.atleast_1d(eixos)
    t = np.arange(sessao["eeg"].shape[1]) / sr
    for i, ch in enumerate(sessao["ch_names"]):
        y, _ = estudo_limpa(sessao["eeg"][i], sr, cfg.get("notch", True),
                            cfg.get("harmonicos", 3))
        ax = eixos[i]
        for fase, a, b in estudo_blocos_de_fase(sessao["fases"]):
            if not estudo_e_repouso(fase):
                ax.axvspan(a / sr, b / sr, color="#ffd54f", alpha=0.28, lw=0)
        q = registro["qualidade"].get(ch, {})
        ax.plot(t, y, lw=0.35, color=ESTUDO_COR.get(q.get("veredito"), "#455a64"))
        ax.set_ylabel("%s\nµV" % ch, fontsize=7)
        ax.set_title("%s — %s (%s %.2fx)"
                     % (ch, tr(q.get("veredito", "")), tr("ação/repouso"),
                        q.get("razao", float("nan"))),
                     fontsize=7.5, loc="left", pad=2)
    eixos[-1].set_xlabel(tr("tempo (s)   ·   faixa amarela = fase de ação"))
    fig.suptitle(titulo, fontsize=9.5, y=0.995)
    fig.tight_layout(rect=(0, 0, 1, 0.985))
    fig.savefig(destino, bbox_inches="tight")
    plt.close(fig)
    return destino


def estudo_fig_envelope(registros, destino, titulo, cfg=None):
    """Envelope da atividade, um traço por grupo (antes e depois)."""
    _mpl, plt = _estudo_plt()
    cfg = cfg or {}
    cores = {"antes": "#1565c0", "depois": "#c2185b"}
    sessoes = [(r["grupo"], estudo_le_csv(r["caminho"])) for r in registros]
    if not sessoes:
        return None
    chs = sessoes[0][1]["ch_names"]
    fig, eixos = plt.subplots(len(chs), 1,
                              figsize=(9.2, 1.35 * len(chs) + 0.7), sharex=True)
    eixos = np.atleast_1d(eixos)
    for i, ch in enumerate(chs):
        ax = eixos[i]
        for grupo, s in sessoes:
            if i >= s["eeg"].shape[0]:
                continue
            y, _ = estudo_limpa(s["eeg"][i], s["sr"], cfg.get("notch", True),
                                cfg.get("harmonicos", 3))
            env = estudo_envelope(y, s["sr"], 0.20)
            ax.plot(np.arange(env.size) / s["sr"], env, lw=0.8, label=tr(grupo),
                    color=cores.get(grupo, "#546e7a"))
        ax.set_ylabel("%s\nµV" % ch, fontsize=7)
        if i == 0:
            ax.legend(fontsize=7, ncol=2, loc="upper right")
    eixos[-1].set_xlabel(tr("tempo (s)"))
    fig.suptitle(titulo, fontsize=9.5, y=0.995)
    fig.tight_layout(rect=(0, 0, 1, 0.985))
    fig.savefig(destino, bbox_inches="tight")
    plt.close(fig)
    return destino


def estudo_fig_mapa_qualidade(registros, destino, titulo):
    """Grade exercício por canal, pintada pelo veredito."""
    mpl, plt = _estudo_plt()
    exs = sorted({r["exercicio"] for r in registros})
    colunas = []
    for r in registros:
        for ch in r["canais"]:
            if (r["grupo"], ch) not in colunas:
                colunas.append((r["grupo"], ch))
    codigo = {"utilizável": 0, "marginal": 1, "não utilizável": 2}
