    ax.set_xticks(range(len(colunas)))
    ax.set_xticklabels(["%s\n%s" % (tr(g), ch) for g, ch in colunas], fontsize=6.5)
    ax.set_yticks(range(len(exs)))
    ax.set_yticklabels([e[:28] for e in exs], fontsize=7)
