# ==========================================================
# Métodos de EEG, ECG e EoG — DSP
# ==========================================================
# ==========================================================================
# 1) Separação periódico / aperiódico  [Donoghue et al. 2020]
# ==========================================================================
def eeg_aperiodico(psd, freqs, faixa=(1.0, 45.0), n_picos=6,
                   limiar_dp=2.5, altura_min=0.05, largura_max=12.0):
    """Ajusta a componente 1/f do espectro e devolve expoente e deslocamento.

    O espectro do EEG é a soma de um fundo aperiódico que cai como 1/f^X com
    picos oscilatórios em cima. Medir "potência de alfa" sem separar os dois
    mistura duas coisas de origem diferente: uma mudança no expoente aperiódico
    desloca TODAS as bandas ao mesmo tempo e é lida, erradamente, como mudança
    de ritmo.

    Segue o algoritmo do artigo na versão sem joelho, que é a adequada a uma
    faixa estreita como 1-45 Hz: ajusta a reta em log-log, tira os picos que
    sobram acima do ajuste, e reajusta sem eles.

    Devolve {"expoente", "deslocamento", "r2", "picos": [(f, altura, largura)]}.
    """
    psd = np.asarray(psd, float)
    freqs = np.asarray(freqs, float)
    b = (freqs >= max(faixa[0], 1e-6)) & (freqs <= faixa[1]) & (psd > 0)
    if b.sum() < 8:
        return {"expoente": float("nan"), "deslocamento": float("nan"),
                "r2": float("nan"), "picos": []}
    lf = np.log10(freqs[b])
    lp = np.log10(psd[b])

    def ajusta(mascara):
        if mascara.sum() < 4:
            return None
        return np.polyfit(lf[mascara], lp[mascara], 1)

    usar = np.ones(lf.size, dtype=bool)
    coef = ajusta(usar)
    picos = []
    for _ in range(int(n_picos)):
        if coef is None:
            break
        resto = lp - np.polyval(coef, lf)
        dp = float(np.std(resto[usar])) if usar.any() else 0.0
        if dp <= 0:
            break
        i = int(np.argmax(np.where(usar, resto, -np.inf)))
        if resto[i] < limiar_dp * dp:
            break
        # largura do pico: até onde o resíduo cai à metade da altura
        alt = float(resto[i])
        j = i
        while j > 0 and resto[j] > alt / 2.0:
            j -= 1
        k = i
        while k < resto.size - 1 and resto[k] > alt / 2.0:
            k += 1
        largura = float(10 ** lf[k] - 10 ** lf[j])
        # Ritmo do EEG é estreito. Sem teto de largura e piso de altura, uma
        # ondulação larga do próprio ruído entra na lista como se fosse pico.
        if alt >= altura_min and largura <= largura_max:
            picos.append((float(10 ** lf[i]), alt, largura))
        usar[j:k + 1] = False
        coef = ajusta(usar)
    if coef is None:
        return {"expoente": float("nan"), "deslocamento": float("nan"),
                "r2": float("nan"), "picos": picos}
    prev = np.polyval(coef, lf)
    total = float(np.sum((lp - lp.mean()) ** 2))
    r2 = 1.0 - float(np.sum((lp - prev) ** 2)) / total if total > 0 else \
        float("nan")
    # o artigo escreve L = b - X.log(f): expoente é o negativo da inclinação
    return {"expoente": float(-coef[0]), "deslocamento": float(coef[1]),
            "r2": float(r2), "picos": picos}


def eeg_potencia_periodica(psd, freqs, banda, faixa=(1.0, 45.0)):
    """Potência da banda ACIMA do fundo aperiódico, e não a potência bruta."""
    ap = eeg_aperiodico(psd, freqs, faixa)
    if not np.isfinite(ap["expoente"]):
        return float("nan")
    psd = np.asarray(psd, float)
    freqs = np.asarray(freqs, float)
    b = (freqs >= banda[0]) & (freqs <= banda[1]) & (freqs > 0) & (psd > 0)
    if not b.any():
        return float("nan")
    fundo = 10 ** (ap["deslocamento"] - ap["expoente"] * np.log10(freqs[b]))
    return float(np.sum(np.maximum(psd[b] - fundo, 0.0)))


# ==========================================================================
# 2) Parâmetros de Hjorth  [Hjorth 1970]
# ==========================================================================
def eeg_hjorth(x):
    """Atividade, mobilidade e complexidade — descritores baratos no tempo.

    Continuam em uso 55 anos depois porque não precisam de FFT e resumem
    potência, frequência dominante e largura de banda em três números.
    """
    x = np.nan_to_num(np.asarray(x, float))
    if x.size < 3:
        return {"atividade": float("nan"), "mobilidade": float("nan"),
                "complexidade": float("nan")}
    d1 = np.diff(x)
    d2 = np.diff(d1)
    v0 = float(np.var(x))
    v1 = float(np.var(d1))
    v2 = float(np.var(d2))
    mob = np.sqrt(v1 / v0) if v0 > 0 else float("nan")
    mob_d = np.sqrt(v2 / v1) if v1 > 0 else float("nan")
    comp = mob_d / mob if (mob and np.isfinite(mob) and mob > 0) else float("nan")
    return {"atividade": v0, "mobilidade": float(mob),
            "complexidade": float(comp)}


# ==========================================================================
# 3) Complexidade  [Bandt & Pompe 2002; Lempel & Ziv 1976]
# ==========================================================================
def eeg_entropia_permutacao(x, ordem=3, atraso=1, normalizada=True):
    """Entropia de permutação: conta padrões ordinais, não amplitudes.

    Imune a transformação monotônica do sinal, o que a torna robusta a ganho
    e a deriva lenta — duas coisas que sobram em EEG.
    """
    x = np.nan_to_num(np.asarray(x, float))
    n = x.size - (ordem - 1) * atraso
    if n < 2 or ordem < 2:
        return float("nan")
    janelas = np.empty((n, ordem))
    for i in range(ordem):
        janelas[:, i] = x[i * atraso:i * atraso + n]
    padroes = np.argsort(janelas, axis=1, kind="stable")
    # cada permutação vira uma chave inteira
    pesos = (ordem ** np.arange(ordem))
    chaves = padroes @ pesos
    _, contagem = np.unique(chaves, return_counts=True)
    p = contagem / float(contagem.sum())
    h = -float(np.sum(p * np.log(p)))
    if not normalizada:
        return h
    # math.factorial e não np.math: o atalho np.math saiu no NumPy 2
    max_h = np.log(float(math.factorial(ordem)))
    return h / max_h if max_h > 0 else float("nan")


def eeg_lempel_ziv(x, normalizada=True):
    """Complexidade de Lempel-Ziv sobre a binarização pela mediana.

    Usada como índice de complexidade cortical em anestesia e consciência.
    Zero é sinal totalmente previsível; perto de 1 é aleatório.
    """
    x = np.nan_to_num(np.asarray(x, float))
    if x.size < 8:
        return float("nan")
    s = (x > np.median(x)).astype(np.uint8)
    n = s.size
    i, k, l = 0, 1, 1
    c, k_max = 1, 1
    while True:
        if s[i + k - 1] == s[l + k - 1]:
            k += 1
            if l + k > n:
                c += 1
                break
        else:
            if k > k_max:
                k_max = k
            i += 1
            if i == l:
                c += 1
                l += k_max
                if l + 1 > n:
                    break
                i, k, k_max = 0, 1, 1
            else:
                k = 1
    if not normalizada:
        return float(c)
    base = n / np.log2(n) if n > 1 else 1.0
    return float(c) / base


# ==========================================================================
# 4) Correlações de longo alcance  [Peng et al. 1994]
# ==========================================================================
def eeg_dfa(x, escalas=None, ordem=1):
    """Expoente de DFA: 0,5 é ruído branco, 1,0 é 1/f, 1,5 é passeio aleatório.

    Em EEG, o DFA da envoltória de alfa mede a persistência das oscilações ao
    longo de dezenas de segundos [Linkenkaer-Hansen et al. 2001].
    """
    x = np.nan_to_num(np.asarray(x, float))
    n = x.size
    if n < 64:
        return float("nan")
    y = np.cumsum(x - x.mean())
    if escalas is None:
        escalas = np.unique(np.logspace(np.log10(8), np.log10(n // 4),
                                        18).astype(int))
    f = []
    usadas = []
    for s in escalas:
        s = int(s)
        if s < 4 or s > n // 2:
            continue
        m = n // s
        trechos = y[:m * s].reshape(m, s)
        t = np.arange(s)
        # remove a tendência polinomial de cada trecho
        coef = np.polyfit(t, trechos.T, ordem)
        tend = np.polyval(coef, t[:, None]).T if ordem > 0 else \
            np.repeat(trechos.mean(axis=1)[:, None], s, axis=1)
        f.append(np.sqrt(np.mean((trechos - tend) ** 2)))
        usadas.append(s)
    if len(f) < 3:
        return float("nan")
    return float(np.polyfit(np.log10(usadas), np.log10(f), 1)[0])


# ==========================================================================
# 5) Acoplamento fase-amplitude  [Tort et al. 2010]
# ==========================================================================
def eeg_pac_tort(x, fs, banda_fase=(4.0, 8.0), banda_amp=(30.0, 80.0),
                 n_bins=18):
    """Índice de modulação de Tort: quanto a fase lenta organiza a amplitude
    rápida.

    Mede se a amplitude da banda rápida se concentra em fases preferenciais da
    banda lenta. É o mecanismo proposto para a coordenação entre ritmos — teta
    organizando gama no hipocampo é o caso clássico.

    O índice é a divergência de Kullback-Leibler entre a distribuição de
    amplitude por fase e a distribuição uniforme, normalizada por log(n_bins).
    """
    x = np.nan_to_num(np.asarray(x, float))
    ny = fs / 2.0
    if x.size < int(2 * fs) or banda_amp[1] >= ny:
        return float("nan")
    sos_f = scipy_signal.butter(4, [banda_fase[0] / ny, banda_fase[1] / ny],
                      btype="band", output="sos")
    sos_a = scipy_signal.butter(4, [banda_amp[0] / ny, min(banda_amp[1], ny * 0.95) / ny],
                      btype="band", output="sos")
    fase = np.angle(scipy_signal.hilbert(scipy_signal.sosfiltfilt(sos_f, x)))
    amp = np.abs(scipy_signal.hilbert(scipy_signal.sosfiltfilt(sos_a, x)))
    bordas = np.linspace(-np.pi, np.pi, int(n_bins) + 1)
    idx = np.clip(np.digitize(fase, bordas) - 1, 0, int(n_bins) - 1)
    media = np.array([amp[idx == i].mean() if np.any(idx == i) else 0.0
                      for i in range(int(n_bins))])
    total = media.sum()
    if total <= 0:
        return float("nan")
    p = media / total
    p = np.where(p > 0, p, 1e-12)
    h = -float(np.sum(p * np.log(p)))
    return float((np.log(n_bins) - h) / np.log(n_bins))


# ==========================================================================
# 6) Assimetria e borda espectral
# ==========================================================================
def eeg_assimetria_alfa(psd_esq, psd_dir, freqs, banda=(8.0, 13.0)):
    """Assimetria alfa frontal: ln(direita) − ln(esquerda)  [Davidson 2004].

    Como o alfa é INVERSO à atividade cortical, valor positivo indica maior
    atividade à esquerda. Trocar o sinal por engano inverte a interpretação
    inteira, e é o erro mais comum nesta métrica.
    """
    freqs = np.asarray(freqs, float)
    b = (freqs >= banda[0]) & (freqs <= banda[1])
    if not b.any():
        return float("nan")
    pe = float(np.sum(np.asarray(psd_esq, float)[b]))
    pd = float(np.sum(np.asarray(psd_dir, float)[b]))
    if pe <= 0 or pd <= 0:
        return float("nan")
    return float(np.log(pd) - np.log(pe))


def eeg_sef(psd, freqs, fracao=0.95, faixa=(0.5, 45.0)):
    """Frequência de borda espectral: abaixo dela está `fracao` da potência.

    A SEF95 é usada como índice de profundidade anestésica e de sonolência:
    cai quando o espectro se desloca para as bandas lentas.
    """
    psd = np.asarray(psd, float)
    freqs = np.asarray(freqs, float)
    b = (freqs >= faixa[0]) & (freqs <= faixa[1])
    if b.sum() < 3:
        return float("nan")
    f, p = freqs[b], np.maximum(psd[b], 0.0)
    acum = np.cumsum(p)
    if acum[-1] <= 0:
        return float("nan")
    alvo = fracao * acum[-1]
    return float(f[int(np.searchsorted(acum, alvo))])


# ==========================================================================
# ECG
# ==========================================================================
def ecg_pan_tompkins(x, fs, refratario_s=0.20):
    """Detecção de QRS de Pan-Tompkins. Devolve os índices dos picos R.

    A cadeia do artigo, na ordem: passa-faixa 5-15 Hz para isolar o QRS,
    derivada para realçar a inclinação íngreme da onda R, quadrado para
    tornar tudo positivo e amplificar, integração por janela móvel da largura
    de um QRS, e limiar adaptativo.

    O período refratário de 200 ms é fisiológico: não existe segundo QRS
    dentro dele, e sem ele a onda T alta de algumas derivações é contada
    como batimento.
    """
    x = np.nan_to_num(np.asarray(x, float))
    if x.size < int(fs):
        return np.array([], dtype=int)
    ny = fs / 2.0
    sos = scipy_signal.butter(3, [max(5.0, 0.5) / ny, min(15.0, ny * 0.95) / ny],
                    btype="band", output="sos")
    filtrado = scipy_signal.sosfiltfilt(sos, x)
    derivada = np.diff(filtrado, prepend=filtrado[0])
    quadrado = derivada ** 2
    jan = max(1, int(0.150 * fs))            # largura típica do QRS
    integrado = np.convolve(quadrado, np.ones(jan) / jan, mode="same")

    limiar = 0.35 * float(np.mean(integrado) + np.std(integrado))
    minimo = int(refratario_s * fs)
    picos, _ = scipy_signal.find_peaks(integrado, height=limiar, distance=minimo)
    # o pico da integral fica DEPOIS da onda R; volta ao máximo local do sinal
    meia = max(1, int(0.10 * fs))
    r = []
    for p in picos:
        a, b = max(0, p - meia), min(x.size, p + meia)
        if b > a:
            r.append(a + int(np.argmax(np.abs(x[a:b] - np.median(x[a:b])))))
    return np.unique(np.asarray(r, dtype=int))


def ecg_rr(picos, fs):
    """Intervalos RR em milissegundos a partir dos índices dos picos."""
    picos = np.asarray(picos, dtype=float)
    if picos.size < 2:
        return np.array([])
    return np.diff(picos) / float(fs) * 1000.0


def ecg_hrv_tempo(rr_ms):
    """Índices de VFC no domínio do tempo — padrão da Task Force de 1996.

    SDNN mede a variabilidade total; RMSSD e pNN50 medem a variação
    batimento a batimento, que é sobretudo parassimpática.
    """
    rr = np.asarray(rr_ms, float)
    rr = rr[np.isfinite(rr)]
    if rr.size < 2:
        return {"sdnn": float("nan"), "rmssd": float("nan"),
                "pnn50": float("nan"), "mediaRR": float("nan"),
                "fc_media": float("nan")}
    d = np.diff(rr)
    return {"sdnn": float(np.std(rr, ddof=1)),
            "rmssd": float(np.sqrt(np.mean(d ** 2))),
            "pnn50": float(100.0 * np.count_nonzero(np.abs(d) > 50.0) / d.size),
            "mediaRR": float(np.mean(rr)),
            "fc_media": float(60000.0 / np.mean(rr))}


def ecg_poincare(rr_ms):
    """SD1 e SD2 do gráfico de Poincaré [Brennan et al. 2001].

    SD1 é a dispersão perpendicular à identidade; SD2, ao longo dela. A razão
    SD1/SD2 resume o equilíbrio entre variação rápida e lenta.

    SD1² = ½·Var(ΔRR), que é a definição de Brennan. Isso coincide com
    RMSSD/raiz(2) apenas quando a média das diferenças é zero — havendo
    tendência na série, os dois divergem, e é a definição de Brennan que vale.
    """
    rr = np.asarray(rr_ms, float)
    rr = rr[np.isfinite(rr)]
    if rr.size < 3:
        return {"sd1": float("nan"), "sd2": float("nan"),
                "razao": float("nan")}
    d = np.diff(rr)
    sd1 = float(np.std(d, ddof=1) / np.sqrt(2.0))
    var_rr = float(np.var(rr, ddof=1))
    sd2_2 = 2.0 * var_rr - sd1 ** 2
    sd2 = float(np.sqrt(sd2_2)) if sd2_2 > 0 else float("nan")
    return {"sd1": sd1, "sd2": sd2,
            "razao": sd1 / sd2 if sd2 and np.isfinite(sd2) and sd2 > 0
            else float("nan")}


def ecg_qtc(qt_ms, rr_ms, formula="bazett"):
    """Intervalo QT corrigido pela frequência cardíaca.

    Bazett (raiz cúbica em Fridericia) sobrecorrige em taquicardia e
    subcorrige em bradicardia; Fridericia é mais estável fora da faixa de
    60 a 100 bpm. O ROA oferece as duas porque a literatura clínica usa as
    duas, e comparar valores obtidos por fórmulas diferentes é erro comum.
    """
    qt = float(qt_ms)
    rr_s = float(rr_ms) / 1000.0
    if rr_s <= 0:
        return float("nan")
    if str(formula).lower().startswith("frid"):
        return qt / (rr_s ** (1.0 / 3.0))
    return qt / np.sqrt(rr_s)


def ecg_edr(x, fs, picos):
    """Respiração derivada do ECG pela modulação da amplitude de R.

    O tórax se move e muda a projeção do vetor cardíaco sobre o eletrodo, o
    que modula a altura da onda R no ritmo da respiração. Devolve
    (tempo, curva, frequência respiratória em Hz).
    """
    x = np.nan_to_num(np.asarray(x, float))
    picos = np.asarray(picos, dtype=int)
    if picos.size < 8:
        return np.array([]), np.array([]), float("nan")
    amp = x[picos]
    t = picos / float(fs)
    # reamostra para grade uniforme antes de estimar a frequência
    grade = np.arange(t[0], t[-1], 1.0 / 4.0)         # 4 Hz basta p/ respiração
    if grade.size < 8:
        return t, amp, float("nan")
    curva = np.interp(grade, t, amp)
    curva = curva - np.mean(curva)
    f, p = scipy_signal.welch(curva, fs=4.0, nperseg=min(len(curva), 64))
    b = (f >= 0.1) & (f <= 0.5)                        # 6 a 30 respirações/min
    fr = float(f[b][np.argmax(p[b])]) if b.any() and p[b].size else float("nan")
    return grade, curva, fr


def ecg_rsa(rr_ms, picos, fs):
    """Arritmia sinusal respiratória: amplitude da modulação do RR pela
    respiração.

    Medida como a potência do RR na banda de alta frequência (0,15 a 0,4 Hz),
    que é a assinatura respiratória no tacograma.
    """
    rr = np.asarray(rr_ms, float)
    picos = np.asarray(picos, dtype=float)
    if rr.size < 16 or picos.size < rr.size + 1:
        return float("nan")
    t = picos[1:] / float(fs)
    grade = np.arange(t[0], t[-1], 0.25)
    if grade.size < 16:
        return float("nan")
    tac = np.interp(grade, t, rr)
    tac = tac - np.mean(tac)
    f, p = scipy_signal.welch(tac, fs=4.0, nperseg=min(len(tac), 128))
    b = (f >= 0.15) & (f <= 0.40)
    if not b.any():
        return float("nan")
    return float(np.trapezoid(p[b], f[b]) if hasattr(np, "trapezoid")
                 else np.trapz(p[b], f[b]))


# ==========================================================================
# EoG
# ==========================================================================
def eog_sacadas(x, fs, limiar_dp=6.0, dur_min_s=0.02):
    """Sacadas por limiar de velocidade [Engbert & Kliegl 2003].

    O limiar é múltiplo da MEDIANA DO DESVIO ABSOLUTO da velocidade, e não do
    desvio padrão: as próprias sacadas inflam o desvio padrão e o limiar
    subiria junto, escondendo o que se quer achar.

    Devolve [(i_inicio, i_fim, amplitude, velocidade_pico), ...].
    """
    x = np.nan_to_num(np.asarray(x, float))
    if x.size < int(0.2 * fs):
        return []
    v = np.gradient(x) * fs
    mad = float(np.median(np.abs(v - np.median(v))))
    escala = 1.4826 * mad                     # MAD -> desvio padrão robusto
    if escala <= 0:
        return []
    limiar = limiar_dp * escala
    acima = np.abs(v) > limiar
    if not acima.any():
        return []
    bordas = np.diff(acima.astype(int))
    inicios = list(np.flatnonzero(bordas == 1) + 1)
    fins = list(np.flatnonzero(bordas == -1) + 1)
    if acima[0]:
        inicios.insert(0, 0)
    if acima[-1]:
        fins.append(acima.size)
    n_min = max(2, int(dur_min_s * fs))
    saida = []
    for a, b in zip(inicios, fins):
        if b - a < n_min:
            continue
        saida.append((int(a), int(b), float(x[b - 1] - x[a]),
                      float(np.max(np.abs(v[a:b])))))
    return saida


def eog_sequencia_principal(sacadas):
    """Sequência principal: velocidade de pico contra amplitude [Bahill 1975].

    A relação é uma lei de potência bem conservada em pessoas saudáveis;
    desvios dela aparecem em doença neurológica e em fadiga. Devolve o
    expoente, o coeficiente e o R² do ajuste em log-log.
    """
    amp = np.array([abs(s[2]) for s in sacadas], float)
    vel = np.array([abs(s[3]) for s in sacadas], float)
    ok = (amp > 0) & (vel > 0) & np.isfinite(amp) & np.isfinite(vel)
    if ok.sum() < 4:
        return {"expoente": float("nan"), "coef": float("nan"),
                "r2": float("nan"), "n": int(ok.sum())}
    la, lv = np.log10(amp[ok]), np.log10(vel[ok])
    coef = np.polyfit(la, lv, 1)
    resto = lv - np.polyval(coef, la)
    total = float(np.sum((lv - lv.mean()) ** 2))
    r2 = 1.0 - float(np.sum(resto ** 2)) / total if total > 0 else float("nan")
    return {"expoente": float(coef[0]), "coef": float(10 ** coef[1]),
            "r2": float(r2), "n": int(ok.sum())}


def eog_linha_base(x, fs, janela_s=2.2):
    """Linha de base LOCAL do EoG: mediana de meia janela antes e de meia
    janela depois de cada ponto; vale a que estiver mais perto do nível
    local (mediana curta, de ~36% da janela, em volta do ponto).

    Cada meia janela ignora o que ocupa menos da metade dela (a piscada) e a
    escolha de lado segue o degrau do olhar sem atraso. Uma mediana centrada
    só atrasava o degrau quando havia piscada ao lado, e o resíduo mostrava
    um pulso que não era piscada; escolher o lado pelo próprio ponto errava
    dentro da piscada logo depois de um degrau para baixo (o pico fica perto
    do nível antigo). Sai de medianas de blocos de 20 ms, para custar pouco
    numa sessão longa e a cada quadro da aba Olhos.
    """
    x = np.nan_to_num(np.asarray(x, float))
    n = x.size
    passo = max(1, int(round(0.02 * fs)))
    nb = n // passo
    if nb < 3:
        return np.full(n, float(np.median(x)) if n else 0.0)
    blocos = np.median(x[:nb * passo].reshape(nb, passo), axis=1)
    h = max(1, int(round(janela_s * fs / passo / 2.0)))   # meia janela
    from scipy.ndimage import median_filter
    cen = median_filter(blocos, size=h + 1, mode="nearest")
    kc = max(3, int(round(0.36 * janela_s * fs / passo)))
    kc += 1 - (kc % 2)
    curta = median_filter(blocos, size=kc, mode="nearest")
    # a mediana centrada em i - h/2 cobre [i - h, i]; em i + h/2, [i, i + h]
    i = np.arange(nb)
    esq = cen[np.clip(i - h // 2, 0, nb - 1)]
    dir_ = cen[np.clip(i + h // 2, 0, nb - 1)]
    lb = np.where(np.abs(curta - esq) <= np.abs(curta - dir_), esq, dir_)
    centros = i * passo + (passo - 1) / 2.0
    return np.interp(np.arange(n), centros, lb)


def eog_piscadas(x, fs, limiar_dp=3.0, dur_min_s=0.05, dur_max_s=0.5):
    """Piscadas: deflexões monofásicas com duração entre 50 e 500 ms.

    A janela de duração é o que separa piscada de sacada vertical: a sacada
    leva o olhar a outra posição e fica lá, a piscada volta à linha de base.
    """
    x = np.nan_to_num(np.asarray(x, float))
    if x.size < int(fs):
        return []
    # Linha de base LOCAL (cada meia janela com mais que o dobro da piscada
    # mais longa). Com a mediana da gravação inteira, os degraus do olhar
    # vertical entravam na escala: sem filtro o limiar subia a ~240 uV, a
    # altura da própria piscada, e o PDF contava 2 de 10.
    base = eog_linha_base(x, fs, max(2.2, 4.4 * dur_max_s))
    r = x - base
    mad = float(np.median(np.abs(r - np.median(r))))
    escala = 1.4826 * mad
    if escala <= 0:
        return []
    acima = np.abs(r) > limiar_dp * escala
    bordas = np.diff(acima.astype(int))
    inicios = list(np.flatnonzero(bordas == 1) + 1)
    fins = list(np.flatnonzero(bordas == -1) + 1)
    if acima[0]:
        inicios.insert(0, 0)
    if acima[-1]:
        fins.append(acima.size)
    n_min, n_max = int(dur_min_s * fs), int(dur_max_s * fs)
    saida = []
    for a, b in zip(inicios, fins):
        if not (n_min <= b - a <= n_max):
            continue
        # Volta à linha de base: é isto que separa piscada de sacada vertical.
        # A conferência é pela MEDIANA de uma janela curta depois do fim, e com
        # a mesma folga do limiar de detecção. Comparar UMA amostra contra 1,5x
        # a escala do próprio ruído reprovava metade das piscadas por acaso —
        # o detector achava 9 de 20.
        j = min(b + int(0.05 * fs), x.size)
        depois = r[b:j] if j > b else r[max(0, b - 1):b]
        seg = r[a:b]
        amp = float(np.max(np.abs(seg)))
        sinal = 1.0 if seg[int(np.argmax(np.abs(seg)))] > 0 else -1.0
        resto = float(np.median(depois)) * sinal if depois.size else 0.0
        # ...e volta PERTO da base também em relação à própria altura (até
        # 25% dela): com o filtro do exame o passa-altas faz de cada degrau
        # do olhar uma cauda que passa do limiar e volta devagar (em 16 min
        # de simulação, 112 piscadas a mais; com este critério, 18). A cauda
        # fica do MESMO lado do evento; do lado oposto é o vale que o
        # passa-altas deixa depois da piscada, que não a reprova até metade
        # da altura (sem isso, a 1a de cada piscada dupla filtrada caía:
        # 148 de 240 em pares a 0,4-0,7 s; com isso, 240).
        if resto > min(limiar_dp * escala, 0.25 * amp) or \
                -resto > 0.5 * amp:
            continue
        # Nível do sinal BRUTO antes e depois do evento: a piscada volta ao
        # nível de onde saiu, a sacada vertical não. Perto de um degrau com
        # piscada ao lado, a mediana móvel atrasa o degrau e o resíduo mostra
        # um pulso que não é piscada (2 falsos em 30 s de simulação).
        w0 = max(1, int(0.05 * fs))
        antes_x, depois_x = x[max(0, a - w0):a], x[b:min(x.size, b + w0)]
        if antes_x.size and depois_x.size and abs(
                float(np.median(antes_x)) - float(np.median(depois_x))) > 0.5 * amp:
            continue
        # A piscada sobe a partir do nível de ANTES dela. Num olhar que desce
        # e volta em 0,6-1 s (ou em 2 s) a base local acompanha parte do
        # patamar e o resíduo mostra só o pedaço final, que começa já no alto:
        # 19 de 19 desses olhares viravam piscada.
        if antes_x.size and float(np.max(
                sinal * (x[a:b] - float(np.median(antes_x))))) < 0.5 * amp:
            continue
        saida.append((int(a), int(b), float((b - a) / fs), amp, sinal))
    # Com o filtro do exame (passa-altas) cada piscada vira um PAR: o pico e,
    # logo depois, um vale da mesma altura. O evento de polaridade oposta que
    # começa até 150 ms depois do fim do anterior é o rebote do filtro, não
    # outra piscada (o PDF contava 27 onde a tela contava 11).
    filtrada = []
    for q in saida:
        if (filtrada and q[4] != filtrada[-1][4]
                and (q[0] - filtrada[-1][1]) <= int(0.15 * fs)):
            continue
        filtrada.append(q)
    saida = filtrada
    # As piscadas de um canal têm todas a mesma polaridade (a do eletrodo).
    # Um evento do lado oposto e menor que metade da altura típica é o vale
    # do passa-altas entre duas piscadas próximas, não outra piscada.
    if len(saida) >= 3:
        pos = sum(q[3] for q in saida if q[4] > 0)
        neg = sum(q[3] for q in saida if q[4] < 0)
        dom = 1.0 if pos >= neg else -1.0
        ref = float(np.median([q[3] for q in saida if q[4] == dom]))
        saida = [q for q in saida if q[4] == dom or q[3] >= 0.5 * ref]
    return [q[:4] for q in saida]


def eog_piscadas_tela(x, fs, limiar, dedup_s=0.2, residuo=False):
    """Piscadas pelo critério da aba Olhos (o mesmo do PDF quando a gravação
    guarda a sensibilidade da tela): deflexão POSITIVA do resíduo sobre a
    linha de base local acima de 1,5 x `limiar` por ao menos 50 ms, um pico
    por trecho, picos a menos de `dedup_s` do anterior descartados. Devolve
    (início, fim, duração_s, amplitude, índice_do_pico). `residuo=True`
    quando `x` já é o resíduo (a tela calcula o dela)."""
    x = np.nan_to_num(np.asarray(x, float))
    if x.size < 3:
        return []
    r = x if residuo else x - eog_linha_base(x, fs)
    acima = r > 1.5 * float(limiar)
    bordas = np.diff(acima.astype(int))
    inicios = list(np.flatnonzero(bordas == 1) + 1)
    fins = list(np.flatnonzero(bordas == -1) + 1)
    if acima[0]:
        inicios.insert(0, 0)
    if acima[-1]:
        fins.append(acima.size)
    n_min = max(2, int(0.05 * fs))
    n_dedup = int(dedup_s * fs)
    saida, ultimo = [], None
    for a, b in zip(inicios, fins):
        if b - a < n_min:
            continue
        pico = a + int(np.argmax(r[a:b]))
        if ultimo is not None and n_dedup > 0 and pico - ultimo < n_dedup:
            continue
        ultimo = pico
        saida.append((int(a), int(b), float((b - a) / fs), float(r[pico]), int(pico)))
    return saida


def eog_perclos(x, fs, janela_s=60.0, limiar_dur_s=0.15):
    """PERCLOS: fração do tempo com os olhos fechados [Wierwille 1994].

    Padrão-ouro de sonolência. Conta só as piscadas PROLONGADAS, acima de
    150 ms: piscada normal é reflexo, piscada longa é o olho que não quer
    abrir.

    Num canal só, um fechamento de 0,5-2 s e o olhar que desce e volta têm o
    mesmo desenho. Por isso o fechamento longo só entra com a polaridade e a
    altura (0,6-1,6x) das piscadas normais do próprio sujeito; sem ao menos
    3 piscadas para servir de régua, sai 0. Contar todo evento de até 2 s
    dava 17-24% de "olho fechado" numa gravação sem nenhuma piscada.
    """
    x = np.nan_to_num(np.asarray(x, float))
    dur_total = x.size / float(fs)
    if dur_total <= 0:
        return float("nan")
    curtas = eog_piscadas(x, fs)
    if len(curtas) < 3:
        return 0.0
    w0 = max(1, int(0.05 * fs))

    def plato(a, b):
        # altura mediana da metade central do evento, a partir do nível de
        # antes dele (o pico de uma piscada por cima do olhar não conta)
        nivel = float(np.median(x[max(0, a - w0):a])) if a > 0 else float(x[0])
        d = x[a:b] - nivel
        m = b - a
        return float(np.median(d[m // 4:m - m // 4] if m >= 4 else d))
    alturas = [plato(a, b) for a, b, _d, _am in curtas]
    polar = 1.0 if np.median(alturas) >= 0 else -1.0
    ref = float(np.median(np.abs(alturas)))
    # máscara de tempo fechado: um fechamento longo que o detector curto
    # também pegou em parte não é contado duas vezes
    fechado = np.zeros(x.size, bool)
    for a, b, dur, _am in curtas:
        if dur >= limiar_dur_s:
            fechado[a:b] = True
    for a, b, dur, _am in eog_piscadas(x, fs, dur_max_s=2.0):
        if dur > 0.5 and 0.6 * ref <= plato(a, b) * polar <= 1.6 * ref:
            fechado[a:b] = True
    return float(100.0 * fechado.mean())


def eog_taxa_piscadas(x, fs):
    """Piscadas por minuto. Faixa de vigília normal: 8 a 21 por minuto."""
    piscadas = eog_piscadas(x, fs)
    minutos = x.size / float(fs) / 60.0
    if minutos <= 0:
        return float("nan")
    return float(len(piscadas) / minutos)


def eog_estabilidade_fixacao(h, v, p=0.68):
    """Área elíptica do contorno bivariado (BCEA) da fixação.

    Quanto menor, mais estável a fixação. É a medida usada em baixa visão e
    em nistagmo para quantificar o quanto o olhar passeia ao tentar fixar.
    """
    h = np.nan_to_num(np.asarray(h, float))
    v = np.nan_to_num(np.asarray(v, float))
    if h.size < 8 or v.size != h.size:
        return float("nan")
    sh, sv = float(np.std(h, ddof=1)), float(np.std(v, ddof=1))
    if sh <= 0 or sv <= 0:
        return float("nan")
    rho = float(np.corrcoef(h, v)[0, 1])
    k = -np.log(1.0 - p)
    return float(2.0 * k * np.pi * sh * sv * np.sqrt(max(0.0, 1.0 - rho ** 2)))

