        super().__init__(parent)
        self._win = parent
        self._sessions = []   # [(nome, dict)]
        self.setWindowTitle(tr("Receitas de análise — Área Maker"))
        self.setMinimumSize(780, 600)
        v = QtWidgets.QVBoxLayout(self)
        # O cabeçalho antigo citava ERD% e potência relativa, que são de EEG.
