        self.b1_edit = QtWidgets.QLineEdit("2");   self.b1_edit.setMinimumWidth(72)
        bl.addWidget(self.b0_edit); bl.addWidget(QtWidgets.QLabel(tr("até")))
        bl.addWidget(self.b1_edit); bl.addWidget(QtWidgets.QLabel(tr("s (repouso)")))
        bl.addStretch(1)
        self.baseline_row = QtWidgets.QWidget(); self.baseline_row.setLayout(bl)
        form.addRow(tr("Baseline p/ ERD%:"), self.baseline_row)
        v.addLayout(form)
        sh = QtWidgets.QHBoxLayout()
        add_btn = QtWidgets.QPushButton(tr("Adicionar sessões…"))
        add_btn.clicked.connect(self._add_sessions)
        clr_btn = QtWidgets.QPushButton(tr("Limpar"))
        clr_btn.clicked.connect(self._clear_sessions)
        self.sess_lbl = QtWidgets.QLabel(tr("0 sessões"))
        sh.addWidget(add_btn); sh.addWidget(clr_btn); sh.addWidget(self.sess_lbl)
        sh.addStretch(1)
        v.addLayout(sh)
        self.result_lbl = QtWidgets.QLabel("")
        self.result_lbl.setStyleSheet(f"color:{COLORS.get('accent','#0f9d75')};"
                                      "font-weight:bold")
        v.addWidget(self.result_lbl)
        self.table = QtWidgets.QTableWidget(0, 1)
        self.table.setHorizontalHeaderLabels([tr("Canal")])
        self.table.setEditTriggers(
            QtWidgets.QAbstractItemView.EditTrigger.NoEditTriggers)
        v.addWidget(self.table, 1)
        ah = QtWidgets.QHBoxLayout()
        run_btn = QtWidgets.QPushButton(tr("▶ Rodar")); run_btn.clicked.connect(self._run)
        save_btn = QtWidgets.QPushButton(tr("Salvar receita…")); save_btn.clicked.connect(self._save_recipe)
        load_btn = QtWidgets.QPushButton(tr("Carregar receita…")); load_btn.clicked.connect(self._load_recipe)
        exp_btn = QtWidgets.QPushButton(tr("Exportar tabela…")); exp_btn.clicked.connect(self._export_csv)
        close_btn = QtWidgets.QPushButton(tr("Fechar")); close_btn.clicked.connect(self.accept)
        for b in (run_btn, save_btn, load_btn, exp_btn):
            ah.addWidget(b)
        ah.addStretch(1); ah.addWidget(close_btn)
        v.addLayout(ah)
        # ---- Exemplo estilo PT-51 (Riemanniano + protótipos, few-shot) ----
        pt51 = QtWidgets.QHBoxLayout()
        self.pt51_btn = QtWidgets.QPushButton(
            tr("Exemplo: Classificador estilo PT-51 (Riemanniano + protótipos, few-shot)…"))
        self.pt51_btn.setToolTip(
            tr("Reproduz, sem deep learning, o núcleo da sua Proposta Técnica 51:\n"
            "embedding Riemanniano (covariância → tangente log-Euclidiano) +\n"
            "classificação por PROTÓTIPOS (MDM) + curva FEW-SHOT. Requer sessões\n"
            "BCI (com trials MI). Cada arquivo é tratado como um sujeito (LOSO)."))
        self.pt51_btn.clicked.connect(self._am_pt51_demo)
        pt51.addWidget(self.pt51_btn); pt51.addStretch(1)
        v.addLayout(pt51)
        # ---- Exemplo: validação do ERD (focal x global) em lote ----
        vld = QtWidgets.QHBoxLayout()
        self.valid_btn = QtWidgets.QPushButton(
            tr("⚑ Exemplo: Validar ERD (focal × global) em TODAS as sessões carregadas…"))
        self.valid_btn.setToolTip(
            tr("TESTE DE HONESTIDADE em lote — a receita que todo estudo de MI deveria rodar\n"
            "antes de publicar mapas de ativação.\n\n"
            "Para cada sessão carregada: usa como referência o repouso IMEDIATAMENTE\n"
            "ANTES de cada tentativa (não um baseline distante, que mede só diferença\n"
            "de estado), acha a banda de mu DO SUJEITO, rejeita artefatos e contrasta\n"
            "C3/Cz/C4 contra eletrodos de CONTROLE (FP1/FP2/T3/T4).\n\n"
            "Responde: o ERD é FOCAL (motor) ou GLOBAL (atenção)? Requer sessões BCI\n"
            "com fase pre_rest."))
        self.valid_btn.clicked.connect(self._am_validate_demo)
        vld.addWidget(self.valid_btn); vld.addStretch(1)
